def _resolve_console_width() -> int | None:
    env_width = os.environ.get("PMS_CONSOLE_WIDTH")
    if env_width:
        try:
            return int(env_width)
        except ValueError:
            return None
    if os.environ.get("PYTEST_CURRENT_TEST"):
        return 160
    if sys.stdout.isatty():
        return None
    return 160


def _build_console() -> Console:
    width = _resolve_console_width()
    console_kwargs: dict[str, Any] = {}
    if width:
        console_kwargs["width"] = width
    if os.environ.get("PYTEST_CURRENT_TEST") or not sys.stdout.isatty():
        console_kwargs["force_terminal"] = False
        console_kwargs["color_system"] = None
        console_kwargs["no_color"] = True
    return Console(**console_kwargs)


console = _build_console()
