F = TypeVar("F", bound=Callable[..., Any])


def async_command[F: Callable[..., Any]](f: F) -> F:
    """Decorator to run async click commands."""

    @wraps(f)
    def wrapper(*args: Any, **kwargs: Any) -> Any:
        try:
            return asyncio.run(f(*args, **kwargs))
        except PMSException as exc:
            output_format = kwargs.get("output_format", "text")
            _emit_cli_exception(exc, output_format=output_format)

    return wrapper  # type: ignore[return-value]


def _csv_row(values: list[str]) -> str:
    buf = StringIO()
    writer = csv.writer(buf)
    writer.writerow(values)
    return buf.getvalue().strip("\r\n")


def _to_iso(value: datetime | str | None) -> str | None:
    if value is None:
        return None
    if isinstance(value, str):
        return value
    return value.isoformat()


def _sort_timestamp(value: datetime | str | None) -> float:
    if isinstance(value, datetime):
        return value.timestamp()
    if isinstance(value, str):
        normalized = value.strip()
        if normalized.endswith("Z"):
            normalized = normalized[:-1] + "+00:00"
        try:
            return datetime.fromisoformat(normalized).timestamp()
        except ValueError:
            return 0.0
    return 0.0


def _resolve_cli_actor(explicit_actor: str | None) -> str:
    if explicit_actor:
        return explicit_actor
    from pms.config import get_settings

    settings = get_settings()
    if settings.current_actor_id:
        actor_value = settings.current_actor_id.strip()
        if actor_value:
            return actor_value
    for env_name in ("PMS_ACTOR", "PMS_USER", "USER", "LOGNAME"):
        actor = os.environ.get(env_name)
        if actor:
            actor_value = actor.strip()
            if actor_value:
                return actor_value
    return "cli"


def _resolve_current_actor() -> str:
    """Resolve the current actor for actor-aware CLI surfaces."""
    actor = _resolve_cli_actor(None)
    if actor == "cli":
        raise click.ClickException(
            "No current actor configured. Set PMS_CURRENT_ACTOR_ID, run "
            "'pms config set --current-actor <actor>' or pass --actor explicitly."
        )
    return actor


def _configured_current_actor() -> str | None:
    """Return an explicitly configured current actor, if any."""
    from pms.config import get_settings

    settings = get_settings()
    if settings.current_actor_id:
        actor_value = settings.current_actor_id.strip()
        if actor_value:
            return actor_value
    return None


async def _resolve_assignee_map(
    tasks: list[Any],
    actor_service: Any,
) -> dict[str, Any]:
    return await _resolve_actor_reference_map(
        [
            actor_key
            for task_obj in tasks
            for actor_key in (
                getattr(task_obj, "assignee_id", None),
                getattr(task_obj, "assignee", None),
            )
        ],
        actor_service,
    )


async def _resolve_checkout_actor_map(
    tasks: list[Any],
    actor_service: Any,
) -> dict[str, Any]:
    return await _resolve_actor_reference_map(
        [getattr(task_obj, "checkout_actor_id", None) for task_obj in tasks],
        actor_service,
    )


async def _resolve_actor_reference_map(
    actor_keys: list[str | None],
    actor_service: Any,
) -> dict[str, Any]:
    actor_map: dict[str, Any] = {}
    for actor_key in actor_keys:
        if actor_key and actor_key not in actor_map:
            actor_map[actor_key] = await actor_service.get_actor(actor_key)
    return actor_map


async def _resolve_owner_map(
    entities: list[Any],
    actor_service: Any,
) -> dict[str, Any]:
    return await _resolve_actor_reference_map(
        [
            actor_key
            for entity in entities
            for actor_key in (
                getattr(entity, "owner_id", None),
                getattr(entity, "owner", None),
            )
        ],
        actor_service,
    )


def _task_assignee_actor(
    task_obj: Any,
    assignee_map: dict[str, Any],
) -> Any | None:
    assignee_id = getattr(task_obj, "assignee_id", None)
    if assignee_id and assignee_map.get(assignee_id) is not None:
        return assignee_map.get(assignee_id)
    assignee = getattr(task_obj, "assignee", None)
    if assignee:
        return assignee_map.get(assignee)
    return None


def _task_assignee_payload(
    task_obj: Any,
    assignee_map: dict[str, Any],
) -> dict[str, Any]:
    assignee_actor = _task_assignee_actor(task_obj, assignee_map)
    return {
        "ref": getattr(task_obj, "assignee", None),
        "id": getattr(task_obj, "assignee_id", None),
        "actor": assignee_actor.to_dict() if assignee_actor is not None else None,
        "links": _normalize_command_links(
            {
                "actor": (
                    f"actor show {assignee_actor.handle} --format json"
                    if assignee_actor is not None
                    else None
                ),
                "tasks": (
                    f"task list --actor {assignee_actor.handle} --format json"
                    if assignee_actor is not None
                    else None
                ),
            }
        ),
    }


def _task_assignee_actor_link(
    task_obj: Any,
    assignee_map: dict[str, Any],
) -> str | None:
    assignee_actor = _task_assignee_actor(task_obj, assignee_map)
    if assignee_actor is None:
        return None
    return f"actor show {assignee_actor.handle} --format json"


def _task_checkout_actor(
    task_obj: Any,
    checkout_actor_map: dict[str, Any],
) -> Any | None:
    checkout_actor_id = getattr(task_obj, "checkout_actor_id", None)
    if checkout_actor_id:
        return checkout_actor_map.get(checkout_actor_id)
    return None


def _task_checkout_payload(
    task_obj: Any,
    checkout_actor_map: dict[str, Any],
) -> dict[str, Any] | None:
    checkout_actor = _task_checkout_actor(task_obj, checkout_actor_map)
    agent_session_id = getattr(task_obj, "checkout_agent_session_id", None)
    checked_out_at = _to_iso(getattr(task_obj, "checked_out_at", None))
    lease_until = _to_iso(getattr(task_obj, "checkout_lease_until", None))
    version = getattr(task_obj, "checkout_version", None)
    expired = getattr(task_obj, "checkout_expired", False)
    if (
        agent_session_id is None
        and checkout_actor is None
        and checked_out_at is None
        and lease_until is None
        and version is None
        and expired is False
    ):
        return None
    return {
        "agent_session_id": agent_session_id,
        "actor": _actor_reference_payload(
            checkout_actor.handle if checkout_actor is not None else None,
            {checkout_actor.id: checkout_actor, checkout_actor.handle: checkout_actor}
            if checkout_actor is not None
            else {},
            actor_id=checkout_actor.id if checkout_actor is not None else None,
        ),
        "checked_out_at": checked_out_at,
        "lease_until": lease_until,
        "version": version,
        "expired": expired,
    }


def _task_checkout_actor_link(
    task_obj: Any,
    checkout_actor_map: dict[str, Any],
) -> str | None:
    checkout_actor = _task_checkout_actor(task_obj, checkout_actor_map)
    if checkout_actor is None:
        return None
    return f"actor show {checkout_actor.handle} --format json"


def _actor_reference_payload(
    actor_key: str | None,
    actor_map: dict[str, Any],
    *,
    actor_id: str | None = None,
) -> dict[str, Any]:
    actor_obj = None
    if actor_id:
        actor_obj = actor_map.get(actor_id)
    if actor_obj is None and actor_key:
        actor_obj = actor_map.get(actor_key)
    return {
        "ref": actor_key,
        "id": actor_id,
        "actor": actor_obj.to_dict() if actor_obj is not None else None,
        "links": _normalize_command_links(
            {
                "actor": (
                    f"actor show {actor_obj.handle} --format json"
                    if actor_obj is not None
                    else None
                ),
                "tasks": (
                    f"task list --actor {actor_obj.handle} --format json"
                    if actor_obj is not None
                    else None
                ),
            }
        ),
    }


def _actor_reference_link(
    actor_key: str | None,
    actor_map: dict[str, Any],
    *,
    actor_id: str | None = None,
) -> str | None:
    actor_obj = actor_map.get(actor_id) if actor_id else None
    if actor_obj is None and actor_key:
        actor_obj = actor_map.get(actor_key)
    if actor_obj is None:
        return None
    return f"actor show {actor_obj.handle} --format json"


def _actor_reference_list_payload(
    actor_keys: list[str] | tuple[str, ...],
    actor_map: dict[str, Any],
) -> list[dict[str, Any]]:
    payloads: list[dict[str, Any]] = []
    for actor_key in actor_keys:
        payloads.append(
            _actor_reference_payload(
                actor_key,
                actor_map,
                actor_id=actor_map[actor_key].id
                if actor_key in actor_map and actor_map[actor_key] is not None
                else None,
            )
        )
    return payloads


