def _resolved_owner_actor(entity: Any, actor_map: dict[str, Any]) -> Any | None:
    actor_id = getattr(entity, "owner_id", None)
    if actor_id and actor_map.get(actor_id) is not None:
        return actor_map.get(actor_id)
    actor_key = getattr(entity, "owner", None)
