def _actor_rollup_entry(
    actor_obj: Any,
    *,
    count: int,
    sample_task_ids: list[str] | None = None,
    sample_entity_ids: list[str] | None = None,
) -> dict[str, Any]:
    payload = actor_obj.to_dict()
    payload["count"] = count
    payload["sample_task_ids"] = sample_task_ids or []
    payload["sample_entity_ids"] = sample_entity_ids or []
    payload["links"] = _normalize_command_links(
        {
            "actor": f"actor show {actor_obj.handle} --format json",
            "tasks": f"task list --actor {actor_obj.handle} --format json",
        }
    )
    return payload


def _ownership_actor_rollup_payload(
    entities: list[Any],
    actor_map: dict[str, Any],
) -> dict[str, Any]:
    counts: dict[str, dict[str, Any]] = {}
    for entity in entities:
        actor_obj = _resolved_owner_actor(entity, actor_map)
        if actor_obj is None:
            continue
        bucket = counts.setdefault(
            actor_obj.id,
            {
                "actor": actor_obj,
                "count": 0,
                "entity_ids": [],
            },
        )
        bucket["count"] += 1
        entity_id = getattr(entity, "id", None)
        if entity_id:
            bucket["entity_ids"].append(entity_id)

    entries = [
        _actor_rollup_entry(
            bucket["actor"],
            count=bucket["count"],
            sample_entity_ids=bucket["entity_ids"][:5],
        )
        for bucket in sorted(
            counts.values(),
            key=lambda item: (-item["count"], item["actor"].handle),
        )
    ]
    return {
        "actor_count": len(entries),
        "entity_count": sum(int(item["count"]) for item in counts.values()),
        "actors": entries,
    }


def _task_actor_rollup_payload(
    tasks: list[Any],
    actor_resolver: Any,
    actor_map: dict[str, Any],
) -> dict[str, Any]:
    counts: dict[str, dict[str, Any]] = {}
    for task_obj in tasks:
        actor_obj = actor_resolver(task_obj, actor_map)
        if actor_obj is None:
            continue
        bucket = counts.setdefault(
            actor_obj.id,
            {
                "actor": actor_obj,
                "count": 0,
                "task_ids": [],
            },
        )
        bucket["count"] += 1
        if getattr(task_obj, "id", None):
            bucket["task_ids"].append(task_obj.id)

    entries = [
        _actor_rollup_entry(
            bucket["actor"],
            count=bucket["count"],
            sample_task_ids=bucket["task_ids"][:5],
        )
        for bucket in sorted(
            counts.values(),
            key=lambda item: (-item["count"], item["actor"].handle),
        )
    ]
    return {
        "actor_count": len(entries),
        "task_count": sum(int(item["count"]) for item in counts.values()),
        "actors": entries,
    }


def _actor_rollups_payload(
    *,
    owners: list[Any] | None = None,
    tasks: list[Any] | None = None,
    owner_map: dict[str, Any] | None = None,
    assignee_map: dict[str, Any] | None = None,
    checkout_actor_map: dict[str, Any] | None = None,
    population_basis: str,
) -> dict[str, Any]:
    owner_entities = owners or []
    task_entities = tasks or []
    return {
        "population_basis": population_basis,
        "ownership": _ownership_actor_rollup_payload(
            owner_entities,
            owner_map or {},
        ),
        "assignments": _task_actor_rollup_payload(
            task_entities,
            _task_assignee_actor,
            assignee_map or {},
        ),
        "checkouts": _task_actor_rollup_payload(
            task_entities,
            _task_checkout_actor,
            checkout_actor_map or {},
        ),
    }


