def _member_payloads(
    member_refs: list[str] | tuple[str, ...],
    actor_map: dict[str, Any],
    *,
    actor_ids: list[str] | tuple[str, ...] | None = None,
) -> list[dict[str, Any]]:
    payloads: list[dict[str, Any]] = []
    actor_ids_list = list(actor_ids or [])
    for idx, actor_key in enumerate(member_refs):
        payloads.append(
            _actor_reference_payload(
                actor_key,
                actor_map,
                actor_id=actor_ids_list[idx] if idx < len(actor_ids_list) else None,
            )
        )
    return payloads


def _public_entity_payload(entity: Any) -> dict[str, Any]:
    payload = entity.to_dict()
    payload.pop("owner_id", None)
    payload.pop("member_ids", None)
    return payload


def _public_task_payload(
    task_obj: Any,
    *,
    assignee_map: dict[str, Any] | None = None,
    checkout_actor_map: dict[str, Any] | None = None,
) -> dict[str, Any]:
    payload = task_obj.to_dict()
    payload.pop("assignee", None)
    payload.pop("assignee_id", None)
    payload.pop("checkout_agent_session_id", None)
    payload.pop("checkout_actor_id", None)
    if assignee_map is not None:
        payload["assignee"] = _task_assignee_payload(task_obj, assignee_map)
    if checkout_actor_map is not None:
        payload["checkout"] = _task_checkout_payload(task_obj, checkout_actor_map)
    return payload


def _focus_task_payload_with_assignee(
    focus_task: CommandFocusTarget | None,
    *,
    task_lookup: dict[str, Any],
    assignee_map: dict[str, Any],
    checkout_actor_map: dict[str, Any] | None = None,
) -> dict[str, Any] | None:
    if focus_task is None:
        return None
    payload: dict[str, Any] = focus_task.to_payload()
    task_obj = task_lookup.get(focus_task.task_id)
    if task_obj is None:
        return payload
    payload["assignee"] = _task_assignee_payload(task_obj, assignee_map)
    payload["checkout"] = _task_checkout_payload(
        task_obj,
        checkout_actor_map or {},
    )
    payload["links"] = _normalize_command_links(
        {
            "self": f"task show {task_obj.id}",
            "actor": _task_assignee_actor_link(task_obj, assignee_map),
            "checkout_actor": _task_checkout_actor_link(
                task_obj,
                checkout_actor_map or {},
            ),
        }
    )
    return payload


