def _help_epilog(*commands: str) -> str:
    lines = ["\b", "Examples:"]
    lines.extend(f"  {_cli_command(command)}" for command in commands)
    return "\n".join(lines)


LOCAL_RUNTIME_DEFAULT_PORT = LOCAL_SERVER_DEFAULT_PORT


def _emit_cli_error(detail: str, *, output_format: str) -> None:
    if output_format == "json":
        click.echo(json.dumps({"error": detail}))
        raise SystemExit(1)
    console.print(f"[red]{detail}[/red]")
    raise click.exceptions.Exit(1)


def _emit_cli_exception(exc: PMSException, *, output_format: str) -> None:
    payload: dict[str, Any] = {"error": exc.message, "error_type": type(exc).__name__}
    payload.update(exc.details)
    if output_format == "json":
        click.echo(json.dumps(payload, default=str))
        raise SystemExit(1)

    detail = exc.message
    suggestions = exc.details.get("suggestions")
    if isinstance(suggestions, list) and suggestions:
        detail += "\nSuggestions:\n" + "\n".join(f"- {item}" for item in suggestions)
    console.print(f"[red]{detail}[/red]")
    raise click.exceptions.Exit(1)


def _emit_missing_optional_dependency(
    feature_name: str, package: str, install_hint: str
) -> None:
    _emit_cli_error(
        f"{feature_name} requires {package}. Install with: {install_hint}",
        output_format="text",
    )


def _ensure_local_only_runtime_write(
    action_name: str,
    *,
    output_format: str,
) -> RuntimeWriteDecision | None:
    from pms.config import get_settings

    settings = get_settings()
    payload = _runtime_server_payload()
    if settings.write_mode == "require_server":
        _emit_cli_error(
            (
                f"`{action_name}` does not support server-backed writes yet, and "
                "PMS_WRITE_MODE=require_server blocks direct-file fallback."
            ),
            output_format=output_format,
        )
    return RuntimeWriteDecision(
        allowed=True,
        use_server=False,
        payload=payload,
        block_reason=None,
    )


def _normalized_id(value: str) -> str:
    return value.replace("-", "").lower()


def _runtime_api_key_material() -> tuple[str | None, str | None]:
    from pms.config import get_settings

    env_api_key = os.environ.get("PMS_API_KEY", "").strip()
    if env_api_key:
        return env_api_key, "env"

    settings = get_settings()
    if settings.api_key_path is None:
        return None, None

    key_file = settings.api_key_path.expanduser()
    if not key_file.exists():
        return None, None

    file_api_key = key_file.read_text(encoding="utf-8").strip()
    if not file_api_key:
        return None, None
    return file_api_key, "file"


def _runtime_api_key() -> str | None:
    api_key, _source = _runtime_api_key_material()
    return api_key


def _id_prefix_matches(entity_id: str, ref: str) -> bool:
    normalized_ref = _normalized_id(ref)
    if len(normalized_ref) < 6:
        return False
    return _normalized_id(entity_id).startswith(normalized_ref)


def _short_id_map(entity_ids: list[str], minimum_length: int = 8) -> dict[str, str]:
    normalized_ids = {entity_id: _normalized_id(entity_id) for entity_id in entity_ids}
    short_map: dict[str, str] = {}
    for entity_id, normalized in normalized_ids.items():
        start_length = min(len(normalized), max(1, minimum_length))
        chosen = normalized
        for length in range(start_length, len(normalized) + 1):
            prefix = normalized[:length]
            conflicts = [
                other_id
                for other_id, other_normalized in normalized_ids.items()
                if other_id != entity_id and other_normalized.startswith(prefix)
            ]
            if not conflicts:
                chosen = prefix
                break
        short_map[entity_id] = chosen
    return short_map


def _unique_prefix_id_match(entity_ids: list[str], ref: str) -> str | None:
    matches = [
        entity_id for entity_id in entity_ids if _id_prefix_matches(entity_id, ref)
    ]
    if len(matches) == 1:
        return matches[0]
    return None


def _unique_name_prefix_match(
    ref: str,
    items: list[object],
    *,
    get_name: Callable[[object], str],
) -> object | None:
    normalized_ref = ref.strip().lower()
    if len(normalized_ref) < 3:
        return None
    matches = [
        item
        for item in items
        if get_name(item).strip().lower().startswith(normalized_ref)
    ]
    if len(matches) == 1:
        return matches[0]
    return None


@dataclass(frozen=True)
class RuntimeServerPayload:
    """Observed runtime server payload for CLI visibility."""

    base_url: str
    reachable: bool
    status: str | None
    database: str | None
    error: str | None
    checked: bool
    api_key_present: bool
    api_key_authorized: bool | None = None
    auth_error: str | None = None
    api_key_source: str | None = None

    def to_dict(self) -> dict[str, str | bool | None]:
        return {
            "base_url": self.base_url,
            "reachable": self.reachable,
            "status": self.status,
            "database": self.database,
            "error": self.error,
            "checked": self.checked,
            "api_key_present": self.api_key_present,
            "api_key_authorized": self.api_key_authorized,
            "auth_error": self.auth_error,
            "api_key_source": self.api_key_source,
        }


@dataclass(frozen=True)
class RuntimeWriteDecision:
    """Decision about whether a command may or should use server-backed writes."""

    allowed: bool
    use_server: bool
    payload: RuntimeServerPayload
    block_reason: str | None


@dataclass(frozen=True)
class RuntimeCoordinationStatus:
    """Operator-facing summary of whether server-backed coordination is working."""

    state: str
    summary: str
    reason: str | None
    can_delegate_writes: bool
    recommended_next_steps: tuple[str, ...]
    recovery_kind: str | None = None
    recovery_summary: str | None = None
    configured_server_url: str | None = None
    discovered_server_url: str | None = None

    def to_dict(self) -> dict[str, object]:
        payload: dict[str, object] = {
            "state": self.state,
            "summary": self.summary,
            "reason": self.reason,
            "can_delegate_writes": self.can_delegate_writes,
            "configured_server_url": self.configured_server_url,
            "discovered_server_url": self.discovered_server_url,
            "recommended_next_steps": _normalize_next_steps(
                *self.recommended_next_steps
            ),
        }
        if self.recovery_kind or self.recovery_summary:
            payload["recovery"] = {
                "kind": self.recovery_kind,
                "summary": self.recovery_summary,
            }
        return payload


@dataclass(frozen=True)
class LocalAdminKeyMaterial:
    """Resolved local admin key material for server-backed runtime setup."""

    key_id: str
    prefix: str
    key_path: str
    reused_existing: bool


@dataclass(frozen=True)
class CommandFocusTarget:
    """Most actionable task for a command-level entry surface."""

    task_id: str
    title: str
    status_value: str
    project_id: str | None
    project_name: str | None
    current_progress_percent: int | None

    @property
    def reason(self) -> str:
        return _task_list_focus_reason(self.status_value)

    def to_payload(self) -> dict[str, str | int | None]:
        return {
            "id": self.task_id,
            "title": self.title,
            "status": self.status_value,
            "project_id": self.project_id,
            "project_name": self.project_name,
            "current_progress_percent": self.current_progress_percent,
            "reason": self.reason,
        }

    def next_steps(self) -> list[str]:
        task_label, project_clause = _task_ref_with_project(
            self.title,
            self.project_name,
        )
        if self.status_value == TaskStatus.IN_PROGRESS.value:
            return [
                f"task progress {task_label}{project_clause} <percent> <message> --by <user>",
                f"task show {task_label}{project_clause}",
            ]
        if self.status_value == TaskStatus.IN_REVIEW.value:
            return [
                f"task complete {task_label}{project_clause} --by <user>",
                f"task show {task_label}{project_clause}",
            ]
        if self.status_value == TaskStatus.TODO.value:
            return [
                f"task start {task_label}{project_clause}",
                f"task show {task_label}{project_clause}",
            ]
        if self.status_value == TaskStatus.BLOCKED.value:
            return [
                f"task unblock {task_label}{project_clause}",
                f"task show {task_label}{project_clause}",
            ]
        return [f"task show {task_label}{project_clause}"]


@dataclass(frozen=True)
class CommandFocusState:
    """Resolved focus state for command-level entry surfaces."""

    focus_task: CommandFocusTarget | None
    terminal_reason: str | None


class CommandFocusEntry(Protocol):
    """Minimal task-like shape needed for command focus selection."""

    id: str
    title: str
    status: TaskStatus | str
    project_id: str | None
    updated_at: datetime


class PlanListEntry(Protocol):
    """Minimal plan-like shape needed for plan list prioritization."""

    id: str
    status: object
    updated_at: datetime


def _runtime_server_payload() -> RuntimeServerPayload:
    from pms.config import get_settings
    from pms.runtime.write_coordination import probe_server_auth, probe_server_health

    settings = get_settings()
    api_key, api_key_source = _runtime_api_key_material()
    api_key_present = bool(api_key)
    if settings.write_mode == "direct":
        return RuntimeServerPayload(
            base_url=settings.server_base_url,
            reachable=False,
            status=None,
            database=None,
            error=None,
            checked=False,
            api_key_present=api_key_present,
            api_key_source=api_key_source,
        )

    health = probe_server_health(settings.server_base_url)
    api_key_authorized: bool | None = None
    auth_error: str | None = None
    if health.reachable and api_key:
        auth_status = probe_server_auth(settings.server_base_url, api_key)
        api_key_authorized = auth_status.authorized
        auth_error = auth_status.error
    return RuntimeServerPayload(
        base_url=health.base_url,
        reachable=health.reachable,
        status=health.status,
        database=health.database,
        error=health.error,
        checked=True,
        api_key_present=api_key_present,
        api_key_authorized=api_key_authorized,
        auth_error=auth_error,
        api_key_source=api_key_source,
    )


def _is_loopback_server_url(server_url: str) -> bool:
    host = (urlparse(server_url).hostname or "").strip().lower()
    return host in {"127.0.0.1", "localhost", "::1"}


def _managed_runtime_servers() -> list[dict[str, object]]:
    from pms.config import get_settings
    from pms.runtime.local_server import list_managed_local_servers

    settings = get_settings()
    return [
        {
            "port": status.port,
            "server_url": status.server_url,
            "pid": status.pid,
            "tracked": status.tracked,
            "running": status.running,
            "reachable": status.reachable,
            "pid_file": status.pid_file,
            "log_file": status.log_file,
            "error": status.error,
        }
        for status in list_managed_local_servers(data_dir=settings.data_dir)
    ]


def _healthy_managed_runtime_server() -> dict[str, object] | None:
    from pms.config import get_settings

    configured_server_url = get_settings().server_base_url
    healthy = [
        status
        for status in _managed_runtime_servers()
        if status["tracked"] and status["running"] and status["reachable"]
    ]
    if not healthy:
        return None
    if configured_server_url:
        for status in healthy:
            if str(status["server_url"]) == configured_server_url:
                return status
    return healthy[0]
    return None


def _resolve_runtime_write_decision(action_name: str) -> RuntimeWriteDecision:
    from pms.config import get_settings

    settings = get_settings()
    payload = _runtime_server_payload()
    if settings.write_mode == "direct":
        return RuntimeWriteDecision(
            allowed=True,
            use_server=False,
            payload=payload,
            block_reason=None,
        )

    if settings.write_mode == "require_server":
        if not payload.reachable:
            return RuntimeWriteDecision(
                allowed=False,
                use_server=False,
                payload=payload,
                block_reason=(
                    f"`{action_name}` requires a reachable PMS server at "
                    f"{settings.server_base_url}."
                ),
            )
        if not payload.api_key_present:
            return RuntimeWriteDecision(
                allowed=False,
                use_server=False,
                payload=payload,
                block_reason=(
                    f"`{action_name}` requires PMS_API_KEY to delegate writes through "
                    f"{settings.server_base_url}."
                ),
            )
        return RuntimeWriteDecision(
            allowed=True,
            use_server=True,
            payload=payload,
            block_reason=None,
        )

    if (
        payload.reachable
        and payload.api_key_present
        and payload.api_key_authorized is False
    ):
        return RuntimeWriteDecision(
            allowed=True,
            use_server=False,
            payload=payload,
            block_reason=None,
        )

    if payload.reachable and payload.api_key_present:
        return RuntimeWriteDecision(
            allowed=True,
            use_server=True,
            payload=payload,
            block_reason=None,
        )
    return RuntimeWriteDecision(
        allowed=True,
        use_server=False,
        payload=payload,
        block_reason=None,
    )


def _runtime_coordination_status() -> RuntimeCoordinationStatus:
    from pms.config import get_settings

    settings = get_settings()
    payload = _runtime_server_payload()
    managed_server = _healthy_managed_runtime_server()

    if settings.write_mode == "direct":
        return RuntimeCoordinationStatus(
            state="direct_file_mode",
            summary="Direct-file mode is active.",
            reason=(
                "Writes are going straight to SQLite because PMS_WRITE_MODE is set to "
                "`direct`."
            ),
            can_delegate_writes=False,
            recommended_next_steps=(
                f"config set --write-mode prefer_server --server-url {LOCAL_SERVER_DEFAULT_BASE_URL}",
                f"runtime prefer-server --host {LOCAL_SERVER_DEFAULT_HOST} --port {LOCAL_RUNTIME_DEFAULT_PORT}",
                "start --format json",
            ),
            recovery_kind="enable_server_coordination",
            recovery_summary=(
                "Switch to server-backed coordination only if you need converged multi-writer behavior."
            ),
            configured_server_url=settings.server_base_url,
            discovered_server_url=(
                str(managed_server["server_url"])
                if managed_server is not None
                else None
            ),
        )

    if (
        payload.reachable
        and payload.api_key_present
        and payload.api_key_authorized is not False
        and managed_server is None
        and _is_loopback_server_url(settings.server_base_url)
    ):
        return RuntimeCoordinationStatus(
            state="degraded_unmanaged_local_server",
            summary="Configured local server is reachable, but PMS is not tracking it as this workspace's managed runtime.",
            reason=(
                f"PMS can reach {payload.base_url}, but it is not one of this workspace's "
                "managed local servers. A reachable localhost endpoint is not enough to "
                "prove converged runtime state or matching credentials."
            ),
            can_delegate_writes=False,
            recommended_next_steps=(
                f"runtime prefer-server --host {LOCAL_SERVER_DEFAULT_HOST} --port {LOCAL_RUNTIME_DEFAULT_PORT}",
                "runtime status --format json",
                "config show --format json",
            ),
            recovery_kind="verify_managed_local_server",
            recovery_summary=(
                "Start or rebind PMS to a managed local server so delegated writes, auth, and workspace state converge."
            ),
            configured_server_url=settings.server_base_url,
            discovered_server_url=None,
        )

    if (
        payload.reachable
        and payload.api_key_present
        and payload.api_key_authorized is False
    ):
        env_override_note = (
            " PMS_API_KEY from the current environment is overriding the file-backed key."
            if payload.api_key_source == "env"
            else ""
        )
        return RuntimeCoordinationStatus(
            state="degraded_invalid_api_key",
            summary="Server is reachable, but delegated writes are not authorized.",
            reason=(
                f"PMS can reach {payload.base_url}, but the configured API key was rejected"
                + (f": {payload.auth_error}." if payload.auth_error else ".")
                + env_override_note
            ),
            can_delegate_writes=False,
            recommended_next_steps=(
                "auth recover-local-admin --show-key",
                "config show --format json",
                "runtime status --format json",
            ),
            recovery_kind="repair_api_key_auth",
            recovery_summary=(
                "Refresh the local admin key or rebind this workspace to the managed local server before relying on delegated writes."
            ),
            configured_server_url=settings.server_base_url,
            discovered_server_url=(
                str(managed_server["server_url"])
                if managed_server is not None
                else None
            ),
        )

    if payload.reachable and payload.api_key_present:
        return RuntimeCoordinationStatus(
            state="server_coordinated",
            summary="Server-backed coordination is healthy.",
            reason=(
                f"Writes can delegate through the PMS server at {payload.base_url}."
            ),
            can_delegate_writes=True,
            recommended_next_steps=(
                "start --format json",
                "dashboard --format json",
                "config show --format json",
            ),
            configured_server_url=settings.server_base_url,
            discovered_server_url=(
                str(managed_server["server_url"])
                if managed_server is not None
                else None
            ),
        )

    if payload.reachable and not payload.api_key_present:
        return RuntimeCoordinationStatus(
            state="degraded_missing_api_key",
            summary="Server is reachable, but writes are falling back to direct-file mode.",
            reason=(
                "PMS_WRITE_MODE prefers the server, but PMS_API_KEY is missing so write "
                f"delegation to {payload.base_url} cannot be used."
            ),
            can_delegate_writes=False,
            recommended_next_steps=(
                "auth recover-local-admin --show-key",
                "export PMS_API_KEY=$(cat .pms-admin-key)",
                "start --format json",
            ),
            recovery_kind="restore_api_key",
            recovery_summary=(
                "Recover or re-export the local admin API key so writes can delegate through the healthy server."
            ),
            configured_server_url=settings.server_base_url,
            discovered_server_url=(
                str(managed_server["server_url"])
                if managed_server is not None
                else None
            ),
        )

    if (
        managed_server is not None
        and str(managed_server["server_url"]) != settings.server_base_url
    ):
        repair_command = (
            f"runtime prefer-server --host 127.0.0.1 --port {managed_server['port']}"
        )
        return RuntimeCoordinationStatus(
            state="degraded_stale_server_url",
            summary="Configured server URL is stale; a healthy managed local server is available.",
            reason=(
                "PMS is configured to prefer "
                f"{settings.server_base_url}, but the managed local runtime is healthy at "
                f"{managed_server['server_url']}."
            ),
            can_delegate_writes=False,
            recommended_next_steps=(
                repair_command,
                "runtime status --format json",
                "config show --format json",
            ),
            recovery_kind="repair_server_url",
            recovery_summary=(
                "Point PMS at the already healthy managed server instead of the stale configured endpoint."
            ),
            configured_server_url=settings.server_base_url,
            discovered_server_url=str(managed_server["server_url"]),
        )

    if settings.write_mode == "require_server":
        return RuntimeCoordinationStatus(
            state="blocked_server_unreachable",
            summary="Required server coordination is blocked.",
            reason=(
                f"PMS_WRITE_MODE is `require_server`, but {payload.base_url} is not "
                "reachable."
            ),
            can_delegate_writes=False,
            recommended_next_steps=(
                f"runtime prefer-server --host {LOCAL_SERVER_DEFAULT_HOST} --port {LOCAL_RUNTIME_DEFAULT_PORT}",
                "config show --format json",
                "start --format json",
            ),
            recovery_kind="restore_required_server",
            recovery_summary=(
                "Writes are blocked until a reachable server is restored because write mode requires delegation."
            ),
            configured_server_url=settings.server_base_url,
            discovered_server_url=(
                str(managed_server["server_url"])
                if managed_server is not None
                else None
            ),
        )

    error_suffix = f" Probe error: {payload.error}" if payload.error else ""
    return RuntimeCoordinationStatus(
        state="degraded_server_unreachable",
        summary="Server-preferred mode is configured, but writes are falling back to direct-file mode.",
        reason=(
            f"PMS_WRITE_MODE prefers the server, but {payload.base_url} is not "
            f"reachable.{error_suffix}"
        ),
        can_delegate_writes=False,
        recommended_next_steps=(
            f"runtime prefer-server --host {LOCAL_SERVER_DEFAULT_HOST} --port {LOCAL_RUNTIME_DEFAULT_PORT}",
            "runtime status --format json",
            "config show --format json",
            "start --format json",
        ),
        recovery_kind="restore_preferred_server",
        recovery_summary=(
            "Run prefer-server to start or rebind the managed PMS API for this workspace. "
            "If the probe returned HTTP 404, the configured port is probably owned by a "
            "non-PMS service."
        ),
        configured_server_url=settings.server_base_url,
        discovered_server_url=(
            str(managed_server["server_url"]) if managed_server is not None else None
        ),
    )


def _ensure_runtime_write_mode(
    action_name: str,
    *,
    emit_messages: bool = True,
) -> RuntimeWriteDecision | None:
    decision = _resolve_runtime_write_decision(action_name)
    if not decision.allowed:
        if emit_messages:
            console.print(f"[red]Write blocked:[/red] {decision.block_reason}")
            if decision.payload.error:
                console.print(
                    f"[dim]Server probe error: {decision.payload.error}[/dim]"
                )
            _print_next_steps(*_runtime_coordination_status().recommended_next_steps)
        return None

    if emit_messages and decision.payload.checked and not decision.payload.reachable:
        console.print(
            "[yellow]Runtime:[/yellow] "
            f"`{action_name}` is running in direct-file fallback because "
            f"{decision.payload.base_url} is not reachable."
        )
    elif (
        emit_messages
        and decision.payload.checked
        and decision.payload.reachable
        and not decision.payload.api_key_present
    ):
        console.print(
            "[yellow]Runtime:[/yellow] "
            f"`{action_name}` is using direct-file fallback because PMS_API_KEY is not set "
            f"for server delegation to {decision.payload.base_url}."
        )
    return decision


def _runtime_write_context_payload(
    decision: RuntimeWriteDecision,
) -> dict[str, object]:
    from pms.config import get_settings

    settings = get_settings()
    live_root = settings.data_dir.expanduser().resolve()
    db_path = settings.database_path.expanduser().resolve()
    cwd = Path.cwd().resolve()
    in_workspace = cwd in live_root.parents or live_root == cwd
    coordination = _runtime_coordination_status()
    write_path = "server_delegated" if decision.use_server else "direct_file"
    target_kind = "server" if decision.use_server else "workspace_sqlite"
    target_location = decision.payload.base_url if decision.use_server else str(db_path)
    return {
        "write_mode": settings.write_mode,
        "write_path": write_path,
        "target_kind": target_kind,
        "target_location": target_location,
        "server_base_url": settings.server_base_url,
        "delegated_server_url": decision.payload.base_url
        if decision.use_server
        else None,
        "coordination_state": coordination.state,
        "workspace": {
            "cwd": str(cwd),
            "data_dir": str(live_root),
            "database_path": str(db_path),
            "managed_state_in_cwd": in_workspace,
        },
    }


def _reconciled_progress_last_update(
    task: Task,
    last_update: dict[str, object] | None,
) -> dict[str, object] | None:
    if (
        task.status == TaskStatus.DONE
        and task.completed_at is not None
        and task.current_progress_percent == 100
    ):
        if (
            last_update is None
            or int(last_update.get("percent_complete") or 0) != 100
            or last_update.get("timestamp") != _to_iso(task.completed_at)
        ):
            reconciled = dict(last_update) if last_update else {}
            reconciled.update(
                {
                    "task_id": task.id,
                    "percent_complete": 100,
                    "status_message": "Completed",
                    "updated_by": last_update.get("updated_by")
                    if last_update
                    else None,
                    "timestamp": _to_iso(task.completed_at),
                }
            )
            return reconciled
    if last_update is None and task.current_progress_percent > 0:
        timestamp = (
            _to_iso(task.last_progress_update_at)
            or _to_iso(task.completed_at)
            or _to_iso(task.updated_at)
        )
        return {
            "task_id": task.id,
            "percent_complete": task.current_progress_percent,
            "status_message": (
                "Completed"
                if task.status == TaskStatus.DONE
                and task.current_progress_percent == 100
                else "Progress reconciled from task snapshot"
            ),
            "updated_by": None,
            "timestamp": timestamp,
        }
    return last_update


async def _ensure_local_admin_key(
    *,
    name: str = "Local Runtime Admin Key",
) -> LocalAdminKeyMaterial:
    """Ensure .pms-admin-key contains a valid local admin key."""
    from pms.db.connection import init_database
    from pms.repositories.api_key_repository import ApiKeyRepository
    from pms.services.auth_service import AuthService
    from pms.utils.secret_files import write_secret_file

    key_file = Path(".pms-admin-key")

    db = await init_database()
    try:
        api_key_repo = ApiKeyRepository(db)
        auth_service = AuthService(api_key_repo)

        if key_file.exists():
            existing_plain_key = key_file.read_text(encoding="utf-8").strip()
            if existing_plain_key:
                existing_admin_key = await auth_service.validate_api_key(
                    existing_plain_key,
                    "admin:keys",
                )
                if existing_admin_key is not None:
                    return LocalAdminKeyMaterial(
                        key_id=existing_admin_key.id,
                        prefix=existing_admin_key.prefix,
                        key_path=str(key_file.resolve()),
                        reused_existing=True,
                    )

        plain_key, api_key = await auth_service.create_api_key(
            name=name,
            scopes=["*"],
            expires_in_days=None,
            rate_limit=None,
            metadata={"type": "admin", "created_by": "runtime_bootstrap"},
        )
        write_secret_file(key_file, plain_key)
        return LocalAdminKeyMaterial(
            key_id=api_key.id,
            prefix=api_key.prefix,
            key_path=str(key_file.resolve()),
            reused_existing=False,
        )
    finally:
        await db.disconnect()


def _install_pms_client_binary(*, server_url: str, sign: bool) -> str:
    """Install the Rust client into the repo-local .bin directory."""
    script_path = (
        Path(__file__).resolve().parents[2] / "scripts" / "install_pms_client.sh"
    )
    command = [str(script_path), "--server-url", server_url]
    if not sign:
        command.append("--no-sign")
    subprocess.run(
        command,
        check=True,
        cwd=Path(__file__).resolve().parents[2],
        capture_output=True,
        text=True,
    )
    return str((Path(__file__).resolve().parents[2] / ".bin" / "pms-client").resolve())


