async def _recover_delegated_task_start(
    *,
    task_id: str,
    task_service: Any,
) -> tuple[Task | None, str | None]:
    """Recover a delegated task start if the server mutated state before failing."""
    task = await task_service.get_task(task_id)
    if task is None or task.status.value != "in_progress":
        return None, None

    return (
        task,
        "Server-backed start completed, but the response failed after the task transitioned to in_progress.",
    )


async def _recover_delegated_task_progress(
    *,
    task_id: str,
    percent: int,
    task_service: Any,
) -> tuple[Task | None, str | None]:
    """Recover a delegated task progress update if the server mutated state first."""
    task = await task_service.get_task(task_id)
    if task is None or task.current_progress_percent != percent:
        return None, None

    return (
        task,
        "Server-backed progress update completed, but the response failed after the task state was updated.",
    )


async def _recover_delegated_task_complete(
    *,
    task_id: str,
    task_service: Any,
) -> tuple[Task | None, str | None]:
    """Recover a delegated completion if the server mutated state before failing."""
    task = await task_service.get_task(task_id)
    if task is None or task.status.value != "done":
        return None, None

    return (
        task,
        "Server-backed completion finished, but the response failed after the task transitioned to done.",
    )


def _http_status_error_detail(exc: httpx.HTTPStatusError) -> str:
    """Extract a readable API detail from an HTTP client error."""
    response = exc.response
    if response is None:
        return str(exc)
    try:
        payload = response.json()
    except ValueError:
        text = response.text.strip()
        return text or str(exc)
    if isinstance(payload, dict):
        detail = payload.get("detail")
        if isinstance(detail, str) and detail.strip():
            return detail
    return str(exc)


