def _page_payload(total_count: int, limit: int, offset: int) -> dict[str, Any]:
    limit_value = max(limit, 0)
    offset_value = max(offset, 0)
    has_more = False
    next_offset = None
    if limit_value > 0 and offset_value + limit_value < total_count:
        has_more = True
        next_offset = offset_value + limit_value
    return {
        "total_count": total_count,
        "limit": limit_value,
        "offset": offset_value,
        "has_more": has_more,
        "next_offset": next_offset,
    }


def _normalize_history_flags(
    include_history: bool,
    include_linked: bool,
    include_linked_history: bool,
) -> tuple[bool, bool, bool]:
    if include_linked_history:
        include_linked = True
        include_history = True
    return include_history, include_linked, include_linked_history


async def _build_task_history(
    *,
    task_id: str,
    progress_repo: Any | None,
    state_repo: Any | None,
    evidence_repo: Any | None,
    history_limit: int,
) -> dict[str, Any]:
    if progress_repo is None or state_repo is None:
        return {
            "progress_updates": [],
            "workflow_transitions": [],
            "status_transitions": [],
            "evidence": [],
        }

    from pms.models.progress_update import ProgressQuery
    from pms.models.state_transition import StateTransitionQuery

    progress_updates = await progress_repo.get_updates(
        ProgressQuery(task_id=task_id, limit=history_limit)
    )
    workflow_transitions = await state_repo.get_transitions(
        StateTransitionQuery(
            entity_type="task_workflow",
            entity_id=task_id,
            limit=history_limit,
        )
    )
    status_transitions = await state_repo.get_transitions(
        StateTransitionQuery(
            entity_type="task_status",
            entity_id=task_id,
            limit=history_limit,
        )
    )
    evidence_items: list[Any] = []
    if evidence_repo:
        evidence_result = await evidence_repo.list_by_task(task_id, limit=history_limit)
        evidence_items = [item.to_dict() for item in evidence_result.items]

    return {
        "progress_updates": [update.to_dict() for update in progress_updates],
        "workflow_transitions": [
            transition.to_dict() for transition in workflow_transitions
        ],
        "status_transitions": [
            transition.to_dict() for transition in status_transitions
        ],
        "evidence": evidence_items,
    }


async def _build_task_linked_payload(
    task_obj: Any,
    *,
    task_repo: Any,
    project_repo: Any,
    task_service: Any,
    linked_limit: int,
    history_limit: int,
    include_linked_history: bool,
    progress_repo: Any | None,
    state_repo: Any | None,
    evidence_repo: Any | None,
) -> tuple[dict[str, Any], dict[str, Any] | None]:
    dependencies = await task_repo.get_dependencies(task_obj.id)
    dependents = await task_repo.get_dependents(task_obj.id)
    dependency_ids = [
        dep.depends_on_id for dep in dependencies[:linked_limit] if dep.depends_on_id
    ]
    dependent_ids = [dep.task_id for dep in dependents[:linked_limit] if dep.task_id]
    linked_ids = list(dict.fromkeys(dependency_ids + dependent_ids))
    if not linked_ids:
        return {"dependencies": [], "dependents": []}, None

    linked_tasks = await task_repo.get_by_ids(linked_ids)
    project_names: dict[str, str | None] = {}
    for linked_task in linked_tasks:
        if linked_task.project_id and linked_task.project_id not in project_names:
            project = await project_repo.get_by_id(linked_task.project_id)
            project_names[linked_task.project_id] = project.name if project else None

    linked_activity_map = await task_service.get_last_activity_map(linked_ids)
    linked_workflow_map = await task_service.get_last_transition_map(
        linked_ids, kind="workflow"
    )
    linked_status_map = await task_service.get_last_transition_map(
        linked_ids, kind="status"
    )

    def _linked_summary(linked_task: Any) -> dict[str, Any]:
        last_linked_transition = (
            linked_workflow_map.get(linked_task.id)
            if linked_task.workflow_id
            else linked_status_map.get(linked_task.id)
        )
        return {
            "id": linked_task.id,
            "title": linked_task.title,
            "status": linked_task.status.value,
            "priority": linked_task.priority.value,
            "project_id": linked_task.project_id,
            "project_name": project_names.get(linked_task.project_id),
            "updated_at": linked_task.updated_at,
            "last_activity_at": _to_iso(linked_activity_map.get(linked_task.id)),
            "last_transition_at": _to_iso(last_linked_transition),
        }

    linked_map = {task.id: task for task in linked_tasks}
    payload = {
        "dependencies": [
            _linked_summary(linked_map[dep_id])
            for dep_id in dependency_ids
            if dep_id in linked_map
        ],
        "dependents": [
            _linked_summary(linked_map[dep_id])
            for dep_id in dependent_ids
            if dep_id in linked_map
        ],
    }

    linked_history = None
    if include_linked_history:
        linked_history = {
            linked_id: await _build_task_history(
                task_id=linked_id,
                progress_repo=progress_repo,
                state_repo=state_repo,
                evidence_repo=evidence_repo,
                history_limit=history_limit,
            )
            for linked_id in linked_ids
        }

    return payload, linked_history


def _format_transition_summary(result: Any) -> list[str]:
    transition = getattr(result, "workflow_transition", None)
    if transition is None:
        return []
    lines = [
        (
            "Workflow transitions: "
            f"{transition.tasks_transitioned}/{transition.tasks_considered} applied "
            f"({transition.tasks_skipped} skipped)"
        )
    ]
    skipped = getattr(transition, "skipped_reasons", None)
    if skipped:
        reasons = ", ".join(
            f"{reason}={count}" for reason, count in sorted(skipped.items())
        )
        lines.append(f"Skipped reasons: {reasons}")
    return lines


def _collect_workflow_transitions(
    workflow: Any, current_state: str | None
) -> list[str]:
    if workflow is None or not current_state:
        return []
    labels: list[str] = []
    for transition in workflow.transitions:
        if transition.from_state not in (current_state, "*"):
            continue
        if transition.to_state == current_state:
            continue
        label = transition.to_state
        if transition.requires_approval:
            label = f"{label} (approval)"
        if label not in labels:
            labels.append(label)
    return labels


def _normalize_state_name(state_name: str) -> str:
    return state_name.replace("-", "_").lower()


def _find_workflow_path(
    workflow: Any, start_state: str, target_state: str
) -> list[str] | None:
    if start_state == target_state:
        return [start_state]

    states = {start_state, target_state}
    for state in getattr(workflow, "states", []):
        state_name = getattr(state, "state_name", None)
        if state_name:
            states.add(state_name)
    for transition in getattr(workflow, "transitions", []):
        if transition.from_state:
            states.add(transition.from_state)
        if transition.to_state:
            states.add(transition.to_state)

    adjacency: dict[str, set[str]] = {state: set() for state in states}
    for transition in getattr(workflow, "transitions", []):
        if transition.from_state == "*":
            for state in states:
                adjacency[state].add(transition.to_state)
        else:
            adjacency.setdefault(transition.from_state, set()).add(transition.to_state)

    visited = {start_state}
    queue: deque[tuple[str, list[str]]] = deque([(start_state, [start_state])])
    while queue:
        current, path = queue.popleft()
        for next_state in sorted(adjacency.get(current, [])):
            if next_state == target_state:
                return [*path, next_state]
            if next_state in visited:
                continue
            visited.add(next_state)
            queue.append((next_state, [*path, next_state]))
    return None


def _suggest_terminal_state(
    status_value: str, terminal_states: list[str]
) -> str | None:
    if not terminal_states:
        return None

    terminal_map = {state: _normalize_state_name(state) for state in terminal_states}

    def match(preferences: tuple[str, ...]) -> str | None:
        for pref in preferences:
            for state, normalized in terminal_map.items():
                if normalized == pref:
                    return state
        return None

    if status_value in {"done", "completed"}:
        match_state = match(
            (
                "done",
                "completed",
                "complete",
                "finished",
                "success",
                "succeeded",
                "released",
                "shipped",
            )
        )
        if match_state:
            return match_state
        non_cancelled = [
            state
            for state, normalized in terminal_map.items()
            if normalized not in {"cancelled", "canceled"}
        ]
        if len(non_cancelled) == 1:
            return non_cancelled[0]
        return None

    if status_value in {"cancelled", "canceled", "archived"}:
        return match(
            (
                "cancelled",
                "canceled",
                "archived",
                "abandoned",
                "rejected",
            )
        )

    return None


def _status_is_terminal(entity_type: str, status_value: Any) -> bool:
    status_str = (
        status_value.value if hasattr(status_value, "value") else str(status_value)
    ).lower()
    match entity_type:
        case "task":
            if hasattr(status_value, "is_terminal"):
                return bool(status_value.is_terminal)
            return status_str in {"done", "cancelled", "canceled"}
        case "goal" | "objective":
            return status_str in {"completed", "archived"}
        case _:
            return False


