def _truncate(value: str, max_len: int) -> str:
    if len(value) <= max_len:
        return value
    return f"{value[: max_len - 3]}..."


def _format_bytes(value: int) -> str:
    if value < 1024:
        return f"{value} B"
    size = float(value)
    for unit in ("KB", "MB", "GB", "TB", "PB"):
        size /= 1024
        if size < 1024:
            return f"{size:.1f} {unit}"
    return f"{size:.1f} EB"


def _print_next_steps(*steps: str) -> None:
    steps_clean = _normalize_next_steps(*steps)
    if not steps_clean:
        return
    console.print("[dim]Next:[/dim]")
    for step in steps_clean:
        console.print(f"[dim]- {step}[/dim]")


def _normalize_next_steps(*steps: str) -> list[str]:
    return _shared_normalize_next_steps(*steps)


def _payload_with_normalized_next_steps(
    payload: dict[str, object], *steps: str
) -> dict[str, object]:
    payload["next_steps"] = _normalize_next_steps(*steps)
    coordination = _runtime_coordination_status()
    alternate_prefix = (
        _alternate_cli_command_prefix() if coordination.can_delegate_writes else None
    )
    payload["cli"] = {
        "canonical_prefix": _cli_command_prefix(),
        "alternate_prefix": alternate_prefix,
    }
    if alternate_prefix is not None:
        payload["fast_path"] = {
            "preferred_for": [
                "repeated_reads",
                "reports",
                "dashboard_views",
                "machine_readable_queries",
            ],
            "recommended_client": alternate_prefix,
            "fallback_client": _cli_command_prefix(),
            "guidance": (
                "Prefer Rust for repeated reads. Use the Python CLI for writes and fallback."
            ),
        }
    return payload


def _normalize_command_links(
    links: dict[str, str | None],
) -> dict[str, str | None]:
    return _shared_normalize_command_links(links)


def _project_surface_payload(
    project_obj: Any,
    *,
    operator_category: str,
    status: Any | None = None,
    stored_status: Any | None = None,
    terminal_reason: str | None = None,
    last_activity_at: datetime | str | None = None,
    last_transition_at: datetime | str | None = None,
    links: dict[str, str | None] | None = None,
    stats: Any | None = None,
    health_score: float | None = None,
    extra: dict[str, Any] | None = None,
) -> dict[str, Any]:
    from pms.services.generated_artifacts import (
        project_operator_category_label,
        project_operator_visibility_reason,
    )

    status_value = getattr(status, "value", status)
    if status_value is None:
        raw_status = getattr(project_obj, "status", None)
        status_value = raw_status if isinstance(raw_status, str) else str(raw_status)
    stored_status_value = getattr(stored_status, "value", stored_status)
    if stored_status_value is None:
        raw_stored_status = getattr(project_obj, "status", None)
        stored_status_value = (
            raw_stored_status
            if isinstance(raw_stored_status, str)
            else getattr(raw_stored_status, "value", str(raw_stored_status))
        )

    payload: dict[str, Any] = {
        "id": getattr(project_obj, "id", None),
        "name": getattr(project_obj, "name", None),
        "project_id": getattr(project_obj, "id", None),
        "project_name": getattr(project_obj, "name", None),
        "status": status_value,
        "stored_status": stored_status_value,
        "created_at": _to_iso(getattr(project_obj, "created_at", None)),
        "updated_at": _to_iso(getattr(project_obj, "updated_at", None)),
        "last_activity_at": _to_iso(last_activity_at),
        "last_transition_at": _to_iso(last_transition_at),
        "terminal_reason": terminal_reason,
        "operator_category": operator_category,
        "operator_category_label": project_operator_category_label(operator_category),
        "operator_visibility_reason": project_operator_visibility_reason(
            operator_category
        ),
        "total_tasks": None,
        "completed_tasks": None,
        "in_progress_tasks": None,
        "blocked_tasks": None,
        "completion_percent": None,
        "health_score": health_score,
        "links": _normalize_command_links(links or {}),
    }
    if stats is not None:
        payload.update(
            {
                "total_tasks": getattr(stats, "total_tasks", 0) or 0,
                "completed_tasks": getattr(stats, "completed_tasks", 0) or 0,
                "in_progress_tasks": getattr(stats, "in_progress_tasks", 0) or 0,
                "blocked_tasks": getattr(stats, "blocked_tasks", 0) or 0,
                "completion_percent": getattr(stats, "completion_percent", 0) or 0,
            }
        )
    if extra:
        payload.update(extra)
    return payload


