def _goal_execution_payload(
    summary: Any,
    *,
    project_name: str | None,
    task_lookup: dict[str, Any],
    assignee_map: dict[str, Any],
    checkout_actor_map: dict[str, Any],
) -> dict[str, Any] | None:
    if summary.execution is None:
        return None
    payload: dict[str, Any] = {
        "total_tasks": summary.execution.total_tasks,
        "completed_tasks": summary.execution.completed_tasks,
        "in_progress_tasks": summary.execution.in_progress_tasks,
        "blocked_tasks": summary.execution.blocked_tasks,
        "average_task_progress": summary.execution.average_task_progress,
        "completion_percent": summary.execution.completion_percent,
        "readiness_state": summary.execution.readiness_state,
        "consistency_status": summary.execution.consistency_status,
        "consistency_reason": summary.execution.consistency_reason,
        "terminal_reason": summary.execution.terminal_reason,
        "population_basis": summary.execution.population_basis,
        "scoped_goal_count": summary.execution.scoped_goal_count,
        "focus_task": None,
    }
    if summary.execution.focus_task is None:
        return payload

    focus_task = summary.execution.focus_task
    focus_task_payload = _focus_task_payload_with_assignee(
        CommandFocusTarget(
            task_id=focus_task.id,
            title=focus_task.title,
            status_value=focus_task.status,
            project_id=summary.goal.project_id,
            project_name=project_name,
            current_progress_percent=focus_task.current_progress_percent,
        ),
        task_lookup=task_lookup,
        assignee_map=assignee_map,
        checkout_actor_map=checkout_actor_map,
    ) or {
        "id": focus_task.id,
        "title": focus_task.title,
        "status": focus_task.status,
        "project_id": summary.goal.project_id,
        "project_name": project_name,
        "current_progress_percent": focus_task.current_progress_percent,
        "reason": focus_task.reason,
    }
    focus_task_payload["completion_criteria_count"] = (
        focus_task.completion_criteria_count
    )
    focus_task_payload["has_completion_criteria"] = focus_task.has_completion_criteria
    payload["focus_task"] = focus_task_payload
    return payload


def _goal_lifecycle_next_steps(
    summary: Any,
    *,
    project_name: str | None,
    terminal_reason: str | None,
    primary_surface: str,
) -> list[str]:
    goal_show_command = f"goal show {summary.goal.id}"
    goal_summary_command = f"goal summary {summary.goal.id}"
    objective_list_command = f"objective list --goal-id {summary.goal.id} --format json"
    plan_list_command = f"plan list --goal-id {summary.goal.id} --format json"
    if summary.execution is not None and summary.execution.focus_task is not None:
        focus_task = summary.execution.focus_task
        task_target = _best_task_command_target(
            focus_task.id,
            focus_task.title,
            project_name,
        )
        return _normalize_next_steps(
            f"task show {task_target}",
            (
                f"task progress {task_target} <percent> <message> --by <user>"
                if focus_task.status == TaskStatus.IN_PROGRESS.value
                else ""
            ),
            (
                f"task show {task_target} --format json"
                if focus_task.has_completion_criteria
                else ""
            ),
            (
                f"task unblock {task_target} --by <user>"
                if focus_task.status == TaskStatus.BLOCKED.value
                else ""
            ),
            (
                f"task complete {task_target} --by <user>"
                if focus_task.status == TaskStatus.IN_REVIEW.value
                else ""
            ),
            (
                f"task start {task_target}"
                if focus_task.status == TaskStatus.TODO.value
                else ""
            ),
            goal_summary_command if primary_surface == "detail" else goal_show_command,
            objective_list_command,
            plan_list_command,
            _goal_project_task_list_command(summary.goal.project_id) or "",
        )
    completion_context = _goal_completion_context_payload(
        goal_id=summary.goal.id,
        project_id=summary.goal.project_id,
        terminal_reason=terminal_reason,
    )
    if completion_context is not None:
        return list(completion_context["next_steps"])
    return _normalize_next_steps(
        goal_summary_command if primary_surface == "detail" else goal_show_command,
        objective_list_command,
        plan_list_command,
        f"goal update {summary.goal.id}",
    )


