async def _recent_completed_project_surface_payloads(
    project_service: Any,
    projects: Iterable[Any],
    *,
    activity_map: Mapping[str, datetime | str | None] | None = None,
    transition_map: Mapping[str, datetime | str | None] | None = None,
) -> tuple[
    list[dict[str, Any]],
    dict[str, datetime | str | None],
    dict[str, datetime | str | None],
]:
    from pms.services.generated_artifacts import classify_project_operator_category

    payloads: list[dict[str, Any]] = []
    recent_activity_map: dict[str, datetime | str | None] = {}
    recent_transition_map: dict[str, datetime | str | None] = {}

    for project in projects:
        summary = await project_service.get_project_summary(project.id)
        if summary is not None:
            payloads.append(_project_summary_surface_payload(summary))
            recent_activity_map[project.id] = summary.last_activity_at
            recent_transition_map[project.id] = summary.last_transition_at
            continue

        payloads.append(
            _project_surface_payload(
                project,
                operator_category=classify_project_operator_category(project),
                last_activity_at=activity_map.get(project.id) if activity_map else None,
                last_transition_at=(
                    transition_map.get(project.id) if transition_map else None
                ),
                links={
                    "self": f'project show "{project.name}" --format json',
                    "tasks": f'task list --project "{project.name}" --format json',
                    "summary": f'project summary "{project.name}" --format json',
                },
            )
        )
        recent_activity_map[project.id] = (
            activity_map.get(project.id) if activity_map else None
        )
        recent_transition_map[project.id] = (
            transition_map.get(project.id) if transition_map else None
        )

    return payloads, recent_activity_map, recent_transition_map


def _recent_terminal_project_completion_summary(
    *,
    no_other_visible_active_work: bool,
    active_surface_label: str,
) -> str:
    if no_other_visible_active_work:
        return (
            "Recently completed scoped work remains terminal. No other visible "
            "active work is currently surfaced in the default operator view."
        )
    return (
        "Recently completed scoped work remains terminal even though this "
        f"{active_surface_label} still shows unrelated active instance work."
    )


def _recent_terminal_project_completion_items(
    project_payloads: Iterable[dict[str, Any]],
) -> list[dict[str, Any]]:
    items: list[dict[str, Any]] = []
    for payload in project_payloads:
        project_name = payload.get("project_name") or payload.get("name")
        item = dict(payload)
        if project_name:
            item["next_steps"] = _normalize_next_steps(
                f'project show "{project_name}" --format json',
                f'task list --project "{project_name}" --format json',
            )
        else:
            item["next_steps"] = []
        items.append(item)
    return items


def _plan_surface_payload(
    plan_obj: Any,
    *,
    stored_status: Any | None = None,
    project_name: str | None = None,
    product_name: str | None = None,
    goal_name: str | None = None,
    objective_name: str | None = None,
    last_activity_at: datetime | str | None = None,
    last_transition_at: datetime | str | None = None,
    terminal_reason: str | None = None,
    links: dict[str, str | None] | None = None,
    extra: dict[str, Any] | None = None,
) -> dict[str, Any]:
    payload: dict[str, Any] = {
        "id": getattr(plan_obj, "id", None),
        "name": getattr(plan_obj, "name", None),
        "status": getattr(getattr(plan_obj, "status", None), "value", None)
        or getattr(plan_obj, "status", None),
        "stored_status": getattr(stored_status, "value", stored_status),
        "format": getattr(getattr(plan_obj, "format", None), "value", None)
        or getattr(plan_obj, "format", None),
        "project_id": getattr(plan_obj, "project_id", None),
        "project_name": project_name,
        "product_id": getattr(plan_obj, "product_id", None),
        "product_name": product_name,
        "goal_id": getattr(plan_obj, "goal_id", None),
        "goal_name": goal_name,
        "objective_id": getattr(plan_obj, "objective_id", None),
        "objective_name": objective_name,
        "created_at": _to_iso(getattr(plan_obj, "created_at", None)),
        "updated_at": _to_iso(getattr(plan_obj, "updated_at", None)),
        "last_activity_at": _to_iso(last_activity_at),
        "last_transition_at": _to_iso(last_transition_at),
        "terminal_reason": terminal_reason,
        "links": _normalize_command_links(links or {}),
    }
    if extra:
        payload.update(extra)
    return payload


def _normalize_nested_command_fields(
    entries: list[dict[str, Any]],
    *,
    fields: tuple[str, ...] = ("command", "continue_with"),
) -> list[dict[str, Any]]:
    normalized_entries: list[dict[str, Any]] = []
    for entry in entries:
        normalized_entry = dict(entry)
        for field in fields:
            value = normalized_entry.get(field)
            if isinstance(value, str):
                normalized_entry[field] = _cli_command(value)
        normalized_entries.append(normalized_entry)
    return normalized_entries


async def _get_project_for_operator_view(
    service: Any,
    project_id: str,
) -> Any | None:
    if hasattr(service, "get_project"):
        return await service.get_project(project_id)
    if hasattr(service, "get_by_id"):
        return await service.get_by_id(project_id)
    return None


async def _generated_project_ids(
    service: Any,
    project_ids: Iterable[str | None],
) -> set[str]:
    from pms.services.generated_artifacts import is_audit_generated_project

    excluded: set[str] = set()
    for project_id in sorted({project_id for project_id in project_ids if project_id}):
        project = await _get_project_for_operator_view(service, project_id)
        if project is None:
            continue
        if is_audit_generated_project(project):
            excluded.add(project_id)
    return excluded


@dataclass
class _VisibleProjectPage:
    items: list[Any]
    total_count: int
    limit: int
    offset: int
    suppressed_generated_count: int

    @property
    def has_more(self) -> bool:
        return self.offset + len(self.items) < self.total_count


@dataclass
class _VisibleTaskPage:
    items: list[Any]
    total_count: int
    limit: int
    offset: int
    suppressed_hidden_count: int

    @property
    def has_more(self) -> bool:
        return self.offset + len(self.items) < self.total_count


