def _task_population_totals(tasks: list[Any], task_status_enum: Any) -> dict[str, int]:
    return {
        "total_tasks": len(tasks),
        "todo_tasks": len(
            [task for task in tasks if task.status == task_status_enum.TODO]
        ),
        "in_progress_tasks": len(
            [task for task in tasks if task.status == task_status_enum.IN_PROGRESS]
        ),
        "blocked_tasks": len(
            [task for task in tasks if task.status == task_status_enum.BLOCKED]
        ),
        "in_review_tasks": len(
            [task for task in tasks if task.status == task_status_enum.IN_REVIEW]
        ),
        "done_tasks": len(
            [task for task in tasks if task.status == task_status_enum.DONE]
        ),
        "cancelled_tasks": len(
            [task for task in tasks if task.status == task_status_enum.CANCELLED]
        ),
    }


def _duplicate_group_totals(groups: list[Any]) -> dict[str, int]:
    return {
        "duplicate_groups": len(groups),
        "duplicate_tasks": sum(len(group.tasks) for group in groups),
    }


def _project_population_totals(
    projects: list[Any], project_status_enum: Any
) -> dict[str, int]:
    completed_status = project_status_enum.COMPLETED
    archived_status = project_status_enum.ARCHIVED
    active_status = project_status_enum.ACTIVE
    return {
        "total_projects": len(projects),
        "completed_projects": len(
            [
                project
                for project in projects
                if (getattr(project, "effective_status", None) or project.status)
                == completed_status
            ]
        ),
        "archived_projects": len(
            [
                project
                for project in projects
                if (getattr(project, "effective_status", None) or project.status)
                == archived_status
            ]
        ),
        "active_projects": len(
            [
                project
                for project in projects
                if (getattr(project, "effective_status", None) or project.status)
                == active_status
            ]
        ),
    }


def _project_operator_category_totals(projects: list[Any]) -> dict[str, int]:
    from pms.services.generated_artifacts import classify_project_operator_category

    counts: dict[str, int] = {}
    for project in projects:
        effective_status = getattr(project, "effective_status", None) or project.status
        category = classify_project_operator_category(
            project,
            effective_status=getattr(effective_status, "value", str(effective_status)),
        )
        counts[category] = counts.get(category, 0) + 1
    return counts


def _project_payloads_by_operator_category(
    payloads: Iterable[dict[str, Any]],
) -> dict[str, list[dict[str, Any]]]:
    grouped: dict[str, list[dict[str, Any]]] = {}
    for payload in payloads:
        category = str(payload.get("operator_category") or "unknown")
        grouped.setdefault(category, []).append(payload)
    return grouped


async def _list_visible_goals(
    service: Any,
    project_repo: Any,
    *,
    status: Any | None,
    horizon: Any | None,
    product_id: str | None,
    project_id: str | None,
    limit: int,
    offset: int,
) -> tuple[QueryResult[Any], int]:
    """Paginate over operator-visible goals, not raw rows then filtered rows."""
    from pms.services.generated_artifacts import is_audit_generated_goal

    batch_size = max(limit if limit > 0 else 100, 100)
    source_offset = 0
    suppressed_generated_count = 0
    visible_seen = 0
    visible_items: list[Any] = []
    project_names: dict[str, str] = {}

    while True:
        result = await service.list_goals(
            status=status,
            horizon=horizon,
            product_id=product_id,
            project_id=project_id,
            limit=batch_size,
            offset=source_offset,
        )
        for goal in result.items:
            project_name = None
            if goal.project_id:
                if goal.project_id not in project_names:
                    project = await project_repo.get_by_id(goal.project_id)
                    if project is not None:
                        project_names[goal.project_id] = project.name
                project_name = project_names.get(goal.project_id)
            if is_audit_generated_goal(goal, project_name=project_name):
                suppressed_generated_count += 1
                continue
            if visible_seen < offset:
                visible_seen += 1
                continue
            if limit <= 0 or len(visible_items) < limit:
                visible_items.append(goal)
            visible_seen += 1
        if not result.has_more:
            break
        source_offset += result.limit

    return (
        QueryResult(
            items=visible_items,
            total_count=visible_seen,
            offset=offset,
            limit=limit,
        ),
        suppressed_generated_count,
    )


async def _collect_goal_operator_populations(
    service: Any,
    project_repo: Any,
    *,
    status: Any | None,
    horizon: Any | None,
    product_id: str | None,
    project_id: str | None,
    limit: int,
    offset: int,
) -> dict[str, Any]:
    """Collect raw and operator-visible goal populations under one paging pass."""
    from pms.services.generated_artifacts import (
        classify_project_operator_category,
        is_audit_generated_goal,
    )

    batch_size = max(limit if limit > 0 else 100, 100)
    source_offset = 0
    project_cache: dict[str, Any | None] = {}
    project_names: dict[str, str] = {}
    raw_items: list[Any] = []
    visible_items: list[Any] = []
    raw_seen = 0
    visible_seen = 0
    suppressed_generated_count = 0
    suppressed_hidden_count = 0
    raw_counts = {key: 0 for key in ("active", "completed", "on_hold", "archived")}
    visible_counts = {key: 0 for key in ("active", "completed", "on_hold", "archived")}
    project_categories: dict[str, str] = {}

    while True:
        result = await service.list_goals(
            status=status,
            horizon=horizon,
            product_id=product_id,
            project_id=project_id,
            limit=batch_size,
            offset=source_offset,
        )
        for goal in result.items:
            raw_counts[goal.status.value] += 1
            if raw_seen >= offset and (limit <= 0 or len(raw_items) < limit):
                raw_items.append(goal)
            raw_seen += 1

            project = None
            project_name = None
            project_category = None
            if goal.project_id:
                if goal.project_id not in project_cache:
                    project_cache[goal.project_id] = await project_repo.get_by_id(
                        goal.project_id
                    )
                    if project_cache[goal.project_id] is not None:
                        project_names[goal.project_id] = project_cache[
                            goal.project_id
                        ].name
                project = project_cache.get(goal.project_id)
                project_name = project_names.get(goal.project_id)
                if project is not None:
                    project_category = classify_project_operator_category(project)
                    project_categories[goal.project_id] = project_category

            if is_audit_generated_goal(goal, project_name=project_name):
                suppressed_generated_count += 1
                continue
            if (
                project_id is None
                and project is not None
                and (
                    project.status.value != "active"
                    or project_category != "active_work"
                )
            ):
                suppressed_hidden_count += 1
                continue

            visible_counts[goal.status.value] += 1
            if visible_seen >= offset and (limit <= 0 or len(visible_items) < limit):
                visible_items.append(goal)
            visible_seen += 1
        if not result.has_more:
            break
        source_offset += result.limit

    return {
        "raw_result": QueryResult(
            items=raw_items,
            total_count=raw_seen,
            offset=offset,
            limit=limit,
        ),
        "visible_result": QueryResult(
            items=visible_items,
            total_count=visible_seen,
            offset=offset,
            limit=limit,
        ),
        "raw_counts": raw_counts,
        "visible_counts": visible_counts,
        "suppressed_generated_count": suppressed_generated_count,
        "suppressed_hidden_count": suppressed_hidden_count,
        "project_names": project_names,
        "project_categories": project_categories,
    }


async def _list_plans_for_display(
    service: Any,
    project_repo: Any,
    *,
    status: Any | None,
    project_id: str | None,
    product_id: str | None,
    goal_id: str | None,
    objective_id: str | None,
    task_id: str | None,
    limit: int,
    offset: int,
    include_generated: bool,
) -> tuple[
    QueryResult[Any],
    QueryResult[Any],
    dict[str, datetime | None],
    dict[str, Any],
    dict[str, str],
    int,
]:
    """List plans in rolled-up activity order, then paginate the visible set."""
    from pms.services.generated_artifacts import (
        is_audit_generated_plan,
    )

    batch_size = max(limit if limit > 0 else 100, 100)
    source_offset = 0
    all_items: list[Any] = []
    result: QueryResult[Any] | None = None

    while True:
        result = await service.list_plans(
            status=None,
            project_id=project_id,
            product_id=product_id,
            goal_id=goal_id,
            objective_id=objective_id,
            task_id=task_id,
            limit=batch_size,
            offset=source_offset,
        )
        all_items.extend(result.items)
        if not result.has_more:
            break
        source_offset += result.limit

    activity_map = await service.get_last_activity_map(all_items)
    lifecycle_rollups = await service.get_lifecycle_rollup_map(all_items)
    stored_status_map = {
        plan.id: plan.status.value
        if hasattr(plan.status, "value")
        else str(plan.status)
        for plan in all_items
    }
    display_candidates = [
        replace(
            plan,
            status=lifecycle_rollups.get(plan.id).effective_status
            if lifecycle_rollups.get(plan.id) is not None
            else plan.status,
        )
        for plan in all_items
    ]
    if status is not None:
        display_candidates = [
            plan for plan in display_candidates if plan.status == status
        ]
    sorted_items = _sort_plan_list_entries(
        display_candidates, activity_map=activity_map
    )

    suppressed_generated_count = 0
    visible_items: list[Any] = []
    project_names: dict[str, str] = {}

    for plan in sorted_items:
        if include_generated:
            visible_items.append(plan)
            continue
        project_name = None
        if plan.project_id:
            if plan.project_id not in project_names:
                project = await project_repo.get_by_id(plan.project_id)
                if project is not None:
                    project_names[plan.project_id] = project.name
            project_name = project_names.get(plan.project_id)
        if is_audit_generated_plan(plan, project_name):
            suppressed_generated_count += 1
            continue
        visible_items.append(plan)

    paged_items = (
        visible_items[offset:] if limit <= 0 else visible_items[offset : offset + limit]
    )

    return (
        QueryResult(
            items=visible_items,
            total_count=len(visible_items),
            offset=0,
            limit=0,
        ),
        QueryResult(
            items=paged_items,
            total_count=len(visible_items),
            offset=offset,
            limit=limit,
        ),
        activity_map,
        lifecycle_rollups,
        stored_status_map,
        suppressed_generated_count,
    )


async def _list_projects_without_plans_for_display(
    db: Any,
    project_service: Any,
    *,
    limit: int,
    include_generated: bool,
) -> tuple[
    QueryResult[Any],
    QueryResult[Any],
    dict[str, datetime | None],
    dict[str, datetime | None],
    dict[str, int],
    int,
]:
    """List recent non-archived projects that have no attached plans."""
    from pms.services.generated_artifacts import is_audit_generated_project

    all_projects = await project_service.list_all_projects()
    candidate_projects = [
        project
        for project in all_projects
        if getattr(project.status, "value", project.status) != "archived"
    ]
    if not candidate_projects:
        return (
            QueryResult(items=[], total_count=0, offset=0, limit=0),
            QueryResult(items=[], total_count=0, offset=0, limit=limit),
            {},
            {},
            {},
            0,
        )

    project_ids = [project.id for project in candidate_projects]
    placeholders = ", ".join("?" * len(project_ids))
    plan_count_rows = await db.fetch_all(
        f"""
        SELECT project_id, COUNT(*) AS count
        FROM plans
        WHERE project_id IN ({placeholders})
        GROUP BY project_id
        """,
        tuple(project_ids),
    )
    plan_counts = {row["project_id"]: int(row["count"] or 0) for row in plan_count_rows}
    unplanned_projects = [
        project for project in candidate_projects if plan_counts.get(project.id, 0) == 0
    ]
    suppressed_generated_count = 0
    if not include_generated:
        visible_unplanned_projects: list[Any] = []
        for project in unplanned_projects:
            if is_audit_generated_project(project):
                suppressed_generated_count += 1
                continue
            visible_unplanned_projects.append(project)
        unplanned_projects = visible_unplanned_projects
    if not unplanned_projects:
        return (
            QueryResult(items=[], total_count=0, offset=0, limit=0),
            QueryResult(items=[], total_count=0, offset=0, limit=limit),
            {},
            {},
            {},
            suppressed_generated_count,
        )

    activity_map = await project_service.get_last_activity_map(
        [project.id for project in unplanned_projects]
    )
    transition_map = await project_service.get_last_transition_map(
        [project.id for project in unplanned_projects]
    )
    sorted_projects = sort_items_by_bubbled_recency(
        unplanned_projects,
        activity_of=lambda project: activity_map.get(project.id),
        transition_of=lambda project: transition_map.get(project.id),
        updated_of=lambda project: project.updated_at,
        label_of=lambda project: project.name,
        id_of=lambda project: project.id,
    )
    visible_projects = sorted_projects[:limit] if limit > 0 else sorted_projects
    return (
        QueryResult(
            items=sorted_projects,
            total_count=len(sorted_projects),
            offset=0,
            limit=0,
        ),
        QueryResult(
            items=visible_projects,
            total_count=len(sorted_projects),
            offset=0,
            limit=limit,
        ),
        activity_map,
        transition_map,
        _project_operator_category_totals(sorted_projects),
        suppressed_generated_count,
    )


async def _list_projects_for_display(
    service: Any,
    *,
    status: Any | None,
    operator_category_filter: str | None,
    include_generated: bool,
    limit: int,
    offset: int,
) -> tuple[
    QueryResult[Any],
    QueryResult[Any],
    int,
    dict[str, Any],
    dict[str, datetime | None],
    dict[str, datetime | None],
]:
    """Return selected and paged projects ordered by bubbled graph recency."""
    if include_generated:
        selected_population = await _list_projects_by_operator_category(
            service,
            status=status,
            operator_category_filter=operator_category_filter,
            limit=0,
            offset=0,
        )
        suppressed_generated_count = 0
    else:
        visible_population = await _list_visible_projects(
            service,
            status=status,
            operator_category_filter=operator_category_filter,
            limit=0,
            offset=0,
        )
        selected_population = QueryResult(
            items=list(visible_population.items),
            total_count=visible_population.total_count,
            offset=0,
            limit=0,
        )
        suppressed_generated_count = visible_population.suppressed_generated_count

    summaries: dict[str, Any] = {}
    activity_map: dict[str, datetime | None] = {}
    transition_map: dict[str, datetime | None] = {}
    for project in selected_population.items:
        summary = await service.get_project_summary(project.id)
        summaries[project.id] = summary
        activity_map[project.id] = (
            summary.last_activity_at if summary else project.updated_at
        )
        transition_map[project.id] = summary.last_transition_at if summary else None

    sorted_projects = sort_items_by_bubbled_recency(
        selected_population.items,
        activity_of=lambda project: activity_map.get(project.id),
        transition_of=lambda project: transition_map.get(project.id),
        updated_of=lambda project: project.updated_at,
        label_of=lambda project: project.name,
        id_of=lambda project: project.id,
    )

    display_projects = (
        sorted_projects[offset : offset + limit]
        if limit > 0
        else sorted_projects[offset:]
    )
    display_result = QueryResult(
        items=display_projects,
        total_count=len(sorted_projects),
        offset=offset,
        limit=limit,
    )
    sorted_population = QueryResult(
        items=sorted_projects,
        total_count=len(sorted_projects),
        offset=0,
        limit=0,
    )
    return (
        sorted_population,
        display_result,
        suppressed_generated_count,
        summaries,
        activity_map,
        transition_map,
    )


def _plan_list_status_value(status: object) -> str:
    value = getattr(status, "value", status)
    return value if isinstance(value, str) else str(value)


def _plan_list_rank(status_value: str) -> int:
    if status_value == "active":
        return 0
    if status_value == "draft":
        return 1
    if status_value == "completed":
        return 2
    if status_value == "archived":
        return 3
    return 4


def _plan_list_activity_sort_timestamp(
    plan: PlanListEntry,
    activity_map: Mapping[str, datetime | None] | None = None,
) -> float:
    plan_updated_ts = _sort_timestamp(plan.updated_at)
    if activity_map is None:
        return plan_updated_ts
    return max(plan_updated_ts, _sort_timestamp(activity_map.get(plan.id)))


def _sort_plan_list_entries(
    plans: list[PlanListEntry],
    activity_map: Mapping[str, datetime | None] | None = None,
) -> list[PlanListEntry]:
    return sorted(
        plans,
        key=lambda plan: (
            _plan_list_rank(_plan_list_status_value(plan.status)),
            -_plan_list_activity_sort_timestamp(plan, activity_map),
        ),
    )


def _primary_plan_list_entry(
    plans: list[PlanListEntry],
    activity_map: Mapping[str, datetime | None] | None = None,
) -> PlanListEntry | None:
    sorted_plans = _sort_plan_list_entries(plans, activity_map=activity_map)
    return sorted_plans[0] if sorted_plans else None


def _freshest_plan_timestamp_entry(
    plans: Iterable[PlanListEntry],
    timestamp_map: Mapping[str, datetime | None],
    *,
    fallback_to_updated_at: bool = False,
) -> tuple[PlanListEntry, datetime | None] | None:
    best_plan: PlanListEntry | None = None
    best_timestamp: datetime | None = None
    for plan in plans:
        candidate = timestamp_map.get(plan.id)
        if candidate is None and fallback_to_updated_at:
            candidate = plan.updated_at
        if candidate is None:
            continue
        if best_timestamp is None or _sort_timestamp(candidate) > _sort_timestamp(
            best_timestamp
        ):
            best_plan = plan
            best_timestamp = candidate
    if best_plan is None:
        return None
    return best_plan, best_timestamp


def _freshest_entity_timestamp_entry(
    items: Iterable[Any],
    timestamp_map: Mapping[str, datetime | None],
    *,
    fallback_to_updated_at: bool = False,
) -> tuple[Any, datetime | None] | None:
    best_item: Any | None = None
    best_timestamp: datetime | None = None
    for item in items:
        item_id = getattr(item, "id", None)
        candidate = timestamp_map.get(item_id) if item_id is not None else None
        if candidate is None and fallback_to_updated_at:
            candidate = getattr(item, "updated_at", None)
        if candidate is None:
            continue
        if best_timestamp is None or _sort_timestamp(candidate) > _sort_timestamp(
            best_timestamp
        ):
            best_item = item
            best_timestamp = candidate
    if best_item is None:
        return None
    return best_item, best_timestamp


async def _operator_hidden_project_ids(
    service: Any,
    project_ids: Iterable[str | None],
) -> set[str]:
    from pms.services.generated_artifacts import classify_project_operator_category

    excluded: set[str] = set()
    projects: list[Any] = []
    for project_id in sorted({project_id for project_id in project_ids if project_id}):
        project = await _get_project_for_operator_view(service, project_id)
        if project is not None:
            projects.append(project)
    lifecycle_rollups = await service.get_lifecycle_rollup_map(projects)
    for project in projects:
        effective_status = (
            lifecycle_rollups.get(project.id).effective_status
            if lifecycle_rollups.get(project.id) is not None
            else project.status
        )
        effective_status_value = getattr(
            effective_status,
            "value",
            str(effective_status),
        )
        if (
            effective_status_value != "active"
            or classify_project_operator_category(
                project,
                effective_status=effective_status_value,
            )
            != "active_work"
        ):
            excluded.add(project.id)
    return excluded


async def _operator_hidden_project_ids_for_task_views(
    project_service: Any,
    task_service: Any,
    *,
    active_projects: Iterable[Any] = (),
    candidate_limit: int = 500,
) -> set[str]:
    ready_tasks = await task_service.list_ready_tasks(limit=candidate_limit, offset=0)
    in_progress_tasks = await task_service.search_tasks(
        statuses=[TaskStatus.IN_PROGRESS],
        include_terminal=True,
        limit=candidate_limit,
        offset=0,
    )
    blocked_tasks = await task_service.search_tasks(
        statuses=[TaskStatus.BLOCKED],
        include_terminal=True,
        limit=candidate_limit,
        offset=0,
    )
    return await _operator_hidden_project_ids(
        project_service,
        [
            *(task.project_id for task in ready_tasks.items),
            *(task.project_id for task in in_progress_tasks.items),
            *(task.project_id for task in blocked_tasks.items),
            *(summary.project.id for summary in active_projects),
        ],
    )


def _exclude_tasks_from_projects(
    tasks: Iterable[Any],
    excluded_project_ids: set[str],
) -> list[Any]:
    return [
        task
        for task in tasks
        if not task.project_id or task.project_id not in excluded_project_ids
    ]


def _exclude_active_project_summaries(
    active_projects: Iterable[Any],
    excluded_project_ids: set[str],
) -> list[Any]:
    from pms.services.generated_artifacts import classify_project_operator_category

    return [
        summary
        for summary in active_projects
        if summary.project.id not in excluded_project_ids
        and classify_project_operator_category(
            summary.project,
            effective_status=getattr(
                summary.effective_status or summary.project.status,
                "value",
                str(summary.effective_status or summary.project.status),
            ),
        )
        == "active_work"
    ]


def _slice_visible_tasks(
    tasks: Iterable[Any],
    excluded_project_ids: set[str],
    *,
    limit: int,
) -> list[Any]:
    visible = _exclude_tasks_from_projects(tasks, excluded_project_ids)
    return visible[:limit] if limit > 0 else visible


def _visible_total_count(
    total_count: int,
    loaded_items: list[Any],
    excluded_project_ids: set[str],
) -> int:
    visible_loaded = len(
        [
            item
            for item in loaded_items
            if not item.project_id or item.project_id not in excluded_project_ids
        ]
    )
    if len(loaded_items) >= total_count:
        return visible_loaded
    hidden_loaded = len(loaded_items) - visible_loaded
    return max(visible_loaded, total_count - hidden_loaded)


async def _resolve_visible_queue_summary(
    *,
    queue_service: Any,
    summary: Any,
    excluded_project_ids: set[str],
    item_limit: int,
    project_id: str | None = None,
    stale_days: int = 14,
    at_risk_days: int = 7,
) -> dict[str, Any]:
    full_summary = summary
    if (
        project_id is None
        and summary.total_count > 0
        and summary.total_count > len(summary.items)
    ):
        refreshed = await queue_service.get_preset(
            name=summary.name,
            project_id=project_id,
            limit=summary.total_count,
            stale_days=stale_days,
            at_risk_days=at_risk_days,
        )
        if refreshed is not None:
            full_summary = refreshed

    visible_items = _exclude_tasks_from_projects(
        full_summary.items,
        excluded_project_ids,
    )
    return {
        "name": full_summary.name,
        "description": full_summary.description,
        "total_count": len(visible_items),
        "items": visible_items[:item_limit] if item_limit > 0 else visible_items,
    }


def _visible_dashboard_totals(active_projects: Iterable[Any]) -> dict[str, int]:
    summaries = list(active_projects)
    total_tasks = 0
    completed_tasks = 0
    blocked_tasks = 0
    overdue_tasks = 0
    for summary in summaries:
        stats = getattr(summary, "stats", None)
        if stats is None:
            continue
        total_tasks += stats.total_tasks or 0
        completed_tasks += stats.completed_tasks or 0
        blocked_tasks += stats.blocked_tasks or 0
        overdue_tasks += stats.overdue_tasks or 0
    return {
        "active_projects": len(summaries),
        "total_tasks": total_tasks,
        "completed_tasks": completed_tasks,
        "blocked_tasks": blocked_tasks,
        "overdue_tasks": overdue_tasks,
    }


def _project_execution_payload(
    tasks: Iterable[Any],
    *,
    project_name_by_id: dict[str, str | None],
    active_limit: int = 5,
) -> dict[str, Any]:
    task_list = list(tasks)
    done_count = sum(1 for task in task_list if task.status.value == "done")
    in_progress = [task for task in task_list if task.status.value == "in_progress"]
    ready = [task for task in task_list if task.status.value == "todo"]
    blocked = [task for task in task_list if task.status.value == "blocked"]
    return {
        "total_tasks": len(task_list),
        "completed_tasks": done_count,
        "in_progress_tasks": len(in_progress),
        "ready_tasks": len(ready),
        "blocked_tasks": len(blocked),
        "active_tasks": [
            {
                "task_id": task.id,
                "title": task.title,
                "status": task.status.value,
                "progress_percent": task.current_progress_percent,
                "project_id": task.project_id,
                "project_name": project_name_by_id.get(task.project_id)
                if task.project_id
                else None,
            }
            for task in [*in_progress, *blocked][:active_limit]
        ],
    }


async def _recent_operator_visible_completed_projects(
    service: Any,
    *,
    limit: int = 3,
) -> list[Any]:
    from pms.models import ProjectStatus

    result = await _list_visible_projects(
        status=ProjectStatus.COMPLETED,
        operator_category_filter=None,
        limit=max(limit * 10, 50),
        offset=0,
        service=service,
    )
    visible_projects = list(result.items)
    activity_map = await service.get_last_activity_map(
        [project.id for project in visible_projects]
    )
    transition_map = await service.get_last_transition_map(
        [project.id for project in visible_projects]
    )
    visible_projects = sort_items_by_bubbled_recency(
        visible_projects,
        activity_of=lambda project: activity_map.get(project.id),
        transition_of=lambda project: transition_map.get(project.id),
        updated_of=lambda project: project.updated_at,
        label_of=lambda project: project.name,
        id_of=lambda project: project.id,
    )
    return visible_projects[:limit]


def _instance_scope_summary(
    *,
    noun: str,
    active_count: int,
    recent_completed_count: int,
) -> str:
    if active_count and recent_completed_count:
        return (
            f"Instance-wide {noun} view. Completed scoped work remains terminal, "
            "but unrelated active work still exists elsewhere in this PMS instance."
        )
    if recent_completed_count:
        return (
            f"Instance-wide {noun} view. The most recent scoped work is terminal; "
            "no other visible active work is currently surfaced."
        )
    return (
        f"Instance-wide {noun} view across visible operator work in this PMS instance."
    )


def _plan_status_group_counts(plans: Iterable[Any]) -> dict[str, int]:
    counts = {"draft": 0, "active": 0, "completed": 0, "archived": 0}
    for plan in plans:
        status_value = (
            plan.status.value if hasattr(plan.status, "value") else str(plan.status)
        )
        counts[status_value] = counts.get(status_value, 0) + 1
    return counts


def _plans_by_status(plans: Iterable[Any]) -> dict[str, list[Any]]:
    grouped: dict[str, list[Any]] = {
        "active": [],
        "draft": [],
        "completed": [],
        "archived": [],
    }
    for plan in plans:
        status_value = (
            plan.status.value if hasattr(plan.status, "value") else str(plan.status)
        )
        grouped.setdefault(status_value, []).append(plan)
    return grouped


def _blocked_summary_for_details(
    blocked_by_details: list[dict[str, Any]],
    execution_lock_plans: list[str],
    dependency_summary: str,
) -> str:
    if not execution_lock_plans:
        return dependency_summary

    blockers_resolved = bool(blocked_by_details) and all(
        detail.get("status") == "done" for detail in blocked_by_details
    )
    if not blocked_by_details or blockers_resolved:
        return "Draft plan lock: " + ", ".join(execution_lock_plans)
    return dependency_summary + "; draft plan lock: " + ", ".join(execution_lock_plans)


def _active_blocked_dependency_details(
    blocked_by_details: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    return [detail for detail in blocked_by_details if detail.get("status") != "done"]


def _dependency_summary_for_details(
    blocked_by_details: list[dict[str, Any]],
) -> str:
    if not blocked_by_details:
        return "No dependency detail recorded"

    if len(blocked_by_details) <= 3:
        return ", ".join(
            detail["title"] or detail["id"] for detail in blocked_by_details
        )

    active_blockers = [
        detail for detail in blocked_by_details if detail.get("status") != "done"
    ]
    preview_source = active_blockers or blocked_by_details
    preview = ", ".join(
        detail["title"] or detail["id"] for detail in preview_source[:3]
    )
    remaining = len(preview_source) - min(len(preview_source), 3)
    if remaining > 0:
        preview += f", +{remaining} more"

    if active_blockers:
        return f"{len(blocked_by_details)} blockers ({len(active_blockers)} active): {preview}"
    return f"{len(blocked_by_details)} blockers: {preview}"


def _print_plan_task_block(
    *,
    linked_tasks: list[Any],
    task_ids: list[str],
) -> None:
    console.print(f"Tasks ({len(task_ids)}):")
    if linked_tasks:
        status_counts = Counter(task.status.value for task in linked_tasks)
        count_summary = " | ".join(
            f"{status} {count}"
            for status, count in sorted(status_counts.items(), key=lambda item: item[0])
        )
        if count_summary:
            console.print(f"  Summary: {count_summary}")
        for task in linked_tasks:
            console.print(f"  - {task.title} ({task.status.value}) {task.id[:8]}")
        hidden_count = len(task_ids) - len(linked_tasks)
        if hidden_count > 0:
            console.print(f"  ... {hidden_count} more linked tasks not loaded")
        return

    for task_id in task_ids:
        console.print(f"  - {task_id[:8]} ({task_id})")


def _project_modeling_guidance(
    *,
    has_scope_links: bool,
    has_tags: bool,
) -> list[str]:
    guidance: list[str] = []
    if not has_scope_links:
        guidance.append(
            "Use org/portfolio/program/product links for durable rollups, dashboards, and multi-project coordination."
        )
        guidance.extend(
            [
                _cli_command("org create <name>"),
                _cli_command('portfolio create <name> --org "<org>"'),
                _cli_command(
                    'program create <name> --org "<org>" --portfolio "<portfolio>"'
                ),
                _cli_command(
                    'project update <ref> --org "<org>" --portfolio "<portfolio>" --program "<program>" --product "<product>"'
                ),
            ]
        )
    if not has_tags:
        guidance.append(
            "Use tags for loose cross-cutting filters; use org/portfolio/program/product for structural grouping."
        )
        guidance.append(_cli_command('project update <ref> --tag "<tag>"'))
    guidance.append(
        "Model execution explicitly: link goals/objectives, create a plan, attach tasks and evidence, then run daily/review loops from the project scope."
    )
    guidance.extend(
        [
            _cli_command('goal create <name> --project "<project>"'),
            _cli_command('objective create <name> --goal "<goal>"'),
            _cli_command('plan create <name> --project "<project>"'),
            _cli_command('task add "<project>" "<title>"'),
            _cli_command(
                'task progress "<task>" --project "<project>" <percent> <message> --by <user>'
            ),
            _cli_command("task evidence add <task_id> artifact <path>"),
            _cli_command('goal summary "<goal>"'),
            _cli_command('work daily --scope-type project --scope "<project>"'),
            _cli_command(
                'work review --scope-type project --scope "<project>" --reviewed-by <user>'
            ),
        ]
    )
    return guidance


