async def _build_blocked_task_detail_map(
    tasks: Iterable[Any],
    *,
    task_service: Any,
    task_repo: Any,
    project_service: Any,
) -> dict[str, dict[str, Any]]:
    task_list = list(tasks)
    if not task_list:
        return {}

    graph_map: dict[str, Any] = {}
    related_ids: list[str] = []
    for task_obj in task_list:
        graph = await task_service.get_dependency_graph(task_obj.id)
        graph_map[task_obj.id] = graph
        related_ids.extend(graph.blocked_by)
        related_ids.extend(graph.blocking)

    related_tasks = await task_repo.get_by_ids(list(dict.fromkeys(related_ids)))
    related_task_map = {task.id: task for task in related_tasks}

    project_names: dict[str, str | None] = {}
    for task_obj in [*task_list, *related_tasks]:
        if task_obj.project_id and task_obj.project_id not in project_names:
            project = await project_service.get_project(task_obj.project_id)
            project_names[task_obj.project_id] = project.name if project else None

    def _detail(dep_id: str) -> dict[str, Any]:
        task_obj = related_task_map.get(dep_id)
        if task_obj is None:
            return {
                "id": dep_id,
                "title": None,
                "status": None,
                "project_id": None,
                "project_name": None,
            }
        return {
            "id": task_obj.id,
            "title": task_obj.title,
            "status": task_obj.status.value,
            "project_id": task_obj.project_id,
            "project_name": project_names.get(task_obj.project_id),
        }

    detail_map: dict[str, dict[str, Any]] = {}
    for task_obj in task_list:
        graph = graph_map[task_obj.id]
        blocked_by_details = [_detail(dep_id) for dep_id in graph.blocked_by]
        active_blocked_by_details = _active_blocked_dependency_details(
            blocked_by_details
        )
        blocking_details = [_detail(dep_id) for dep_id in graph.blocking]
        execution_lock_plans = await task_service.get_execution_lock_plan_names(
            task_obj.id
        )
        dependency_summary = _dependency_summary_for_details(active_blocked_by_details)
        blocked_summary = _blocked_summary_for_details(
            active_blocked_by_details,
            execution_lock_plans,
            dependency_summary,
        )
        detail_map[task_obj.id] = {
            "blocked_by": [detail["id"] for detail in active_blocked_by_details],
            "blocking": list(graph.blocking),
            "blocked_by_details": active_blocked_by_details,
            "resolved_blocked_by_details": [
                detail
                for detail in blocked_by_details
                if detail.get("status") == "done"
            ],
            "blocking_details": blocking_details,
            "dependency_summary": dependency_summary,
            "execution_lock_plans": execution_lock_plans,
            "blocked_summary": blocked_summary,
        }
    return detail_map


def _task_ref_with_project(
    task_title: str, project_name: str | None
) -> tuple[str, str]:
    task_label = f'"{task_title}"'
    project_clause = f' --project "{project_name}"' if project_name else ""
    return task_label, project_clause


def _best_task_command_target(
    task_id: str,
    task_title: str | None,
    project_name: str | None,
) -> str:
    """Return the most ergonomic runnable task reference available."""
    if task_title:
        task_label, project_clause = _task_ref_with_project(task_title, project_name)
        return f"{task_label}{project_clause}"
    return task_id


def _task_followup_commands(
    task_id: str,
    task_title: str | None,
    project_name: str | None,
) -> tuple[dict[str, str | None], list[str]]:
    """Return normalized task links and next steps for the best available target."""
    task_target = _best_task_command_target(task_id, task_title, project_name)
    links = _normalize_command_links(
        {
            "self": _cli_command(f"task show {task_target}"),
            "timeline": _cli_command(f"task timeline {task_target}"),
            "evidence": _cli_command(f"task evidence list {task_target}"),
        }
    )
    next_steps = _normalize_next_steps(
        _cli_command(f"task show {task_target}"),
        _cli_command(f"task evidence list {task_target}"),
        _cli_command(f"task timeline {task_target}"),
    )
    return links, next_steps


def _primary_followup_step(item: dict[str, Any]) -> str | None:
    """Extract the best primary next step from a task-like payload."""
    next_steps = item.get("next_steps")
    if isinstance(next_steps, list) and next_steps:
        first = next_steps[0]
        if isinstance(first, str) and first:
            return first

    links = item.get("links")
    if isinstance(links, dict):
        for key in ("self", "show", "timeline"):
            value = links.get(key)
            if isinstance(value, str) and value:
                return value

    task_id = item.get("id")
    if isinstance(task_id, str) and task_id:
        return _cli_command(f"task show {task_id}")
    return None


def _plan_ref_with_project(
    plan_name: str,
    project_name: str | None,
) -> tuple[str, str]:
    plan_label = f'"{plan_name}"'
    project_clause = f' --project "{project_name}"' if project_name else ""
    return plan_label, project_clause


def _best_plan_command_target(
    plan_id: str,
    plan_name: str | None,
    project_name: str | None,
) -> str:
    """Return the most ergonomic runnable plan reference available."""
    if plan_name:
        plan_label, project_clause = _plan_ref_with_project(plan_name, project_name)
        return f"{plan_label}{project_clause}"
    return plan_id


def _plan_followup_commands(
    plan_id: str,
    plan_name: str | None,
    project_name: str | None,
) -> tuple[dict[str, str | None], list[str]]:
    """Return normalized plan links and next steps for the best available target."""
    plan_target = _best_plan_command_target(plan_id, plan_name, project_name)
    links = _normalize_command_links(
        {
            "self": _cli_command(f"plan show {plan_id}"),
            "lineage": _cli_command(f"plan lineage --plan-id {plan_id} --format json"),
        }
    )
    next_steps = _normalize_next_steps(
        _cli_command(f"plan show {plan_target}"),
        _cli_command(f"plan lineage --plan {plan_target}"),
    )
    return links, next_steps


def _scope_resolution_next_steps(scope_type: str, scope_ref: str) -> list[str]:
    if scope_type == "project":
        return _normalize_next_steps(
            "project list --format json",
            f'project show "{scope_ref}"',
            "start --format json",
        )
    if scope_type == "organization":
        return _normalize_next_steps(
            "org list --format json",
            f'org show "{scope_ref}"',
            "start --format json",
        )
    if scope_type == "portfolio":
        return _normalize_next_steps(
            "portfolio list --format json",
            f'portfolio show "{scope_ref}"',
            "start --format json",
        )
    if scope_type == "program":
        return _normalize_next_steps(
            "program list --format json",
            f'program show "{scope_ref}"',
            "start --format json",
        )
    return _normalize_next_steps("start --format json")


def _inline_cli_code(command: str) -> str:
    return f"`{_cli_command(command)}`"


async def _emit_draft_plan_execution_lock(
    *,
    task_id: str,
    task_service,
    project_service,
    plan_service,
    output_format: str,
    error_message: str,
    exit_code: int = 1,
) -> None:
    """Render actionable guidance when execution is locked by draft plans."""
    from pms.models import PlanStatus

    task = await task_service.get_task(task_id)
    project_name: str | None = None
    draft_plans: list[object] = []
    if task is not None and task.project_id:
        project = await project_service.get_project(task.project_id)
        project_name = project.name if project else None
        plans = await plan_service.list_plans(project_id=task.project_id, limit=1000)
        draft_plans = [
            plan
            for plan in plans.items
            if plan.status == PlanStatus.DRAFT and task.id in plan.task_ids
        ]

    task_target = _best_task_command_target(
        task_id,
        task.title if task is not None else None,
        project_name,
    )
    next_steps = [
        _cli_command(f"task show {task_target}"),
        *[
            _cli_command(f"plan update {plan.id} --status active")
            for plan in draft_plans
        ],
        *[_cli_command(f"plan show {plan.id}") for plan in draft_plans],
    ]

    if output_format == "json":
        payload = _payload_with_normalized_next_steps(
            {
                "error": {
                    "code": "draft_plan_execution_locked",
                    "message": error_message,
                },
                "task_id": task_id,
                "blocking_plans": [
                    {
                        "id": plan.id,
                        "name": plan.name,
                        "status": plan.status.value,
                    }
                    for plan in draft_plans
                ],
                "links": _normalize_command_links(
                    {
                        "task": _cli_command(f"task show {task_target}"),
                        **{
                            f"plan_{index + 1}": _cli_command(f"plan show {plan.id}")
                            for index, plan in enumerate(draft_plans)
                        },
                    }
                ),
            },
            *next_steps,
        )
        click.echo(json.dumps(payload, default=str))
        raise click.exceptions.Exit(exit_code)

    console.print(f"[red]{error_message}[/red]")
    if draft_plans:
        console.print("[yellow]Blocking draft plans:[/yellow]")
        for plan in draft_plans:
            console.print(f"- {plan.name} ({plan.id})")
    _print_next_steps(*next_steps)
    raise click.exceptions.Exit(exit_code)


async def _run_task_execution_operation(
    *,
    operation,
    task_id: str,
    task_service,
    project_service,
    plan_service,
    output_format: str,
    draft_lock_exit_code: int = 1,
):
    """Execute a task state-changing operation with reusable draft-plan handling."""
    try:
        return await operation()
    except ValueError as exc:
        if "draft" in str(exc).lower():
            await _emit_draft_plan_execution_lock(
                task_id=task_id,
                task_service=task_service,
                project_service=project_service,
                plan_service=plan_service,
                output_format=output_format,
                error_message=str(exc),
                exit_code=draft_lock_exit_code,
            )
            return None
        raise


def _task_list_focus_rank(status_value: str) -> int:
    if status_value == "in_progress":
        return 0
    if status_value == "in_review":
        return 1
    if status_value == "todo":
        return 2
    if status_value == "blocked":
        return 3
    if status_value == "done":
        return 4
    if status_value == "cancelled":
        return 5
    return 6


def _task_list_focus_reason(status_value: str) -> str:
    if status_value == "in_progress":
        return "active execution in progress"
    if status_value == "blocked":
        return "blocked execution needs unblocking"
    if status_value == "in_review":
        return "review-ready work can be closed"
    if status_value == "todo":
        return "next ready work to start"
    if status_value == "done":
        return "most actionable task already completed"
    if status_value == "cancelled":
        return "remaining task is cancelled"
    return "best available task focus"


def _task_terminal_reason(tasks: list[CommandFocusEntry]) -> str | None:
    if not tasks:
        return None
    status_values = [
        task.status.value if isinstance(task.status, TaskStatus) else task.status
        for task in tasks
    ]
    if status_values and all(
        status == TaskStatus.CANCELLED.value for status in status_values
    ):
        return "all surfaced tasks are cancelled"
    if status_values and all(
        status == TaskStatus.DONE.value for status in status_values
    ):
        return "all surfaced tasks are already complete"
    if status_values and all(
        status in {TaskStatus.DONE.value, TaskStatus.CANCELLED.value}
        for status in status_values
    ):
        return "all surfaced tasks are already terminal"
    return None


def _completion_criteria(task_obj) -> list[str]:
    raw_value = task_obj.workflow_metadata.get("completion_criteria")
    if not isinstance(raw_value, list):
        return []
    criteria: list[str] = []
    for item in raw_value:
        if isinstance(item, str):
            normalized = item.strip()
            if normalized:
                criteria.append(normalized)
    return criteria


def _command_focus_payload(
    task_obj, project_name: str | None
) -> dict[str, str | int | None]:
    return {
        "id": task_obj.id,
        "title": task_obj.title,
        "status": task_obj.status.value,
        "project_id": task_obj.project_id,
        "project_name": project_name,
        "current_progress_percent": task_obj.current_progress_percent,
        "reason": _task_list_focus_reason(task_obj.status.value),
    }


def _resolve_command_focus_state(
    tasks: list[CommandFocusEntry],
    project_names: dict[str, str | None],
) -> CommandFocusState:
    if not tasks:
        return CommandFocusState(focus_task=None, terminal_reason=None)
    terminal_reason = _task_terminal_reason(tasks)
    if terminal_reason is not None:
        return CommandFocusState(focus_task=None, terminal_reason=terminal_reason)
    focus_task = min(
        tasks,
        key=lambda task: (
            _task_list_focus_rank(
                task.status.value
                if isinstance(task.status, TaskStatus)
                else task.status
            ),
            -_sort_timestamp(getattr(task, "updated_at", None)),
        ),
    )
    project_name = (
        project_names.get(focus_task.project_id) if focus_task.project_id else None
    )
    status_value = (
        focus_task.status.value
        if isinstance(focus_task.status, TaskStatus)
        else focus_task.status
    )
    return CommandFocusState(
        focus_task=CommandFocusTarget(
            task_id=focus_task.id,
            title=focus_task.title,
            status_value=status_value,
            project_id=focus_task.project_id,
            project_name=project_name,
            current_progress_percent=getattr(
                focus_task, "current_progress_percent", None
            ),
        ),
        terminal_reason=None,
    )


def _select_command_focus(
    tasks: list[CommandFocusEntry],
    project_names: dict[str, str | None],
) -> CommandFocusTarget | None:
    return _resolve_command_focus_state(tasks, project_names).focus_task


async def _tasks_with_latest_progress(
    db,
    task_repo,
    task_ids: list[str],
):
    """Return task snapshots with latest progress-update truth overlaid."""
    tasks = await task_repo.get_by_ids(task_ids) if task_ids else []
    if not tasks:
        return []

    unique_ids = [task.id for task in tasks]
    placeholders = ", ".join("?" * len(unique_ids))
    rows = await db.fetch_all(
        f"""
        SELECT task_id, percent_complete, timestamp
        FROM task_progress_updates
        WHERE task_id IN ({placeholders})
        ORDER BY timestamp DESC
        """,
        tuple(unique_ids),
    )

    latest_progress: dict[str, tuple[int, datetime | None]] = {}
    for row in rows:
        task_id = str(row["task_id"])
        if task_id in latest_progress:
            continue
        timestamp = row["timestamp"]
        if isinstance(timestamp, str):
            timestamp = datetime.fromisoformat(timestamp)
        latest_progress[task_id] = (int(row["percent_complete"] or 0), timestamp)

    for task in tasks:
        latest = latest_progress.get(task.id)
        if latest is None:
            continue
        latest_percent, latest_timestamp = latest
        if latest_timestamp is not None and (
            task.last_progress_update_at is None
            or latest_timestamp >= task.last_progress_update_at
        ):
            task.current_progress_percent = latest_percent
            task.last_progress_update_at = latest_timestamp
            continue
        if latest_percent > task.current_progress_percent:
            task.current_progress_percent = latest_percent
    return tasks


def _digest_summary(digest: Any | None) -> str:
    if digest is None:
        return "-"
    if isinstance(digest, dict):
        tasks_created = digest.get("tasks_created", 0)
        tasks_completed = digest.get("tasks_completed", 0)
        tasks_updated = digest.get("tasks_updated", 0)
    else:
        tasks_created = getattr(digest, "tasks_created", 0)
        tasks_completed = getattr(digest, "tasks_completed", 0)
        tasks_updated = getattr(digest, "tasks_updated", 0)
    return f"+{tasks_created} / done {tasks_completed} / upd {tasks_updated}"


def _next_actions_summary(actions: list[dict[str, Any]] | None) -> str:
    if not actions:
        return "-"
    titles = [action.get("title", "") for action in actions if action.get("title")]
    if not titles:
        return "-"
    preview = ", ".join(titles[:2])
    if len(titles) > 2:
        preview = f"{preview} +{len(titles) - 2}"
    return preview


def _print_task_footer(
    tasks: list[Any], activity_map: dict[str, datetime | None]
) -> None:
    if not tasks:
        return
    status_counts = Counter(task.status.value for task in tasks)
    status_order = ["todo", "in_progress", "in_review", "blocked", "done", "cancelled"]
    count_bits = [
        f"{status} {status_counts.get(status, 0)}"
        for status in status_order
        if status_counts.get(status, 0)
    ]
    if not count_bits:
        count_bits = [f"{status} {count}" for status, count in status_counts.items()]

    latest_task = max(tasks, key=lambda t: activity_map.get(t.id) or t.updated_at)
    latest_time = activity_map.get(latest_task.id) or latest_task.updated_at
    console.print(
        f"[dim]Latest activity: {latest_task.title} "
        f"({latest_task.status.value}) "
        f"{format_relative(latest_time, include_absolute=False)}[/dim]"
    )
    if count_bits:
        console.print(f"[dim]Shown status counts: {', '.join(count_bits)}[/dim]")


def _task_review_section_title(status_value: str) -> str:
    return {
        "in_progress": "In Progress",
        "in_review": "In Review",
        "blocked": "Blocked",
        "todo": "Ready",
        "done": "Recently Done",
        "cancelled": "Cancelled",
    }.get(status_value, status_value.replace("_", " ").title())


def _task_review_status_style(status_value: str) -> str:
    return {
        "todo": "cyan",
        "in_progress": "blue",
        "in_review": "yellow",
        "blocked": "red",
        "done": "green",
        "cancelled": "dim",
    }.get(status_value, "")


def _task_review_section_limit(status_value: str) -> int | None:
    if status_value == "done":
        return 5
    if status_value == "cancelled":
        return 3
    return None


def _task_status_summary_text(tasks: list[Any]) -> str:
    status_counts = Counter(task.status.value for task in tasks)
    return " | ".join(
        f"{status} {status_counts.get(status, 0)}"
        for status in (
            "todo",
            "in_progress",
            "in_review",
            "blocked",
            "done",
            "cancelled",
        )
    )


def _task_review_sort_key(
    task_obj: Any,
    activity_map: dict[str, datetime | None],
) -> tuple[float, str]:
    latest = activity_map.get(task_obj.id) or task_obj.updated_at
    title = getattr(task_obj, "title", "") or ""
    return (-_sort_timestamp(latest), title.lower())


def _task_graph_navigation_payload(
    *,
    task_obj: Any | None,
    project_id: str | None,
    project_name: str | None,
    assignee_map: dict[str, Any],
) -> dict[str, Any]:
    if task_obj is None:
        links = _normalize_command_links(
            {
                "project": (
                    f"project show {project_id} --format json" if project_id else None
                ),
                "tree": (f"task tree --project {project_id}" if project_id else None),
                "review": (
                    f"work review --scope-type project --scope-id {project_id}"
                    if project_id
                    else None
                ),
                "guide": "start --format json",
            }
        )
        commands = _normalize_next_steps(*[value for value in links.values() if value])
        return {
            "basis": "scope",
            "task_id": None,
            "commands": commands,
            "links": links,
        }

    task_target = _best_task_command_target(task_obj.id, task_obj.title, project_name)
    assignee_actor = _task_assignee_actor(task_obj, assignee_map)
    links = _normalize_command_links(
        {
            "show": f"task show {task_target}",
            "graph": f"task graph {task_target}",
            "timeline": f"task timeline {task_target}",
            "plans": f"plan list --task-id {task_obj.id} --format json",
            "evidence": f"task evidence list {task_target}",
            "actor": (
                f"actor show {assignee_actor.handle} --format json"
                if assignee_actor is not None
                else None
            ),
            "project": (
                f"project show {task_obj.project_id} --format json"
                if getattr(task_obj, "project_id", None)
                else None
            ),
            "tree": (
                f"task tree --project {task_obj.project_id}"
                if getattr(task_obj, "project_id", None)
                else None
            ),
            "review": (
                f"work review --scope-type project --scope-id {task_obj.project_id}"
                if getattr(task_obj, "project_id", None)
                else None
            ),
        }
    )
    return {
        "basis": "focus_task",
        "task_id": task_obj.id,
        "commands": _normalize_next_steps(
            *[value for value in links.values() if value]
        ),
        "links": links,
    }


def _print_task_review_view(
    *,
    result: QueryResult[Any],
    tasks: list[Any],
    total_tasks: list[Any],
    title: str = "Task Review",
    project_label: str | None,
    project_id: str | None,
    assignee_actor: Any | None,
    assignee_map: dict[str, Any],
    project_names: dict[str, str | None],
    activity_map: dict[str, datetime | None],
    workflow_transition_map: dict[str, datetime | None],
    status_transition_map: dict[str, datetime | None],
    focus_state: CommandFocusState,
    focus_task_payload: dict[str, Any] | None,
    suppressed_hidden_count: int,
    no_actionable_work: bool,
    scope_summary: str,
) -> None:
    console.print(f"[bold]{title}[/bold]")
    console.print(
        f"Scope: {project_label or 'instance-wide'} | shown {len(tasks)} of {result.total_count}"
    )
    console.print(
        f"Shown summary (current limit/page: {len(tasks)} tasks): "
        f"{_task_status_summary_text(tasks)}"
    )
    console.print(
        f"Total summary (all {len(total_tasks)} matching tasks): "
        f"{_task_status_summary_text(total_tasks)}"
    )
    if assignee_actor is not None:
        console.print(
            f"[dim]Actor filter: {assignee_actor.handle} (direct + inherited memberships)[/dim]"
        )
    if project_id is None and suppressed_hidden_count:
        console.print(
            f"[dim]Suppressed hidden tasks: {suppressed_hidden_count} "
            "(use --include-generated to widen into retained audit/history work)[/dim]"
        )
    if no_actionable_work:
        console.print(f"[dim]{scope_summary}[/dim]")

    if focus_task_payload is not None:
        focus_task = next(
            (task for task in tasks if task.id == focus_task_payload["id"]), None
        )
        if focus_task is not None:
            focus_graph = _task_graph_navigation_payload(
                task_obj=focus_task,
                project_id=project_id,
                project_name=project_label or project_names.get(focus_task.project_id),
                assignee_map=assignee_map,
            )
            focus_style = _task_review_status_style(focus_task.status.value)
            focus_status = (
                f"[{focus_style}]{focus_task.status.value}[/{focus_style}]"
                if focus_style
                else focus_task.status.value
            )
            focus_actor = _task_assignee_actor(focus_task, assignee_map)
            focus_actor_label = (
                focus_actor.handle
                if focus_actor is not None
                else (focus_task.assignee or "-")
            )
            focus_project_label = (
                project_names.get(focus_task.project_id, focus_task.project_id)
                if focus_task.project_id
                else "-"
            )
            focus_last_activity = (
                activity_map.get(focus_task.id) or focus_task.updated_at
            )
            console.print("\n[bold]Focus[/bold]")
            console.print(
                f"- {focus_task.title} | {focus_status} | {focus_task.current_progress_percent}%"
            )
            console.print(
                "  "
                f"ref {focus_task.id[:8]} | "
                f"project {focus_project_label} | "
                f"actor {focus_actor_label} | "
                f"activity {format_relative(focus_last_activity, include_absolute=False)}"
            )
            console.print(f"  why {focus_task_payload['reason']}")
            console.print("  graph walk:")
            for command in focus_graph["commands"]:
                console.print(f"    - {command}")
    elif focus_state.terminal_reason is not None:
        console.print(
            f"\n[bold]Execution State[/bold]\n- {focus_state.terminal_reason}"
        )

    grouped: dict[str, list[Any]] = {
        "in_progress": [],
        "in_review": [],
        "blocked": [],
        "todo": [],
        "done": [],
        "cancelled": [],
    }
    focus_task_id = focus_task_payload["id"] if focus_task_payload is not None else None
    for task_obj in tasks:
        if focus_task_id and task_obj.id == focus_task_id:
            continue
        grouped.setdefault(task_obj.status.value, []).append(task_obj)

    for status_value in (
        "in_progress",
        "in_review",
        "blocked",
        "todo",
        "done",
        "cancelled",
    ):
        group_items = grouped.get(status_value, [])
        if not group_items:
            continue
        group_items = sorted(
            group_items,
            key=lambda task_obj: _task_review_sort_key(task_obj, activity_map),
        )
        limit = _task_review_section_limit(status_value)
        visible_items = group_items[:limit] if limit is not None else group_items
        console.print(
            f"\n[bold]{_task_review_section_title(status_value)} ({len(group_items)})[/bold]"
        )
        for task_obj in visible_items:
            status_style = _task_review_status_style(task_obj.status.value)
            status_text = (
                f"[{status_style}]{task_obj.status.value}[/{status_style}]"
                if status_style
                else task_obj.status.value
            )
            assignee_actor_obj = _task_assignee_actor(task_obj, assignee_map)
            actor_label = (
                assignee_actor_obj.handle
                if assignee_actor_obj is not None
                else (task_obj.assignee or "-")
            )
            project_name = (
                project_names.get(task_obj.project_id, task_obj.project_id)
                if task_obj.project_id
                else "-"
            )
            workflow_state = task_obj.current_state if task_obj.workflow_id else "-"
            last_activity = activity_map.get(task_obj.id) or task_obj.updated_at
            last_transition = (
                workflow_transition_map.get(task_obj.id)
                if task_obj.workflow_id
                else status_transition_map.get(task_obj.id)
            )
            console.print(
                f"- {task_obj.title} | {status_text} | {task_obj.current_progress_percent}%"
            )
            console.print(
                "  "
                f"ref {task_obj.id[:8]} | "
                f"project {project_name} | "
                f"actor {actor_label} | "
                f"state {workflow_state} | "
                f"activity {format_relative(last_activity, include_absolute=False)} | "
                f"transition {format_relative(last_transition, include_absolute=False)}"
            )
        if limit is not None and len(group_items) > len(visible_items):
            console.print(
                f"[dim]... {len(group_items) - len(visible_items)} more {_task_review_section_title(status_value).lower()} not shown[/dim]"
            )

    _print_task_footer(tasks, activity_map)


def _command_focus_graph_navigation(
    *,
    focus_task: CommandFocusTarget | None,
    task_lookup: dict[str, Any],
    assignee_map: dict[str, Any],
    project_id: str | None = None,
    project_name: str | None = None,
) -> dict[str, Any]:
    task_obj = task_lookup.get(focus_task.task_id) if focus_task is not None else None
    resolved_project_id = project_id or getattr(task_obj, "project_id", None)
    resolved_project_name = project_name or (
        getattr(task_obj, "project_name", None) if task_obj is not None else None
    )
    return _task_graph_navigation_payload(
        task_obj=task_obj,
        project_id=resolved_project_id,
        project_name=resolved_project_name,
        assignee_map=assignee_map,
    )


def _evidence_summary(evidence: Any | None) -> str:
    if evidence is None:
        return "-"
    if isinstance(evidence, dict):
        total = evidence.get("total_count", 0)
        new = evidence.get("new_count", 0)
    else:
        total = getattr(evidence, "total_count", 0)
        new = getattr(evidence, "new_count", 0)
    return f"{total} total / {new} new"


def _retention_summary(retention: dict[str, Any] | None) -> str:
    if not retention:
        return "-"
    total_runs = retention.get("total_runs", 0)
    total_bytes = retention.get("total_bytes", 0)
    alerts = retention.get("alerts") or []
    alert_count = len(alerts)
    summary = f"{_format_bytes(total_bytes)} / {total_runs} runs"
    if alert_count:
        summary = f"{summary} / {alert_count} alerts"
    return summary


