@claudo.command("import")
@click.argument(
    "input_path",
    required=False,
    type=click.Path(exists=True, dir_okay=False, path_type=Path),
)
@click.option(
    "--source-path",
    default="~/.claude/tasks",
    show_default=True,
    help="Claude task root passed to Claudo when no input file is provided.",
)
@click.option(
    "--claudo-repo",
    type=click.Path(file_okay=False, path_type=Path),
    default=Path("~/repos/claudo"),
    show_default=True,
    help="Claudo repository used for live export.",
)
@click.option(
    "--session", "session_id", help="Restrict live Claudo export to one session."
)
@click.option(
    "--project",
    "project_name",
    help="Import all Claudo sessions into this PMS project name.",
)
@click.option(
    "--project-prefix",
    default="",
    help="Prefix PMS project names created from Claudo project hints.",
)
@click.option(
    "--project-root",
    type=click.Path(exists=True, file_okay=False, path_type=Path),
    help=(
        "Filter the Claudo graph to sessions whose project metadata matches "
        "this repository root before importing."
    ),
)
@click.option("--dry-run", is_flag=True, help="Preview import actions without writing.")
@click.option(
    "--goals/--no-goals",
    "create_goals",
    default=True,
    show_default=True,
    help="Create/update one PMS goal per Claudo session.",
)
@click.option(
    "--plans/--no-plans",
    "create_plans",
    default=True,
    show_default=True,
    help="Create/update one active PMS plan per Claudo session.",
)
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json"]),
    default="text",
    show_default=True,
)
@async_command
async def claudo_import(
    input_path: Path | None,
    source_path: str,
    claudo_repo: Path,
    session_id: str | None,
    project_name: str | None,
    project_prefix: str,
    project_root: Path | None,
    dry_run: bool,
    create_goals: bool,
    create_plans: bool,
    output_format: str,
) -> None:
    """Import a Claudo interchange graph into PMS."""

    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.integrations.claudo import (
        ClaudoImportOptions,
        ClaudoInteropService,
        filter_claudo_graph_for_project,
        load_claudo_graph,
        run_claudo_export,
    )

    if not dry_run:
        _ensure_local_only_runtime_write(
            "pms claudo import",
            output_format=output_format,
        )

    try:
        graph = (
            load_claudo_graph(input_path)
            if input_path is not None
            else run_claudo_export(
                claudo_repo=claudo_repo,
                source_path=source_path,
                session_id=session_id,
            )
        )
        if project_root is not None:
            graph = filter_claudo_graph_for_project(graph, project_root).graph
    except (RuntimeError, ValueError, OSError) as exc:
        _emit_cli_error(str(exc), output_format=output_format)

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        service = ClaudoInteropService(db, event_store, revision_store, metrics)
        result = await service.import_graph(
            graph,
            ClaudoImportOptions(
                dry_run=dry_run,
                project_name=project_name,
                project_prefix=project_prefix,
                create_goals=create_goals,
                create_plans=create_plans,
            ),
        )
    finally:
        await db.disconnect()

    payload = result.to_dict()
    if output_format == "json":
        click.echo(json.dumps(payload, default=str))
        return

    action = "would import" if dry_run else "imported"
    console.print(
        f"[bold]Claudo {action}[/bold] "
        f"{payload['tasks_seen']} tasks, {payload['edges_seen']} dependencies, "
        f"{payload['sessions']} sessions"
    )
    console.print(
        "Projects: "
        f"{payload['projects_created']} created, {payload['projects_reused']} reused"
    )
    console.print(
        "Tasks: "
        f"{payload['tasks_created']} created, {payload['tasks_updated']} updated, "
        f"{payload['tasks_reused']} reused"
    )
    console.print(
        "Dependencies: "
        f"{payload['dependencies_created']} created, "
        f"{payload['dependencies_reused']} reused, "
        f"{payload['dependencies_missing']} missing"
    )
    if payload["warnings"]:
        console.print("[yellow]Warnings:[/yellow]")
        for warning in payload["warnings"][:10]:
            console.print(f"- {warning}")
        if len(payload["warnings"]) > 10:
            console.print(f"- ... {len(payload['warnings']) - 10} more")


@claudo.command("export")
@click.argument("project_ref")
@click.option(
    "-o",
    "--output",
    "output_path",
    type=click.Path(dir_okay=False, path_type=Path),
    help="Write Claudo interchange JSON to this file.",
)
@click.option(
    "--session-id",
    help="Session id to place in the exported Claudo graph.",
)
@click.option(
    "--claudo-repo",
    type=click.Path(file_okay=False, path_type=Path),
    default=Path("~/repos/claudo"),
    show_default=True,
    help="Claudo repository used for optional materialization.",
)
@click.option(
    "--materialize-claude",
    "materialize_dir",
    type=click.Path(file_okay=False, path_type=Path),
    help="Also run Claudo materialize-claude into this staging directory.",
)
@click.option(
    "--overwrite-materialized",
    is_flag=True,
    help="Allow Claudo to replace the materialization output directory.",
)
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json"]),
    default="text",
    show_default=True,
)
@async_command
async def claudo_export(
    project_ref: str,
    output_path: Path | None,
    session_id: str | None,
    claudo_repo: Path,
    materialize_dir: Path | None,
    overwrite_materialized: bool,
    output_format: str,
) -> None:
    """Export a PMS project as Claudo interchange JSON."""

    from tempfile import TemporaryDirectory

    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.integrations.claudo import (
        ClaudoInteropService,
        materialize_claude_export,
        write_claudo_graph,
    )
    from pms.services.project_service import ProjectService

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        project_service = ProjectService(db, event_store, revision_store, metrics)
        project = await project_service.get_project(project_ref)
        if project is None:
            project = await project_service.get_project_by_name(project_ref)
        if project is None:
            _emit_cli_error(
                f"Project '{project_ref}' not found",
                output_format=output_format,
            )

        service = ClaudoInteropService(db, event_store, revision_store, metrics)
        graph_payload = await service.export_project(
            project.id,
            session_id=session_id,
        )
    except (RuntimeError, ValueError, OSError) as exc:
        _emit_cli_error(str(exc), output_format=output_format)
    finally:
        await db.disconnect()

    materialized: dict[str, Any] | None = None
    if output_path is not None:
        write_claudo_graph(graph_payload, output_path)

    if materialize_dir is not None:
        try:
            if output_path is not None:
                graph_path = output_path
                command_result = materialize_claude_export(
                    claudo_repo=claudo_repo,
                    graph_path=graph_path,
                    output_dir=materialize_dir,
                    overwrite=overwrite_materialized,
                )
            else:
                with TemporaryDirectory() as tmpdir:
                    graph_path = Path(tmpdir) / "pms-claudo-export.json"
                    write_claudo_graph(graph_payload, graph_path)
                    command_result = materialize_claude_export(
                        claudo_repo=claudo_repo,
                        graph_path=graph_path,
                        output_dir=materialize_dir,
                        overwrite=overwrite_materialized,
                    )
        except (RuntimeError, OSError) as exc:
            _emit_cli_error(str(exc), output_format=output_format)
        materialized = {
            "output_dir": str(materialize_dir),
            "command": command_result.to_dict(),
        }

    if output_format == "json":
        if output_path is None and materialized is None:
            click.echo(json.dumps(graph_payload, default=str))
            return
        click.echo(
            json.dumps(
                {
                    "output": str(output_path) if output_path else None,
                    "summary": graph_payload.get("summary"),
                    "materialized": materialized,
                },
                default=str,
            )
        )
        return

    summary = graph_payload.get("summary", {})
    console.print(
        "[bold]Claudo export ready[/bold] "
        f"{summary.get('task_count', 0)} tasks, {summary.get('edge_count', 0)} edges"
    )
    if output_path is not None:
        console.print(f"Output: {output_path}")
    else:
        console.print("Use --format json to print the graph or -o to write it.")
    if materialized is not None:
        console.print(f"Materialized: {materialize_dir}")


