@context.command("compact")
@click.option(
    "--reason",
    default="manual_compact",
    show_default=True,
    help="Reason to store with the snapshot",
)
@click.option("-t", "--tag", "tags", multiple=True, help="Tag snapshot (repeatable)")
@click.option(
    "--preserve-project/--clear-project",
    default=True,
    show_default=True,
    help="Preserve active project in the new session",
)
@click.option(
    "--max-items",
    default=20,
    show_default=True,
    help="Max items to include in the snapshot",
)
@async_command
async def context_compact(
    reason: str,
    tags: tuple[str, ...],
    preserve_project: bool,
    max_items: int,
) -> None:
    """Snapshot context and start a new session."""
    from pms.memory import ContextPrimer, get_context_manager, get_knowledge_store

    context_manager = get_context_manager()
    primer = ContextPrimer(context_manager, get_knowledge_store())
    snapshot_id = await primer.compact_and_snapshot(
        reason=reason,
        tags=list(tags) if tags else None,
        preserve_project=preserve_project,
        max_items=max_items,
    )

    if snapshot_id:
        console.print(f"[green]Saved context snapshot:[/green] {snapshot_id}")
    else:
        console.print("[yellow]No context snapshot saved.[/yellow]")

    console.print(f"[dim]New session: {context_manager.get_session_id()}[/dim]")


