async def _resolve_product_id(
    product_ref: str | None,
    product_service,
) -> str | None:
    if not product_ref:
        return None
    product = await product_service.get_product(product_ref)
    if product is None:
        product = await product_service.get_product_by_name(product_ref)
    if product is None:
        result = await product_service.list_products(limit=1000, offset=0)
        product_ids = [item.id for item in result.items]
        matched_id = _unique_prefix_id_match(product_ids, product_ref)
        if matched_id is not None:
            product = await product_service.get_product(matched_id)
        if product is None:
            matched_product = _unique_name_prefix_match(
                product_ref,
                list(result.items),
                get_name=lambda item: item.name,
            )
            if matched_product is not None:
                product = matched_product
    if product is None:
        console.print(f"[red]Product '{product_ref}' not found[/red]")
        _print_next_steps(
            "pms product list",
            "pms product create <name>",
        )
        return None
    return product.id


