async def _resolve_goal_id(
    goal_ref: str | None,
    goal_service,
    *,
    pick: bool = False,
) -> str | None:
    if not goal_ref:
        return None
    goal = await goal_service.get_goal(goal_ref)
    if goal is None:
        result = await goal_service.list_goals(limit=200, offset=0)
        goal_ids = [item.id for item in result.items]
        matched_id = _unique_prefix_id_match(goal_ids, goal_ref)
        if matched_id is not None:
            goal = await goal_service.get_goal(matched_id)
        if goal is None:
            matched_goal = _unique_name_prefix_match(
                goal_ref,
                list(result.items),
                get_name=lambda item: item.name,
            )
            if matched_goal is not None:
                goal = matched_goal
    if goal is None:
        if pick:
            matches = [
                item
                for item in result.items
                if item.name.strip().lower() == goal_ref.strip().lower()
            ]
            if len(matches) == 1:
                return matches[0].id
            if len(matches) > 1:
                table = Table(title="Matching Goals")
                table.add_column("#", justify="right")
                table.add_column("ID", style="cyan")
                table.add_column("Name")
                table.add_column("Status")
                table.add_column("Updated")
                for idx, item in enumerate(matches, start=1):
                    table.add_row(
                        str(idx),
                        item.id,
                        item.name,
                        item.status.value,
                        format_relative(item.updated_at),
                    )
                console.print(table)
                choice = click.prompt(
                    "Pick goal",
                    type=click.IntRange(1, len(matches)),
                )
                return matches[choice - 1].id
        goal = await goal_service.get_goal_by_name(goal_ref)
    if goal is None:
        console.print(f"[red]Goal '{goal_ref}' not found[/red]")
        _print_next_steps(
            "pms goal list",
            "pms goal create <name>",
        )
        return None
    return goal.id


async def _resolve_objective_id(
    objective_ref: str | None,
    goal_ref: str | None,
    goal_service,
    *,
    pick: bool = False,
) -> str | None:
    if not objective_ref:
        return None
    objective = await goal_service.get_objective(objective_ref)
    if objective:
        return objective.id
    result_all = await goal_service.list_objectives(limit=1000, offset=0)
    objective_ids = [item.id for item in result_all.items]
    matched_id = _unique_prefix_id_match(objective_ids, objective_ref)
    if matched_id is not None:
        objective = await goal_service.get_objective(matched_id)
        if objective is not None:
            return objective.id

    if goal_ref:
        goal_id = await _resolve_goal_id(goal_ref, goal_service, pick=pick)
        if goal_id is None:
            return None
        result = await goal_service.list_objectives(
            goal_id=goal_id,
            limit=1000,
            offset=0,
        )
        matches = [item for item in result.items if item.name == objective_ref]
        if not matches:
            matched_objective = _unique_name_prefix_match(
                objective_ref,
                list(result.items),
                get_name=lambda item: item.name,
            )
            if matched_objective is not None:
                return matched_objective.id
        if not matches:
            console.print(
                f"[red]Objective '{objective_ref}' not found in goal '{goal_ref}'[/red]"
            )
            _print_next_steps(
                f'pms objective list --goal "{goal_ref}"',
                f'pms goal show "{goal_ref}"',
            )
            return None
        if len(matches) > 1:
            if pick:
                table = Table(title="Matching Objectives")
