@product.command("create")
@click.argument("name")
@click.option("-d", "--description", help="Product description")
@click.option("-v", "--vision", help="Product vision")
@click.option("--repo", "repository_url", help="Repository URL")
@click.option("--owner", help="Product owner")
@click.option("-t", "--tag", "tags", multiple=True, help="Product tags")
@click.option(
    "--type",
    "product_type",
    default="service",
    help="Product type (default: service)",
)
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json"]),
    default="text",
    show_default=True,
)
@async_command
async def product_create(
    name: str,
    description: str | None,
    vision: str | None,
    repository_url: str | None,
    owner: str | None,
    tags: tuple[str, ...],
    product_type: str,
    output_format: str,
) -> None:
    """Create a new product."""
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.services.actor_service import ActorService
    from pms.services.product_service import ProductService

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)

        service = ProductService(db, event_store, revision_store, metrics)
        actor_service = ActorService(db, event_store, revision_store, metrics)

        product = await service.create_product(
            name=name,
            description=description,
            vision=vision,
            repository_url=repository_url,
            owner=owner,
            tags=list(tags) if tags else None,
            product_type=product_type,
        )

        next_steps = _normalize_next_steps(
            f'pms product show "{product.name}"',
            f'pms product summary "{product.name}"',
            f'pms project create <name> --product "{product.name}"',
        )
        if output_format == "json":
            owner_map = await _resolve_owner_map([product], actor_service)
            payload = _payload_with_normalized_next_steps(
                {
                    "product": _public_entity_payload(product),
                    "ownership": _ownership_payload(product, owner_map),
                    "links": _normalize_command_links(
                        {
                            "self": f"product show {product.id}",
                            "summary": f"product summary {product.id}",
                            "project_create": f'project create <name> --product "{product.name}"',
                            "owner": _ownership_link(product, owner_map),
                        }
                    ),
                },
                *next_steps,
            )
            click.echo(json.dumps(payload, default=str))
            return

        console.print(f"[green]Created product:[/green] {product.name}")
        console.print(f"[dim]ID: {product.id}[/dim]")
        _print_next_steps(*next_steps)
    finally:
        await db.disconnect()


@product.command("list")
@click.option(
    "-s",
    "--status",
    type=click.Choice(["planning", "active", "mature", "sunset", "archived"]),
)
@click.option(
    "-f",
    "--format",
    "fmt",
    type=click.Choice(["table", "json", "csv"]),
    default="table",
)
@click.option(
    "--view",
    type=click.Choice(["overview", "detail", "trace"]),
    default="detail",
    show_default=True,
    help="Output view profile (overview/detail/trace)",
)
@click.option("--include-history", is_flag=True, help="Include history in JSON")
@click.option("--include-linked", is_flag=True, help="Include linked items in JSON")
@click.option(
    "--include-linked-history",
    is_flag=True,
    help="Include history for linked items in JSON",
)
@click.option("--history-limit", type=int, default=20, show_default=True)
@click.option("--linked-limit", type=int, default=20, show_default=True)
@click.option("--limit", type=int, default=100, show_default=True)
@click.option("--offset", type=int, default=0, show_default=True)
@async_command
async def product_list(
    status: str | None,
    fmt: str,
    view: str,
    include_history: bool,
    include_linked: bool,
    include_linked_history: bool,
    history_limit: int,
    linked_limit: int,
    limit: int,
    offset: int,
) -> None:
    """List products."""
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.models import ProductStatus
    from pms.repositories.product_repository import ProductRepository
    from pms.repositories.project_repository import ProjectRepository
    from pms.services.actor_service import ActorService
    from pms.services.product_service import ProductService
    from pms.services.project_service import ProjectService

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)

        service = ProductService(db, event_store, revision_store, metrics)
        project_service = ProjectService(db, event_store, revision_store, metrics)
        product_repo = ProductRepository(db, event_store, revision_store, metrics)
        project_repo = ProjectRepository(db, event_store, revision_store, metrics)
        actor_service = ActorService(db, event_store, revision_store, metrics)

        if view == "trace":
            include_history = True
            include_linked = True
        if include_linked_history:
            include_linked = True
            include_history = True

        status_filter = ProductStatus(status) if status else None
        result = await service.list_products(
            status=status_filter, limit=limit, offset=offset
        )
        first_product = result.items[0] if result.items else None
        if first_product:
            product_label = first_product.name
            next_actions = [
                f'pms product show "{product_label}"',
                f'pms product summary "{product_label}"',
                f'pms project list --product "{product_label}"',
            ]
        else:
            next_actions = ["pms product create <name> --type <type>"]

        match fmt:
            case "json":
                effective_history_limit = history_limit if history_limit > 0 else 1000
                effective_linked_limit = linked_limit if linked_limit > 0 else 1000
                summaries: dict[str, Any] = {}
                if view != "overview" or include_linked:
                    for product in result.items:
                        summaries[product.id] = await service.get_product_summary(
                            product.id
                        )
                owner_map = await _resolve_owner_map(result.items, actor_service)

                def _product_links(product_obj) -> dict[str, str]:
                    return _normalize_command_links(
                        {
                            "self": f"pms product show {product_obj.id}",
                            "summary": f"pms product summary {product_obj.id}",
                            "projects": f"pms project list --product-id {product_obj.id}",
                            "owner": _ownership_link(product_obj, owner_map),
                        }
                    )

                items: list[dict[str, Any]] = []
                for product in result.items:
                    summary = summaries.get(product.id)
                    if view == "overview":
                        payload = {
                            "id": product.id,
                            "name": product.name,
                            "status": product.status.value,
                            "product_type": product.product_type,
                            "owner": product.owner,
                            "ownership": _ownership_payload(product, owner_map),
                            "created_at": _to_iso(product.created_at),
                            "updated_at": _to_iso(product.updated_at),
                            "links": _product_links(product),
                        }
                    else:
                        payload = _public_entity_payload(product)
                        payload["ownership"] = _ownership_payload(product, owner_map)
                        payload["links"] = _product_links(product)
                        if summary and summary.stats:
                            payload["stats"] = summary.stats.to_dict()

                    if include_linked:
                        project_result = await project_repo.get_by_product(
                            product.id, limit=effective_linked_limit, offset=0
                        )
                        project_items = []
                        for project in project_result.items:
                            project_summary = await project_service.get_project_summary(
                                project.id
                            )
                            last_activity = (
                                project_summary.last_activity_at
                                if project_summary
                                else project.updated_at
                            )
                            last_transition = (
                                project_summary.last_transition_at
                                if project_summary
                                else None
                            )
                            project_items.append(
                                {
                                    "id": project.id,
                                    "name": project.name,
                                    "status": project.status.value,
                                    "updated_at": _to_iso(project.updated_at),
                                    "last_activity_at": _to_iso(last_activity),
                                    "last_transition_at": _to_iso(last_transition),
                                    "links": _normalize_command_links(
                                        {
                                            "self": f"pms project show {project.name}",
                                            "summary": (
                                                f"pms project summary {project.id}"
                                            ),
                                        }
                                    ),
                                }
                            )
                        payload["linked"] = {
                            "projects": project_items,
                            "page": {
                                "total_count": project_result.total_count,
                                "limit": project_result.limit,
                                "offset": project_result.offset,
                                "has_more": project_result.has_more,
                                "next_offset": project_result.offset
                                + project_result.limit
                                if project_result.has_more
                                else None,
                            },
                        }

                        if include_linked_history:
                            payload["linked_history"] = {}
                            for project in project_result.items:
                                history = await project_repo.get_history(
                                    project.id, limit=effective_history_limit
                                )
                                payload["linked_history"][project.id] = [
                                    {
                                        "revision_number": rev.revision_number,
                                        "change_type": rev.change_type.value,
                                        "message": rev.message,
                                        "created_by": rev.created_by,
                                        "created_at": rev.created_at,
                                    }
                                    for rev in history
                                ]

                    if include_history:
                        history = await product_repo.get_history(
                            product.id, limit=effective_history_limit
                        )
                        payload["history"] = [
                            {
                                "revision_number": rev.revision_number,
                                "change_type": rev.change_type.value,
                                "message": rev.message,
                                "created_by": rev.created_by,
                                "created_at": rev.created_at,
                            }
                            for rev in history
                        ]

                    items.append(payload)

                base_cmd = "pms product list --format json"
                if status:
                    base_cmd += f" --status {status}"
                if view != "overview":
                    base_cmd += f" --view {view}"
                payload = {
                    "items": items,
                    "page": {
                        "total_count": result.total_count,
                        "limit": result.limit,
                        "offset": result.offset,
                        "has_more": result.has_more,
                        "next_offset": result.offset + result.limit
                        if result.has_more
                        else None,
                    },
                    "links": _normalize_command_links(
                        {
                            "self": f"{base_cmd} --limit {limit} --offset {offset}",
                            "next": (
                                f"{base_cmd} --limit {limit} "
                                f"--offset {result.offset + result.limit}"
                                if result.has_more
                                else None
                            ),
                        }
                    ),
                }
                click.echo(json.dumps(payload, indent=2, default=str))
            case "csv":
                headers = ["id", "name", "status", "product_type", "updated_at"]
                click.echo(_csv_row(headers))
                for p in result.items:
                    row = [
                        p.id,
                        p.name,
                        p.status.value,
                        p.product_type,
                        str(p.updated_at)[:19] if p.updated_at else "",
                    ]
                    click.echo(_csv_row(row))
            case _:
                from pms.utils.time import format_relative

                table = Table(title="Products")
                table.add_column("Name", style="cyan")
                table.add_column("Status")
                table.add_column("Type")
                table.add_column("Updated")
                for p in result.items:
                    table.add_row(
                        p.name,
                        p.status.value,
                        p.product_type,
                        format_relative(p.updated_at),
                    )
                console.print(table)
                console.print(f"[dim]Total: {result.total_count}[/dim]")
                _print_next_steps(*next_actions)
    finally:
        await db.disconnect()


@product.command("show")
@click.argument("product_ref")
@async_command
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json", "csv"]),
    default="text",
    show_default=True,
)
async def product_show(product_ref: str, output_format: str) -> None:
    """Show product details."""
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.services.actor_service import ActorService
    from pms.services.product_service import ProductService

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)

        service = ProductService(db, event_store, revision_store, metrics)
        actor_service = ActorService(db, event_store, revision_store, metrics)
        product = await service.get_product(product_ref)
        if product is None:
            product = await service.get_product_by_name(product_ref)
        if product is None:
            console.print(f"[red]Product '{product_ref}' not found[/red]")
            return

        product_next_steps = _normalize_next_steps(
            f'pms product summary "{product.name}"',
            f'pms project list --product "{product.name}"',
            f'pms project create <name> --product "{product.name}"',
        )
        product_links = _normalize_command_links(
            {
                "self": f"pms product show {product.id}",
                "summary": f"pms product summary {product.id}",
                "projects": f'pms project list --product "{product.name}" --format json',
                "owner": None,
            }
        )
        owner_map = await _resolve_owner_map([product], actor_service)
        product_links["owner"] = _ownership_link(product, owner_map)

        if output_format == "json":
            payload = _public_entity_payload(product)
            payload["ownership"] = _ownership_payload(product, owner_map)
            payload["links"] = product_links
            payload["next_steps"] = product_next_steps
            payload = _payload_with_normalized_next_steps(payload, *product_next_steps)
            click.echo(json.dumps(payload, default=str))
            return

        if output_format == "csv":
            headers = [
                "id",
                "name",
                "status",
                "description",
                "vision",
                "repository_url",
                "owner",
                "product_type",
                "tags",
            ]
            click.echo(_csv_row(headers))
            row = [
                product.id,
                product.name,
                product.status.value,
                product.description or "",
                product.vision or "",
                product.repository_url or "",
                product.owner or "",
                product.product_type,
                ", ".join(product.tags) if product.tags else "",
            ]
            click.echo(_csv_row(row))
            return

        console.print(f"[bold cyan]{product.name}[/bold cyan]")
        console.print(f"[dim]ID: {product.id}[/dim]")
        console.print(f"Status: {product.status.value}")
        if product.description:
            console.print(f"Description: {product.description}")
        if product.vision:
            console.print(f"Vision: {product.vision}")
        if product.repository_url:
            console.print(f"Repo: {product.repository_url}")
        if product.owner:
            console.print(f"Owner: {product.owner}")
        console.print(f"Type: {product.product_type}")
        if product.tags:
            console.print(f"Tags: {', '.join(product.tags)}")
        _print_next_steps(*product_next_steps)
    finally:
        await db.disconnect()


@product.command("update")
@click.argument("product_id")
@click.option("--name", help="New product name")
@click.option("--description", help="New description")
@click.option("--vision", help="New vision")
@click.option("--repo", "repository_url", help="Repository URL")
@click.option("--owner", help="Product owner")
@click.option("--clear-owner", is_flag=True, help="Remove product owner")
@click.option("--type", "product_type", help="Product type")
@click.option(
    "--status",
    type=click.Choice(["planning", "active", "mature", "sunset", "archived"]),
)
@click.option("-t", "--tag", "tags", multiple=True, help="Product tags")
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json"]),
    default="text",
    show_default=True,
)
@async_command
async def product_update(
    product_id: str,
    name: str | None,
    description: str | None,
    vision: str | None,
    repository_url: str | None,
    owner: str | None,
    clear_owner: bool,
    product_type: str | None,
    status: str | None,
    tags: tuple[str, ...],
    output_format: str,
) -> None:
    """Update a product."""
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.models import ProductStatus
    from pms.services.actor_service import ActorService
    from pms.services.product_service import ProductService

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        service = ProductService(db, event_store, revision_store, metrics)
        actor_service = ActorService(db, event_store, revision_store, metrics)

        if clear_owner and owner:
            _emit_cli_error(
                "Use --owner or --clear-owner, not both",
                output_format=output_format,
            )

        status_enum = ProductStatus(status) if status else None
        updated = await service.update_product(
            product_id=product_id,
            name=name,
            description=description,
            vision=vision,
            repository_url=repository_url,
            owner=owner,
            clear_owner=clear_owner,
            product_type=product_type,
            status=status_enum,
            tags=list(tags) if tags else None,
        )

        if updated is None:
            console.print(f"[red]Product '{product_id}' not found[/red]")
            return

        next_steps = _normalize_next_steps(
            f'pms product show "{updated.name}"',
            f'pms product summary "{updated.name}"',
            f'pms project list --product "{updated.name}"',
        )
        if output_format == "json":
            owner_map = await _resolve_owner_map([updated], actor_service)
            payload = _payload_with_normalized_next_steps(
                {
                    "product": _public_entity_payload(updated),
                    "ownership": _ownership_payload(updated, owner_map),
                    "links": _normalize_command_links(
                        {
                            "self": f"product show {updated.id}",
                            "summary": f"product summary {updated.id}",
                            "projects": f'project list --product "{updated.name}" --format json',
                            "owner": _ownership_link(updated, owner_map),
                        }
                    ),
                },
                *next_steps,
            )
            click.echo(json.dumps(payload, default=str))
            return

        console.print(f"[green]Updated product:[/green] {updated.name}")
        _print_next_steps(*next_steps)
    finally:
        await db.disconnect()


