@product.command("summary")
@click.argument("product_ref")
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json", "csv"]),
    default="text",
    show_default=True,
)
@async_command
async def product_summary(product_ref: str, output_format: str) -> None:
    """Show product summary with stats."""
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.services.actor_service import ActorService
    from pms.services.product_service import ProductService

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        service = ProductService(db, event_store, revision_store, metrics)
        actor_service = ActorService(db, event_store, revision_store, metrics)

        product = await service.get_product(product_ref)
        if product is None:
            product = await service.get_product_by_name(product_ref)
        if product is None:
            console.print(f"[red]Product '{product_ref}' not found[/red]")
            return
        summary = await service.get_product_summary(product.id)
        if summary is None:
            console.print(f"[red]Product '{product_ref}' not found[/red]")
            return

        summary_next_steps = _normalize_next_steps(
            f'pms product show "{summary.product.name}"',
            f'pms project list --product "{summary.product.name}"',
            f'pms project create <name> --product "{summary.product.name}"',
        )
        summary_links = _normalize_command_links(
            {
                "self": f"pms product summary {summary.product.id}",
                "show": f"pms product show {summary.product.id}",
                "projects": (
                    f'project list --product "{summary.product.name}" --format json'
                ),
            }
        )
        owner_map = await _resolve_owner_map([summary.product], actor_service)

        if output_format == "json":
            from dataclasses import asdict

            payload = _payload_with_normalized_next_steps(
                {
                    "product": _public_entity_payload(summary.product),
                    "ownership": _ownership_payload(summary.product, owner_map),
                    "health_score": summary.health_score,
                    "stats": asdict(summary.stats) if summary.stats else None,
                    "links": _normalize_command_links(
                        {
                            **summary_links,
                            "owner": _ownership_link(summary.product, owner_map),
                        }
                    ),
                },
                *summary_next_steps,
            )
            click.echo(json.dumps(payload, default=str))
            return

        if output_format == "csv":
            headers = ["product_id", "product_name", "health_score"]
            click.echo(_csv_row(headers))
            row = [
                summary.product.id,
                summary.product.name,
                f"{summary.health_score:.2f}",
            ]
            click.echo(_csv_row(row))
            if summary.stats:
                stat_headers = [
                    "stats_total_projects",
                    "stats_total_tasks",
                    "stats_completed_tasks",
                    "stats_total_complexity_points",
                    "stats_total_goals",
                    "stats_completed_goals",
                    "stats_avg_goal_progress",
                ]
                click.echo(_csv_row(stat_headers))
                stat_row = [
                    str(summary.stats.total_projects),
                    str(summary.stats.total_tasks),
                    str(summary.stats.completed_tasks),
                    str(summary.stats.total_complexity_points),
                    str(summary.stats.total_goals),
                    str(summary.stats.completed_goals),
                    f"{summary.stats.avg_goal_progress:.1f}",
                ]
                click.echo(_csv_row(stat_row))
            return

        console.print(f"[bold cyan]{summary.product.name}[/bold cyan]")
        console.print(f"Health: {summary.health_score:.0%}")
        if summary.stats:
            console.print(
                f"Projects: {summary.stats.total_projects} | "
                f"Tasks: {summary.stats.total_tasks} | "
                f"Completed: {summary.stats.completed_tasks}"
            )
            console.print(f"Complexity: {summary.stats.total_complexity_points} points")
            if summary.stats.total_goals > 0:
                console.print(
                    f"Goals: {summary.stats.completed_goals}/{summary.stats.total_goals} "
                    f"({summary.stats.avg_goal_progress:.1f}% avg)"
                )
        _print_next_steps(*summary_next_steps)
    finally:
        await db.disconnect()


