@team.command("create")
@click.argument("name")
@click.option("--org", "org_ref", help="Organization name or ID")
@click.option("--org-id", help="Organization ID")
@click.option("-d", "--description", help="Team description")
@click.option("--owner", help="Team owner")
@click.option("-m", "--member", "members", multiple=True, help="Member identifier")
@click.option("-t", "--tag", "tags", multiple=True, help="Team tags")
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json"]),
    default="text",
    show_default=True,
)
@async_command
async def team_create(
    name: str,
    org_ref: str | None,
    org_id: str | None,
    description: str | None,
    owner: str | None,
    members: tuple[str, ...],
    tags: tuple[str, ...],
    output_format: str,
) -> None:
    """Create a new team."""
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.services.actor_service import ActorService
    from pms.services.organization_service import OrganizationService
    from pms.services.team_service import TeamService

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        org_service = OrganizationService(db, event_store, revision_store, metrics)
        service = TeamService(db, event_store, revision_store, metrics)
        actor_service = ActorService(db, event_store, revision_store, metrics)

        if org_ref and org_id:
            _emit_cli_error(
                "Use --org or --org-id, not both",
                output_format=output_format,
            )
        resolved_org_id = org_id
        if org_ref:
            resolved_org_id = await _resolve_org_id(org_ref, org_service)
            if resolved_org_id is None:
                return

        team_obj = await service.create_team(
            name=name,
            org_id=resolved_org_id,
            description=description,
            owner=owner,
            members=list(members) if members else None,
            tags=list(tags) if tags else None,
        )

        next_steps = _normalize_next_steps(
            f'pms team show "{team_obj.name}"',
            (
                f'pms team list --org "{org_ref}"'
                if org_ref
                else f"pms team list --org-id {resolved_org_id}"
                if resolved_org_id
                else "pms team list"
            ),
        )
        if output_format == "json":
            identity_actor_map = await _resolve_actor_reference_map(
                [
                    team_obj.owner_id,
                    team_obj.owner,
                    *team_obj.member_ids,
                    *team_obj.members,
                ],
                actor_service,
            )
            payload = _payload_with_normalized_next_steps(
                {
                    "team": _public_entity_payload(team_obj),
                    "ownership": _ownership_payload(team_obj, identity_actor_map),
                    "members": _member_payloads(
                        team_obj.members,
                        identity_actor_map,
                        actor_ids=team_obj.member_ids,
                    ),
                    "links": _normalize_command_links(
                        {
                            "self": f"team show {team_obj.id}",
                            "list": (
                                f'team list --org "{org_ref}" --format json'
                                if org_ref
                                else f"team list --org-id {resolved_org_id} --format json"
                                if resolved_org_id
                                else "team list --format json"
                            ),
                            "owner": _ownership_link(team_obj, identity_actor_map),
                        }
                    ),
                },
                *next_steps,
            )
            click.echo(json.dumps(payload, default=str))
            return

        console.print(f"[green]Created team:[/green] {team_obj.name}")
        console.print(f"[dim]ID: {team_obj.id}[/dim]")
        _print_next_steps(*next_steps)
    finally:
        await db.disconnect()


@team.command("list")
@click.option("--org-id", help="Filter by organization")
@click.option(
    "-s",
    "--status",
    type=click.Choice(["active", "archived"]),
)
@click.option(
    "-f",
    "--format",
    "fmt",
    type=click.Choice(["table", "json", "csv"]),
    default="table",
)
@click.option(
    "--view",
    type=click.Choice(["review", "overview", "detail", "trace"]),
    default="review",
    show_default=True,
    help="Output view profile (review/overview/detail/trace)",
)
@click.option("--include-history", is_flag=True, help="Include history in JSON")
@click.option("--include-linked", is_flag=True, help="Include linked items in JSON")
@click.option(
    "--include-linked-history",
    is_flag=True,
    help="Include history for linked items in JSON",
)
@click.option("--history-limit", type=int, default=20, show_default=True)
@click.option("--linked-limit", type=int, default=20, show_default=True)
@click.option("--limit", type=int, default=100, show_default=True)
@click.option("--offset", type=int, default=0, show_default=True)
@async_command
async def team_list(
    org_id: str | None,
    status: str | None,
    fmt: str,
    view: str,
    include_history: bool,
    include_linked: bool,
    include_linked_history: bool,
    history_limit: int,
    linked_limit: int,
    limit: int,
    offset: int,
) -> None:
    """List teams."""
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.models import TeamStatus
    from pms.repositories.organization_repository import OrganizationRepository
    from pms.repositories.team_repository import TeamRepository
    from pms.services.actor_service import ActorService
    from pms.services.team_service import TeamService

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        service = TeamService(db, event_store, revision_store, metrics)
        team_repo = TeamRepository(db, event_store, revision_store, metrics)
        org_repo = OrganizationRepository(db, event_store, revision_store, metrics)
        actor_service = ActorService(db, event_store, revision_store, metrics)

        if view == "trace":
            include_history = True
            include_linked = True
        if include_linked_history:
            include_linked = True
            include_history = True

        status_filter = TeamStatus(status) if status else None
        result = await service.list_teams(
            status=status_filter, org_id=org_id, limit=limit, offset=offset
        )
        org_names: dict[str, str] = {}
        org_ids = {team.org_id for team in result.items if team.org_id}
        for org_ref in org_ids:
            org_obj = await org_repo.get_by_id(org_ref)
            if org_obj:
                org_names[org_ref] = org_obj.name

        next_actions: list[str] = []
        if result.items:
            first_team = result.items[0]
            next_actions.append(f'pms team show "{first_team.name}"')
            if first_team.org_id:
                org_label = org_names.get(first_team.org_id)
                if org_label:
                    next_actions.append(f'pms team list --org "{org_label}"')
                else:
                    next_actions.append(f"pms team list --org-id {first_team.org_id}")
        else:
            next_actions.append("pms team create <name> --org <name>")

        match fmt:
            case "json":
                effective_history_limit = history_limit if history_limit > 0 else 1000
                items = []
                for team in result.items:
                    org_name = org_names.get(team.org_id) if team.org_id else None
                    identity_actor_map = await _resolve_actor_reference_map(
                        [
                            team.owner_id,
                            team.owner,
                            *team.member_ids,
                            *team.members,
                        ],
                        actor_service,
                    )
                    links = _normalize_command_links(
                        {
                            "self": f"pms team show {team.id}",
                            "org": f"pms org show {team.org_id}"
                            if team.org_id
                            else None,
                            "owner": _ownership_link(team, identity_actor_map),
                        }
                    )
                    if view == "overview":
                        payload = {
                            "id": team.id,
                            "name": team.name,
                            "status": team.status.value,
                            "org_id": team.org_id,
                            "org_name": org_name,
                            "owner": team.owner,
                            "ownership": _ownership_payload(team, identity_actor_map),
                            "members_count": len(team.members),
                            "members": _member_payloads(
                                team.members,
                                identity_actor_map,
                                actor_ids=team.member_ids,
                            ),
                            "created_at": _to_iso(team.created_at),
                            "updated_at": _to_iso(team.updated_at),
                            "links": links,
                        }
                    else:
                        payload = _public_entity_payload(team)
                        payload.update(
                            {
                                "org_name": org_name,
                                "ownership": _ownership_payload(
                                    team, identity_actor_map
                                ),
                                "members": _member_payloads(
                                    team.members,
                                    identity_actor_map,
                                    actor_ids=team.member_ids,
                                ),
                                "links": links,
                            }
                        )

                    if include_linked and team.org_id:
                        org_obj = await org_repo.get_by_id(team.org_id)
                        if org_obj:
                            payload["linked"] = {
                                "organization": {
                                    "id": org_obj.id,
                                    "name": org_obj.name,
                                    "status": org_obj.status.value,
                                    "updated_at": _to_iso(org_obj.updated_at),
                                    "links": _normalize_command_links(
                                        {"self": f"pms org show {org_obj.id}"}
                                    ),
                                }
                            }
                            if include_linked_history:
                                history = await org_repo.get_history(
                                    org_obj.id, limit=effective_history_limit
                                )
                                payload["linked_history"] = {
                                    "organization": [
                                        {
                                            "revision_number": rev.revision_number,
                                            "change_type": rev.change_type.value,
                                            "message": rev.message,
                                            "created_by": rev.created_by,
                                            "created_at": rev.created_at,
                                        }
                                        for rev in history
                                    ]
                                }

                    if include_history:
                        history = await team_repo.get_history(
                            team.id, limit=effective_history_limit
                        )
                        payload["history"] = [
                            {
                                "revision_number": rev.revision_number,
                                "change_type": rev.change_type.value,
                                "message": rev.message,
                                "created_by": rev.created_by,
                                "created_at": rev.created_at,
                            }
                            for rev in history
                        ]

                    items.append(payload)

                base_cmd = "pms team list --format json"
                if org_id:
                    base_cmd += f" --org-id {org_id}"
                if status:
                    base_cmd += f" --status {status}"
                if view != "overview":
                    base_cmd += f" --view {view}"
                payload = {
                    "items": items,
                    "page": {
                        "total_count": result.total_count,
                        "limit": result.limit,
                        "offset": result.offset,
                        "has_more": result.has_more,
                        "next_offset": result.offset + result.limit
                        if result.has_more
                        else None,
                    },
                    "links": _normalize_command_links(
                        {
                            "self": f"{base_cmd} --limit {limit} --offset {offset}",
                            "next": (
                                f"{base_cmd} --limit {limit} "
                                f"--offset {result.offset + result.limit}"
                                if result.has_more
                                else None
                            ),
                        }
                    ),
                }
                click.echo(json.dumps(payload, indent=2, default=str))
            case "csv":
                headers = ["id", "name", "status", "org_id", "members", "updated_at"]
                click.echo(_csv_row(headers))
                for t in result.items:
                    row = [
                        t.id,
                        t.name,
                        t.status.value,
                        t.org_id or "",
                        str(len(t.members)),
                        str(t.updated_at)[:19] if t.updated_at else "",
                    ]
                    click.echo(_csv_row(row))
            case _:
                from pms.utils.time import format_relative

                table = Table(title="Teams")
                table.add_column("Name", style="cyan")
                table.add_column("Status")
                table.add_column("Org")
                table.add_column("Members", justify="right")
                table.add_column("Updated")
                for t in result.items:
                    table.add_row(
                        t.name,
                        t.status.value,
                        org_names.get(t.org_id) if t.org_id else "-",
                        str(len(t.members)),
                        format_relative(t.updated_at),
                    )
                console.print(table)
                console.print(f"[dim]Total: {result.total_count}[/dim]")
                _print_next_steps(*next_actions)
    finally:
        await db.disconnect()


@team.command("show")
@click.argument("team_ref")
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json", "csv"]),
    default="text",
    show_default=True,
)
@click.option(
    "--view",
    type=click.Choice(["overview", "detail", "trace"]),
    default="detail",
    show_default=True,
    help="Output view profile (overview/detail/trace)",
)
@click.option("--include-history", is_flag=True, help="Include history in JSON")
@click.option("--include-linked", is_flag=True, help="Include linked items in JSON")
@click.option(
    "--include-linked-history",
    is_flag=True,
    help="Include history for linked items in JSON",
)
@click.option("--history-limit", type=int, default=20, show_default=True)
@async_command
async def team_show(
    team_ref: str,
    output_format: str,
    view: str,
    include_history: bool,
    include_linked: bool,
    include_linked_history: bool,
    history_limit: int,
) -> None:
    """Show team details."""
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.repositories.organization_repository import OrganizationRepository
    from pms.repositories.team_repository import TeamRepository
    from pms.services.actor_service import ActorService
    from pms.services.team_service import TeamService

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        service = TeamService(db, event_store, revision_store, metrics)
        team_repo = TeamRepository(db, event_store, revision_store, metrics)
        org_repo = OrganizationRepository(db, event_store, revision_store, metrics)
        actor_service = ActorService(db, event_store, revision_store, metrics)

        if view == "trace":
            include_history = True
            include_linked = True
        if include_linked_history:
            include_linked = True
            include_history = True

        team_obj = await service.get_team(team_ref)
        if team_obj is None:
            team_obj = await service.get_team_by_name(team_ref)
        if team_obj is None:
            console.print(f"[red]Team '{team_ref}' not found[/red]")
            return

        org_name = None
        org_obj = None
        if team_obj.org_id:
            org_obj = await org_repo.get_by_id(team_obj.org_id)
            if org_obj:
                org_name = org_obj.name
        identity_actor_map = await _resolve_actor_reference_map(
            [
                team_obj.owner_id,
                team_obj.owner,
                *team_obj.member_ids,
                *team_obj.members,
            ],
            actor_service,
        )

        if output_format == "json":
            links = _normalize_command_links(
                {
                    "self": f"pms team show {team_obj.id}",
                    "org": f"pms org show {team_obj.org_id}"
                    if team_obj.org_id
                    else None,
                    "owner": _ownership_link(team_obj, identity_actor_map),
                }
            )

            if view == "overview":
                payload: dict[str, Any] = {
                    "id": team_obj.id,
                    "name": team_obj.name,
                    "status": team_obj.status.value,
                    "org_id": team_obj.org_id,
                    "org_name": org_name,
                    "owner": team_obj.owner,
                    "ownership": _ownership_payload(team_obj, identity_actor_map),
                    "members_count": len(team_obj.members),
                    "members": _member_payloads(
                        team_obj.members,
                        identity_actor_map,
                        actor_ids=team_obj.member_ids,
                    ),
                    "created_at": _to_iso(team_obj.created_at),
                    "updated_at": _to_iso(team_obj.updated_at),
                    "links": links,
                }
            else:
                payload = _public_entity_payload(team_obj)
                payload.update(
                    {
                        "org_name": org_name,
                        "ownership": _ownership_payload(team_obj, identity_actor_map),
                        "members": _member_payloads(
                            team_obj.members,
                            identity_actor_map,
                            actor_ids=team_obj.member_ids,
                        ),
                        "links": links,
                    }
                )

            if include_linked and org_obj:
                payload["linked"] = {
                    "organization": {
                        "id": org_obj.id,
                        "name": org_obj.name,
                        "status": org_obj.status.value,
                        "updated_at": _to_iso(org_obj.updated_at),
                        "links": _normalize_command_links(
                            {"self": f"pms org show {org_obj.id}"}
                        ),
                    }
                }
                if include_linked_history:
                    history = await org_repo.get_history(
                        org_obj.id, limit=history_limit
                    )
                    payload["linked_history"] = {
                        "organization": [
                            {
                                "revision_number": rev.revision_number,
                                "change_type": rev.change_type.value,
                                "message": rev.message,
                                "created_by": rev.created_by,
                                "created_at": rev.created_at,
                            }
                            for rev in history
                        ]
                    }

            if include_history:
                history = await team_repo.get_history(team_obj.id, limit=history_limit)
                payload["history"] = [
                    {
                        "revision_number": rev.revision_number,
                        "change_type": rev.change_type.value,
                        "message": rev.message,
                        "created_by": rev.created_by,
                        "created_at": rev.created_at,
                    }
                    for rev in history
                ]

            click.echo(json.dumps(payload, indent=2, default=str))
            return

        if output_format == "csv":
            headers = ["id", "name", "status", "org_id", "owner", "members", "tags"]
            click.echo(_csv_row(headers))
            row = [
                team_obj.id,
                team_obj.name,
                team_obj.status.value,
                team_obj.org_id or "",
                team_obj.owner or "",
                ", ".join(team_obj.members) if team_obj.members else "",
                ", ".join(team_obj.tags) if team_obj.tags else "",
            ]
            click.echo(_csv_row(row))
            return

        if view == "overview":
            console.print(f"[bold cyan]{team_obj.name}[/bold cyan]")
            console.print(f"Status: {team_obj.status.value}")
            console.print(f"Members: {len(team_obj.members)}")
            _print_next_steps(
                f'pms team show "{team_obj.name}"',
                (
                    f'pms team list --org "{org_name}"'
                    if org_name
                    else f"pms team list --org-id {team_obj.org_id}"
                    if team_obj.org_id
                    else "pms team list"
                ),
            )
            return

        console.print(f"[bold cyan]{team_obj.name}[/bold cyan]")
        if org_name:
            console.print(f"Org: {org_name} ({team_obj.org_id})")
        else:
            console.print(f"Org: {team_obj.org_id or '-'}")
        console.print(f"Owner: {team_obj.owner or '-'}")
        console.print(
            f"Members: {', '.join(team_obj.members) if team_obj.members else '-'}"
        )
        console.print(f"Tags: {', '.join(team_obj.tags) if team_obj.tags else '-'}")
        _print_next_steps(
            f'pms team show "{team_obj.name}"',
            (
                f'pms team list --org "{org_name}"'
                if org_name
                else f"pms team list --org-id {team_obj.org_id}"
                if team_obj.org_id
                else "pms team list"
            ),
        )
    finally:
        await db.disconnect()


@team.command("update")
@click.argument("team_id")
@click.option("--name", help="New team name")
@click.option("-d", "--description", help="Team description")
@click.option("--status", type=click.Choice(["active", "archived"]))
@click.option("--owner", help="Team owner")
@click.option("--clear-owner", is_flag=True, help="Remove team owner")
@click.option("-m", "--member", "members", multiple=True, help="Member identifier")
@click.option("--clear-members", is_flag=True, help="Clear team members")
@click.option("-t", "--tag", "tags", multiple=True, help="Team tags")
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json"]),
    default="text",
    show_default=True,
)
@async_command
async def team_update(
    team_id: str,
    name: str | None,
    description: str | None,
    status: str | None,
    owner: str | None,
    clear_owner: bool,
    members: tuple[str, ...],
    clear_members: bool,
    tags: tuple[str, ...],
    output_format: str,
) -> None:
    """Update a team."""
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.models import TeamStatus
    from pms.services.actor_service import ActorService
    from pms.services.team_service import TeamService

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        service = TeamService(db, event_store, revision_store, metrics)
        actor_service = ActorService(db, event_store, revision_store, metrics)

        if clear_owner and owner:
            _emit_cli_error(
                "Use --owner or --clear-owner, not both",
                output_format=output_format,
            )
        if clear_members and members:
            _emit_cli_error(
                "Use --member or --clear-members, not both",
                output_format=output_format,
            )

        status_enum = TeamStatus(status) if status else None
        team_obj = await service.update_team(
            team_id=team_id,
            name=name,
            description=description,
            status=status_enum,
            owner=owner,
            clear_owner=clear_owner,
            members=list(members) if members else None,
            clear_members=clear_members,
            tags=list(tags) if tags else None,
        )

        if team_obj is None:
            console.print(f"[red]Team '{team_id}' not found[/red]")
            return

        next_steps = _normalize_next_steps(
            f'pms team show "{team_obj.name}"',
            (
                f"pms team list --org-id {team_obj.org_id}"
                if team_obj.org_id
                else "pms team list"
            ),
        )
        if output_format == "json":
            identity_actor_map = await _resolve_actor_reference_map(
                [
                    team_obj.owner_id,
                    team_obj.owner,
                    *team_obj.member_ids,
                    *team_obj.members,
                ],
                actor_service,
            )
            payload = _payload_with_normalized_next_steps(
                {
                    "team": _public_entity_payload(team_obj),
                    "ownership": _ownership_payload(team_obj, identity_actor_map),
                    "members": _member_payloads(
                        team_obj.members,
                        identity_actor_map,
                        actor_ids=team_obj.member_ids,
                    ),
                    "links": _normalize_command_links(
                        {
                            "self": f"team show {team_obj.id}",
                            "list": (
                                f"team list --org-id {team_obj.org_id} --format json"
                                if team_obj.org_id
                                else "team list --format json"
                            ),
                            "owner": _ownership_link(team_obj, identity_actor_map),
                        }
                    ),
                },
                *next_steps,
            )
            click.echo(json.dumps(payload, default=str))
            return

        console.print(f"[green]Updated team:[/green] {team_obj.name}")
        _print_next_steps(*next_steps)
    finally:
        await db.disconnect()


@cli.group()
def portfolio() -> None:
    """Manage portfolios."""
    pass


@portfolio.command("create")
@click.argument("name")
@click.option("--org", "org_ref", help="Organization name or ID")
@click.option("--org-id", help="Organization ID")
@click.option("-d", "--description", help="Portfolio description")
@click.option("--owner", help="Portfolio owner")
@click.option("--project-id", "project_ids", multiple=True, help="Project IDs")
@click.option("--goal-id", "goal_ids", multiple=True, help="Goal IDs")
@click.option("--objective-id", "objective_ids", multiple=True, help="Objective IDs")
@click.option("-t", "--tag", "tags", multiple=True, help="Portfolio tags")
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json"]),
    default="text",
    show_default=True,
)
@async_command
async def portfolio_create(
    name: str,
    org_ref: str | None,
    org_id: str | None,
    description: str | None,
    owner: str | None,
    project_ids: tuple[str, ...],
    goal_ids: tuple[str, ...],
    objective_ids: tuple[str, ...],
    tags: tuple[str, ...],
    output_format: str,
) -> None:
    """Create a new portfolio."""
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.services.actor_service import ActorService
    from pms.services.organization_service import OrganizationService
    from pms.services.portfolio_service import PortfolioService

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        org_service = OrganizationService(db, event_store, revision_store, metrics)
        service = PortfolioService(db, event_store, revision_store, metrics)
        actor_service = ActorService(db, event_store, revision_store, metrics)

        if org_ref and org_id:
            _emit_cli_error(
                "Use --org or --org-id, not both",
                output_format=output_format,
            )
        resolved_org_id = org_id or await _resolve_org_id(org_ref, org_service)
        if org_ref and resolved_org_id is None:
            return

        portfolio_obj = await service.create_portfolio(
            name=name,
            org_id=resolved_org_id,
            description=description,
            owner=owner,
            project_ids=list(project_ids) if project_ids else None,
            goal_ids=list(goal_ids) if goal_ids else None,
            objective_ids=list(objective_ids) if objective_ids else None,
            tags=list(tags) if tags else None,
        )

        org_label = org_ref
        if not org_label and resolved_org_id:
            org_obj = await org_service.get_organization(resolved_org_id)
            if org_obj:
                org_label = org_obj.name
        next_steps = _normalize_next_steps(
            f'pms portfolio show "{portfolio_obj.name}"',
            (
                f'pms program create <name> --portfolio "{portfolio_obj.name}"'
                + (f' --org "{org_label}"' if org_label else "")
            ),
            (f'pms portfolio dashboard --org "{org_label}"' if org_label else ""),
        )
        if output_format == "json":
            owner_map = await _resolve_owner_map([portfolio_obj], actor_service)
            full_scope_snapshot = await service.get_portfolio_scope_snapshot(
                portfolio_obj.id,
                limit=100000,
                offset=0,
            )
            payload = _payload_with_normalized_next_steps(
                {
                    "portfolio": {
                        **portfolio_obj.to_dict(),
                        **_scope_snapshot_ids(full_scope_snapshot),
                    },
                    "ownership": _ownership_payload(portfolio_obj, owner_map),
                    "links": _normalize_command_links(
                        {
                            "self": f"portfolio show {portfolio_obj.id}",
                            "program_create": (
                                f'program create <name> --portfolio "{portfolio_obj.name}"'
                                + (f' --org "{org_label}"' if org_label else "")
                            ),
                            "dashboard": (
                                f'portfolio dashboard --org "{org_label}"'
                                if org_label
                                else None
                            ),
                            "owner": _ownership_link(portfolio_obj, owner_map),
                        }
                    ),
                },
                *next_steps,
            )
            click.echo(json.dumps(payload, default=str))
            return

        console.print(f"[green]Created portfolio:[/green] {portfolio_obj.name}")
        console.print(f"[dim]ID: {portfolio_obj.id}[/dim]")
        _print_next_steps(*next_steps)
    finally:
        await db.disconnect()


@portfolio.command("list")
@click.option("--org", "org_ref", help="Filter by organization name or ID")
@click.option("--org-id", help="Filter by organization ID")
@click.option(
    "-s",
    "--status",
    type=click.Choice(["active", "archived"]),
)
@click.option(
    "-f",
    "--format",
    "fmt",
    type=click.Choice(["table", "json", "csv"]),
    default="table",
)
@click.option(
    "--view",
    type=click.Choice(["overview", "detail", "trace"]),
    default="overview",
    show_default=True,
    help="Output view profile (overview/detail/trace)",
)
@click.option("--include-history", is_flag=True, help="Include history in JSON")
@click.option("--include-linked", is_flag=True, help="Include linked items in JSON")
@click.option(
    "--include-linked-history",
    is_flag=True,
    help="Include history for linked items in JSON",
)
@click.option("--history-limit", type=int, default=20, show_default=True)
@click.option("--linked-limit", type=int, default=20, show_default=True)
@click.option("--limit", type=int, default=100, show_default=True)
@click.option("--offset", type=int, default=0, show_default=True)
@async_command
async def portfolio_list(
    org_ref: str | None,
    org_id: str | None,
    status: str | None,
    fmt: str,
    view: str,
    include_history: bool,
    include_linked: bool,
    include_linked_history: bool,
    history_limit: int,
    linked_limit: int,
    limit: int,
    offset: int,
) -> None:
    """List portfolios."""
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.models import PortfolioStatus
    from pms.repositories.goal_repository import GoalRepository
    from pms.repositories.objective_repository import ObjectiveRepository
    from pms.repositories.organization_repository import OrganizationRepository
    from pms.repositories.portfolio_repository import PortfolioRepository
    from pms.repositories.program_repository import ProgramRepository
    from pms.repositories.project_repository import ProjectRepository
    from pms.services.actor_service import ActorService
    from pms.services.organization_service import OrganizationService
    from pms.services.portfolio_service import PortfolioService
    from pms.utils.time import format_relative

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        org_service = OrganizationService(db, event_store, revision_store, metrics)
        service = PortfolioService(db, event_store, revision_store, metrics)
        portfolio_repo = PortfolioRepository(db, event_store, revision_store, metrics)
        org_repo = OrganizationRepository(db, event_store, revision_store, metrics)
        project_repo = ProjectRepository(db, event_store, revision_store, metrics)
        goal_repo = GoalRepository(db, event_store, revision_store, metrics)
        objective_repo = ObjectiveRepository(db, event_store, revision_store, metrics)
        program_repo = ProgramRepository(db, event_store, revision_store, metrics)
        actor_service = ActorService(db, event_store, revision_store, metrics)

        if view == "trace":
            include_history = True
            include_linked = True
        if include_linked_history:
            include_linked = True
            include_history = True

        if org_ref and org_id:
            _emit_cli_error(
                "Use --org or --org-id, not both",
                output_format="json" if fmt == "json" else "text",
            )
        resolved_org_id = org_id or await _resolve_org_id(org_ref, org_service)
        if org_ref and resolved_org_id is None:
            return

        status_filter = PortfolioStatus(status) if status else None
        result = await service.list_portfolios(
            status=status_filter,
            org_id=resolved_org_id,
            limit=limit,
            offset=offset,
        )

        summaries: dict[str, Any] = {}
        activity_map: dict[str, datetime | None] = {}
        transition_map: dict[str, datetime | None] = {}
        for portfolio_obj in result.items:
            summary = await service.get_portfolio_summary(portfolio_obj.id)
            summaries[portfolio_obj.id] = summary
            activity_map[portfolio_obj.id] = (
                summary.last_activity_at if summary else portfolio_obj.updated_at
            )
            transition_map[portfolio_obj.id] = (
                summary.last_transition_at if summary else None
            )

        org_names: dict[str, str] = {}
        org_ids = {portfolio.org_id for portfolio in result.items if portfolio.org_id}
        for org_ref in org_ids:
            org_obj = await org_repo.get_by_id(org_ref)
            if org_obj:
                org_names[org_ref] = org_obj.name

        next_actions: list[str] = []
        if result.items:
            first_portfolio = result.items[0]
            next_actions.extend(
                [
                    f'pms portfolio show "{first_portfolio.name}"',
                    f'pms portfolio summary "{first_portfolio.name}"',
                    f'pms program list --portfolio "{first_portfolio.name}"',
                ]
            )
            org_label = (
                org_names.get(first_portfolio.org_id)
                if first_portfolio.org_id
                else None
            )
            if org_label:
                next_actions.append(f'pms portfolio dashboard --org "{org_label}"')
        else:
            next_actions.append("pms portfolio create <name> --org <name>")

        match fmt:
            case "json":
                effective_history_limit = history_limit if history_limit > 0 else 1000
                effective_linked_limit = linked_limit if linked_limit > 0 else 1000

                def _portfolio_links(portfolio_obj) -> dict[str, str]:
                    return _normalize_command_links(
                        {
                            "self": f"pms portfolio show {portfolio_obj.id}",
                            "summary": f"pms portfolio summary {portfolio_obj.id}",
                            "programs": (
                                f"pms program list --portfolio-id {portfolio_obj.id}"
                            ),
                        }
                    )

                items = []
                for portfolio in result.items:
                    summary = summaries.get(portfolio.id)
                    last_activity = activity_map.get(portfolio.id)
                    last_transition = transition_map.get(portfolio.id)
                    org_name = (
                        org_names.get(portfolio.org_id) if portfolio.org_id else None
                    )
                    owner_map = await _resolve_owner_map([portfolio], actor_service)
                    full_scope_snapshot = await service.get_portfolio_scope_snapshot(
                        portfolio.id,
                        limit=100000,
                        offset=0,
                    )
                    if view == "overview":
                        payload = {
                            "id": portfolio.id,
                            "name": portfolio.name,
                            "status": portfolio.status.value,
                            "org_id": portfolio.org_id,
                            "org_name": org_name,
                            "owner": portfolio.owner,
                            "ownership": _ownership_payload(portfolio, owner_map),
                            "created_at": _to_iso(portfolio.created_at),
                            "updated_at": _to_iso(portfolio.updated_at),
                            "last_activity_at": _to_iso(last_activity),
                            "last_transition_at": _to_iso(last_transition),
                            "links": _normalize_command_links(
                                {
                                    **_portfolio_links(portfolio),
                                    "owner": _ownership_link(portfolio, owner_map),
                                }
                            ),
                        }
                    else:
                        payload = _public_entity_payload(portfolio)
                        payload.update(
                            {
                                **_scope_snapshot_ids(full_scope_snapshot),
                                "org_name": org_name,
                                "ownership": _ownership_payload(portfolio, owner_map),
                                "last_activity_at": _to_iso(last_activity),
                                "last_transition_at": _to_iso(last_transition),
                                "risk_level": summary.risk_level if summary else None,
                                "links": _normalize_command_links(
                                    {
                                        **_portfolio_links(portfolio),
                                        "owner": _ownership_link(portfolio, owner_map),
                                    }
                                ),
                            }
                        )
                        if summary and summary.stats:
                            payload["stats"] = summary.stats.to_dict()

                    if include_linked:
                        linked_scope_snapshot = (
                            await service.get_portfolio_scope_snapshot(
                                portfolio.id,
                                limit=effective_linked_limit,
                                offset=0,
                            )
                        )
                        programs_result = await program_repo.get_by_portfolio(
                            portfolio.id, limit=effective_linked_limit, offset=0
                        )

                        payload["linked"] = {
                            **_scope_linked_payload(linked_scope_snapshot),
                            "programs": [
                                {
                                    "id": program.id,
                                    "name": program.name,
                                    "status": program.status.value,
                                    "updated_at": _to_iso(program.updated_at),
                                    "links": _normalize_command_links(
                                        {"self": f"pms program show {program.id}"}
                                    ),
                                }
                                for program in programs_result.items
                            ],
                            "page": {
                                **_scope_linked_page_payload(linked_scope_snapshot),
                                "programs": {
                                    "total_count": programs_result.total_count,
                                    "limit": programs_result.limit,
                                    "offset": programs_result.offset,
                                    "has_more": programs_result.has_more,
                                    "next_offset": programs_result.offset
                                    + programs_result.limit
                                    if programs_result.has_more
                                    else None,
                                },
                            },
                        }

                        if include_linked_history:
                            payload["linked_history"] = {
                                "projects": {
                                    project.id: [
                                        {
                                            "revision_number": rev.revision_number,
                                            "change_type": rev.change_type.value,
                                            "message": rev.message,
                                            "created_by": rev.created_by,
                                            "created_at": rev.created_at,
                                        }
                                        for rev in await project_repo.get_history(
                                            project.id, limit=effective_history_limit
                                        )
                                    ]
                                    for project in linked_scope_snapshot.projects.items
                                },
                                "goals": {
                                    goal.id: [
                                        {
                                            "revision_number": rev.revision_number,
                                            "change_type": rev.change_type.value,
                                            "message": rev.message,
                                            "created_by": rev.created_by,
                                            "created_at": rev.created_at,
                                        }
                                        for rev in await goal_repo.get_history(
                                            goal.id, limit=effective_history_limit
                                        )
                                    ]
                                    for goal in linked_scope_snapshot.goals.items
                                },
                                "objectives": {
                                    objective.id: [
                                        {
                                            "revision_number": rev.revision_number,
                                            "change_type": rev.change_type.value,
                                            "message": rev.message,
                                            "created_by": rev.created_by,
                                            "created_at": rev.created_at,
                                        }
                                        for rev in await objective_repo.get_history(
                                            objective.id,
                                            limit=effective_history_limit,
                                        )
                                    ]
                                    for objective in linked_scope_snapshot.objectives.items
                                },
                                "programs": {
                                    program.id: [
                                        {
                                            "revision_number": rev.revision_number,
                                            "change_type": rev.change_type.value,
                                            "message": rev.message,
                                            "created_by": rev.created_by,
                                            "created_at": rev.created_at,
                                        }
                                        for rev in await program_repo.get_history(
                                            program.id, limit=effective_history_limit
                                        )
                                    ]
                                    for program in programs_result.items
                                },
                            }

                    if include_history:
                        history = await portfolio_repo.get_history(
                            portfolio.id, limit=effective_history_limit
                        )
                        payload["history"] = [
                            {
                                "revision_number": rev.revision_number,
                                "change_type": rev.change_type.value,
                                "message": rev.message,
                                "created_by": rev.created_by,
                                "created_at": rev.created_at,
                            }
                            for rev in history
                        ]

                    items.append(payload)

                base_cmd = "pms portfolio list --format json"
                if org_id:
                    base_cmd += f" --org-id {org_id}"
                if status:
                    base_cmd += f" --status {status}"
                if view != "overview":
                    base_cmd += f" --view {view}"
                payload = {
                    "items": items,
                    "page": {
                        "total_count": result.total_count,
                        "limit": result.limit,
                        "offset": result.offset,
                        "has_more": result.has_more,
                        "next_offset": result.offset + result.limit
                        if result.has_more
                        else None,
                    },
                    "links": _normalize_command_links(
                        {
                            "self": f"{base_cmd} --limit {limit} --offset {offset}",
                            "next": (
                                f"{base_cmd} --limit {limit} "
                                f"--offset {result.offset + result.limit}"
                                if result.has_more
                                else None
                            ),
                        }
                    ),
                }
                click.echo(json.dumps(payload, indent=2, default=str))
            case "csv":
                headers = [
                    "id",
                    "name",
                    "status",
                    "org_id",
                    "projects",
                    "goals",
                    "objectives",
                    "last_activity_at",
                ]
                click.echo(_csv_row(headers))
                for p in result.items:
                    last_activity = activity_map.get(p.id)
                    summary = summaries.get(p.id)
                    row = [
                        p.id,
                        p.name,
                        p.status.value,
                        p.org_id or "",
                        str(
                            summary.stats.total_projects
                            if summary
                            else len(p.project_ids)
                        ),
                        str(
                            summary.stats.total_goals
                            if summary
                            else len(p.effective_goal_ids)
                        ),
                        str(
                            summary.stats.total_objectives
                            if summary
                            else len(p.effective_objective_ids)
                        ),
                        _to_iso(last_activity) or "",
                    ]
                    click.echo(_csv_row(row))
            case _:
                table = Table(title="Portfolios")
                table.add_column("Name", style="cyan", overflow="fold", min_width=20)
                table.add_column("Status")
                table.add_column("Org")
                table.add_column("Projects", justify="right")
                table.add_column("Goals", justify="right")
                table.add_column("Objectives", justify="right")
                table.add_column("Updated")
                for p in result.items:
                    last_activity = activity_map.get(p.id)
                    summary = summaries.get(p.id)
                    table.add_row(
                        p.name,
                        p.status.value,
                        org_names.get(p.org_id) if p.org_id else "-",
                        str(
                            summary.stats.total_projects
                            if summary
                            else len(p.project_ids)
                        ),
                        str(
                            summary.stats.total_goals
                            if summary
                            else len(p.effective_goal_ids)
                        ),
                        str(
                            summary.stats.total_objectives
                            if summary
                            else len(p.effective_objective_ids)
                        ),
                        format_relative(last_activity or p.updated_at),
                    )
                console.print(table)
                console.print(f"[dim]Total: {result.total_count}[/dim]")
                _print_next_steps(*next_actions)
    finally:
        await db.disconnect()


@portfolio.command("show")
@click.argument("portfolio_ref")
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json", "csv"]),
    default="text",
    show_default=True,
)
@click.option(
    "--view",
    type=click.Choice(["overview", "detail", "trace"]),
    default="detail",
    show_default=True,
    help="Output view profile (overview/detail/trace)",
)
@click.option("--include-history", is_flag=True, help="Include history in JSON")
@click.option("--include-linked", is_flag=True, help="Include linked items in JSON")
@click.option(
    "--include-linked-history",
    is_flag=True,
    help="Include history for linked items in JSON",
)
@click.option("--history-limit", type=int, default=20, show_default=True)
@click.option("--linked-limit", type=int, default=20, show_default=True)
@async_command
async def portfolio_show(
    portfolio_ref: str,
    output_format: str,
    view: str,
    include_history: bool,
    include_linked: bool,
    include_linked_history: bool,
    history_limit: int,
    linked_limit: int,
) -> None:
    """Show portfolio details."""
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.repositories.goal_repository import GoalRepository
    from pms.repositories.objective_repository import ObjectiveRepository
    from pms.repositories.organization_repository import OrganizationRepository
    from pms.repositories.portfolio_repository import PortfolioRepository
    from pms.repositories.program_repository import ProgramRepository
    from pms.repositories.project_repository import ProjectRepository
    from pms.services.actor_service import ActorService
    from pms.services.portfolio_service import PortfolioService

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        service = PortfolioService(db, event_store, revision_store, metrics)
        portfolio_repo = PortfolioRepository(db, event_store, revision_store, metrics)
        org_repo = OrganizationRepository(db, event_store, revision_store, metrics)
        project_repo = ProjectRepository(db, event_store, revision_store, metrics)
        goal_repo = GoalRepository(db, event_store, revision_store, metrics)
        objective_repo = ObjectiveRepository(db, event_store, revision_store, metrics)
        program_repo = ProgramRepository(db, event_store, revision_store, metrics)
        actor_service = ActorService(db, event_store, revision_store, metrics)

        if view == "trace":
            include_history = True
            include_linked = True
        if include_linked_history:
            include_linked = True
            include_history = True

        portfolio_id = await _resolve_portfolio_id(portfolio_ref, service)
        if portfolio_id is None:
            return
        portfolio_obj = await service.get_portfolio(portfolio_id)
        if portfolio_obj is None:
            console.print(f"[red]Portfolio '{portfolio_ref}' not found[/red]")
            return
        summary = await service.get_portfolio_summary(portfolio_id)
        last_activity = (
            summary.last_activity_at if summary else portfolio_obj.updated_at
        )
        last_transition = summary.last_transition_at if summary else None
        full_scope_snapshot = await service.get_portfolio_scope_snapshot(
            portfolio_obj.id,
            limit=100000,
            offset=0,
        )
        org_name = None
        if portfolio_obj.org_id:
            org_obj = await org_repo.get_by_id(portfolio_obj.org_id)
            if org_obj:
                org_name = org_obj.name

        links = {
            "self": f"pms portfolio show {portfolio_obj.id}",
            "summary": f"pms portfolio summary {portfolio_obj.id}",
            "programs": f"pms program list --portfolio-id {portfolio_obj.id}",
        }
        owner_map = await _resolve_owner_map([portfolio_obj], actor_service)
        links = _normalize_command_links(links)

        if output_format == "json":
            effective_history_limit = history_limit if history_limit > 0 else 1000
            effective_linked_limit = linked_limit if linked_limit > 0 else 1000

            if view == "overview":
                payload: dict[str, Any] = {
                    "id": portfolio_obj.id,
                    "name": portfolio_obj.name,
                    "status": portfolio_obj.status.value,
                    "org_id": portfolio_obj.org_id,
                    "org_name": org_name,
                    "owner": portfolio_obj.owner,
                    "ownership": _ownership_payload(portfolio_obj, owner_map),
                    "created_at": _to_iso(portfolio_obj.created_at),
                    "updated_at": _to_iso(portfolio_obj.updated_at),
                    "last_activity_at": _to_iso(last_activity),
                    "last_transition_at": _to_iso(last_transition),
                    "links": _normalize_command_links(
                        {
                            **links,
                            "owner": _ownership_link(portfolio_obj, owner_map),
                        }
                    ),
                }
            else:
                payload = _public_entity_payload(portfolio_obj)
                payload.update(
                    {
                        **_scope_snapshot_ids(full_scope_snapshot),
                        "org_name": org_name,
                        "ownership": _ownership_payload(portfolio_obj, owner_map),
                        "last_activity_at": _to_iso(last_activity),
                        "last_transition_at": _to_iso(last_transition),
                        "risk_level": summary.risk_level if summary else None,
                        "links": _normalize_command_links(
                            {
                                **links,
                                "owner": _ownership_link(portfolio_obj, owner_map),
                            }
                        ),
                    }
                )
                if summary and summary.stats:
                    payload["stats"] = summary.stats.to_dict()

            if include_linked:
                linked_scope_snapshot = await service.get_portfolio_scope_snapshot(
                    portfolio_obj.id,
                    limit=effective_linked_limit,
                    offset=0,
                )
                programs_result = await program_repo.get_by_portfolio(
                    portfolio_obj.id, limit=effective_linked_limit, offset=0
                )

                payload["linked"] = {
                    **_scope_linked_payload(linked_scope_snapshot),
                    "programs": [
                        {
                            "id": program.id,
                            "name": program.name,
                            "status": program.status.value,
                            "updated_at": _to_iso(program.updated_at),
                            "links": _normalize_command_links(
                                {"self": f"pms program show {program.id}"}
                            ),
                        }
                        for program in programs_result.items
                    ],
                }

                if include_linked_history:
                    payload["linked_history"] = {
                        "projects": {
                            project.id: [
                                {
                                    "revision_number": rev.revision_number,
                                    "change_type": rev.change_type.value,
                                    "message": rev.message,
                                    "created_by": rev.created_by,
                                    "created_at": rev.created_at,
                                }
                                for rev in await project_repo.get_history(
                                    project.id, limit=effective_history_limit
                                )
                            ]
                            for project in linked_scope_snapshot.projects.items
                        },
                        "goals": {
                            goal.id: [
                                {
                                    "revision_number": rev.revision_number,
                                    "change_type": rev.change_type.value,
                                    "message": rev.message,
                                    "created_by": rev.created_by,
                                    "created_at": rev.created_at,
                                }
                                for rev in await goal_repo.get_history(
                                    goal.id, limit=effective_history_limit
                                )
                            ]
                            for goal in linked_scope_snapshot.goals.items
                        },
                        "objectives": {
                            objective.id: [
                                {
                                    "revision_number": rev.revision_number,
                                    "change_type": rev.change_type.value,
                                    "message": rev.message,
                                    "created_by": rev.created_by,
                                    "created_at": rev.created_at,
                                }
                                for rev in await objective_repo.get_history(
                                    objective.id, limit=effective_history_limit
                                )
                            ]
                            for objective in linked_scope_snapshot.objectives.items
                        },
                        "programs": {
                            program.id: [
                                {
                                    "revision_number": rev.revision_number,
                                    "change_type": rev.change_type.value,
                                    "message": rev.message,
                                    "created_by": rev.created_by,
                                    "created_at": rev.created_at,
                                }
                                for rev in await program_repo.get_history(
                                    program.id, limit=effective_history_limit
                                )
                            ]
                            for program in programs_result.items
                        },
                    }

            if include_history:
                history = await portfolio_repo.get_history(
                    portfolio_obj.id, limit=effective_history_limit
                )
                payload["history"] = [
                    {
                        "revision_number": rev.revision_number,
                        "change_type": rev.change_type.value,
                        "message": rev.message,
                        "created_by": rev.created_by,
                        "created_at": rev.created_at,
                    }
                    for rev in history
                ]

            click.echo(json.dumps(payload, indent=2, default=str))
            return

        if output_format == "csv":
            headers = [
                "id",
                "name",
                "status",
                "org_id",
                "projects",
                "goals",
                "objectives",
                "tags",
                "last_activity_at",
            ]
            click.echo(_csv_row(headers))
            row = [
                portfolio_obj.id,
                portfolio_obj.name,
                portfolio_obj.status.value,
                portfolio_obj.org_id or "",
                ", ".join(_scope_snapshot_ids(full_scope_snapshot)["project_ids"])
                if full_scope_snapshot.projects.items
                else "",
                ", ".join(
                    _scope_snapshot_ids(full_scope_snapshot)["effective_goal_ids"]
                )
                if full_scope_snapshot.goals.items
                else "",
                ", ".join(
                    _scope_snapshot_ids(full_scope_snapshot)["effective_objective_ids"]
                )
                if full_scope_snapshot.objectives.items
                else "",
                ", ".join(portfolio_obj.tags) if portfolio_obj.tags else "",
                _to_iso(last_activity) or "",
            ]
            click.echo(_csv_row(row))
            return

        if view == "overview":
            console.print(f"[bold cyan]{portfolio_obj.name}[/bold cyan]")
            console.print(f"Status: {portfolio_obj.status.value}")
            console.print(f"Org: {org_name or portfolio_obj.org_id or '-'}")
            console.print(f"Last Activity: {format_relative(last_activity)}")
            _print_next_steps(
                f'pms portfolio summary "{portfolio_obj.name}"',
                f'pms program list --portfolio "{portfolio_obj.name}"',
                (f'pms portfolio dashboard --org "{org_name}"' if org_name else ""),
            )
            return

        console.print(f"[bold cyan]{portfolio_obj.name}[/bold cyan]")
        console.print(f"Org: {org_name or portfolio_obj.org_id or '-'}")
        console.print(f"Status: {portfolio_obj.status.value}")
        console.print(f"Projects: {full_scope_snapshot.projects.total_count}")
        console.print(f"Goals: {full_scope_snapshot.goals.total_count}")
        console.print(f"Objectives: {full_scope_snapshot.objectives.total_count}")
        console.print(f"Last Activity: {format_relative(last_activity)}")
        if last_transition:
            console.print(f"Last Transition: {format_relative(last_transition)}")
        if summary:
            console.print(f"Risk: {summary.risk_level}")
        _print_next_steps(
            f'pms portfolio summary "{portfolio_obj.name}"',
            f'pms program list --portfolio "{portfolio_obj.name}"',
            (f'pms portfolio dashboard --org "{org_name}"' if org_name else ""),
        )
    finally:
        await db.disconnect()


@portfolio.command("update")
@click.argument("portfolio_id")
@click.option("--name", help="New portfolio name")
@click.option("-d", "--description", help="Portfolio description")
@click.option("--status", type=click.Choice(["active", "archived"]))
@click.option("--owner", help="Portfolio owner")
@click.option("--clear-owner", is_flag=True, help="Remove portfolio owner")
@click.option("--project-id", "project_ids", multiple=True, help="Project IDs")
@click.option("--goal-id", "goal_ids", multiple=True, help="Goal IDs")
@click.option("--objective-id", "objective_ids", multiple=True, help="Objective IDs")
@click.option("-t", "--tag", "tags", multiple=True, help="Portfolio tags")
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json"]),
    default="text",
    show_default=True,
)
@async_command
async def portfolio_update(
    portfolio_id: str,
    name: str | None,
    description: str | None,
    status: str | None,
    owner: str | None,
    clear_owner: bool,
    project_ids: tuple[str, ...],
    goal_ids: tuple[str, ...],
    objective_ids: tuple[str, ...],
    tags: tuple[str, ...],
    output_format: str,
) -> None:
    """Update a portfolio."""
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.models import PortfolioStatus
    from pms.services.actor_service import ActorService
    from pms.services.lineage_service import LineageService
    from pms.services.organization_service import OrganizationService
    from pms.services.portfolio_service import PortfolioService
    from pms.services.program_service import ProgramService
    from pms.services.project_service import ProjectService
    from pms.services.task_service import TaskService
    from pms.services.test_run_retention_service import TestRunRetentionService
    from pms.services.work_snapshot_service import WorkSnapshotService

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        service = PortfolioService(db, event_store, revision_store, metrics)
        actor_service = ActorService(db, event_store, revision_store, metrics)
        project_service = ProjectService(db, event_store, revision_store, metrics)
        program_service = ProgramService(db, event_store, revision_store, metrics)
        org_service = OrganizationService(db, event_store, revision_store, metrics)
        lineage_service = LineageService(db, event_store, revision_store, metrics)
        retention_service = TestRunRetentionService(db, metrics)
        task_service = TaskService(db, event_store, revision_store, metrics)
        snapshot_service = WorkSnapshotService(
            db,
            metrics,
            project_service=project_service,
            organization_service=org_service,
            program_service=program_service,
            portfolio_service=service,
            lineage_service=lineage_service,
            retention_service=retention_service,
        )

        if clear_owner and owner:
            _emit_cli_error(
                "Use --owner or --clear-owner, not both",
                output_format=output_format,
            )

        status_enum = PortfolioStatus(status) if status else None
        portfolio_obj = await service.update_portfolio(
            portfolio_id=portfolio_id,
            name=name,
            description=description,
            status=status_enum,
            owner=owner,
            clear_owner=clear_owner,
            project_ids=list(project_ids) if project_ids else None,
            goal_ids=list(goal_ids) if goal_ids else None,
            objective_ids=list(objective_ids) if objective_ids else None,
            tags=list(tags) if tags else None,
        )

        if portfolio_obj is None:
            console.print(f"[red]Portfolio '{portfolio_id}' not found[/red]")
            return

        next_steps = _normalize_next_steps(
            f'pms portfolio show "{portfolio_obj.name}"',
            f'pms portfolio summary "{portfolio_obj.name}"',
            f'pms program list --portfolio "{portfolio_obj.name}"',
        )
        if output_format == "json":
            owner_map = await _resolve_owner_map([portfolio_obj], actor_service)
            full_scope_snapshot = await service.get_portfolio_scope_snapshot(
                portfolio_obj.id,
                limit=100000,
                offset=0,
            )
            payload = _payload_with_normalized_next_steps(
                {
                    "portfolio": {
                        **portfolio_obj.to_dict(),
                        **_scope_snapshot_ids(full_scope_snapshot),
                    },
                    "ownership": _ownership_payload(portfolio_obj, owner_map),
                    "links": _normalize_command_links(
                        {
                            "self": f"portfolio show {portfolio_obj.id}",
                            "summary": f"portfolio summary {portfolio_obj.id}",
                            "programs": f'program list --portfolio "{portfolio_obj.name}"',
                            "owner": _ownership_link(portfolio_obj, owner_map),
                        }
                    ),
                },
                *next_steps,
            )
            click.echo(json.dumps(payload, default=str))
            return

        console.print(f"[green]Updated portfolio:[/green] {portfolio_obj.name}")
        _print_next_steps(*next_steps)
    finally:
        await db.disconnect()


@portfolio.command("summary")
@click.argument("portfolio_ref")
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json", "csv"]),
    default="text",
    show_default=True,
)
@async_command
async def portfolio_summary(portfolio_ref: str, output_format: str) -> None:
    """Show portfolio summary with rollups."""
    from dataclasses import asdict

    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.services.actor_service import ActorService
    from pms.services.portfolio_service import PortfolioService

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        service = PortfolioService(db, event_store, revision_store, metrics)
        actor_service = ActorService(db, event_store, revision_store, metrics)

        portfolio_id = await _resolve_portfolio_id(portfolio_ref, service)
        if portfolio_id is None:
            return
        summary = await service.get_portfolio_summary(portfolio_id)
        if summary is None:
            console.print(f"[red]Portfolio '{portfolio_ref}' not found[/red]")
            return

        summary_links = _normalize_command_links(
            {
                "self": f"pms portfolio summary {summary.portfolio.id}",
                "show": f"pms portfolio show {summary.portfolio.id}",
                "programs": f"pms program list --portfolio-id {summary.portfolio.id}",
            }
        )
        owner_map = await _resolve_owner_map([summary.portfolio], actor_service)
        summary_next_steps = _normalize_next_steps(
            f'pms portfolio show "{summary.portfolio.name}"',
            f'pms program list --portfolio "{summary.portfolio.name}"',
        )

        if output_format == "json":
            full_scope_snapshot = await service.get_portfolio_scope_snapshot(
                summary.portfolio.id,
                limit=100000,
                offset=0,
            )
            payload = _payload_with_normalized_next_steps(
                {
                    "portfolio": {
                        **summary.portfolio.to_dict(),
                        **_scope_snapshot_ids(full_scope_snapshot),
                    },
                    "ownership": _ownership_payload(summary.portfolio, owner_map),
                    "stats": asdict(summary.stats),
                    "risk_level": summary.risk_level,
                    "links": _normalize_command_links(
                        {
                            **summary_links,
                            "owner": _ownership_link(
                                summary.portfolio,
                                owner_map,
                            ),
                        }
                    ),
                },
                *summary_next_steps,
            )
            click.echo(json.dumps(payload, indent=2, default=str))
            return

        if output_format == "csv":
            headers = [
                "portfolio_id",
                "portfolio_name",
                "total_projects",
                "total_goals",
                "completed_goals",
                "avg_goal_progress",
                "total_tasks",
                "blocked_tasks",
                "risk_level",
            ]
            click.echo(_csv_row(headers))
            row = [
                summary.portfolio.id,
                summary.portfolio.name,
                str(summary.stats.total_projects),
                str(summary.stats.total_goals),
                str(summary.stats.completed_goals),
                f"{summary.stats.avg_goal_progress:.1f}",
                str(summary.stats.total_tasks),
                str(summary.stats.blocked_tasks),
                summary.risk_level,
            ]
            click.echo(_csv_row(row))
            return

        console.print(f"[bold cyan]{summary.portfolio.name}[/bold cyan]")
        console.print(f"Projects: {summary.stats.total_projects}")
        console.print(
            f"Goals: {summary.stats.completed_goals}/{summary.stats.total_goals} "
            f"({summary.stats.avg_goal_progress:.1f}% avg)"
        )
        console.print(
            f"Objectives: {summary.stats.completed_objectives}/{summary.stats.total_objectives} "
            f"({summary.stats.avg_objective_progress:.1f}% avg)"
        )
        console.print(
            f"Tasks blocked: {summary.stats.blocked_tasks}/{summary.stats.total_tasks}"
        )
        console.print(f"Risk: {summary.risk_level}")
    finally:
        await db.disconnect()


@portfolio.command("dashboard")
@click.option("--org", "org_ref", help="Filter by organization name or ID")
@click.option("--org-id", help="Filter by organization ID")
@click.option(
    "-s",
    "--status",
    type=click.Choice(["active", "archived"]),
)
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["table", "json", "csv"]),
    default="table",
    show_default=True,
)
@click.option(
    "--include-digest/--no-digest",
    default=True,
    show_default=True,
    help="Include digest counts since last review",
)
@click.option(
    "--include-next-actions/--no-next-actions",
    default=True,
    show_default=True,
    help="Include ready-task suggestions",
)
@click.option(
    "--include-evidence/--no-evidence",
    default=True,
    show_default=True,
    help="Include evidence totals since last review",
)
@click.option(
    "--include-retention/--no-retention",
    default=True,
    show_default=True,
    help="Include test retention usage",
)
@click.option("--next-limit", type=int, default=3, show_default=True)
@async_command
async def portfolio_dashboard(
    org_ref: str | None,
    org_id: str | None,
    status: str | None,
    output_format: str,
    include_digest: bool,
    include_next_actions: bool,
    include_evidence: bool,
    include_retention: bool,
    next_limit: int,
) -> None:
    """Show portfolio dashboard with rollups."""
    from dataclasses import asdict

    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.models import PortfolioStatus
    from pms.services.lineage_service import LineageService
    from pms.services.organization_service import OrganizationService
    from pms.services.portfolio_service import PortfolioService
    from pms.services.program_service import ProgramService
    from pms.services.project_service import ProjectService
    from pms.services.task_service import TaskService
    from pms.services.test_run_retention_service import TestRunRetentionService
    from pms.services.work_snapshot_service import WorkSnapshotService

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        service = PortfolioService(db, event_store, revision_store, metrics)
        project_service = ProjectService(db, event_store, revision_store, metrics)
        program_service = ProgramService(db, event_store, revision_store, metrics)
        org_service = OrganizationService(db, event_store, revision_store, metrics)
        lineage_service = LineageService(db, event_store, revision_store, metrics)
        retention_service = TestRunRetentionService(db, metrics)
        task_service = TaskService(db, event_store, revision_store, metrics)
        snapshot_service = WorkSnapshotService(
            db,
            metrics,
            project_service=project_service,
            organization_service=org_service,
            program_service=program_service,
            portfolio_service=service,
            lineage_service=lineage_service,
            retention_service=retention_service,
        )

        if org_ref and org_id:
            _emit_cli_error(
                "Use --org or --org-id, not both",
                output_format="json" if fmt == "json" else "text",
            )
        resolved_org_id = org_id or await _resolve_org_id(org_ref, org_service)
        if org_ref and resolved_org_id is None:
            return

        status_filter = PortfolioStatus(status) if status else None
        dashboard = await service.get_portfolio_dashboard(
            status=status_filter, org_id=resolved_org_id
        )

        digest_map: dict[str, Any] = {}
        next_actions_map: dict[str, list[dict[str, Any]]] = {}
        usage_map: dict[str, Any] = {}
        if include_digest:
            for item in dashboard.items:
                digest_result = await snapshot_service.get_digest(
                    "portfolio", item.portfolio.id
                )
                if digest_result:
                    digest_map[item.portfolio.id] = digest_result
        if include_next_actions:
            for item in dashboard.items:
                next_actions_map[
                    item.portfolio.id
                ] = await snapshot_service.get_next_actions(
                    "portfolio",
                    item.portfolio.id,
                    task_service=task_service,
                    project_service=project_service,
                    limit=next_limit,
                )
        if include_evidence or include_retention:
            for item in dashboard.items:
                usage = await snapshot_service.get_usage_summary(
                    "portfolio", item.portfolio.id
                )
                if usage:
                    usage_map[item.portfolio.id] = usage

        org_names: dict[str, str] = {}
        for item in dashboard.items:
            if item.portfolio.org_id and item.portfolio.org_id not in org_names:
                org = await org_service.get_organization(item.portfolio.org_id)
                if org:
                    org_names[item.portfolio.org_id] = org.name

        if output_format == "json":
            payload = {
                "totals": {
                    "total_portfolios": dashboard.total_portfolios,
                    "total_projects": dashboard.total_projects,
                    "total_goals": dashboard.total_goals,
                    "total_objectives": dashboard.total_objectives,
                    "total_tasks": dashboard.total_tasks,
                    "blocked_tasks": dashboard.blocked_tasks,
                },
                "items": [],
            }
            for item in dashboard.items:
                digest_result = digest_map.get(item.portfolio.id)
                usage_result = usage_map.get(item.portfolio.id)
                last_reviewed_at = (
                    digest_result.last_reviewed_at
                    if digest_result
                    else usage_result.last_reviewed_at
                    if usage_result
                    else None
                )
                payload_item = {
                    "portfolio": _public_entity_payload(item.portfolio),
                    "stats": asdict(item.stats),
                    "risk_level": item.risk_level,
                    "last_activity_at": _to_iso(item.last_activity_at),
                    "last_transition_at": _to_iso(item.last_transition_at),
                    "org_name": org_names.get(item.portfolio.org_id)
                    if item.portfolio.org_id
                    else None,
                }
                if include_digest and digest_result:
                    payload_item["last_reviewed_at"] = _to_iso(last_reviewed_at)
                    payload_item["digest"] = digest_result.digest.to_dict()
                if include_next_actions:
                    payload_item["next_actions"] = next_actions_map.get(
                        item.portfolio.id, []
                    )
                if include_evidence and usage_result:
                    payload_item["last_reviewed_at"] = _to_iso(last_reviewed_at)
                    payload_item["evidence"] = usage_result.evidence.to_dict()
                if include_retention:
                    payload_item["retention"] = (
                        usage_result.retention if usage_result else None
                    )
                payload["items"].append(payload_item)
            base_cmd = "pms portfolio dashboard --format json"
            if resolved_org_id:
                base_cmd += f" --org-id {resolved_org_id}"
            if status:
                base_cmd += f" --status {status}"
            if include_digest is False:
                base_cmd += " --no-digest"
            if include_next_actions is False:
                base_cmd += " --no-next-actions"
            if include_evidence is False:
                base_cmd += " --no-evidence"
            if include_retention is False:
                base_cmd += " --no-retention"
            if next_limit != 3:
                base_cmd += f" --next-limit {next_limit}"
            payload["links"] = _normalize_command_links(
                {
                    "self": base_cmd,
                    "programs": (
                        f"program dashboard --org-id {resolved_org_id} --format json"
                        if resolved_org_id
                        else "program dashboard --format json"
                    ),
                    "guide": "start --format json",
                }
            )
            payload = _payload_with_normalized_next_steps(
                payload,
                (
                    f"pms program dashboard --org-id {resolved_org_id} --format json"
                    if resolved_org_id
                    else "pms program dashboard --format json"
                ),
                "pms start --format json",
            )
            click.echo(json.dumps(payload, default=str))
            return

        if output_format == "csv":
            headers = [
                "total_portfolios",
                "total_projects",
                "total_goals",
                "total_objectives",
                "total_tasks",
                "blocked_tasks",
            ]
            click.echo(_csv_row(headers))
            click.echo(
                _csv_row(
                    [
                        str(dashboard.total_portfolios),
                        str(dashboard.total_projects),
                        str(dashboard.total_goals),
                        str(dashboard.total_objectives),
                        str(dashboard.total_tasks),
                        str(dashboard.blocked_tasks),
                    ]
                )
            )
            item_headers = [
                "portfolio_id",
                "portfolio_name",
                "org_id",
                "org_name",
                "projects",
                "goals",
                "objectives",
                "tasks",
                "blocked_tasks",
                "risk_level",
                "last_activity_at",
                "last_transition_at",
            ]
            if include_digest:
                item_headers.extend(
                    [
                        "last_reviewed_at",
                        "digest_tasks_created",
                        "digest_tasks_completed",
                        "digest_tasks_updated",
                        "digest_plans_created",
                        "digest_plans_updated",
                        "digest_test_runs",
                        "digest_failed_test_runs",
                        "digest_evidence_added",
                    ]
                )
            if include_next_actions:
                item_headers.append("next_actions")
            if include_evidence:
                item_headers.extend(
                    [
                        "evidence_total_count",
                        "evidence_new_count",
                    ]
                )
            if include_retention:
                item_headers.extend(
                    [
                        "retention_total_runs",
                        "retention_total_bytes",
                        "retention_log_bytes",
                        "retention_artifact_bytes",
                        "retention_max_log_bytes",
                        "retention_max_artifact_bytes",
                        "retention_alerts",
                    ]
                )
            click.echo(_csv_row(item_headers))
            for item in dashboard.items:
                stats = item.stats
                digest_result = digest_map.get(item.portfolio.id)
                digest_payload = (
                    digest_result.digest.to_dict() if digest_result else None
                )
                usage_result = usage_map.get(item.portfolio.id)
                next_summary = _next_actions_summary(
                    next_actions_map.get(item.portfolio.id)
                )
                row = [
                    item.portfolio.id,
                    item.portfolio.name,
                    item.portfolio.org_id or "",
                    org_names.get(item.portfolio.org_id, "")
                    if item.portfolio.org_id
                    else "",
                    str(stats.total_projects),
                    str(stats.total_goals),
                    str(stats.total_objectives),
                    str(stats.total_tasks),
                    str(stats.blocked_tasks),
                    item.risk_level,
                    _to_iso(item.last_activity_at) or "",
                    _to_iso(item.last_transition_at) or "",
                ]
                if include_digest:
                    row.extend(
                        [
                            _to_iso(digest_result.last_reviewed_at)
                            if digest_result
                            else "",
                            str(digest_payload["tasks_created"])
                            if digest_payload
                            else "",
                            str(digest_payload["tasks_completed"])
                            if digest_payload
                            else "",
                            str(digest_payload["tasks_updated"])
                            if digest_payload
                            else "",
                            str(digest_payload["plans_created"])
                            if digest_payload
                            else "",
                            str(digest_payload["plans_updated"])
                            if digest_payload
                            else "",
                            str(digest_payload["test_runs"]) if digest_payload else "",
                            str(digest_payload["failed_test_runs"])
                            if digest_payload
                            else "",
                            str(digest_payload["evidence_added"])
                            if digest_payload
                            else "",
                        ]
                    )
                if include_next_actions:
                    row.append(next_summary)
                if include_evidence:
                    evidence_payload = (
                        usage_result.evidence.to_dict() if usage_result else {}
                    )
                    row.extend(
                        [
                            str(evidence_payload.get("total_count", 0)),
                            str(evidence_payload.get("new_count", 0)),
                        ]
                    )
                if include_retention:
                    retention_payload = usage_result.retention if usage_result else {}
                    row.extend(
                        [
                            str(retention_payload.get("total_runs", 0)),
                            str(retention_payload.get("total_bytes", 0)),
                            str(retention_payload.get("total_log_bytes_combined", 0)),
                            str(retention_payload.get("total_artifact_bytes", 0)),
                            str(retention_payload.get("max_log_bytes", 0)),
                            str(retention_payload.get("max_artifact_bytes", 0)),
                            str(len(retention_payload.get("alerts") or [])),
                        ]
                    )
                click.echo(_csv_row(row))
            return

        console.print("[bold]Portfolio Dashboard[/bold]")
        console.print("=" * 40)
        console.print(f"Total Portfolios: {dashboard.total_portfolios}")
        console.print(
            f"Projects: {dashboard.total_projects} | Goals: {dashboard.total_goals} | Objectives: {dashboard.total_objectives}"
        )
        console.print(f"Tasks: {dashboard.total_tasks}")
        if dashboard.blocked_tasks > 0:
            console.print(f"Blocked Tasks: [red]{dashboard.blocked_tasks}[/red]")

        if dashboard.items:
            console.print()
            table = Table(title="Portfolios")
            table.add_column("Portfolio", style="cyan")
            table.add_column("Org")
            table.add_column("Projects", justify="right")
            table.add_column("Goals", justify="right")
            table.add_column("Objectives", justify="right")
            table.add_column("Tasks", justify="right")
            table.add_column("Risk")
            table.add_column("Activity")
            table.add_column("Last Transition")
            if include_digest:
                table.add_column("Digest")
            if include_next_actions:
                table.add_column("Next")
            if include_evidence:
                table.add_column("Evidence")
            if include_retention:
                table.add_column("Retention")

            for item in dashboard.items:
                stats = item.stats
                risk_color = {
                    "low": "green",
                    "medium": "yellow",
                    "high": "red",
                }.get(item.risk_level, "white")
                org_label = (
                    org_names.get(item.portfolio.org_id, item.portfolio.org_id)
                    if item.portfolio.org_id
                    else "-"
                )
                row = [
                    item.portfolio.name,
                    org_label,
                    str(stats.total_projects),
                    str(stats.total_goals),
                    str(stats.total_objectives),
                    str(stats.total_tasks),
                    f"[{risk_color}]{item.risk_level}[/{risk_color}]",
                    format_relative(item.last_activity_at),
                    format_relative(item.last_transition_at),
                ]
                if include_digest:
                    digest_result = digest_map.get(item.portfolio.id)
                    row.append(
                        _digest_summary(digest_result.digest if digest_result else None)
                    )
                if include_next_actions:
                    row.append(
                        _truncate(
                            _next_actions_summary(
                                next_actions_map.get(item.portfolio.id)
                            ),
                            32,
                        )
                    )
                if include_evidence:
                    usage_result = usage_map.get(item.portfolio.id)
                    evidence_payload = (
                        usage_result.evidence.to_dict() if usage_result else None
                    )
                    row.append(_evidence_summary(evidence_payload))
                if include_retention:
                    usage_result = usage_map.get(item.portfolio.id)
                    row.append(
                        _truncate(
                            _retention_summary(
                                usage_result.retention if usage_result else None
                            ),
                            26,
                        )
                    )
                table.add_row(*row)

            console.print(table)
    finally:
        await db.disconnect()


@cli.group()
def program() -> None:
    """Manage programs."""
    pass


@program.command("create")
@click.argument("name")
@click.option("--org", "org_ref", help="Organization name or ID")
@click.option("--org-id", help="Organization ID")
@click.option("--portfolio", "portfolio_ref", help="Portfolio name or ID")
@click.option("--portfolio-id", help="Portfolio ID")
@click.option("-d", "--description", help="Program description")
@click.option("--owner", help="Program owner")
@click.option("--project-id", "project_ids", multiple=True, help="Project IDs")
@click.option("--goal-id", "goal_ids", multiple=True, help="Goal IDs")
@click.option("--objective-id", "objective_ids", multiple=True, help="Objective IDs")
@click.option("-t", "--tag", "tags", multiple=True, help="Program tags")
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json"]),
    default="text",
    show_default=True,
)
@async_command
async def program_create(
    name: str,
    org_ref: str | None,
    org_id: str | None,
    portfolio_ref: str | None,
    portfolio_id: str | None,
    description: str | None,
    owner: str | None,
    project_ids: tuple[str, ...],
    goal_ids: tuple[str, ...],
    objective_ids: tuple[str, ...],
    tags: tuple[str, ...],
    output_format: str,
) -> None:
    """Create a new program."""
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.services.actor_service import ActorService
    from pms.services.organization_service import OrganizationService
    from pms.services.portfolio_service import PortfolioService
    from pms.services.program_service import ProgramService

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        org_service = OrganizationService(db, event_store, revision_store, metrics)
        portfolio_service = PortfolioService(db, event_store, revision_store, metrics)
        service = ProgramService(db, event_store, revision_store, metrics)
        actor_service = ActorService(db, event_store, revision_store, metrics)

        if org_ref and org_id:
            _emit_cli_error(
                "Use --org or --org-id, not both",
                output_format=output_format,
            )
        if portfolio_ref and portfolio_id:
            _emit_cli_error(
                "Use --portfolio or --portfolio-id, not both",
                output_format=output_format,
            )
        resolved_org_id = org_id or await _resolve_org_id(org_ref, org_service)
        if org_ref and resolved_org_id is None:
            return
        resolved_portfolio_id = portfolio_id or await _resolve_portfolio_id(
            portfolio_ref, portfolio_service
        )
        if portfolio_ref and resolved_portfolio_id is None:
            return

        program_obj = await service.create_program(
            name=name,
            org_id=resolved_org_id,
            portfolio_id=resolved_portfolio_id,
            description=description,
            owner=owner,
            project_ids=list(project_ids) if project_ids else None,
            goal_ids=list(goal_ids) if goal_ids else None,
            objective_ids=list(objective_ids) if objective_ids else None,
            tags=list(tags) if tags else None,
        )

        org_label = org_ref
        if not org_label and resolved_org_id:
            org_obj = await org_service.get_organization(resolved_org_id)
            if org_obj:
                org_label = org_obj.name
        next_steps = _normalize_next_steps(
            f'pms program show "{program_obj.name}"',
            (f'pms program dashboard --org "{org_label}"' if org_label else ""),
        )
        if output_format == "json":
            owner_map = await _resolve_owner_map([program_obj], actor_service)
            full_scope_snapshot = await service.get_program_scope_snapshot(
                program_obj.id,
                limit=100000,
                offset=0,
            )
            payload = _payload_with_normalized_next_steps(
                {
                    "program": {
                        **program_obj.to_dict(),
                        **_scope_snapshot_ids(full_scope_snapshot),
                    },
                    "ownership": _ownership_payload(program_obj, owner_map),
                    "links": _normalize_command_links(
                        {
                            "self": f"program show {program_obj.id}",
                            "dashboard": (
                                f'program dashboard --org "{org_label}"'
                                if org_label
                                else None
                            ),
                            "owner": _ownership_link(program_obj, owner_map),
                        }
                    ),
                },
                *next_steps,
            )
            click.echo(json.dumps(payload, default=str))
            return

        console.print(f"[green]Created program:[/green] {program_obj.name}")
        console.print(f"[dim]ID: {program_obj.id}[/dim]")
        _print_next_steps(*next_steps)
    finally:
        await db.disconnect()


@program.command("list")
@click.option("--org", "org_ref", help="Filter by organization name or ID")
@click.option("--org-id", help="Filter by organization ID")
@click.option("--portfolio", "portfolio_ref", help="Filter by portfolio name or ID")
@click.option("--portfolio-id", help="Filter by portfolio ID")
@click.option(
    "-s",
    "--status",
    type=click.Choice(["active", "archived"]),
)
@click.option(
    "-f",
    "--format",
    "fmt",
    type=click.Choice(["table", "json", "csv"]),
    default="table",
)
@click.option(
    "--view",
    type=click.Choice(["overview", "detail", "trace"]),
    default="overview",
    show_default=True,
    help="Output view profile (overview/detail/trace)",
)
@click.option("--include-history", is_flag=True, help="Include history in JSON")
@click.option("--include-linked", is_flag=True, help="Include linked items in JSON")
@click.option(
    "--include-linked-history",
    is_flag=True,
    help="Include history for linked items in JSON",
)
@click.option("--history-limit", type=int, default=20, show_default=True)
@click.option("--linked-limit", type=int, default=20, show_default=True)
@click.option("--limit", type=int, default=100, show_default=True)
@click.option("--offset", type=int, default=0, show_default=True)
@async_command
async def program_list(
    org_ref: str | None,
    org_id: str | None,
    portfolio_ref: str | None,
    portfolio_id: str | None,
    status: str | None,
    fmt: str,
    view: str,
    include_history: bool,
    include_linked: bool,
    include_linked_history: bool,
    history_limit: int,
    linked_limit: int,
    limit: int,
    offset: int,
) -> None:
    """List programs."""
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.models import ProgramStatus
    from pms.repositories.goal_repository import GoalRepository
    from pms.repositories.objective_repository import ObjectiveRepository
    from pms.repositories.organization_repository import OrganizationRepository
    from pms.repositories.portfolio_repository import PortfolioRepository
    from pms.repositories.program_repository import ProgramRepository
    from pms.repositories.project_repository import ProjectRepository
    from pms.services.actor_service import ActorService
    from pms.services.organization_service import OrganizationService
    from pms.services.portfolio_service import PortfolioService
    from pms.services.program_service import ProgramService
    from pms.utils.time import format_relative

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        org_service = OrganizationService(db, event_store, revision_store, metrics)
        portfolio_service = PortfolioService(db, event_store, revision_store, metrics)
        service = ProgramService(db, event_store, revision_store, metrics)
        program_repo = ProgramRepository(db, event_store, revision_store, metrics)
        org_repo = OrganizationRepository(db, event_store, revision_store, metrics)
        portfolio_repo = PortfolioRepository(db, event_store, revision_store, metrics)
        project_repo = ProjectRepository(db, event_store, revision_store, metrics)
        goal_repo = GoalRepository(db, event_store, revision_store, metrics)
        objective_repo = ObjectiveRepository(db, event_store, revision_store, metrics)
        actor_service = ActorService(db, event_store, revision_store, metrics)

        if view == "trace":
            include_history = True
            include_linked = True
        if include_linked_history:
            include_linked = True
            include_history = True

        if org_ref and org_id:
            _emit_cli_error(
                "Use --org or --org-id, not both",
                output_format="json" if fmt == "json" else "text",
            )
        if portfolio_ref and portfolio_id:
            _emit_cli_error(
                "Use --portfolio or --portfolio-id, not both",
                output_format="json" if fmt == "json" else "text",
            )
        resolved_org_id = org_id or await _resolve_org_id(org_ref, org_service)
        if org_ref and resolved_org_id is None:
            return
        resolved_portfolio_id = portfolio_id or await _resolve_portfolio_id(
            portfolio_ref, portfolio_service
        )
        if portfolio_ref and resolved_portfolio_id is None:
            return

        status_filter = ProgramStatus(status) if status else None
        result = await service.list_programs(
            status=status_filter,
            org_id=resolved_org_id,
            portfolio_id=resolved_portfolio_id,
            limit=limit,
            offset=offset,
        )

        summaries: dict[str, Any] = {}
        activity_map: dict[str, datetime | None] = {}
        transition_map: dict[str, datetime | None] = {}
        for program_obj in result.items:
            summary = await service.get_program_summary(program_obj.id)
            summaries[program_obj.id] = summary
            activity_map[program_obj.id] = (
                summary.last_activity_at if summary else program_obj.updated_at
            )
            transition_map[program_obj.id] = (
                summary.last_transition_at if summary else None
            )

        org_names: dict[str, str] = {}
        org_ids = {program.org_id for program in result.items if program.org_id}
        for org_ref in org_ids:
            org_obj = await org_repo.get_by_id(org_ref)
            if org_obj:
                org_names[org_ref] = org_obj.name

        portfolio_names: dict[str, str] = {}
        portfolio_ids = {
            program.portfolio_id for program in result.items if program.portfolio_id
        }
        for portfolio_ref in portfolio_ids:
            portfolio_obj = await portfolio_repo.get_by_id(portfolio_ref)
            if portfolio_obj:
                portfolio_names[portfolio_ref] = portfolio_obj.name

        next_actions: list[str] = []
        if result.items:
            first_program = result.items[0]
            next_actions.append(f'pms program show "{first_program.name}"')
            next_actions.append(f'pms program summary "{first_program.name}"')
            org_label = (
                org_names.get(first_program.org_id) if first_program.org_id else None
            )
            if org_label:
                next_actions.append(f'pms program dashboard --org "{org_label}"')
        else:
            next_actions.append("pms program create <name> --org <name>")

        match fmt:
            case "json":
                effective_history_limit = history_limit if history_limit > 0 else 1000
                effective_linked_limit = linked_limit if linked_limit > 0 else 1000

                def _program_links(program_obj) -> dict[str, str]:
                    return _normalize_command_links(
                        {
                            "self": f"pms program show {program_obj.id}",
                            "summary": f"pms program summary {program_obj.id}",
                        }
                    )

                items = []
                for program in result.items:
                    summary = summaries.get(program.id)
                    last_activity = activity_map.get(program.id)
                    last_transition = transition_map.get(program.id)
                    org_name = org_names.get(program.org_id) if program.org_id else None
                    portfolio_name = (
                        portfolio_names.get(program.portfolio_id)
                        if program.portfolio_id
                        else None
                    )
                    owner_map = await _resolve_owner_map([program], actor_service)
                    full_scope_snapshot = await service.get_program_scope_snapshot(
                        program.id,
                        limit=100000,
                        offset=0,
                    )
                    if view == "overview":
                        payload = {
                            "id": program.id,
                            "name": program.name,
                            "status": program.status.value,
                            "org_id": program.org_id,
                            "org_name": org_name,
                            "portfolio_id": program.portfolio_id,
                            "portfolio_name": portfolio_name,
                            "owner": program.owner,
                            "ownership": _ownership_payload(program, owner_map),
                            "created_at": _to_iso(program.created_at),
                            "updated_at": _to_iso(program.updated_at),
                            "last_activity_at": _to_iso(last_activity),
                            "last_transition_at": _to_iso(last_transition),
                            "links": _normalize_command_links(
                                {
                                    **_program_links(program),
                                    "owner": _ownership_link(program, owner_map),
                                }
                            ),
                        }
                    else:
                        payload = _public_entity_payload(program)
                        payload.update(
                            {
                                **_scope_snapshot_ids(full_scope_snapshot),
                                "org_name": org_name,
                                "portfolio_name": portfolio_name,
                                "ownership": _ownership_payload(program, owner_map),
                                "last_activity_at": _to_iso(last_activity),
                                "last_transition_at": _to_iso(last_transition),
                                "risk_level": summary.risk_level if summary else None,
                                "links": _normalize_command_links(
                                    {
                                        **_program_links(program),
                                        "owner": _ownership_link(program, owner_map),
                                    }
                                ),
                            }
                        )
                        if summary and summary.stats:
                            payload["stats"] = summary.stats.to_dict()

                    if include_linked:
                        linked_scope_snapshot = (
                            await service.get_program_scope_snapshot(
                                program.id,
                                limit=effective_linked_limit,
                                offset=0,
                            )
                        )
                        payload["linked"] = {
                            **_scope_linked_payload(linked_scope_snapshot),
                            "page": _scope_linked_page_payload(linked_scope_snapshot),
                        }

                        if include_linked_history:
                            payload["linked_history"] = {
                                "projects": {
                                    project.id: [
                                        {
                                            "revision_number": rev.revision_number,
                                            "change_type": rev.change_type.value,
                                            "message": rev.message,
                                            "created_by": rev.created_by,
                                            "created_at": rev.created_at,
                                        }
                                        for rev in await project_repo.get_history(
                                            project.id, limit=effective_history_limit
                                        )
                                    ]
                                    for project in linked_scope_snapshot.projects.items
                                },
                                "goals": {
                                    goal.id: [
                                        {
                                            "revision_number": rev.revision_number,
                                            "change_type": rev.change_type.value,
                                            "message": rev.message,
                                            "created_by": rev.created_by,
                                            "created_at": rev.created_at,
                                        }
                                        for rev in await goal_repo.get_history(
                                            goal.id, limit=effective_history_limit
                                        )
                                    ]
                                    for goal in linked_scope_snapshot.goals.items
                                },
                                "objectives": {
                                    objective.id: [
                                        {
                                            "revision_number": rev.revision_number,
                                            "change_type": rev.change_type.value,
                                            "message": rev.message,
                                            "created_by": rev.created_by,
                                            "created_at": rev.created_at,
                                        }
                                        for rev in await objective_repo.get_history(
                                            objective.id,
                                            limit=effective_history_limit,
                                        )
                                    ]
                                    for objective in linked_scope_snapshot.objectives.items
                                },
                            }

                    if include_history:
                        history = await program_repo.get_history(
                            program.id, limit=effective_history_limit
                        )
                        payload["history"] = [
                            {
                                "revision_number": rev.revision_number,
                                "change_type": rev.change_type.value,
                                "message": rev.message,
                                "created_by": rev.created_by,
                                "created_at": rev.created_at,
                            }
                            for rev in history
                        ]

                    items.append(payload)

                base_cmd = "pms program list --format json"
                if org_id:
                    base_cmd += f" --org-id {org_id}"
                if portfolio_id:
                    base_cmd += f" --portfolio-id {portfolio_id}"
                if status:
                    base_cmd += f" --status {status}"
                if view != "overview":
                    base_cmd += f" --view {view}"
                payload = {
                    "items": items,
                    "page": {
                        "total_count": result.total_count,
                        "limit": result.limit,
                        "offset": result.offset,
                        "has_more": result.has_more,
                        "next_offset": result.offset + result.limit
                        if result.has_more
                        else None,
                    },
                    "links": _normalize_command_links(
                        {
                            "self": f"{base_cmd} --limit {limit} --offset {offset}",
                            "next": (
                                f"{base_cmd} --limit {limit} "
                                f"--offset {result.offset + result.limit}"
                                if result.has_more
                                else None
                            ),
                        }
                    ),
                }
                click.echo(json.dumps(payload, indent=2, default=str))
            case "csv":
                headers = [
                    "id",
                    "name",
                    "status",
                    "org_id",
                    "portfolio_id",
                    "projects",
                    "goals",
                    "objectives",
                    "last_activity_at",
                ]
                click.echo(_csv_row(headers))
                for p in result.items:
                    last_activity = activity_map.get(p.id)
                    summary = summaries.get(p.id)
                    row = [
                        p.id,
                        p.name,
                        p.status.value,
                        p.org_id or "",
                        p.portfolio_id or "",
                        str(
                            summary.stats.total_projects
                            if summary
                            else len(p.project_ids)
                        ),
                        str(
                            summary.stats.total_goals
                            if summary
                            else len(p.effective_goal_ids)
                        ),
                        str(
                            summary.stats.total_objectives
                            if summary
                            else len(p.effective_objective_ids)
                        ),
                        _to_iso(last_activity) or "",
                    ]
                    click.echo(_csv_row(row))
            case _:
                table = Table(title="Programs")
                table.add_column("Name", style="cyan", overflow="fold", min_width=20)
                table.add_column("Status")
                table.add_column("Org")
                table.add_column("Portfolio")
                table.add_column("Projects", justify="right")
                table.add_column("Goals", justify="right")
                table.add_column("Objectives", justify="right")
                table.add_column("Updated")
                for p in result.items:
                    last_activity = activity_map.get(p.id)
                    summary = summaries.get(p.id)
                    table.add_row(
                        p.name,
                        p.status.value,
                        org_names.get(p.org_id) if p.org_id else "-",
                        portfolio_names.get(p.portfolio_id) if p.portfolio_id else "-",
                        str(
                            summary.stats.total_projects
                            if summary
                            else len(p.project_ids)
                        ),
                        str(
                            summary.stats.total_goals
                            if summary
                            else len(p.effective_goal_ids)
                        ),
                        str(
                            summary.stats.total_objectives
                            if summary
                            else len(p.effective_objective_ids)
                        ),
                        format_relative(last_activity or p.updated_at),
                    )
                console.print(table)
                console.print(f"[dim]Total: {result.total_count}[/dim]")
                _print_next_steps(*next_actions)
    finally:
        await db.disconnect()


@program.command("show")
@click.argument("program_ref")
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json", "csv"]),
    default="text",
    show_default=True,
)
@click.option(
    "--view",
    type=click.Choice(["overview", "detail", "trace"]),
    default="detail",
    show_default=True,
    help="Output view profile (overview/detail/trace)",
)
@click.option("--include-history", is_flag=True, help="Include history in JSON")
@click.option("--include-linked", is_flag=True, help="Include linked items in JSON")
@click.option(
    "--include-linked-history",
    is_flag=True,
    help="Include history for linked items in JSON",
)
@click.option("--history-limit", type=int, default=20, show_default=True)
@click.option("--linked-limit", type=int, default=20, show_default=True)
@async_command
async def program_show(
    program_ref: str,
    output_format: str,
    view: str,
    include_history: bool,
    include_linked: bool,
    include_linked_history: bool,
    history_limit: int,
    linked_limit: int,
) -> None:
    """Show program details."""
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.repositories.goal_repository import GoalRepository
    from pms.repositories.objective_repository import ObjectiveRepository
    from pms.repositories.organization_repository import OrganizationRepository
    from pms.repositories.portfolio_repository import PortfolioRepository
    from pms.repositories.program_repository import ProgramRepository
    from pms.repositories.project_repository import ProjectRepository
    from pms.services.actor_service import ActorService
    from pms.services.program_service import ProgramService

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        service = ProgramService(db, event_store, revision_store, metrics)
        program_repo = ProgramRepository(db, event_store, revision_store, metrics)
        org_repo = OrganizationRepository(db, event_store, revision_store, metrics)
        portfolio_repo = PortfolioRepository(db, event_store, revision_store, metrics)
        project_repo = ProjectRepository(db, event_store, revision_store, metrics)
        goal_repo = GoalRepository(db, event_store, revision_store, metrics)
        objective_repo = ObjectiveRepository(db, event_store, revision_store, metrics)
        actor_service = ActorService(db, event_store, revision_store, metrics)

        if view == "trace":
            include_history = True
            include_linked = True
        if include_linked_history:
            include_linked = True
            include_history = True

        program_obj = await service.get_program(program_ref)
        if program_obj is None:
            program_obj = await service.get_program_by_name(program_ref)
        if program_obj is None:
            console.print(f"[red]Program '{program_ref}' not found[/red]")
            return
        summary = await service.get_program_summary(program_obj.id)
        last_activity = summary.last_activity_at if summary else program_obj.updated_at
        last_transition = summary.last_transition_at if summary else None
        full_scope_snapshot = await service.get_program_scope_snapshot(
            program_obj.id,
            limit=100000,
            offset=0,
        )
        org_name = None
        if program_obj.org_id:
            org_obj = await org_repo.get_by_id(program_obj.org_id)
            if org_obj:
                org_name = org_obj.name
        portfolio_name = None
        if program_obj.portfolio_id:
            portfolio_obj = await portfolio_repo.get_by_id(program_obj.portfolio_id)
            if portfolio_obj:
                portfolio_name = portfolio_obj.name

        links = _normalize_command_links(
            {
                "self": f"pms program show {program_obj.id}",
                "summary": f"pms program summary {program_obj.id}",
            }
        )
        owner_map = await _resolve_owner_map([program_obj], actor_service)

        if output_format == "json":
            effective_history_limit = history_limit if history_limit > 0 else 1000
            effective_linked_limit = linked_limit if linked_limit > 0 else 1000

            if view == "overview":
                payload: dict[str, Any] = {
                    "id": program_obj.id,
                    "name": program_obj.name,
                    "status": program_obj.status.value,
                    "org_id": program_obj.org_id,
                    "org_name": org_name,
                    "portfolio_id": program_obj.portfolio_id,
                    "portfolio_name": portfolio_name,
                    "owner": program_obj.owner,
                    "ownership": _ownership_payload(program_obj, owner_map),
                    "created_at": _to_iso(program_obj.created_at),
                    "updated_at": _to_iso(program_obj.updated_at),
                    "last_activity_at": _to_iso(last_activity),
                    "last_transition_at": _to_iso(last_transition),
                    "links": _normalize_command_links(
                        {
                            **links,
                            "owner": _ownership_link(program_obj, owner_map),
                        }
                    ),
                }
            else:
                payload = _public_entity_payload(program_obj)
                payload.update(
                    {
                        **_scope_snapshot_ids(full_scope_snapshot),
                        "org_name": org_name,
                        "portfolio_name": portfolio_name,
                        "ownership": _ownership_payload(program_obj, owner_map),
                        "last_activity_at": _to_iso(last_activity),
                        "last_transition_at": _to_iso(last_transition),
                        "risk_level": summary.risk_level if summary else None,
                        "links": _normalize_command_links(
                            {
                                **links,
                                "owner": _ownership_link(program_obj, owner_map),
                            }
                        ),
                    }
                )
                if summary and summary.stats:
                    payload["stats"] = summary.stats.to_dict()

            if include_linked:
                linked_scope_snapshot = await service.get_program_scope_snapshot(
                    program_obj.id,
                    limit=effective_linked_limit,
                    offset=0,
                )
                payload["linked"] = _scope_linked_payload(linked_scope_snapshot)

                if include_linked_history:
                    payload["linked_history"] = {
                        "projects": {
                            project.id: [
                                {
                                    "revision_number": rev.revision_number,
                                    "change_type": rev.change_type.value,
                                    "message": rev.message,
                                    "created_by": rev.created_by,
                                    "created_at": rev.created_at,
                                }
                                for rev in await project_repo.get_history(
                                    project.id, limit=effective_history_limit
                                )
                            ]
                            for project in linked_scope_snapshot.projects.items
                        },
                        "goals": {
                            goal.id: [
                                {
                                    "revision_number": rev.revision_number,
                                    "change_type": rev.change_type.value,
                                    "message": rev.message,
                                    "created_by": rev.created_by,
                                    "created_at": rev.created_at,
                                }
                                for rev in await goal_repo.get_history(
                                    goal.id, limit=effective_history_limit
                                )
                            ]
                            for goal in linked_scope_snapshot.goals.items
                        },
                        "objectives": {
                            objective.id: [
                                {
                                    "revision_number": rev.revision_number,
                                    "change_type": rev.change_type.value,
                                    "message": rev.message,
                                    "created_by": rev.created_by,
                                    "created_at": rev.created_at,
                                }
                                for rev in await objective_repo.get_history(
                                    objective.id, limit=effective_history_limit
                                )
                            ]
                            for objective in linked_scope_snapshot.objectives.items
                        },
                    }

            if include_history:
                history = await program_repo.get_history(
                    program_obj.id, limit=effective_history_limit
                )
                payload["history"] = [
                    {
                        "revision_number": rev.revision_number,
                        "change_type": rev.change_type.value,
                        "message": rev.message,
                        "created_by": rev.created_by,
                        "created_at": rev.created_at,
                    }
                    for rev in history
                ]

            click.echo(json.dumps(payload, indent=2, default=str))
            return

        if output_format == "csv":
            headers = [
                "id",
                "name",
                "status",
                "org_id",
                "portfolio_id",
                "projects",
                "goals",
                "objectives",
                "tags",
                "last_activity_at",
            ]
            click.echo(_csv_row(headers))
            row = [
                program_obj.id,
                program_obj.name,
                program_obj.status.value,
                program_obj.org_id or "",
                program_obj.portfolio_id or "",
                ", ".join(_scope_snapshot_ids(full_scope_snapshot)["project_ids"])
                if full_scope_snapshot.projects.items
                else "",
                ", ".join(
                    _scope_snapshot_ids(full_scope_snapshot)["effective_goal_ids"]
                )
                if full_scope_snapshot.goals.items
                else "",
                ", ".join(
                    _scope_snapshot_ids(full_scope_snapshot)["effective_objective_ids"]
                )
                if full_scope_snapshot.objectives.items
                else "",
                ", ".join(program_obj.tags) if program_obj.tags else "",
                _to_iso(last_activity) or "",
            ]
            click.echo(_csv_row(row))
            return

        if view == "overview":
            console.print(f"[bold cyan]{program_obj.name}[/bold cyan]")
            console.print(f"Status: {program_obj.status.value}")
            console.print(f"Org: {org_name or program_obj.org_id or '-'}")
            console.print(
                f"Portfolio: {portfolio_name or program_obj.portfolio_id or '-'}"
            )
            console.print(f"Last Activity: {format_relative(last_activity)}")
            _print_next_steps(
                f'pms program summary "{program_obj.name}"',
                f'pms program dashboard --org "{org_name}"' if org_name else "",
            )
            return

        console.print(f"[bold cyan]{program_obj.name}[/bold cyan]")
        console.print(f"Org: {org_name or program_obj.org_id or '-'}")
        console.print(f"Portfolio: {portfolio_name or program_obj.portfolio_id or '-'}")
        console.print(f"Status: {program_obj.status.value}")
        console.print(f"Projects: {full_scope_snapshot.projects.total_count}")
        console.print(f"Goals: {full_scope_snapshot.goals.total_count}")
        console.print(f"Objectives: {full_scope_snapshot.objectives.total_count}")
        console.print(f"Last Activity: {format_relative(last_activity)}")
        if last_transition:
            console.print(f"Last Transition: {format_relative(last_transition)}")
        if summary:
            console.print(f"Risk: {summary.risk_level}")
        _print_next_steps(
            f'pms program summary "{program_obj.name}"',
            f'pms program dashboard --org "{org_name}"' if org_name else "",
        )
    finally:
        await db.disconnect()


@program.command("update")
@click.argument("program_id")
@click.option("--name", help="New program name")
@click.option("-d", "--description", help="Program description")
@click.option("--status", type=click.Choice(["active", "archived"]))
@click.option("--owner", help="Program owner")
@click.option("--clear-owner", is_flag=True, help="Remove program owner")
@click.option("--project-id", "project_ids", multiple=True, help="Project IDs")
@click.option("--goal-id", "goal_ids", multiple=True, help="Goal IDs")
@click.option("--objective-id", "objective_ids", multiple=True, help="Objective IDs")
@click.option("-t", "--tag", "tags", multiple=True, help="Program tags")
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json"]),
    default="text",
    show_default=True,
)
@async_command
async def program_update(
    program_id: str,
    name: str | None,
    description: str | None,
    status: str | None,
    owner: str | None,
    clear_owner: bool,
    project_ids: tuple[str, ...],
    goal_ids: tuple[str, ...],
    objective_ids: tuple[str, ...],
    tags: tuple[str, ...],
    output_format: str,
) -> None:
    """Update a program."""
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.models import ProgramStatus
    from pms.services.actor_service import ActorService
    from pms.services.lineage_service import LineageService
    from pms.services.organization_service import OrganizationService
    from pms.services.portfolio_service import PortfolioService
    from pms.services.program_service import ProgramService
    from pms.services.project_service import ProjectService
    from pms.services.task_service import TaskService
    from pms.services.test_run_retention_service import TestRunRetentionService
    from pms.services.work_snapshot_service import WorkSnapshotService

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        service = ProgramService(db, event_store, revision_store, metrics)
        actor_service = ActorService(db, event_store, revision_store, metrics)
        project_service = ProjectService(db, event_store, revision_store, metrics)
        org_service = OrganizationService(db, event_store, revision_store, metrics)
        portfolio_service = PortfolioService(db, event_store, revision_store, metrics)
        lineage_service = LineageService(db, event_store, revision_store, metrics)
        retention_service = TestRunRetentionService(db, metrics)
        task_service = TaskService(db, event_store, revision_store, metrics)
        snapshot_service = WorkSnapshotService(
            db,
            metrics,
            project_service=project_service,
            organization_service=org_service,
            program_service=service,
            portfolio_service=portfolio_service,
            lineage_service=lineage_service,
            retention_service=retention_service,
        )

        if clear_owner and owner:
            _emit_cli_error(
                "Use --owner or --clear-owner, not both",
                output_format=output_format,
            )

        status_enum = ProgramStatus(status) if status else None
        program_obj = await service.update_program(
            program_id=program_id,
            name=name,
            description=description,
            status=status_enum,
            owner=owner,
            clear_owner=clear_owner,
            project_ids=list(project_ids) if project_ids else None,
            goal_ids=list(goal_ids) if goal_ids else None,
            objective_ids=list(objective_ids) if objective_ids else None,
            tags=list(tags) if tags else None,
        )

        if program_obj is None:
            console.print(f"[red]Program '{program_id}' not found[/red]")
            return

        next_steps = _normalize_next_steps(
            f'pms program show "{program_obj.name}"',
            f'pms program summary "{program_obj.name}"',
        )
        if output_format == "json":
            owner_map = await _resolve_owner_map([program_obj], actor_service)
            full_scope_snapshot = await service.get_program_scope_snapshot(
                program_obj.id,
                limit=100000,
                offset=0,
            )
            payload = _payload_with_normalized_next_steps(
                {
                    "program": {
                        **program_obj.to_dict(),
                        **_scope_snapshot_ids(full_scope_snapshot),
                    },
                    "ownership": _ownership_payload(program_obj, owner_map),
                    "links": _normalize_command_links(
                        {
                            "self": f"program show {program_obj.id}",
                            "summary": f"program summary {program_obj.id}",
                            "owner": _ownership_link(program_obj, owner_map),
                        }
                    ),
                },
                *next_steps,
            )
            click.echo(json.dumps(payload, default=str))
            return

        console.print(f"[green]Updated program:[/green] {program_obj.name}")
        _print_next_steps(*next_steps)
    finally:
        await db.disconnect()


@program.command("summary")
@click.argument("program_ref")
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json", "csv"]),
    default="text",
    show_default=True,
)
@async_command
async def program_summary(program_ref: str, output_format: str) -> None:
    """Show program summary with rollups."""
    from dataclasses import asdict

    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.services.actor_service import ActorService
    from pms.services.program_service import ProgramService

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        service = ProgramService(db, event_store, revision_store, metrics)
        actor_service = ActorService(db, event_store, revision_store, metrics)

        program_obj = await service.get_program(program_ref)
        if program_obj is None:
            program_obj = await service.get_program_by_name(program_ref)
        if program_obj is None:
            console.print(f"[red]Program '{program_ref}' not found[/red]")
            return
        summary = await service.get_program_summary(program_obj.id)
        if summary is None:
            console.print(f"[red]Program '{program_ref}' not found[/red]")
            return

        summary_links = _normalize_command_links(
            {
                "self": f"pms program summary {summary.program.id}",
                "show": f"pms program show {summary.program.id}",
            }
        )
        owner_map = await _resolve_owner_map([summary.program], actor_service)
        summary_next_steps = _normalize_next_steps(
            f'pms program show "{summary.program.name}"',
        )

        if output_format == "json":
            full_scope_snapshot = await service.get_program_scope_snapshot(
                summary.program.id,
                limit=100000,
                offset=0,
            )
            payload = _payload_with_normalized_next_steps(
                {
                    "program": {
                        **summary.program.to_dict(),
                        **_scope_snapshot_ids(full_scope_snapshot),
                    },
                    "ownership": _ownership_payload(summary.program, owner_map),
                    "stats": asdict(summary.stats),
                    "risk_level": summary.risk_level,
                    "links": _normalize_command_links(
                        {
                            **summary_links,
                            "owner": _ownership_link(summary.program, owner_map),
                        }
                    ),
                },
                *summary_next_steps,
            )
            click.echo(json.dumps(payload, indent=2, default=str))
            return

        if output_format == "csv":
            headers = [
                "program_id",
                "program_name",
                "total_projects",
                "total_goals",
                "completed_goals",
                "avg_goal_progress",
                "total_tasks",
                "blocked_tasks",
                "risk_level",
            ]
            click.echo(_csv_row(headers))
            row = [
                summary.program.id,
                summary.program.name,
                str(summary.stats.total_projects),
                str(summary.stats.total_goals),
                str(summary.stats.completed_goals),
                f"{summary.stats.avg_goal_progress:.1f}",
                str(summary.stats.total_tasks),
                str(summary.stats.blocked_tasks),
                summary.risk_level,
            ]
            click.echo(_csv_row(row))
            return

        console.print(f"[bold cyan]{summary.program.name}[/bold cyan]")
        console.print(f"Projects: {summary.stats.total_projects}")
        console.print(
            f"Goals: {summary.stats.completed_goals}/{summary.stats.total_goals} "
            f"({summary.stats.avg_goal_progress:.1f}% avg)"
        )
        console.print(
            f"Objectives: {summary.stats.completed_objectives}/{summary.stats.total_objectives} "
            f"({summary.stats.avg_objective_progress:.1f}% avg)"
        )
        console.print(
            f"Tasks blocked: {summary.stats.blocked_tasks}/{summary.stats.total_tasks}"
        )
        console.print(f"Risk: {summary.risk_level}")
    finally:
        await db.disconnect()


@program.command("dashboard")
@click.option("--org", "org_ref", help="Filter by organization name or ID")
@click.option("--org-id", help="Filter by organization ID")
@click.option("--portfolio", "portfolio_ref", help="Filter by portfolio name or ID")
@click.option("--portfolio-id", help="Filter by portfolio ID")
@click.option(
    "-s",
    "--status",
    type=click.Choice(["active", "archived"]),
)
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["table", "json", "csv"]),
    default="table",
    show_default=True,
)
@click.option(
    "--include-digest/--no-digest",
    default=True,
    show_default=True,
    help="Include digest counts since last review",
)
@click.option(
    "--include-next-actions/--no-next-actions",
    default=True,
    show_default=True,
    help="Include ready-task suggestions",
)
@click.option(
    "--include-evidence/--no-evidence",
    default=True,
    show_default=True,
    help="Include evidence totals since last review",
)
@click.option(
    "--include-retention/--no-retention",
    default=True,
    show_default=True,
    help="Include test retention usage",
)
@click.option("--next-limit", type=int, default=3, show_default=True)
@async_command
async def program_dashboard(
    org_ref: str | None,
    org_id: str | None,
    portfolio_ref: str | None,
    portfolio_id: str | None,
    status: str | None,
    output_format: str,
    include_digest: bool,
    include_next_actions: bool,
    include_evidence: bool,
    include_retention: bool,
    next_limit: int,
) -> None:
    """Show program dashboard with rollups."""
    from dataclasses import asdict

    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.models import ProgramStatus
    from pms.services.lineage_service import LineageService
    from pms.services.organization_service import OrganizationService
    from pms.services.portfolio_service import PortfolioService
    from pms.services.program_service import ProgramService
    from pms.services.project_service import ProjectService
    from pms.services.task_service import TaskService
    from pms.services.test_run_retention_service import TestRunRetentionService
    from pms.services.work_snapshot_service import WorkSnapshotService

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        service = ProgramService(db, event_store, revision_store, metrics)
        project_service = ProjectService(db, event_store, revision_store, metrics)
        org_service = OrganizationService(db, event_store, revision_store, metrics)
        portfolio_service = PortfolioService(db, event_store, revision_store, metrics)
        lineage_service = LineageService(db, event_store, revision_store, metrics)
        retention_service = TestRunRetentionService(db, metrics)
        task_service = TaskService(db, event_store, revision_store, metrics)
        snapshot_service = WorkSnapshotService(
            db,
            metrics,
            project_service=project_service,
            organization_service=org_service,
            program_service=service,
            portfolio_service=portfolio_service,
            lineage_service=lineage_service,
            retention_service=retention_service,
        )

        if org_ref and org_id:
            _emit_cli_error(
                "Use --org or --org-id, not both",
                output_format="json" if output_format == "json" else "text",
            )
        if portfolio_ref and portfolio_id:
            _emit_cli_error(
                "Use --portfolio or --portfolio-id, not both",
                output_format="json" if output_format == "json" else "text",
            )
        resolved_org_id = org_id or await _resolve_org_id(org_ref, org_service)
        if org_ref and resolved_org_id is None:
            return
        resolved_portfolio_id = portfolio_id or await _resolve_portfolio_id(
            portfolio_ref, portfolio_service
        )
        if portfolio_ref and resolved_portfolio_id is None:
            return

        status_filter = ProgramStatus(status) if status else None
        dashboard = await service.get_program_dashboard(
            status=status_filter,
            org_id=resolved_org_id,
            portfolio_id=resolved_portfolio_id,
        )

        digest_map: dict[str, Any] = {}
        next_actions_map: dict[str, list[dict[str, Any]]] = {}
        usage_map: dict[str, Any] = {}
        if include_digest:
            for item in dashboard.items:
                digest_result = await snapshot_service.get_digest(
                    "program", item.program.id
                )
                if digest_result:
                    digest_map[item.program.id] = digest_result
        if include_next_actions:
            for item in dashboard.items:
                next_actions_map[
                    item.program.id
                ] = await snapshot_service.get_next_actions(
                    "program",
                    item.program.id,
                    task_service=task_service,
                    project_service=project_service,
                    limit=next_limit,
                )
        if include_evidence or include_retention:
            for item in dashboard.items:
                usage = await snapshot_service.get_usage_summary(
                    "program", item.program.id
                )
                if usage:
                    usage_map[item.program.id] = usage

        org_names: dict[str, str] = {}
        portfolio_names: dict[str, str] = {}
        for item in dashboard.items:
            if item.program.org_id and item.program.org_id not in org_names:
                org = await org_service.get_organization(item.program.org_id)
                if org:
                    org_names[item.program.org_id] = org.name
            if (
                item.program.portfolio_id
                and item.program.portfolio_id not in portfolio_names
            ):
                portfolio = await portfolio_service.get_portfolio(
                    item.program.portfolio_id
                )
                if portfolio:
                    portfolio_names[item.program.portfolio_id] = portfolio.name

        if output_format == "json":
            payload = {
                "totals": {
                    "total_programs": dashboard.total_programs,
                    "total_projects": dashboard.total_projects,
                    "total_goals": dashboard.total_goals,
                    "total_objectives": dashboard.total_objectives,
                    "total_tasks": dashboard.total_tasks,
                    "blocked_tasks": dashboard.blocked_tasks,
                },
                "items": [],
            }
            for item in dashboard.items:
                digest_result = digest_map.get(item.program.id)
                usage_result = usage_map.get(item.program.id)
                last_reviewed_at = (
                    digest_result.last_reviewed_at
                    if digest_result
                    else usage_result.last_reviewed_at
                    if usage_result
                    else None
                )
                payload_item = {
                    "program": _public_entity_payload(item.program),
                    "stats": asdict(item.stats),
                    "risk_level": item.risk_level,
                    "last_activity_at": _to_iso(item.last_activity_at),
                    "last_transition_at": _to_iso(item.last_transition_at),
                    "org_name": org_names.get(item.program.org_id)
                    if item.program.org_id
                    else None,
                    "portfolio_name": portfolio_names.get(item.program.portfolio_id)
                    if item.program.portfolio_id
                    else None,
                }
                if include_digest and digest_result:
                    payload_item["last_reviewed_at"] = _to_iso(last_reviewed_at)
                    payload_item["digest"] = digest_result.digest.to_dict()
                if include_next_actions:
                    payload_item["next_actions"] = next_actions_map.get(
                        item.program.id, []
                    )
                if include_evidence and usage_result:
                    payload_item["last_reviewed_at"] = _to_iso(last_reviewed_at)
                    payload_item["evidence"] = usage_result.evidence.to_dict()
                if include_retention:
                    payload_item["retention"] = (
                        usage_result.retention if usage_result else None
                    )
                payload["items"].append(payload_item)
            base_cmd = "pms program dashboard --format json"
            if resolved_org_id:
                base_cmd += f" --org-id {resolved_org_id}"
            if resolved_portfolio_id:
                base_cmd += f" --portfolio-id {resolved_portfolio_id}"
            if status:
                base_cmd += f" --status {status}"
            if include_digest is False:
                base_cmd += " --no-digest"
            if include_next_actions is False:
                base_cmd += " --no-next-actions"
            if include_evidence is False:
                base_cmd += " --no-evidence"
            if include_retention is False:
                base_cmd += " --no-retention"
            if next_limit != 3:
                base_cmd += f" --next-limit {next_limit}"
            payload["links"] = _normalize_command_links(
                {
                    "self": base_cmd,
                    "portfolio": (
                        f"portfolio dashboard --org-id {resolved_org_id} --format json"
                        if resolved_org_id
                        else "portfolio dashboard --format json"
                    ),
                    "guide": "start --format json",
                }
            )
            payload = _payload_with_normalized_next_steps(
                payload,
                (
                    f"pms portfolio dashboard --org-id {resolved_org_id} --format json"
                    if resolved_org_id
                    else "pms portfolio dashboard --format json"
                ),
                "pms start --format json",
            )
            click.echo(json.dumps(payload, default=str))
            return

        if output_format == "csv":
            headers = [
                "total_programs",
                "total_projects",
                "total_goals",
                "total_objectives",
                "total_tasks",
                "blocked_tasks",
            ]
            click.echo(_csv_row(headers))
            click.echo(
                _csv_row(
                    [
                        str(dashboard.total_programs),
                        str(dashboard.total_projects),
                        str(dashboard.total_goals),
                        str(dashboard.total_objectives),
                        str(dashboard.total_tasks),
                        str(dashboard.blocked_tasks),
                    ]
                )
            )
            item_headers = [
                "program_id",
                "program_name",
                "org_id",
                "org_name",
                "portfolio_id",
                "portfolio_name",
                "projects",
                "goals",
                "objectives",
                "tasks",
                "blocked_tasks",
                "risk_level",
                "last_activity_at",
                "last_transition_at",
            ]
            if include_digest:
                item_headers.extend(
                    [
                        "last_reviewed_at",
                        "digest_tasks_created",
                        "digest_tasks_completed",
                        "digest_tasks_updated",
                        "digest_plans_created",
                        "digest_plans_updated",
                        "digest_test_runs",
                        "digest_failed_test_runs",
                        "digest_evidence_added",
                    ]
                )
            if include_next_actions:
                item_headers.append("next_actions")
            if include_evidence:
                item_headers.extend(
                    [
                        "evidence_total_count",
                        "evidence_new_count",
                    ]
                )
            if include_retention:
                item_headers.extend(
                    [
                        "retention_total_runs",
                        "retention_total_bytes",
                        "retention_log_bytes",
                        "retention_artifact_bytes",
                        "retention_max_log_bytes",
                        "retention_max_artifact_bytes",
                        "retention_alerts",
                    ]
                )
            click.echo(_csv_row(item_headers))
            for item in dashboard.items:
                stats = item.stats
                digest_result = digest_map.get(item.program.id)
                digest_payload = (
                    digest_result.digest.to_dict() if digest_result else None
                )
                usage_result = usage_map.get(item.program.id)
                next_summary = _next_actions_summary(
                    next_actions_map.get(item.program.id)
                )
                row = [
                    item.program.id,
                    item.program.name,
                    item.program.org_id or "",
                    org_names.get(item.program.org_id, "")
                    if item.program.org_id
                    else "",
                    item.program.portfolio_id or "",
                    portfolio_names.get(item.program.portfolio_id, "")
                    if item.program.portfolio_id
                    else "",
                    str(stats.total_projects),
                    str(stats.total_goals),
                    str(stats.total_objectives),
                    str(stats.total_tasks),
                    str(stats.blocked_tasks),
                    item.risk_level,
                    _to_iso(item.last_activity_at) or "",
                    _to_iso(item.last_transition_at) or "",
                ]
                if include_digest:
                    row.extend(
                        [
                            _to_iso(digest_result.last_reviewed_at)
                            if digest_result
                            else "",
                            str(digest_payload["tasks_created"])
                            if digest_payload
                            else "",
                            str(digest_payload["tasks_completed"])
                            if digest_payload
                            else "",
                            str(digest_payload["tasks_updated"])
                            if digest_payload
                            else "",
                            str(digest_payload["plans_created"])
                            if digest_payload
                            else "",
                            str(digest_payload["plans_updated"])
                            if digest_payload
                            else "",
                            str(digest_payload["test_runs"]) if digest_payload else "",
                            str(digest_payload["failed_test_runs"])
                            if digest_payload
                            else "",
                            str(digest_payload["evidence_added"])
                            if digest_payload
                            else "",
                        ]
                    )
                if include_next_actions:
                    row.append(next_summary)
                if include_evidence:
                    evidence_payload = (
                        usage_result.evidence.to_dict() if usage_result else {}
                    )
                    row.extend(
                        [
                            str(evidence_payload.get("total_count", 0)),
                            str(evidence_payload.get("new_count", 0)),
                        ]
                    )
                if include_retention:
                    retention_payload = usage_result.retention if usage_result else {}
                    row.extend(
                        [
                            str(retention_payload.get("total_runs", 0)),
                            str(retention_payload.get("total_bytes", 0)),
                            str(retention_payload.get("total_log_bytes_combined", 0)),
                            str(retention_payload.get("total_artifact_bytes", 0)),
                            str(retention_payload.get("max_log_bytes", 0)),
                            str(retention_payload.get("max_artifact_bytes", 0)),
                            str(len(retention_payload.get("alerts") or [])),
                        ]
                    )
                click.echo(_csv_row(row))
            return

        console.print("[bold]Program Dashboard[/bold]")
        console.print("=" * 40)
        console.print(f"Total Programs: {dashboard.total_programs}")
        console.print(
            f"Projects: {dashboard.total_projects} | Goals: {dashboard.total_goals} | Objectives: {dashboard.total_objectives}"
        )
        console.print(f"Tasks: {dashboard.total_tasks}")
        if dashboard.blocked_tasks > 0:
            console.print(f"Blocked Tasks: [red]{dashboard.blocked_tasks}[/red]")

        if dashboard.items:
            console.print()
            table = Table(title="Programs")
            table.add_column("Program", style="cyan")
            table.add_column("Org")
            table.add_column("Portfolio")
            table.add_column("Projects", justify="right")
            table.add_column("Goals", justify="right")
            table.add_column("Objectives", justify="right")
            table.add_column("Tasks", justify="right")
            table.add_column("Risk")
            table.add_column("Activity")
            table.add_column("Last Transition")
            if include_digest:
                table.add_column("Digest")
            if include_next_actions:
                table.add_column("Next")
            if include_evidence:
                table.add_column("Evidence")
            if include_retention:
                table.add_column("Retention")

            for item in dashboard.items:
                stats = item.stats
                risk_color = {
                    "low": "green",
                    "medium": "yellow",
                    "high": "red",
                }.get(item.risk_level, "white")
                org_label = (
                    org_names.get(item.program.org_id, item.program.org_id)
                    if item.program.org_id
                    else "-"
                )
                portfolio_label = (
                    portfolio_names.get(
                        item.program.portfolio_id, item.program.portfolio_id
                    )
                    if item.program.portfolio_id
                    else "-"
                )
                row = [
                    item.program.name,
                    org_label,
                    portfolio_label,
                    str(stats.total_projects),
                    str(stats.total_goals),
                    str(stats.total_objectives),
                    str(stats.total_tasks),
                    f"[{risk_color}]{item.risk_level}[/{risk_color}]",
                    format_relative(item.last_activity_at),
                    format_relative(item.last_transition_at),
                ]
                if include_digest:
                    digest_result = digest_map.get(item.program.id)
                    row.append(
                        _digest_summary(digest_result.digest if digest_result else None)
                    )
                if include_next_actions:
                    row.append(
                        _truncate(
                            _next_actions_summary(
                                next_actions_map.get(item.program.id)
                            ),
                            32,
                        )
                    )
                if include_evidence:
                    usage_result = usage_map.get(item.program.id)
                    evidence_payload = (
                        usage_result.evidence.to_dict() if usage_result else None
                    )
                    row.append(_evidence_summary(evidence_payload))
                if include_retention:
                    usage_result = usage_map.get(item.program.id)
                    row.append(
                        _truncate(
                            _retention_summary(
                                usage_result.retention if usage_result else None
                            ),
                            26,
                        )
                    )
                table.add_row(*row)

            console.print(table)
    finally:
        await db.disconnect()


@cli.group()
def goal() -> None:
    """Manage goals."""
    pass


@goal.command("create")
@click.argument("name")
@click.option("-d", "--description", help="Goal description")
@click.option(
    "--horizon",
    type=click.Choice(["short_term", "medium_term", "long_term"]),
    default="short_term",
)
@click.option("--target-date", help="Target date (ISO format)")
@click.option("--owner", help="Goal owner")
@click.option("--product", "product_ref", help="Product ID or name")
@click.option("--product-id", help="Link to product")
@click.option("--project", "project_ref", help="Project ID or name")
@click.option("--project-id", help="Link to project")
@click.option("-t", "--tag", "tags", multiple=True, help="Goal tags")
@click.option("--progress", type=int, default=0, help="Progress percent (0-100)")
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json"]),
    default="text",
    show_default=True,
)
@async_command
async def goal_create(
    name: str,
    description: str | None,
    horizon: str,
    target_date: str | None,
    owner: str | None,
    product_ref: str | None,
    product_id: str | None,
    project_ref: str | None,
    project_id: str | None,
    tags: tuple[str, ...],
    progress: int,
    output_format: str,
) -> None:
    """Create a new goal."""
    from datetime import datetime

    write_decision = _ensure_runtime_write_mode(
        "pms goal create",
        emit_messages=output_format != "json",
    )
    if write_decision is None:
        return

    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.models import GoalHorizon
    from pms.services.actor_service import ActorService
    from pms.services.goal_service import GoalService
    from pms.services.product_service import ProductService
    from pms.services.project_service import ProjectService

    target_dt = None
    if target_date:
        try:
            target_dt = datetime.fromisoformat(target_date)
        except ValueError:
            _emit_cli_error(
                "Invalid target date format (use ISO)",
                output_format="json" if output_format == "json" else "text",
            )

    if progress < 0 or progress > 100:
        _emit_cli_error(
            "Progress must be 0-100",
            output_format="json" if output_format == "json" else "text",
        )
    if product_ref and product_id:
        _emit_cli_error(
            "Use --product or --product-id, not both",
            output_format="json" if output_format == "json" else "text",
        )
    if project_ref and project_id:
        _emit_cli_error(
            "Use --project or --project-id, not both",
            output_format="json" if output_format == "json" else "text",
        )

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        service = GoalService(db, event_store, revision_store, metrics)
        actor_service = ActorService(db, event_store, revision_store, metrics)
        actor_service = ActorService(db, event_store, revision_store, metrics)
        product_service = ProductService(db, event_store, revision_store, metrics)
        project_service = ProjectService(db, event_store, revision_store, metrics)

        resolved_product_id = product_id or await _resolve_product_id(
            product_ref, product_service
        )
        if product_ref and resolved_product_id is None:
            return
        resolved_project_id = project_id or await _resolve_project_id(
            project_ref, project_service
        )
        if project_ref and resolved_project_id is None:
            return

        try:
            if write_decision.use_server:
                goal_payload = await _delegate_goal_create_to_server(
                    name=name,
                    description=description,
                    horizon=horizon,
                    target_date=target_dt.isoformat() if target_dt else None,
                    owner=owner,
                    product_id=resolved_product_id,
                    project_id=resolved_project_id,
                    tags=list(tags) if tags else None,
                    progress_percent=progress,
                )
                goal = await service.get_goal(str(goal_payload["id"]))
                if goal is None:
                    _emit_cli_error(
                        "Created goal on server but failed to reload it locally",
                        output_format="json" if output_format == "json" else "text",
                    )
            else:
                goal = await service.create_goal(
                    name=name,
                    description=description,
                    horizon=GoalHorizon(horizon),
                    target_date=target_dt,
                    owner=owner,
                    product_id=resolved_product_id,
                    project_id=resolved_project_id,
                    tags=list(tags) if tags else None,
                    progress_percent=progress,
                )
        except ValueError as exc:
            console.print(f"[red]{exc}[/red]")
            return

        project_label = project_ref
        if not project_label and resolved_project_id:
            project = await project_service.get_project(resolved_project_id)
            if project:
                project_label = project.name
        next_steps = _normalize_next_steps(
            f"pms goal show {goal.id}",
            f'pms objective create <name> --goal "{goal.name}"',
            (
                f'pms goal list --project "{project_label}"'
                if project_label
                else f"pms goal list --project {resolved_project_id}"
                if resolved_project_id
                else ""
            ),
        )
        if output_format == "json":
            owner_map = await _resolve_owner_map([goal], actor_service)
            payload = {
                "goal": {
                    **_public_entity_payload(goal),
                    "ownership": _ownership_payload(goal, owner_map),
                },
                "runtime_write": _runtime_write_context_payload(write_decision),
                "links": _normalize_command_links(
                    {
                        "self": f"pms goal show {goal.id}",
                        "summary": f"pms goal summary {goal.id} --format json",
                        "objective_create": f'pms objective create <name> --goal "{goal.name}"',
                        "goal_list": (
                            f"pms goal list --project {resolved_project_id} --format json"
                            if resolved_project_id
                            else "pms goal list --format json"
                        ),
                        "owner": _ownership_link(goal, owner_map),
                    }
                ),
                "next_steps": next_steps,
            }
            click.echo(json.dumps(payload, default=str))
            return

        console.print(f"[green]Created goal:[/green] {goal.name}")
        console.print(f"[dim]ID: {goal.id}[/dim]")
        _print_next_steps(*next_steps)
    finally:
        await db.disconnect()


@goal.command("list")
@click.option(
    "-s",
    "--status",
    type=click.Choice(["active", "completed", "on_hold", "archived"]),
)
@click.option(
    "--horizon",
    type=click.Choice(["short_term", "medium_term", "long_term"]),
)
@click.option("--product", "product_ref", help="Product ID or name")
@click.option("--product-id", help="Filter by product")
@click.option("--project", "project_ref", help="Project ID or name")
@click.option("--project-id", help="Filter by project")
@click.option(
    "--include-generated",
    is_flag=True,
    help="Include audit/demo/generated goals normally suppressed from default operator views",
)
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["table", "json", "csv"]),
    default="table",
    show_default=True,
)
@click.option(
    "--view",
    type=click.Choice(["overview", "detail", "trace"]),
    default="overview",
    show_default=True,
    help="Output view profile (overview/detail/trace)",
)
@click.option("--include-history", is_flag=True, help="Include history in JSON")
@click.option("--include-linked", is_flag=True, help="Include linked items in JSON")
@click.option(
    "--include-linked-history",
    is_flag=True,
    help="Include history for linked items in JSON",
)
@click.option("--history-limit", type=int, default=20, show_default=True)
@click.option("--linked-limit", type=int, default=20, show_default=True)
@click.option("--limit", type=int, default=100, show_default=True)
@click.option("--offset", type=int, default=0, show_default=True)
@async_command
async def goal_list(
    status: str | None,
    horizon: str | None,
    product_ref: str | None,
    product_id: str | None,
    project_ref: str | None,
    project_id: str | None,
    include_generated: bool,
    output_format: str,
    view: str,
    include_history: bool,
    include_linked: bool,
    include_linked_history: bool,
    history_limit: int,
    linked_limit: int,
    limit: int,
    offset: int,
) -> None:
    """List goals."""
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.models import GoalHorizon, GoalStatus
    from pms.repositories.goal_repository import GoalRepository
    from pms.repositories.objective_repository import ObjectiveRepository
    from pms.repositories.product_repository import ProductRepository
    from pms.repositories.project_repository import ProjectRepository
    from pms.services.generated_artifacts import (
        is_placeholder_reference,
        project_operator_category_label,
        project_operator_visibility_reason,
    )
    from pms.services.goal_service import GoalService
    from pms.services.product_service import ProductService
    from pms.services.project_service import ProjectService
    from pms.utils.time import format_relative

    if product_ref and product_id:
        _emit_cli_error(
            "Use --product or --product-id, not both",
            output_format="json" if output_format == "json" else "text",
        )
    if project_ref and project_id:
        _emit_cli_error(
            "Use --project or --project-id, not both",
            output_format="json" if output_format == "json" else "text",
        )

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        service = GoalService(db, event_store, revision_store, metrics)
        product_service = ProductService(db, event_store, revision_store, metrics)
        project_service = ProjectService(db, event_store, revision_store, metrics)
        goal_repo = GoalRepository(db, event_store, revision_store, metrics)
        objective_repo = ObjectiveRepository(db, event_store, revision_store, metrics)
        project_repo = ProjectRepository(db, event_store, revision_store, metrics)
        product_repo = ProductRepository(db, event_store, revision_store, metrics)

        if view == "trace":
            include_history = True
            include_linked = True
        if include_linked_history:
            include_linked = True
            include_history = True

        resolved_product_id = product_id or await _resolve_product_id(
            product_ref, product_service
        )
        if product_ref and resolved_product_id is None:
            return
        resolved_project_id = project_id or await _resolve_project_id(
            project_ref, project_service
        )
        if project_ref and resolved_project_id is None:
            return

        status_filter = GoalStatus(status) if status else None
        horizon_filter = GoalHorizon(horizon) if horizon else None
        population_data = await _collect_goal_operator_populations(
            service,
            project_repo,
            status=status_filter,
            horizon=horizon_filter,
            product_id=resolved_product_id,
            project_id=resolved_project_id,
            limit=limit,
            offset=offset,
        )
        suppressed_generated_count = population_data["suppressed_generated_count"]
        suppressed_hidden_count = population_data["suppressed_hidden_count"]
        visible_counts = population_data["visible_counts"]
        raw_counts = population_data["raw_counts"]
        project_operator_categories = population_data["project_categories"]
        if include_generated:
            result = population_data["raw_result"]
            selected_counts = raw_counts
            selected_population = "all_retained"
            population_totals = {
                "population": "all_retained",
                "total_goals": population_data["raw_result"].total_count,
                **{f"{key}_goals": value for key, value in raw_counts.items()},
            }
        else:
            result = population_data["visible_result"]
            selected_counts = visible_counts
            selected_population = "visible_operator"
            population_totals = {
                "population": "visible_operator",
                "total_goals": population_data["visible_result"].total_count,
                **{f"{key}_goals": value for key, value in visible_counts.items()},
            }

        project_names: dict[str, str] = {}
        product_names: dict[str, str] = {}
        for goal in result.items:
            if goal.project_id and goal.project_id not in project_names:
                project = await project_repo.get_by_id(goal.project_id)
                if project:
                    project_names[goal.project_id] = project.name
            if goal.product_id and goal.product_id not in product_names:
                product = await product_repo.get_by_id(goal.product_id)
                if product:
                    product_names[goal.product_id] = product.name

        visible_items: list[Any] = list(result.items)
        status_groups = dict(selected_counts)

        next_actions: list[str] = []
        if visible_items:
            next_actions.append(f"pms goal show {visible_items[0].id}")
            next_actions.append(f'pms objective list --goal "{visible_items[0].name}"')
        project_hint = project_ref or project_id or "<project>"
        next_actions.append(f'pms goal create <name> --project "{project_hint}"')
        if not visible_items and (
            suppressed_generated_count or suppressed_hidden_count
        ):
            next_actions.append("pms goal list --include-generated --format json")
            next_actions.append("pms dashboard --format json")
        effective_rollups = await service.get_effective_rollups_for_goals(visible_items)
        execution_summaries = await service.get_execution_summaries_for_goals(
            visible_items
        )
        goal_ids = [goal.id for goal in visible_items]
        activity_map = await service.get_last_activity_map(goal_ids)
        transition_map = await service.get_last_transition_map(goal_ids)

        if output_format == "json":
            effective_history_limit = history_limit if history_limit > 0 else 1000
            effective_linked_limit = linked_limit if linked_limit > 0 else 1000

            payload_items = []
            for goal in visible_items:
                project_name = (
                    project_names.get(goal.project_id) if goal.project_id else None
                )
                product_name = (
                    product_names.get(goal.product_id) if goal.product_id else None
                )
                effective_rollup = effective_rollups.get(goal.id)
                execution_summary = execution_summaries.get(goal.id)
                goal_last_activity = _to_iso(activity_map.get(goal.id))
                goal_last_transition = _to_iso(transition_map.get(goal.id))
                goal_terminal_reason = _goal_terminal_reason(
                    goal,
                    effective_rollup=effective_rollup,
                    execution=execution_summary,
                )
                goal_links = _goal_list_links(goal)
                if view == "overview":
                    payload = {
                        "id": goal.id,
                        "name": goal.name,
                        "status": goal.status.value,
                        "horizon": goal.horizon.value,
                        "progress_percent": goal.progress_percent,
                        "effective_rollup": _goal_effective_rollup_struct(
                            effective_rollup
                        ),
                        "product_id": goal.product_id,
                        "product_name": product_name,
                        "project_id": goal.project_id,
                        "project_name": project_name,
                        "project_operator_category": (
                            project_operator_categories.get(goal.project_id)
                            if goal.project_id
                            else None
                        ),
                        "project_operator_category_label": (
                            project_operator_category_label(
                                project_operator_categories.get(goal.project_id, "")
                            )
                            if goal.project_id
                            and goal.project_id in project_operator_categories
                            else None
                        ),
                        "project_operator_visibility_reason": (
                            project_operator_visibility_reason(
                                project_operator_categories.get(goal.project_id, "")
                            )
                            if goal.project_id
                            and goal.project_id in project_operator_categories
                            else None
                        ),
                        "created_at": _to_iso(goal.created_at),
                        "updated_at": _to_iso(goal.updated_at),
                        "last_activity_at": goal_last_activity,
                        "last_transition_at": goal_last_transition,
                        "terminal_reason": goal_terminal_reason,
                        "links": goal_links,
                    }
                else:
                    payload = _public_entity_payload(goal)
                    payload.update(
                        {
                            "product_name": product_name,
                            "project_name": project_name,
                            "project_operator_category": (
                                project_operator_categories.get(goal.project_id)
                                if goal.project_id
                                else None
                            ),
                            "project_operator_category_label": (
                                project_operator_category_label(
                                    project_operator_categories.get(goal.project_id, "")
                                )
                                if goal.project_id
                                and goal.project_id in project_operator_categories
                                else None
                            ),
                            "project_operator_visibility_reason": (
                                project_operator_visibility_reason(
                                    project_operator_categories.get(goal.project_id, "")
                                )
                                if goal.project_id
                                and goal.project_id in project_operator_categories
                                else None
                            ),
                            "links": goal_links,
                            "effective_rollup": _goal_effective_rollup_struct(
                                effective_rollup
                            ),
                            "last_activity_at": goal_last_activity,
                            "last_transition_at": goal_last_transition,
                            "terminal_reason": goal_terminal_reason,
                        }
                    )
                    summary = await service.get_goal_summary(goal.id)
                    if summary:
                        payload["summary"] = {
                            "objective_count": summary.objective_count,
                            "completed_objectives": summary.completed_objectives,
                            "key_result_count": summary.key_result_count,
                            "completed_key_results": summary.completed_key_results,
                            "average_progress": summary.average_progress,
                        }

                if include_linked:
                    objectives_result = await objective_repo.get_by_goal(
                        goal.id, limit=effective_linked_limit, offset=0
                    )
                    objectives = objectives_result.items
                    payload["linked"] = {
                        "objectives": [
                            {
                                "id": objective.id,
                                "name": objective.name,
                                "status": objective.status.value,
                                "progress_percent": objective.progress_percent,
                                "updated_at": _to_iso(objective.updated_at),
                                "links": _normalize_command_links(
                                    {"self": f"pms objective show {objective.id}"}
                                ),
                            }
                            for objective in objectives
                        ],
                        "page": {
                            "total_count": objectives_result.total_count,
                            "limit": objectives_result.limit,
                            "offset": objectives_result.offset,
                            "has_more": objectives_result.has_more,
                            "next_offset": objectives_result.offset
                            + objectives_result.limit
                            if objectives_result.has_more
                            else None,
                        },
                    }
                    if include_linked_history:
                        payload["linked_history"] = {
                            objective.id: [
                                {
                                    "revision_number": rev.revision_number,
                                    "change_type": rev.change_type.value,
                                    "message": rev.message,
                                    "created_by": rev.created_by,
                                    "created_at": rev.created_at,
                                }
                                for rev in await objective_repo.get_history(
                                    objective.id, limit=effective_history_limit
                                )
                            ]
                            for objective in objectives
                        }

                if include_history:
                    history = await goal_repo.get_history(
                        goal.id, limit=effective_history_limit
                    )
                    payload["history"] = [
                        {
                            "revision_number": rev.revision_number,
                            "change_type": rev.change_type.value,
                            "message": rev.message,
                            "created_by": rev.created_by,
                            "created_at": rev.created_at,
                        }
                        for rev in history
                    ]

                payload_items.append(payload)

            base_cmd = "pms goal list --format json"
            if status:
                base_cmd += f" --status {status}"
            if horizon:
                base_cmd += f" --horizon {horizon}"
            if resolved_product_id:
                base_cmd += f" --product-id {resolved_product_id}"
            if resolved_project_id:
                base_cmd += f" --project-id {resolved_project_id}"
            if include_generated:
                base_cmd += " --include-generated"
            if view != "overview":
                base_cmd += f" --view {view}"
            payload = {
                "items": payload_items,
                "scope": {
                    "kind": "instance_goal_list"
                    if resolved_project_id is None
                    else "scoped_goal_list",
                    "population": selected_population,
                    "summary": (
                        "Instance-wide retained goal list view. Generated and historical project goals are included explicitly."
                        if include_generated
                        else "Instance-wide operator-visible goal list view. Generated and retained-history goals are excluded by default."
                    ),
                },
                "status_groups": status_groups,
                "items_by_status": {
                    status_key: [
                        item for item in payload_items if item["status"] == status_key
                    ]
                    for status_key in ("active", "completed", "on_hold", "archived")
                },
                "visible_totals": {
                    "population": "visible_operator",
                    "total_goals": population_data["visible_result"].total_count,
                    **{f"{key}_goals": value for key, value in visible_counts.items()},
                },
                "population_totals": population_totals,
                "page": {
                    "total_count": result.total_count,
                    "limit": result.limit,
                    "offset": result.offset,
                    "has_more": result.has_more,
                    "next_offset": (
                        result.offset + result.limit if result.has_more else None
                    ),
                },
                "suppressed_generated_count": suppressed_generated_count,
                "suppressed_hidden_count": suppressed_hidden_count,
                "links": _normalize_command_links(
                    {
                        "self": f"{base_cmd} --limit {limit} --offset {offset}",
                        "next": None,
                    }
                ),
            }
            payload = _payload_with_normalized_next_steps(payload, *next_actions)
            click.echo(json.dumps(payload, indent=2, default=str))
            return

        if output_format == "csv":
            headers = [
                "id",
                "name",
                "status",
                "horizon",
                "progress_percent",
                "effective_progress_percent",
                "effective_status",
                "effective_basis",
                "project_id",
                "project_name",
                "product_id",
                "product_name",
                "target_date",
                "updated_at",
            ]
            click.echo(_csv_row(headers))
            for g in visible_items:
                effective_rollup = effective_rollups.get(g.id)
                row = [
                    g.id,
                    g.name,
                    g.status.value,
                    g.horizon.value,
                    str(g.progress_percent),
                    (
                        str(effective_rollup.progress_percent)
                        if effective_rollup is not None
                        else str(g.progress_percent)
                    ),
                    effective_rollup.status
                    if effective_rollup is not None
                    else g.status.value,
                    effective_rollup.basis
                    if effective_rollup is not None
                    else "stored_goal",
                    g.project_id or "",
                    project_names.get(g.project_id, "") if g.project_id else "",
                    g.product_id or "",
                    product_names.get(g.product_id, "") if g.product_id else "",
                    g.target_date.isoformat() if g.target_date else "",
                    str(g.updated_at)[:19] if g.updated_at else "",
                ]
                click.echo(_csv_row(row))
            return

        goal_ref_map = (
            _short_id_map([goal.id for goal in visible_items]) if visible_items else {}
        )
        table = Table(title="Goals")
        table.add_column("Ref", style="cyan")
        table.add_column("Name", style="cyan")
        table.add_column("Status")
        table.add_column("Effective")
        table.add_column("Horizon")
        table.add_column("Progress")
        table.add_column("Project")
        table.add_column("Product")
        table.add_column("Target")
        table.add_column("Updated")
        for g in visible_items:
            effective_rollup = effective_rollups.get(g.id)
            target = g.target_date.date().isoformat() if g.target_date else "-"
            project_label = (
                "-"
                if not g.project_id or is_placeholder_reference(g.project_id)
                else project_names.get(g.project_id, g.project_id)
            )
            product_label = (
                "-"
                if not g.product_id or is_placeholder_reference(g.product_id)
                else product_names.get(g.product_id, g.product_id)
            )
            effective_status = (
                effective_rollup.status
                if effective_rollup is not None
                else g.status.value
            )
            progress_label = f"{g.progress_percent}%"
            if (
                effective_rollup is not None
                and effective_rollup.progress_percent != g.progress_percent
            ):
                progress_label = (
                    f"{effective_rollup.progress_percent}% "
                    f"(stored {g.progress_percent}%)"
                )
            table.add_row(
                goal_ref_map.get(g.id, g.id),
                g.name,
                g.status.value,
                effective_status,
                g.horizon.value,
                progress_label,
                project_label,
                product_label,
                target,
                format_relative(g.updated_at),
            )
        console.print(table)
        console.print(f"[dim]Total: {len(visible_items)}[/dim]")
        console.print(
            "[dim]"
            f"Status groups: active {status_groups['active']} | "
            f"completed {status_groups['completed']} | "
            f"on_hold {status_groups['on_hold']} | "
            f"archived {status_groups['archived']}"
            "[/dim]"
        )
        if suppressed_generated_count:
            console.print(
                f"[dim]Suppressed generated goals: {suppressed_generated_count} "
                f"(use --include-generated to show)[/dim]"
            )
        _print_next_steps(*next_actions)
    finally:
        await db.disconnect()


@goal.command("show")
@click.argument("goal_ref")
@click.option(
    "--pick",
    is_flag=True,
    help="Pick from matching goals when name is ambiguous",
)
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json", "csv"]),
    default="text",
    show_default=True,
)
@click.option(
    "--view",
    type=click.Choice(["overview", "detail", "trace"]),
    default="detail",
    show_default=True,
    help="Output view profile (overview/detail/trace)",
)
@click.option("--include-history", is_flag=True, help="Include history in JSON")
@click.option("--include-linked", is_flag=True, help="Include linked items in JSON")
@click.option(
    "--include-linked-history",
    is_flag=True,
    help="Include history for linked items in JSON",
)
@click.option("--history-limit", type=int, default=20, show_default=True)
@click.option("--linked-limit", type=int, default=20, show_default=True)
@async_command
async def goal_show(
    goal_ref: str,
    pick: bool,
    output_format: str,
    view: str,
    include_history: bool,
    include_linked: bool,
    include_linked_history: bool,
    history_limit: int,
    linked_limit: int,
) -> None:
    """Show goal details."""
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.repositories.goal_repository import GoalRepository
    from pms.repositories.objective_repository import ObjectiveRepository
    from pms.repositories.product_repository import ProductRepository
    from pms.repositories.project_repository import ProjectRepository
    from pms.services.actor_service import ActorService
    from pms.services.goal_service import GoalService
    from pms.utils.time import format_relative

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        service = GoalService(db, event_store, revision_store, metrics)
        actor_service = ActorService(db, event_store, revision_store, metrics)
        goal_repo = GoalRepository(db, event_store, revision_store, metrics)
        objective_repo = ObjectiveRepository(db, event_store, revision_store, metrics)
        product_repo = ProductRepository(db, event_store, revision_store, metrics)
        project_repo = ProjectRepository(db, event_store, revision_store, metrics)

        if view == "trace":
            include_history = True
            include_linked = True
        if include_linked_history:
            include_linked = True
            include_history = True

        resolved_goal_id = await _resolve_goal_id(goal_ref, service, pick=pick)
        if resolved_goal_id is None:
            return

        goal = await service.get_goal(resolved_goal_id)
        if goal is None:
            console.print(f"[red]Goal '{goal_ref}' not found[/red]")
            return

        product_name = None
        project_name = None
        if goal.product_id:
            product = await product_repo.get_by_id(goal.product_id)
            if product:
                product_name = product.name
        if goal.project_id:
            project = await project_repo.get_by_id(goal.project_id)
            if project:
                project_name = project.name
        owner_map = await _resolve_actor_reference_map(
            [goal.owner_id, goal.owner],
            actor_service,
        )
        goal_rollup_entities: list[Any] = [goal]
        goal_rollup_actor_map = dict(owner_map)

        if output_format == "json":
            effective_history_limit = history_limit if history_limit > 0 else 1000
            effective_linked_limit = linked_limit if linked_limit > 0 else 1000

            goal_summary_data = await service.get_goal_summary(goal.id)
            goal_activity_map = await service.get_last_activity_map([goal.id])
            goal_transition_map = await service.get_last_transition_map([goal.id])
            goal_last_activity = goal_activity_map.get(goal.id)
            goal_last_transition = goal_transition_map.get(goal.id)
            focus_task_lookup: dict[str, Any] = {}
            if (
                goal_summary_data is not None
                and goal_summary_data.execution is not None
                and goal_summary_data.execution.focus_task is not None
            ):
                from pms.repositories.task_repository import TaskRepository

                task_repo = TaskRepository(db, event_store, revision_store, metrics)
                focus_task_obj = await task_repo.get_by_id(
                    goal_summary_data.execution.focus_task.id
                )
                if focus_task_obj is not None:
                    focus_task_lookup[focus_task_obj.id] = focus_task_obj
            focus_assignee_map = await _resolve_assignee_map(
                list(focus_task_lookup.values()),
                actor_service,
            )
            focus_checkout_actor_map = await _resolve_checkout_actor_map(
                list(focus_task_lookup.values()),
                actor_service,
            )
            goal_terminal_reason = (
                _goal_terminal_reason_from_summary(goal_summary_data)
                if goal_summary_data is not None
                else None
            )
            goal_completion_context = _goal_completion_context_payload(
                goal_id=goal.id,
                project_id=goal.project_id,
                terminal_reason=goal_terminal_reason,
            )
            links = _goal_detail_links(
                goal,
                owner_link=_actor_reference_link(
                    goal.owner,
                    owner_map,
                    actor_id=goal.owner_id,
                ),
            )

            if view == "overview":
                payload: dict[str, Any] = {
                    "id": goal.id,
                    "name": goal.name,
                    "status": goal.status.value,
                    "horizon": goal.horizon.value,
                    "progress_percent": goal.progress_percent,
                    "owner": goal.owner,
                    "ownership": _actor_reference_payload(
                        goal.owner,
                        owner_map,
                        actor_id=goal.owner_id,
                    ),
                    "product_id": goal.product_id,
                    "product_name": product_name,
                    "project_id": goal.project_id,
                    "project_name": project_name,
                    "created_at": _to_iso(goal.created_at),
                    "updated_at": _to_iso(goal.updated_at),
                    "links": links,
                }
            else:
                payload = _public_entity_payload(goal)
                payload.update(
                    {
                        "product_name": product_name,
                        "project_name": project_name,
                        "ownership": _actor_reference_payload(
                            goal.owner,
                            owner_map,
                            actor_id=goal.owner_id,
                        ),
                        "links": links,
                        "last_activity_at": _to_iso(goal_last_activity),
                        "last_transition_at": _to_iso(goal_last_transition),
                        "terminal_reason": goal_terminal_reason,
                        "completion_context": goal_completion_context,
                    }
                )
                if goal_summary_data is not None:
                    payload["stats"] = _goal_stats_payload(goal_summary_data)
                    payload["effective_rollup"] = _goal_effective_rollup_payload(
                        goal_summary_data
                    )
                    payload["effective_hierarchy"] = _goal_effective_hierarchy_payload(
                        goal_summary_data
                    )
                    payload["execution"] = _goal_execution_payload(
                        goal_summary_data,
                        project_name=project_name,
                        task_lookup=focus_task_lookup,
                        assignee_map=focus_assignee_map,
                        checkout_actor_map=focus_checkout_actor_map,
                    )
                    payload = _payload_with_normalized_next_steps(
                        payload,
                        *_goal_lifecycle_next_steps(
                            goal_summary_data,
                            project_name=project_name,
                            terminal_reason=goal_terminal_reason,
                            primary_surface="detail",
                        ),
                    )

            if include_linked:
                objectives_result = await objective_repo.get_by_goal(
                    goal.id, limit=effective_linked_limit, offset=0
                )
                objectives = objectives_result.items
                objective_owner_map = await _resolve_actor_reference_map(
                    [
                        actor_key
                        for objective in objectives
                        for actor_key in (objective.owner_id, objective.owner)
                    ],
                    actor_service,
                )
                payload["linked"] = {
                    "project": (
                        {
                            "id": goal.project_id,
                            "name": project_name,
                            "links": _normalize_command_links(
                                {
                                    "self": (
                                        f"pms project show {goal.project_id} --format json"
                                    ),
                                    "summary": (
                                        f"pms project summary {goal.project_id} --format json"
                                    ),
                                    "goals": (
                                        f"pms goal list --project-id {goal.project_id} --format json"
                                    ),
                                }
                            ),
                        }
                        if goal.project_id
                        else None
                    ),
                    "product": (
                        {
                            "id": goal.product_id,
                            "name": product_name,
                            "links": _normalize_command_links(
                                {
                                    "self": (
                                        f"pms product show {goal.product_id} --format json"
                                    ),
                                }
                            ),
                        }
                        if goal.product_id
                        else None
                    ),
                    "objectives": [
                        {
                            "id": objective.id,
                            "name": objective.name,
                            "status": objective.status.value,
                            "progress_percent": objective.progress_percent,
                            "owner": objective.owner,
                            "ownership": _actor_reference_payload(
                                objective.owner,
                                objective_owner_map,
                                actor_id=objective.owner_id,
                            ),
                            "updated_at": _to_iso(objective.updated_at),
                            "links": _normalize_command_links(
                                {
                                    "self": f"pms objective show {objective.id}",
                                    "goal": f"pms goal show {goal.id}",
                                    "owner": _actor_reference_link(
                                        objective.owner,
                                        objective_owner_map,
                                        actor_id=objective.owner_id,
                                    ),
                                }
                            ),
                        }
                        for objective in objectives
                    ],
                    "page": {
                        "total_count": objectives_result.total_count,
                        "limit": objectives_result.limit,
                        "offset": objectives_result.offset,
                        "has_more": objectives_result.has_more,
                        "next_offset": objectives_result.offset
                        + objectives_result.limit
                        if objectives_result.has_more
                        else None,
                    },
                }
                if include_linked_history:
                    payload["linked_history"] = {
                        objective.id: [
                            {
                                "revision_number": rev.revision_number,
                                "change_type": rev.change_type.value,
                                "message": rev.message,
                                "created_by": rev.created_by,
                                "created_at": rev.created_at,
                            }
                            for rev in await objective_repo.get_history(
                                objective.id, limit=effective_history_limit
                            )
                        ]
                        for objective in objectives
                    }
                goal_rollup_entities = [goal, *objectives]
                goal_rollup_actor_map = {**owner_map, **objective_owner_map}

            if include_history:
                history = await goal_repo.get_history(
                    goal.id, limit=effective_history_limit
                )
                payload["history"] = [
                    {
                        "revision_number": rev.revision_number,
                        "change_type": rev.change_type.value,
                        "message": rev.message,
                        "created_by": rev.created_by,
                        "created_at": rev.created_at,
                    }
                    for rev in history
                ]

            payload["actor_rollups"] = _actor_rollups_payload(
                owners=goal_rollup_entities,
                owner_map=goal_rollup_actor_map,
                population_basis="goal_surface_visible_entities",
            )
            if view == "overview":
                payload = _payload_with_normalized_next_steps(
                    payload,
                    f"goal summary {goal.id}",
                    f"objective list --goal-id {goal.id} --format json",
                    f"goal update {goal.id}",
                )

            click.echo(json.dumps(payload, default=str))
            return

        if output_format == "csv":
            headers = [
                "id",
                "name",
                "status",
                "horizon",
                "progress_percent",
                "target_date",
                "owner",
                "product_id",
                "product_name",
                "project_id",
                "project_name",
            ]
            click.echo(_csv_row(headers))
            row = [
                goal.id,
                goal.name,
                goal.status.value,
                goal.horizon.value,
                str(goal.progress_percent),
                goal.target_date.isoformat() if goal.target_date else "",
                goal.owner or "",
                goal.product_id or "",
                product_name or "",
                goal.project_id or "",
                project_name or "",
            ]
            click.echo(_csv_row(row))
            return

        if view == "overview":
            console.print(f"[bold cyan]{goal.name}[/bold cyan]")
            console.print(f"Status: {goal.status.value}")
            console.print(f"Horizon: {goal.horizon.value}")
            console.print(f"Progress: {goal.progress_percent}%")
            console.print(f"Updated: {format_relative(goal.updated_at)}")
            _print_next_steps(
                f"pms goal summary {goal.id}",
                f'pms objective list --goal "{goal.name}"',
                f"pms goal update {goal.id}",
            )
            return

        console.print(f"[bold cyan]{goal.name}[/bold cyan]")
        console.print(f"Status: {goal.status.value}")
        console.print(f"Horizon: {goal.horizon.value}")
        console.print(f"Progress: {goal.progress_percent}%")
        console.print(f"Created: {format_relative(goal.created_at)}")
        console.print(f"Updated: {format_relative(goal.updated_at)}")
        if goal.description:
            console.print(f"Description: {goal.description}")
        if goal.target_date:
            console.print(f"Target: {goal.target_date.isoformat()}")
        if goal.owner:
            console.print(f"Owner: {goal.owner}")
        if goal.product_id:
            if product_name:
                console.print(f"Product: {product_name} ({goal.product_id})")
            else:
                console.print(f"Product: {goal.product_id}")
        if goal.project_id:
            if project_name:
                console.print(f"Project: {project_name} ({goal.project_id})")
            else:
                console.print(f"Project: {goal.project_id}")
        if goal.tags:
            console.print(f"Tags: {', '.join(goal.tags)}")
        if goal.workflow_id:
            console.print(f"Workflow: {goal.workflow_id}")
        if goal.current_state:
            console.print(f"Workflow State: {goal.current_state}")
        _print_next_steps(
            (
                f"pms project show {goal.project_id} --format json"
                if goal.project_id
                else ""
            ),
            f'pms objective list --goal "{goal.name}"',
            f"pms goal summary {goal.id}",
            f"pms goal update {goal.id}",
        )
    finally:
        await db.disconnect()


@goal.command("update")
@click.argument("goal_ref")
@click.option(
    "--pick",
    is_flag=True,
    help="Pick from matching goals when name is ambiguous",
)
@click.option("--name", help="New goal name")
@click.option("--description", help="New description")
@click.option(
    "--status",
    type=click.Choice(["active", "completed", "on_hold", "archived"]),
)
@click.option(
    "--horizon",
    type=click.Choice(["short_term", "medium_term", "long_term"]),
)
@click.option("--target-date", help="Target date (ISO format)")
@click.option("--owner", help="Goal owner")
@click.option("--clear-owner", is_flag=True, help="Remove goal owner")
@click.option("--product-id", help="Link to product")
@click.option("--project-id", help="Link to project")
@click.option("-t", "--tag", "tags", multiple=True, help="Goal tags")
@click.option("--progress", type=int, help="Progress percent (0-100)")
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json"]),
    default="text",
    show_default=True,
)
@async_command
async def goal_update(
    goal_ref: str,
    pick: bool,
    name: str | None,
    description: str | None,
    status: str | None,
    horizon: str | None,
    target_date: str | None,
    owner: str | None,
    clear_owner: bool,
    product_id: str | None,
    project_id: str | None,
    tags: tuple[str, ...],
    progress: int | None,
    output_format: str,
) -> None:
    """Update a goal."""
    from datetime import datetime

    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.models import GoalHorizon, GoalStatus
    from pms.services.actor_service import ActorService
    from pms.services.goal_service import GoalService

    target_dt = None
    if target_date:
        try:
            target_dt = datetime.fromisoformat(target_date)
        except ValueError:
            _emit_cli_error(
                "Invalid target date format (use ISO)",
                output_format="json" if output_format == "json" else "text",
            )

    if progress is not None and (progress < 0 or progress > 100):
        _emit_cli_error(
            "Progress must be 0-100",
            output_format="json" if output_format == "json" else "text",
        )
    if clear_owner and owner:
        _emit_cli_error(
            "Use --owner or --clear-owner, not both",
            output_format="json" if output_format == "json" else "text",
        )

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        service = GoalService(db, event_store, revision_store, metrics)
        actor_service = ActorService(db, event_store, revision_store, metrics)

        resolved_goal_id = await _resolve_goal_id(goal_ref, service, pick=pick)
        if resolved_goal_id is None:
            return

        status_enum = GoalStatus(status) if status else None
        horizon_enum = GoalHorizon(horizon) if horizon else None
        try:
            updated = await service.update_goal(
                goal_id=resolved_goal_id,
                name=name,
                description=description,
                status=status_enum,
                horizon=horizon_enum,
                target_date=target_dt,
                owner=owner,
                clear_owner=clear_owner,
                product_id=product_id,
                project_id=project_id,
                tags=list(tags) if tags else None,
                progress_percent=progress,
            )
        except ValueError as exc:
            console.print(f"[red]{exc}[/red]")
            return

        if updated is None:
            console.print(f"[red]Goal '{goal_ref}' not found[/red]")
            return

        next_steps = _normalize_next_steps(
            f"pms goal show {updated.id}",
            f'pms objective list --goal "{updated.name}"',
        )
        if output_format == "json":
            owner_map = await _resolve_owner_map([updated], actor_service)
            payload = _payload_with_normalized_next_steps(
                {
                    "goal": {
                        **_public_entity_payload(updated),
                        "ownership": _ownership_payload(updated, owner_map),
                    },
                    "links": _normalize_command_links(
                        {
                            "self": f"goal show {updated.id}",
                            "objectives": f'objective list --goal "{updated.name}"',
                            "owner": _ownership_link(updated, owner_map),
                        }
                    ),
                },
                *next_steps,
            )
            click.echo(json.dumps(payload, default=str))
            return

        console.print(f"[green]Updated goal:[/green] {updated.name}")
        _print_next_steps(*next_steps)
    finally:
        await db.disconnect()


