@goal.command("summary")
@click.argument("goal_ref")
@click.option(
    "--pick",
    is_flag=True,
    help="Pick from matching goals when name is ambiguous",
)
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json", "csv"]),
    default="text",
    show_default=True,
)
@async_command
async def goal_summary(goal_ref: str, pick: bool, output_format: str) -> None:
    """Show goal summary with rollup metrics."""
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.repositories.task_repository import TaskRepository
    from pms.services.actor_service import ActorService
    from pms.services.goal_service import GoalService

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        service = GoalService(db, event_store, revision_store, metrics)
        actor_service = ActorService(db, event_store, revision_store, metrics)
        task_repo = TaskRepository(db, event_store, revision_store, metrics)

        resolved_goal_id = await _resolve_goal_id(goal_ref, service, pick=pick)
        if resolved_goal_id is None:
            return

        summary = await service.get_goal_summary(resolved_goal_id)
        if summary is None:
            console.print(f"[red]Goal '{goal_ref}' not found[/red]")
            return
        owner_map = await _resolve_actor_reference_map(
            [summary.goal.owner_id, summary.goal.owner],
            actor_service,
        )
        focus_task_lookup: dict[str, Any] = {}
        if summary.execution is not None and summary.execution.focus_task is not None:
            focus_task_obj = await task_repo.get_by_id(summary.execution.focus_task.id)
            if focus_task_obj is not None:
                focus_task_lookup[focus_task_obj.id] = focus_task_obj
        focus_assignee_map = await _resolve_assignee_map(
            list(focus_task_lookup.values()),
            actor_service,
        )
        focus_checkout_actor_map = await _resolve_checkout_actor_map(
            list(focus_task_lookup.values()),
            actor_service,
        )

        goal_project_name: str | None = None
        if summary.goal.project_id:
            project_row = await db.fetch_one(
                "SELECT name FROM projects WHERE id = ?",
                (summary.goal.project_id,),
            )
            if project_row is not None:
                goal_project_name = project_row["name"]

        goal_terminal_reason = _goal_terminal_reason_from_summary(summary)
        goal_completion_context = _goal_completion_context_payload(
            goal_id=summary.goal.id,
            project_id=summary.goal.project_id,
            terminal_reason=goal_terminal_reason,
        )
        goal_activity_map = await service.get_last_activity_map([summary.goal.id])
        goal_transition_map = await service.get_last_transition_map([summary.goal.id])
        goal_last_activity = goal_activity_map.get(summary.goal.id)
        goal_last_transition = goal_transition_map.get(summary.goal.id)

        if output_format == "json":
            payload = {
                "goal": _public_entity_payload(summary.goal),
                "stats": _goal_stats_payload(summary),
                "effective_hierarchy": _goal_effective_hierarchy_payload(summary),
                "effective_rollup": _goal_effective_rollup_payload(summary),
                "last_activity_at": _to_iso(goal_last_activity),
                "last_transition_at": _to_iso(goal_last_transition),
                "terminal_reason": goal_terminal_reason,
                "completion_context": goal_completion_context,
                "links": _goal_summary_links(summary.goal),
            }
            payload["goal"]["ownership"] = _actor_reference_payload(
                summary.goal.owner,
                owner_map,
                actor_id=summary.goal.owner_id,
            )
            payload["actor_rollups"] = _actor_rollups_payload(
                owners=[summary.goal],
                tasks=list(focus_task_lookup.values()),
                owner_map=owner_map,
                assignee_map=focus_assignee_map,
                checkout_actor_map=focus_checkout_actor_map,
                population_basis="goal_summary_visible_focus_execution",
            )
            payload["execution"] = _goal_execution_payload(
                summary,
                project_name=goal_project_name,
                task_lookup=focus_task_lookup,
                assignee_map=focus_assignee_map,
                checkout_actor_map=focus_checkout_actor_map,
            )
            payload = _payload_with_normalized_next_steps(
                payload,
                *_goal_lifecycle_next_steps(
                    summary,
                    project_name=goal_project_name,
                    terminal_reason=goal_terminal_reason,
                    primary_surface="summary",
                ),
            )
            click.echo(json.dumps(payload, default=str))
            return

        if output_format == "csv":
            headers = [
                "goal_id",
                "goal_name",
                "goal_status",
                "goal_progress_percent",
                "effective_goal_progress_percent",
                "effective_goal_status",
                "effective_goal_basis",
                "objective_count",
                "completed_objectives",
                "key_result_count",
                "completed_key_results",
                "average_progress",
                "effective_hierarchy_average_progress",
                "effective_hierarchy_basis",
                "execution_total_tasks",
                "execution_completed_tasks",
                "execution_in_progress_tasks",
                "execution_blocked_tasks",
                "execution_average_task_progress",
                "execution_completion_percent",
                "execution_readiness_state",
                "execution_consistency_status",
            ]
            click.echo(_csv_row(headers))
            execution = summary.execution
            row = [
                summary.goal.id,
                summary.goal.name,
                summary.goal.status.value,
                str(summary.goal.progress_percent),
                str(summary.effective_rollup.progress_percent),
                summary.effective_rollup.status,
                summary.effective_rollup.basis,
                str(summary.objective_count),
                str(summary.completed_objectives),
                str(summary.key_result_count),
                str(summary.completed_key_results),
                f"{summary.average_progress:.1f}",
                f"{summary.effective_hierarchy.average_progress:.1f}",
                summary.effective_hierarchy.basis,
                str(execution.total_tasks) if execution is not None else "",
                str(execution.completed_tasks) if execution is not None else "",
                str(execution.in_progress_tasks) if execution is not None else "",
                str(execution.blocked_tasks) if execution is not None else "",
                (
                    f"{execution.average_task_progress:.1f}"
                    if execution is not None
                    else ""
                ),
                f"{execution.completion_percent:.1f}" if execution is not None else "",
                execution.readiness_state if execution is not None else "",
                execution.consistency_status if execution is not None else "",
            ]
            click.echo(_csv_row(row))
            return

        console.print(f"[bold cyan]{summary.goal.name}[/bold cyan]")
        console.print(
            f"Goal State: {summary.goal.status.value} | Progress: {summary.goal.progress_percent}%"
        )
        if (
            summary.effective_rollup.progress_percent != summary.goal.progress_percent
            or summary.effective_rollup.status != summary.goal.status.value
        ):
            console.print(
                "Effective Rollup: "
                f"{summary.effective_rollup.status} | "
                f"{summary.effective_rollup.progress_percent}% "
                f"({summary.effective_rollup.basis})"
            )
            if summary.effective_rollup.reason:
                console.print(f"Effective Reason: {summary.effective_rollup.reason}")
        console.print(
            f"Objectives: {summary.completed_objectives}/{summary.objective_count} | "
            f"Key Results: {summary.completed_key_results}/{summary.key_result_count}"
        )
        console.print(f"Average Progress: {summary.average_progress:.1f}%")
        if (
            summary.effective_hierarchy.average_progress != summary.average_progress
            or summary.effective_hierarchy.basis != "stored_goal"
        ):
            console.print(
                "Effective Hierarchy Progress: "
                f"{summary.effective_hierarchy.average_progress:.1f}% "
                f"({summary.effective_hierarchy.basis})"
            )
            if summary.effective_hierarchy.reason:
                console.print(
                    f"Effective Hierarchy Reason: {summary.effective_hierarchy.reason}"
                )
        if summary.execution is not None:
            console.print(
                "Execution Tasks: "
                f"{summary.execution.completed_tasks}/{summary.execution.total_tasks} done | "
                f"{summary.execution.in_progress_tasks} in progress | "
                f"{summary.execution.blocked_tasks} blocked"
            )
            console.print(
                f"Execution Average Progress: {summary.execution.average_task_progress:.1f}%"
            )
            console.print(
                "Execution Completion: "
                f"{summary.execution.completion_percent:.1f}% | "
                f"Readiness: {summary.execution.readiness_state}"
            )
            console.print(
                "Execution Consistency: "
                f"{summary.execution.consistency_status}"
                + (
                    f" ({summary.execution.consistency_reason})"
                    if summary.execution.consistency_reason
                    else ""
                )
            )
            if summary.execution.focus_task is not None:
                focus_task = summary.execution.focus_task
                task_target = _best_task_command_target(
                    focus_task.id,
                    focus_task.title,
                    goal_project_name,
                )
                console.print(
                    "Execution Focus: "
                    f"{focus_task.title} [{focus_task.status}] "
                    f"({focus_task.current_progress_percent}%)"
                )
                console.print(f"Focus Reason: {focus_task.reason}")
                console.print(
                    "Completion Criteria: "
                    f"{focus_task.completion_criteria_count} defined"
                )
                _print_next_steps(
                    f"pms task show {task_target}",
                    (
                        f"pms task progress {task_target} <percent> <message> --by <user>"
                        if focus_task.status == "in_progress"
                        else ""
                    ),
                    (
                        f"pms task show {task_target} --format json"
                        if focus_task.has_completion_criteria
                        else ""
                    ),
                    (
                        f"pms task unblock {task_target} --by <user>"
                        if focus_task.status == "blocked"
                        else ""
                    ),
                    (
                        f"pms task complete {task_target} --by <user>"
                        if focus_task.status == "in_review"
                        else ""
                    ),
                    (
                        f"pms task start {task_target}"
                        if focus_task.status == "todo"
                        else ""
                    ),
                )
            elif summary.execution.terminal_reason is not None:
                console.print(f"Execution State: {summary.execution.terminal_reason}")
                if goal_completion_context is not None:
                    console.print(goal_completion_context["summary"])
                _print_next_steps(
                    f"pms goal show {summary.goal.id}",
                    (
                        f"pms task list --project {summary.goal.project_id} --format json"
                        if summary.goal.project_id
                        else ""
                    ),
                    "pms goal list --status completed --format json",
                )
    finally:
        await db.disconnect()


@cli.group()
def plan() -> None:
    """Manage plans."""
    pass


@plan.command("create")
@click.argument("name")
@click.option("-d", "--description", help="Plan description")
@click.option(
    "--status",
    type=click.Choice(["draft", "active", "completed", "archived"]),
    default="draft",
)
@click.option(
    "--format",
    "plan_format",
    type=click.Choice(["json", "yaml"]),
    default="json",
)
@click.option("--content", help="Plan content (JSON string or YAML)")
@click.option(
    "--file",
    "content_file",
    type=click.Path(exists=True, dir_okay=False),
    help="Load plan content from file",
)
@click.option("--product", "product_ref", help="Product ID or name")
@click.option("--product-id", help="Link to product")
@click.option("--project", "project_ref", help="Project ID or name")
@click.option("--project-id", help="Link to project")
@click.option("--goal", "goal_ref", help="Link to goal (name or ID)")
@click.option("--goal-id", help="Link to goal")
@click.option("--objective", "objective_ref", help="Link to objective (name or ID)")
@click.option("--objective-id", help="Link to objective")
@click.option("--task-id", "task_ids", multiple=True, help="Link to task IDs")
@click.option("-t", "--tag", "tags", multiple=True, help="Plan tags")
@click.option(
    "--pick",
    is_flag=True,
    help="Pick from matching goals/objectives when name is ambiguous",
)
@click.option(
    "--output-format",
    type=click.Choice(["text", "json"]),
    default="text",
    show_default=True,
    help="Render mutation result as human text or JSON",
)
@async_command
async def plan_create(
    name: str,
    description: str | None,
    status: str,
    plan_format: str,
    content: str | None,
    content_file: str | None,
    product_ref: str | None,
    product_id: str | None,
    project_ref: str | None,
    project_id: str | None,
    goal_ref: str | None,
    goal_id: str | None,
    objective_ref: str | None,
    objective_id: str | None,
    task_ids: tuple[str, ...],
    tags: tuple[str, ...],
    pick: bool,
    output_format: str,
) -> None:
    """Create a new plan."""
    from pathlib import Path

    write_decision = _ensure_runtime_write_mode(
        "pms plan create",
        emit_messages=output_format != "json",
    )
    if write_decision is None:
        return

    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.models import PlanFormat, PlanStatus
    from pms.services.goal_service import GoalService
    from pms.services.plan_service import PlanService
    from pms.services.product_service import ProductService
    from pms.services.project_service import ProjectService

    content_value: str | None = content
    if content_file:
        content_value = Path(content_file).read_text()

    plan_format_enum = PlanFormat(plan_format)
    if content_value is None:
        match plan_format_enum:
            case PlanFormat.JSON:
                content_value = "{}"
            case PlanFormat.YAML:
                _emit_cli_error(
                    "Content required for YAML plans",
                    output_format="json" if output_format == "json" else "text",
                )
            case _:
                _emit_cli_error(
                    "Unsupported plan format",
                    output_format="json" if output_format == "json" else "text",
                )
    elif plan_format_enum == PlanFormat.JSON:
        try:
            json.loads(content_value)
        except json.JSONDecodeError as exc:
            _emit_cli_error(
                f"JSON plan content must be valid JSON: {exc.msg}",
                output_format="json" if output_format == "json" else "text",
            )

    if product_ref and product_id:
        _emit_cli_error(
            "Use --product or --product-id, not both",
            output_format="json" if output_format == "json" else "text",
        )
    if project_ref and project_id:
        _emit_cli_error(
            "Use --project or --project-id, not both",
            output_format="json" if output_format == "json" else "text",
        )
    if goal_ref and goal_id:
        _emit_cli_error(
            "Use --goal or --goal-id, not both",
            output_format="json" if output_format == "json" else "text",
        )
    if objective_ref and objective_id:
        _emit_cli_error(
            "Use --objective or --objective-id, not both",
            output_format="json" if output_format == "json" else "text",
        )

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        goal_service = GoalService(db, event_store, revision_store, metrics)
        service = PlanService(db, event_store, revision_store, metrics)
        product_service = ProductService(db, event_store, revision_store, metrics)
        project_service = ProjectService(db, event_store, revision_store, metrics)

        resolved_product_id = product_id or await _resolve_product_id(
            product_ref, product_service
        )
        if product_ref and resolved_product_id is None:
            return
        resolved_project_id = project_id or await _resolve_project_id(
            project_ref, project_service
        )
        if project_ref and resolved_project_id is None:
            return

        resolved_goal_id = goal_id
        if goal_ref:
            resolved_goal_id = await _resolve_goal_id(goal_ref, goal_service, pick=pick)
            if resolved_goal_id is None:
                return
        resolved_objective_id = objective_id
        if objective_ref:
            objective_goal_ref = goal_id or goal_ref
            resolved_objective_id = await _resolve_objective_id(
                objective_ref, objective_goal_ref, goal_service, pick=pick
            )
            if resolved_objective_id is None:
                return

        try:
            if write_decision.use_server:
                plan_payload = await _delegate_plan_create_to_server(
                    name=name,
                    description=description,
                    status=status,
                    plan_format=plan_format,
                    content=content_value,
                    product_id=resolved_product_id,
                    project_id=resolved_project_id,
                    goal_id=resolved_goal_id,
                    objective_id=resolved_objective_id,
                    task_ids=list(task_ids) if task_ids else None,
                    tags=list(tags) if tags else None,
                )
                plan = await service.get_plan(str(plan_payload["id"]))
                if plan is None:
                    console.print(
                        "[red]Created plan on server but failed to reload it locally[/red]"
                    )
                    return
            else:
                plan = await service.create_plan(
                    name=name,
                    description=description,
                    status=PlanStatus(status),
                    format=plan_format_enum,
                    content=content_value,
                    product_id=resolved_product_id,
                    project_id=resolved_project_id,
                    goal_id=resolved_goal_id,
                    objective_id=resolved_objective_id,
                    task_ids=list(task_ids) if task_ids else None,
                    tags=list(tags) if tags else None,
                )
        except ValueError as exc:
            console.print(f"[red]{exc}[/red]")
            return

        project_label = project_ref
        if not project_label and resolved_project_id:
            project = await project_service.get_project(resolved_project_id)
            project_label = project.name if project else resolved_project_id
        plan_target = _best_plan_command_target(plan.id, plan.name, project_label)
        update_target = plan_target if project_label else '"<name>" --project <name>'
        next_steps = _normalize_next_steps(
            _cli_command(f"plan show {plan_target}"),
            _cli_command(f"plan update {update_target} --task <title>"),
            _cli_command(f"plan lineage --plan {plan_target}"),
        )
        if output_format == "json":
            payload = {
                "plan": plan.to_dict(),
                "runtime_write": _runtime_write_context_payload(write_decision),
                "links": _normalize_command_links(
                    {
                        "self": f"plan show {plan_target}",
                        "lineage": f"plan lineage --plan {plan_target}",
                        "update": f"plan update {update_target} --task <title>",
                    }
                ),
                "next_steps": next_steps,
            }
            click.echo(json.dumps(payload, default=str))
            return

        console.print(f"[green]Created plan:[/green] {plan.name}")
        console.print(f"[dim]ID: {plan.id}[/dim]")
        _print_next_steps(*next_steps)
    finally:
        await db.disconnect()


@plan.command("list")
@click.option(
    "-s",
    "--status",
    type=click.Choice(["draft", "active", "completed", "archived"]),
)
@click.option("--project", "project_ref", help="Project ID or name")
@click.option("--project-id", help="Filter by project")
@click.option("--product", "product_ref", help="Product ID or name")
@click.option("--product-id", help="Filter by product")
@click.option("--goal", "goal_ref", help="Filter by goal name or ID")
@click.option("--goal-id", help="Filter by goal")
@click.option("--objective", "objective_ref", help="Filter by objective name or ID")
@click.option("--objective-id", help="Filter by objective")
@click.option("--task-id", help="Filter by linked task ID")
@click.option(
    "--pick",
    is_flag=True,
    help="Pick from matching goals/objectives when name is ambiguous",
)
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["table", "json", "csv"]),
    default="table",
    show_default=True,
)
@click.option(
    "--view",
    type=click.Choice(["overview", "detail", "trace"]),
    default="overview",
    show_default=True,
    help="Output view profile (overview/detail/trace)",
)
@click.option("--include-history", is_flag=True, help="Include history in JSON")
@click.option("--include-linked", is_flag=True, help="Include linked items in JSON")
@click.option(
    "--include-linked-history",
    is_flag=True,
    help="Include history for linked items in JSON",
)
@click.option("--history-limit", type=int, default=20, show_default=True)
@click.option("--linked-limit", type=int, default=20, show_default=True)
@click.option(
    "--include-generated",
    is_flag=True,
    help="Include audit-generated ephemeral plans in default operator views",
)
@click.option("--limit", type=int, default=100, show_default=True)
@click.option("--offset", type=int, default=0, show_default=True)
@async_command
async def plan_list(
    status: str | None,
    project_ref: str | None,
    project_id: str | None,
    product_ref: str | None,
    product_id: str | None,
    goal_ref: str | None,
    goal_id: str | None,
    objective_ref: str | None,
    objective_id: str | None,
    task_id: str | None,
    pick: bool,
    output_format: str,
    view: str,
    include_history: bool,
    include_linked: bool,
    include_linked_history: bool,
    history_limit: int,
    linked_limit: int,
    include_generated: bool,
    limit: int,
    offset: int,
) -> None:
    """List plans."""
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.models import PlanStatus
    from pms.repositories.goal_repository import GoalRepository
    from pms.repositories.objective_repository import ObjectiveRepository
    from pms.repositories.plan_repository import PlanRepository
    from pms.repositories.product_repository import ProductRepository
    from pms.repositories.project_repository import ProjectRepository
    from pms.repositories.task_repository import TaskRepository
    from pms.services.generated_artifacts import (
        classify_project_operator_category,
    )
    from pms.services.goal_service import GoalService
    from pms.services.plan_service import PlanService
    from pms.services.product_service import ProductService
    from pms.services.project_service import ProjectService

    if product_ref and product_id:
        _emit_cli_error(
            "Use --product or --product-id, not both",
            output_format="json" if output_format == "json" else "text",
        )
    if project_ref and project_id:
        _emit_cli_error(
            "Use --project or --project-id, not both",
            output_format="json" if output_format == "json" else "text",
        )
    if goal_ref and goal_id:
        _emit_cli_error(
            "Use --goal or --goal-id, not both",
            output_format="json" if output_format == "json" else "text",
        )
    if objective_ref and objective_id:
        _emit_cli_error(
            "Use --objective or --objective-id, not both",
            output_format="json" if output_format == "json" else "text",
        )

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        service = PlanService(db, event_store, revision_store, metrics)
        goal_service = GoalService(db, event_store, revision_store, metrics)
        product_service = ProductService(db, event_store, revision_store, metrics)
        project_service = ProjectService(db, event_store, revision_store, metrics)
        plan_repo = PlanRepository(db, event_store, revision_store, metrics)
        project_repo = ProjectRepository(db, event_store, revision_store, metrics)
        product_repo = ProductRepository(db, event_store, revision_store, metrics)
        goal_repo = GoalRepository(db, event_store, revision_store, metrics)
        objective_repo = ObjectiveRepository(db, event_store, revision_store, metrics)
        task_repo = TaskRepository(db, event_store, revision_store, metrics)

        if view == "trace":
            include_history = True
            include_linked = True
        if include_linked_history:
            include_linked = True
            include_history = True

        resolved_product_id = product_id or await _resolve_product_id(
            product_ref, product_service
        )
        if product_ref and resolved_product_id is None:
            return
        resolved_project_id = project_id or await _resolve_project_id(
            project_ref, project_service
        )
        if project_ref and resolved_project_id is None:
            return

        resolved_goal_id = goal_id
        if goal_ref:
            resolved_goal_id = await _resolve_goal_id(goal_ref, goal_service, pick=pick)
            if resolved_goal_id is None:
                return

        resolved_objective_id = objective_id
        if objective_ref:
            objective_goal_ref = resolved_goal_id or goal_ref
            resolved_objective_id = await _resolve_objective_id(
                objective_ref, objective_goal_ref, goal_service, pick=pick
            )
            if resolved_objective_id is None:
                return

        status_filter = PlanStatus(status) if status else None
        suppressed_generated_count = 0
        (
            visible_result,
            result,
            activity_map,
            lifecycle_rollups,
            stored_status_map,
            suppressed_generated_count,
        ) = await _list_plans_for_display(
            service,
            project_repo,
            status=status_filter,
            project_id=resolved_project_id,
            product_id=resolved_product_id,
            goal_id=resolved_goal_id,
            objective_id=resolved_objective_id,
            task_id=task_id,
            limit=limit,
            offset=offset,
            include_generated=include_generated,
        )
        visible_plans = list(visible_result.items)
        display_plans = list(result.items)
        plan_ids = [plan.id for plan in visible_plans]
        transition_map = await service.get_last_transition_map(plan_ids)
        unplanned_population = QueryResult(items=[], total_count=0, offset=0, limit=0)
        unplanned_result = QueryResult(
            items=[], total_count=0, offset=0, limit=max(limit, 5)
        )
        all_unplanned_projects: list[Any] = []
        unplanned_projects: list[Any] = []
        unplanned_activity_map: dict[str, datetime | None] = {}
        unplanned_transition_map: dict[str, datetime | None] = {}
        unplanned_total_category_counts: dict[str, int] = {}
        suppressed_generated_projects_without_plans = 0
        if (
            resolved_project_id is None
            and resolved_product_id is None
            and resolved_goal_id is None
            and resolved_objective_id is None
            and task_id is None
        ):
            (
                unplanned_population,
                unplanned_result,
                unplanned_activity_map,
                unplanned_transition_map,
                unplanned_total_category_counts,
                suppressed_generated_projects_without_plans,
            ) = await _list_projects_without_plans_for_display(
                db,
                project_service,
                limit=max(limit, 5),
                include_generated=include_generated,
            )
            all_unplanned_projects = list(unplanned_population.items)
            unplanned_projects = list(unplanned_result.items)
        project_names: dict[str, str] = {}
        product_names: dict[str, str] = {}
        goal_names: dict[str, str] = {}
        objective_names: dict[str, str] = {}
        for plan in display_plans:
            if plan.project_id and plan.project_id not in project_names:
                project = await project_repo.get_by_id(plan.project_id)
                if project:
                    project_names[plan.project_id] = project.name
            if plan.product_id and plan.product_id not in product_names:
                product = await product_repo.get_by_id(plan.product_id)
                if product:
                    product_names[plan.product_id] = product.name
            if plan.goal_id and plan.goal_id not in goal_names:
                goal = await goal_repo.get_by_id(plan.goal_id)
                if goal:
                    goal_names[plan.goal_id] = goal.name
            if plan.objective_id and plan.objective_id not in objective_names:
                objective = await objective_repo.get_by_id(plan.objective_id)
                if objective:
                    objective_names[plan.objective_id] = objective.name

        freshest_visible_plan_activity = _freshest_plan_timestamp_entry(
            visible_plans,
            activity_map,
            fallback_to_updated_at=True,
        )
        freshest_visible_plan_transition = _freshest_plan_timestamp_entry(
            visible_plans,
            transition_map,
        )
        freshest_visible_project_activity = _freshest_entity_timestamp_entry(
            all_unplanned_projects,
            unplanned_activity_map,
            fallback_to_updated_at=True,
        )
        freshest_visible_project_transition = _freshest_entity_timestamp_entry(
            all_unplanned_projects,
            unplanned_transition_map,
        )
        freshest_visible_activity = freshest_visible_plan_activity
        if freshest_visible_project_activity is not None and (
            freshest_visible_activity is None
            or _sort_timestamp(freshest_visible_project_activity[1])
            > _sort_timestamp(freshest_visible_activity[1])
        ):
            freshest_visible_activity = freshest_visible_project_activity
        freshest_visible_transition = freshest_visible_plan_transition
        if freshest_visible_project_transition is not None and (
            freshest_visible_transition is None
            or _sort_timestamp(freshest_visible_project_transition[1])
            > _sort_timestamp(freshest_visible_transition[1])
        ):
            freshest_visible_transition = freshest_visible_project_transition

        recent_completed_plans: list[Any] = []
        recent_completed_activity_map: dict[str, datetime | None] = {}
        recent_completed_transition_map: dict[str, datetime | None] = {}
        recent_completed_lifecycle_rollups: dict[str, Any] = {}
        recent_completed_stored_status_map: dict[str, str] = {}
        if (
            resolved_project_id is None
            and resolved_product_id is None
            and resolved_goal_id is None
            and resolved_objective_id is None
            and task_id is None
        ):
            (
                _completed_visible_result,
                completed_result,
                recent_completed_activity_map,
                recent_completed_lifecycle_rollups,
                recent_completed_stored_status_map,
                _,
            ) = await _list_plans_for_display(
                service,
                project_repo,
                status=PlanStatus.COMPLETED,
                project_id=None,
                product_id=None,
                goal_id=None,
                objective_id=None,
                task_id=None,
                limit=max(limit, 25),
                offset=0,
                include_generated=include_generated,
            )
            recent_completed_transition_map = await service.get_last_transition_map(
                [plan.id for plan in completed_result.items]
            )
            for completed_plan in completed_result.items:
                if (
                    completed_plan.project_id
                    and completed_plan.project_id not in project_names
                ):
                    project = await project_repo.get_by_id(completed_plan.project_id)
                    if project:
                        project_names[completed_plan.project_id] = project.name
                if (
                    completed_plan.product_id
                    and completed_plan.product_id not in product_names
                ):
                    product = await product_repo.get_by_id(completed_plan.product_id)
                    if product:
                        product_names[completed_plan.product_id] = product.name
                if completed_plan.goal_id and completed_plan.goal_id not in goal_names:
                    goal = await goal_repo.get_by_id(completed_plan.goal_id)
                    if goal:
                        goal_names[completed_plan.goal_id] = goal.name
                if (
                    completed_plan.objective_id
                    and completed_plan.objective_id not in objective_names
                ):
                    objective = await objective_repo.get_by_id(
                        completed_plan.objective_id
                    )
                    if objective:
                        objective_names[completed_plan.objective_id] = objective.name
                recent_completed_plans.append(completed_plan)
                if len(recent_completed_plans) >= 3:
                    break

        next_actions: list[str] = []
        plan_ref_map = (
            _short_id_map([plan.id for plan in display_plans]) if display_plans else {}
        )
        lead_plan = _primary_plan_list_entry(display_plans, activity_map=activity_map)
        if lead_plan is not None:
            lead_plan_ref = plan_ref_map.get(lead_plan.id, lead_plan.id)
            next_actions.append(_cli_command(f"plan show {lead_plan_ref}"))
            next_actions.append(_cli_command(f"plan lineage --plan-id {lead_plan_ref}"))
        project_hint = project_ref or project_id or "<name>"
        next_actions.append(
            _cli_command(
                f"plan create <name> --project \"{project_hint}\" --content '{{}}'"
            )
        )
        plan_focus_candidates: list[Task] = []
        for plan in display_plans:
            if plan.task_ids:
                plan_focus_candidates.extend(
                    await _tasks_with_latest_progress(
                        db, task_repo, list(plan.task_ids)
                    )
                )
        focus_state = _resolve_command_focus_state(plan_focus_candidates, project_names)
        focus_task = focus_state.focus_task
        status_groups = _plan_status_group_counts(display_plans)

        def _plan_project_name(plan_obj: Any) -> str | None:
            return (
                project_names.get(plan_obj.project_id) if plan_obj.project_id else None
            )

        if focus_task is not None:
            next_actions = _normalize_next_steps(
                *focus_task.next_steps(), *next_actions
            )
        else:
            next_actions = _normalize_next_steps(*next_actions)
        if recent_completed_plans and status_groups.get("active", 0) == 0:
            recent_completed_plan = recent_completed_plans[0]
            recent_completed_links, _ = _plan_followup_commands(
                recent_completed_plan.id,
                recent_completed_plan.name,
                _plan_project_name(recent_completed_plan),
            )
            next_actions = _normalize_next_steps(
                *next_actions,
                recent_completed_links["self"],
            )
        plan_list_scope = _instance_scope_summary(
            noun="plan list",
            active_count=status_groups.get("active", 0),
            recent_completed_count=len(recent_completed_plans),
        )
        visible_terminal_plans: list[Any] = []
        if status_groups.get("active", 0) == 0 and status_groups.get("draft", 0) == 0:
            visible_terminal_plans = [
                plan
                for plan in display_plans
                if plan.status in {PlanStatus.COMPLETED, PlanStatus.ARCHIVED}
            ]
        effective_terminal_reason = focus_state.terminal_reason
        if effective_terminal_reason is None and visible_terminal_plans:
            effective_terminal_reason = "all surfaced plans are already terminal"
        completion_context: dict[str, Any] | None = None
        completion_source = recent_completed_plans or visible_terminal_plans[:3]
        if completion_source:
            completion_summary = (
                "Recently completed plans remain terminal even though unrelated "
                "active or draft plans still exist elsewhere in this instance."
            )
            if status_groups.get("active", 0) == 0:
                completion_summary = (
                    "Recently completed plans remain terminal. No other visible active "
                    "or draft plans are currently surfaced in the default operator view."
                )
            completion_context = {
                "summary": completion_summary,
                "items": [
                    {
                        "id": plan.id,
                        "name": plan.name,
                        "project_name": _plan_project_name(plan),
                        "next_steps": _normalize_next_steps(
                            _plan_followup_commands(
                                plan.id,
                                plan.name,
                                _plan_project_name(plan),
                            )[0]["self"]
                        ),
                    }
                    for plan in completion_source
                ],
            }

        unplanned_payloads = [
            _project_surface_payload(
                project,
                operator_category=classify_project_operator_category(project),
                last_activity_at=unplanned_activity_map.get(project.id),
                last_transition_at=unplanned_transition_map.get(project.id),
                links={
                    "self": _cli_command(f"project show {project.id} --format json"),
                },
            )
            for project in unplanned_projects
        ]
        unplanned_payloads_by_category = _project_payloads_by_operator_category(
            unplanned_payloads
        )
        unplanned_visible_category_counts = {
            category: len(entries)
            for category, entries in unplanned_payloads_by_category.items()
        }

        if output_format == "json":
            effective_history_limit = history_limit if history_limit > 0 else 1000
            effective_linked_limit = linked_limit if linked_limit > 0 else 1000
            visible_plan_ids = {plan.id for plan in visible_plans}

            def _plan_links(plan_obj) -> dict[str, str]:
                return _plan_followup_commands(
                    plan_obj.id,
                    plan_obj.name,
                    project_names.get(plan_obj.project_id)
                    if plan_obj.project_id
                    else None,
                )[0]

            payload_items = []
            for plan in display_plans:
                last_activity = activity_map.get(plan.id)
                last_transition = transition_map.get(plan.id)
                lifecycle_rollup = lifecycle_rollups.get(plan.id)
                project_name = (
                    project_names.get(plan.project_id) if plan.project_id else None
                )
                product_name = (
                    product_names.get(plan.product_id) if plan.product_id else None
                )
                goal_name = goal_names.get(plan.goal_id) if plan.goal_id else None
                objective_name = (
                    objective_names.get(plan.objective_id)
                    if plan.objective_id
                    else None
                )
                base_payload = _plan_surface_payload(
                    plan,
                    stored_status=stored_status_map.get(plan.id),
                    project_name=project_name,
                    product_name=product_name,
                    goal_name=goal_name,
                    objective_name=objective_name,
                    last_activity_at=last_activity,
                    last_transition_at=last_transition,
                    terminal_reason=(
                        lifecycle_rollup.terminal_reason
                        if lifecycle_rollup is not None
                        else None
                    ),
                    links=_plan_links(plan),
                )
                if view == "overview":
                    payload = dict(base_payload)
                else:
                    payload = plan.to_dict()
                    payload.update(base_payload)

                if include_linked:
                    task_ids = list(plan.task_ids or [])[:effective_linked_limit]
                    tasks = (
                        await _tasks_with_latest_progress(db, task_repo, task_ids)
                        if task_ids
                        else []
                    )
                    payload["linked"] = {
                        "tasks": [
                            {
                                "id": task.id,
                                "title": task.title,
                                "status": task.status.value,
                                "updated_at": _to_iso(task.updated_at),
                                "links": _normalize_command_links(
                                    {
                                        "self": _cli_command(f"task show {task.id}"),
                                    }
                                ),
                            }
                            for task in tasks
                        ],
                        "page": {
                            "total_count": len(plan.task_ids),
                            "limit": min(effective_linked_limit, len(plan.task_ids)),
                            "offset": 0,
                            "has_more": len(plan.task_ids) > effective_linked_limit,
                            "next_offset": effective_linked_limit
                            if len(plan.task_ids) > effective_linked_limit
                            else None,
                        },
                    }
                    if include_linked_history:
                        payload["linked_history"] = {
                            task.id: [
                                {
                                    "revision_number": rev.revision_number,
                                    "change_type": rev.change_type.value,
                                    "message": rev.message,
                                    "created_by": rev.created_by,
                                    "created_at": rev.created_at,
                                }
                                for rev in await task_repo.get_history(
                                    task.id, limit=effective_history_limit
                                )
                            ]
                            for task in tasks
                        }

                if include_history:
                    history = await plan_repo.get_history(
                        plan.id, limit=effective_history_limit
                    )
                    payload["history"] = [
                        {
                            "revision_number": rev.revision_number,
                            "change_type": rev.change_type.value,
                            "message": rev.message,
                            "created_by": rev.created_by,
                            "created_at": rev.created_at,
                        }
                        for rev in history
                    ]

                payload_items.append(payload)

            base_cmd = _cli_command("plan list --format json")
            if status:
                base_cmd += f" --status {status}"
            if resolved_project_id:
                base_cmd += f" --project-id {resolved_project_id}"
            if resolved_product_id:
                base_cmd += f" --product-id {resolved_product_id}"
            if resolved_goal_id:
                base_cmd += f" --goal-id {resolved_goal_id}"
            if resolved_objective_id:
                base_cmd += f" --objective-id {resolved_objective_id}"
            if task_id:
                base_cmd += f" --task-id {task_id}"
            if view != "overview":
                base_cmd += f" --view {view}"
            payload = {
                "items": payload_items,
                "scope": {
                    "kind": "instance_plan_list",
                    "summary": plan_list_scope,
                    "active_visible_plans": status_groups.get("active", 0),
                    "recently_completed_plans": len(recent_completed_plans),
                },
                "freshest_visible_activity": (
                    {
                        "kind": (
                            "plan"
                            if freshest_visible_activity[0].id in visible_plan_ids
                            else "project_without_plan"
                        ),
                        "plan_id": (
                            freshest_visible_activity[0].id
                            if freshest_visible_activity[0].id in visible_plan_ids
                            else None
                        ),
                        "plan_name": (
                            freshest_visible_activity[0].name
                            if freshest_visible_activity[0].id in visible_plan_ids
                            else None
                        ),
                        "project_id": (
                            freshest_visible_activity[0].project_id
                            if freshest_visible_activity[0].id in visible_plan_ids
                            else freshest_visible_activity[0].id
                        ),
                        "project_name": (
                            project_names.get(freshest_visible_activity[0].project_id)
                            if freshest_visible_activity[0].id in visible_plan_ids
                            and freshest_visible_activity[0].project_id
                            else freshest_visible_activity[0].name
                        ),
                        "last_activity_at": _to_iso(freshest_visible_activity[1]),
                    }
                    if freshest_visible_activity is not None
                    else None
                ),
                "freshest_visible_transition": (
                    {
                        "kind": (
                            "plan"
                            if freshest_visible_transition[0].id in visible_plan_ids
                            else "project_without_plan"
                        ),
                        "plan_id": (
                            freshest_visible_transition[0].id
                            if freshest_visible_transition[0].id in visible_plan_ids
                            else None
                        ),
                        "plan_name": (
                            freshest_visible_transition[0].name
                            if freshest_visible_transition[0].id in visible_plan_ids
                            else None
                        ),
                        "project_id": (
                            freshest_visible_transition[0].project_id
                            if freshest_visible_transition[0].id in visible_plan_ids
                            else freshest_visible_transition[0].id
                        ),
                        "project_name": (
                            project_names.get(freshest_visible_transition[0].project_id)
                            if freshest_visible_transition[0].id in visible_plan_ids
                            and freshest_visible_transition[0].project_id
                            else freshest_visible_transition[0].name
                        ),
                        "last_transition_at": _to_iso(freshest_visible_transition[1]),
                    }
                    if freshest_visible_transition is not None
                    else None
                ),
                "projects_without_plans": [*unplanned_payloads],
                "projects_without_plans_by_category": unplanned_payloads_by_category,
                "projects_without_plans_summary": {
                    "displayed_count": len(unplanned_payloads),
                    "total_count": unplanned_result.total_count,
                    "limit": unplanned_result.limit,
                    "is_truncated": unplanned_result.total_count
                    > len(unplanned_payloads),
                    "displayed_category_counts": unplanned_visible_category_counts,
                    "total_category_counts": unplanned_total_category_counts,
                    "suppressed_generated_count": (
                        suppressed_generated_projects_without_plans
                    ),
                },
                "completion_context": completion_context,
                "focus_task": focus_task.to_payload()
                if focus_task is not None
                else None,
                "terminal_reason": effective_terminal_reason,
                "status_groups": status_groups,
                "items_by_status": {
                    status_key: [
                        item for item in payload_items if item["status"] == status_key
                    ]
                    for status_key in ("active", "draft", "completed", "archived")
                },
                "recently_completed_plans": [
                    _plan_surface_payload(
                        plan,
                        stored_status=recent_completed_stored_status_map.get(plan.id),
                        project_name=(
                            project_names.get(plan.project_id)
                            if plan.project_id
                            else None
                        ),
                        product_name=(
                            product_names.get(plan.product_id)
                            if plan.product_id
                            else None
                        ),
                        goal_name=goal_names.get(plan.goal_id)
                        if plan.goal_id
                        else None,
                        objective_name=(
                            objective_names.get(plan.objective_id)
                            if plan.objective_id
                            else None
                        ),
                        last_activity_at=recent_completed_activity_map.get(plan.id),
                        last_transition_at=recent_completed_transition_map.get(plan.id),
                        terminal_reason=(
                            recent_completed_lifecycle_rollups.get(
                                plan.id
                            ).terminal_reason
                            if recent_completed_lifecycle_rollups.get(plan.id)
                            is not None
                            else None
                        ),
                        links=_plan_links(plan),
                    )
                    for plan in recent_completed_plans
                ],
                "page": {
                    "total_count": result.total_count,
                    "limit": result.limit,
                    "offset": result.offset,
                    "has_more": result.has_more,
                    "next_offset": result.offset + result.limit
                    if result.has_more
                    else None,
                },
                "suppressed_generated_count": suppressed_generated_count,
                "links": _normalize_command_links(
                    {
                        "self": f"{base_cmd} --limit {limit} --offset {offset}",
                        "next": (
                            f"{base_cmd} --limit {limit} "
                            f"--offset {result.offset + result.limit}"
                            if result.has_more
                            else None
                        ),
                    }
                ),
                "next_steps": next_actions,
            }
            payload = _payload_with_normalized_next_steps(payload, *next_actions)
            click.echo(json.dumps(payload, indent=2, default=str))
            return

        if output_format == "csv":
            headers = [
                "id",
                "name",
                "status",
                "format",
                "project_id",
                "project_name",
                "goal_id",
                "goal_name",
                "objective_id",
                "objective_name",
                "task_count",
                "updated_at",
                "last_activity_at",
                "last_transition_at",
            ]
            click.echo(_csv_row(headers))
            for p in display_plans:
                last_activity = activity_map.get(p.id)
                last_transition = transition_map.get(p.id)
                row = [
                    p.id,
                    p.name,
                    p.status.value,
                    p.format.value,
                    p.project_id or "",
                    project_names.get(p.project_id, "") if p.project_id else "",
                    p.goal_id or "",
                    goal_names.get(p.goal_id, "") if p.goal_id else "",
                    p.objective_id or "",
                    objective_names.get(p.objective_id, "") if p.objective_id else "",
                    str(len(p.task_ids)),
                    str(p.updated_at)[:19] if p.updated_at else "",
                    _to_iso(last_activity) or "",
                    _to_iso(last_transition) or "",
                ]
                click.echo(_csv_row(row))
            return

        from pms.utils.time import format_relative

        console.print(f"Scope: {plan_list_scope}")
        grouped_plans = _plans_by_status(display_plans)
        has_effective_status_mismatch = any(
            stored_status_map.get(plan.id) not in {None, plan.status.value}
            for plan in display_plans
        )
        status_titles = {
            "active": "Active Plans",
            "draft": "Draft Plans",
            "completed": "Completed Plans",
            "archived": "Archived Plans",
        }
        for status_key in ("active", "draft", "completed", "archived"):
            plans_for_status = grouped_plans.get(status_key, [])
            console.print(f"[bold]{status_titles[status_key]}[/bold]")
            console.print(f"[dim]{len(plans_for_status)} visible[/dim]")
            if not plans_for_status:
                console.print("[dim](none)[/dim]")
                console.print()
                continue
            show_format_column = len({p.format.value for p in plans_for_status}) > 1
            table = Table()
            table.add_column("Ref", style="cyan")
            table.add_column("Name", style="cyan")
            table.add_column("Status")
            if show_format_column:
                table.add_column("Format")
            table.add_column("Project")
            table.add_column("Goal")
            table.add_column("Objective")
            table.add_column("Tasks")
            table.add_column("Activity")
            table.add_column("Last Transition")
            for p in plans_for_status:
                last_activity = activity_map.get(p.id)
                last_transition = transition_map.get(p.id)
                project_label = (
                    project_names.get(p.project_id, p.project_id)
                    if p.project_id
                    else "-"
                )
                goal_label = goal_names.get(p.goal_id, p.goal_id) if p.goal_id else "-"
                objective_label = (
                    objective_names.get(p.objective_id, p.objective_id)
                    if p.objective_id
                    else "-"
                )
                row = [
                    plan_ref_map.get(p.id, p.id),
                    p.name,
                    (
                        f"{p.status.value}*"
                        if stored_status_map.get(p.id) not in {None, p.status.value}
                        else p.status.value
                    ),
                    project_label,
                    goal_label,
                    objective_label,
                    str(len(p.task_ids)),
                    format_relative(last_activity or p.updated_at),
                    format_relative(last_transition),
                ]
                if show_format_column:
                    row.insert(3, p.format.value)
                table.add_row(*row)
            console.print(table)
            console.print()
        if has_effective_status_mismatch:
            console.print(
                "[dim]* status shown is the derived graph lifecycle, not the stale stored plan row[/dim]"
            )
            console.print()
        if unplanned_projects:
            console.print("[bold]Projects Without Plans[/bold]")
            console.print(
                f"[dim]{len(unplanned_payloads)} visible[/dim]"
                + (
                    f" [dim](top {len(unplanned_payloads)} of {unplanned_result.total_count} by bubbled recency)[/dim]"
                    if unplanned_result.total_count > len(unplanned_payloads)
                    else ""
                )
            )
            from pms.services.generated_artifacts import project_operator_category_label

            for category, entries in unplanned_payloads_by_category.items():
                category_total = unplanned_total_category_counts.get(category, 0)
                console.print(
                    f"[bold]{project_operator_category_label(category)}[/bold]"
                    f" [dim]({len(entries)} visible"
                    + (
                        f" / {category_total} total"
                        if category_total != len(entries)
                        else ""
                    )
                    + ")[/dim]"
                )
                table = Table()
                table.add_column("Ref", style="cyan")
                table.add_column("Name", style="cyan")
                table.add_column("Status")
                table.add_column("Activity")
                table.add_column("Last Transition")
                for entry in entries:
                    table.add_row(
                        str(entry["id"])[:8],
                        str(entry["name"]),
                        str(entry["status"]),
                        format_relative(entry["last_activity_at"]),
                        format_relative(entry["last_transition_at"]),
                    )
                console.print(table)
            console.print(
                "[dim]These projects have fresh graph activity but no persisted plan row, so they are invisible as plan entries unless surfaced here.[/dim]"
            )
            if suppressed_generated_projects_without_plans:
                console.print(
                    "[dim]Suppressed generated planless projects: "
                    f"{suppressed_generated_projects_without_plans} "
                    "(use --include-generated to show)[/dim]"
                )
            console.print()
        elif suppressed_generated_projects_without_plans:
            console.print(
                "[dim]Suppressed generated planless projects: "
                f"{suppressed_generated_projects_without_plans} "
                "(use --include-generated to show)[/dim]"
            )
        console.print(f"[dim]Total: {len(display_plans)}[/dim]")
        console.print(
            "[dim]"
            f"Status groups: active {status_groups.get('active', 0)} | "
            f"draft {status_groups.get('draft', 0)} | "
            f"completed {status_groups.get('completed', 0)} | "
            f"archived {status_groups.get('archived', 0)}"
            "[/dim]"
        )
        if freshest_visible_activity is not None:
            freshest_item, freshest_timestamp = freshest_visible_activity
            if freshest_item in display_plans:
                freshest_project = (
                    project_names.get(freshest_item.project_id)
                    if freshest_item.project_id
                    else None
                )
                project_suffix = f" [{freshest_project}]" if freshest_project else ""
                freshest_label = f"{freshest_item.name}{project_suffix}"
            else:
                freshest_label = f"{freshest_item.name} (project without plan)"
            console.print(
                "Freshest Visible Activity: "
                f"{freshest_label} "
                f"({format_relative(freshest_timestamp)})"
            )
        if freshest_visible_transition is not None:
            freshest_item, freshest_timestamp = freshest_visible_transition
            if freshest_item in display_plans:
                freshest_project = (
                    project_names.get(freshest_item.project_id)
                    if freshest_item.project_id
                    else None
                )
                project_suffix = f" [{freshest_project}]" if freshest_project else ""
                freshest_label = f"{freshest_item.name}{project_suffix}"
            else:
                freshest_label = f"{freshest_item.name} (project without plan)"
            console.print(
                "Freshest Visible Transition: "
                f"{freshest_label} "
                f"({format_relative(freshest_timestamp)})"
            )
        if suppressed_generated_count:
            console.print(
                f"[dim]Suppressed generated plans: {suppressed_generated_count} "
                f"(use --include-generated to show)[/dim]"
            )
        if recent_completed_plans:
            console.print("[bold]Recently Completed Plans:[/bold]")
            for plan in recent_completed_plans:
                project_name = _plan_project_name(plan)
                project_suffix = f" [{project_name}]" if project_name else ""
                console.print(
                    f"- {plan.name}{project_suffix} "
                    f"(updated {format_relative(recent_completed_activity_map.get(plan.id) or plan.updated_at)})"
                )
            console.print(
                "Completed-scope shortcuts: "
                + ", ".join(
                    _plan_followup_commands(
                        plan.id,
                        plan.name,
                        _plan_project_name(plan),
                    )[0]["self"]
                    for plan in recent_completed_plans
                )
            )
        if focus_task is not None:
            console.print(
                "Execution Focus: "
                f"{focus_task.title} [{focus_task.status_value}] "
                f"({focus_task.current_progress_percent}%)"
            )
            console.print(f"Focus Reason: {focus_task.reason}")
        elif effective_terminal_reason is not None:
            console.print(f"Execution State: {effective_terminal_reason}")
            if completion_context is not None:
                console.print(completion_context["summary"])
        _print_next_steps(*next_actions)
    finally:
        await db.disconnect()


@plan.command("lineage")
@click.option(
    "-s",
    "--status",
    type=click.Choice(["draft", "active", "completed", "archived"]),
)
@click.option("--project", "project_ref", help="Filter by project name or ID")
@click.option("--project-id", help="Filter by project")
@click.option("--plan", "plan_ref", help="Filter by plan name or ID")
@click.option("--plan-id", help="Filter by plan ID")
@click.option(
    "--pick",
    is_flag=True,
    help="Pick from matching plans when name is ambiguous",
)
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["table", "json", "csv"]),
    default="table",
    show_default=True,
)
@click.option("--task-limit", default=10, show_default=True, type=int)
@click.option("--test-limit", default=5, show_default=True, type=int)
@async_command
async def plan_lineage(
    status: str | None,
    project_ref: str | None,
    project_id: str | None,
    plan_ref: str | None,
    plan_id: str | None,
    pick: bool,
    output_format: str,
    task_limit: int,
    test_limit: int,
) -> None:
    """Show plan → task → test lineage dashboard."""
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.models import PlanStatus
    from pms.repositories import ProjectRepository
    from pms.repositories.task_repository import TaskRepository
    from pms.services.lineage_service import LineageService
    from pms.services.plan_service import PlanService
    from pms.services.project_service import ProjectService
    from pms.utils.time import format_relative

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        service = LineageService(db, event_store, revision_store, metrics)
        plan_service = PlanService(db, event_store, revision_store, metrics)
        project_repo = ProjectRepository(db, event_store, revision_store, metrics)
        task_repo = TaskRepository(db, event_store, revision_store, metrics)
        project_service = ProjectService(db, event_store, revision_store, metrics)

        if project_ref and project_id:
            _emit_cli_error(
                "Use --project or --project-id, not both",
                output_format="json" if output_format == "json" else "text",
            )
        if plan_ref and plan_id:
            _emit_cli_error(
                "Use --plan or --plan-id, not both",
                output_format="json" if output_format == "json" else "text",
            )
        resolved_project_id = project_id or await _resolve_project_id(
            project_ref, project_service
        )
        if project_ref and resolved_project_id is None:
            return
        resolved_plan_id = plan_id
        if plan_ref:
            resolved_plan_id = await _resolve_plan_id(
                plan_ref,
                project_ref or resolved_project_id,
                plan_service,
                project_service,
                pick=pick,
            )
            if resolved_plan_id is None:
                return

        status_filter = PlanStatus(status) if status else None
        dashboard = await service.get_plan_lineage_dashboard(
            status=status_filter,
            project_id=resolved_project_id,
            plan_id=resolved_plan_id,
            task_limit=task_limit,
            test_limit=test_limit,
        )
        lineage_stored_statuses = {
            item.plan.id: item.stored_status or item.plan.status.value
            for item in dashboard.items
        }

        project_names: dict[str, str] = {}
        for item in dashboard.items:
            if item.plan.project_id and item.plan.project_id not in project_names:
                project = await project_repo.get_by_id(item.plan.project_id)
                if project:
                    project_names[item.plan.project_id] = project.name

        lineage_focus_ids = [
            task_id for item in dashboard.items for task_id in item.plan.task_ids
        ]
        lineage_focus_tasks = (
            await _tasks_with_latest_progress(db, task_repo, lineage_focus_ids)
            if lineage_focus_ids
            else []
        )
        for task in lineage_focus_tasks:
            if task.project_id and task.project_id not in project_names:
                project = await project_repo.get_by_id(task.project_id)
                if project:
                    project_names[task.project_id] = project.name

        focus_state = _resolve_command_focus_state(lineage_focus_tasks, project_names)
        focus_task = focus_state.focus_task
        lineage_terminal_reason = focus_state.terminal_reason
        if lineage_terminal_reason is None and dashboard.items:
            if len(dashboard.items) == 1 and dashboard.items[0].terminal_reason:
                lineage_terminal_reason = dashboard.items[0].terminal_reason
            elif all(
                item.plan.status in {PlanStatus.COMPLETED, PlanStatus.ARCHIVED}
                for item in dashboard.items
            ):
                lineage_terminal_reason = "all surfaced plans are already terminal"
        lineage_next_steps: list[str] = []
        if focus_task is not None:
            lineage_next_steps.extend(focus_task.next_steps())
        lead_plan = dashboard.items[0].plan if dashboard.items else None
        if lead_plan is not None:
            lineage_next_steps.extend(
                [
                    _cli_command(f"plan show {lead_plan.id}"),
                    _cli_command(f"plan test-job list {lead_plan.id} --format json"),
                ]
            )
        else:
            lineage_next_steps.append(_cli_command("plan list --format json"))
        lineage_next_steps = _normalize_next_steps(*lineage_next_steps)

        if output_format == "json":
            base_cmd = _cli_command("plan lineage --format json")
            if status:
                base_cmd += f" --status {status}"
            if resolved_project_id:
                base_cmd += f" --project-id {resolved_project_id}"
            if resolved_plan_id:
                base_cmd += f" --plan-id {resolved_plan_id}"
            payload = {
                "items": [
                    {
                        "plan": _plan_surface_payload(
                            item.plan,
                            stored_status=lineage_stored_statuses.get(item.plan.id),
                            project_name=(
                                project_names.get(item.plan.project_id)
                                if item.plan.project_id
                                else None
                            ),
                            last_activity_at=item.last_activity_at,
                            last_transition_at=item.last_transition_at,
                            terminal_reason=item.terminal_reason,
                            links={
                                "self": _cli_command(
                                    f"plan show {item.plan.id} --format json"
                                ),
                                "lineage": _cli_command(
                                    f"plan lineage --plan-id {item.plan.id} --format json"
                                ),
                            },
                        ),
                        "links": _normalize_command_links(
                            {
                                "plan": _cli_command(f"plan show {item.plan.id}"),
                                "lineage": _cli_command(
                                    f"plan lineage --plan-id {item.plan.id} --format json"
                                ),
                            }
                        ),
                        "stats": {
                            "total_tasks": item.total_tasks,
                            "completed_tasks": item.completed_tasks,
                            "blocked_tasks": item.blocked_tasks,
                            "total_test_runs": item.total_test_runs,
                            "latest_test_success": item.latest_test_success,
                            "latest_test_run_id": item.latest_test_run_id,
                        },
                        "last_activity_at": _to_iso(item.last_activity_at),
                        "last_transition_at": _to_iso(item.last_transition_at),
                        "evidence": {
                            "total": item.evidence.total,
                            "types": item.evidence.types,
                            "code_total": item.evidence.code_total,
                            "latest_code_reference": item.evidence.latest_code_reference,
                            "latest_code_created_at": item.evidence.latest_code_created_at,
                        },
                        "tasks": [task.__dict__ for task in item.tasks],
                        "test_runs": [
                            {
                                **run.__dict__,
                                "task_ids": list(run.task_ids),
                            }
                            for run in item.test_runs
                        ],
                    }
                    for item in dashboard.items
                ],
                "totals": {
                    "total_plans": dashboard.total_plans,
                    "total_tasks": dashboard.total_tasks,
                    "total_test_runs": dashboard.total_test_runs,
                    "failed_test_runs": dashboard.failed_test_runs,
                    "total_evidence": dashboard.total_evidence,
                    "total_code_evidence": dashboard.total_code_evidence,
                },
                "focus_task": (
                    focus_task.to_payload() if focus_task is not None else None
                ),
                "terminal_reason": lineage_terminal_reason,
                "links": _normalize_command_links(
                    {
                        "self": base_cmd,
                        "plan": _cli_command(f"plan show {lead_plan.id}")
                        if lead_plan
                        else None,
                    }
                ),
                "next_steps": lineage_next_steps,
            }
            payload = _payload_with_normalized_next_steps(
                payload,
                *lineage_next_steps,
            )
            click.echo(json.dumps(payload, indent=2, default=str))
            return

        if output_format == "csv":
            headers = [
                "plan_id",
                "plan_name",
                "status",
                "project_id",
                "tasks_completed",
                "tasks_total",
                "blocked_tasks",
                "latest_test_success",
                "total_test_runs",
                "evidence_total",
                "code_evidence_total",
                "latest_code_reference",
                "last_activity_at",
                "last_transition_at",
            ]
            click.echo(_csv_row(headers))
            for item in dashboard.items:
                row = [
                    item.plan.id,
                    item.plan.name,
                    item.plan.status.value,
                    item.plan.project_id or "",
                    str(item.completed_tasks),
                    str(item.total_tasks),
                    str(item.blocked_tasks),
                    str(item.latest_test_success),
                    str(item.total_test_runs),
                    str(item.evidence.total),
                    str(item.evidence.code_total),
                    item.evidence.latest_code_reference or "",
                    _to_iso(item.last_activity_at) or "",
                    _to_iso(item.last_transition_at) or "",
                ]
                click.echo(_csv_row(row))
            return

        table = Table(title="Plan Lineage")
        lineage_ref_map = (
            _short_id_map([item.plan.id for item in dashboard.items])
            if dashboard.items
            else {}
        )
        table.add_column("Ref", style="cyan")
        table.add_column("Plan", style="cyan")
        table.add_column("Status")
        table.add_column("Project")
        table.add_column("Tasks")
        table.add_column("Blocked")
        table.add_column("Evidence")
        table.add_column("Latest Test")
        table.add_column("Test Runs")
        table.add_column("Activity")
        table.add_column("Transition")
        for item in dashboard.items:
            test_status = (
                "passed"
                if item.latest_test_success is True
                else "failed"
                if item.latest_test_success is False
                else "-"
            )
            table.add_row(
                lineage_ref_map.get(item.plan.id, item.plan.id),
                item.plan.name,
                (
                    f"{item.plan.status.value}*"
                    if lineage_stored_statuses.get(item.plan.id)
                    not in {None, item.plan.status.value}
                    else item.plan.status.value
                ),
                (
                    f"{project_names[item.plan.project_id]} ({item.plan.project_id})"
                    if item.plan.project_id in project_names
                    else item.plan.project_id or "-"
                ),
                f"{item.completed_tasks}/{item.total_tasks}",
                str(item.blocked_tasks),
                f"{item.evidence.code_total}/{item.evidence.total}",
                test_status,
                str(item.total_test_runs),
                format_relative(item.last_activity_at),
                format_relative(item.last_transition_at),
            )
        console.print(table)
        console.print(f"[dim]Total plans: {dashboard.total_plans}[/dim]")
        if focus_task is not None:
            console.print(
                "Execution Focus: "
                f"{focus_task.title} [{focus_task.status_value}] "
                f"({focus_task.current_progress_percent}%)"
            )
            console.print(f"Focus Reason: {focus_task.reason}")
        elif lineage_terminal_reason is not None:
            console.print(f"Execution State: {lineage_terminal_reason}")
        _print_next_steps(*lineage_next_steps)
    finally:
        await db.disconnect()


@plan.command("show")
@click.argument("plan_ref")
@click.option("--project", "project_ref", help="Project name or ID for lookup")
@click.option(
    "--pick",
    is_flag=True,
    help="Pick from matching plans when name is ambiguous",
)
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json"]),
    default="text",
    show_default=True,
)
@click.option(
    "--view",
    type=click.Choice(["overview", "detail", "trace"]),
    default="detail",
    show_default=True,
    help="Output view profile (overview/detail/trace)",
)
@click.option("--include-history", is_flag=True, help="Include history in JSON")
@click.option("--include-linked", is_flag=True, help="Include linked items in JSON")
@click.option(
    "--include-linked-history",
    is_flag=True,
    help="Include history for linked items in JSON",
)
@click.option("--history-limit", type=int, default=20, show_default=True)
@click.option("--linked-limit", type=int, default=20, show_default=True)
@async_command
async def plan_show(
    plan_ref: str,
    project_ref: str | None,
    pick: bool,
    output_format: str,
    view: str,
    include_history: bool,
    include_linked: bool,
    include_linked_history: bool,
    history_limit: int,
    linked_limit: int,
) -> None:
    """Show plan details."""
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.repositories import ProjectRepository
    from pms.repositories.goal_repository import GoalRepository
    from pms.repositories.objective_repository import ObjectiveRepository
    from pms.repositories.plan_repository import PlanRepository
    from pms.repositories.product_repository import ProductRepository
    from pms.repositories.task_repository import TaskRepository
    from pms.services.actor_service import ActorService
    from pms.services.plan_service import PlanService
    from pms.services.project_service import ProjectService
    from pms.utils.time import format_relative

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        service = PlanService(db, event_store, revision_store, metrics)
        project_service = ProjectService(db, event_store, revision_store, metrics)
        actor_service = ActorService(db, event_store, revision_store, metrics)
        project_repo = ProjectRepository(db, event_store, revision_store, metrics)
        goal_repo = GoalRepository(db, event_store, revision_store, metrics)
        objective_repo = ObjectiveRepository(db, event_store, revision_store, metrics)
        plan_repo = PlanRepository(db, event_store, revision_store, metrics)
        product_repo = ProductRepository(db, event_store, revision_store, metrics)
        task_repo = TaskRepository(db, event_store, revision_store, metrics)

        if view == "trace":
            include_history = True
            include_linked = True
        if include_linked_history:
            include_linked = True
            include_history = True

        resolved_plan_id = await _resolve_plan_id(
            plan_ref, project_ref, service, project_service, pick=pick
        )
        if resolved_plan_id is None:
            return
        plan = await service.get_plan(resolved_plan_id)
        if plan is None:
            console.print(f"[red]Plan '{plan_ref}' not found[/red]")
            return

        last_activity = (await service.get_last_activity_map([plan])).get(plan.id)
        last_transition = (await service.get_last_transition_map([plan.id])).get(
            plan.id
        )
        lifecycle_rollup = (await service.get_lifecycle_rollup_map([plan])).get(plan.id)
        stored_status_value = plan.status.value
        if lifecycle_rollup is not None:
            plan = replace(plan, status=lifecycle_rollup.effective_status)

        goal_name = None
        objective_name = None
        goal = None
        objective = None
        if plan.goal_id:
            goal = await goal_repo.get_by_id(plan.goal_id)
            if goal:
                goal_name = goal.name
        if plan.objective_id:
            objective = await objective_repo.get_by_id(plan.objective_id)
            if objective:
                objective_name = objective.name
        project_name = None
        if plan.project_id:
            project = await project_repo.get_by_id(plan.project_id)
            if project:
                project_name = project.name
        project_label = project_name or plan.project_id
        plan_target = _best_plan_command_target(plan.id, plan.name, project_label)
        update_target = plan_target if plan.project_id else '"<name>" --project <name>'
        linked_tasks = (
            await _tasks_with_latest_progress(db, task_repo, list(plan.task_ids))
            if plan.task_ids
            else []
        )
        focus_state = _resolve_command_focus_state(
            linked_tasks,
            {plan.project_id: project_name} if plan.project_id else {},
        )
        focus_task = focus_state.focus_task
        linked_task_lookup = {task.id: task for task in linked_tasks}
        linked_assignee_map = await _resolve_assignee_map(
            list(linked_tasks),
            actor_service,
        )
        linked_checkout_actor_map = await _resolve_checkout_actor_map(
            list(linked_tasks),
            actor_service,
        )
        focus_task_payload = _focus_task_payload_with_assignee(
            focus_task,
            task_lookup=linked_task_lookup,
            assignee_map=linked_assignee_map,
            checkout_actor_map=linked_checkout_actor_map,
        )
        effective_plan_terminal_reason = (
            lifecycle_rollup.terminal_reason if lifecycle_rollup is not None else None
        ) or focus_state.terminal_reason
        if effective_plan_terminal_reason is None and plan.status.value == "completed":
            effective_plan_terminal_reason = "plan is already marked completed"
        plan_completion_context: dict[str, Any] | None = None
        if effective_plan_terminal_reason is not None:
            completion_steps = [
                _cli_command(f"plan lineage --plan {plan_target}"),
                _cli_command(f'task list --project "{project_label}"')
                if plan.project_id
                else "",
                _cli_command(f'project show "{project_label}" --format json')
                if plan.project_id and project_name
                else "",
                _cli_command(f"goal summary {plan.goal_id}") if plan.goal_id else "",
            ]
            plan_completion_context = {
                "summary": (
                    "This plan is terminal. Inspect lineage, linked tasks, project state, "
                    "or goal state instead of treating the plan as active work."
                ),
                "next_steps": _normalize_next_steps(*completion_steps),
            }
            plan_next_steps = plan_completion_context["next_steps"]
        else:
            plan_next_steps = _normalize_next_steps(
                *(focus_task.next_steps() if focus_task is not None else []),
                _cli_command(f"plan lineage --plan {plan_target}"),
                _cli_command(f"plan update {update_target} --task <title>"),
                _cli_command(f'task list --project "{project_label}"')
                if plan.project_id
                else "",
            )

        if output_format == "json":
            effective_history_limit = history_limit if history_limit > 0 else 1000
            effective_linked_limit = linked_limit if linked_limit > 0 else 1000
            product_name = None
            if plan.product_id:
                product = await product_repo.get_by_id(plan.product_id)
                if product:
                    product_name = product.name

            links, _ = _plan_followup_commands(plan.id, plan.name, project_name)
            links = _normalize_command_links(
                {
                    **links,
                    "project": (
                        f"project show {plan.project_id} --format json"
                        if plan.project_id
                        else None
                    ),
                    "goal": f"goal show {plan.goal_id}" if plan.goal_id else None,
                    "objective": (
                        f"objective show {plan.objective_id}"
                        if plan.objective_id
                        else None
                    ),
                }
            )

            if view == "overview":
                payload: dict[str, Any] = {
                    "id": plan.id,
                    "name": plan.name,
                    "status": plan.status.value,
                    "stored_status": stored_status_value,
                    "format": plan.format.value,
                    "project_id": plan.project_id,
                    "project_name": project_name,
                    "product_id": plan.product_id,
                    "product_name": product_name,
                    "goal_id": plan.goal_id,
                    "goal_name": goal_name,
                    "objective_id": plan.objective_id,
                    "objective_name": objective_name,
                    "created_at": _to_iso(plan.created_at),
                    "updated_at": _to_iso(plan.updated_at),
                    "last_activity_at": _to_iso(last_activity),
                    "last_transition_at": _to_iso(last_transition),
                    "links": links,
                }
            else:
                payload = plan.to_dict()
                payload.update(
                    {
                        "stored_status": stored_status_value,
                        "project_name": project_name,
                        "product_name": product_name,
                        "goal_name": goal_name,
                        "objective_name": objective_name,
                        "last_activity_at": _to_iso(last_activity),
                        "last_transition_at": _to_iso(last_transition),
                        "links": links,
                    }
                )
            payload["focus_task"] = focus_task_payload
            payload["terminal_reason"] = effective_plan_terminal_reason
            payload["completion_context"] = plan_completion_context
            payload["next_steps"] = plan_next_steps
            owner_entities = [item for item in (goal, objective) if item is not None]
            owner_map = await _resolve_owner_map(owner_entities, actor_service)
            payload["actor_rollups"] = _actor_rollups_payload(
                owners=owner_entities,
                tasks=list(linked_tasks),
                owner_map=owner_map,
                assignee_map=linked_assignee_map,
                checkout_actor_map=linked_checkout_actor_map,
                population_basis="plan_linked_graph",
            )

            if include_linked:
                task_ids = list(plan.task_ids or [])[:effective_linked_limit]
                tasks = linked_tasks[:effective_linked_limit] if task_ids else []
                payload["linked"] = {
                    "tasks": [
                        {
                            "id": task.id,
                            "title": task.title,
                            "status": task.status.value,
                            "updated_at": _to_iso(task.updated_at),
                            "assignee": _task_assignee_payload(
                                task,
                                linked_assignee_map,
                            ),
                            "links": _normalize_command_links(
                                {
                                    "self": _cli_command(f"task show {task.id}"),
                                    "actor": _task_assignee_actor_link(
                                        task,
                                        linked_assignee_map,
                                    ),
                                }
                            ),
                        }
                        for task in tasks
                    ],
                    "page": {
                        "total_count": len(plan.task_ids),
                        "limit": min(effective_linked_limit, len(plan.task_ids)),
                        "offset": 0,
                        "has_more": len(plan.task_ids) > effective_linked_limit,
                        "next_offset": effective_linked_limit
                        if len(plan.task_ids) > effective_linked_limit
                        else None,
                    },
                }
                if include_linked_history:
                    payload["linked_history"] = {
                        task.id: [
                            {
                                "revision_number": rev.revision_number,
                                "change_type": rev.change_type.value,
                                "message": rev.message,
                                "created_by": rev.created_by,
                                "created_at": rev.created_at,
                            }
                            for rev in await task_repo.get_history(
                                task.id, limit=effective_history_limit
                            )
                        ]
                        for task in tasks
                    }

            if include_history:
                history = await plan_repo.get_history(
                    plan.id, limit=effective_history_limit
                )
                payload["history"] = [
                    {
                        "revision_number": rev.revision_number,
                        "change_type": rev.change_type.value,
                        "message": rev.message,
                        "created_by": rev.created_by,
                        "created_at": rev.created_at,
                    }
                    for rev in history
                ]

            payload = _payload_with_normalized_next_steps(payload, *plan_next_steps)
            click.echo(json.dumps(payload, default=str))
            return

        if view == "overview":
            console.print(f"[bold cyan]{plan.name}[/bold cyan]")
            console.print(f"Status: {plan.status.value}")
            if stored_status_value != plan.status.value:
                console.print(f"[dim]Stored Status: {stored_status_value}[/dim]")
            if last_activity:
                console.print(f"Last Activity: {format_relative(last_activity)}")
            if last_transition:
                console.print(f"Last Transition: {format_relative(last_transition)}")
            if focus_task is not None:
                console.print(
                    "Execution Focus: "
                    f"{focus_task.title} [{focus_task.status_value}] "
                    f"({focus_task.current_progress_percent}%)"
                )
                console.print(f"Focus Reason: {focus_task.reason}")
            elif effective_plan_terminal_reason is not None:
                console.print(f"Execution State: {effective_plan_terminal_reason}")
                if plan_completion_context is not None:
                    console.print(plan_completion_context["summary"])
            _print_next_steps(
                _cli_command(f"plan show {plan_target}"), *plan_next_steps
            )
            return

        console.print(f"[bold cyan]{plan.name}[/bold cyan]")
        console.print(f"Status: {plan.status.value}")
        if stored_status_value != plan.status.value:
            console.print(f"Stored Status: {stored_status_value}")
        console.print(f"Format: {plan.format.value}")
        if last_activity:
            console.print(f"Last Activity: {format_relative(last_activity)}")
        if last_transition:
            console.print(f"Last Transition: {format_relative(last_transition)}")
        if plan.description:
            console.print(f"Description: {plan.description}")
        if plan.project_id:
            if project_name:
                console.print(f"Project: {project_name} ({plan.project_id})")
            else:
                console.print(f"Project: {plan.project_id}")
        if plan.goal_id:
            if goal_name:
                console.print(f"Goal: {goal_name} ({plan.goal_id})")
            else:
                console.print(f"Goal: {plan.goal_id}")
        if plan.objective_id:
            if objective_name:
                console.print(f"Objective: {objective_name} ({plan.objective_id})")
            else:
                console.print(f"Objective: {plan.objective_id}")
        if plan.task_ids:
            _print_plan_task_block(
                linked_tasks=linked_tasks,
                task_ids=list(plan.task_ids),
            )
        if plan.tags:
            console.print(f"Tags: {', '.join(plan.tags)}")
        if focus_task is not None:
            console.print(
                "Execution Focus: "
                f"{focus_task.title} [{focus_task.status_value}] "
                f"({focus_task.current_progress_percent}%)"
            )
            console.print(f"Focus Reason: {focus_task.reason}")
        elif effective_plan_terminal_reason is not None:
            console.print(f"Execution State: {effective_plan_terminal_reason}")
            if plan_completion_context is not None:
                console.print(plan_completion_context["summary"])
        console.print("Content:")
        console.print(plan.content)
        _print_next_steps(*plan_next_steps)
    finally:
        await db.disconnect()


@plan.command("update")
@click.argument("plan_ref")
@click.option("--project", "project_ref", help="Project name or ID for plan lookup")
@click.option(
    "--pick",
    is_flag=True,
    help="Pick from matching plans when name is ambiguous",
)
@click.option("--name", help="New plan name")
@click.option("--description", help="New description")
@click.option(
    "--status",
    type=click.Choice(["draft", "active", "completed", "archived"]),
)
@click.option(
    "--format",
    "plan_format",
    type=click.Choice(["json", "yaml"]),
    help="Plan content format when replacing stored content",
)
@click.option("--content", help="Plan content (JSON string or YAML)")
@click.option(
    "--file",
    "content_file",
    type=click.Path(exists=True, dir_okay=False),
    help="Load plan content from file",
)
@click.option(
    "--output-format",
    type=click.Choice(["text", "json"]),
    default="text",
    show_default=True,
    help="Render mutation result as human text or JSON",
)
@click.option("--product-id", help="Link to product")
@click.option("--project-id", help="Link to project")
@click.option("--goal", "goal_ref", help="Link to goal (name or ID)")
@click.option("--goal-id", help="Link to goal")
@click.option("--objective", "objective_ref", help="Link to objective (name or ID)")
@click.option("--objective-id", help="Link to objective")
@click.option("--task", "task_titles", multiple=True, help="Add task links by title")
@click.option("--task-id", "task_ids", multiple=True, help="Add task links")
@click.option(
    "--replace-task",
    "replace_task_titles",
    multiple=True,
    help="Replace all linked tasks by title",
)
@click.option(
    "--replace-task-id",
    "replace_task_ids",
    multiple=True,
    help="Replace all linked tasks by ID",
)
@click.option(
    "--remove-task",
    "remove_task_titles",
    multiple=True,
    help="Remove linked tasks by title",
)
@click.option(
    "--remove-task-id",
    "remove_task_ids",
    multiple=True,
    help="Remove linked tasks by ID",
)
@click.option(
    "--clear-tasks",
    is_flag=True,
    help="Remove all linked tasks before applying any add/replace operations",
)
@click.option("-t", "--tag", "tags", multiple=True, help="Replace plan tags")
@async_command
async def plan_update(
    plan_ref: str,
    project_ref: str | None,
    pick: bool,
    name: str | None,
    description: str | None,
    status: str | None,
    plan_format: str | None,
    content: str | None,
    content_file: str | None,
    output_format: str,
    product_id: str | None,
    project_id: str | None,
    goal_ref: str | None,
    goal_id: str | None,
    objective_ref: str | None,
    objective_id: str | None,
    task_titles: tuple[str, ...],
    task_ids: tuple[str, ...],
    replace_task_titles: tuple[str, ...],
    replace_task_ids: tuple[str, ...],
    remove_task_titles: tuple[str, ...],
    remove_task_ids: tuple[str, ...],
    clear_tasks: bool,
    tags: tuple[str, ...],
) -> None:
    """Update a plan."""
    from pathlib import Path

    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.models import PlanFormat, PlanStatus
    from pms.services.goal_service import GoalService
    from pms.services.plan_service import PlanService
    from pms.services.project_service import ProjectService
    from pms.services.task_service import TaskService

    content_value: str | None = content
    if content_file:
        content_value = Path(content_file).read_text()
    if plan_format and content_value is None:
        console.print(
            "[red]Use --format only when replacing plan content via --content or --file. "
            "For JSON command output, use --output-format json.[/red]"
        )
        return

    write_decision = _ensure_local_only_runtime_write(
        "pms plan update",
        output_format=output_format,
    )

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        service = PlanService(db, event_store, revision_store, metrics)
        goal_service = GoalService(db, event_store, revision_store, metrics)
        project_service = ProjectService(db, event_store, revision_store, metrics)
        task_service = TaskService(db, event_store, revision_store, metrics)

        if goal_ref and goal_id:
            _emit_cli_error(
                "Use --goal or --goal-id, not both",
                output_format=output_format,
            )
        if objective_ref and objective_id:
            _emit_cli_error(
                "Use --objective or --objective-id, not both",
                output_format=output_format,
            )

        plan_id = await _resolve_plan_id(
            plan_ref, project_ref, service, project_service, pick=pick
        )
        if plan_id is None:
            return

        plan_record = await service.get_plan(plan_id)
        if plan_record is None:
            console.print(f"[red]Plan '{plan_ref}' not found[/red]")
            return

        uses_replace_links = bool(replace_task_ids or replace_task_titles)
        uses_add_links = bool(task_ids or task_titles)
        uses_remove_links = bool(remove_task_ids or remove_task_titles)
        if uses_replace_links and (uses_add_links or uses_remove_links or clear_tasks):
            console.print(
                "[red]Use replace task-link options by themselves. "
                "Do not mix --replace-task/--replace-task-id with add/remove/clear task options.[/red]"
            )
            return

        task_project_ref = project_ref or project_id or plan_record.project_id

        def _append_unique_task_ids(
            target: list[str], incoming_ids: list[str]
        ) -> list[str]:
            for incoming_id in incoming_ids:
                if incoming_id not in target:
                    target.append(incoming_id)
            return target

        async def _resolve_titles(
            titles: tuple[str, ...],
            *,
            option_label: str,
        ) -> list[str] | None:
            if not titles:
                return []
            if not task_project_ref:
                console.print(
                    "[red]Use --project or --project-id, or link the plan to a project, "
                    f"to resolve task titles for {option_label}.[/red]"
                )
                return None
            resolved_ids: list[str] = []
            for title in titles:
                task_id = await _resolve_task_id(
                    title, task_project_ref, task_service, project_service
                )
                if task_id is None:
                    return None
                resolved_ids.append(task_id)
            return resolved_ids

        add_title_ids = await _resolve_titles(task_titles, option_label="--task")
        if add_title_ids is None:
            return
        replace_title_ids = await _resolve_titles(
            replace_task_titles, option_label="--replace-task"
        )
        if replace_title_ids is None:
            return
        remove_title_ids = await _resolve_titles(
            remove_task_titles, option_label="--remove-task"
        )
        if remove_title_ids is None:
            return

        task_ids_update_requested = any(
            (
                uses_replace_links,
                uses_add_links,
                uses_remove_links,
                clear_tasks,
            )
        )
        resolved_task_ids: list[str] | None = None
        if task_ids_update_requested:
            if uses_replace_links:
                resolved_task_ids = []
                _append_unique_task_ids(resolved_task_ids, list(replace_task_ids))
                _append_unique_task_ids(resolved_task_ids, replace_title_ids)
            else:
                resolved_task_ids = list(plan_record.task_ids)
                if clear_tasks:
                    resolved_task_ids = []
                remove_ids = set(remove_task_ids)
                remove_ids.update(remove_title_ids)
                if remove_ids:
                    resolved_task_ids = [
                        existing_id
                        for existing_id in resolved_task_ids
                        if existing_id not in remove_ids
                    ]
                _append_unique_task_ids(resolved_task_ids, list(task_ids))
                _append_unique_task_ids(resolved_task_ids, add_title_ids)

        resolved_goal_id = goal_id
        if goal_ref:
            resolved_goal_id = await _resolve_goal_id(goal_ref, goal_service, pick=pick)
            if resolved_goal_id is None:
                return

        resolved_objective_id = objective_id
        if objective_ref:
            objective_goal_ref = goal_id or goal_ref
            resolved_objective_id = await _resolve_objective_id(
                objective_ref, objective_goal_ref, goal_service, pick=pick
            )
            if resolved_objective_id is None:
                return

        try:
            plan = await service.update_plan(
                plan_id=plan_id,
                name=name,
                description=description,
                status=PlanStatus(status) if status else None,
                format=PlanFormat(plan_format) if plan_format else None,
                content=content_value,
                product_id=product_id,
                project_id=project_id,
                goal_id=resolved_goal_id,
                objective_id=resolved_objective_id,
                task_ids=resolved_task_ids,
                tags=list(tags) if tags else None,
            )
        except ValueError as exc:
            console.print(f"[red]{exc}[/red]")
            return

        if plan is None:
            console.print(f"[red]Plan '{plan_ref}' not found[/red]")
            return

        plan_target = _best_plan_command_target(plan.id, plan.name, None)
        next_steps = _normalize_next_steps(
            _cli_command(f"plan show {plan_target}"),
            _cli_command(f"plan lineage --plan-id {plan.id}"),
        )
        if output_format == "json":
            click.echo(
                json.dumps(
                    {
                        "plan": plan.to_dict(),
                        "runtime_write": _runtime_write_context_payload(write_decision),
                        "task_link_update": {
                            "mode": (
                                "replace"
                                if uses_replace_links
                                else "mutate"
                                if task_ids_update_requested
                                else "unchanged"
                            ),
                            "task_count": len(plan.task_ids),
                        },
                        "links": _normalize_command_links(
                            {
                                "self": f"plan show {plan_target}",
                                "lineage": f"plan lineage --plan-id {plan.id}",
                            }
                        ),
                        "next_steps": next_steps,
                    },
                    default=str,
                )
            )
            return

        console.print(f"[green]Updated plan:[/green] {plan.name}")
        _print_next_steps(*next_steps)
    finally:
        await db.disconnect()


@plan.group("test-job")
def plan_test_job() -> None:
    """Manage plan-linked test jobs."""
    pass


@plan_test_job.command("add")
@click.argument("plan_id")
@click.argument("name")
@click.argument("project_path", default=".", required=False)
@click.option(
    "--mode",
    type=click.Choice(["local", "aws"]),
    default="local",
    show_default=True,
)
@click.option("-d", "--description", help="Job description")
@click.option("-c", "--command", "test_command", default="pytest", help="Test command")
@click.option(
    "-s",
    "--setup",
    "setup_cmd",
    help="Setup command (e.g., pip install -r requirements.txt)",
)
@click.option(
    "-w",
    "--workdir",
    "working_dir",
    help="Working directory relative to project path",
)
@click.option("-t", "--timeout", default=600.0, help="Test timeout in seconds")
@click.option("--project-id", help="Link test run to a project")
@click.option(
    "--task-id",
    "task_ids",
    multiple=True,
    help="Link test run to task IDs (repeatable)",
)
@click.option(
    "--capture-log",
    "capture_logs",
    multiple=True,
    help="Capture log file contents (repeatable)",
)
@click.option(
    "--save-artifact",
    "save_artifacts",
    multiple=True,
    help="Record artifact file paths (repeatable)",
)
@click.option(
    "--env",
    "env_vars",
    multiple=True,
    help="Environment variable (KEY=VALUE, repeatable)",
)
@click.option(
    "--on-success-state",
    help="Workflow state to transition tasks to on success",
)
@click.option(
    "--on-failure-state",
    help="Workflow state to transition tasks to on failure",
)
@click.option(
    "--transition-by",
    help="Workflow transition actor",
)
@click.option(
    "--transition-reason",
    help="Workflow transition reason",
)
@click.option("--server-id", help="AWS test server ID")
@click.option("--server-name", help="AWS test server name")
@click.option("--remote-path", default="/home/ec2-user/project", show_default=True)
@click.option(
    "--exclude",
    "exclude_patterns",
    multiple=True,
    help="Exclude path patterns (repeatable)",
)
@click.option(
    "--stream-output/--no-stream",
    default=False,
    show_default=True,
    help=(
        "Deprecated for plan test jobs; live output is only available through "
        "`pms aws test run`."
    ),
)
@async_command
async def plan_test_job_add(
    plan_id: str,
    name: str,
    project_path: str,
    mode: str,
    description: str | None,
    test_command: str,
    setup_cmd: str | None,
    working_dir: str | None,
    timeout: float,
    project_id: str | None,
    task_ids: tuple[str, ...],
    capture_logs: tuple[str, ...],
    save_artifacts: tuple[str, ...],
    env_vars: tuple[str, ...],
    on_success_state: str | None,
    on_failure_state: str | None,
    transition_by: str | None,
    transition_reason: str | None,
    server_id: str | None,
    server_name: str | None,
    remote_path: str,
    exclude_patterns: tuple[str, ...],
    stream_output: bool,
) -> None:
    """Create a plan test job."""
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.services.plan_test_job_service import PlanTestJobService

    env_pairs: list[tuple[str, str]] = []
    for item in env_vars:
        if "=" not in item:
            console.print(f"[red]Invalid --env entry: {item}[/red]")
            return
        key, value = item.split("=", 1)
        env_pairs.append((key, value))

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        service = PlanTestJobService(db, event_store, revision_store, metrics)

        try:
            job = await service.create_job(
                plan_id=plan_id,
                name=name,
                description=description,
                mode=mode,
                project_path=project_path,
                test_command=test_command,
                setup_command=setup_cmd,
                working_dir=working_dir,
                env_vars=tuple(env_pairs),
                timeout=timeout,
                capture_logs=tuple(capture_logs),
                save_artifacts=tuple(save_artifacts),
                task_ids=tuple(task_ids),
                transition_on_success=on_success_state,
                transition_on_failure=on_failure_state,
                transition_by=transition_by,
                transition_reason=transition_reason,
                project_id=project_id,
                server_id=server_id,
                server_name=server_name,
                remote_path=remote_path,
                exclude_patterns=tuple(exclude_patterns) if exclude_patterns else None,
                stream_output=stream_output,
            )
        except ValueError as exc:
            console.print(f"[red]{exc}[/red]")
            return

        console.print(f"[green]Created plan test job:[/green] {job.name}")
        console.print(f"[dim]ID: {job.id}[/dim]")
    finally:
        await db.disconnect()


@plan_test_job.command("list")
@click.argument("plan_id")
@click.option(
    "--include-archived",
    is_flag=True,
    help="Include archived test jobs",
)
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["table", "json", "csv"]),
    default="table",
    show_default=True,
)
@click.option(
    "--view",
    type=click.Choice(["overview", "detail", "trace"]),
    default="overview",
    show_default=True,
    help="Output view profile (overview/detail/trace)",
)
@click.option("--include-history", is_flag=True, help="Include history in JSON")
@click.option("--include-linked", is_flag=True, help="Include linked items in JSON")
@click.option(
    "--include-linked-history",
    is_flag=True,
    help="Include history for linked items in JSON",
)
@click.option("--history-limit", type=int, default=20, show_default=True)
@click.option("--linked-limit", type=int, default=20, show_default=True)
@click.option("--limit", type=int, default=100, show_default=True)
@click.option("--offset", type=int, default=0, show_default=True)
@async_command
async def plan_test_job_list(
    plan_id: str,
    output_format: str,
    include_archived: bool,
    view: str,
    include_history: bool,
    include_linked: bool,
    include_linked_history: bool,
    history_limit: int,
    linked_limit: int,
    limit: int,
    offset: int,
) -> None:
    """List test jobs for a plan."""
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.services.plan_test_job_service import PlanTestJobService

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        service = PlanTestJobService(db, event_store, revision_store, metrics)
        if view == "trace":
            include_history = True
            include_linked = True
        if include_linked_history:
            include_linked = True
            include_history = True

        result = await service.list_jobs(
            plan_id=plan_id,
            limit=limit,
            offset=offset,
            include_archived=include_archived,
        )

        if output_format == "json":
            from pms.repositories.plan_test_job_repository import (
                PlanTestJobRepository,
            )
            from pms.repositories.progress_repository import (
                ProgressQuery,
                ProgressRepository,
            )
            from pms.repositories.state_transition_repository import (
                StateTransitionQuery,
                StateTransitionRepository,
            )
            from pms.repositories.task_evidence_repository import (
                TaskEvidenceRepository,
            )
            from pms.services.plan_service import PlanService
            from pms.services.project_service import ProjectService
            from pms.services.task_service import TaskService

            job_repo = PlanTestJobRepository(db)
            task_service = TaskService(db, event_store, revision_store, metrics)
            plan_service = PlanService(db, event_store, revision_store, metrics)
            project_service = ProjectService(db, event_store, revision_store, metrics)
            progress_repo = ProgressRepository(db) if include_linked_history else None
            state_repo = (
                StateTransitionRepository(db) if include_linked_history else None
            )
            evidence_repo = (
                TaskEvidenceRepository(db) if include_linked_history else None
            )

            effective_history_limit = history_limit if history_limit > 0 else 1000
            effective_linked_limit = linked_limit if linked_limit > 0 else 1000
            plan_names: dict[str, str] = {}
            project_names: dict[str, str] = {}

            def _job_links(job_obj) -> dict[str, str]:
                return _normalize_command_links(
                    {
                        "self": _cli_command(f"plan test-job show {job_obj.id}"),
                        "run": _cli_command(f"plan test-job run {job_obj.id}"),
                        "update": _cli_command(f"plan test-job update {job_obj.id}"),
                        "delete": _cli_command(f"plan test-job delete {job_obj.id}"),
                        "restore": _cli_command(f"plan test-job restore {job_obj.id}"),
                    }
                )

            async def _task_history(task_id: str) -> dict[str, Any]:
                if not progress_repo or not state_repo or not evidence_repo:
                    return {}
                progress_updates = await progress_repo.get_updates(
                    ProgressQuery(task_id=task_id, limit=effective_history_limit)
                )
                workflow_transitions = await state_repo.get_transitions(
                    StateTransitionQuery(
                        entity_type="task_workflow",
                        entity_id=task_id,
                        limit=effective_history_limit,
                    )
                )
                status_transitions = await state_repo.get_transitions(
                    StateTransitionQuery(
                        entity_type="task_status",
                        entity_id=task_id,
                        limit=effective_history_limit,
                    )
                )
                evidence_result = await evidence_repo.list_by_task(
                    task_id, limit=effective_history_limit
                )
                return {
                    "progress_updates": [
                        update.to_dict() for update in progress_updates
                    ],
                    "workflow_transitions": [
                        transition.to_dict() for transition in workflow_transitions
                    ],
                    "status_transitions": [
                        transition.to_dict() for transition in status_transitions
                    ],
                    "evidence": [item.to_dict() for item in evidence_result.items],
                }

            items: list[dict[str, Any]] = []
            for job in result.items:
                plan_name = None
                if job.plan_id:
                    if job.plan_id not in plan_names:
                        plan = await plan_service.get_plan(job.plan_id)
                        if plan:
                            plan_names[job.plan_id] = plan.name
                    plan_name = plan_names.get(job.plan_id)
                project_name = None
                if job.project_id:
                    if job.project_id not in project_names:
                        project = await project_service.get_project(job.project_id)
                        if project:
                            project_names[job.project_id] = project.name
                    project_name = project_names.get(job.project_id)

                if view == "overview":
                    payload = {
                        "id": job.id,
                        "name": job.name,
                        "plan_id": job.plan_id,
                        "plan_name": plan_name,
                        "project_id": job.project_id,
                        "project_name": project_name,
                        "mode": job.mode,
                        "created_at": _to_iso(job.created_at),
                        "updated_at": _to_iso(job.updated_at),
                        "archived_at": _to_iso(job.archived_at),
                        "links": _job_links(job),
                    }
                else:
                    payload = job.to_dict()
                    payload["plan_name"] = plan_name
                    payload["project_name"] = project_name
                    payload["links"] = _job_links(job)

                if include_linked:
                    task_items = []
                    task_ids = list(job.task_ids or ())
                    for task_id in task_ids[:effective_linked_limit]:
                        task_obj = await task_service.get_task(task_id)
                        if task_obj:
                            task_items.append(
                                {
                                    "id": task_obj.id,
                                    "title": task_obj.title,
                                    "status": task_obj.status.value,
                                    "priority": task_obj.priority.value,
                                    "project_id": task_obj.project_id,
                                    "updated_at": _to_iso(task_obj.updated_at),
                                    "links": _normalize_command_links(
                                        {
                                            "self": _cli_command(
                                                f"task show {task_obj.id}"
                                            ),
                                            "timeline": _cli_command(
                                                f"task timeline {task_obj.id}"
                                            ),
                                        }
                                    ),
                                }
                            )
                    payload["linked"] = {
                        "tasks": task_items,
                        "page": _page_payload(len(task_ids), effective_linked_limit, 0),
                    }
                    if include_linked_history and task_ids:
                        payload["linked_history"] = {
                            task_id: await _task_history(task_id)
                            for task_id in task_ids[:effective_linked_limit]
                        }

                if include_history:
                    history = await job_repo.get_history(
                        job.id, limit=effective_history_limit
                    )
                    payload["history"] = [
                        {
                            "revision_number": rev.revision_number,
                            "change_type": rev.change_type.value,
                            "message": rev.message,
                            "created_by": rev.created_by,
                            "created_at": rev.created_at,
                        }
                        for rev in history
                    ]

                items.append(payload)

            base_cmd = _cli_command(f"plan test-job list {plan_id} --format json")
            if include_archived:
                base_cmd += " --include-archived"
            if view != "overview":
                base_cmd += f" --view {view}"
            payload = {
                "items": items,
                "page": _page_payload(result.total_count, result.limit, result.offset),
                "links": _normalize_command_links(
                    {
                        "self": f"{base_cmd} --limit {limit} --offset {offset}",
                        "next": (
                            f"{base_cmd} --limit {limit} --offset {offset + limit}"
                            if limit > 0 and offset + limit < result.total_count
                            else None
                        ),
                    }
                ),
            }
            click.echo(json.dumps(payload, indent=2, default=str))
            return

        if output_format == "csv":
            headers = [
                "id",
                "name",
                "mode",
                "command",
                "task_count",
                "updated_at",
                "archived_at",
            ]
            click.echo(_csv_row(headers))
            for job in result.items:
                row = [
                    job.id,
                    job.name,
                    job.mode,
                    job.test_command,
                    str(len(job.task_ids)),
                    str(job.updated_at)[:19] if job.updated_at else "",
                    str(job.archived_at)[:19] if job.archived_at else "",
                ]
                click.echo(_csv_row(row))
            return

        from pms.utils.time import format_relative

        table = Table(title="Plan Test Jobs")
        table.add_column("ID", style="dim")
        table.add_column("Name", style="cyan")
        table.add_column("Mode")
        table.add_column("Command")
        table.add_column("Tasks")
        table.add_column("Updated")
        table.add_column("Archived")
        for job in result.items:
            table.add_row(
                job.id,
                job.name,
                job.mode,
                job.test_command,
                str(len(job.task_ids)),
                format_relative(job.updated_at),
                format_relative(job.archived_at),
            )
        console.print(table)
        console.print(f"[dim]Total: {result.total_count}[/dim]")
    finally:
        await db.disconnect()


@plan_test_job.command("show")
@click.argument("job_id")
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json"]),
    default="text",
    show_default=True,
)
@click.option(
    "--view",
    type=click.Choice(["overview", "detail", "trace"]),
    default="detail",
    show_default=True,
    help="Output view profile (overview/detail/trace)",
)
@click.option("--include-history", is_flag=True, help="Include history in JSON")
@click.option("--include-linked", is_flag=True, help="Include linked items in JSON")
@click.option(
    "--include-linked-history",
    is_flag=True,
    help="Include history for linked items in JSON",
)
@click.option("--history-limit", type=int, default=20, show_default=True)
@click.option("--linked-limit", type=int, default=20, show_default=True)
@async_command
async def plan_test_job_show(
    job_id: str,
    output_format: str,
    view: str,
    include_history: bool,
    include_linked: bool,
    include_linked_history: bool,
    history_limit: int,
    linked_limit: int,
) -> None:
    """Show plan test job details."""
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.services.plan_test_job_service import PlanTestJobService

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        service = PlanTestJobService(db, event_store, revision_store, metrics)
        if view == "trace":
            include_history = True
            include_linked = True
        if include_linked_history:
            include_linked = True
            include_history = True

        job = await service.get_job(job_id)
        if job is None:
            console.print(f"[red]Plan test job '{job_id}' not found[/red]")
            return

        if output_format == "json":
            from pms.repositories.plan_test_job_repository import (
                PlanTestJobRepository,
            )
            from pms.repositories.progress_repository import (
                ProgressQuery,
                ProgressRepository,
            )
            from pms.repositories.state_transition_repository import (
                StateTransitionQuery,
                StateTransitionRepository,
            )
            from pms.repositories.task_evidence_repository import (
                TaskEvidenceRepository,
            )
            from pms.services.plan_service import PlanService
            from pms.services.project_service import ProjectService
            from pms.services.task_service import TaskService

            job_repo = PlanTestJobRepository(db)
            task_service = TaskService(db, event_store, revision_store, metrics)
            plan_service = PlanService(db, event_store, revision_store, metrics)
            project_service = ProjectService(db, event_store, revision_store, metrics)
            progress_repo = ProgressRepository(db) if include_linked_history else None
            state_repo = (
                StateTransitionRepository(db) if include_linked_history else None
            )
            evidence_repo = (
                TaskEvidenceRepository(db) if include_linked_history else None
            )

            effective_history_limit = history_limit if history_limit > 0 else 1000
            effective_linked_limit = linked_limit if linked_limit > 0 else 1000

            def _job_links(job_obj) -> dict[str, str]:
                return _normalize_command_links(
                    {
                        "self": _cli_command(f"plan test-job show {job_obj.id}"),
                        "run": _cli_command(f"plan test-job run {job_obj.id}"),
                        "update": _cli_command(f"plan test-job update {job_obj.id}"),
                        "delete": _cli_command(f"plan test-job delete {job_obj.id}"),
                        "restore": _cli_command(f"plan test-job restore {job_obj.id}"),
                    }
                )

            async def _task_history(task_id: str) -> dict[str, Any]:
                if not progress_repo or not state_repo or not evidence_repo:
                    return {}
                progress_updates = await progress_repo.get_updates(
                    ProgressQuery(task_id=task_id, limit=effective_history_limit)
                )
                workflow_transitions = await state_repo.get_transitions(
                    StateTransitionQuery(
                        entity_type="task_workflow",
                        entity_id=task_id,
                        limit=effective_history_limit,
                    )
                )
                status_transitions = await state_repo.get_transitions(
                    StateTransitionQuery(
                        entity_type="task_status",
                        entity_id=task_id,
                        limit=effective_history_limit,
                    )
                )
                evidence_result = await evidence_repo.list_by_task(
                    task_id, limit=effective_history_limit
                )
                return {
                    "progress_updates": [
                        update.to_dict() for update in progress_updates
                    ],
                    "workflow_transitions": [
                        transition.to_dict() for transition in workflow_transitions
                    ],
                    "status_transitions": [
                        transition.to_dict() for transition in status_transitions
                    ],
                    "evidence": [item.to_dict() for item in evidence_result.items],
                }

            plan_name = None
            if job.plan_id:
                plan = await plan_service.get_plan(job.plan_id)
                if plan:
                    plan_name = plan.name
            project_name = None
            if job.project_id:
                project = await project_service.get_project(job.project_id)
                if project:
                    project_name = project.name

            if view == "overview":
                payload = {
                    "id": job.id,
                    "name": job.name,
                    "plan_id": job.plan_id,
                    "plan_name": plan_name,
                    "project_id": job.project_id,
                    "project_name": project_name,
                    "mode": job.mode,
                    "created_at": _to_iso(job.created_at),
                    "updated_at": _to_iso(job.updated_at),
                    "archived_at": _to_iso(job.archived_at),
                    "links": _job_links(job),
                }
            else:
                payload = job.to_dict()
                payload["plan_name"] = plan_name
                payload["project_name"] = project_name
                payload["links"] = _job_links(job)

            if include_linked:
                task_items = []
                task_ids = list(job.task_ids or ())
                for task_id in task_ids[:effective_linked_limit]:
                    task_obj = await task_service.get_task(task_id)
                    if task_obj:
                        task_items.append(
                            {
                                "id": task_obj.id,
                                "title": task_obj.title,
                                "status": task_obj.status.value,
                                "priority": task_obj.priority.value,
                                "project_id": task_obj.project_id,
                                "updated_at": _to_iso(task_obj.updated_at),
                                "links": _normalize_command_links(
                                    {
                                        "self": f"pms task show {task_obj.id}",
                                        "timeline": (
                                            f"pms task timeline {task_obj.id}"
                                        ),
                                    }
                                ),
                            }
                        )
                payload["linked"] = {
                    "tasks": task_items,
                    "page": _page_payload(len(task_ids), effective_linked_limit, 0),
                }
                if include_linked_history and task_ids:
                    payload["linked_history"] = {
                        task_id: await _task_history(task_id)
                        for task_id in task_ids[:effective_linked_limit]
                    }

            if include_history:
                history = await job_repo.get_history(
                    job.id, limit=effective_history_limit
                )
                payload["history"] = [
                    {
                        "revision_number": rev.revision_number,
                        "change_type": rev.change_type.value,
                        "message": rev.message,
                        "created_by": rev.created_by,
                        "created_at": rev.created_at,
                    }
                    for rev in history
                ]

            click.echo(json.dumps(payload, indent=2, default=str))
            return

        console.print(f"[bold cyan]{job.name}[/bold cyan]")
        console.print(f"Plan: {job.plan_id}")
        console.print(f"Mode: {job.mode}")
        console.print(f"Project Path: {job.project_path}")
        console.print(f"Command: {job.test_command}")
        if job.setup_command:
            console.print(f"Setup: {job.setup_command}")
        if job.working_dir:
            console.print(f"Working Dir: {job.working_dir}")
        console.print(f"Timeout: {job.timeout}s")
        if job.task_ids:
            console.print(f"Tasks: {', '.join(job.task_ids)}")
        if job.capture_logs:
            console.print(f"Capture Logs: {', '.join(job.capture_logs)}")
        if job.save_artifacts:
            console.print(f"Save Artifacts: {', '.join(job.save_artifacts)}")
        if job.env_vars:
            env_text = ", ".join(f"{key}={value}" for key, value in job.env_vars)
            console.print(f"Env: {env_text}")
        if job.transition_on_success or job.transition_on_failure:
            console.print(
                f"Transitions: success={job.transition_on_success or '-'} "
                f"failure={job.transition_on_failure or '-'}"
            )
        if job.server_name or job.server_id:
            console.print(
                f"Server: {job.server_name or job.server_id} ({job.remote_path})"
            )
        if job.exclude_patterns:
            console.print(f"Exclude: {', '.join(job.exclude_patterns)}")
    finally:
        await db.disconnect()


