@plan_test_job.command("run")
@click.argument("job_args", nargs=-1)
@click.option("--no-output", is_flag=True, help="Do not print stdout/stderr")
@async_command
async def plan_test_job_run(job_args: tuple[str, ...], no_output: bool) -> None:
    """Run a plan test job (JOB_ID or PLAN_ID JOB_ID)."""
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.services.plan_test_job_service import PlanTestJobService

    if len(job_args) == 1:
        plan_id = None
        job_id = job_args[0]
    elif len(job_args) == 2:
        plan_id, job_id = job_args
    else:
        _emit_cli_error("Expected JOB_ID or PLAN_ID JOB_ID", output_format="text")

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        service = PlanTestJobService(db, event_store, revision_store, metrics)

        if plan_id:
            job = await service.get_job(job_id)
            if job is None:
                console.print(f"[red]Plan test job '{job_id}' not found[/red]")
                return
            if job.plan_id != plan_id:
                console.print(
                    "[red]Plan mismatch:[/red] "
                    f"job belongs to {job.plan_id}, not {plan_id}"
                )
                return

        run = await service.run_job(job_id)
        if run is None:
            console.print(f"[red]Plan test job '{job_id}' not found[/red]")
            return

        result = run.result
        if not no_output:
            if result.stdout:
                console.print(result.stdout)
            if result.stderr:
                console.print(f"[red]{result.stderr}[/red]")

        console.print()
        style = "green" if result.success else "red"
        console.print(f"[{style}]{result.summary}[/{style}]")
        for line in _format_transition_summary(result):
            console.print(f"[dim]{line}[/dim]")
        console.print(f"[dim]Run ID: {result.run_id}[/dim]")
    except Exception as exc:
        console.print(f"[red]Error: {exc}[/red]")
    finally:
        await db.disconnect()


