@objective.command("create")
@click.argument("name")
@click.option("--goal", "goal_ref", help="Parent goal name or ID")
@click.option("--goal-id", help="Parent goal ID")
@click.option(
    "--pick",
    is_flag=True,
    help="Pick from matching goals when name is ambiguous",
)
@click.option("-d", "--description", help="Objective description")
@click.option("--target-date", help="Target date (ISO format)")
@click.option("--owner", help="Objective owner")
@click.option("-t", "--tag", "tags", multiple=True, help="Objective tags")
@click.option("--progress", type=int, default=0, help="Progress percent (0-100)")
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json"]),
    default="text",
    show_default=True,
)
@async_command
async def objective_create(
    name: str,
    goal_ref: str | None,
    goal_id: str | None,
    pick: bool,
    description: str | None,
    target_date: str | None,
    owner: str | None,
    tags: tuple[str, ...],
    progress: int,
    output_format: str,
) -> None:
    """Create a new objective."""
    from datetime import datetime

    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.services.actor_service import ActorService
    from pms.services.goal_service import GoalService

    target_dt = None
    if target_date:
        try:
            target_dt = datetime.fromisoformat(target_date)
        except ValueError:
            _emit_cli_error(
                "Invalid target date format (use ISO)",
                output_format="json" if output_format == "json" else "text",
            )

    if progress < 0 or progress > 100:
        _emit_cli_error(
            "Progress must be 0-100",
            output_format="json" if output_format == "json" else "text",
        )

    if goal_ref and goal_id:
        _emit_cli_error(
            "Use --goal or --goal-id, not both",
            output_format="json" if output_format == "json" else "text",
        )
    if not goal_ref and not goal_id:
        _emit_cli_error(
            "Goal is required (--goal or --goal-id)",
            output_format="json" if output_format == "json" else "text",
        )

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        service = GoalService(db, event_store, revision_store, metrics)
        actor_service = ActorService(db, event_store, revision_store, metrics)

        resolved_goal_id = goal_id or await _resolve_goal_id(
            goal_ref, service, pick=pick
        )
        if resolved_goal_id is None:
            return

        objective = await service.create_objective(
            goal_id=resolved_goal_id,
            name=name,
            description=description,
            target_date=target_dt,
            owner=owner,
            tags=list(tags) if tags else None,
            progress_percent=progress,
        )

        goal_label = goal_ref
        if not goal_label and resolved_goal_id:
            goal_obj = await service.get_goal(resolved_goal_id)
            if goal_obj:
                goal_label = goal_obj.name
        next_steps = _normalize_next_steps(
            f"pms objective show {objective.id}",
            (
                f'pms keyresult create <name> --objective "{objective.name}" --goal "{goal_label}"'
                if goal_label
                else f"pms keyresult create <name> --objective {objective.id}"
            ),
        )
        if output_format == "json":
            owner_map = await _resolve_owner_map([objective], actor_service)
            payload = _payload_with_normalized_next_steps(
                {
                    "objective": {
                        **_public_entity_payload(objective),
                        "ownership": _ownership_payload(objective, owner_map),
                    },
                    "links": _normalize_command_links(
                        {
                            "self": f"objective show {objective.id}",
                            "key_result_create": (
                                f'keyresult create <name> --objective "{objective.name}" --goal "{goal_label}"'
                                if goal_label
                                else f"keyresult create <name> --objective {objective.id}"
                            ),
                            "owner": _ownership_link(objective, owner_map),
                        }
                    ),
                },
                *next_steps,
            )
            click.echo(json.dumps(payload, default=str))
            return

        console.print(f"[green]Created objective:[/green] {objective.name}")
        console.print(f"[dim]ID: {objective.id}[/dim]")
        _print_next_steps(*next_steps)
    finally:
        await db.disconnect()


@objective.command("list")
@click.option("--goal", "goal_ref", help="Filter by goal name or ID")
@click.option("--goal-id", help="Filter by goal ID")
@click.option(
    "--pick",
    is_flag=True,
    help="Pick from matching goals when name is ambiguous",
)
@click.option(
    "-s",
    "--status",
    type=click.Choice(["active", "completed", "on_hold", "archived"]),
)
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["table", "json", "csv"]),
    default="table",
    show_default=True,
)
@click.option(
    "--view",
    type=click.Choice(["overview", "detail", "trace"]),
    default="overview",
    show_default=True,
    help="Output view profile (overview/detail/trace)",
)
@click.option("--include-history", is_flag=True, help="Include history in JSON")
@click.option("--include-linked", is_flag=True, help="Include linked items in JSON")
@click.option(
    "--include-linked-history",
    is_flag=True,
    help="Include history for linked items in JSON",
)
@click.option("--history-limit", type=int, default=20, show_default=True)
@click.option("--linked-limit", type=int, default=20, show_default=True)
@click.option("--limit", type=int, default=100, show_default=True)
@click.option("--offset", type=int, default=0, show_default=True)
@async_command
async def objective_list(
    goal_ref: str | None,
    goal_id: str | None,
    pick: bool,
    status: str | None,
    output_format: str,
    view: str,
    include_history: bool,
    include_linked: bool,
    include_linked_history: bool,
    history_limit: int,
    linked_limit: int,
    limit: int,
    offset: int,
) -> None:
    """List objectives."""
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.models import GoalStatus
    from pms.repositories.goal_repository import GoalRepository
    from pms.repositories.key_result_repository import KeyResultRepository
    from pms.repositories.objective_repository import ObjectiveRepository
    from pms.repositories.project_repository import ProjectRepository
    from pms.services.goal_service import GoalService

    if goal_ref and goal_id:
        _emit_cli_error(
            "Use --goal or --goal-id, not both",
            output_format="json" if output_format == "json" else "text",
        )

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        service = GoalService(db, event_store, revision_store, metrics)
        goal_repo = GoalRepository(db, event_store, revision_store, metrics)
        objective_repo = ObjectiveRepository(db, event_store, revision_store, metrics)
        key_result_repo = KeyResultRepository(db, event_store, revision_store, metrics)
        project_repo = ProjectRepository(db, event_store, revision_store, metrics)

        if view == "trace":
            include_history = True
            include_linked = True
        if include_linked_history:
            include_linked = True
            include_history = True

        resolved_goal_id = goal_id
        if goal_ref:
            resolved_goal_id = await _resolve_goal_id(goal_ref, service, pick=pick)
            if resolved_goal_id is None:
                return

        status_filter = GoalStatus(status) if status else None
        result = await service.list_objectives(
            goal_id=resolved_goal_id,
            status=status_filter,
            limit=limit,
            offset=offset,
        )

        goal_names: dict[str, str] = {}
        goal_objects: dict[str, Any] = {}
        project_names: dict[str, str] = {}
        for objective in result.items:
            if objective.goal_id and objective.goal_id not in goal_names:
                goal = await goal_repo.get_by_id(objective.goal_id)
                if goal:
                    goal_names[objective.goal_id] = goal.name
                    goal_objects[objective.goal_id] = goal
                    if goal.project_id and goal.project_id not in project_names:
                        project = await project_repo.get_by_id(goal.project_id)
                        if project:
                            project_names[goal.project_id] = project.name

        if output_format == "json":
            effective_history_limit = history_limit if history_limit > 0 else 1000
            effective_linked_limit = linked_limit if linked_limit > 0 else 1000
            objective_summaries = await service.get_objective_summaries_for_objectives(
                result.items
            )
            objective_ids = [objective.id for objective in result.items]
            activity_map = await service.get_objective_last_activity_map(objective_ids)
            transition_map = await service.get_objective_last_transition_map(
                objective_ids
            )

            payload_items = []
            for objective in result.items:
                goal_name = (
                    goal_names.get(objective.goal_id) if objective.goal_id else None
                )
                goal_obj = (
                    goal_objects.get(objective.goal_id) if objective.goal_id else None
                )
                project_id = goal_obj.project_id if goal_obj is not None else None
                project_name = (
                    project_names.get(project_id) if project_id is not None else None
                )
                summary = objective_summaries.get(objective.id)
                objective_last_activity = _to_iso(activity_map.get(objective.id))
                objective_last_transition = _to_iso(transition_map.get(objective.id))
                terminal_reason = (
                    _objective_terminal_reason_from_summary(summary)
                    if summary is not None
                    else None
                )
                links = _objective_list_links(
                    objective,
                    project_id=project_id,
                )
                next_steps = (
                    _objective_lifecycle_next_steps(
                        summary,
                        project_id=project_id,
                        terminal_reason=terminal_reason,
                    )
                    if summary is not None
                    else _normalize_next_steps(
                        f"objective show {objective.id}",
                        f"keyresult list --objective-id {objective.id} --format json",
                        f"goal show {objective.goal_id}" if objective.goal_id else "",
                    )
                )
                if view == "overview":
                    payload = {
                        "id": objective.id,
                        "name": objective.name,
                        "status": objective.status.value,
                        "goal_id": objective.goal_id,
                        "goal_name": goal_name,
                        "project_id": project_id,
                        "project_name": project_name,
                        "progress_percent": objective.progress_percent,
                        "effective_rollup": (
                            _goal_effective_rollup_struct(summary.effective_rollup)
                            if summary is not None
                            else None
                        ),
                        "effective_hierarchy": (
                            _objective_effective_hierarchy_payload(summary)
                            if summary is not None
                            else None
                        ),
                        "created_at": _to_iso(objective.created_at),
                        "updated_at": _to_iso(objective.updated_at),
                        "last_activity_at": objective_last_activity,
                        "last_transition_at": objective_last_transition,
                        "terminal_reason": terminal_reason,
                        "links": links,
                    }
                else:
                    payload = _public_entity_payload(objective)
                    payload.update(
                        {
                            "goal_name": goal_name,
                            "project_id": project_id,
                            "project_name": project_name,
                            "links": links,
                            "effective_rollup": (
                                _goal_effective_rollup_struct(summary.effective_rollup)
                                if summary is not None
                                else None
                            ),
                            "effective_hierarchy": (
                                _objective_effective_hierarchy_payload(summary)
                                if summary is not None
                                else None
                            ),
                            "stats": (
                                _objective_stats_payload(summary)
                                if summary is not None
                                else None
                            ),
                            "last_activity_at": objective_last_activity,
                            "last_transition_at": objective_last_transition,
                            "terminal_reason": terminal_reason,
                            "completion_context": _objective_completion_context_payload(
                                objective_id=objective.id,
                                goal_id=objective.goal_id,
                                project_id=project_id,
                                terminal_reason=terminal_reason,
                            ),
                        }
                    )

                if include_linked:
                    key_results_result = await key_result_repo.get_by_objective(
                        objective.id, limit=effective_linked_limit, offset=0
                    )
                    key_results = key_results_result.items
                    payload["linked"] = {
                        "key_results": [
                            {
                                "id": key_result.id,
                                "name": key_result.name,
                                "status": key_result.status.value,
                                "progress_percent": key_result.progress_percent,
                                "updated_at": _to_iso(key_result.updated_at),
                                "links": _normalize_command_links(
                                    {"self": f"pms keyresult show {key_result.id}"}
                                ),
                            }
                            for key_result in key_results
                        ],
                        "page": {
                            "total_count": key_results_result.total_count,
                            "limit": key_results_result.limit,
                            "offset": key_results_result.offset,
                            "has_more": key_results_result.has_more,
                            "next_offset": key_results_result.offset
                            + key_results_result.limit
                            if key_results_result.has_more
                            else None,
                        },
                    }
                    if include_linked_history:
                        payload["linked_history"] = {
                            key_result.id: [
                                {
                                    "revision_number": rev.revision_number,
                                    "change_type": rev.change_type.value,
                                    "message": rev.message,
                                    "created_by": rev.created_by,
                                    "created_at": rev.created_at,
                                }
                                for rev in await key_result_repo.get_history(
                                    key_result.id, limit=effective_history_limit
                                )
                            ]
                            for key_result in key_results
                        }

                if include_history:
                    history = await objective_repo.get_history(
                        objective.id, limit=effective_history_limit
                    )
                    payload["history"] = [
                        {
                            "revision_number": rev.revision_number,
                            "change_type": rev.change_type.value,
                            "message": rev.message,
                            "created_by": rev.created_by,
                            "created_at": rev.created_at,
                        }
                        for rev in history
                    ]

                payload = _payload_with_normalized_next_steps(payload, *next_steps)
                payload_items.append(payload)

            base_cmd = "pms objective list --format json"
            if resolved_goal_id:
                base_cmd += f" --goal-id {resolved_goal_id}"
            if status:
                base_cmd += f" --status {status}"
            if view != "overview":
                base_cmd += f" --view {view}"
            payload = {
                "items": payload_items,
                "page": {
                    "total_count": result.total_count,
                    "limit": result.limit,
                    "offset": result.offset,
                    "has_more": result.has_more,
                    "next_offset": result.offset + result.limit
                    if result.has_more
                    else None,
                },
                "links": _normalize_command_links(
                    {
                        "self": f"{base_cmd} --limit {limit} --offset {offset}",
                        "next": (
                            f"{base_cmd} --limit {limit} "
                            f"--offset {result.offset + result.limit}"
                            if result.has_more
                            else None
                        ),
                    }
                ),
            }
            list_next_steps = _normalize_next_steps(
                (f"objective show {result.items[0].id}" if result.items else ""),
                (
                    f"keyresult list --objective-id {result.items[0].id} --format json"
                    if result.items
                    else ""
                ),
                (
                    f"goal show {resolved_goal_id}"
                    if resolved_goal_id
                    else "goal list --format json"
                ),
                (
                    f"objective create <name> --goal-id {resolved_goal_id} --format json"
                    if resolved_goal_id
                    else "objective create <name> --goal <goal> --format json"
                ),
            )
            payload = _payload_with_normalized_next_steps(payload, *list_next_steps)
            click.echo(json.dumps(payload, indent=2, default=str))
            return

        if output_format == "csv":
            headers = [
                "id",
                "goal_id",
                "goal_name",
                "name",
                "status",
                "progress_percent",
                "target_date",
                "updated_at",
            ]
            click.echo(_csv_row(headers))
            for o in result.items:
                row = [
                    o.id,
                    o.goal_id,
                    goal_names.get(o.goal_id, "") if o.goal_id else "",
                    o.name,
                    o.status.value,
                    str(o.progress_percent),
                    o.target_date.isoformat() if o.target_date else "",
                    str(o.updated_at)[:19] if o.updated_at else "",
                ]
                click.echo(_csv_row(row))
            return

        from pms.utils.time import format_relative

        table = Table(title="Objectives")
        table.add_column("Name", style="cyan")
        table.add_column("Status")
        table.add_column("Progress")
        table.add_column("Goal")
        table.add_column("Target")
        table.add_column("Updated")
        for o in result.items:
            target = o.target_date.date().isoformat() if o.target_date else "-"
            goal_label = goal_names.get(o.goal_id, o.goal_id) if o.goal_id else "-"
            table.add_row(
                o.name,
                o.status.value,
                f"{o.progress_percent}%",
                goal_label,
                target,
                format_relative(o.updated_at),
            )
        console.print(table)
        console.print(f"[dim]Total: {result.total_count}[/dim]")
    finally:
        await db.disconnect()


@objective.command("show")
@click.argument("objective_ref")
@click.option("--goal", "goal_ref", help="Goal name or ID (disambiguate)")
@click.option(
    "--pick",
    is_flag=True,
    help="Pick from matching objectives when name is ambiguous",
)
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json", "csv"]),
    default="text",
    show_default=True,
)
@click.option(
    "--view",
    type=click.Choice(["overview", "detail", "trace"]),
    default="detail",
    show_default=True,
    help="Output view profile (overview/detail/trace)",
)
@click.option("--include-history", is_flag=True, help="Include history in JSON")
@click.option("--include-linked", is_flag=True, help="Include linked items in JSON")
@click.option(
    "--include-linked-history",
    is_flag=True,
    help="Include history for linked items in JSON",
)
@click.option("--history-limit", type=int, default=20, show_default=True)
@click.option("--linked-limit", type=int, default=20, show_default=True)
@async_command
async def objective_show(
    objective_ref: str,
    goal_ref: str | None,
    pick: bool,
    output_format: str,
    view: str,
    include_history: bool,
    include_linked: bool,
    include_linked_history: bool,
    history_limit: int,
    linked_limit: int,
) -> None:
    """Show objective details."""
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.repositories.goal_repository import GoalRepository
    from pms.repositories.key_result_repository import KeyResultRepository
    from pms.repositories.objective_repository import ObjectiveRepository
    from pms.repositories.project_repository import ProjectRepository
    from pms.services.actor_service import ActorService
    from pms.services.goal_service import GoalService

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        service = GoalService(db, event_store, revision_store, metrics)
        actor_service = ActorService(db, event_store, revision_store, metrics)
        objective_repo = ObjectiveRepository(db, event_store, revision_store, metrics)
        goal_repo = GoalRepository(db, event_store, revision_store, metrics)
        key_result_repo = KeyResultRepository(db, event_store, revision_store, metrics)
        project_repo = ProjectRepository(db, event_store, revision_store, metrics)

        if view == "trace":
            include_history = True
            include_linked = True
        if include_linked_history:
            include_linked = True
            include_history = True

        resolved_objective_id = await _resolve_objective_id(
            objective_ref, goal_ref, service, pick=pick
        )
        if resolved_objective_id is None:
            return

        objective = await service.get_objective(resolved_objective_id)
        if objective is None:
            console.print(f"[red]Objective '{objective_ref}' not found[/red]")
            return

        goal_obj = None
        goal_name = None
        project_name = None
        project_id = None
        if objective.goal_id:
            goal_obj = await goal_repo.get_by_id(objective.goal_id)
            if goal_obj:
                goal_name = goal_obj.name
                project_id = goal_obj.project_id
                if project_id:
                    project = await project_repo.get_by_id(project_id)
                    if project:
                        project_name = project.name
        owner_map = await _resolve_actor_reference_map(
            [objective.owner_id, objective.owner],
            actor_service,
        )
        objective_rollup_entities: list[Any] = [objective]
        objective_rollup_actor_map = dict(owner_map)

        if output_format == "json":
            effective_history_limit = history_limit if history_limit > 0 else 1000
            effective_linked_limit = linked_limit if linked_limit > 0 else 1000
            objective_summary = await service.get_objective_summary(objective.id)
            objective_activity_map = await service.get_objective_last_activity_map(
                [objective.id]
            )
            objective_transition_map = await service.get_objective_last_transition_map(
                [objective.id]
            )
            objective_last_activity = _to_iso(objective_activity_map.get(objective.id))
            objective_last_transition = _to_iso(
                objective_transition_map.get(objective.id)
            )
            objective_terminal_reason = (
                _objective_terminal_reason_from_summary(objective_summary)
                if objective_summary is not None
                else None
            )
            objective_completion_context = _objective_completion_context_payload(
                objective_id=objective.id,
                goal_id=objective.goal_id,
                project_id=project_id,
                terminal_reason=objective_terminal_reason,
            )
            links = _objective_detail_links(
                objective,
                project_id=project_id,
                owner_link=_actor_reference_link(
                    objective.owner,
                    owner_map,
                    actor_id=objective.owner_id,
                ),
            )
            next_steps = (
                _objective_lifecycle_next_steps(
                    objective_summary,
                    project_id=project_id,
                    terminal_reason=objective_terminal_reason,
                )
                if objective_summary is not None
                else _normalize_next_steps(
                    f"objective show {objective.id}",
                    f"keyresult list --objective-id {objective.id} --format json",
                    f"goal show {objective.goal_id}" if objective.goal_id else "",
                )
            )

            if view == "overview":
                payload: dict[str, Any] = {
                    "id": objective.id,
                    "name": objective.name,
                    "status": objective.status.value,
                    "goal_id": objective.goal_id,
                    "goal_name": goal_name,
                    "project_id": project_id,
                    "project_name": project_name,
                    "owner": objective.owner,
                    "ownership": _actor_reference_payload(
                        objective.owner,
                        owner_map,
                        actor_id=objective.owner_id,
                    ),
                    "progress_percent": objective.progress_percent,
                    "effective_rollup": (
                        _goal_effective_rollup_struct(
                            objective_summary.effective_rollup
                        )
                        if objective_summary is not None
                        else None
                    ),
                    "effective_hierarchy": (
                        _objective_effective_hierarchy_payload(objective_summary)
                        if objective_summary is not None
                        else None
                    ),
                    "created_at": _to_iso(objective.created_at),
                    "updated_at": _to_iso(objective.updated_at),
                    "last_activity_at": objective_last_activity,
                    "last_transition_at": objective_last_transition,
                    "terminal_reason": objective_terminal_reason,
                    "links": links,
                }
            else:
                payload = _public_entity_payload(objective)
                payload.update(
                    {
                        "goal_name": goal_name,
                        "project_id": project_id,
                        "project_name": project_name,
                        "ownership": _actor_reference_payload(
                            objective.owner,
                            owner_map,
                            actor_id=objective.owner_id,
                        ),
                        "links": links,
                        "stats": (
                            _objective_stats_payload(objective_summary)
                            if objective_summary is not None
                            else None
                        ),
                        "effective_rollup": (
                            _goal_effective_rollup_struct(
                                objective_summary.effective_rollup
                            )
                            if objective_summary is not None
                            else None
                        ),
                        "effective_hierarchy": (
                            _objective_effective_hierarchy_payload(objective_summary)
                            if objective_summary is not None
                            else None
                        ),
                        "last_activity_at": objective_last_activity,
                        "last_transition_at": objective_last_transition,
                        "terminal_reason": objective_terminal_reason,
                        "completion_context": objective_completion_context,
                    }
                )

            if include_linked:
                key_results_result = await key_result_repo.get_by_objective(
                    objective.id, limit=effective_linked_limit, offset=0
                )
                key_results = key_results_result.items
                key_result_owner_map = await _resolve_actor_reference_map(
                    [
                        actor_key
                        for key_result in key_results
                        for actor_key in (
                            key_result.owner_id,
                            key_result.owner,
                        )
                    ],
                    actor_service,
                )
                payload["linked"] = {
                    "goal": (
                        {
                            "id": goal_obj.id,
                            "name": goal_obj.name,
                            "status": goal_obj.status.value,
                            "progress_percent": goal_obj.progress_percent,
                            "project_id": goal_obj.project_id,
                            "links": _normalize_command_links(
                                {
                                    "self": f"pms goal show {goal_obj.id}",
                                    "summary": f"pms goal summary {goal_obj.id}",
                                    "project": (
                                        f"pms project show {goal_obj.project_id} --format json"
                                        if goal_obj.project_id
                                        else None
                                    ),
                                    "objectives": (
                                        f"pms objective list --goal-id {goal_obj.id} --format json"
                                    ),
                                }
                            ),
                        }
                        if goal_obj is not None
                        else None
                    ),
                    "key_results": [
                        {
                            "id": key_result.id,
                            "name": key_result.name,
                            "status": key_result.status.value,
                            "progress_percent": key_result.progress_percent,
                            "owner": key_result.owner,
                            "ownership": _actor_reference_payload(
                                key_result.owner,
                                key_result_owner_map,
                                actor_id=key_result.owner_id,
                            ),
                            "updated_at": _to_iso(key_result.updated_at),
                            "links": _normalize_command_links(
                                {
                                    "self": f"pms keyresult show {key_result.id}",
                                    "objective": f"pms objective show {objective.id}",
                                    "goal": (
                                        f"pms goal show {objective.goal_id}"
                                        if objective.goal_id
                                        else None
                                    ),
                                    "owner": _actor_reference_link(
                                        key_result.owner,
                                        key_result_owner_map,
                                        actor_id=key_result.owner_id,
                                    ),
                                }
                            ),
                        }
                        for key_result in key_results
                    ],
                    "page": {
                        "total_count": key_results_result.total_count,
                        "limit": key_results_result.limit,
                        "offset": key_results_result.offset,
                        "has_more": key_results_result.has_more,
                        "next_offset": key_results_result.offset
                        + key_results_result.limit
                        if key_results_result.has_more
                        else None,
                    },
                }
                if include_linked_history:
                    payload["linked_history"] = {
                        key_result.id: [
                            {
                                "revision_number": rev.revision_number,
                                "change_type": rev.change_type.value,
                                "message": rev.message,
                                "created_by": rev.created_by,
                                "created_at": rev.created_at,
                            }
                            for rev in await key_result_repo.get_history(
                                key_result.id, limit=effective_history_limit
                            )
                        ]
                        for key_result in key_results
                    }
                objective_rollup_entities = [objective, *key_results]
                objective_rollup_actor_map = {
                    **owner_map,
                    **key_result_owner_map,
                }

            if include_history:
                history = await objective_repo.get_history(
                    objective.id, limit=effective_history_limit
                )
                payload["history"] = [
                    {
                        "revision_number": rev.revision_number,
                        "change_type": rev.change_type.value,
                        "message": rev.message,
                        "created_by": rev.created_by,
                        "created_at": rev.created_at,
                    }
                    for rev in history
                ]

            payload["actor_rollups"] = _actor_rollups_payload(
                owners=objective_rollup_entities,
                owner_map=objective_rollup_actor_map,
                population_basis="objective_surface_visible_entities",
            )
            payload = _payload_with_normalized_next_steps(payload, *next_steps)

            click.echo(json.dumps(payload, indent=2, default=str))
            return

        if output_format == "csv":
            headers = [
                "id",
                "goal_id",
                "goal_name",
                "name",
                "status",
                "progress_percent",
                "target_date",
                "owner",
            ]
            click.echo(_csv_row(headers))
            row = [
                objective.id,
                objective.goal_id,
                goal_name or "",
                objective.name,
                objective.status.value,
                str(objective.progress_percent),
                objective.target_date.isoformat() if objective.target_date else "",
                objective.owner or "",
            ]
            click.echo(_csv_row(row))
            return

        if view == "overview":
            console.print(f"[bold cyan]{objective.name}[/bold cyan]")
            console.print(f"Status: {objective.status.value}")
            console.print(f"Progress: {objective.progress_percent}%")
            if objective.goal_id:
                if goal_name:
                    console.print(f"Goal: {goal_name} ({objective.goal_id})")
                else:
                    console.print(f"Goal: {objective.goal_id}")
            _print_next_steps(
                f'pms keyresult list --objective "{objective.name}"'
                + (f' --goal "{goal_name}"' if goal_name else ""),
                f"pms objective update {objective.id}",
            )
            return

        console.print(f"[bold cyan]{objective.name}[/bold cyan]")
        console.print(f"Status: {objective.status.value}")
        console.print(f"Progress: {objective.progress_percent}%")
        if objective.goal_id:
            if goal_name:
                console.print(f"Goal: {goal_name} ({objective.goal_id})")
            else:
                console.print(f"Goal: {objective.goal_id}")
        if objective.description:
            console.print(f"Description: {objective.description}")
        if objective.target_date:
            console.print(f"Target: {objective.target_date.isoformat()}")
        if objective.owner:
            console.print(f"Owner: {objective.owner}")
        if objective.tags:
            console.print(f"Tags: {', '.join(objective.tags)}")
        if objective.workflow_id:
            console.print(f"Workflow: {objective.workflow_id}")
        if objective.current_state:
            console.print(f"Workflow State: {objective.current_state}")
        _print_next_steps(
            (f"pms goal show {objective.goal_id}" if objective.goal_id else ""),
            f'pms keyresult list --objective "{objective.name}"'
            + (f' --goal "{goal_name}"' if goal_name else ""),
            f"pms objective update {objective.id}",
            f"pms objective complete {objective.id}",
        )
    finally:
        await db.disconnect()


@objective.command("update")
@click.argument("objective_ref")
@click.option("--goal", "goal_ref", help="Goal name or ID (disambiguate)")
@click.option(
    "--pick",
    is_flag=True,
    help="Pick from matching objectives when name is ambiguous",
)
@click.option("--name", help="New objective name")
@click.option("--description", help="New description")
@click.option(
    "--status",
    type=click.Choice(["active", "completed", "on_hold", "archived"]),
)
@click.option("--target-date", help="Target date (ISO format)")
@click.option("--owner", help="Objective owner")
@click.option("--clear-owner", is_flag=True, help="Remove objective owner")
@click.option("-t", "--tag", "tags", multiple=True, help="Objective tags")
@click.option("--progress", type=int, help="Progress percent (0-100)")
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json"]),
    default="text",
    show_default=True,
)
@async_command
async def objective_update(
    objective_ref: str,
    goal_ref: str | None,
    pick: bool,
    name: str | None,
    description: str | None,
    status: str | None,
    target_date: str | None,
    owner: str | None,
    clear_owner: bool,
    tags: tuple[str, ...],
    progress: int | None,
    output_format: str,
) -> None:
    """Update an objective."""
    from datetime import datetime

    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.models import GoalStatus
    from pms.services.actor_service import ActorService
    from pms.services.goal_service import GoalService

    target_dt = None
    if target_date:
        try:
            target_dt = datetime.fromisoformat(target_date)
        except ValueError:
            _emit_cli_error(
                "Invalid target date format (use ISO)",
                output_format="json" if output_format == "json" else "text",
            )

    if progress is not None and (progress < 0 or progress > 100):
        _emit_cli_error(
            "Progress must be 0-100",
            output_format="json" if output_format == "json" else "text",
        )
    if clear_owner and owner:
        _emit_cli_error(
            "Use --owner or --clear-owner, not both",
            output_format="json" if output_format == "json" else "text",
        )

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        service = GoalService(db, event_store, revision_store, metrics)
        actor_service = ActorService(db, event_store, revision_store, metrics)

        status_enum = GoalStatus(status) if status else None
        resolved_objective_id = await _resolve_objective_id(
            objective_ref, goal_ref, service, pick=pick
        )
        if resolved_objective_id is None:
            return

        updated = await service.update_objective(
            objective_id=resolved_objective_id,
            name=name,
            description=description,
            status=status_enum,
            target_date=target_dt,
            owner=owner,
            clear_owner=clear_owner,
            tags=list(tags) if tags else None,
            progress_percent=progress,
        )

        if updated is None:
            console.print(f"[red]Objective '{objective_ref}' not found[/red]")
            return

        next_steps = _normalize_next_steps(
            f"pms objective show {updated.id}",
            f'pms keyresult list --objective "{updated.name}"',
        )
        if output_format == "json":
            owner_map = await _resolve_owner_map([updated], actor_service)
            payload = _payload_with_normalized_next_steps(
                {
                    "objective": {
                        **_public_entity_payload(updated),
                        "ownership": _ownership_payload(updated, owner_map),
                    },
                    "links": _normalize_command_links(
                        {
                            "self": f"objective show {updated.id}",
                            "key_results": f'keyresult list --objective "{updated.name}"',
                            "owner": _ownership_link(updated, owner_map),
                        }
                    ),
                },
                *next_steps,
            )
            click.echo(json.dumps(payload, default=str))
            return

        console.print(f"[green]Updated objective:[/green] {updated.name}")
        _print_next_steps(*next_steps)
    finally:
        await db.disconnect()


