@keyresult.command("create")
@click.argument("name")
@click.option("--objective", "objective_ref", help="Parent objective name or ID")
@click.option("--objective-id", help="Parent objective ID")
@click.option("--goal", "goal_ref", help="Goal name or ID (disambiguate objective)")
@click.option(
    "--pick",
    is_flag=True,
    help="Pick from matching objectives when name is ambiguous",
)
@click.option("-d", "--description", help="Key result description")
@click.option("--current", "current_value", type=float, help="Current value")
@click.option("--target", "target_value", type=float, help="Target value")
@click.option("--unit", help="Unit of measure")
@click.option("--owner", help="Key result owner")
@click.option("--clear-owner", is_flag=True, help="Remove key result owner")
@click.option("-t", "--tag", "tags", multiple=True, help="Key result tags")
@click.option("--progress", type=int, help="Progress percent (0-100)")
@async_command
async def keyresult_create(
    name: str,
    objective_ref: str | None,
    objective_id: str | None,
    goal_ref: str | None,
    pick: bool,
    description: str | None,
    current_value: float | None,
    target_value: float | None,
    unit: str | None,
    owner: str | None,
    clear_owner: bool,
    tags: tuple[str, ...],
    progress: int | None,
) -> None:
    """Create a new key result."""
    if progress is not None and (progress < 0 or progress > 100):
        _emit_cli_error("Progress must be 0-100", output_format="text")
    if objective_ref and objective_id:
        _emit_cli_error(
            "Use --objective or --objective-id, not both", output_format="text"
        )
    if goal_ref and objective_id:
        _emit_cli_error(
            "Use --goal with --objective, not --objective-id", output_format="text"
        )
    if not objective_ref and not objective_id:
        _emit_cli_error(
            "Objective is required (--objective or --objective-id)",
            output_format="text",
        )

    from pms.db.connection import init_database

    db = await init_database()
    try:
        from pms.core.events import EventStore
        from pms.core.metrics import MetricsCollector
        from pms.core.revisions import RevisionStore
        from pms.services.goal_service import GoalService

        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        service = GoalService(db, event_store, revision_store, metrics)

        resolved_objective_id = objective_id
        if objective_ref:
            resolved_objective_id = await _resolve_objective_id(
                objective_ref, goal_ref, service, pick=pick
            )
            if resolved_objective_id is None:
                return

        key_result = await service.create_key_result(
            objective_id=resolved_objective_id,
            name=name,
            description=description,
            current_value=current_value,
            target_value=target_value,
            unit=unit,
            owner=owner,
            tags=list(tags) if tags else None,
            progress_percent=progress,
        )

        console.print(f"[green]Created key result:[/green] {key_result.name}")
        console.print(f"[dim]ID: {key_result.id}[/dim]")
        objective_label = objective_ref
        if not objective_label and resolved_objective_id:
            objective_obj = await service.get_objective(resolved_objective_id)
            if objective_obj:
                objective_label = objective_obj.name
        _print_next_steps(
            f"pms keyresult show {key_result.id}",
            (
                f'pms objective show "{objective_label}"'
                if objective_label
                else f"pms objective show {resolved_objective_id}"
            ),
        )
    finally:
        await db.disconnect()


@keyresult.command("list")
@click.option("--objective", "objective_ref", help="Filter by objective name or ID")
@click.option("--objective-id", help="Filter by objective ID")
@click.option("--goal", "goal_ref", help="Goal name or ID (disambiguate objective)")
@click.option(
    "--pick",
    is_flag=True,
    help="Pick from matching objectives when name is ambiguous",
)
@click.option(
    "-s",
    "--status",
    type=click.Choice(["active", "completed", "on_hold", "archived"]),
)
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["table", "json", "csv"]),
    default="table",
    show_default=True,
)
@click.option(
    "--view",
    type=click.Choice(["overview", "detail", "trace"]),
    default="overview",
    show_default=True,
    help="Output view profile (overview/detail/trace)",
)
@click.option("--include-history", is_flag=True, help="Include history in JSON")
@click.option("--include-linked", is_flag=True, help="Include linked items in JSON")
@click.option(
    "--include-linked-history",
    is_flag=True,
    help="Include history for linked items in JSON",
)
@click.option("--history-limit", type=int, default=20, show_default=True)
@click.option("--linked-limit", type=int, default=20, show_default=True)
@click.option("--limit", type=int, default=100, show_default=True)
@click.option("--offset", type=int, default=0, show_default=True)
@async_command
async def keyresult_list(
    objective_ref: str | None,
    objective_id: str | None,
    goal_ref: str | None,
    pick: bool,
    status: str | None,
    output_format: str,
    view: str,
    include_history: bool,
    include_linked: bool,
    include_linked_history: bool,
    history_limit: int,
    linked_limit: int,
    limit: int,
    offset: int,
) -> None:
    """List key results."""
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.models import GoalStatus
    from pms.repositories.goal_repository import GoalRepository
    from pms.repositories.key_result_repository import KeyResultRepository
    from pms.repositories.objective_repository import ObjectiveRepository
    from pms.repositories.project_repository import ProjectRepository
    from pms.services.actor_service import ActorService
    from pms.services.goal_service import GoalService

    if objective_ref and objective_id:
        _emit_cli_error(
            "Use --objective or --objective-id, not both",
            output_format="json" if output_format == "json" else "text",
        )
    if goal_ref and objective_id:
        _emit_cli_error(
            "Use --goal with --objective, not --objective-id",
            output_format="json" if output_format == "json" else "text",
        )
    if goal_ref and not objective_ref and not objective_id:
        _emit_cli_error(
            "Use --goal with --objective",
            output_format="json" if output_format == "json" else "text",
        )

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        service = GoalService(db, event_store, revision_store, metrics)
        actor_service = ActorService(db, event_store, revision_store, metrics)
        goal_repo = GoalRepository(db, event_store, revision_store, metrics)
        key_result_repo = KeyResultRepository(db, event_store, revision_store, metrics)
        objective_repo = ObjectiveRepository(db, event_store, revision_store, metrics)
        project_repo = ProjectRepository(db, event_store, revision_store, metrics)

        if view == "trace":
            include_history = True
            include_linked = True
        if include_linked_history:
            include_linked = True
            include_history = True

        resolved_objective_id = objective_id
        if objective_ref:
            resolved_objective_id = await _resolve_objective_id(
                objective_ref, goal_ref, service, pick=pick
            )
            if resolved_objective_id is None:
                return

        status_filter = GoalStatus(status) if status else None
        result = await service.list_key_results(
            objective_id=resolved_objective_id,
            status=status_filter,
            limit=limit,
            offset=offset,
        )

        objective_names: dict[str, str] = {}
        objective_objects: dict[str, Any] = {}
        goal_names: dict[str, str] = {}
        goal_objects: dict[str, Any] = {}
        project_names: dict[str, str] = {}
        for key_result in result.items:
            if (
                key_result.objective_id
                and key_result.objective_id not in objective_names
            ):
                objective = await objective_repo.get_by_id(key_result.objective_id)
                if objective:
                    objective_names[key_result.objective_id] = objective.name
                    objective_objects[key_result.objective_id] = objective
                    if objective.goal_id and objective.goal_id not in goal_names:
                        goal = await goal_repo.get_by_id(objective.goal_id)
                        if goal:
                            goal_names[objective.goal_id] = goal.name
                            goal_objects[objective.goal_id] = goal
                            if goal.project_id and goal.project_id not in project_names:
                                project = await project_repo.get_by_id(goal.project_id)
                                if project:
                                    project_names[goal.project_id] = project.name

        if output_format == "json":
            effective_history_limit = history_limit if history_limit > 0 else 1000
            key_result_ids = [key_result.id for key_result in result.items]
            activity_map = await service.get_key_result_last_activity_map(
                key_result_ids
            )
            transition_map = await service.get_key_result_last_transition_map(
                key_result_ids
            )
            owner_map = await _resolve_actor_reference_map(
                [
                    actor_key
                    for key_result in result.items
                    for actor_key in (
                        key_result.owner_id,
                        key_result.owner,
                    )
                ],
                actor_service,
            )

            payload_items = []
            for key_result in result.items:
                objective_obj = (
                    objective_objects.get(key_result.objective_id)
                    if key_result.objective_id
                    else None
                )
                objective_name = (
                    objective_names.get(key_result.objective_id)
                    if key_result.objective_id
                    else None
                )
                goal_obj = (
                    goal_objects.get(objective_obj.goal_id)
                    if objective_obj is not None and objective_obj.goal_id
                    else None
                )
                goal_id = (
                    goal_obj.id
                    if goal_obj is not None
                    else objective_obj.goal_id
                    if objective_obj is not None
                    else None
                )
                goal_name = goal_names.get(goal_id) if goal_id else None
                project_id = goal_obj.project_id if goal_obj is not None else None
                project_name = (
                    project_names.get(project_id) if project_id is not None else None
                )
                terminal_reason = _key_result_terminal_reason(key_result)
                links = _key_result_list_links(
                    key_result,
                    goal_id=goal_id,
                    project_id=project_id,
                )
                next_steps = _key_result_lifecycle_next_steps(
                    key_result_id=key_result.id,
                    objective_id=key_result.objective_id,
                    goal_id=goal_id,
                    project_id=project_id,
                    terminal_reason=terminal_reason,
                )
                if view == "overview":
                    payload = {
                        "id": key_result.id,
                        "name": key_result.name,
                        "status": key_result.status.value,
                        "objective_id": key_result.objective_id,
                        "objective_name": objective_name,
                        "goal_id": goal_id,
                        "goal_name": goal_name,
                        "project_id": project_id,
                        "project_name": project_name,
                        "owner": key_result.owner,
                        "ownership": _actor_reference_payload(
                            key_result.owner,
                            owner_map,
                            actor_id=key_result.owner_id,
                        ),
                        "progress_percent": key_result.progress_percent,
                        "effective_rollup": _key_result_effective_rollup_payload(
                            key_result
                        ),
                        "created_at": _to_iso(key_result.created_at),
                        "updated_at": _to_iso(key_result.updated_at),
                        "last_activity_at": _to_iso(activity_map.get(key_result.id)),
                        "last_transition_at": _to_iso(
                            transition_map.get(key_result.id)
                        ),
                        "terminal_reason": terminal_reason,
                        "links": links,
                    }
                else:
                    payload = _public_entity_payload(key_result)
                    payload.update(
                        {
                            "objective_name": objective_name,
                            "goal_id": goal_id,
                            "goal_name": goal_name,
                            "project_id": project_id,
                            "project_name": project_name,
                            "ownership": _actor_reference_payload(
                                key_result.owner,
                                owner_map,
                                actor_id=key_result.owner_id,
                            ),
                            "effective_rollup": _key_result_effective_rollup_payload(
                                key_result
                            ),
                            "last_activity_at": _to_iso(
                                activity_map.get(key_result.id)
                            ),
                            "last_transition_at": _to_iso(
                                transition_map.get(key_result.id)
                            ),
                            "terminal_reason": terminal_reason,
                            "links": links,
                        }
                    )

                if include_linked and objective_obj is not None:
                    payload["linked"] = {
                        "objective": {
                            "id": objective_obj.id,
                            "name": objective_obj.name,
                            "status": objective_obj.status.value,
                            "progress_percent": objective_obj.progress_percent,
                            "updated_at": _to_iso(objective_obj.updated_at),
                            "owner": objective_obj.owner,
                            "ownership": _actor_reference_payload(
                                objective_obj.owner,
                                owner_map,
                                actor_id=objective_obj.owner_id,
                            ),
                            "links": _normalize_command_links(
                                {
                                    "self": f"objective show {objective_obj.id}",
                                    "goal": (
                                        f"goal show {objective_obj.goal_id}"
                                        if objective_obj.goal_id
                                        else None
                                    ),
                                    "key_results": (
                                        f"keyresult list --objective-id {objective_obj.id} --format json"
                                    ),
                                    "owner": _actor_reference_link(
                                        objective_obj.owner,
                                        owner_map,
                                        actor_id=objective_obj.owner_id,
                                    ),
                                }
                            ),
                        },
                        "goal": (
                            {
                                "id": goal_obj.id,
                                "name": goal_obj.name,
                                "status": goal_obj.status.value,
                                "progress_percent": goal_obj.progress_percent,
                                "project_id": goal_obj.project_id,
                                "ownership": _actor_reference_payload(
                                    goal_obj.owner,
                                    owner_map,
                                    actor_id=goal_obj.owner_id,
                                ),
                                "links": _normalize_command_links(
                                    {
                                        "self": f"goal show {goal_obj.id}",
                                        "summary": f"goal summary {goal_obj.id}",
                                        "project": (
                                            f"project show {goal_obj.project_id} --format json"
                                            if goal_obj.project_id
                                            else None
                                        ),
                                    }
                                ),
                            }
                            if goal_obj is not None
                            else None
                        ),
                    }
                    if include_linked_history:
                        history = await objective_repo.get_history(
                            objective_obj.id, limit=effective_history_limit
                        )
                        payload["linked_history"] = {
                            "objective": [
                                {
                                    "revision_number": rev.revision_number,
                                    "change_type": rev.change_type.value,
                                    "message": rev.message,
                                    "created_by": rev.created_by,
                                    "created_at": rev.created_at,
                                }
                                for rev in history
                            ]
                        }

                if include_history:
                    history = await key_result_repo.get_history(
                        key_result.id, limit=effective_history_limit
                    )
                    payload["history"] = [
                        {
                            "revision_number": rev.revision_number,
                            "change_type": rev.change_type.value,
                            "message": rev.message,
                            "created_by": rev.created_by,
                            "created_at": rev.created_at,
                        }
                        for rev in history
                    ]

                payload = _payload_with_normalized_next_steps(payload, *next_steps)
                payload_items.append(payload)

            base_cmd = "pms keyresult list --format json"
            if resolved_objective_id:
                base_cmd += f" --objective-id {resolved_objective_id}"
            if status:
                base_cmd += f" --status {status}"
            if view != "overview":
                base_cmd += f" --view {view}"
            payload = {
                "items": payload_items,
                "page": {
                    "total_count": result.total_count,
                    "limit": result.limit,
                    "offset": result.offset,
                    "has_more": result.has_more,
                    "next_offset": result.offset + result.limit
                    if result.has_more
                    else None,
                },
                "links": _normalize_command_links(
                    {
                        "self": f"{base_cmd} --limit {limit} --offset {offset}",
                        "next": (
                            f"{base_cmd} --limit {limit} "
                            f"--offset {result.offset + result.limit}"
                            if result.has_more
                            else None
                        ),
                    }
                ),
            }
            click.echo(json.dumps(payload, indent=2, default=str))
            return

        if output_format == "csv":
            headers = [
                "id",
                "objective_id",
                "objective_name",
                "name",
                "status",
                "progress_percent",
                "current_value",
                "target_value",
                "unit",
                "updated_at",
            ]
            click.echo(_csv_row(headers))
            for k in result.items:
                row = [
                    k.id,
                    k.objective_id,
                    objective_names.get(k.objective_id, "") if k.objective_id else "",
                    k.name,
                    k.status.value,
                    str(k.progress_percent),
                    str(k.current_value) if k.current_value is not None else "",
                    str(k.target_value) if k.target_value is not None else "",
                    k.unit or "",
                    str(k.updated_at)[:19] if k.updated_at else "",
                ]
                click.echo(_csv_row(row))
            return

        from pms.utils.time import format_relative

        table = Table(title="Key Results")
        table.add_column("Name", style="cyan")
        table.add_column("Status")
        table.add_column("Progress")
        table.add_column("Objective")
        table.add_column("Current/Target")
        table.add_column("Updated")
        for k in result.items:
            current = "-" if k.current_value is None else str(k.current_value)
            target = "-" if k.target_value is None else str(k.target_value)
            objective_label = (
                objective_names.get(k.objective_id, k.objective_id)
                if k.objective_id
                else "-"
            )
            table.add_row(
                k.name,
                k.status.value,
                f"{k.progress_percent}%",
                objective_label,
                f"{current}/{target}",
                format_relative(k.updated_at),
            )
        console.print(table)
        console.print(f"[dim]Total: {result.total_count}[/dim]")
    finally:
        await db.disconnect()


@keyresult.command("show")
@click.argument("key_result_ref")
@click.option("--objective", "objective_ref", help="Objective name or ID")
@click.option("--goal", "goal_ref", help="Goal name or ID (disambiguate)")
@click.option(
    "--pick",
    is_flag=True,
    help="Pick from matching key results when name is ambiguous",
)
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json", "csv"]),
    default="text",
    show_default=True,
)
@click.option(
    "--view",
    type=click.Choice(["overview", "detail", "trace"]),
    default="detail",
    show_default=True,
    help="Output view profile (overview/detail/trace)",
)
@click.option("--include-history", is_flag=True, help="Include history in JSON")
@click.option("--include-linked", is_flag=True, help="Include linked items in JSON")
@click.option(
    "--include-linked-history",
    is_flag=True,
    help="Include history for linked items in JSON",
)
@click.option("--history-limit", type=int, default=20, show_default=True)
@async_command
async def keyresult_show(
    key_result_ref: str,
    objective_ref: str | None,
    goal_ref: str | None,
    pick: bool,
    output_format: str,
    view: str,
    include_history: bool,
    include_linked: bool,
    include_linked_history: bool,
    history_limit: int,
) -> None:
    """Show key result details."""
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.repositories.goal_repository import GoalRepository
    from pms.repositories.key_result_repository import KeyResultRepository
    from pms.repositories.objective_repository import ObjectiveRepository
    from pms.repositories.project_repository import ProjectRepository
    from pms.services.actor_service import ActorService
    from pms.services.goal_service import GoalService

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        service = GoalService(db, event_store, revision_store, metrics)
        actor_service = ActorService(db, event_store, revision_store, metrics)
        goal_repo = GoalRepository(db, event_store, revision_store, metrics)
        key_result_repo = KeyResultRepository(db, event_store, revision_store, metrics)
        objective_repo = ObjectiveRepository(db, event_store, revision_store, metrics)
        project_repo = ProjectRepository(db, event_store, revision_store, metrics)

        if view == "trace":
            include_history = True
            include_linked = True
        if include_linked_history:
            include_linked = True
            include_history = True

        resolved_key_result_id = await _resolve_key_result_id(
            key_result_ref, objective_ref, goal_ref, service, pick=pick
        )
        if resolved_key_result_id is None:
            return

        key_result = await service.get_key_result(resolved_key_result_id)
        if key_result is None:
            console.print(f"[red]Key result '{key_result_ref}' not found[/red]")
            return

        objective_name = None
        objective_obj = None
        goal_obj = None
        goal_name = None
        project_name = None
        if key_result.objective_id:
            objective_obj = await objective_repo.get_by_id(key_result.objective_id)
            if objective_obj:
                objective_name = objective_obj.name
                if objective_obj.goal_id:
                    goal_obj = await goal_repo.get_by_id(objective_obj.goal_id)
                    if goal_obj is not None:
                        goal_name = goal_obj.name
                        if goal_obj.project_id:
                            project = await project_repo.get_by_id(goal_obj.project_id)
                            if project is not None:
                                project_name = project.name
        owner_map = await _resolve_actor_reference_map(
            [
                key_result.owner_id,
                key_result.owner,
                objective_obj.owner_id if objective_obj else None,
                objective_obj.owner if objective_obj else None,
                goal_obj.owner_id if goal_obj else None,
                goal_obj.owner if goal_obj else None,
            ],
            actor_service,
        )
        activity_map = await service.get_key_result_last_activity_map([key_result.id])
        transition_map = await service.get_key_result_last_transition_map(
            [key_result.id]
        )

        if output_format == "json":
            goal_id = goal_obj.id if goal_obj is not None else None
            project_id = goal_obj.project_id if goal_obj is not None else None
            terminal_reason = _key_result_terminal_reason(key_result)
            links = _key_result_detail_links(
                key_result,
                goal_id=goal_id,
                project_id=project_id,
                owner_link=_actor_reference_link(
                    key_result.owner,
                    owner_map,
                    actor_id=key_result.owner_id,
                ),
            )
            next_steps = _key_result_lifecycle_next_steps(
                key_result_id=key_result.id,
                objective_id=key_result.objective_id,
                goal_id=goal_id,
                project_id=project_id,
                terminal_reason=terminal_reason,
            )

            if view == "overview":
                payload: dict[str, Any] = {
                    "id": key_result.id,
                    "name": key_result.name,
                    "status": key_result.status.value,
                    "objective_id": key_result.objective_id,
                    "objective_name": objective_name,
                    "goal_id": goal_id,
                    "goal_name": goal_name,
                    "project_id": project_id,
                    "project_name": project_name,
                    "owner": key_result.owner,
                    "ownership": _actor_reference_payload(
                        key_result.owner,
                        owner_map,
                        actor_id=key_result.owner_id,
                    ),
                    "progress_percent": key_result.progress_percent,
                    "effective_rollup": _key_result_effective_rollup_payload(
                        key_result
                    ),
                    "created_at": _to_iso(key_result.created_at),
                    "updated_at": _to_iso(key_result.updated_at),
                    "last_activity_at": _to_iso(activity_map.get(key_result.id)),
                    "last_transition_at": _to_iso(transition_map.get(key_result.id)),
                    "terminal_reason": terminal_reason,
                    "links": links,
                }
            else:
                payload = _public_entity_payload(key_result)
                payload.update(
                    {
                        "objective_name": objective_name,
                        "goal_id": goal_id,
                        "goal_name": goal_name,
                        "project_id": project_id,
                        "project_name": project_name,
                        "ownership": _actor_reference_payload(
                            key_result.owner,
                            owner_map,
                            actor_id=key_result.owner_id,
                        ),
                        "effective_rollup": _key_result_effective_rollup_payload(
                            key_result
                        ),
                        "last_activity_at": _to_iso(activity_map.get(key_result.id)),
                        "last_transition_at": _to_iso(
                            transition_map.get(key_result.id)
                        ),
                        "terminal_reason": terminal_reason,
                        "completion_context": _key_result_completion_context_payload(
                            key_result_id=key_result.id,
                            objective_id=key_result.objective_id,
                            goal_id=goal_id,
                            project_id=project_id,
                            terminal_reason=terminal_reason,
                        ),
                        "links": links,
                    }
                )

            if include_linked and objective_obj:
                payload["linked"] = {
                    "objective": {
                        "id": objective_obj.id,
                        "name": objective_obj.name,
                        "status": objective_obj.status.value,
                        "progress_percent": objective_obj.progress_percent,
                        "owner": objective_obj.owner,
                        "ownership": _actor_reference_payload(
                            objective_obj.owner,
                            owner_map,
                            actor_id=objective_obj.owner_id,
                        ),
                        "updated_at": _to_iso(objective_obj.updated_at),
                        "links": _normalize_command_links(
                            {
                                "self": f"pms objective show {objective_obj.id}",
                                "goal": (
                                    f"pms goal show {objective_obj.goal_id}"
                                    if objective_obj.goal_id
                                    else None
                                ),
                                "owner": _actor_reference_link(
                                    objective_obj.owner,
                                    owner_map,
                                    actor_id=objective_obj.owner_id,
                                ),
                            }
                        ),
                    },
                    "goal": (
                        {
                            "id": goal_obj.id,
                            "name": goal_obj.name,
                            "status": goal_obj.status.value,
                            "progress_percent": goal_obj.progress_percent,
                            "project_id": goal_obj.project_id,
                            "ownership": _actor_reference_payload(
                                goal_obj.owner,
                                owner_map,
                                actor_id=goal_obj.owner_id,
                            ),
                            "links": _normalize_command_links(
                                {
                                    "self": f"pms goal show {goal_obj.id}",
                                    "summary": f"pms goal summary {goal_obj.id}",
                                    "project": (
                                        f"pms project show {goal_obj.project_id} --format json"
                                        if goal_obj.project_id
                                        else None
                                    ),
                                    "objectives": (
                                        f"pms objective list --goal-id {goal_obj.id} --format json"
                                    ),
                                }
                            ),
                        }
                        if goal_obj is not None
                        else None
                    ),
                }
                if include_linked_history:
                    history = await objective_repo.get_history(
                        objective_obj.id, limit=history_limit
                    )
                    payload["linked_history"] = {
                        "objective": [
                            {
                                "revision_number": rev.revision_number,
                                "change_type": rev.change_type.value,
                                "message": rev.message,
                                "created_by": rev.created_by,
                                "created_at": rev.created_at,
                            }
                            for rev in history
                        ]
                    }

            if include_history:
                history = await key_result_repo.get_history(
                    key_result.id, limit=history_limit
                )
                payload["history"] = [
                    {
                        "revision_number": rev.revision_number,
                        "change_type": rev.change_type.value,
                        "message": rev.message,
                        "created_by": rev.created_by,
                        "created_at": rev.created_at,
                    }
                    for rev in history
                ]

            payload = _payload_with_normalized_next_steps(payload, *next_steps)
            click.echo(json.dumps(payload, default=str))
            return

        if output_format == "csv":
            headers = [
                "id",
                "objective_id",
                "objective_name",
                "name",
                "status",
                "progress_percent",
                "current_value",
                "target_value",
                "unit",
                "owner",
            ]
            click.echo(_csv_row(headers))
            row = [
                key_result.id,
                key_result.objective_id,
                objective_name or "",
                key_result.name,
                key_result.status.value,
                str(key_result.progress_percent),
                str(key_result.current_value)
                if key_result.current_value is not None
                else "",
                str(key_result.target_value)
                if key_result.target_value is not None
                else "",
                key_result.unit or "",
                key_result.owner or "",
            ]
            click.echo(_csv_row(row))
            return

        if view == "overview":
            console.print(f"[bold cyan]{key_result.name}[/bold cyan]")
            console.print(f"Status: {key_result.status.value}")
            console.print(f"Progress: {key_result.progress_percent}%")
            if key_result.objective_id:
                if objective_name:
                    console.print(
                        f"Objective: {objective_name} ({key_result.objective_id})"
                    )
                else:
                    console.print(f"Objective: {key_result.objective_id}")
            _print_next_steps(
                f"pms keyresult update {key_result.id}",
                f"pms keyresult complete {key_result.id}",
            )
            return

        console.print(f"[bold cyan]{key_result.name}[/bold cyan]")
        console.print(f"Status: {key_result.status.value}")
        console.print(f"Progress: {key_result.progress_percent}%")
        if key_result.objective_id:
            if objective_name:
                console.print(
                    f"Objective: {objective_name} ({key_result.objective_id})"
                )
            else:
                console.print(f"Objective: {key_result.objective_id}")
        if key_result.description:
            console.print(f"Description: {key_result.description}")
        if key_result.current_value is not None or key_result.target_value is not None:
            current = (
                key_result.current_value
                if key_result.current_value is not None
                else "-"
            )
            target = (
                key_result.target_value if key_result.target_value is not None else "-"
            )
            console.print(
                f"Progress Values: {current}/{target} {key_result.unit or ''}".strip()
            )
        if key_result.owner:
            console.print(f"Owner: {key_result.owner}")
        if key_result.tags:
            console.print(f"Tags: {', '.join(key_result.tags)}")
        _print_next_steps(
            (
                f"pms objective show {key_result.objective_id}"
                if key_result.objective_id
                else ""
            ),
            (f"pms goal show {goal_obj.id}" if goal_obj is not None else ""),
            f"pms keyresult update {key_result.id}",
            f"pms keyresult complete {key_result.id}",
        )
    finally:
        await db.disconnect()


@keyresult.command("update")
@click.argument("key_result_ref")
@click.option("--objective", "objective_ref", help="Objective name or ID")
@click.option("--goal", "goal_ref", help="Goal name or ID (disambiguate)")
@click.option(
    "--pick",
    is_flag=True,
    help="Pick from matching key results when name is ambiguous",
)
@click.option("--name", help="New key result name")
@click.option("--description", help="New description")
@click.option(
    "--status",
    type=click.Choice(["active", "completed", "on_hold", "archived"]),
)
@click.option("--current", "current_value", type=float, help="Current value")
@click.option("--target", "target_value", type=float, help="Target value")
@click.option("--unit", help="Unit of measure")
@click.option("--owner", help="Key result owner")
@click.option("--clear-owner", is_flag=True, help="Remove key result owner")
@click.option("-t", "--tag", "tags", multiple=True, help="Key result tags")
@click.option("--progress", type=int, help="Progress percent (0-100)")
@async_command
async def keyresult_update(
    key_result_ref: str,
    objective_ref: str | None,
    goal_ref: str | None,
    pick: bool,
    name: str | None,
    description: str | None,
    status: str | None,
    current_value: float | None,
    target_value: float | None,
    unit: str | None,
    owner: str | None,
    clear_owner: bool,
    tags: tuple[str, ...],
    progress: int | None,
) -> None:
    """Update a key result."""
    if progress is not None and (progress < 0 or progress > 100):
        _emit_cli_error("Progress must be 0-100", output_format="text")
    if clear_owner and owner:
        _emit_cli_error("Use --owner or --clear-owner, not both", output_format="text")

    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.models import GoalStatus
    from pms.services.actor_service import ActorService
    from pms.services.goal_service import GoalService

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        service = GoalService(db, event_store, revision_store, metrics)
        actor_service = ActorService(db, event_store, revision_store, metrics)

        resolved_key_result_id = await _resolve_key_result_id(
            key_result_ref, objective_ref, goal_ref, service, pick=pick
        )
        if resolved_key_result_id is None:
            return

        status_enum = GoalStatus(status) if status else None
        updated = await service.update_key_result(
            key_result_id=resolved_key_result_id,
            name=name,
            description=description,
            status=status_enum,
            current_value=current_value,
            target_value=target_value,
            unit=unit,
            owner=owner,
            clear_owner=clear_owner,
            tags=list(tags) if tags else None,
            progress_percent=progress,
        )

        if updated is None:
            console.print(f"[red]Key result '{key_result_ref}' not found[/red]")
            return

        console.print(f"[green]Updated key result:[/green] {updated.name}")
        _print_next_steps(
            f"pms keyresult show {updated.id}",
            f"pms objective show {updated.objective_id}"
            if updated.objective_id
            else "",
        )
    finally:
        await db.disconnect()


