async def _create_task_from_cli(
    project_ref: str,
    title: str,
    description: str | None,
    parent_id: str | None,
    priority: str,
    complexity: int | None,
    assignee: str | None,
    tags: tuple[str, ...],
    output_format: str,
) -> None:
    import uuid

    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.models import Priority
    from pms.repositories.project_repository import ProjectRepository
    from pms.services.actor_service import ActorService
    from pms.services.task_service import TaskService

    write_decision = _ensure_local_only_runtime_write(
        "pms task create",
        output_format=output_format,
    )

    db = await init_database()

    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)

        project_repo = ProjectRepository(db, event_store, revision_store, metrics)
        actor_service = ActorService(db, event_store, revision_store, metrics)
        task_service = TaskService(db, event_store, revision_store, metrics)

        project = None
        try:
            uuid.UUID(project_ref)
        except ValueError:
            project = None
        else:
            project = await project_repo.get_by_id(project_ref)
        if project is None:
            project = await project_repo.get_by_name(project_ref)
        if project is None:
            console.print(f"[red]Project '{project_ref}' not found[/red]")
            return

        try:
            task = await task_service.create_task(
                project_id=project.id,
                title=title,
                description=description,
                parent_id=parent_id,
                priority=Priority(priority),
                complexity_points=complexity,
                assignee=assignee,
                tags=list(tags) if tags else None,
            )
        except ValueError as exc:
            console.print(f"[red]{exc}[/red]")
            return

        await metrics.flush_best_effort(context="cli.task_create")

        task_target = _best_task_command_target(task.id, task.title, project.name)
        next_steps = _normalize_next_steps(
            f"task show {task_target}",
            f"task start {task_target} --by <user>",
            f"task complete {task_target} --by <user>",
        )

        if output_format == "json":
            assignee_map = await _resolve_assignee_map(
                [task],
                actor_service,
            )
            task_payload = _public_task_payload(
                task,
                assignee_map=assignee_map,
            )
            task_payload.update(
                {
                    "status": task.status.value,
                    "priority": task.priority.value,
                    "project_name": project.name,
                    "tags": list(task.tags) if task.tags else [],
                }
            )
            payload = _payload_with_normalized_next_steps(
                {
                    "task": task_payload,
                    "project": {"id": project.id, "name": project.name},
                    "runtime_write": _runtime_write_context_payload(write_decision),
                    "links": _normalize_command_links(
                        {
                            "self": f"task show {task.id}",
                            "project": f"project show {project.id}",
                            "timeline": f"task timeline {task.id}",
                            "graph": f"task graph {task.id}",
                            "actor": _task_assignee_actor_link(
                                task,
                                assignee_map,
                            ),
                        }
                    ),
                },
                *next_steps,
            )
            click.echo(json.dumps(payload, default=str))
            return

        console.print(f"[green]Created task:[/green] {task.title}")
        console.print(f"[dim]ID: {task.id}[/dim]")
        console.print(f"[dim]Project: {project.name}[/dim]")
        if complexity:
            console.print(f"[dim]Complexity: {complexity} points[/dim]")
        if task.assignee:
            console.print(f"[dim]Assigned: {task.assignee}[/dim]")
        _print_next_steps(*next_steps)
    finally:
        await db.disconnect()


@task.command("add")
@click.argument("project_ref")
@click.argument("title", required=False)
@click.option("-d", "--description", help="Task description")
@click.option("--parent-id", help="Parent task ID for subtasks")
@click.option(
    "--assigned-to",
    "assignee",
    help="Task assignee actor handle, alias, id, or stored label",
)
@click.option(
    "-p",
    "--priority",
    type=click.Choice(["low", "medium", "high", "critical"]),
    default="medium",
)
@click.option("-c", "--complexity", type=int, help="Complexity points (1-100)")
@click.option("-t", "--tag", "tags", multiple=True, help="Task tags")
@click.option(
    "--project",
    "project_ref_option",
    help="Project name or ID (alternate form with title as the only argument)",
)
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json"]),
    default="text",
    show_default=True,
)
@async_command
async def task_add(
    project_ref: str,
    title: str | None,
    description: str | None,
    parent_id: str | None,
    assignee: str | None,
    priority: str,
    complexity: int | None,
    tags: tuple[str, ...],
    project_ref_option: str | None,
    output_format: str,
) -> None:
    """Add a task to a project (name or ID)."""
    if project_ref_option:
        if title is not None:
            console.print(
                "[red]Use either <project> <title> or --project <project> <title>[/red]"
            )
            return
        title = project_ref
        project_ref = project_ref_option
    if title is None:
        console.print(
            "[red]Missing task title. Use <project> <title> or --project <project> <title>[/red]"
        )
        return

    await _create_task_from_cli(
        project_ref=project_ref,
        title=title,
        description=description,
        parent_id=parent_id,
        priority=priority,
        complexity=complexity,
        assignee=assignee,
        tags=tags,
        output_format=output_format,
    )


