@task.command("list")
@click.option("-p", "--project", "project_ref", help="Filter by project name or ID")
@click.option(
    "-s",
    "--status",
    type=click.Choice(
        ["todo", "in_progress", "blocked", "in_review", "done", "cancelled"]
    ),
)
@click.option("--actor", help="Filter by actor handle, id, or alias")
@click.option(
    "--mine",
    is_flag=True,
    help="Filter by the current actor plus inherited persona/team memberships",
)
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["table", "json", "csv"]),
    default="table",
    show_default=True,
)
@click.option(
    "--view",
    type=click.Choice(["review", "overview", "detail", "trace"]),
    default="review",
    show_default=True,
    help="Output view profile (review/overview/detail/trace)",
)
@click.option("--include-history", is_flag=True, help="Include history in JSON")
@click.option("--include-linked", is_flag=True, help="Include linked items in JSON")
@click.option(
    "--include-linked-history",
    is_flag=True,
    help="Include history for linked items in JSON",
)
@click.option("--history-limit", type=int, default=50, show_default=True)
@click.option("--linked-limit", type=int, default=20, show_default=True)
@click.option(
    "--include-generated",
    is_flag=True,
    help="Include tasks from generated or otherwise non-operator-visible projects in instance-wide views",
)
@click.option("--limit", type=int, default=100, show_default=True)
@click.option("--offset", type=int, default=0, show_default=True)
@async_command
async def task_list(
    project_ref: str | None,
    status: str | None,
    actor: str | None,
    mine: bool,
    output_format: str,
    view: str,
    include_history: bool,
    include_linked: bool,
    include_linked_history: bool,
    history_limit: int,
    linked_limit: int,
    include_generated: bool,
    limit: int,
    offset: int,
) -> None:
    """List tasks."""
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.models import TaskStatus
    from pms.models.progress_update import ProgressQuery
    from pms.models.state_transition import StateTransitionQuery
    from pms.models.workflow_state import get_workflow_by_id
    from pms.repositories import (
        LabelAssignmentRepository,
        LabelRepository,
        TaskEvidenceRepository,
    )
    from pms.repositories.progress_repository import ProgressRepository
    from pms.repositories.project_repository import ProjectRepository
    from pms.repositories.state_transition_repository import StateTransitionRepository
    from pms.repositories.task_repository import TaskRepository
    from pms.services.actor_service import ActorService
    from pms.services.generated_artifacts import (
        classify_project_operator_category,
        project_operator_category_label,
        project_operator_visibility_reason,
    )
    from pms.services.project_service import ProjectService
    from pms.services.task_service import TaskService
    from pms.utils.time import format_relative

    db = await init_database()

    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)

        project_repo = ProjectRepository(db, event_store, revision_store, metrics)
        task_repo = TaskRepository(db, event_store, revision_store, metrics)
        task_service = TaskService(db, event_store, revision_store, metrics)
        project_service = ProjectService(db, event_store, revision_store, metrics)
        actor_service = ActorService(db, event_store, revision_store, metrics)

        if mine and actor:
            _emit_cli_error(
                "Use --actor or --mine, not both",
                output_format="json" if output_format == "json" else "text",
            )

        assignee_actor_key = _resolve_current_actor() if mine else actor
        assignee_actor = None
        assignment_tokens: list[str] | None = None
        if assignee_actor_key:
            assignee_actor = await actor_service.get_actor(assignee_actor_key)
            if assignee_actor is None:
                _emit_cli_error(
                    f"Actor '{assignee_actor_key}' not found",
                    output_format="json" if output_format == "json" else "text",
                )
            assignment_tokens = await actor_service.resolve_assignment_tokens(
                assignee_actor.id,
                include_inherited=True,
            )

        project_id = None
        project_label = None
        if project_ref:
            project = await project_repo.get_by_name(project_ref)
            if project is None:
                project = await project_repo.get_by_id(project_ref)
            if project is None:
                console.print(f"[red]Project '{project_ref}' not found[/red]")
                return
            project_id = project.id
            project_label = project.name

        status_filter = TaskStatus(status) if status else None
        if project_id:
            result = await task_repo.get_by_project(
                project_id,
                status=status_filter,
                assignee_any=assignment_tokens,
                limit=limit,
                offset=offset,
            )
            project_population = await task_repo.get_by_project(
                project_id,
                status=status_filter,
                assignee_any=assignment_tokens,
                limit=max(int(result.total_count or 0), 1),
                offset=0,
            )
            visible_task_page = None
            visible_population_tasks = list(project_population.items)
            selected_population_tasks = list(project_population.items)
            suppressed_hidden_count = 0
            selected_population_name = "scoped_project"
        else:
            if include_generated:
                result = await task_repo.get_all(
                    limit=limit,
                    offset=offset,
                    status=status_filter,
                    assignee_any=assignment_tokens,
                )
                suppressed_hidden_count = 0
                selected_population_name = "all_retained"
            else:
                visible_task_page = await _list_visible_tasks(
                    task_repo,
                    project_service,
                    status=status_filter,
                    assignee_any=assignment_tokens,
                    limit=limit,
                    offset=offset,
                )
                result = QueryResult(
                    items=list(visible_task_page.items),
                    total_count=visible_task_page.total_count,
                    offset=visible_task_page.offset,
                    limit=visible_task_page.limit,
                )
                suppressed_hidden_count = visible_task_page.suppressed_hidden_count
                selected_population_name = "visible_operator"

            visible_population_page = await _list_visible_tasks(
                task_repo,
                project_service,
                status=status_filter,
                assignee_any=assignment_tokens,
                limit=0,
                offset=0,
            )
            visible_population_tasks = list(visible_population_page.items)
            if include_generated:
                selected_population_tasks = await _list_all_tasks(
                    task_repo,
                    status=status_filter,
                    assignee_any=assignment_tokens,
                )
            else:
                selected_population_tasks = list(visible_population_tasks)

        task_ids = [task.id for task in result.items]
        activity_map = await task_service.get_last_activity_map(task_ids)
        workflow_transition_map = await task_service.get_last_transition_map(
            task_ids, kind="workflow"
        )
        status_transition_map = await task_service.get_last_transition_map(
            task_ids, kind="status"
        )

        project_names: dict[str, str | None] = {}
        task_project_operator_categories: dict[str, str | None] = {}
        for task in result.items:
            if task.project_id and task.project_id not in project_names:
                project = await project_repo.get_by_id(task.project_id)
                project_names[task.project_id] = project.name if project else None
                if project is not None:
                    task_project_operator_categories[task.project_id] = (
                        classify_project_operator_category(project)
                    )
                else:
                    task_project_operator_categories[task.project_id] = None
        assignee_map = await _resolve_assignee_map(
            list(result.items),
            actor_service,
        )

        focus_state = _resolve_command_focus_state(result.items, project_names)
        first_task = focus_state.focus_task
        next_actions: list[str] = []
        focus_task_payload: dict[str, str | int | None] | None = None
        if first_task:
            task_target = _best_task_command_target(
                first_task.task_id,
                first_task.title,
                project_label or project_names.get(first_task.project_id),
            )
            focus_task_payload = first_task.to_payload()
            next_actions.append(_cli_command(f"task show {task_target}"))
            match first_task.status_value:
                case "todo":
                    next_actions.append(_cli_command(f"task start {task_target}"))
                case "in_progress":
                    next_actions.append(
                        _cli_command(
                            f"task progress {task_target} <percent> <message> --by <user>"
                        )
                    )
                    next_actions.append(
                        _cli_command(f"task review {task_target} --by <user>")
                    )
                case "in_review":
                    next_actions.append(
                        _cli_command(f"task complete {task_target} --by <user>")
                    )
                case "blocked":
                    next_actions.append(
                        _cli_command(f"task unblock {task_target} --by <user>")
                    )
                case "done" | "cancelled":
                    next_actions.append(
                        _cli_command(f"task reopen {task_target} --by <user>")
                    )
                case _:
                    pass
        if project_label:
            next_actions.append(_cli_command(f'task add "{project_label}" "New task"'))
        if assignee_actor is not None:
            next_actions.append(_cli_command(f"actor show {assignee_actor.handle}"))

        no_actionable_work = _instance_task_surface_has_no_actionable_work(
            project_id=project_id,
            include_generated=include_generated,
            visible_total_count=result.total_count,
            suppressed_hidden_count=suppressed_hidden_count,
        )
        scope_summary = (
            "Instance-wide retained task list view. Generated and historical project tasks are included explicitly."
            if include_generated
            else "Instance-wide task list view. Only operator-visible active-project tasks are surfaced by default."
        )
        terminal_reason = focus_state.terminal_reason

        if output_format == "json":
            payload_view = "overview" if view == "review" else view
            if payload_view == "trace":
                include_history = True
                include_linked = True
            if include_linked_history:
                include_linked = True
                include_history = True

            effective_history_limit = history_limit if history_limit > 0 else 1000
            effective_linked_limit = linked_limit if linked_limit > 0 else 1000

            label_repo = LabelRepository(db)
            assignment_repo = LabelAssignmentRepository(db)
            evidence_repo = (
                TaskEvidenceRepository(db)
                if view != "overview" or include_history or include_linked_history
                else None
            )
            progress_repo = ProgressRepository(db) if include_history else None
            state_repo = StateTransitionRepository(db) if include_history else None
            label_items_by_task: dict[str, list[dict[str, Any]]] = {}
            if task_ids:
                assignments = await assignment_repo.list_for_entities("task", task_ids)
                label_ids = {assignment.label_id for assignment in assignments}
                label_lookup: dict[str, dict[str, Any]] = {}
                for label_id in label_ids:
                    label = await label_repo.get_by_id(label_id)
                    if label:
                        label_lookup[label_id] = label.to_dict()
                for assignment in assignments:
                    label_data = label_lookup.get(assignment.label_id)
                    if label_data:
                        label_items_by_task.setdefault(assignment.entity_id, []).append(
                            label_data
                        )

            async def _task_payload(task_obj) -> dict[str, Any]:
                last_activity = activity_map.get(task_obj.id)
                last_transition = (
                    workflow_transition_map.get(task_obj.id)
                    if task_obj.workflow_id
                    else status_transition_map.get(task_obj.id)
                )
                task_assignee_actor = (
                    assignee_map.get(task_obj.assignee) if task_obj.assignee else None
                )
                assignee_payload = _task_assignee_payload(
                    task_obj,
                    assignee_map,
                )
                links = _normalize_command_links(
                    {
                        "self": f"task show {task_obj.id}",
                        "timeline": f"task timeline {task_obj.id}",
                        "graph": f"task graph {task_obj.id}",
                        "evidence": f"task evidence list {task_obj.id}",
                        "actor": (
                            f"actor show {task_assignee_actor.handle} --format json"
                            if task_assignee_actor is not None
                            else None
                        ),
                    }
                )

                if payload_view == "overview":
                    return {
                        "id": task_obj.id,
                        "title": task_obj.title,
                        "status": task_obj.status.value,
                        "priority": task_obj.priority.value,
                        "description": task_obj.description,
                        "project_id": task_obj.project_id,
                        "project_name": project_names.get(task_obj.project_id),
                        "project_operator_category": (
                            task_project_operator_categories.get(task_obj.project_id)
                            if task_obj.project_id
                            else None
                        ),
                        "project_operator_category_label": (
                            project_operator_category_label(
                                task_project_operator_categories[task_obj.project_id]
                            )
                            if task_obj.project_id
                            and task_project_operator_categories.get(
                                task_obj.project_id
                            )
                            else None
                        ),
                        "project_operator_visibility_reason": (
                            project_operator_visibility_reason(
                                task_project_operator_categories[task_obj.project_id]
                            )
                            if task_obj.project_id
                            and task_project_operator_categories.get(
                                task_obj.project_id
                            )
                            else None
                        ),
                        "created_at": _to_iso(task_obj.created_at),
                        "updated_at": task_obj.updated_at,
                        "due_date": _to_iso(task_obj.due_date),
                        "completed_at": _to_iso(task_obj.completed_at),
                        "assignee": assignee_payload,
                        "tags": list(task_obj.tags) if task_obj.tags else [],
                        "labels": label_items_by_task.get(task_obj.id, []),
                        "current_progress_percent": task_obj.current_progress_percent,
                        "workflow_id": task_obj.workflow_id,
                        "current_state": task_obj.current_state,
                        "is_overdue": task_obj.is_overdue,
                        "last_activity_at": _to_iso(last_activity),
                        "last_transition_at": _to_iso(last_transition),
                        "links": links,
                    }

                workflow_summary = None
                available_transitions: list[str] = []
                if task_obj.workflow_id:
                    workflow = get_workflow_by_id(task_obj.workflow_id)
                    if workflow:
                        workflow_summary = f"{workflow.name} @ {task_obj.current_state}"
                        available_transitions = _collect_workflow_transitions(
                            workflow, task_obj.current_state
                        )

                label_items = label_items_by_task.get(task_obj.id, [])

                evidence_count = None
                if evidence_repo:
                    evidence_result = await evidence_repo.list_by_task(
                        task_obj.id, limit=1
                    )
                    evidence_count = evidence_result.total_count

                progress_summary = None
                if progress_repo:
                    updates = await progress_repo.get_updates(
                        ProgressQuery(task_id=task_obj.id, limit=1)
                    )
                    last_update = updates[0].to_dict() if updates else None
                    last_update = _reconciled_progress_last_update(
                        task_obj, last_update
                    )
                    progress_summary = {
                        "current_percent": task_obj.current_progress_percent,
                        "last_update": last_update,
                        "last_updated_at": _to_iso(task_obj.last_progress_update_at),
                    }

                payload = _public_task_payload(
                    task_obj,
                    assignee_map=assignee_map,
                )
                payload.update(
                    {
                        "project_name": project_names.get(task_obj.project_id),
                        "project_operator_category": (
                            task_project_operator_categories.get(task_obj.project_id)
                            if task_obj.project_id
                            else None
                        ),
                        "project_operator_category_label": (
                            project_operator_category_label(
                                task_project_operator_categories[task_obj.project_id]
                            )
                            if task_obj.project_id
                            and task_project_operator_categories.get(
                                task_obj.project_id
                            )
                            else None
                        ),
                        "project_operator_visibility_reason": (
                            project_operator_visibility_reason(
                                task_project_operator_categories[task_obj.project_id]
                            )
                            if task_obj.project_id
                            and task_project_operator_categories.get(
                                task_obj.project_id
                            )
                            else None
                        ),
                        "last_activity_at": _to_iso(last_activity),
                        "last_transition_at": _to_iso(last_transition),
                        "workflow_summary": workflow_summary,
                        "available_transitions": available_transitions,
                        "labels": label_items,
                        "evidence_count": evidence_count,
                        "progress": progress_summary,
                        "assignee": assignee_payload,
                        "links": links,
                    }
                )

                if include_linked:
                    dependencies = await task_repo.get_dependencies(task_obj.id)
                    dependents = await task_repo.get_dependents(task_obj.id)
                    dependency_ids = [
                        dep.depends_on_id
                        for dep in dependencies[:effective_linked_limit]
                    ]
                    dependent_ids = [
                        dep.task_id for dep in dependents[:effective_linked_limit]
                    ]
                    linked_ids = list(dict.fromkeys(dependency_ids + dependent_ids))
                    linked_tasks = (
                        await task_repo.get_by_ids(linked_ids) if linked_ids else []
                    )
                    linked_project_names = dict(project_names)
                    for linked_task in linked_tasks:
                        if (
                            linked_task.project_id
                            and linked_task.project_id not in linked_project_names
                        ):
                            project = await project_repo.get_by_id(
                                linked_task.project_id
                            )
                            linked_project_names[linked_task.project_id] = (
                                project.name if project else None
                            )

                    linked_activity_map = await task_service.get_last_activity_map(
                        linked_ids
                    )
                    linked_workflow_map = await task_service.get_last_transition_map(
                        linked_ids, kind="workflow"
                    )
                    linked_status_map = await task_service.get_last_transition_map(
                        linked_ids, kind="status"
                    )

                    def _linked_summary(linked_task) -> dict[str, Any]:
                        last_linked_transition = (
                            linked_workflow_map.get(linked_task.id)
                            if linked_task.workflow_id
                            else linked_status_map.get(linked_task.id)
                        )
                        return {
                            "id": linked_task.id,
                            "title": linked_task.title,
                            "status": linked_task.status.value,
                            "priority": linked_task.priority.value,
                            "project_id": linked_task.project_id,
                            "project_name": linked_project_names.get(
                                linked_task.project_id
                            ),
                            "updated_at": linked_task.updated_at,
                            "last_activity_at": _to_iso(
                                linked_activity_map.get(linked_task.id)
                            ),
                            "last_transition_at": _to_iso(last_linked_transition),
                        }

                    linked_map = {task.id: task for task in linked_tasks}
                    payload["linked"] = {
                        "dependencies": [
                            _linked_summary(linked_map[dep_id])
                            for dep_id in dependency_ids
                            if dep_id in linked_map
                        ],
                        "dependents": [
                            _linked_summary(linked_map[dep_id])
                            for dep_id in dependent_ids
                            if dep_id in linked_map
                        ],
                    }

                    if include_linked_history and linked_ids and state_repo:
                        linked_progress_repo = progress_repo or ProgressRepository(db)

                        async def _history_for(
                            linked_id: str,
                        ) -> dict[str, Any]:
                            progress_updates = await linked_progress_repo.get_updates(
                                ProgressQuery(
                                    task_id=linked_id,
                                    limit=effective_history_limit,
                                )
                            )
                            workflow_transitions = await state_repo.get_transitions(
                                StateTransitionQuery(
                                    entity_type="task_workflow",
                                    entity_id=linked_id,
                                    limit=effective_history_limit,
                                )
                            )
                            status_transitions = await state_repo.get_transitions(
                                StateTransitionQuery(
                                    entity_type="task_status",
                                    entity_id=linked_id,
                                    limit=effective_history_limit,
                                )
                            )
                            evidence_result = await evidence_repo.list_by_task(
                                linked_id, limit=effective_history_limit
                            )
                            return {
                                "progress_updates": [
                                    update.to_dict() for update in progress_updates
                                ],
                                "workflow_transitions": [
                                    transition.to_dict()
                                    for transition in workflow_transitions
                                ],
                                "status_transitions": [
                                    transition.to_dict()
                                    for transition in status_transitions
                                ],
                                "evidence": [
                                    item.to_dict() for item in evidence_result.items
                                ],
                            }

                        payload["linked_history"] = {
                            dep_id: await _history_for(dep_id) for dep_id in linked_ids
                        }

                if include_history and state_repo and progress_repo:
                    progress_updates = await progress_repo.get_updates(
                        ProgressQuery(
                            task_id=task_obj.id,
                            limit=effective_history_limit,
                        )
                    )
                    workflow_transitions = await state_repo.get_transitions(
                        StateTransitionQuery(
                            entity_type="task_workflow",
                            entity_id=task_obj.id,
                            limit=effective_history_limit,
                        )
                    )
                    status_transitions = await state_repo.get_transitions(
                        StateTransitionQuery(
                            entity_type="task_status",
                            entity_id=task_obj.id,
                            limit=effective_history_limit,
                        )
                    )
                    evidence_result = await evidence_repo.list_by_task(
                        task_obj.id, limit=effective_history_limit
                    )
                    payload["history"] = {
                        "progress_updates": [
                            update.to_dict() for update in progress_updates
                        ],
                        "workflow_transitions": [
                            transition.to_dict() for transition in workflow_transitions
                        ],
                        "status_transitions": [
                            transition.to_dict() for transition in status_transitions
                        ],
                        "evidence": [item.to_dict() for item in evidence_result.items],
                    }

                return payload

            payload_items = [await _task_payload(task) for task in result.items]
            list_self_command = "task list --format json"
            if project_id:
                list_self_command = _append_cli_option(
                    list_self_command, "--project", project_id
                )
            if status:
                list_self_command = _append_cli_option(
                    list_self_command, "--status", status
                )
            if actor:
                list_self_command = _append_cli_option(
                    list_self_command, "--actor", actor
                )
            if mine:
                list_self_command += " --mine"
            if include_generated and not project_id:
                list_self_command += " --include-generated"
            if view != "overview":
                list_self_command = _append_cli_option(
                    list_self_command, "--view", view
                )
            if include_history:
                list_self_command += " --include-history"
            if include_linked:
                list_self_command += " --include-linked"
            if include_linked_history:
                list_self_command += " --include-linked-history"
            if history_limit != 50:
                list_self_command = _append_cli_option(
                    list_self_command, "--history-limit", history_limit
                )
            if linked_limit != 20:
                list_self_command = _append_cli_option(
                    list_self_command, "--linked-limit", linked_limit
                )
            base_cmd = _cli_command(list_self_command)
            links = _normalize_command_links(
                {
                    "self": f"{base_cmd} --limit {result.limit} --offset {result.offset}",
                    "next": (
                        f"{base_cmd} --offset {result.offset + result.limit} --limit {result.limit}"
                        if result.has_more
                        else None
                    ),
                    "ready": "task ready --format json",
                    "dashboard": "dashboard --format json",
                    "guide": "start --format json",
                }
            )
            if project_id:
                links["project"] = _cli_command(
                    f"project show {project_id} --format json"
                )
            if no_actionable_work:
                scope_summary = _instance_task_surface_no_actionable_summary(
                    "task list view"
                )
                next_actions = _no_actionable_work_next_steps(
                    list_self_command
                    if include_generated
                    else list_self_command.replace(
                        " --format json", " --include-generated --format json"
                    )
                )
                terminal_reason = terminal_reason or (
                    "no operator-visible active work is currently surfaced"
                )
            payload = {
                "items": payload_items,
                "page": {
                    "total_count": result.total_count,
                    "limit": result.limit,
                    "offset": result.offset,
                    "has_more": result.has_more,
                    "next_offset": result.offset + result.limit
                    if result.has_more
                    else None,
                },
                "scope": (
                    {
                        "kind": "project_task_list",
                        "population": "scoped_project",
                        "project_id": project_id,
                        "project_name": project_label,
                        "actor_handle": assignee_actor.handle
                        if assignee_actor is not None
                        else None,
                    }
                    if project_id
                    else {
                        "kind": "instance_task_list",
                        "population": selected_population_name,
                        "summary": scope_summary,
                        "actor_handle": assignee_actor.handle
                        if assignee_actor is not None
                        else None,
                    }
                ),
                "assignment_scope": (
                    {
                        "mode": "mine" if mine else "actor",
                        "actor_id": assignee_actor.id,
                        "actor_handle": assignee_actor.handle,
                        "include_inherited": True,
                    }
                    if assignee_actor is not None
                    else None
                ),
                "visible_totals": (
                    {
                        "population": "visible_operator",
                        **_task_population_totals(visible_population_tasks, TaskStatus),
                    }
                    if not project_id
                    else {
                        "population": "scoped_project",
                        **_task_population_totals(visible_population_tasks, TaskStatus),
                    }
                ),
                "population_totals": {
                    "population": selected_population_name,
                    **_task_population_totals(selected_population_tasks, TaskStatus),
                },
                "suppressed_hidden_count": suppressed_hidden_count
                if not project_id
                else 0,
                "focus_task": focus_task_payload,
                "graph_navigation": _task_graph_navigation_payload(
                    task_obj=(
                        next(
                            (
                                task_obj
                                for task_obj in result.items
                                if task_obj.id == first_task.task_id
                            ),
                            None,
                        )
                        if first_task is not None
                        else None
                    ),
                    project_id=project_id,
                    project_name=project_label,
                    assignee_map=assignee_map,
                ),
                "terminal_reason": terminal_reason,
                "links": links,
                "next_steps": _normalize_next_steps(*next_actions),
                "params": {
                    "project_id": project_id,
                    "status": status,
                    "actor": actor,
                    "mine": mine,
                    "view": view,
                    "include_history": include_history,
                    "include_linked": include_linked,
                    "include_linked_history": include_linked_history,
                    "history_limit": history_limit,
                    "linked_limit": linked_limit,
                    "include_generated": include_generated,
                    "limit": result.limit,
                    "offset": result.offset,
                },
            }
            payload = _payload_with_normalized_next_steps(payload, *next_actions)
            click.echo(json.dumps(payload, default=str))
            return

        if output_format == "csv":
            headers = [
                "id",
                "title",
                "status",
                "priority",
                "assignee",
                "complexity_points",
                "current_progress_percent",
                "project_id",
                "last_activity_at",
                "last_transition_at",
            ]
            click.echo(_csv_row(headers))
            for task in result.items:
                last_activity = activity_map.get(task.id)
                last_transition = (
                    workflow_transition_map.get(task.id)
                    if task.workflow_id
                    else status_transition_map.get(task.id)
                )
                row = [
                    task.id,
                    task.title,
                    task.status.value,
                    task.priority.value,
                    task.assignee or "",
                    str(task.complexity_points or ""),
                    str(task.current_progress_percent),
                    task.project_id,
                    _to_iso(last_activity) or "",
                    _to_iso(last_transition) or "",
                ]
                click.echo(_csv_row(row))
            return

        if view == "review":
            _print_task_review_view(
                result=result,
                tasks=list(result.items),
                total_tasks=selected_population_tasks,
                project_label=project_label,
                project_id=project_id,
                assignee_actor=assignee_actor,
                assignee_map=assignee_map,
                project_names=project_names,
                activity_map=activity_map,
                workflow_transition_map=workflow_transition_map,
                status_transition_map=status_transition_map,
                focus_state=focus_state,
                focus_task_payload=focus_task_payload,
                suppressed_hidden_count=suppressed_hidden_count,
                no_actionable_work=no_actionable_work,
                scope_summary=scope_summary,
            )
            _print_next_steps(*next_actions)
            return

        page_status_summary = _task_status_summary_text(list(result.items))
        total_status_summary = _task_status_summary_text(selected_population_tasks)
        mismatch_count = 0
        for task in result.items:
            if not task.workflow_id or not task.current_state:
                continue
            workflow = get_workflow_by_id(task.workflow_id)
            if workflow is None:
                continue
            workflow_terminal = task.current_state in workflow.terminal_states
            status_terminal = task.status.is_terminal
            if workflow_terminal != status_terminal:
                mismatch_count += 1

        table = Table(title="Tasks")
        table.add_column(
            "Title",
            style="cyan",
            overflow="ellipsis",
            min_width=24,
            max_width=44,
            no_wrap=True,
        )
        table.add_column(
            "Project",
            overflow="ellipsis",
            min_width=16,
            max_width=32,
            no_wrap=True,
        )
        table.add_column("Workflow")
        table.add_column("Next")
        table.add_column("Status")
        table.add_column("Priority")
        table.add_column("Complexity", justify="right")
        table.add_column("Progress", justify="right")
        table.add_column("Activity")
        table.add_column("Last Transition")
        table.add_column("Ref", style="dim", no_wrap=True)

        for t in result.items:
            status_style = {
                "todo": "",
                "in_progress": "blue",
                "blocked": "red",
                "in_review": "yellow",
                "done": "green",
                "cancelled": "dim",
            }.get(t.status.value, "")

            complexity_str = str(t.complexity_points) if t.complexity_points else "-"
            progress_str = f"{t.current_progress_percent}%"
            project_label = (
                project_names.get(t.project_id, t.project_id) if t.project_id else "-"
            )
            workflow_state = t.current_state if t.workflow_id else "-"
            next_transitions = "-"
            if t.workflow_id and t.current_state:
                workflow = get_workflow_by_id(t.workflow_id)
                transitions = _collect_workflow_transitions(workflow, t.current_state)
                if transitions:
                    next_transitions = _truncate(", ".join(transitions), 24)

            last_activity = activity_map.get(t.id)
            last_transition = (
                workflow_transition_map.get(t.id)
                if t.workflow_id
                else status_transition_map.get(t.id)
            )

            table.add_row(
                t.title,
                project_label,
                workflow_state,
                next_transitions,
                f"[{status_style}]{t.status.value}[/{status_style}]"
                if status_style
                else t.status.value,
                t.priority.value,
                complexity_str,
                progress_str,
                format_relative(last_activity or t.updated_at, include_absolute=False),
                format_relative(last_transition, include_absolute=False),
                t.id[:8],
            )

        console.print(
            f"Shown summary (current limit/page: {len(result.items)} tasks): "
            f"{page_status_summary}"
        )
        console.print(
            f"Total summary (all {len(selected_population_tasks)} matching tasks): "
            f"{total_status_summary}"
        )
        if mismatch_count:
            console.print(
                f"[yellow]Workflow/Status mismatches: {mismatch_count}[/yellow]"
            )

        console.print(table)
        console.print(f"[dim]Total: {result.total_count}[/dim]")
        if assignee_actor is not None:
            console.print(
                f"[dim]Actor filter: {assignee_actor.handle} "
                "(direct + inherited memberships)[/dim]"
            )
        if not project_id and suppressed_hidden_count:
            console.print(
                f"[dim]Suppressed hidden tasks: {suppressed_hidden_count} "
                f"(use --include-generated to show retained audit/history tasks)[/dim]"
            )
        if no_actionable_work:
            console.print(f"[dim]{scope_summary}[/dim]")
        if focus_task_payload is not None:
            console.print(
                "Focus: "
                f"{focus_task_payload['title']} "
                f"[{focus_task_payload['status']}] "
                f"({focus_task_payload['current_progress_percent']}%)"
            )
            console.print(f"Why: {focus_task_payload['reason']}")
        elif focus_state.terminal_reason is not None:
            console.print(f"Execution State: {focus_state.terminal_reason}")
        _print_task_footer(result.items, activity_map)
        _print_next_steps(*next_actions)
    finally:
        await db.disconnect()


@task.command("search")
@click.option("--query", help="Text query (title/description)")
@click.option("-p", "--project", "project_ref", help="Filter by project name or ID")
@click.option(
    "-s",
    "--status",
    "statuses",
    multiple=True,
    type=click.Choice(
        ["todo", "in_progress", "blocked", "in_review", "done", "cancelled"]
    ),
)
@click.option(
    "--priority",
    "priorities",
    multiple=True,
    type=click.Choice(["low", "medium", "high", "critical"]),
)
@click.option("--assigned-to", "assignee", help="Filter by assignee")
@click.option("--actor", help="Filter by actor handle, id, or alias")
@click.option(
    "--mine",
    is_flag=True,
    help="Filter by the current actor plus inherited persona/team memberships",
)
@click.option("-t", "--tag", "tags", multiple=True, help="Filter by tag")
@click.option("--label", "labels", multiple=True, help="Label ID or name")
@click.option(
    "--label-category",
    "label_categories",
    multiple=True,
    help="Label category ID or name",
)
@click.option("--created-from", help="Created after (ISO timestamp)")
@click.option("--created-to", help="Created before (ISO timestamp)")
@click.option("--updated-from", help="Updated after (ISO timestamp)")
@click.option("--updated-to", help="Updated before (ISO timestamp)")
@click.option("--due-from", help="Due after (ISO timestamp)")
@click.option("--due-to", help="Due before (ISO timestamp)")
@click.option("--include-terminal", is_flag=True, help="Include done/cancelled tasks")
@click.option(
    "--sort-by",
    type=click.Choice(["updated_at", "created_at", "due_date", "priority"]),
    help="Sort field",
)
@click.option(
    "--sort-dir",
    type=click.Choice(["asc", "desc"]),
    default="desc",
    show_default=True,
    help="Sort direction",
)
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["table", "json", "csv"]),
    default="table",
    show_default=True,
)
@click.option(
    "--view",
    type=click.Choice(["review", "overview"]),
    default="review",
    show_default=True,
    help="Text view profile (review/overview)",
)
@click.option("--include-history", is_flag=True, help="Include history in JSON")
@click.option("--include-linked", is_flag=True, help="Include linked items in JSON")
@click.option(
    "--include-linked-history",
    is_flag=True,
    help="Include history for linked items in JSON",
)
@click.option(
    "--include-generated",
    is_flag=True,
    help="Include tasks from generated or otherwise non-operator-visible projects in instance-wide views",
)
@click.option("--history-limit", type=int, default=50, show_default=True)
@click.option("--linked-limit", type=int, default=20, show_default=True)
@async_command
async def task_search(
    query: str | None,
    project_ref: str | None,
    statuses: tuple[str, ...],
    priorities: tuple[str, ...],
    assignee: str | None,
    actor: str | None,
    mine: bool,
    tags: tuple[str, ...],
    labels: tuple[str, ...],
    label_categories: tuple[str, ...],
    created_from: str | None,
    created_to: str | None,
    updated_from: str | None,
    updated_to: str | None,
    due_from: str | None,
    due_to: str | None,
    include_terminal: bool,
    sort_by: str | None,
    sort_dir: str,
    output_format: str,
    view: str,
    include_history: bool,
    include_linked: bool,
    include_linked_history: bool,
    include_generated: bool,
    history_limit: int,
    linked_limit: int,
) -> None:
    """Search tasks with rich filters."""
    from datetime import datetime

    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.models import Priority, TaskStatus
    from pms.repositories.project_repository import ProjectRepository
    from pms.services.actor_service import ActorService
    from pms.services.generated_artifacts import (
        classify_project_operator_category,
        project_operator_category_label,
        project_operator_visibility_reason,
    )
    from pms.services.label_service import LabelService
    from pms.services.project_service import ProjectService
    from pms.services.task_service import TaskService

    def parse_dt(value: str | None, label: str) -> datetime | None:
        if value is None:
            return None
        try:
            return datetime.fromisoformat(value)
        except ValueError:
            raise click.ClickException(f"Invalid {label} timestamp")

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)

        task_service = TaskService(db, event_store, revision_store, metrics)
        project_service = ProjectService(db, event_store, revision_store, metrics)
        project_repo = ProjectRepository(db, event_store, revision_store, metrics)
        actor_service = ActorService(db, event_store, revision_store, metrics)
        label_service = LabelService(db, metrics)

        if mine and actor:
            _emit_cli_error(
                "Use --actor or --mine, not both",
                output_format="json" if output_format == "json" else "text",
            )
        if assignee and (mine or actor):
            _emit_cli_error(
                "Use --assigned-to or --actor/--mine, not both",
                output_format="json" if output_format == "json" else "text",
            )

        assignee_actor_key = _resolve_current_actor() if mine else actor
        assignee_actor = None
        assignment_tokens: list[str] | None = None
        if assignee_actor_key:
            assignee_actor = await actor_service.get_actor(assignee_actor_key)
            if assignee_actor is None:
                _emit_cli_error(
                    f"Actor '{assignee_actor_key}' not found",
                    output_format="json" if output_format == "json" else "text",
                )
            assignment_tokens = await actor_service.resolve_assignment_tokens(
                assignee_actor.id,
                include_inherited=True,
            )

        project_id = None
        project_label = None
        if project_ref:
            project = await project_repo.get_by_name(project_ref)
            if project is None:
                project = await project_repo.get_by_id(project_ref)
            if project is None:
                console.print(f"[red]Project '{project_ref}' not found[/red]")
                return
            project_id = project.id
            project_label = project.name

        status_list = [TaskStatus(s) for s in statuses] if statuses else None
        priority_list = [Priority(p) for p in priorities] if priorities else None

        label_ids: list[str] | None = None
        if labels:
            label_ids = []
            for label_ref in labels:
                label_obj = await label_service.get_label(label_ref)
                if label_obj is None:
                    label_obj = await label_service.get_label_by_name(label_ref)
                if label_obj is None:
                    console.print(f"[red]Label '{label_ref}' not found[/red]")
                    return
                label_ids.append(label_obj.id)

        label_category_ids: list[str] | None = None
        if label_categories:
            label_category_ids = []
            for category_ref in label_categories:
                category = await label_service.get_category(category_ref)
                if category is None:
                    category = await label_service.get_category_by_name(category_ref)
                if category is None:
                    console.print(
                        f"[red]Label category '{category_ref}' not found[/red]"
                    )
                    return
                label_category_ids.append(category.id)

        created_from_dt = parse_dt(created_from, "created_from")
        created_to_dt = parse_dt(created_to, "created_to")
        updated_from_dt = parse_dt(updated_from, "updated_from")
        updated_to_dt = parse_dt(updated_to, "updated_to")
        due_from_dt = parse_dt(due_from, "due_from")
        due_to_dt = parse_dt(due_to, "due_to")
        tag_list = list(tags) if tags else None

        all_matching_tasks = await _search_all_tasks(
            task_service,
            query=query,
            project_id=project_id,
            statuses=status_list,
            priorities=priority_list,
            assignee=assignee,
            assignee_any=assignment_tokens,
            created_from=created_from_dt,
            created_to=created_to_dt,
            updated_from=updated_from_dt,
            updated_to=updated_to_dt,
            due_from=due_from_dt,
            due_to=due_to_dt,
            tags=tag_list,
            label_ids=label_ids,
            label_category_ids=label_category_ids,
            include_terminal=include_terminal,
            sort_by=sort_by,
            sort_dir=sort_dir,
        )

        if project_id:
            result = QueryResult(
                items=list(all_matching_tasks),
                total_count=len(all_matching_tasks),
                offset=0,
                limit=len(all_matching_tasks),
            )
            selected_population_name = "scoped_project"
            selected_population_tasks = list(all_matching_tasks)
            visible_population_tasks = list(all_matching_tasks)
            suppressed_hidden_count = 0
        else:
            excluded_project_ids = await _operator_hidden_project_ids(
                project_service,
                [task.project_id for task in all_matching_tasks],
            )
            visible_population_tasks = _exclude_tasks_from_projects(
                all_matching_tasks,
                excluded_project_ids,
            )
            if include_generated:
                result = await task_service.search_tasks(
                    query=query,
                    project_id=project_id,
                    statuses=status_list,
                    priorities=priority_list,
                    assignee=assignee,
                    assignee_any=assignment_tokens,
                    created_from=created_from_dt,
                    created_to=created_to_dt,
                    updated_from=updated_from_dt,
                    updated_to=updated_to_dt,
                    due_from=due_from_dt,
                    due_to=due_to_dt,
                    tags=tag_list,
                    label_ids=label_ids,
                    label_category_ids=label_category_ids,
                    include_terminal=include_terminal,
                    sort_by=sort_by,
                    sort_dir=sort_dir,
                )
                selected_population_name = "all_retained"
                selected_population_tasks = list(all_matching_tasks)
                suppressed_hidden_count = max(
                    0, len(selected_population_tasks) - len(visible_population_tasks)
                )
            else:
                visible_page = await _search_visible_tasks(
                    task_service,
                    project_service,
                    query=query,
                    project_id=project_id,
                    statuses=status_list,
                    priorities=priority_list,
                    assignee=assignee,
                    assignee_any=assignment_tokens,
                    created_from=created_from_dt,
                    created_to=created_to_dt,
                    updated_from=updated_from_dt,
                    updated_to=updated_to_dt,
                    due_from=due_from_dt,
                    due_to=due_to_dt,
                    tags=tag_list,
                    label_ids=label_ids,
                    label_category_ids=label_category_ids,
                    include_terminal=include_terminal,
                    sort_by=sort_by,
                    sort_dir=sort_dir,
                    limit=100,
                    offset=0,
                )
                result = QueryResult(
                    items=visible_page.items,
                    total_count=visible_page.total_count,
                    offset=0,
                    limit=100,
                )
                selected_population_name = "visible_operator"
                selected_population_tasks = list(visible_population_tasks)
                suppressed_hidden_count = visible_page.suppressed_hidden_count

        task_ids = [task.id for task in result.items]
        activity_map = await task_service.get_last_activity_map(task_ids)
        workflow_transition_map = await task_service.get_last_transition_map(
            task_ids, kind="workflow"
        )
        status_transition_map = await task_service.get_last_transition_map(
            task_ids, kind="status"
        )
        project_names: dict[str, str | None] = {}
        task_project_operator_categories: dict[str, str | None] = {}
        for task_obj in result.items:
            if task_obj.project_id and task_obj.project_id not in project_names:
                project = await project_repo.get_by_id(task_obj.project_id)
                project_names[task_obj.project_id] = project.name if project else None
                if project is not None:
                    task_project_operator_categories[task_obj.project_id] = (
                        classify_project_operator_category(project)
                    )
                else:
                    task_project_operator_categories[task_obj.project_id] = None
        assignee_map = await _resolve_assignee_map(
            list(result.items),
            actor_service,
        )

        first_task = result.items[0] if result.items else None
        next_steps: list[str] = []
        if first_task:
            next_steps.append(f"task show {first_task.id}")
            next_steps.append(f"task update {first_task.id}")
            if first_task.project_id:
                project_hint = project_names.get(first_task.project_id)
                if project_hint:
                    next_steps.append(f'task list --project "{project_hint}"')
                else:
                    next_steps.append(f"task list --project {first_task.project_id}")
        if assignee_actor is not None:
            next_steps.append(f"actor show {assignee_actor.handle}")
        next_steps.extend(["task ready --format json", "start --format json"])
        next_steps = _normalize_next_steps(*next_steps)
        search_self_command = "task search --format json"
        retained_search_command = "task search --include-generated --format json"
        if query:
            search_self_command = _append_cli_option(
                search_self_command, "--query", query
            )
            retained_search_command = _append_cli_option(
                retained_search_command, "--query", query
            )
        if project_id:
            search_self_command = _append_cli_option(
                search_self_command, "--project", project_id
            )
        if statuses:
            search_self_command = _append_cli_repeatable_options(
                search_self_command, "--status", statuses
            )
        if priorities:
            search_self_command = _append_cli_repeatable_options(
                search_self_command, "--priority", priorities
            )
        if assignee:
            search_self_command = _append_cli_option(
                search_self_command, "--assigned-to", assignee
            )
        if assignee_actor is not None and not mine:
            search_self_command = _append_cli_option(
                search_self_command, "--actor", assignee_actor.handle
            )
        if mine:
            search_self_command += " --mine"
        if tags:
            search_self_command = _append_cli_repeatable_options(
                search_self_command, "--tag", tags
            )
        if labels:
            search_self_command = _append_cli_repeatable_options(
                search_self_command, "--label", labels
            )
        if label_categories:
            search_self_command = _append_cli_repeatable_options(
                search_self_command, "--label-category", label_categories
            )
        if created_from:
            search_self_command = _append_cli_option(
                search_self_command, "--created-from", created_from
            )
        if created_to:
            search_self_command = _append_cli_option(
                search_self_command, "--created-to", created_to
            )
        if updated_from:
            search_self_command = _append_cli_option(
                search_self_command, "--updated-from", updated_from
            )
        if updated_to:
            search_self_command = _append_cli_option(
                search_self_command, "--updated-to", updated_to
            )
        if due_from:
            search_self_command = _append_cli_option(
                search_self_command, "--due-from", due_from
            )
        if due_to:
            search_self_command = _append_cli_option(
                search_self_command, "--due-to", due_to
            )
        if include_terminal:
            search_self_command += " --include-terminal"
        if sort_by:
            search_self_command = _append_cli_option(
                search_self_command, "--sort-by", sort_by
            )
        if sort_dir:
            search_self_command = _append_cli_option(
                search_self_command, "--sort-dir", sort_dir
            )
        if include_generated:
            search_self_command += " --include-generated"
        if view != "review":
            search_self_command = _append_cli_option(
                search_self_command, "--view", view
            )
        retained_search_command = (
            search_self_command
            if include_generated
            else search_self_command.replace(
                " --format json", " --include-generated --format json"
            )
        )
        no_actionable_work = _instance_task_surface_has_no_actionable_work(
            project_id=project_id,
            include_generated=include_generated,
            visible_total_count=result.total_count,
            suppressed_hidden_count=suppressed_hidden_count,
        )
        scope_summary = (
            "Instance-wide retained task search. Generated and historical project tasks are included explicitly."
            if include_generated
            else "Instance-wide task search. Only operator-visible active-project tasks are surfaced by default."
        )
        if no_actionable_work:
            scope_summary = _instance_task_surface_no_actionable_summary("task search")
            next_steps = _no_actionable_work_next_steps(retained_search_command)
        focus_state = _resolve_command_focus_state(list(result.items), project_names)
        focus_task_payload = (
            focus_state.focus_task.to_payload()
            if focus_state.focus_task is not None
            else None
        )

        if output_format == "json":
            include_history, include_linked, include_linked_history = (
                _normalize_history_flags(
                    include_history, include_linked, include_linked_history
                )
            )
            effective_history_limit = history_limit if history_limit > 0 else 1000
            effective_linked_limit = linked_limit if linked_limit > 0 else 1000

            task_repo = None
            if include_linked:
                from pms.repositories.task_repository import TaskRepository

                task_repo = TaskRepository(db, event_store, revision_store, metrics)

            progress_repo = None
            state_repo = None
            evidence_repo = None
            if include_history or include_linked_history:
                from pms.repositories.progress_repository import ProgressRepository
                from pms.repositories.state_transition_repository import (
                    StateTransitionRepository,
                )
                from pms.repositories.task_evidence_repository import (
                    TaskEvidenceRepository,
                )

                progress_repo = ProgressRepository(db)
                state_repo = StateTransitionRepository(db)
                evidence_repo = TaskEvidenceRepository(db)

            payload_items = []
            for task_obj in result.items:
                last_activity = activity_map.get(task_obj.id)
                last_transition = (
                    workflow_transition_map.get(task_obj.id)
                    if task_obj.workflow_id
                    else status_transition_map.get(task_obj.id)
                )
                data = _public_task_payload(
                    task_obj,
                    assignee_map=assignee_map,
                )
                data["last_activity_at"] = _to_iso(last_activity)
                data["last_transition_at"] = _to_iso(last_transition)
                data["project_name"] = project_names.get(task_obj.project_id)
                data["project_operator_category"] = (
                    task_project_operator_categories.get(task_obj.project_id)
                    if task_obj.project_id
                    else None
                )
                data["project_operator_category_label"] = (
                    project_operator_category_label(
                        task_project_operator_categories[task_obj.project_id]
                    )
                    if task_obj.project_id
                    and task_project_operator_categories.get(task_obj.project_id)
                    else None
                )
                data["project_operator_visibility_reason"] = (
                    project_operator_visibility_reason(
                        task_project_operator_categories[task_obj.project_id]
                    )
                    if task_obj.project_id
                    and task_project_operator_categories.get(task_obj.project_id)
                    else None
                )
                data["links"] = _normalize_command_links(
                    {
                        "self": f"task show {task_obj.id}",
                        "timeline": f"task timeline {task_obj.id}",
                        "graph": f"task graph {task_obj.id}",
                        "evidence": f"task evidence list {task_obj.id}",
                        "ready": "task ready --format json",
                        "dashboard": "dashboard --format json",
                        "guide": "start --format json",
                        "actor": (
                            f"actor show {assignee_map[task_obj.assignee].handle} --format json"
                            if task_obj.assignee
                            and assignee_map.get(task_obj.assignee) is not None
                            else None
                        ),
                    }
                )
                data["assignee"] = _task_assignee_payload(
                    task_obj,
                    assignee_map,
                )
                task_steps = _normalize_next_steps(
                    f"pms task show {task_obj.id}",
                    (
                        f"pms task update {task_obj.id}"
                        if task_obj.status.value != "done"
                        and task_obj.status.value != "cancelled"
                        else f"pms task reopen {task_obj.id} --by <user>"
                    ),
                    (
                        f'pms task list --project "{project_names.get(task_obj.project_id)}"'
                        if task_obj.project_id
                        and project_names.get(task_obj.project_id)
                        else f"pms task list --project {task_obj.project_id}"
                        if task_obj.project_id
                        else "pms task list"
                    ),
                    "pms task ready --format json",
                    "pms start --format json",
                )
                data["next_steps"] = task_steps

                if include_history:
                    data["history"] = await _build_task_history(
                        task_id=task_obj.id,
                        progress_repo=progress_repo,
                        state_repo=state_repo,
                        evidence_repo=evidence_repo,
                        history_limit=effective_history_limit,
                    )

                if include_linked and task_repo:
                    linked_payload, linked_history = await _build_task_linked_payload(
                        task_obj,
                        task_repo=task_repo,
                        project_repo=project_repo,
                        task_service=task_service,
                        linked_limit=effective_linked_limit,
                        history_limit=effective_history_limit,
                        include_linked_history=include_linked_history,
                        progress_repo=progress_repo,
                        state_repo=state_repo,
                        evidence_repo=evidence_repo,
                    )
                    data["linked"] = linked_payload
                    if linked_history:
                        data["linked_history"] = linked_history

                payload_items.append(data)
            payload = {
                "items": payload_items,
                "page": {
                    "total_count": result.total_count,
                    "limit": result.limit,
                    "offset": result.offset,
                    "has_more": result.has_more,
                    "next_offset": result.offset + result.limit
                    if result.has_more
                    else None,
                },
                "scope": (
                    {
                        "kind": "project_task_search",
                        "population": "scoped_project",
                        "project_id": project_id,
                        "project_name": project_ref,
                        "actor_handle": assignee_actor.handle
                        if assignee_actor is not None
                        else None,
                    }
                    if project_id
                    else {
                        "kind": "instance_task_search",
                        "population": selected_population_name,
                        "summary": scope_summary,
                        "actor_handle": assignee_actor.handle
                        if assignee_actor is not None
                        else None,
                    }
                ),
                "assignment_scope": (
                    {
                        "mode": "mine" if mine else "actor",
                        "actor_id": assignee_actor.id,
                        "actor_handle": assignee_actor.handle,
                        "include_inherited": True,
                    }
                    if assignee_actor is not None
                    else None
                ),
                "visible_totals": (
                    {
                        "population": "visible_operator",
                        **_task_population_totals(
                            visible_population_tasks,
                            TaskStatus,
                        ),
                    }
                    if not project_id
                    else {
                        "population": "scoped_project",
                        **_task_population_totals(
                            selected_population_tasks,
                            TaskStatus,
                        ),
                    }
                ),
                "population_totals": {
                    "population": selected_population_name,
                    **_task_population_totals(selected_population_tasks, TaskStatus),
                },
                "suppressed_hidden_count": suppressed_hidden_count
                if not project_id
                else 0,
                "focus_task": focus_task_payload,
                "graph_navigation": _command_focus_graph_navigation(
                    focus_task=focus_state.focus_task,
                    task_lookup={task.id: task for task in result.items},
                    assignee_map=assignee_map,
                    project_id=project_id,
                    project_name=project_label,
                ),
                "links": _normalize_command_links(
                    {
                        "self": search_self_command,
                        "ready": "task ready --format json",
                        "dashboard": "dashboard --format json",
                        "guide": "start --format json",
                        "actor": (
                            f"actor show {assignee_actor.handle} --format json"
                            if assignee_actor is not None
                            else None
                        ),
                    }
                ),
                "next_steps": next_steps,
                "params": {
                    "query": query,
                    "project_id": project_id,
                    "statuses": list(statuses),
                    "priorities": list(priorities),
                    "assignee": assignee,
                    "actor": actor,
                    "mine": mine,
                    "view": view,
                    "tags": list(tags),
                    "labels": list(labels),
                    "label_categories": list(label_categories),
                    "created_from": created_from,
                    "created_to": created_to,
                    "updated_from": updated_from,
                    "updated_to": updated_to,
                    "due_from": due_from,
                    "due_to": due_to,
                    "include_terminal": include_terminal,
                    "sort_by": sort_by,
                    "sort_dir": sort_dir,
                    "include_history": include_history,
                    "include_linked": include_linked,
                    "include_linked_history": include_linked_history,
                    "include_generated": include_generated,
                    "history_limit": history_limit,
                    "linked_limit": linked_limit,
                },
            }
            click.echo(json.dumps(payload, default=str))
            return

        if output_format == "csv":
            headers = [
                "id",
                "title",
                "status",
                "priority",
                "assignee",
                "last_activity_at",
                "last_transition_at",
                "project_id",
                "project_name",
            ]
            click.echo(_csv_row(headers))
            for task_obj in result.items:
                last_activity = activity_map.get(task_obj.id)
                last_transition = (
                    workflow_transition_map.get(task_obj.id)
                    if task_obj.workflow_id
                    else status_transition_map.get(task_obj.id)
                )
                row = [
                    task_obj.id,
                    task_obj.title,
                    task_obj.status.value,
                    task_obj.priority.value,
                    task_obj.assignee or "",
                    _to_iso(last_activity) or "",
                    _to_iso(last_transition) or "",
                    task_obj.project_id,
                    project_names.get(task_obj.project_id) or "",
                ]
                click.echo(_csv_row(row))
            return

        from pms.utils.time import format_relative

        if view == "review":
            _print_task_review_view(
                result=result,
                tasks=list(result.items),
                total_tasks=selected_population_tasks,
                project_label=project_label,
                project_id=project_id,
                assignee_actor=assignee_actor,
                assignee_map=assignee_map,
                project_names=project_names,
                activity_map=activity_map,
                workflow_transition_map=workflow_transition_map,
                status_transition_map=status_transition_map,
                focus_state=focus_state,
                focus_task_payload=focus_task_payload,
                suppressed_hidden_count=suppressed_hidden_count,
                no_actionable_work=no_actionable_work,
                scope_summary=scope_summary,
            )
            _print_next_steps(*next_steps)
            return

        table = Table(title="Task Search")
        table.add_column("Title", style="cyan")
        table.add_column("Project")
        table.add_column("Status")
        table.add_column("Priority")
        table.add_column("Activity")
        table.add_column("Transition")
        table.add_column("Assignee")
        table.add_column("ID", style="dim")

        for task_obj in result.items:
            status_style = {
                "todo": "",
                "in_progress": "blue",
                "blocked": "red",
                "in_review": "yellow",
                "done": "green",
                "cancelled": "dim",
            }.get(task_obj.status.value, "")

            last_activity = activity_map.get(task_obj.id)
            last_transition = (
                workflow_transition_map.get(task_obj.id)
                if task_obj.workflow_id
                else status_transition_map.get(task_obj.id)
            )
            activity_text = format_relative(last_activity or task_obj.updated_at)
            project_label = (
                project_names.get(task_obj.project_id, task_obj.project_id)
                if task_obj.project_id
                else "-"
            )
            table.add_row(
                task_obj.title[:40],
                project_label[:20],
                f"[{status_style}]{task_obj.status.value}[/{status_style}]"
                if status_style
                else task_obj.status.value,
                task_obj.priority.value,
                activity_text,
                format_relative(last_transition),
                task_obj.assignee or "-",
                task_obj.id[:8],
            )

        console.print(table)
        console.print(f"[dim]Total: {result.total_count}[/dim]")
        if assignee_actor is not None:
            console.print(
                f"[dim]Actor filter: {assignee_actor.handle} "
                "(direct + inherited memberships)[/dim]"
            )
        if not project_id and suppressed_hidden_count:
            console.print(
                f"[dim]Suppressed hidden tasks: {suppressed_hidden_count} "
                f"(use --include-generated to show retained audit/history tasks)[/dim]"
            )
        if no_actionable_work:
            console.print(f"[dim]{scope_summary}[/dim]")
        _print_next_steps(*next_steps)
    finally:
        await db.disconnect()


@task.command("ready")
@click.option("-p", "--project", "project_ref", help="Filter by project name or ID")
@click.option(
    "-s",
    "--status",
    "statuses",
    multiple=True,
    type=click.Choice(
        ["todo", "in_progress", "blocked", "in_review", "done", "cancelled"]
    ),
)
@click.option(
    "--include-checked-out",
    is_flag=True,
    help="Include tasks currently checked out",
)
@click.option(
    "--include-generated",
    is_flag=True,
    help="Include tasks from generated or otherwise non-operator-visible projects in instance-wide views",
)
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["table", "json", "csv"]),
    default="table",
    show_default=True,
)
@click.option(
    "--view",
    type=click.Choice(["review", "overview"]),
    default="review",
    show_default=True,
    help="Text view profile (review/overview)",
)
@click.option("--include-history", is_flag=True, help="Include history in JSON")
@click.option("--include-linked", is_flag=True, help="Include linked items in JSON")
@click.option(
    "--include-linked-history",
    is_flag=True,
    help="Include history for linked items in JSON",
)
@click.option("--history-limit", type=int, default=50, show_default=True)
@click.option("--linked-limit", type=int, default=20, show_default=True)
@async_command
async def task_ready(
    project_ref: str | None,
    statuses: tuple[str, ...],
    include_checked_out: bool,
    include_generated: bool,
    output_format: str,
    view: str,
    include_history: bool,
    include_linked: bool,
    include_linked_history: bool,
    history_limit: int,
    linked_limit: int,
) -> None:
    """List tasks ready to start (no blocking dependencies)."""
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.models import TaskStatus
    from pms.models.workflow_state import get_workflow_by_id
    from pms.repositories.project_repository import ProjectRepository
    from pms.services.actor_service import ActorService
    from pms.services.generated_artifacts import (
        classify_project_operator_category,
        project_operator_category_label,
        project_operator_visibility_reason,
    )
    from pms.services.project_service import ProjectService
    from pms.services.task_service import TaskService
    from pms.utils.time import format_relative

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)

        task_service = TaskService(db, event_store, revision_store, metrics)
        project_service = ProjectService(db, event_store, revision_store, metrics)
        project_repo = ProjectRepository(db, event_store, revision_store, metrics)
        actor_service = ActorService(db, event_store, revision_store, metrics)

        project_id = None
        project_label = None
        if project_ref:
            project = await project_repo.get_by_name(project_ref)
            if project is None:
                project = await project_repo.get_by_id(project_ref)
            if project is None:
                console.print(f"[red]Project '{project_ref}' not found[/red]")
                return
            project_id = project.id
            project_label = project.name

        status_list = [TaskStatus(s) for s in statuses] if statuses else None

        async def _fetch_ready_page(
            page_limit: int, page_offset: int
        ) -> QueryResult[Any]:
            return await task_service.list_ready_tasks(
                project_id=project_id,
                statuses=status_list,
                exclude_checked_out=not include_checked_out,
                limit=page_limit,
                offset=page_offset,
            )

        all_matching_tasks = await _collect_all_task_query(_fetch_ready_page)
        if project_id:
            result = QueryResult(
                items=list(all_matching_tasks),
                total_count=len(all_matching_tasks),
                offset=0,
                limit=len(all_matching_tasks),
            )
            selected_population_name = "scoped_project"
            selected_population_tasks = list(all_matching_tasks)
            visible_population_tasks = list(all_matching_tasks)
            suppressed_hidden_count = 0
        else:
            excluded_project_ids = await _operator_hidden_project_ids(
                project_service,
                [task.project_id for task in all_matching_tasks],
            )
            visible_population_tasks = _exclude_tasks_from_projects(
                all_matching_tasks, excluded_project_ids
            )
            if include_generated:
                result = await _fetch_ready_page(100, 0)
                selected_population_name = "all_retained"
                selected_population_tasks = list(all_matching_tasks)
                suppressed_hidden_count = max(
                    0, len(selected_population_tasks) - len(visible_population_tasks)
                )
            else:
                visible_page = await _paginate_visible_task_query(
                    _fetch_ready_page,
                    project_service,
                    limit=100,
                    offset=0,
                )
                result = QueryResult(
                    items=visible_page.items,
                    total_count=visible_page.total_count,
                    offset=0,
                    limit=100,
                )
                selected_population_name = "visible_operator"
                selected_population_tasks = list(visible_population_tasks)
                suppressed_hidden_count = visible_page.suppressed_hidden_count

        task_ids = [task.id for task in result.items]
        activity_map = await task_service.get_last_activity_map(task_ids)
        workflow_transition_map = await task_service.get_last_transition_map(
            task_ids, kind="workflow"
        )
        status_transition_map = await task_service.get_last_transition_map(
            task_ids, kind="status"
        )
        project_names: dict[str, str | None] = {}
        task_project_operator_categories: dict[str, str | None] = {}
        for task_obj in result.items:
            if task_obj.project_id and task_obj.project_id not in project_names:
                project = await project_repo.get_by_id(task_obj.project_id)
                project_names[task_obj.project_id] = project.name if project else None
                if project is not None:
                    task_project_operator_categories[task_obj.project_id] = (
                        classify_project_operator_category(project)
                    )
                else:
                    task_project_operator_categories[task_obj.project_id] = None
        assignee_map = await _resolve_assignee_map(
            list(result.items),
            actor_service,
        )
        focus_state = _resolve_command_focus_state(list(result.items), project_names)
        focus_task_payload = (
            focus_state.focus_task.to_payload()
            if focus_state.focus_task is not None
            else None
        )

        first_task = result.items[0] if result.items else None
        next_actions: list[str] = []
        if first_task:
            next_actions.append(f"task show {first_task.id}")
            next_actions.append(f"task start {first_task.id}")
        if project_label:
            next_actions.append(f'task add "{project_label}" "New task"')
        else:
            next_actions.append("task list")
        next_actions = _normalize_next_steps(
            *next_actions,
            "task stale --format json",
            "dashboard --format json",
            "start --format json",
        )
        no_actionable_work = _instance_task_surface_has_no_actionable_work(
            project_id=project_id,
            include_generated=include_generated,
            visible_total_count=result.total_count,
            suppressed_hidden_count=suppressed_hidden_count,
        )
        scope_summary = (
            "Instance-wide retained ready-task view. Generated and historical project tasks are included explicitly."
            if include_generated
            else "Instance-wide ready-task view. Only operator-visible active-project tasks are surfaced by default."
        )
        ready_self_command = "task ready --format json"
        if project_id:
            ready_self_command = _append_cli_option(
                ready_self_command, "--project", project_id
            )
        ready_self_command = _append_cli_repeatable_options(
            ready_self_command, "--status", statuses
        )
        if include_checked_out:
            ready_self_command += " --include-checked-out"
        if include_generated:
            ready_self_command += " --include-generated"
        if view != "review":
            ready_self_command = _append_cli_option(ready_self_command, "--view", view)
        if include_history:
            ready_self_command += " --include-history"
        if include_linked:
            ready_self_command += " --include-linked"
        if include_linked_history:
            ready_self_command += " --include-linked-history"
        if history_limit != 50:
            ready_self_command = _append_cli_option(
                ready_self_command, "--history-limit", history_limit
            )
        if linked_limit != 20:
            ready_self_command = _append_cli_option(
                ready_self_command, "--linked-limit", linked_limit
            )
        if no_actionable_work:
            scope_summary = _instance_task_surface_no_actionable_summary(
                "ready-task view"
            )
            next_actions = _no_actionable_work_next_steps(
                ready_self_command
                if include_generated
                else ready_self_command.replace(
                    " --format json", " --include-generated --format json"
                )
            )

        if output_format == "json":
            include_history, include_linked, include_linked_history = (
                _normalize_history_flags(
                    include_history, include_linked, include_linked_history
                )
            )
            effective_history_limit = history_limit if history_limit > 0 else 1000
            effective_linked_limit = linked_limit if linked_limit > 0 else 1000
            task_repo = None
            if include_linked:
                from pms.repositories.task_repository import TaskRepository

                task_repo = TaskRepository(db, event_store, revision_store, metrics)

            progress_repo = None
            state_repo = None
            evidence_repo = None
            if include_history or include_linked_history:
                from pms.repositories.progress_repository import ProgressRepository
                from pms.repositories.state_transition_repository import (
                    StateTransitionRepository,
                )
                from pms.repositories.task_evidence_repository import (
                    TaskEvidenceRepository,
                )

                progress_repo = ProgressRepository(db)
                state_repo = StateTransitionRepository(db)
                evidence_repo = TaskEvidenceRepository(db)

            payload_items = []
            for task_obj in result.items:
                data = _public_task_payload(
                    task_obj,
                    assignee_map=assignee_map,
                )
                data["last_activity_at"] = _to_iso(activity_map.get(task_obj.id))
                data["project_name"] = project_names.get(task_obj.project_id)
                data["project_operator_category"] = (
                    task_project_operator_categories.get(task_obj.project_id)
                    if task_obj.project_id
                    else None
                )
                data["project_operator_category_label"] = (
                    project_operator_category_label(
                        task_project_operator_categories[task_obj.project_id]
                    )
                    if task_obj.project_id
                    and task_project_operator_categories.get(task_obj.project_id)
                    else None
                )
                data["project_operator_visibility_reason"] = (
                    project_operator_visibility_reason(
                        task_project_operator_categories[task_obj.project_id]
                    )
                    if task_obj.project_id
                    and task_project_operator_categories.get(task_obj.project_id)
                    else None
                )
                data["links"] = _normalize_command_links(
                    {
                        "self": f"task show {task_obj.id}",
                        "timeline": f"task timeline {task_obj.id}",
                        "graph": f"task graph {task_obj.id}",
                        "evidence": f"task evidence list {task_obj.id}",
                        "ready": ready_self_command,
                        "stale": "task stale --format json",
                        "list": (
                            f"task list --project {task_obj.project_id} --format json"
                            if task_obj.project_id
                            else "task list --format json"
                        ),
                        "actor": _task_assignee_actor_link(task_obj, assignee_map),
                        "dashboard": "dashboard --format json",
                        "guide": "start --format json",
                    }
                )
                data["assignee"] = _task_assignee_payload(task_obj, assignee_map)
                data["next_steps"] = _normalize_next_steps(
                    f"pms task show {task_obj.id}",
                    f"pms task start {task_obj.id}",
                    f"pms task update {task_obj.id}",
                    (
                        f"pms task list --project {task_obj.project_id}"
                        if task_obj.project_id
                        else "pms task list"
                    ),
                    *next_actions,
                )

                if include_history:
                    data["history"] = await _build_task_history(
                        task_id=task_obj.id,
                        progress_repo=progress_repo,
                        state_repo=state_repo,
                        evidence_repo=evidence_repo,
                        history_limit=effective_history_limit,
                    )

                if include_linked and task_repo:
                    linked_payload, linked_history = await _build_task_linked_payload(
                        task_obj,
                        task_repo=task_repo,
                        project_repo=project_repo,
                        task_service=task_service,
                        linked_limit=effective_linked_limit,
                        history_limit=effective_history_limit,
                        include_linked_history=include_linked_history,
                        progress_repo=progress_repo,
                        state_repo=state_repo,
                        evidence_repo=evidence_repo,
                    )
                    data["linked"] = linked_payload
                    if linked_history:
                        data["linked_history"] = linked_history

                payload_items.append(data)
            payload = {
                "items": payload_items,
                "page": {
                    "total_count": result.total_count,
                    "limit": result.limit,
                    "offset": result.offset,
                    "has_more": result.has_more,
                    "next_offset": result.offset + result.limit
                    if result.has_more
                    else None,
                },
                "scope": (
                    {
                        "kind": "project_ready_tasks",
                        "population": "scoped_project",
                        "project_id": project_id,
                        "project_name": project_label,
                    }
                    if project_id
                    else {
                        "kind": "instance_ready_tasks",
                        "population": selected_population_name,
                        "summary": scope_summary,
                    }
                ),
                "visible_totals": (
                    {
                        "population": "visible_operator",
                        **_task_population_totals(visible_population_tasks, TaskStatus),
                    }
                    if not project_id
                    else {
                        "population": "scoped_project",
                        **_task_population_totals(
                            selected_population_tasks, TaskStatus
                        ),
                    }
                ),
                "population_totals": {
                    "population": selected_population_name,
                    **_task_population_totals(selected_population_tasks, TaskStatus),
                },
                "suppressed_hidden_count": suppressed_hidden_count
                if not project_id
                else 0,
                "focus_task": focus_task_payload,
                "graph_navigation": _command_focus_graph_navigation(
                    focus_task=focus_state.focus_task,
                    task_lookup={task.id: task for task in result.items},
                    assignee_map=assignee_map,
                    project_id=project_id,
                    project_name=project_label,
                ),
                "links": _normalize_command_links(
                    {
                        "self": ready_self_command,
                        "stale": "task stale --format json",
                        "dashboard": "dashboard --format json",
                        "guide": "start --format json",
                    }
                ),
                "next_steps": next_actions,
                "params": {
                    "project_id": project_id,
                    "statuses": list(statuses),
                    "include_checked_out": include_checked_out,
                    "view": view,
                    "include_history": include_history,
                    "include_linked": include_linked,
                    "include_linked_history": include_linked_history,
                    "include_generated": include_generated,
                    "history_limit": history_limit,
                    "linked_limit": linked_limit,
                },
            }
            click.echo(json.dumps(payload, default=str))
            return

        if output_format == "csv":
            headers = [
                "id",
                "title",
                "priority",
                "status",
                "project_id",
                "project_name",
                "last_activity_at",
            ]
            click.echo(_csv_row(headers))
            for task_obj in result.items:
                row = [
                    task_obj.id,
                    task_obj.title,
                    task_obj.priority.value,
                    task_obj.status.value,
                    task_obj.project_id,
                    project_names.get(task_obj.project_id) or "",
                    _to_iso(activity_map.get(task_obj.id)) or "",
                ]
                click.echo(_csv_row(row))
            return

        if result.total_count == 0:
            console.print("No ready tasks.")
            console.print("[dim]Total: 0[/dim]")
            if no_actionable_work:
                console.print(f"[dim]{scope_summary}[/dim]")
            _print_next_steps(*next_actions)
            return

        if view == "review":
            _print_task_review_view(
                result=result,
                tasks=list(result.items),
                total_tasks=selected_population_tasks,
                title="Ready Tasks",
                project_label=project_label,
                project_id=project_id,
                assignee_actor=None,
                assignee_map=assignee_map,
                project_names=project_names,
                activity_map=activity_map,
                workflow_transition_map=workflow_transition_map,
                status_transition_map=status_transition_map,
                focus_state=focus_state,
                focus_task_payload=focus_task_payload,
                suppressed_hidden_count=suppressed_hidden_count,
                no_actionable_work=no_actionable_work,
                scope_summary=scope_summary,
            )
            _print_next_steps(*next_actions)
            return

        table = Table(title="Ready Tasks")
        table.add_column("Title", style="cyan")
        table.add_column("Project")
        table.add_column("Workflow")
        table.add_column("Next")
        table.add_column("Status")
        table.add_column("Priority")
        table.add_column("Activity")
        table.add_column("ID", style="dim")

        for task_obj in result.items:
            project_label = (
                project_names.get(task_obj.project_id, task_obj.project_id)
                if task_obj.project_id
                else "-"
            )
            workflow_state = task_obj.current_state if task_obj.workflow_id else "-"
            next_transitions = "-"
            if task_obj.workflow_id and task_obj.current_state:
                workflow = get_workflow_by_id(task_obj.workflow_id)
                transitions = _collect_workflow_transitions(
                    workflow, task_obj.current_state
                )
                if transitions:
                    next_transitions = _truncate(", ".join(transitions), 24)
            table.add_row(
                task_obj.title[:40],
                project_label[:20],
                workflow_state,
                next_transitions,
                task_obj.status.value,
                task_obj.priority.value,
                format_relative(activity_map.get(task_obj.id) or task_obj.updated_at),
                task_obj.id[:8],
            )

        console.print(table)
        console.print(f"[dim]Total: {result.total_count}[/dim]")
        if not project_id and suppressed_hidden_count:
            console.print(
                f"[dim]Suppressed hidden tasks: {suppressed_hidden_count} "
                f"(use --include-generated to show retained audit/history tasks)[/dim]"
            )
        if no_actionable_work:
            console.print(f"[dim]{scope_summary}[/dim]")
        _print_next_steps(*next_actions)
    finally:
        await db.disconnect()


@task.command("stale")
@click.option("-p", "--project", "project_ref", help="Filter by project name or ID")
@click.option(
    "-s",
    "--status",
    "statuses",
    multiple=True,
    type=click.Choice(
        ["todo", "in_progress", "blocked", "in_review", "done", "cancelled"]
    ),
)
@click.option("--days", default=14, show_default=True, help="Stale after N days")
@click.option("--updated-before", help="Updated before (ISO timestamp)")
@click.option("--include-terminal", is_flag=True, help="Include done/cancelled tasks")
@click.option(
    "--include-generated",
    is_flag=True,
    help="Include tasks from generated or otherwise non-operator-visible projects in instance-wide views",
)
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["table", "json", "csv"]),
    default="table",
    show_default=True,
)
@click.option(
    "--view",
    type=click.Choice(["review", "overview"]),
    default="review",
    show_default=True,
    help="Text view profile (review/overview)",
)
@click.option("--include-history", is_flag=True, help="Include history in JSON")
@click.option("--include-linked", is_flag=True, help="Include linked items in JSON")
@click.option(
    "--include-linked-history",
    is_flag=True,
    help="Include history for linked items in JSON",
)
@click.option("--history-limit", type=int, default=50, show_default=True)
@click.option("--linked-limit", type=int, default=20, show_default=True)
@async_command
async def task_stale(
    project_ref: str | None,
    statuses: tuple[str, ...],
    days: int,
    updated_before: str | None,
    include_terminal: bool,
    include_generated: bool,
    output_format: str,
    view: str,
    include_history: bool,
    include_linked: bool,
    include_linked_history: bool,
    history_limit: int,
    linked_limit: int,
) -> None:
    """List stale tasks (no recent updates)."""
    from datetime import datetime

    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.models import TaskStatus
    from pms.repositories.project_repository import ProjectRepository
    from pms.services.actor_service import ActorService
    from pms.services.generated_artifacts import (
        classify_project_operator_category,
        project_operator_category_label,
        project_operator_visibility_reason,
    )
    from pms.services.project_service import ProjectService
    from pms.services.task_service import TaskService

    def parse_dt(value: str | None) -> datetime | None:
        if value is None:
            return None
        try:
            return datetime.fromisoformat(value)
        except ValueError:
            raise click.ClickException("Invalid updated-before timestamp")

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)

        task_service = TaskService(db, event_store, revision_store, metrics)
        project_service = ProjectService(db, event_store, revision_store, metrics)
        project_repo = ProjectRepository(db, event_store, revision_store, metrics)
        actor_service = ActorService(db, event_store, revision_store, metrics)

        project_id = None
        project_label = None
        if project_ref:
            project = await project_repo.get_by_name(project_ref)
            if project is None:
                project = await project_repo.get_by_id(project_ref)
            if project is None:
                console.print(f"[red]Project '{project_ref}' not found[/red]")
                return
            project_id = project.id
            project_label = project.name

        status_list = [TaskStatus(s) for s in statuses] if statuses else None

        updated_before_dt = parse_dt(updated_before)

        async def _fetch_stale_page(
            page_limit: int, page_offset: int
        ) -> QueryResult[Any]:
            return await task_service.list_stale_tasks(
                project_id=project_id,
                statuses=status_list,
                stale_after_days=days,
                updated_before=updated_before_dt,
                include_terminal=include_terminal,
                limit=page_limit,
                offset=page_offset,
            )

        all_matching_tasks = await _collect_all_task_query(_fetch_stale_page)
        if project_id:
            result = QueryResult(
                items=list(all_matching_tasks),
                total_count=len(all_matching_tasks),
                offset=0,
                limit=len(all_matching_tasks),
            )
            selected_population_name = "scoped_project"
            selected_population_tasks = list(all_matching_tasks)
            visible_population_tasks = list(all_matching_tasks)
            suppressed_hidden_count = 0
        else:
            excluded_project_ids = await _operator_hidden_project_ids(
                project_service,
                [task.project_id for task in all_matching_tasks],
            )
            visible_population_tasks = _exclude_tasks_from_projects(
                all_matching_tasks, excluded_project_ids
            )
            if include_generated:
                result = await _fetch_stale_page(100, 0)
                selected_population_name = "all_retained"
                selected_population_tasks = list(all_matching_tasks)
                suppressed_hidden_count = max(
                    0, len(selected_population_tasks) - len(visible_population_tasks)
                )
            else:
                visible_page = await _paginate_visible_task_query(
                    _fetch_stale_page,
                    project_service,
                    limit=100,
                    offset=0,
                )
                result = QueryResult(
                    items=visible_page.items,
                    total_count=visible_page.total_count,
                    offset=0,
                    limit=100,
                )
                selected_population_name = "visible_operator"
                selected_population_tasks = list(visible_population_tasks)
                suppressed_hidden_count = visible_page.suppressed_hidden_count

        task_ids = [task.id for task in result.items]
        activity_map = await task_service.get_last_activity_map(task_ids)
        workflow_transition_map = await task_service.get_last_transition_map(
            task_ids, kind="workflow"
        )
        status_transition_map = await task_service.get_last_transition_map(
            task_ids, kind="status"
        )
        project_names: dict[str, str | None] = {}
        task_project_operator_categories: dict[str, str | None] = {}
        for task_obj in result.items:
            if task_obj.project_id and task_obj.project_id not in project_names:
                project = await project_repo.get_by_id(task_obj.project_id)
                project_names[task_obj.project_id] = project.name if project else None
                if project is not None:
                    task_project_operator_categories[task_obj.project_id] = (
                        classify_project_operator_category(project)
                    )
                else:
                    task_project_operator_categories[task_obj.project_id] = None
        assignee_map = await _resolve_assignee_map(
            list(result.items),
            actor_service,
        )
        focus_state = _resolve_command_focus_state(list(result.items), project_names)
        focus_task_payload = (
            focus_state.focus_task.to_payload()
            if focus_state.focus_task is not None
            else None
        )

        first_task = result.items[0] if result.items else None
        next_steps = []
        if first_task:
            next_steps.append(f"pms task show {first_task.id}")
            next_steps.append(f"pms task update {first_task.id}")
        if project_label:
            next_steps.append(f'pms task list --project "{project_label}"')
        else:
            next_steps.append("pms task list")
        next_steps = _normalize_next_steps(
            *next_steps,
            "pms task ready --format json",
            "pms dashboard --format json",
            "pms start --format json",
        )
        stale_self_command = "task stale --format json"
        if project_id:
            stale_self_command = _append_cli_option(
                stale_self_command, "--project", project_id
            )
        if statuses:
            stale_self_command = _append_cli_repeatable_options(
                stale_self_command, "--status", statuses
            )
        stale_self_command = _append_cli_option(stale_self_command, "--days", days)
        if updated_before:
            stale_self_command = _append_cli_option(
                stale_self_command, "--updated-before", updated_before
            )
        if include_terminal:
            stale_self_command += " --include-terminal"
        if include_generated:
            stale_self_command += " --include-generated"
        if view != "review":
            stale_self_command = _append_cli_option(stale_self_command, "--view", view)
        no_actionable_work = _instance_task_surface_has_no_actionable_work(
            project_id=project_id,
            include_generated=include_generated,
            visible_total_count=result.total_count,
            suppressed_hidden_count=suppressed_hidden_count,
        )
        scope_summary = (
            "Instance-wide retained stale-task view. Generated and historical project tasks are included explicitly."
            if include_generated
            else "Instance-wide stale-task view. Only operator-visible active-project tasks are surfaced by default."
        )
        if no_actionable_work:
            scope_summary = _instance_task_surface_no_actionable_summary(
                "stale-task view"
            )
            next_steps = _no_actionable_work_next_steps(
                stale_self_command
                if include_generated
                else stale_self_command.replace(
                    " --format json", " --include-generated --format json"
                )
            )

        if output_format == "json":
            include_history, include_linked, include_linked_history = (
                _normalize_history_flags(
                    include_history, include_linked, include_linked_history
                )
            )
            effective_history_limit = history_limit if history_limit > 0 else 1000
            effective_linked_limit = linked_limit if linked_limit > 0 else 1000
            stale_self_command = _cli_command(stale_self_command)
            if include_terminal:
                pass
            if include_history:
                stale_self_command += " --include-history"
            if include_linked:
                stale_self_command += " --include-linked"
            if include_linked_history:
                stale_self_command += " --include-linked-history"
            if history_limit != 50:
                stale_self_command += f" --history-limit {history_limit}"
            if linked_limit != 20:
                stale_self_command += f" --linked-limit {linked_limit}"

            task_repo = None
            if include_linked:
                from pms.repositories.task_repository import TaskRepository

                task_repo = TaskRepository(db, event_store, revision_store, metrics)

            progress_repo = None
            state_repo = None
            evidence_repo = None
            if include_history or include_linked_history:
                from pms.repositories.progress_repository import ProgressRepository
                from pms.repositories.state_transition_repository import (
                    StateTransitionRepository,
                )
                from pms.repositories.task_evidence_repository import (
                    TaskEvidenceRepository,
                )

                progress_repo = ProgressRepository(db)
                state_repo = StateTransitionRepository(db)
                evidence_repo = TaskEvidenceRepository(db)

            payload_items = []
            for task_obj in result.items:
                data = _public_task_payload(
                    task_obj,
                    assignee_map=assignee_map,
                )
                data["last_activity_at"] = _to_iso(activity_map.get(task_obj.id))
                data["project_name"] = project_names.get(task_obj.project_id)
                data["project_operator_category"] = (
                    task_project_operator_categories.get(task_obj.project_id)
                    if task_obj.project_id
                    else None
                )
                data["project_operator_category_label"] = (
                    project_operator_category_label(
                        task_project_operator_categories[task_obj.project_id]
                    )
                    if task_obj.project_id
                    and task_project_operator_categories.get(task_obj.project_id)
                    else None
                )
                data["project_operator_visibility_reason"] = (
                    project_operator_visibility_reason(
                        task_project_operator_categories[task_obj.project_id]
                    )
                    if task_obj.project_id
                    and task_project_operator_categories.get(task_obj.project_id)
                    else None
                )
                data["links"] = _normalize_command_links(
                    {
                        "self": f"task show {task_obj.id}",
                        "timeline": f"task timeline {task_obj.id}",
                        "graph": f"task graph {task_obj.id}",
                        "evidence": f"task evidence list {task_obj.id}",
                        "stale": stale_self_command,
                        "ready": "task ready --format json",
                        "list": (
                            f"task list --project {task_obj.project_id} --format json"
                            if task_obj.project_id
                            else "task list --format json"
                        ),
                        "actor": _task_assignee_actor_link(task_obj, assignee_map),
                        "dashboard": "dashboard --format json",
                        "guide": "start --format json",
                    }
                )
                data["assignee"] = _task_assignee_payload(task_obj, assignee_map)
                data["next_steps"] = _normalize_next_steps(
                    f"pms task show {task_obj.id}",
                    f"pms task update {task_obj.id}",
                    f"pms task start {task_obj.id}",
                    (
                        f"pms task list --project {task_obj.project_id}"
                        if task_obj.project_id
                        else "pms task list"
                    ),
                    *next_steps,
                )

                if include_history:
                    data["history"] = await _build_task_history(
                        task_id=task_obj.id,
                        progress_repo=progress_repo,
                        state_repo=state_repo,
                        evidence_repo=evidence_repo,
                        history_limit=effective_history_limit,
                    )

                if include_linked and task_repo:
                    linked_payload, linked_history = await _build_task_linked_payload(
                        task_obj,
                        task_repo=task_repo,
                        project_repo=project_repo,
                        task_service=task_service,
                        linked_limit=effective_linked_limit,
                        history_limit=effective_history_limit,
                        include_linked_history=include_linked_history,
                        progress_repo=progress_repo,
                        state_repo=state_repo,
                        evidence_repo=evidence_repo,
                    )
                    data["linked"] = linked_payload
                    if linked_history:
                        data["linked_history"] = linked_history

                payload_items.append(data)
            payload = {
                "items": payload_items,
                "page": {
                    "total_count": result.total_count,
                    "limit": result.limit,
                    "offset": result.offset,
                    "has_more": result.has_more,
                    "next_offset": result.offset + result.limit
                    if result.has_more
                    else None,
                },
                "scope": (
                    {
                        "kind": "project_stale_tasks",
                        "population": "scoped_project",
                        "project_id": project_id,
                        "project_name": project_label,
                    }
                    if project_id
                    else {
                        "kind": "instance_stale_tasks",
                        "population": selected_population_name,
                        "summary": scope_summary,
                    }
                ),
                "visible_totals": (
                    {
                        "population": "visible_operator",
                        **_task_population_totals(visible_population_tasks, TaskStatus),
                    }
                    if not project_id
                    else {
                        "population": "scoped_project",
                        **_task_population_totals(
                            selected_population_tasks, TaskStatus
                        ),
                    }
                ),
                "population_totals": {
                    "population": selected_population_name,
                    **_task_population_totals(selected_population_tasks, TaskStatus),
                },
                "suppressed_hidden_count": suppressed_hidden_count
                if not project_id
                else 0,
                "focus_task": focus_task_payload,
                "graph_navigation": _command_focus_graph_navigation(
                    focus_task=focus_state.focus_task,
                    task_lookup={task.id: task for task in result.items},
                    assignee_map=assignee_map,
                    project_id=project_id,
                    project_name=project_label,
                ),
                "links": _normalize_command_links(
                    {
                        "self": stale_self_command,
                        "ready": "task ready --format json",
                        "dashboard": "dashboard --format json",
                        "guide": "start --format json",
                    }
                ),
                "next_steps": next_steps,
                "params": {
                    "project_id": project_id,
                    "statuses": list(statuses),
                    "days": days,
                    "updated_before": updated_before,
                    "include_terminal": include_terminal,
                    "view": view,
                    "include_history": include_history,
                    "include_linked": include_linked,
                    "include_linked_history": include_linked_history,
                    "include_generated": include_generated,
                    "history_limit": history_limit,
                    "linked_limit": linked_limit,
                },
            }
            click.echo(json.dumps(payload, default=str))
            return

        if output_format == "csv":
            headers = [
                "id",
                "title",
                "status",
                "last_activity_at",
                "project_id",
                "project_name",
            ]
            click.echo(_csv_row(headers))
            for task_obj in result.items:
                row = [
                    task_obj.id,
                    task_obj.title,
                    task_obj.status.value,
                    _to_iso(activity_map.get(task_obj.id)) or "",
                    task_obj.project_id,
                    project_names.get(task_obj.project_id) or "",
                ]
                click.echo(_csv_row(row))
            return

        if view == "review":
            _print_task_review_view(
                result=result,
                tasks=list(result.items),
                total_tasks=selected_population_tasks,
                project_label=project_label,
                project_id=project_id,
                assignee_actor=None,
                assignee_map=assignee_map,
                project_names=project_names,
                activity_map=activity_map,
                workflow_transition_map=workflow_transition_map,
                status_transition_map=status_transition_map,
                focus_state=focus_state,
                focus_task_payload=focus_task_payload,
                suppressed_hidden_count=suppressed_hidden_count,
                no_actionable_work=no_actionable_work,
                scope_summary=scope_summary,
            )
            _print_next_steps(*next_steps)
            return

        from pms.utils.time import format_relative

        table = Table(title="Stale Tasks")
        table.add_column("Title", style="cyan")
        table.add_column("Project")
        table.add_column("Status")
        table.add_column("Activity")
        table.add_column("ID", style="dim")

        for task_obj in result.items:
            updated_at = format_relative(
                activity_map.get(task_obj.id) or task_obj.updated_at
            )
            project_label = (
                project_names.get(task_obj.project_id, task_obj.project_id)
                if task_obj.project_id
                else "-"
            )
            table.add_row(
                task_obj.title[:40],
                project_label[:20],
                task_obj.status.value,
                updated_at,
                task_obj.id[:8],
            )

        console.print(table)
        console.print(f"[dim]Total: {result.total_count}[/dim]")
        if not project_id and suppressed_hidden_count:
            console.print(
                f"[dim]Suppressed hidden tasks: {suppressed_hidden_count} "
                f"(use --include-generated to show retained audit/history tasks)[/dim]"
            )
        if no_actionable_work:
            console.print(f"[dim]{scope_summary}[/dim]")
        _print_next_steps(*next_steps)
    finally:
        await db.disconnect()


@task.command("duplicates")
@click.option("-p", "--project", "project_ref", help="Filter by project name or ID")
@click.option(
    "-s",
    "--status",
    "statuses",
    multiple=True,
    type=click.Choice(
        ["todo", "in_progress", "blocked", "in_review", "done", "cancelled"]
    ),
)
@click.option("--include-terminal", is_flag=True, help="Include done/cancelled tasks")
@click.option("--min-count", default=2, show_default=True, help="Minimum group size")
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["table", "json", "csv"]),
    default="table",
    show_default=True,
)
@click.option("--include-history", is_flag=True, help="Include history in JSON")
@click.option("--include-linked", is_flag=True, help="Include linked items in JSON")
@click.option(
    "--include-generated",
    is_flag=True,
    help="Include retained/generated task groups from hidden projects in instance-wide views",
)
@click.option(
    "--include-linked-history",
    is_flag=True,
    help="Include history for linked items in JSON",
)
@click.option("--history-limit", type=int, default=50, show_default=True)
@click.option("--linked-limit", type=int, default=20, show_default=True)
@async_command
async def task_duplicates(
    project_ref: str | None,
    statuses: tuple[str, ...],
    include_terminal: bool,
    min_count: int,
    output_format: str,
    include_history: bool,
    include_linked: bool,
    include_generated: bool,
    include_linked_history: bool,
    history_limit: int,
    linked_limit: int,
) -> None:
    """List duplicate task groups by normalized title."""
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.models import DuplicateTaskGroup, TaskStatus
    from pms.repositories.project_repository import ProjectRepository
    from pms.services.actor_service import ActorService
    from pms.services.generated_artifacts import (
        classify_project_operator_category,
        project_operator_category_label,
        project_operator_visibility_reason,
    )
    from pms.services.project_service import ProjectService
    from pms.services.task_service import TaskService

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)

        task_service = TaskService(db, event_store, revision_store, metrics)
        project_service = ProjectService(db, event_store, revision_store, metrics)
        project_repo = ProjectRepository(db, event_store, revision_store, metrics)
        actor_service = ActorService(db, event_store, revision_store, metrics)

        project_id = None
        project_label = None
        if project_ref:
            project = await project_repo.get_by_name(project_ref)
            if project is None:
                project = await project_repo.get_by_id(project_ref)
            if project is None:
                console.print(f"[red]Project '{project_ref}' not found[/red]")
                return
            project_id = project.id
            project_label = project.name

        status_list = [TaskStatus(s) for s in statuses] if statuses else None

        async def _fetch_duplicate_page(
            page_limit: int, page_offset: int
        ) -> QueryResult[Any]:
            return await task_service.find_duplicate_tasks(
                project_id=project_id,
                statuses=status_list,
                include_terminal=include_terminal,
                min_count=min_count,
                limit=page_limit,
                offset=page_offset,
            )

        all_retained_groups: list[Any] = []
        duplicate_offset = 0
        duplicate_limit = 100
        duplicate_total_count = 0
        while True:
            duplicate_page = await _fetch_duplicate_page(
                duplicate_limit, duplicate_offset
            )
            all_retained_groups.extend(duplicate_page.items)
            duplicate_total_count = duplicate_page.total_count
            if len(duplicate_page.items) < duplicate_limit:
                break
            duplicate_offset += duplicate_limit

        selected_population_name = "scoped_project"
        visible_groups = list(all_retained_groups)
        selected_groups = list(all_retained_groups)
        suppressed_hidden_count = 0
        if not project_id:
            hidden_project_ids = await _operator_hidden_project_ids(
                project_service,
                [
                    task.project_id
                    for group in all_retained_groups
                    for task in group.tasks
                    if task.project_id
                ],
            )

            visible_groups = []
            for group in all_retained_groups:
                visible_tasks = [
                    task
                    for task in group.tasks
                    if not task.project_id or task.project_id not in hidden_project_ids
                ]
                if len(visible_tasks) < min_count:
                    continue
                visible_primary_id = group.suggested_primary_id
                if visible_primary_id and all(
                    task.id != visible_primary_id for task in visible_tasks
                ):
                    visible_primary_id = visible_tasks[0].id
                visible_groups.append(
                    DuplicateTaskGroup(
                        normalized_title=group.normalized_title,
                        tasks=visible_tasks,
                        suggested_primary_id=visible_primary_id,
                        suggested_primary_reason=(
                            group.suggested_primary_reason
                            if visible_primary_id == group.suggested_primary_id
                            else "Recomputed after suppressing hidden generated tasks"
                        ),
                    )
                )

            suppressed_hidden_count = max(
                0,
                sum(len(group.tasks) for group in all_retained_groups)
                - sum(len(group.tasks) for group in visible_groups),
            )
            if include_generated:
                selected_population_name = "all_retained"
                selected_groups = list(all_retained_groups)
            else:
                selected_population_name = "visible_operator"
                selected_groups = list(visible_groups)

        result = QueryResult(
            items=selected_groups,
            total_count=len(selected_groups),
            offset=0,
            limit=len(selected_groups),
        )

        task_ids = [task.id for group in result.items for task in group.tasks]
        activity_map = (
            await task_service.get_last_activity_map(task_ids) if task_ids else {}
        )
        project_names: dict[str, str | None] = {}
        task_project_operator_categories: dict[str, str | None] = {}
        for task_obj in [task for group in result.items for task in group.tasks]:
            if task_obj.project_id and task_obj.project_id not in project_names:
                project = await project_repo.get_by_id(task_obj.project_id)
                project_names[task_obj.project_id] = project.name if project else None
                if project is not None:
                    task_project_operator_categories[task_obj.project_id] = (
                        classify_project_operator_category(project)
                    )
                else:
                    task_project_operator_categories[task_obj.project_id] = None
        assignee_map = await _resolve_assignee_map(
            [task for group in result.items for task in group.tasks],
            actor_service,
        )

        def group_last_activity(group) -> datetime | None:
            if not group.tasks:
                return None
            timestamps = [
                activity_map.get(task.id) or task.updated_at for task in group.tasks
            ]
            return max(timestamps)

        def group_projects(group) -> str:
            if not group.tasks:
                return "-"
            seen: list[str] = []
            for task_obj in group.tasks:
                label = (
                    project_names.get(task_obj.project_id, task_obj.project_id)
                    if task_obj.project_id
                    else "-"
                )
                if label and label not in seen:
                    seen.append(label)
            preview = ", ".join(seen[:2])
            if len(seen) > 2:
                preview = f"{preview} +{len(seen) - 2}"
            return preview or "-"

        first_group = result.items[0] if result.items else None
        next_steps = []
        if first_group and first_group.tasks:
            primary_id = first_group.suggested_primary_id or first_group.tasks[0].id
            duplicate_ids = [
                task.id for task in first_group.tasks if task.id != primary_id
            ][:2]
            if duplicate_ids:
                preview_cmd = " ".join(
                    [f"--duplicate-id {dup_id}" for dup_id in duplicate_ids]
                )
                next_steps.append(f"pms task merge-preview {primary_id} {preview_cmd}")
                next_steps.append(
                    f"pms task merge-duplicates {primary_id} {preview_cmd}"
                )
        if project_label:
            next_steps.append(f'pms task list --project "{project_label}"')
        else:
            next_steps.append("pms task list")
        next_steps = _normalize_next_steps(
            *next_steps,
            "pms task ready --format json",
            "pms task stale --format json",
            "pms dashboard --format json",
            "pms start --format json",
        )
        duplicates_self_command = "task duplicates --format json"
        if project_id:
            duplicates_self_command = _append_cli_option(
                duplicates_self_command, "--project", project_id
            )
        if statuses:
            duplicates_self_command = _append_cli_repeatable_options(
                duplicates_self_command, "--status", statuses
            )
        if include_terminal:
            duplicates_self_command += " --include-terminal"
        duplicates_self_command = _append_cli_option(
            duplicates_self_command, "--min-count", min_count
        )
        if include_generated:
            duplicates_self_command += " --include-generated"
        no_actionable_work = _instance_task_surface_has_no_actionable_work(
            project_id=project_id,
            include_generated=include_generated,
            visible_total_count=result.total_count,
            suppressed_hidden_count=suppressed_hidden_count,
        )
        scope_summary = (
            "Instance-wide retained duplicate task groups. Generated and historical project tasks are included explicitly."
            if include_generated
            else "Instance-wide duplicate task groups. Only operator-visible active-project tasks are surfaced by default."
        )
        if no_actionable_work:
            scope_summary = _instance_task_surface_no_actionable_summary(
                "duplicate task groups"
            )
            next_steps = _no_actionable_work_next_steps(
                duplicates_self_command
                if include_generated
                else duplicates_self_command.replace(
                    " --format json", " --include-generated --format json"
                )
            )

        if output_format == "json":
            include_history, include_linked, include_linked_history = (
                _normalize_history_flags(
                    include_history, include_linked, include_linked_history
                )
            )
            effective_history_limit = history_limit if history_limit > 0 else 1000
            effective_linked_limit = linked_limit if linked_limit > 0 else 1000
            duplicates_self_command = _cli_command(duplicates_self_command)
            if include_history:
                duplicates_self_command += " --include-history"
            if include_linked:
                duplicates_self_command += " --include-linked"
            if include_linked_history:
                duplicates_self_command += " --include-linked-history"
            if history_limit != 50:
                duplicates_self_command += f" --history-limit {history_limit}"
            if linked_limit != 20:
                duplicates_self_command += f" --linked-limit {linked_limit}"

            task_repo = None
            if include_linked:
                from pms.repositories.task_repository import TaskRepository

                task_repo = TaskRepository(db, event_store, revision_store, metrics)

            progress_repo = None
            state_repo = None
            evidence_repo = None
            if include_history or include_linked_history:
                from pms.repositories.progress_repository import ProgressRepository
                from pms.repositories.state_transition_repository import (
                    StateTransitionRepository,
                )
                from pms.repositories.task_evidence_repository import (
                    TaskEvidenceRepository,
                )

                progress_repo = ProgressRepository(db)
                state_repo = StateTransitionRepository(db)
                evidence_repo = TaskEvidenceRepository(db)

            payload_items: list[dict[str, Any]] = []
            for group in result.items:
                group_primary_id = (
                    group.suggested_primary_id or group.tasks[0].id
                    if group.tasks
                    else None
                )
                group_duplicate_ids = (
                    [task.id for task in group.tasks if task.id != group_primary_id][:2]
                    if group_primary_id
                    else []
                )
                group_duplicate_args = " ".join(
                    [f"--duplicate-id {dup_id}" for dup_id in group_duplicate_ids]
                )
                group_merge_preview = (
                    f"pms task merge-preview {group_primary_id} {group_duplicate_args}"
                    if group_primary_id and group_duplicate_args
                    else None
                )
                group_merge_apply = (
                    "pms task merge-duplicates "
                    f"{group_primary_id} {group_duplicate_args}"
                    if group_primary_id and group_duplicate_args
                    else None
                )
                group_next_steps = _normalize_next_steps(
                    group_merge_preview or "",
                    group_merge_apply or "",
                    *next_steps,
                )

                tasks_payload = []
                for task_obj in group.tasks:
                    task_payload = {
                        **task_obj.to_dict(),
                        "last_activity_at": _to_iso(activity_map.get(task_obj.id)),
                        "project_name": project_names.get(task_obj.project_id),
                        "project_operator_category": (
                            task_project_operator_categories.get(task_obj.project_id)
                            if task_obj.project_id
                            else None
                        ),
                        "project_operator_category_label": (
                            project_operator_category_label(
                                task_project_operator_categories[task_obj.project_id]
                            )
                            if task_obj.project_id
                            and task_project_operator_categories.get(
                                task_obj.project_id
                            )
                            else None
                        ),
                        "project_operator_visibility_reason": (
                            project_operator_visibility_reason(
                                task_project_operator_categories[task_obj.project_id]
                            )
                            if task_obj.project_id
                            and task_project_operator_categories.get(
                                task_obj.project_id
                            )
                            else None
                        ),
                        "links": _normalize_command_links(
                            {
                                "self": f"task show {task_obj.id}",
                                "timeline": f"task timeline {task_obj.id}",
                                "graph": f"task graph {task_obj.id}",
                                "evidence": f"task evidence list {task_obj.id}",
                                "duplicates": duplicates_self_command,
                                "actor": _task_assignee_actor_link(
                                    task_obj, assignee_map
                                ),
                                "dashboard": "dashboard --format json",
                                "guide": "start --format json",
                            }
                        ),
                        "assignee": _task_assignee_payload(task_obj, assignee_map),
                        "next_steps": _normalize_next_steps(
                            f"pms task show {task_obj.id}",
                            group_merge_preview or "",
                            group_merge_apply or "",
                            *next_steps,
                        ),
                    }

                    if include_history:
                        task_payload["history"] = await _build_task_history(
                            task_id=task_obj.id,
                            progress_repo=progress_repo,
                            state_repo=state_repo,
                            evidence_repo=evidence_repo,
                            history_limit=effective_history_limit,
                        )

                    if include_linked and task_repo:
                        (
                            linked_payload,
                            linked_history,
                        ) = await _build_task_linked_payload(
                            task_obj,
                            task_repo=task_repo,
                            project_repo=project_repo,
                            task_service=task_service,
                            linked_limit=effective_linked_limit,
                            history_limit=effective_history_limit,
                            include_linked_history=include_linked_history,
                            progress_repo=progress_repo,
                            state_repo=state_repo,
                            evidence_repo=evidence_repo,
                        )
                        task_payload["linked"] = linked_payload
                        if linked_history:
                            task_payload["linked_history"] = linked_history

                    tasks_payload.append(task_payload)

                payload_items.append(
                    {
                        "normalized_title": group.normalized_title,
                        "count": group.count,
                        "suggested_primary_id": group.suggested_primary_id,
                        "suggested_primary_reason": group.suggested_primary_reason,
                        "last_activity_at": _to_iso(group_last_activity(group)),
                        "projects": [
                            project_names.get(task.project_id, task.project_id)
                            if task.project_id
                            else "-"
                            for task in group.tasks
                        ],
                        "links": _normalize_command_links(
                            {
                                "self": duplicates_self_command,
                                "primary": (
                                    f"task show {group_primary_id}"
                                    if group_primary_id
                                    else None
                                ),
                                "merge_preview": group_merge_preview,
                                "merge_apply": group_merge_apply,
                                "dashboard": "dashboard --format json",
                                "guide": "start --format json",
                            }
                        ),
                        "next_steps": group_next_steps,
                        "tasks": tasks_payload,
                    }
                )

            payload = {
                "items": payload_items,
                "page": {
                    "total_count": result.total_count,
                    "limit": result.limit,
                    "offset": result.offset,
                    "has_more": False,
                    "next_offset": None,
                },
                "scope": (
                    {
                        "kind": "project_task_duplicates",
                        "population": "scoped_project",
                        "project_id": project_id,
                        "project_name": project_label,
                    }
                    if project_id
                    else {
                        "kind": "instance_task_duplicates",
                        "population": selected_population_name,
                        "summary": scope_summary,
                    }
                ),
                "visible_totals": (
                    {
                        "population": "visible_operator",
                        **_duplicate_group_totals(visible_groups),
                    }
                    if not project_id
                    else {
                        "population": "scoped_project",
                        **_duplicate_group_totals(selected_groups),
                    }
                ),
                "population_totals": {
                    "population": selected_population_name,
                    **_duplicate_group_totals(selected_groups),
                },
                "suppressed_hidden_count": suppressed_hidden_count
                if not project_id
                else 0,
                "links": _normalize_command_links(
                    {
                        "self": duplicates_self_command,
                        "list": (
                            f"task list --project {project_id} --format json"
                            if project_id
                            else "task list --format json"
                        ),
                        "ready": "task ready --format json",
                        "dashboard": "dashboard --format json",
                        "guide": "start --format json",
                    }
                ),
                "next_steps": next_steps,
                "params": {
                    "project_id": project_id,
                    "statuses": list(statuses),
                    "include_terminal": include_terminal,
                    "include_generated": include_generated,
                    "min_count": min_count,
                    "include_history": include_history,
                    "include_linked": include_linked,
                    "include_linked_history": include_linked_history,
                    "history_limit": history_limit,
                    "linked_limit": linked_limit,
                },
            }
            click.echo(json.dumps(payload, default=str))
            return

        if output_format == "csv":
            headers = [
                "normalized_title",
                "suggested_primary_id",
                "suggested_primary_reason",
                "group_last_activity_at",
                "task_id",
                "title",
                "status",
                "priority",
                "last_activity_at",
                "project_id",
                "project_name",
            ]
            click.echo(_csv_row(headers))
            for group in result.items:
                for task_obj in group.tasks:
                    row = [
                        group.normalized_title,
                        group.suggested_primary_id or "",
                        group.suggested_primary_reason or "",
                        _to_iso(group_last_activity(group)) or "",
                        task_obj.id,
                        task_obj.title,
                        task_obj.status.value,
                        task_obj.priority.value,
                        _to_iso(activity_map.get(task_obj.id)) or "",
                        task_obj.project_id,
                        project_names.get(task_obj.project_id) or "",
                    ]
                    click.echo(_csv_row(row))
            return

        table = Table(title="Duplicate Tasks")
        table.add_column("Normalized Title", style="cyan")
        table.add_column("Count", justify="right")
        table.add_column("Projects")
        table.add_column("Suggested", style="green")
        table.add_column("Reason")
        table.add_column("Activity")
        table.add_column("Task IDs", style="dim")

        for group in result.items:
            ids_preview = ", ".join([task.id[:8] for task in group.tasks[:5]])
            if len(group.tasks) > 5:
                ids_preview = f"{ids_preview}..."
            suggested = group.suggested_primary_id
            table.add_row(
                group.normalized_title,
                str(group.count),
                _truncate(group_projects(group), 24),
                suggested[:8] if suggested else "-",
                _truncate(group.suggested_primary_reason or "-", 26),
                format_relative(group_last_activity(group)),
                ids_preview,
            )

        console.print(table)
        console.print(f"[dim]Total groups: {result.total_count}[/dim]")
        if not project_id and suppressed_hidden_count:
            console.print(
                f"[dim]Suppressed hidden tasks: {suppressed_hidden_count} "
                f"(use --include-generated to show retained audit/history tasks)[/dim]"
            )
        if no_actionable_work:
            console.print(f"[dim]{scope_summary}[/dim]")
        _print_next_steps(*next_steps)
    finally:
        await db.disconnect()


@task.command("merge-duplicates")
@click.argument("primary_task_id")
@click.option(
    "--duplicate-id",
    "duplicate_ids",
    multiple=True,
    required=True,
    help="Duplicate task ID (repeatable)",
)
@click.option(
    "--cancel-duplicates/--keep-duplicates",
    default=True,
    show_default=True,
    help="Cancel duplicates after linking",
)
@async_command
async def task_merge_duplicates(
    primary_task_id: str,
    duplicate_ids: tuple[str, ...],
    cancel_duplicates: bool,
) -> None:
    """Merge duplicate tasks by linking to a primary task."""
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.services.task_service import TaskService

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        task_service = TaskService(db, event_store, revision_store, metrics)

        result = await task_service.merge_duplicate_tasks(
            primary_task_id=primary_task_id,
            duplicate_task_ids=list(duplicate_ids),
            cancel_duplicates=cancel_duplicates,
        )

        if result is None:
            console.print(f"[red]Task '{primary_task_id}' not found[/red]")
            return

        console.print(f"[bold]Primary:[/bold] {result.primary_task.title}")
        console.print(f"Links added: {result.links_added}")
        console.print(f"Duplicates cancelled: {result.duplicates_cancelled}")

        if result.duplicate_tasks:
            console.print("[bold]Duplicates:[/bold]")
            for task_obj in result.duplicate_tasks:
                console.print(
                    f"- {task_obj.title} ({task_obj.status.value}) {task_obj.id}"
                )
    finally:
        await db.disconnect()


@task.command("merge-preview")
@click.argument("primary_task_id")
@click.option(
    "--duplicate-id",
    "duplicate_ids",
    multiple=True,
    required=True,
    help="Duplicate task ID (repeatable)",
)
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json"]),
    default="text",
    show_default=True,
)
@async_command
async def task_merge_preview(
    primary_task_id: str,
    duplicate_ids: tuple[str, ...],
    output_format: str,
) -> None:
    """Preview duplicate task merge conflicts and warnings."""
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.services.task_service import TaskService

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        task_service = TaskService(db, event_store, revision_store, metrics)

        preview = await task_service.preview_merge_duplicate_tasks(
            primary_task_id=primary_task_id,
            duplicate_task_ids=list(duplicate_ids),
        )

        if preview is None:
            console.print(f"[red]Task '{primary_task_id}' not found[/red]")
            return

        duplicate_args = " ".join(
            [f"--duplicate-id {dup_id}" for dup_id in duplicate_ids]
        )
        merge_apply_command = (
            f"pms task merge-duplicates {primary_task_id} {duplicate_args}"
        )
        merge_preview_command = (
            f"pms task merge-preview {primary_task_id} {duplicate_args} --format json"
        )
        next_steps = _normalize_next_steps(
            merge_apply_command,
            f"pms task show {primary_task_id}",
            "pms task duplicates --format json",
            "pms dashboard --format json",
            "pms start --format json",
        )

        match output_format:
            case "json":
                payload = preview.to_dict()
                payload["links"] = _normalize_command_links(
                    {
                        "self": merge_preview_command,
                        "primary_task": f"task show {primary_task_id}",
                        "merge_apply": merge_apply_command,
                        "duplicates": "task duplicates --format json",
                        "dashboard": "dashboard --format json",
                        "guide": "start --format json",
                    }
                )
                payload["next_steps"] = next_steps
                click.echo(json.dumps(payload, indent=2, default=str))
            case _:
                console.print(
                    f"[bold]Primary:[/bold] {preview.primary_task.title} ({preview.primary_task.id})"
                )

                if preview.suggested_primary_id and (
                    preview.suggested_primary_id != preview.primary_task.id
                ):
                    console.print(
                        "[yellow]Suggested primary:[/yellow] "
                        f"{preview.suggested_primary_id} ({preview.suggested_primary_reason})"
                    )

                if preview.warnings:
                    console.print("[bold]Warnings:[/bold]")
                    for warning in preview.warnings:
                        console.print(f"- {warning}")

                if preview.missing_ids:
                    console.print("[bold]Missing IDs:[/bold]")
                    for missing_id in preview.missing_ids:
                        console.print(f"- {missing_id}")

                if preview.duplicates:
                    console.print("[bold]Duplicates:[/bold]")
                    for item in preview.duplicates:
                        flags = "linked" if item.already_linked else "unlinked"
                        console.print(
                            f"- {item.task.title} ({item.task.status.value}) {item.task.id} [{flags}]"
                        )
                        for conflict in item.conflicts:
                            console.print(
                                f"  * {conflict.field}: "
                                f"{conflict.primary_value} != {conflict.duplicate_value}"
                            )
                _print_next_steps(*next_steps)
    finally:
        await db.disconnect()


@task.command("show")
@click.argument("task_ref")
@click.option(
    "--project",
    "project_ref",
    help="Project name or ID (required for title-based lookup)",
)
@click.option(
    "--pick",
    is_flag=True,
    help="Pick from matching tasks when title is ambiguous",
)
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json", "csv"]),
    default="text",
    show_default=True,
)
@click.option(
    "--view",
    type=click.Choice(["overview", "detail", "trace"]),
    default="detail",
    show_default=True,
    help="Output view profile (overview/detail/trace)",
)
@click.option(
    "--include-history",
    is_flag=True,
    help="Include task history in JSON output",
)
@click.option(
    "--include-linked",
    is_flag=True,
    help="Include linked items in JSON output",
)
@click.option(
    "--include-linked-history",
    is_flag=True,
    help="Include history for linked items in JSON output",
)
@click.option("--history-limit", type=int, default=50, show_default=True)
@click.option("--linked-limit", type=int, default=20, show_default=True)
@async_command
async def task_show(
    task_ref: str,
    project_ref: str | None,
    pick: bool,
    output_format: str,
    view: str,
    include_history: bool,
    include_linked: bool,
    include_linked_history: bool,
    history_limit: int,
    linked_limit: int,
) -> None:
    """Show task details."""
    from pms.core import EventStore, MetricsCollector, RevisionStore
    from pms.db.connection import init_database
    from pms.models.progress_update import ProgressQuery
    from pms.models.state_transition import StateTransitionQuery
    from pms.models.workflow_state import get_workflow_by_id, get_workflow_registry
    from pms.repositories import (
        LabelAssignmentRepository,
        LabelRepository,
        PlanRepository,
        ProjectRepository,
        TaskEvidenceRepository,
        TaskRepository,
    )
    from pms.repositories.progress_repository import ProgressRepository
    from pms.repositories.state_transition_repository import StateTransitionRepository
    from pms.services.actor_service import ActorService
    from pms.services.project_service import ProjectService
    from pms.services.task_service import TaskService
    from pms.utils.time import format_relative

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        task_repo = TaskRepository(db, event_store, revision_store, metrics)
        task_service = TaskService(db, event_store, revision_store, metrics)
        actor_service = ActorService(db, event_store, revision_store, metrics)
        project_service = ProjectService(db, event_store, revision_store, metrics)
        project_repo = ProjectRepository(db, event_store, revision_store, metrics)
        plan_repo = PlanRepository(db, event_store, revision_store, metrics)
        label_repo = LabelRepository(db)
        assignment_repo = LabelAssignmentRepository(db)
        progress_repo = ProgressRepository(db)
        evidence_repo = TaskEvidenceRepository(db)
        task_id = await _resolve_task_id(
            task_ref, project_ref, task_service, project_service, pick=pick
        )
        if task_id is None:
            return

        task = await task_repo.get_by_id(task_id)

        if task is None:
            console.print(f"[red]Task '{task_id}' not found[/red]")
            return

        task_context = await task_service.get_task_with_context(task.id)

        if view == "trace":
            include_history = True
            include_linked = True
        if include_linked_history:
            include_linked = True
            include_history = True

        last_activity = await task_service.get_last_activity(task_id)
        last_transition = await task_service.get_last_transition(
            task_id, kind="workflow"
        )
        if last_transition is None:
            last_transition = await task_service.get_last_transition(
                task_id, kind="status"
            )

        if output_format == "csv":
            headers = [
                "id",
                "title",
                "status",
                "priority",
                "complexity_points",
                "current_progress_percent",
                "project_id",
                "description",
                "last_activity_at",
                "last_transition_at",
            ]
            click.echo(_csv_row(headers))
            row = [
                task.id,
                task.title,
                task.status.value,
                task.priority.value,
                str(task.complexity_points or ""),
                str(task.current_progress_percent),
                task.project_id,
                task.description or "",
                _to_iso(last_activity) or "",
                _to_iso(last_transition) or "",
            ]
            click.echo(_csv_row(row))
            return

        project_name = None
        project = None
        if task.project_id:
            project = await project_repo.get_by_id(task.project_id)
            project_name = project.name if project else None
        assignee_map = await _resolve_assignee_map([task], actor_service)
        checkout_actor_map = await _resolve_checkout_actor_map([task], actor_service)
        assignee_actor = _task_assignee_actor(task, assignee_map)
        checkout_actor = _task_checkout_actor(task, checkout_actor_map)

        context_task_ids: list[str] = []
        if task.parent_id:
            context_task_ids.append(task.parent_id)
        if task_context is not None:
            context_task_ids.extend(subtask.id for subtask in task_context.subtasks)
        context_tasks = await _tasks_with_latest_progress(
            db,
            task_repo,
            list(dict.fromkeys(context_task_ids)),
        )
        context_task_lookup = {task_obj.id: task_obj for task_obj in context_tasks}
        parent_task = (
            context_task_lookup.get(task.parent_id) if task.parent_id else None
        )
        subtask_models = [
            context_task_lookup.get(subtask.id, subtask)
            for subtask in (task_context.subtasks if task_context is not None else [])
        ]
        context_assignee_map = await _resolve_assignee_map(
            [
                task_obj
                for task_obj in [parent_task, *subtask_models]
                if task_obj is not None
            ],
            actor_service,
        )
        context_checkout_actor_map = await _resolve_checkout_actor_map(
            [
                task_obj
                for task_obj in [parent_task, *subtask_models]
                if task_obj is not None
            ],
            actor_service,
        )
        project_label = project_name or task.project_id
        task_label, project_clause = _task_ref_with_project(task.title, project_label)
        task_next_steps = _normalize_next_steps(
            f"pms plan list --task-id {task.id} --format json",
            (
                f"pms project show {task.project_id} --format json"
                if task.project_id
                else ""
            ),
            f"pms task tree --project {task.project_id} --root-task-id {task.id} --format json"
            if task.project_id
            else "",
            f"pms task show {task.parent_id}" if task.parent_id else "",
            f"pms task timeline {task_label}{project_clause}",
            f"pms task progress {task_label}{project_clause} <percent> <message> --by <user>",
            f"pms task evidence list {task_label}{project_clause}",
            (
                f"pms actor show {assignee_actor.handle}"
                if assignee_actor is not None
                else ""
            ),
        )

        workflow_summary = None
        workflow = None
        available_transitions: list[str] = []
        if task.workflow_id:
            workflow = get_workflow_by_id(task.workflow_id)
            workflow_key = None
            if workflow:
                for key, wf in get_workflow_registry().items():
                    if wf.id == workflow.id:
                        workflow_key = key
                        break
            if workflow:
                name = workflow.name
                if workflow_key:
                    name = f"{workflow_key} ({workflow.name})"
                workflow_summary = f"{name} @ {task.current_state}"
                available_transitions = _collect_workflow_transitions(
                    workflow, task.current_state
                )
            else:
                workflow_summary = f"{task.workflow_id} @ {task.current_state}"

        label_names: list[str] = []
        label_items = []
        assignments = await assignment_repo.list_for_entity("task", task.id)
        for assignment in assignments:
            label = await label_repo.get_by_id(assignment.label_id)
            if label:
                label_names.append(label.name)
                label_items.append(label.to_dict())

        evidence_count = 0
        evidence_result = await evidence_repo.list_by_task(task.id, limit=1)
        evidence_count = evidence_result.total_count
        last_progress = None
        progress_updates = await progress_repo.get_updates(
            ProgressQuery(task_id=task.id, limit=1)
        )
        if progress_updates:
            last_progress = progress_updates[0]

        def _task_linked_plan_links(plan_obj) -> dict[str, str]:
            return _normalize_command_links(
                _plan_followup_commands(
                    plan_obj.id,
                    plan_obj.name,
                    project_name,
                )[0]
            )

        def _task_context_summary(task_obj: Any) -> dict[str, Any]:
            project_label = (
                project_name if task_obj.project_id == task.project_id else None
            )
            return {
                "id": task_obj.id,
                "title": task_obj.title,
                "status": task_obj.status.value,
                "priority": task_obj.priority.value,
                "project_id": task_obj.project_id,
                "project_name": project_label,
                "parent_id": task_obj.parent_id,
                "milestone_id": task_obj.milestone_id,
                "current_progress_percent": task_obj.current_progress_percent,
                "updated_at": _to_iso(task_obj.updated_at),
                "assignee": _task_assignee_payload(
                    task_obj,
                    context_assignee_map,
                ),
                "checkout": _task_checkout_payload(
                    task_obj,
                    context_checkout_actor_map,
                ),
                "links": _normalize_command_links(
                    {
                        "self": f"task show {task_obj.id}",
                        "project": (
                            f"project show {task_obj.project_id} --format json"
                            if task_obj.project_id
                            else None
                        ),
                        "timeline": f"task timeline {task_obj.id}",
                        "graph": f"task graph {task_obj.id}",
                        "actor": _task_assignee_actor_link(
                            task_obj,
                            context_assignee_map,
                        ),
                        "checkout_actor": _task_checkout_actor_link(
                            task_obj,
                            context_checkout_actor_map,
                        ),
                    }
                ),
            }

        context_payload = {
            "project": (
                {
                    "id": task.project_id,
                    "name": project_name,
                    "links": _normalize_command_links(
                        {
                            "self": (
                                f"project show {task.project_id} --format json"
                                if task.project_id
                                else None
                            ),
                            "summary": (
                                f"project summary {task.project_id} --format json"
                                if task.project_id
                                else None
                            ),
                            "tasks": (
                                f"task list --project {task.project_id} --format json"
                                if task.project_id
                                else None
                            ),
                            "plans": (
                                f"plan list --project-id {task.project_id} --format json"
                                if task.project_id
                                else None
                            ),
                        }
                    ),
                }
                if task.project_id
                else None
            ),
            "milestone": (
                {
                    "id": task.milestone_id,
                    "name": task_context.milestone_name
                    if task_context is not None
                    else None,
                }
                if task.milestone_id
                else None
            ),
            "parent": _task_context_summary(parent_task)
            if parent_task is not None
            else None,
            "subtasks": [_task_context_summary(subtask) for subtask in subtask_models],
            "subtask_count": len(subtask_models),
            "dependency_count": (
                task_context.blocked_by_count if task_context is not None else 0
            ),
            "dependent_count": (
                task_context.blocking_count if task_context is not None else 0
            ),
        }

        if output_format == "json":
            effective_history_limit = history_limit if history_limit > 0 else 1000
            effective_linked_limit = linked_limit if linked_limit > 0 else 1000
            completion_criteria = _completion_criteria(task)
            links = _normalize_command_links(
                {
                    "self": f"task show {task.id}",
                    "project": (
                        f"project show {task.project_id} --format json"
                        if task.project_id
                        else None
                    ),
                    "parent": f"task show {task.parent_id}" if task.parent_id else None,
                    "subtasks": (
                        f"task tree --project {task.project_id} --root-task-id {task.id} --format json"
                        if task.project_id
                        else None
                    ),
                    "timeline": f"task timeline {task.id}",
                    "graph": f"task graph {task.id}",
                    "evidence": f"task evidence list {task.id}",
                    "progress": f"task progress {task.id} <percent> <message> --by <id>",
                    "plans": f"plan list --task-id {task.id} --format json",
                    "actor": _task_assignee_actor_link(task, assignee_map),
                    "checkout_actor": _task_checkout_actor_link(
                        task, checkout_actor_map
                    ),
                }
            )
            assignee_payload = _task_assignee_payload(task, assignee_map)
            checkout_payload = _task_checkout_payload(task, checkout_actor_map)
            linked_plans = await plan_repo.list_by_task_id(task.id)

            payload: dict[str, Any]
            if view == "overview":
                payload = {
                    "id": task.id,
                    "title": task.title,
                    "status": task.status.value,
                    "priority": task.priority.value,
                    "project_id": task.project_id,
                    "project_name": project_name,
                    "assignee": assignee_payload,
                    "checkout": checkout_payload,
                    "linked_plan_count": len(linked_plans),
                    "updated_at": task.updated_at,
                    "last_activity_at": _to_iso(last_activity),
                    "last_transition_at": _to_iso(last_transition),
                    "context": context_payload,
                    "links": links,
                }
            else:
                payload = _public_task_payload(
                    task,
                    assignee_map=assignee_map,
                    checkout_actor_map=checkout_actor_map,
                )
                payload.update(
                    {
                        "project_name": project_name,
                        "last_activity_at": _to_iso(last_activity),
                        "last_transition_at": _to_iso(last_transition),
                        "workflow_summary": workflow_summary,
                        "available_transitions": available_transitions,
                        "labels": label_items,
                        "evidence_count": evidence_count,
                        "completion_criteria": completion_criteria,
                        "completion_ready": (
                            task.status.value in {"in_review", "done"}
                            and bool(completion_criteria)
                        ),
                        "context": context_payload,
                        "progress": {
                            "current_percent": task.current_progress_percent,
                            "last_update": _reconciled_progress_last_update(
                                task,
                                last_progress.to_dict() if last_progress else None,
                            ),
                            "last_updated_at": _to_iso(task.last_progress_update_at),
                        },
                        "assignee": assignee_payload,
                        "checkout": checkout_payload,
                        "linked_plan_count": len(linked_plans),
                        "linked_plans": [
                            {
                                "id": plan.id,
                                "name": plan.name,
                                "status": plan.status.value,
                                "project_id": plan.project_id,
                                "goal_id": plan.goal_id,
                                "objective_id": plan.objective_id,
                                "updated_at": _to_iso(plan.updated_at),
                                "links": _task_linked_plan_links(plan),
                            }
                            for plan in linked_plans
                        ],
                        "links": links,
                    }
                )
                payload["links"] = {
                    **payload["links"],
                    "plans": _cli_command(
                        f"plan list --task-id {task.id} --format json"
                    ),
                }

            if include_linked:
                dependencies = await task_repo.get_dependencies(task.id)
                dependents = await task_repo.get_dependents(task.id)
                dependency_ids = [
                    dep.depends_on_id for dep in dependencies[:effective_linked_limit]
                ]
                dependent_ids = [
                    dep.task_id for dep in dependents[:effective_linked_limit]
                ]
                linked_ids = list(dict.fromkeys(dependency_ids + dependent_ids))
                linked_tasks = (
                    await task_repo.get_by_ids(linked_ids) if linked_ids else []
                )
                linked_map = {task_obj.id: task_obj for task_obj in linked_tasks}
                linked_assignee_map = await _resolve_assignee_map(
                    linked_tasks,
                    actor_service,
                )
                linked_checkout_actor_map = await _resolve_checkout_actor_map(
                    linked_tasks,
                    actor_service,
                )

                project_names: dict[str, str | None] = {}
                if task.project_id:
                    project_names[task.project_id] = project_name
                for task_obj in linked_tasks:
                    if task_obj.project_id and task_obj.project_id not in project_names:
                        project = await project_repo.get_by_id(task_obj.project_id)
                        project_names[task_obj.project_id] = (
                            project.name if project else None
                        )

                activity_map = await task_service.get_last_activity_map(linked_ids)
                workflow_map = await task_service.get_last_transition_map(
                    linked_ids, kind="workflow"
                )
                status_map = await task_service.get_last_transition_map(
                    linked_ids, kind="status"
                )

                def _linked_summary(task_obj) -> dict[str, Any]:
                    last_linked_transition = (
                        workflow_map.get(task_obj.id)
                        if task_obj.workflow_id
                        else status_map.get(task_obj.id)
                    )
                    return {
                        "id": task_obj.id,
                        "title": task_obj.title,
                        "status": task_obj.status.value,
                        "priority": task_obj.priority.value,
                        "project_id": task_obj.project_id,
                        "project_name": project_names.get(task_obj.project_id),
                        "current_progress_percent": task_obj.current_progress_percent,
                        "updated_at": task_obj.updated_at,
                        "last_activity_at": _to_iso(activity_map.get(task_obj.id)),
                        "last_transition_at": _to_iso(last_linked_transition),
                        "assignee": _task_assignee_payload(
                            task_obj,
                            linked_assignee_map,
                        ),
                        "checkout": _task_checkout_payload(
                            task_obj,
                            linked_checkout_actor_map,
                        ),
                        "links": _normalize_command_links(
                            {
                                "self": f"task show {task_obj.id}",
                                "project": (
                                    f"project show {task_obj.project_id} --format json"
                                    if task_obj.project_id
                                    else None
                                ),
                                "timeline": f"task timeline {task_obj.id}",
                                "graph": f"task graph {task_obj.id}",
                                "actor": _task_assignee_actor_link(
                                    task_obj,
                                    linked_assignee_map,
                                ),
                                "checkout_actor": _task_checkout_actor_link(
                                    task_obj,
                                    linked_checkout_actor_map,
                                ),
                            }
                        ),
                    }

                payload["linked"] = {
                    "project": context_payload["project"],
                    "milestone": context_payload["milestone"],
                    "parent": context_payload["parent"],
                    "subtasks": context_payload["subtasks"],
                    "plans": [
                        {
                            "id": plan.id,
                            "name": plan.name,
                            "status": plan.status.value,
                            "project_id": plan.project_id,
                            "goal_id": plan.goal_id,
                            "objective_id": plan.objective_id,
                            "updated_at": _to_iso(plan.updated_at),
                            "links": _task_linked_plan_links(plan),
                        }
                        for plan in linked_plans[:effective_linked_limit]
                    ],
                    "dependencies": [
                        _linked_summary(linked_map[dep_id])
                        for dep_id in dependency_ids
                        if dep_id in linked_map
                    ],
                    "dependents": [
                        _linked_summary(linked_map[dep_id])
                        for dep_id in dependent_ids
                        if dep_id in linked_map
                    ],
                    "labels": label_items,
                }

                if include_linked_history and linked_ids:
                    state_repo = StateTransitionRepository(db)

                    async def _history_for(
                        linked_id: str,
                    ) -> dict[str, Any]:
                        progress_updates = await progress_repo.get_updates(
                            ProgressQuery(
                                task_id=linked_id, limit=effective_history_limit
                            )
                        )
                        workflow_transitions = await state_repo.get_transitions(
                            StateTransitionQuery(
                                entity_type="task_workflow",
                                entity_id=linked_id,
                                limit=effective_history_limit,
                            )
                        )
                        status_transitions = await state_repo.get_transitions(
                            StateTransitionQuery(
                                entity_type="task_status",
                                entity_id=linked_id,
                                limit=effective_history_limit,
                            )
                        )
                        evidence_result = await evidence_repo.list_by_task(
                            linked_id, limit=effective_history_limit
                        )
                        return {
                            "progress_updates": [
                                update.to_dict() for update in progress_updates
                            ],
                            "workflow_transitions": [
                                transition.to_dict()
                                for transition in workflow_transitions
                            ],
                            "status_transitions": [
                                transition.to_dict()
                                for transition in status_transitions
                            ],
                            "evidence": [
                                item.to_dict() for item in evidence_result.items
                            ],
                        }

                    payload["linked_history"] = {
                        dep_id: await _history_for(dep_id) for dep_id in linked_ids
                    }

            if include_history:
                state_repo = StateTransitionRepository(db)
                progress_updates = await progress_repo.get_updates(
                    ProgressQuery(task_id=task.id, limit=effective_history_limit)
                )
                workflow_transitions = await state_repo.get_transitions(
                    StateTransitionQuery(
                        entity_type="task_workflow",
                        entity_id=task.id,
                        limit=effective_history_limit,
                    )
                )
                status_transitions = await state_repo.get_transitions(
                    StateTransitionQuery(
                        entity_type="task_status",
                        entity_id=task.id,
                        limit=effective_history_limit,
                    )
                )
                evidence_result = await evidence_repo.list_by_task(
                    task.id, limit=effective_history_limit
                )
                payload["history"] = {
                    "progress_updates": [
                        update.to_dict() for update in progress_updates
                    ],
                    "workflow_transitions": [
                        transition.to_dict() for transition in workflow_transitions
                    ],
                    "status_transitions": [
                        transition.to_dict() for transition in status_transitions
                    ],
                    "evidence": [item.to_dict() for item in evidence_result.items],
                }

            payload = _payload_with_normalized_next_steps(payload, *task_next_steps)
            click.echo(json.dumps(payload, default=str))
            return

        if view == "overview":
            console.print(f"[bold cyan]{task.title}[/bold cyan]")
            console.print(f"ID: {task.id}")
            if project_name:
                console.print(f"Project: {project_name} ({task.project_id})")
            elif task.project_id:
                console.print(f"Project: {task.project_id}")
            console.print(f"Status: {task.status.value}")
            console.print(f"Priority: {task.priority.value}")
            console.print(f"Updated: {format_relative(task.updated_at)}")
            console.print(f"Last Activity: {format_relative(last_activity)}")
            if last_transition:
                console.print(f"Last Transition: {format_relative(last_transition)}")
            _print_next_steps(*task_next_steps)
            return

        console.print(f"[bold cyan]{task.title}[/bold cyan]")
        console.print(f"ID: {task.id}")
        if project_name:
            console.print(f"Project: {project_name} ({task.project_id})")
        elif task.project_id:
            console.print(f"Project: {task.project_id}")
        console.print(f"Created: {format_relative(task.created_at)}")
        console.print(f"Updated: {format_relative(task.updated_at)}")
        console.print(f"Last Activity: {format_relative(last_activity)}")
        if last_transition:
            console.print(f"Last Transition: {format_relative(last_transition)}")
        console.print(f"Status: {task.status.value}")
        if task.assignee:
            if assignee_actor is not None:
                console.print(
                    "Assigned: "
                    f"{task.assignee} -> {assignee_actor.name} "
                    f"({assignee_actor.handle}, {assignee_actor.kind.value})"
                )
            else:
                console.print(f"Assigned: {task.assignee}")
        if task.checkout_agent_session_id:
            if checkout_actor is not None:
                console.print(
                    "Checked Out: "
                    f"{task.checkout_agent_session_id} -> {checkout_actor.name} "
                    f"({checkout_actor.handle}, {checkout_actor.kind.value})"
                )
            else:
                console.print(f"Checked Out: {task.checkout_agent_session_id}")
        if workflow_summary:
            console.print(f"Workflow: {workflow_summary}")
        if available_transitions:
            console.print(
                "Transitions: "
                + ", ".join(available_transitions)
                + " (gates may apply)"
            )
        if task.workflow_id and task.current_state and workflow:
            workflow_terminal = task.current_state in workflow.terminal_states
            status_terminal = task.status.is_terminal
            if workflow_terminal != status_terminal:
                if workflow_terminal:
                    console.print(
                        f"[yellow]Note:[/yellow] Workflow is terminal ({task.current_state}) "
                        f"but status is {task.status.value}. Consider updating task status."
                    )
                else:
                    console.print(
                        f"[yellow]Note:[/yellow] Status is terminal ({task.status.value}) "
                        f"but workflow is {task.current_state}. Consider transitioning "
                        "the workflow or reopening the task."
                    )
        console.print(f"Priority: {task.priority.value}")
        if parent_task is not None:
            console.print(f"Parent: {parent_task.title} ({parent_task.id})")
        elif task.parent_id:
            console.print(f"Parent: {task.parent_id}")
        if context_payload["milestone"] is not None:
            console.print(
                "Milestone: "
                f"{context_payload['milestone']['name']} ({context_payload['milestone']['id']})"
            )
        if label_names:
            console.print(f"Labels: {', '.join(label_names)}")
        console.print(f"Evidence: {evidence_count}")
        if task_context is not None:
            console.print(
                "Graph: "
                f"{task_context.blocked_by_count} blocked-by | "
                f"{task_context.blocking_count} dependents | "
                f"{len(subtask_models)} subtasks"
            )
        console.print(f"Progress: {task.current_progress_percent}%")
        if last_progress:
            last_ts = format_relative(last_progress.timestamp)
            message = last_progress.status_message or "-"
            by = last_progress.updated_by or "unknown"
            console.print(f"Last Update: {last_ts} by {by} - {message}")
        if task.last_progress_update_at and (
            not last_progress or task.last_progress_update_at != last_progress.timestamp
        ):
            console.print(
                f"Progress Updated At: {format_relative(task.last_progress_update_at)}"
            )
        if task.description:
            console.print(f"Description: {task.description}")
        linked_plans = await plan_repo.list_by_task_id(task.id)
        if linked_plans:
            console.print("Linked Plans:")
            for plan in linked_plans[
                : linked_limit if linked_limit > 0 else len(linked_plans)
            ]:
                console.print(f"  - {plan.name} [{plan.status.value}] ({plan.id})")
        if subtask_models:
            console.print("Subtasks:")
            max_subtasks = linked_limit if linked_limit > 0 else len(subtask_models)
            for subtask in subtask_models[:max_subtasks]:
                console.print(
                    "  - "
                    f"{subtask.title} [{subtask.status.value}] "
                    f"({subtask.current_progress_percent}%) ({subtask.id})"
                )
        completion_criteria = _completion_criteria(task)
        if completion_criteria:
            console.print("Done When:")
            for criterion in completion_criteria:
                console.print(f"  - {criterion}")
        if task.actual_hours:
            console.print(f"Actual: {task.actual_hours}h")
        _print_next_steps(*task_next_steps)
    finally:
        await db.disconnect()


@task.command("resolve")
@click.argument("task_ref")
@click.option(
    "--project",
    "project_ref",
    help="Project name or ID (required for title-based lookup)",
)
@click.option(
    "--pick",
    is_flag=True,
    help="Pick from matching tasks when title is ambiguous",
)
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json"]),
    default="text",
    show_default=True,
)
@async_command
async def task_resolve(
    task_ref: str,
    project_ref: str | None,
    pick: bool,
    output_format: str,
) -> None:
    """Resolve a task reference to ID and project."""
    from pms.core import EventStore, MetricsCollector, RevisionStore
    from pms.db.connection import init_database
    from pms.services.project_service import ProjectService
    from pms.services.task_service import TaskService

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        task_service = TaskService(db, event_store, revision_store, metrics)
        project_service = ProjectService(db, event_store, revision_store, metrics)

        task_id = await _resolve_task_id(
            task_ref,
            project_ref,
            task_service,
            project_service,
            pick=pick,
        )
        if task_id is None:
            return

        task = await task_service.get_task(task_id)
        if task is None:
            console.print(f"[red]Task '{task_id}' not found[/red]")
            return

        project_name = None
        if task.project_id:
            project = await project_service.get_project(task.project_id)
            project_name = project.name if project else None

        match output_format:
            case "json":
                payload = {
                    "id": task.id,
                    "title": task.title,
                    "project_id": task.project_id,
                    "project_name": project_name,
                    "status": task.status.value,
                    "updated_at": task.updated_at.isoformat(),
                }
                click.echo(json.dumps(payload, indent=2, default=str))
            case _:
                project_label = project_name or task.project_id or "-"
                lines = [
                    f"Task: {task.title}",
                    f"ID: {task.id}",
                    f"Project: {project_label}",
                    f"Status: {task.status.value}",
                    f"Updated: {format_relative(task.updated_at)}",
                ]
                console.print("\n".join(lines))
    finally:
        await db.disconnect()


@task.command("update")
@click.argument("task_ref")
@click.option(
    "--project",
    "project_ref",
    help="Project name or ID (required for title-based lookup)",
)
@click.option(
    "--pick",
    is_flag=True,
    help="Pick from matching tasks when title is ambiguous",
)
@click.option("--title", help="New title")
@click.option("--description", help="New description")
@click.option("--parent-id", help="Parent task ID for subtasks")
@click.option("--clear-parent", is_flag=True, help="Remove parent task")
@click.option(
    "--assigned-to",
    "assignee",
    help="Task assignee actor handle, alias, id, or stored label",
)
@click.option(
    "--clear-assigned-to", "clear_assignee", is_flag=True, help="Remove task assignee"
)
@click.option("--priority", type=click.Choice(["low", "medium", "high", "critical"]))
@click.option("--complexity-points", type=int, help="Complexity points (1-100)")
@click.option(
    "--done-when",
    "completion_criteria",
    multiple=True,
    help="Completion criterion bullet; repeat for multiple criteria",
)
@click.option(
    "--clear-done-when",
    is_flag=True,
    help="Remove all structured completion criteria",
)
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json"]),
    default="text",
    show_default=True,
)
@async_command
async def task_update(
    task_ref: str,
    project_ref: str | None,
    pick: bool,
    title: str | None,
    description: str | None,
    parent_id: str | None,
    clear_parent: bool,
    assignee: str | None,
    clear_assignee: bool,
    priority: str | None,
    complexity_points: int | None,
    completion_criteria: tuple[str, ...],
    clear_done_when: bool,
    output_format: str,
) -> None:
    """Update task fields."""
    from pms.core import EventStore, MetricsCollector, RevisionStore
    from pms.db.connection import init_database
    from pms.models import Priority
    from pms.services.actor_service import ActorService
    from pms.services.project_service import ProjectService
    from pms.services.task_service import TaskService

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        actor_service = ActorService(db, event_store, revision_store, metrics)
        task_service = TaskService(db, event_store, revision_store, metrics)
        project_service = ProjectService(db, event_store, revision_store, metrics)

        task_id = await _resolve_task_id(
            task_ref,
            project_ref,
            task_service,
            project_service,
            pick=pick,
        )
        if task_id is None:
            return

        if clear_parent and parent_id:
            _emit_cli_error(
                "Use --parent-id or --clear-parent, not both",
                output_format="json" if output_format == "json" else "text",
            )
        if clear_done_when and completion_criteria:
            _emit_cli_error(
                "Use --done-when or --clear-done-when, not both",
                output_format="json" if output_format == "json" else "text",
            )
        if clear_assignee and assignee:
            _emit_cli_error(
                "Use --assigned-to or --clear-assigned-to, not both",
                output_format="json" if output_format == "json" else "text",
            )

        try:
            updated = await task_service.update_task(
                task_id=task_id,
                title=title,
                description=description,
                parent_id=parent_id,
                clear_parent=clear_parent,
                assignee=assignee,
                clear_assignee=clear_assignee,
                priority=Priority(priority) if priority else None,
                complexity_points=complexity_points,
                completion_criteria=list(completion_criteria) or None,
                clear_completion_criteria=clear_done_when,
            )
        except ValueError as exc:
            console.print(f"[red]{exc}[/red]")
            return

        project_name = None
        if updated.project_id:
            project = await project_service.get_project(updated.project_id)
            project_name = project.name if project else None
        task_label, project_clause = _task_ref_with_project(updated.title, project_name)
        next_steps = _normalize_next_steps(
            f"pms task show {task_label}{project_clause}",
            f"pms task timeline {task_label}{project_clause}",
            f"pms task progress {task_label}{project_clause} <percent> <message> --by <user>",
        )
        if output_format == "json":
            assignee_map = await _resolve_assignee_map(
                [updated],
                actor_service,
            )
            payload = {
                "task": _public_task_payload(
                    updated,
                    assignee_map=assignee_map,
                ),
                "links": _normalize_command_links(
                    {
                        "self": f"task show {updated.id}",
                        "timeline": f"task timeline {updated.id}",
                        "evidence": f"task evidence list {updated.id}",
                        "actor": _task_assignee_actor_link(
                            updated,
                            assignee_map,
                        ),
                    }
                ),
                "next_steps": next_steps,
            }
            click.echo(json.dumps(payload, default=str))
            return

        console.print(f"[green]Updated task: {updated.title}[/green]")
        _print_next_steps(*next_steps)
    finally:
        await db.disconnect()


@task.command("complete")
@click.argument("task_ref")
@click.option(
    "--project",
    "project_ref",
    help="Project name or ID (required for title-based lookup)",
)
@click.option(
    "--pick",
    is_flag=True,
    help="Pick from matching tasks when title is ambiguous",
)
@click.option("--actual-hours", type=float, help="Actual hours spent")
@click.option("--by", "updated_by", help="Updater identifier")
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json"]),
    default="text",
    show_default=True,
)
@click.option(
    "--align-workflow/--no-align-workflow",
    default=False,
    show_default=True,
    help="Align workflow to status after completion",
)
@click.option("--workflow-to", help="Target workflow state for alignment")
@click.option("--workflow-approved-by", help="Approver for workflow alignment")
@click.option("--workflow-reason", help="Reason for workflow alignment")
@async_command
async def task_complete_cmd(
    task_ref: str,
    project_ref: str | None,
    pick: bool,
    actual_hours: float | None,
    updated_by: str | None,
    output_format: str,
    align_workflow: bool,
    workflow_to: str | None,
    workflow_approved_by: str | None,
    workflow_reason: str | None,
) -> None:
    """Mark task as completed."""
    write_decision = _ensure_runtime_write_mode(
        "pms task complete",
        emit_messages=output_format != "json",
    )
    if write_decision is None:
        return

    from pms.core import EventStore, MetricsCollector, RevisionStore
    from pms.core.events import EventType
    from pms.db.connection import init_database
    from pms.models.workflow_state import get_workflow_by_id
    from pms.repositories import TaskRepository
    from pms.repositories.base import RepositoryContext
    from pms.services.plan_service import PlanService
    from pms.services.project_service import ProjectService
    from pms.services.task_service import TaskService

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        task_repo = TaskRepository(db, event_store, revision_store, metrics)
        task_service = TaskService(db, event_store, revision_store, metrics)
        plan_service = PlanService(db, event_store, revision_store, metrics)
        project_service = ProjectService(db, event_store, revision_store, metrics)
        if updated_by:
            task_service = task_service.with_context(user_id=updated_by)
            task_repo.with_context(RepositoryContext(user_id=updated_by))

        task_id = await _resolve_task_id(
            task_ref, project_ref, task_service, project_service, pick=pick
        )
        if task_id is None:
            return

        actor_id = updated_by
        completion_result = None
        server_newly_unblocked_payload: list[dict[str, Any]] = []
        messages: list[dict[str, str]] = []
        if write_decision.use_server:
            try:
                completion_response = await _delegate_task_complete_to_server(
                    task_id=task_id,
                    notes=None,
                    actor_id=actor_id,
                    actual_hours=actual_hours,
                )
                task = await task_service.get_task(task_id)
                completion_response = completion_response or {}
                server_newly_unblocked_payload = list(
                    completion_response.get("newly_unblocked", [])
                )
                newly_unblocked_tasks: list[Any] = []
            except httpx.HTTPStatusError as exc:
                (
                    recovered_task,
                    recovered_message,
                ) = await _recover_delegated_task_complete(
                    task_id=task_id,
                    task_service=task_service,
                )
                if recovered_task is not None:
                    task = recovered_task
                    if recovered_message:
                        messages.append(
                            {"level": "warning", "message": recovered_message}
                        )
                    newly_unblocked_tasks = []
                else:
                    detail = _http_status_error_detail(exc)
                    current_task = await task_service.get_task(task_id)
                    if (
                        exc.response is not None
                        and exc.response.status_code == 409
                        and current_task is not None
                        and current_task.status.value == "done"
                    ):
                        task = current_task
                        messages.append(
                            {
                                "level": "warning",
                                "message": (
                                    f"Server reported a completion conflict: {detail}. "
                                    "Current state is done."
                                ),
                            }
                        )
                        newly_unblocked_tasks = []
                    else:
                        _emit_cli_error(detail, output_format=output_format)
        else:
            completion_result = await _run_task_execution_operation(
                operation=lambda: task_service.complete_task_with_effects(
                    task_id,
                    actual_hours=actual_hours,
                ),
                task_id=task_id,
                task_service=task_service,
                project_service=project_service,
                plan_service=plan_service,
                output_format=output_format,
            )
            task = completion_result.task if completion_result else None
            newly_unblocked_tasks = (
                list(completion_result.newly_unblocked_tasks)
                if completion_result
                else []
            )

        if task is None:
            if not write_decision.use_server:
                return
            console.print(f"[red]Task '{task_id}' not found or completion failed[/red]")
            return

        alignment: dict[str, Any] | None = None

        def _record_message(level: str, message: str) -> None:
            if output_format == "json":
                messages.append({"level": level, "message": message})

        if output_format == "text":
            console.print(f"[green]✓ Completed: {task.title}[/green]")
        else:
            _record_message("info", f"Completed: {task.title}")

        if task.workflow_id and task.current_state and not align_workflow:
            workflow = get_workflow_by_id(task.workflow_id)
            if workflow and task.current_state not in workflow.terminal_states:
                transitions = _collect_workflow_transitions(
                    workflow, task.current_state
                )
                next_text = f" Next: {', '.join(transitions)}." if transitions else ""
                note_text = (
                    f"Workflow is still at {task.current_state}.{next_text} "
                    "Use `pms workflow align`, `pms workflow transition`, or "
                    "re-run with `--align-workflow`."
                )
                if output_format == "text":
                    console.print(f"[yellow]Note:[/yellow] {note_text}")
                else:
                    _record_message("warning", note_text)
                    alignment = {
                        "requested": False,
                        "status": "needs_alignment",
                        "workflow_id": task.workflow_id,
                        "current_state": task.current_state,
                        "terminal_states": list(workflow.terminal_states),
                        "next_transitions": transitions,
                    }

        if align_workflow:
            alignment = alignment or {
                "requested": True,
                "workflow_id": task.workflow_id,
                "current_state": task.current_state,
            }
            if not task.workflow_id or not task.current_state:
                message = "Skip: Task has no workflow to align."
                if output_format == "text":
                    console.print(
                        "[yellow]Skip:[/yellow] Task has no workflow to align."
                    )
                    return
                _record_message("warning", message)
                alignment.update({"status": "skipped", "reason": "no_workflow"})
            else:
                from pms.repositories import StateTransitionRepository
                from pms.services.evidence_gate_service import EvidenceGateService
                from pms.services.label_service import LabelService

                workflow = get_workflow_by_id(task.workflow_id)
                if workflow is None:
                    message = "Skip: Workflow not found."
                    if output_format == "text":
                        console.print("[yellow]Skip:[/yellow] Workflow not found.")
                        return
                    _record_message("warning", message)
                    alignment.update(
                        {"status": "skipped", "reason": "workflow_missing"}
                    )
                elif task.current_state in workflow.terminal_states:
                    message = "Workflow already aligned."
                    if output_format == "text":
                        console.print("[green]Workflow already aligned.[/green]")
                        return
                    _record_message("info", message)
                    alignment.update(
                        {
                            "status": "aligned",
                            "target_state": task.current_state,
                        }
                    )
                else:
                    target_state = workflow_to or _suggest_terminal_state(
                        task.status.value, workflow.terminal_states
                    )
                    if target_state is None:
                        terminals = ", ".join(workflow.terminal_states) or "none"
                        if output_format == "text":
                            console.print(
                                "[red]Workflow alignment requires a target state.[/red] "
                                "Provide --workflow-to."
                            )
                            console.print(f"[dim]Terminal states: {terminals}[/dim]")
                            return
                        _record_message(
                            "error",
                            "Workflow alignment requires a target state. Provide --workflow-to.",
                        )
                        alignment.update(
                            {
                                "status": "failed",
                                "reason": "missing_target",
                                "terminal_states": list(workflow.terminal_states),
                            }
                        )
                    else:
                        path = _find_workflow_path(
                            workflow, task.current_state, target_state
                        )
                        if path is None:
                            message = f"No workflow path from {task.current_state} to {target_state}"
                            if output_format == "text":
                                console.print(f"[red]{message}[/red]")
                                return
                            _record_message("error", message)
                            alignment.update(
                                {
                                    "status": "failed",
                                    "reason": "no_path",
                                    "from_state": task.current_state,
                                    "to_state": target_state,
                                }
                            )
                        else:
                            state_repo = StateTransitionRepository(db)
                            label_service = LabelService(db, metrics)
                            evidence_gate_service = EvidenceGateService(db, metrics)

                            reason = (
                                workflow_reason
                                or f"Align workflow to status {task.status.value}"
                            )
                            transitions_applied = 0
                            error_message = None
                            needs_approval_flag = False

                            for next_state in path[1:]:
                                (
                                    transition,
                                    error,
                                    needs_approval,
                                ) = await _execute_workflow_transition(
                                    entity=task,
                                    repo=task_repo,
                                    workflow=workflow,
                                    update_event=EventType.TASK_UPDATED,
                                    entity_type="task",
                                    to_state=next_state,
                                    triggered_by=updated_by or "cli",
                                    reason=reason,
                                    approved_by=workflow_approved_by,
                                    state_repo=state_repo,
                                    label_service=label_service,
                                    evidence_gate_service=evidence_gate_service,
                                )
                                if error:
                                    error_message = error
                                    needs_approval_flag = bool(needs_approval)
                                    if output_format == "text":
                                        console.print(
                                            f"[red]Alignment stopped:[/red] {error}"
                                        )
                                        if needs_approval:
                                            console.print(
                                                "[yellow]Tip:[/yellow] Provide --workflow-approved-by <name>"
                                            )
                                    else:
                                        _record_message(
                                            "error", f"Alignment stopped: {error}"
                                        )
                                        if needs_approval:
                                            _record_message(
                                                "warning",
                                                "Provide --workflow-approved-by <name>.",
                                            )
                                    break
                                transitions_applied += 1

                            if transitions_applied == len(path) - 1:
                                message = f"Aligned workflow: {path[0]} -> {path[-1]}"
                                if output_format == "text":
                                    console.print(
                                        f"[green]Aligned workflow:[/green] {path[0]} -> {path[-1]}"
                                    )
                                else:
                                    _record_message("info", message)
                                alignment.update(
                                    {
                                        "status": "aligned",
                                        "target_state": target_state,
                                        "path": path,
                                        "transitions_applied": transitions_applied,
                                    }
                                )
                            else:
                                remaining = path[transitions_applied:]
                                if remaining:
                                    message = (
                                        f"Remaining path: {' -> '.join(remaining)}"
                                    )
                                    if output_format == "text":
                                        console.print(
                                            f"[yellow]Remaining path:[/yellow] {' -> '.join(remaining)}"
                                        )
                                    else:
                                        _record_message("warning", message)
                                alignment.update(
                                    {
                                        "status": "partial",
                                        "target_state": target_state,
                                        "path": path,
                                        "transitions_applied": transitions_applied,
                                        "remaining": remaining,
                                        "error": error_message,
                                        "needs_approval": needs_approval_flag,
                                    }
                                )

        project_name = None
        if task.project_id:
            project = await project_service.get_project(task.project_id)
            project_name = project.name if project else None
        links, next_steps = _task_followup_commands(
            task.id,
            task.title,
            project_name,
        )
        newly_unblocked_payload: list[dict[str, Any]] = list(
            server_newly_unblocked_payload
        )
        if not newly_unblocked_payload:
            for unblocked in newly_unblocked_tasks:
                unblocked_project_name = project_name
                if unblocked.project_id and unblocked.project_id != task.project_id:
                    unblocked_project = await project_service.get_project(
                        unblocked.project_id
                    )
                    unblocked_project_name = (
                        unblocked_project.name if unblocked_project else None
                    )
                unblocked_links, _ = _task_followup_commands(
                    unblocked.id,
                    unblocked.title,
                    unblocked_project_name,
                )
                task_target = _best_task_command_target(
                    unblocked.id,
                    unblocked.title,
                    unblocked_project_name,
                )
                start_command = _cli_command(f"task start {task_target}")
                show_command = _cli_command(f"task show {task_target}")
                newly_unblocked_payload.append(
                    {
                        "id": unblocked.id,
                        "title": unblocked.title,
                        "status": unblocked.status.value,
                        "project_id": unblocked.project_id,
                        "project_name": unblocked_project_name,
                        "links": unblocked_links,
                        "next_steps": _normalize_next_steps(
                            show_command, start_command
                        ),
                    }
                )
        if newly_unblocked_payload:
            unblocked_steps = [
                step
                for item in newly_unblocked_payload
                if (step := _primary_followup_step(item)) is not None
            ]
            next_steps = _normalize_next_steps(
                *unblocked_steps,
                *next_steps,
            )

        if output_format == "json":
            task_payload = _public_task_payload(task)
            task_payload.update(
                {
                    "status": task.status.value,
                    "priority": task.priority.value,
                    "project_name": project_name,
                    "tags": list(task.tags) if task.tags else [],
                }
            )
            payload = {
                "task": task_payload,
                "completion": {
                    "actual_hours": actual_hours,
                    "completed_at": _to_iso(task.completed_at),
                },
                "runtime_write": _runtime_write_context_payload(write_decision),
                "links": links,
                "next_steps": next_steps,
                "newly_unblocked": newly_unblocked_payload,
            }
            if messages:
                payload["messages"] = messages
            if alignment:
                payload["workflow_alignment"] = alignment
            click.echo(json.dumps(payload, default=str))
            return

        if newly_unblocked_payload:
            console.print("[green]Newly unblocked:[/green]")
            for item in newly_unblocked_payload:
                ref = str(item.get("id", ""))[:8]
                title = item.get("title") or "(unnamed task)"
                project_label = item.get("project_name")
                if project_label:
                    console.print(f"- {title} [{ref}] ({project_label})")
                else:
                    console.print(f"- {title} [{ref}]")

        _print_next_steps(*next_steps)
    finally:
        await db.disconnect()


@task.command("delete")
@click.argument("task_ref")
@click.option(
    "--project",
    "project_ref",
    help="Project name or ID (required for title-based lookup)",
)
@click.option(
    "--pick",
    is_flag=True,
    help="Pick from matching tasks when title is ambiguous",
)
@click.option("--reason", help="Cancellation reason")
@click.option("--by", "updated_by", help="Updater identifier")
@async_command
async def task_delete_cmd(
    task_ref: str,
    project_ref: str | None,
    pick: bool,
    reason: str | None,
    updated_by: str | None,
) -> None:
    """Delete (cancel) a task."""
    from pms.core import EventStore, MetricsCollector, RevisionStore
    from pms.db.connection import init_database
    from pms.repositories import TaskRepository
    from pms.services.project_service import ProjectService
    from pms.services.task_service import TaskService

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        task_repo = TaskRepository(db, event_store, revision_store, metrics)
        task_service = TaskService(db, event_store, revision_store, metrics)
        project_service = ProjectService(db, event_store, revision_store, metrics)
        if updated_by:
            task_service = task_service.with_context(user_id=updated_by)

        task_id = await _resolve_task_id(
            task_ref,
            project_ref,
            task_service,
            project_service,
            pick=pick,
        )
        if task_id is None:
            return

        task = await task_service.cancel_task(task_id, reason=reason)

        if task is None:
            console.print(
                f"[red]Task '{task_id}' not found or cancellation failed[/red]"
            )
            return

        console.print(f"[yellow]Deleted: {task.title}[/yellow]")
    finally:
        await db.disconnect()


@task.command("start")
@click.argument("task_ref")
@click.option(
    "--project",
    "project_ref",
    help="Project name or ID (required for title-based lookup)",
)
@click.option(
    "--pick",
    is_flag=True,
    help="Pick from matching tasks when title is ambiguous",
)
@click.option("--by", "updated_by", help="Updater identifier")
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json"]),
    default="text",
    show_default=True,
)
@async_command
async def task_start(
    task_ref: str,
    project_ref: str | None,
    pick: bool,
    updated_by: str | None,
    output_format: str,
) -> None:
    """Start a task (set to in_progress)."""
    write_decision = _ensure_runtime_write_mode(
        "pms task start",
        emit_messages=output_format != "json",
    )
    if write_decision is None:
        return

    from pms.core import EventStore, MetricsCollector, RevisionStore
    from pms.db.connection import init_database
    from pms.services.plan_service import PlanService
    from pms.services.project_service import ProjectService
    from pms.services.task_service import TaskService

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        service = TaskService(db, event_store, revision_store, metrics)
        plan_service = PlanService(db, event_store, revision_store, metrics)
        project_service = ProjectService(db, event_store, revision_store, metrics)
        if updated_by:
            service = service.with_context(user_id=updated_by)

        task_id = await _resolve_task_id(
            task_ref,
            project_ref,
            service,
            project_service,
            pick=pick,
        )
        if task_id is None:
            return

        actor_id = updated_by
        messages: list[dict[str, str]] = []
        if write_decision.use_server:
            try:
                await _delegate_task_start_to_server(
                    task_id=task_id,
                    actor_id=_resolve_cli_actor(actor_id),
                )
                task = await service.get_task(task_id)
            except httpx.HTTPStatusError as exc:
                recovered_task, recovered_message = await _recover_delegated_task_start(
                    task_id=task_id,
                    task_service=service,
                )
                if recovered_task is not None:
                    task = recovered_task
                    if recovered_message:
                        messages.append(
                            {"level": "warning", "message": recovered_message}
                        )
                else:
                    detail = _http_status_error_detail(exc)
                    current_task = await service.get_task(task_id)
                    if (
                        exc.response is not None
                        and exc.response.status_code == 409
                        and current_task is not None
                        and current_task.status.value in {"in_progress", "done"}
                    ):
                        task = current_task
                        messages.append(
                            {
                                "level": "warning",
                                "message": (
                                    f"Server reported a start conflict: {detail}. "
                                    f"Current state is {current_task.status.value}."
                                ),
                            }
                        )
                    else:
                        _emit_cli_error(detail, output_format=output_format)
        else:
            task = await _run_task_execution_operation(
                operation=lambda: service.start_task(task_id),
                task_id=task_id,
                task_service=service,
                project_service=project_service,
                plan_service=plan_service,
                output_format=output_format,
                draft_lock_exit_code=1 if project_ref else 0,
            )

        if task is None:
            if not write_decision.use_server:
                return

        project_name = None
        if task.project_id:
            project = await project_service.get_project(task.project_id)
            project_name = project.name if project else None

        task_label, project_clause = _task_ref_with_project(task.title, project_name)
        user_label = updated_by or "<user>"
        next_steps = _normalize_next_steps(
            f"pms task show {task_label}{project_clause}",
            f"pms task progress {task_label}{project_clause} <percent> <message> --by {user_label}",
            f"pms task review {task_label}{project_clause} --by {user_label}",
        )

        if output_format == "json":
            task_payload = _public_task_payload(task)
            task_payload.update(
                {
                    "status": task.status.value,
                    "priority": task.priority.value,
                    "project_name": project_name,
                    "tags": list(task.tags) if task.tags else [],
                }
            )
            payload = {
                "task": task_payload,
                "runtime_write": _runtime_write_context_payload(write_decision),
                "links": _normalize_command_links(
                    {
                        "self": f"pms task show {task.id}",
                        "timeline": f"pms task timeline {task.id}",
                        "progress": f"pms task progress {task.id} <percent> <message> --by <id>",
                    }
                ),
                "next_steps": next_steps,
            }
            if messages:
                payload["messages"] = messages
            click.echo(json.dumps(payload, default=str))
            return

        console.print(f"[green]Started:[/green] {task.title}")
        for item in messages:
            console.print(f"[yellow]{item['message']}[/yellow]")
        _print_next_steps(*next_steps)
    finally:
        await db.disconnect()


@task.command("block")
@click.argument("task_ref")
@click.option(
    "--project",
    "project_ref",
    help="Project name or ID (required for title-based lookup)",
)
@click.option(
    "--pick",
    is_flag=True,
    help="Pick from matching tasks when title is ambiguous",
)
@click.option("--reason", help="Block reason")
@click.option("--by", "updated_by", help="Updater identifier")
@async_command
async def task_block(
    task_ref: str,
    project_ref: str | None,
    pick: bool,
    reason: str | None,
    updated_by: str | None,
) -> None:
    """Block a task."""
    from pms.core import EventStore, MetricsCollector, RevisionStore
    from pms.db.connection import init_database
    from pms.services.plan_service import PlanService
    from pms.services.project_service import ProjectService
    from pms.services.task_service import TaskService

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        service = TaskService(db, event_store, revision_store, metrics)
        plan_service = PlanService(db, event_store, revision_store, metrics)
        project_service = ProjectService(db, event_store, revision_store, metrics)
        if updated_by:
            service = service.with_context(user_id=updated_by)

        task_id = await _resolve_task_id(
            task_ref,
            project_ref,
            service,
            project_service,
            pick=pick,
        )
        if task_id is None:
            return

        task = await _run_task_execution_operation(
            operation=lambda: service.block_task(task_id, reason=reason),
            task_id=task_id,
            task_service=service,
            project_service=project_service,
            plan_service=plan_service,
            output_format="text",
        )
        if task is None:
            console.print(f"[red]Task '{task_id}' not found[/red]")
            return

        console.print(f"[yellow]Blocked:[/yellow] {task.title}")
        project_name = None
        if task.project_id:
            project = await project_service.get_project(task.project_id)
            project_name = project.name if project else None
        task_label, project_clause = _task_ref_with_project(task.title, project_name)
        _print_next_steps(
            f"pms task show {task_label}{project_clause}",
            f"pms task unblock {task_label}{project_clause} --by {updated_by or '<user>'}",
        )
    finally:
        await db.disconnect()


