@task.command("proof-bundle")
@click.argument("task_id")
@click.option(
    "--include-output",
    is_flag=True,
    help="Include stdout/stderr for test runs",
)
@click.option("--include-logs", is_flag=True, help="Include test run logs")
@click.option("--include-artifacts", is_flag=True, help="Include test run artifacts")
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json"]),
    default="text",
    show_default=True,
)
@async_command
async def task_proof_bundle(
    task_id: str,
    include_output: bool,
    include_logs: bool,
    include_artifacts: bool,
    output_format: str,
) -> None:
    """Export a proof bundle for a task."""
    from pms.core import EventStore, MetricsCollector, RevisionStore
    from pms.db.connection import init_database
    from pms.services.proof_bundle_service import ProofBundleService
    from pms.services.task_evidence_service import TaskEvidenceService
    from pms.services.task_service import TaskService
    from pms.services.test_run_service import TestRunService

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        task_service = TaskService(db, event_store, revision_store, metrics)
        evidence_service = TaskEvidenceService(db, metrics)
        test_run_service = TestRunService(db, metrics)
        proof_bundle_service = ProofBundleService(
            task_service=task_service,
            evidence_service=evidence_service,
            test_run_service=test_run_service,
        )

        bundle = await proof_bundle_service.build_task_bundle(
            task_id=task_id,
            include_output=include_output,
            include_logs=include_logs,
            include_artifacts=include_artifacts,
        )
        if bundle is None:
            console.print(f"[red]Task '{task_id}' not found[/red]")
            return

        match output_format:
            case "json":
                click.echo(json.dumps(bundle.to_dict(), default=str))
            case _:
                from pms.utils.time import format_relative

                summary = bundle.summary
                console.print("[bold cyan]Proof Bundle[/bold cyan]")
                console.print(f"Task: {bundle.task.title} ({bundle.task.id})")
                console.print(f"Generated: {format_relative(bundle.generated_at)}")
                console.print(
                    "Evidence: "
                    f"{summary.evidence_total} total | "
                    f"types {summary.evidence_types}"
                )
                console.print(
                    "Test runs: "
                    f"{summary.successful_test_runs}/{summary.test_runs} successful"
                )
                console.print(f"Log bytes: {summary.log_bytes_total}")
                console.print(f"Artifact bytes: {summary.artifact_bytes_total}")

                if bundle.evidence:
                    evidence_table = Table(title="Evidence")
                    evidence_table.add_column("Type")
                    evidence_table.add_column("Reference", style="cyan")
                    evidence_table.add_column("Created By")
                    evidence_table.add_column("Created")
                    evidence_table.add_column("Details")
                    for item in bundle.evidence:
                        details = item.evidence.description or "-"
                        if item.evidence.evidence_type == "test_run" and item.test_run:
                            status = "passed" if item.test_run.success else "failed"
                            details = (
                                f"{status} ({item.test_run.command or 'test run'})"
                            )
                        evidence_table.add_row(
                            item.evidence.evidence_type,
                            item.evidence.reference,
                            item.evidence.created_by,
                            format_relative(item.evidence.created_at),
                            details,
                        )
                    console.print(evidence_table)

                if bundle.test_runs:
                    run_table = Table(title="Test Runs")
                    run_table.add_column("ID", style="cyan")
                    run_table.add_column("Status")
                    run_table.add_column("Duration")
                    run_table.add_column("Command")
                    for run in bundle.test_runs:
                        status = "passed" if run.success else "failed"
                        duration = (
                            f"{run.duration_seconds:.1f}s"
                            if run.duration_seconds is not None
                            else "-"
                        )
                        run_table.add_row(
                            run.id,
                            status,
                            duration,
                            run.command or "-",
                        )
                    console.print(run_table)
                _print_next_steps(
                    f"pms task evidence list {task_id}",
                    f"pms task proof-bundle-search --task-id {task_id}",
                )
    finally:
        await db.disconnect()


@task.command("proof-bundle-search")
@click.option(
    "--task-id",
    "task_ids",
    multiple=True,
    help="Filter by task ID (repeatable)",
)
@click.option("--plan-id", help="Filter by plan ID")
@click.option(
    "--status",
    "statuses",
    multiple=True,
    help="Filter by task status (repeatable)",
)
@click.option(
    "--evidence-type",
    "evidence_types",
    multiple=True,
    help="Filter by evidence type (repeatable)",
)
@click.option("--created-from", help="Filter evidence created after ISO timestamp")
@click.option("--created-to", help="Filter evidence created before ISO timestamp")
@click.option("--include-evidence", is_flag=True, help="Include evidence entries")
@click.option("--include-test-runs", is_flag=True, help="Include test run summaries")
@click.option("--include-output", is_flag=True, help="Include stdout/stderr")
@click.option("--include-logs", is_flag=True, help="Include test run logs")
@click.option("--include-artifacts", is_flag=True, help="Include test run artifacts")
@click.option("--limit", default=50, show_default=True)
@click.option("--offset", default=0, show_default=True)
@click.option(
    "--view",
    type=click.Choice(["overview", "detail", "trace"]),
    default="overview",
    show_default=True,
    help="Output detail profile",
)
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["table", "json", "csv"]),
    default="table",
    show_default=True,
)
@async_command
async def task_proof_bundle_search(
    task_ids: tuple[str, ...],
    plan_id: str | None,
    statuses: tuple[str, ...],
    evidence_types: tuple[str, ...],
    created_from: str | None,
    created_to: str | None,
    include_evidence: bool,
    include_test_runs: bool,
    include_output: bool,
    include_logs: bool,
    include_artifacts: bool,
    limit: int,
    offset: int,
    view: str,
    output_format: str,
) -> None:
    """Search proof bundles across tasks."""
    from datetime import datetime

    from pms.core import EventStore, MetricsCollector, RevisionStore
    from pms.db.connection import init_database
    from pms.models.enums import TaskStatus
    from pms.services.plan_service import PlanService
    from pms.services.proof_bundle_service import ProofBundleService
    from pms.services.task_evidence_service import TaskEvidenceService
    from pms.services.task_service import TaskService
    from pms.services.test_run_service import TestRunService
    from pms.utils.time import format_relative

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        task_service = TaskService(db, event_store, revision_store, metrics)
        plan_service = PlanService(db, event_store, revision_store, metrics)
        evidence_service = TaskEvidenceService(db, metrics)
        test_run_service = TestRunService(db, metrics)
        proof_bundle_service = ProofBundleService(
            task_service=task_service,
            evidence_service=evidence_service,
            test_run_service=test_run_service,
        )

        try:
            created_from_dt = (
                datetime.fromisoformat(created_from) if created_from else None
            )
        except ValueError:
            _emit_cli_error(
                "created-from must be ISO timestamp",
                output_format="json" if output_format == "json" else "text",
            )
        try:
            created_to_dt = datetime.fromisoformat(created_to) if created_to else None
        except ValueError:
            _emit_cli_error(
                "created-to must be ISO timestamp",
                output_format="json" if output_format == "json" else "text",
            )

        status_filters: list[TaskStatus] | None = None
        if statuses:
            status_filters = []
            for status in statuses:
                try:
                    status_filters.append(TaskStatus(status.lower()))
                except ValueError:
                    console.print(
                        "[red]Invalid status. Use todo, in_progress, blocked, in_review, done, cancelled[/red]"
                    )
                    return

        task_id_filters: list[str] | None = list(task_ids) if task_ids else None
        if plan_id:
            plan = await plan_service.get_plan(plan_id)
            if plan is None:
                console.print(f"[red]Plan '{plan_id}' not found[/red]")
                return
            plan_task_ids = list(plan.task_ids)
            if task_id_filters is None:
                task_id_filters = plan_task_ids
            else:
                task_id_filters = [
                    task_id for task_id in task_id_filters if task_id in plan_task_ids
                ]

        no_results = task_id_filters is not None and not task_id_filters

        match view:
            case "detail":
                include_evidence = True
                include_test_runs = True
            case "trace":
                include_evidence = True
                include_test_runs = True
                include_output = True
                include_logs = True
                include_artifacts = True

        if include_output:
            include_test_runs = True

        if no_results:
            results = ProofBundleService.SearchPage(
                items=[],
                total_count=0,
                offset=offset,
                limit=limit,
            )
        else:
            results = await proof_bundle_service.search_bundles(
                task_ids=task_id_filters,
                task_statuses=status_filters,
                evidence_types=list(evidence_types) if evidence_types else None,
                created_from=created_from_dt,
                created_to=created_to_dt,
                include_evidence=include_evidence,
                include_test_runs=include_test_runs,
                include_output=include_output,
                include_logs=include_logs,
                include_artifacts=include_artifacts,
                limit=limit,
                offset=offset,
            )

        if output_format == "json":
            items = []
            for item in results.items:
                entry = {
                    "task": _public_task_payload(item.task),
                    "summary": item.summary.to_dict(),
                    "last_evidence_at": item.last_evidence_at,
                }
                if include_evidence:
                    entry["evidence"] = [
                        {
                            "evidence": evidence_item.evidence.to_dict(),
                            "test_run": (
                                evidence_item.test_run.__dict__
                                if include_test_runs and evidence_item.test_run
                                else None
                            ),
                        }
                        for evidence_item in item.evidence
                    ]
                if include_output or include_logs or include_artifacts:
                    entry["test_runs"] = [
                        {
                            "id": run.id,
                            "server_id": run.server_id,
                            "project_id": run.project_id,
                            "success": run.success,
                            "exit_code": run.exit_code,
                            "duration_seconds": run.duration_seconds,
                            "started_at": run.started_at,
                            "finished_at": run.finished_at,
                            "command": run.command,
                            "runner": run.runner,
                            "plan_id": run.plan_id,
                            "task_ids": list(run.task_ids),
                            "stdout": run.stdout,
                            "stderr": run.stderr,
                            "logs": run.logs or None,
                            "artifacts": run.artifacts or None,
                        }
                        for run in item.test_runs
                    ]
                items.append(entry)

            base_cmd = "pms task proof-bundle-search --format json"
            if task_id_filters:
                for task_id in task_id_filters:
                    base_cmd += f" --task-id {task_id}"
            if plan_id:
                base_cmd += f" --plan-id {plan_id}"
            if status_filters:
                for status in status_filters:
                    base_cmd += f" --status {status.value}"
            if evidence_types:
                for evidence_type in evidence_types:
                    base_cmd += f" --evidence-type {evidence_type}"
            if created_from:
                base_cmd += f" --created-from {created_from}"
            if created_to:
                base_cmd += f" --created-to {created_to}"
            if include_evidence:
                base_cmd += " --include-evidence"
            if include_test_runs:
                base_cmd += " --include-test-runs"
            if include_output:
                base_cmd += " --include-output"
            if include_logs:
                base_cmd += " --include-logs"
            if include_artifacts:
                base_cmd += " --include-artifacts"
            if view != "overview":
                base_cmd += f" --view {view}"
            payload = {
                "items": items,
                "page": _page_payload(
                    results.total_count, results.limit, results.offset
                ),
                "links": _normalize_command_links(
                    {
                        "self": f"{base_cmd} --limit {limit} --offset {offset}",
                        "next": (
                            f"{base_cmd} --limit {limit} --offset {offset + limit}"
                            if limit > 0 and offset + limit < results.total_count
                            else None
                        ),
                    }
                ),
            }
            click.echo(json.dumps(payload, default=str))
            return

        if output_format == "csv":
            headers = [
                "task_id",
                "task_title",
                "status",
                "evidence_total",
                "test_runs",
                "successful_test_runs",
                "log_bytes_total",
                "artifact_bytes_total",
                "last_evidence_at",
            ]
            click.echo(_csv_row(headers))
            for item in results.items:
                row = [
                    item.task.id,
                    item.task.title,
                    item.task.status.value,
                    str(item.summary.evidence_total),
                    str(item.summary.test_runs),
                    str(item.summary.successful_test_runs),
                    str(item.summary.log_bytes_total),
                    str(item.summary.artifact_bytes_total),
                    _to_iso(item.last_evidence_at) or "",
                ]
                click.echo(_csv_row(row))
            return

        table = Table(title="Proof Bundle Search")
        table.add_column("Task")
        table.add_column("Status")
        table.add_column("Evidence")
        table.add_column("Tests")
        table.add_column("Logs")
        table.add_column("Artifacts")
        table.add_column("Last Evidence")

        for item in results.items:
            summary = item.summary
            table.add_row(
                item.task.title,
                item.task.status.value,
                str(summary.evidence_total),
                f"{summary.successful_test_runs}/{summary.test_runs}",
                str(summary.log_bytes_total),
                str(summary.artifact_bytes_total),
                format_relative(item.last_evidence_at),
            )
        console.print(table)
        console.print(f"[dim]Total: {results.total_count}[/dim]")
        next_steps = ["pms task proof-bundle-search --format json"]
        if results.items:
            next_steps.append(f"pms task proof-bundle {results.items[0].task.id}")
        _print_next_steps(*next_steps)
    finally:
        await db.disconnect()


@task.group("evidence")
def task_evidence() -> None:
    """Manage task evidence."""
    pass


@task_evidence.command("add")
@click.argument("task_ref")
@click.argument("evidence_type")
@click.argument("reference")
@click.option(
    "--project",
    "project_ref",
    help="Project name or ID (required for title-based lookup)",
)
@click.option(
    "--pick",
    is_flag=True,
    help="Pick from matching tasks when title is ambiguous",
)
@click.option("--description", help="Evidence description")
@click.option("--metadata", help="JSON metadata for the evidence record")
@click.option("--created-by", help="Created-by label for the evidence record")
@async_command
async def task_evidence_add(
    task_ref: str,
    evidence_type: str,
    reference: str,
    project_ref: str | None,
    pick: bool,
    description: str | None,
    metadata: str | None,
    created_by: str | None,
) -> None:
    """Add evidence to a task (manual input only)."""
    from pms.core import EventStore, MetricsCollector, RevisionStore
    from pms.db.connection import init_database
    from pms.services.project_service import ProjectService
    from pms.services.task_evidence_service import TaskEvidenceService
    from pms.services.task_service import TaskService

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        task_service = TaskService(db, event_store, revision_store, metrics)
        project_service = ProjectService(db, event_store, revision_store, metrics)
        evidence_service = TaskEvidenceService(db, metrics)

        task_id = await _resolve_task_id(
            task_ref,
            project_ref,
            task_service,
            project_service,
            pick=pick,
        )
        if task_id is None:
            return

        metadata_payload: dict[str, Any] | None = None
        if metadata:
            try:
                metadata_payload = json.loads(metadata)
            except json.JSONDecodeError:
                _emit_cli_error("Metadata must be valid JSON", output_format="text")

        evidence = await evidence_service.add_evidence(
            task_id=task_id,
            evidence_type=evidence_type,
            reference=reference,
            description=description,
            metadata=metadata_payload,
            created_by=created_by or "cli",
        )

        console.print(
            f"[green]Added evidence:[/green] {evidence.evidence_type} -> {evidence.reference}"
        )
        console.print(f"[dim]ID: {evidence.id}[/dim]")
        _print_next_steps(
            f"pms task evidence list {task_id}",
            f"pms task show {task_id}",
        )
    finally:
        await db.disconnect()


@task_evidence.command("list")
@click.argument("task_ref")
@click.option(
    "--project",
    "project_ref",
    help="Project name or ID (required for title-based lookup)",
)
@click.option(
    "--pick",
    is_flag=True,
    help="Pick from matching tasks when title is ambiguous",
)
@click.option("--include-test-runs", is_flag=True, help="Include test run details")
@click.option(
    "--include-output", is_flag=True, help="Include stdout/stderr for test runs"
)
@click.option("--limit", default=100, help="Maximum entries to show")
@click.option("--offset", default=0, help="Offset for pagination")
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["table", "json", "csv"]),
    default="table",
    show_default=True,
)
@click.option(
    "--view",
    type=click.Choice(["overview", "detail", "trace"]),
    default="detail",
    show_default=True,
    help="Output view profile (overview/detail/trace)",
)
@async_command
async def task_evidence_list(
    task_ref: str,
    project_ref: str | None,
    pick: bool,
    include_test_runs: bool,
    include_output: bool,
    limit: int,
    offset: int,
    output_format: str,
    view: str,
) -> None:
    """List evidence for a task."""
    from pms.core import EventStore, MetricsCollector, RevisionStore
    from pms.db.connection import init_database
    from pms.services.project_service import ProjectService
    from pms.services.task_evidence_service import TaskEvidenceService
    from pms.services.task_service import TaskService

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        task_service = TaskService(db, event_store, revision_store, metrics)
        project_service = ProjectService(db, event_store, revision_store, metrics)
        evidence_service = TaskEvidenceService(db, metrics)

        if project_ref:
            task_id = await _resolve_task_id(
                task_ref,
                project_ref,
                task_service,
                project_service,
                pick=pick,
            )
            if task_id is None:
                return
        else:
            task_id = task_ref

        task = await task_service.get_task(task_id)
        if task is None:
            hint = " (use --project for title-based lookup)" if not project_ref else ""
            console.print(f"[red]Task '{task_ref}' not found{hint}[/red]")
            return
        project_name = None
        if task.project_id:
            project = await project_service.get_project(task.project_id)
            if project:
                project_name = project.name
        if view == "trace":
            include_test_runs = True

        result = await evidence_service.list_evidence(
            task_id=task_id,
            limit=limit,
            offset=offset,
            include_test_runs=include_test_runs,
            include_output=include_output,
        )

        if output_format == "json":
            items = []
            for item in result.items:
                if view == "overview":
                    entry = {
                        "id": item.evidence.id,
                        "task_id": item.evidence.task_id,
                        "evidence_type": item.evidence.evidence_type,
                        "reference": item.evidence.reference,
                        "created_by": item.evidence.created_by,
                        "created_at": item.evidence.created_at,
                        "links": _normalize_command_links(
                            {
                                "task": f"pms task show {item.evidence.task_id}",
                                "task_evidence": (
                                    f"pms task evidence list {item.evidence.task_id}"
                                ),
                            }
                        ),
                    }
                else:
                    entry = {
                        "id": item.evidence.id,
                        "task_id": item.evidence.task_id,
                        "evidence_type": item.evidence.evidence_type,
                        "reference": item.evidence.reference,
                        "description": item.evidence.description,
                        "metadata": item.evidence.metadata,
                        "created_by": item.evidence.created_by,
                        "created_at": item.evidence.created_at,
                        "links": _normalize_command_links(
                            {
                                "task": f"pms task show {item.evidence.task_id}",
                                "task_evidence": (
                                    f"pms task evidence list {item.evidence.task_id}"
                                ),
                            }
                        ),
                    }

                if item.test_run and include_test_runs:
                    entry["test_run"] = {
                        "id": item.test_run.id,
                        "success": item.test_run.success,
                        "exit_code": item.test_run.exit_code,
                        "duration_seconds": item.test_run.duration_seconds,
                        "started_at": item.test_run.started_at,
                        "finished_at": item.test_run.finished_at,
                        "command": item.test_run.command,
                        "stdout": item.test_run.stdout if include_output else None,
                        "stderr": item.test_run.stderr if include_output else None,
                        "links": _normalize_command_links(
                            {"self": f"pms test show {item.test_run.id}"}
                        ),
                    }
                items.append(entry)

            base_cmd = f"pms task evidence list {task_id} --format json"
            if include_test_runs:
                base_cmd += " --include-test-runs"
            if include_output:
                base_cmd += " --include-output"
            if view != "overview":
                base_cmd += f" --view {view}"
            payload = {
                "task": {
                    "id": task.id,
                    "title": task.title,
                    "project_id": task.project_id,
                    "project_name": project_name,
                },
                "items": items,
                "page": _page_payload(result.total_count, result.limit, result.offset),
                "links": _normalize_command_links(
                    {
                        "self": f"{base_cmd} --limit {limit} --offset {offset}",
                        "next": (
                            f"{base_cmd} --limit {limit} --offset {offset + limit}"
                            if limit > 0 and offset + limit < result.total_count
                            else None
                        ),
                    }
                ),
            }
            click.echo(json.dumps(payload, default=str))
            return

        if output_format == "csv":
            headers = [
                "id",
                "evidence_type",
                "reference",
                "description",
                "created_by",
                "created_at",
            ]
            if include_test_runs:
                headers.extend(
                    [
                        "test_run_id",
                        "test_success",
                        "test_exit_code",
                        "test_duration_seconds",
                        "test_command",
                    ]
                )
                if include_output:
                    headers.extend(["test_stdout", "test_stderr"])
            click.echo(_csv_row(headers))
            for item in result.items:
                row = [
                    item.evidence.id,
                    item.evidence.evidence_type,
                    item.evidence.reference,
                    item.evidence.description or "",
                    item.evidence.created_by,
                    str(item.evidence.created_at),
                ]
                if include_test_runs:
                    test_run = item.test_run
                    success_value = ""
                    if test_run is not None:
                        success_value = "true" if test_run.success else "false"
                    row.extend(
                        [
                            test_run.id if test_run else "",
                            success_value,
                            str(test_run.exit_code) if test_run else "",
                            str(test_run.duration_seconds) if test_run else "",
                            test_run.command if test_run else "",
                        ]
                    )
                    if include_output:
                        row.extend(
                            [
                                test_run.stdout if test_run else "",
                                test_run.stderr if test_run else "",
                            ]
                        )
                click.echo(_csv_row(row))
            return

        from pms.utils.time import format_relative

        console.print(f"[dim]Task: {task.title} ({task.id})[/dim]")
        if project_name and task.project_id:
            console.print(f"[dim]Project: {project_name} ({task.project_id})[/dim]")
        table = Table(title="Task Evidence")
        table.add_column("Type")
        table.add_column("Reference", style="cyan")
        table.add_column("Created By")
        table.add_column("Created")
        table.add_column("Details")
        for item in result.items:
            details = item.evidence.description or "-"
            if include_test_runs and item.test_run:
                status = "passed" if item.test_run.success else "failed"
                details = f"{status} ({item.test_run.command or 'test run'})"
            table.add_row(
                item.evidence.evidence_type,
                item.evidence.reference,
                item.evidence.created_by,
                format_relative(item.evidence.created_at),
                details,
            )
        console.print(table)
        console.print(f"[dim]Total: {result.total_count}[/dim]")
        _print_next_steps(
            f"pms task show {task.id}",
            f"pms task proof-bundle {task.id}",
            f"pms task timeline {task.id}",
        )
    finally:
        await db.disconnect()


@task.group("dep")
def task_dep() -> None:
    """Manage task dependencies."""
    pass


@task_dep.command("add")
@click.argument("task_id")
@click.argument("depends_on_id")
@click.option(
    "--type",
    "dependency_type",
    type=click.Choice(["blocks", "relates_to", "duplicates"]),
    default="blocks",
)
@async_command
async def task_dep_add(
    task_id: str,
    depends_on_id: str,
    dependency_type: str,
) -> None:
    """Add a task dependency."""
    from pms.core import EventStore, MetricsCollector, RevisionStore
    from pms.db.connection import init_database
    from pms.models.enums import DependencyType
    from pms.services.task_service import TaskService

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        service = TaskService(db, event_store, revision_store, metrics)

        dep = await service.add_dependency(
            task_id=task_id,
            depends_on_id=depends_on_id,
            dependency_type=DependencyType(dependency_type),
        )

        if dep is None:
            _emit_cli_error("Dependency not created", output_format="text")

        console.print(
            f"[green]Added dependency:[/green] {dep.task_id} -> {dep.depends_on_id}"
        )
    finally:
        await db.disconnect()


@task_dep.command("remove")
@click.argument("task_id")
@click.argument("depends_on_id")
@async_command
async def task_dep_remove(task_id: str, depends_on_id: str) -> None:
    """Remove a task dependency."""
    from pms.core import EventStore, MetricsCollector, RevisionStore
    from pms.db.connection import init_database
    from pms.services.task_service import TaskService

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        service = TaskService(db, event_store, revision_store, metrics)

        removed = await service.remove_dependency(task_id, depends_on_id)
        if not removed:
            _emit_cli_error("Dependency not found", output_format="text")

        console.print(
            f"[green]Removed dependency:[/green] {task_id} -> {depends_on_id}"
        )
    finally:
        await db.disconnect()


@task.command("blocked")
@click.option("--project", "project_name", help="Filter by project name")
@click.option(
    "--include-generated",
    is_flag=True,
    help="Include tasks from generated or otherwise non-operator-visible projects in instance-wide views",
)
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["table", "json", "csv"]),
    default="table",
    show_default=True,
)
@click.option(
    "--view",
    type=click.Choice(["review", "overview"]),
    default="review",
    show_default=True,
    help="Text view profile (review/overview)",
)
@click.option("--include-history", is_flag=True, help="Include history in JSON")
@click.option("--include-linked", is_flag=True, help="Include linked items in JSON")
@click.option(
    "--include-linked-history",
    is_flag=True,
    help="Include history for linked items in JSON",
)
@click.option("--history-limit", type=int, default=50, show_default=True)
@click.option("--linked-limit", type=int, default=20, show_default=True)
@async_command
async def task_blocked(
    project_name: str | None,
    include_generated: bool,
    output_format: str,
    view: str,
    include_history: bool,
    include_linked: bool,
    include_linked_history: bool,
    history_limit: int,
    linked_limit: int,
) -> None:
    """List blocked tasks."""
    from pms.core import EventStore, MetricsCollector, RevisionStore
    from pms.db.connection import init_database
    from pms.models import TaskStatus
    from pms.repositories import ProjectRepository
    from pms.services.actor_service import ActorService
    from pms.services.generated_artifacts import (
        classify_project_operator_category,
        project_operator_category_label,
        project_operator_visibility_reason,
    )
    from pms.services.project_service import ProjectService
    from pms.services.task_service import TaskService

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        task_service = TaskService(db, event_store, revision_store, metrics)
        project_service = ProjectService(db, event_store, revision_store, metrics)
        project_repo = ProjectRepository(db, event_store, revision_store, metrics)
        actor_service = ActorService(db, event_store, revision_store, metrics)

        project_id = None
        project_label = None
        if project_name:
            project = await project_repo.get_by_name(project_name)
            if project is None:
                project = await project_repo.get_by_id(project_name)
            if project is None:
                console.print(f"[red]Project '{project_name}' not found[/red]")
                return
            project_id = project.id
            project_label = project.name

        all_tasks = await task_service.get_blocked_tasks(project_id=project_id)
        if project_id:
            tasks = list(all_tasks)
            selected_population_name = "scoped_project"
            selected_population_tasks = list(all_tasks)
            visible_population_tasks = list(all_tasks)
            suppressed_hidden_count = 0
        else:
            excluded_project_ids = await _operator_hidden_project_ids(
                project_service,
                [task.project_id for task in all_tasks],
            )
            visible_population_tasks = _exclude_tasks_from_projects(
                all_tasks, excluded_project_ids
            )
            if include_generated:
                tasks = list(all_tasks)
                selected_population_name = "all_retained"
                selected_population_tasks = list(all_tasks)
                suppressed_hidden_count = max(
                    0, len(selected_population_tasks) - len(visible_population_tasks)
                )
            else:
                tasks = list(visible_population_tasks)
                selected_population_name = "visible_operator"
                selected_population_tasks = list(visible_population_tasks)
                suppressed_hidden_count = max(
                    0, len(all_tasks) - len(visible_population_tasks)
                )
        no_actionable_work = _instance_task_surface_has_no_actionable_work(
            project_id=project_id,
            include_generated=include_generated,
            visible_total_count=len(tasks),
            suppressed_hidden_count=suppressed_hidden_count,
        )
        blocked_scope_summary = (
            "Instance-wide retained blocked-task view. Generated and historical project tasks are included explicitly."
            if include_generated
            else "Instance-wide blocked-task view. Only operator-visible active-project tasks are surfaced by default."
        )
        if no_actionable_work:
            blocked_scope_summary = _instance_task_surface_no_actionable_summary(
                "blocked-task view"
            )
        blocked_self_command = "task blocked --format json"
        if project_name:
            blocked_self_command = _append_cli_option(
                blocked_self_command, "--project", project_name
            )
        if include_generated:
            blocked_self_command += " --include-generated"
        if view != "review":
            blocked_self_command = _append_cli_option(
                blocked_self_command, "--view", view
            )
        blocked_next_steps = (
            _no_actionable_work_next_steps(
                blocked_self_command
                if include_generated
                else blocked_self_command.replace(
                    " --format json", " --include-generated --format json"
                )
            )
            if no_actionable_work
            else _normalize_next_steps(
                "task ready --format json",
                "dashboard --format json",
                "start --format json",
            )
        )
        if not tasks:
            if output_format == "json":
                payload = {
                    "items": [],
                    "page": {
                        "total_count": 0,
                        "limit": 0,
                        "offset": 0,
                        "has_more": False,
                        "next_offset": None,
                    },
                    "scope": (
                        {
                            "kind": "project_blocked_tasks",
                            "population": "scoped_project",
                            "project_id": project_id,
                            "project_name": project_label,
                        }
                        if project_id
                        else {
                            "kind": "instance_blocked_tasks",
                            "population": selected_population_name,
                            "summary": blocked_scope_summary,
                        }
                    ),
                    "visible_totals": (
                        {
                            "population": "visible_operator",
                            **_task_population_totals(
                                visible_population_tasks, TaskStatus
                            ),
                        }
                        if not project_id
                        else {
                            "population": "scoped_project",
                            **_task_population_totals(
                                selected_population_tasks, TaskStatus
                            ),
                        }
                    ),
                    "population_totals": {
                        "population": selected_population_name,
                        **_task_population_totals(
                            selected_population_tasks, TaskStatus
                        ),
                    },
                    "suppressed_hidden_count": suppressed_hidden_count
                    if not project_id
                    else 0,
                    "graph_navigation": _command_focus_graph_navigation(
                        focus_task=None,
                        task_lookup={},
                        assignee_map={},
                        project_id=project_id,
                        project_name=project_label,
                    ),
                    "links": _normalize_command_links(
                        {
                            "self": blocked_self_command,
                            "ready": "task ready --format json",
                            "dashboard": "dashboard --format json",
                            "guide": "start --format json",
                        }
                    ),
                    "next_steps": blocked_next_steps,
                    "params": {
                        "project_id": project_id,
                        "include_generated": include_generated,
                        "view": view,
                        "include_history": include_history,
                        "include_linked": include_linked,
                        "include_linked_history": include_linked_history,
                        "history_limit": history_limit,
                        "linked_limit": linked_limit,
                    },
                }
                payload = _payload_with_normalized_next_steps(
                    payload, *blocked_next_steps
                )
                click.echo(json.dumps(payload, default=str))
                return
            if output_format == "csv":
                headers = ["id", "title", "project_id"]
                click.echo(_csv_row(headers))
                return
            console.print("[dim]No blocked tasks.[/dim]")
            if no_actionable_work:
                console.print(f"[dim]{blocked_scope_summary}[/dim]")
            _print_next_steps(*blocked_next_steps)
            return

        task_ids = [task_obj.id for task_obj in tasks]
        activity_map = await task_service.get_last_activity_map(task_ids)
        project_names: dict[str, str | None] = {}
        task_project_operator_categories: dict[str, str | None] = {}
        for task_obj in tasks:
            if task_obj.project_id and task_obj.project_id not in project_names:
                project = await project_repo.get_by_id(task_obj.project_id)
                project_names[task_obj.project_id] = project.name if project else None
                if project is not None:
                    task_project_operator_categories[task_obj.project_id] = (
                        classify_project_operator_category(project)
                    )
                else:
                    task_project_operator_categories[task_obj.project_id] = None
        assignee_map = await _resolve_assignee_map(
            list(tasks),
            actor_service,
        )
        workflow_transition_map = await task_service.get_last_transition_map(
            task_ids, kind="workflow"
        )
        status_transition_map = await task_service.get_last_transition_map(
            task_ids, kind="status"
        )
        focus_state = _resolve_command_focus_state(list(tasks), project_names)
        focus_task_payload = (
            focus_state.focus_task.to_payload()
            if focus_state.focus_task is not None
            else None
        )
        from pms.repositories.task_repository import TaskRepository

        task_repo = TaskRepository(db, event_store, revision_store, metrics)
        blocked_detail_map = await _build_blocked_task_detail_map(
            tasks,
            task_service=task_service,
            task_repo=task_repo,
            project_service=project_service,
        )

        first_task = tasks[0] if tasks else None
        collection_steps = []
        if first_task:
            task_target = _best_task_command_target(
                first_task.id,
                first_task.title,
                project_names.get(first_task.project_id),
            )
            first_task_details = blocked_detail_map.get(first_task.id, {})
            collection_steps.append(_cli_command(f"task show {task_target}"))
            if first_task_details.get("blocked_by"):
                collection_steps.append(_cli_command(f"task unblock {task_target}"))
        if project_label:
            collection_steps.append(
                _cli_command(f'task list --project "{project_label}"')
            )
        elif project_id:
            collection_steps.append(_cli_command(f"task list --project {project_id}"))
        else:
            collection_steps.append(_cli_command("task list"))
        common_steps = blocked_next_steps
        next_steps = _normalize_next_steps(*collection_steps, *common_steps)

        if output_format == "json":
            include_history, include_linked, include_linked_history = (
                _normalize_history_flags(
                    include_history, include_linked, include_linked_history
                )
            )
            effective_history_limit = history_limit if history_limit > 0 else 1000
            effective_linked_limit = linked_limit if linked_limit > 0 else 1000
            blocked_self_command = _cli_command(blocked_self_command)
            if include_history:
                blocked_self_command += " --include-history"
            if include_linked:
                blocked_self_command += " --include-linked"
            if include_linked_history:
                blocked_self_command += " --include-linked-history"
            if history_limit != 50:
                blocked_self_command += f" --history-limit {history_limit}"
            if linked_limit != 20:
                blocked_self_command += f" --linked-limit {linked_limit}"

            task_repo = None
            if include_linked:
                from pms.repositories.task_repository import TaskRepository

                task_repo = TaskRepository(db, event_store, revision_store, metrics)

            progress_repo = None
            state_repo = None
            evidence_repo = None
            if include_history or include_linked_history:
                from pms.repositories.progress_repository import ProgressRepository
                from pms.repositories.state_transition_repository import (
                    StateTransitionRepository,
                )
                from pms.repositories.task_evidence_repository import (
                    TaskEvidenceRepository,
                )

                progress_repo = ProgressRepository(db)
                state_repo = StateTransitionRepository(db)
                evidence_repo = TaskEvidenceRepository(db)

            payload_items = []
            for task_obj in tasks:
                data = {
                    "id": task_obj.id,
                    "title": task_obj.title,
                    "project_id": task_obj.project_id,
                    "project_name": project_names.get(task_obj.project_id),
                    "project_operator_category": (
                        task_project_operator_categories.get(task_obj.project_id)
                        if task_obj.project_id
                        else None
                    ),
                    "project_operator_category_label": (
                        project_operator_category_label(
                            task_project_operator_categories[task_obj.project_id]
                        )
                        if task_obj.project_id
                        and task_project_operator_categories.get(task_obj.project_id)
                        else None
                    ),
                    "project_operator_visibility_reason": (
                        project_operator_visibility_reason(
                            task_project_operator_categories[task_obj.project_id]
                        )
                        if task_obj.project_id
                        and task_project_operator_categories.get(task_obj.project_id)
                        else None
                    ),
                    "last_activity_at": _to_iso(activity_map.get(task_obj.id)),
                    "blocked_by": blocked_detail_map.get(task_obj.id, {}).get(
                        "blocked_by",
                        [],
                    ),
                    "blocked_by_details": blocked_detail_map.get(
                        task_obj.id,
                        {},
                    ).get("blocked_by_details", []),
                    "resolved_blocked_by_details": blocked_detail_map.get(
                        task_obj.id,
                        {},
                    ).get("resolved_blocked_by_details", []),
                    "execution_lock_plans": blocked_detail_map.get(
                        task_obj.id,
                        {},
                    ).get("execution_lock_plans", []),
                    "dependency_summary": blocked_detail_map.get(
                        task_obj.id,
                        {},
                    ).get("dependency_summary"),
                    "blocked_summary": blocked_detail_map.get(task_obj.id, {}).get(
                        "blocked_summary",
                        "No dependency detail recorded",
                    ),
                    "links": _normalize_command_links(
                        {
                            "self": f"task show {task_obj.id}",
                            "timeline": f"task timeline {task_obj.id}",
                            "graph": f"task graph {task_obj.id}",
                            "evidence": f"task evidence list {task_obj.id}",
                            "blocked": blocked_self_command,
                            "ready": "task ready --format json",
                            "list": (
                                f"task list --project {task_obj.project_id} --format json"
                                if task_obj.project_id
                                else "task list --format json"
                            ),
                            "actor": _task_assignee_actor_link(task_obj, assignee_map),
                            "dashboard": "dashboard --format json",
                            "guide": "start --format json",
                        }
                    ),
                    "assignee": _task_assignee_payload(task_obj, assignee_map),
                }
                task_target = _best_task_command_target(
                    task_obj.id,
                    task_obj.title,
                    project_names.get(task_obj.project_id),
                )
                data["next_steps"] = _normalize_next_steps(
                    f"task show {task_target}",
                    (
                        f"task unblock {task_target}"
                        if blocked_detail_map.get(task_obj.id, {}).get("blocked_by")
                        else ""
                    ),
                    (
                        f"task start {task_target}"
                        if blocked_detail_map.get(task_obj.id, {}).get("blocked_by")
                        else ""
                    ),
                    (
                        f"task list --project {task_obj.project_id}"
                        if task_obj.project_id
                        else "task list"
                    ),
                    *common_steps,
                )

                if include_history:
                    data["history"] = await _build_task_history(
                        task_id=task_obj.id,
                        progress_repo=progress_repo,
                        state_repo=state_repo,
                        evidence_repo=evidence_repo,
                        history_limit=effective_history_limit,
                    )

                if include_linked and task_repo:
                    linked_payload, linked_history = await _build_task_linked_payload(
                        task_obj,
                        task_repo=task_repo,
                        project_repo=project_repo,
                        task_service=task_service,
                        linked_limit=effective_linked_limit,
                        history_limit=effective_history_limit,
                        include_linked_history=include_linked_history,
                        progress_repo=progress_repo,
                        state_repo=state_repo,
                        evidence_repo=evidence_repo,
                    )
                    data["linked"] = linked_payload
                    if linked_history:
                        data["linked_history"] = linked_history

                payload_items.append(data)
            payload = {
                "items": payload_items,
                "page": {
                    "total_count": len(tasks),
                    "limit": len(tasks),
                    "offset": 0,
                    "has_more": False,
                    "next_offset": None,
                },
                "scope": (
                    {
                        "kind": "project_blocked_tasks",
                        "population": "scoped_project",
                        "project_id": project_id,
                        "project_name": project_label,
                    }
                    if project_id
                    else {
                        "kind": "instance_blocked_tasks",
                        "population": selected_population_name,
                        "summary": blocked_scope_summary,
                    }
                ),
                "visible_totals": (
                    {
                        "population": "visible_operator",
                        **_task_population_totals(visible_population_tasks, TaskStatus),
                    }
                    if not project_id
                    else {
                        "population": "scoped_project",
                        **_task_population_totals(
                            selected_population_tasks, TaskStatus
                        ),
                    }
                ),
                "population_totals": {
                    "population": selected_population_name,
                    **_task_population_totals(selected_population_tasks, TaskStatus),
                },
                "suppressed_hidden_count": suppressed_hidden_count
                if not project_id
                else 0,
                "focus_task": focus_task_payload,
                "graph_navigation": _command_focus_graph_navigation(
                    focus_task=focus_state.focus_task,
                    task_lookup={task.id: task for task in tasks},
                    assignee_map=assignee_map,
                    project_id=project_id,
                    project_name=project_label,
                ),
                "links": _normalize_command_links(
                    {
                        "self": blocked_self_command,
                        "ready": "task ready --format json",
                        "dashboard": "dashboard --format json",
                        "guide": "start --format json",
                    }
                ),
                "next_steps": next_steps,
                "params": {
                    "project_id": project_id,
                    "include_generated": include_generated,
                    "view": view,
                    "include_history": include_history,
                    "include_linked": include_linked,
                    "include_linked_history": include_linked_history,
                    "history_limit": history_limit,
                    "linked_limit": linked_limit,
                },
            }
            payload = _payload_with_normalized_next_steps(payload, *next_steps)
            click.echo(json.dumps(payload, default=str))
            return

        if output_format == "csv":
            headers = [
                "id",
                "title",
                "project_id",
                "project_name",
                "last_activity_at",
            ]
            click.echo(_csv_row(headers))
            for task in tasks:
                row = [
                    task.id,
                    task.title,
                    task.project_id,
                    project_names.get(task.project_id) or "",
                    _to_iso(activity_map.get(task.id)) or "",
                ]
                click.echo(_csv_row(row))
            return

        if view == "review":
            _print_task_review_view(
                result=QueryResult(
                    items=list(tasks),
                    total_count=len(tasks),
                    offset=0,
                    limit=len(tasks),
                ),
                tasks=list(tasks),
                total_tasks=list(tasks),
                project_label=project_label,
                project_id=project_id,
                assignee_actor=None,
                assignee_map=assignee_map,
                project_names=project_names,
                activity_map=activity_map,
                workflow_transition_map=workflow_transition_map,
                status_transition_map=status_transition_map,
                focus_state=focus_state,
                focus_task_payload=focus_task_payload,
                suppressed_hidden_count=suppressed_hidden_count,
                no_actionable_work=no_actionable_work,
                scope_summary=blocked_scope_summary,
            )
            _print_next_steps(*next_steps)
            return

        table = Table(title="Blocked Tasks")
        table.add_column("Title")
        table.add_column("Project")
        table.add_column("Activity")
        table.add_column("ID", style="dim")
        from pms.utils.time import format_relative

        for task in tasks:
            project_value = (
                project_names.get(task.project_id, task.project_id)
                if task.project_id
                else "-"
            )
            activity_text = format_relative(
                activity_map.get(task.id) or task.updated_at
            )
            blocked_summary = blocked_detail_map.get(task.id, {}).get(
                "blocked_summary",
                "No dependency detail recorded",
            )
            table.add_row(
                task.title,
                f"{project_value}\n{blocked_summary}",
                activity_text,
                task.id[:8],
            )
        console.print(table)
        console.print(f"[dim]Total: {len(tasks)}[/dim]")
        if not project_id and suppressed_hidden_count:
            console.print(
                f"[dim]Suppressed hidden tasks: {suppressed_hidden_count} "
                f"(use --include-generated to show retained audit/history tasks)[/dim]"
            )
        if no_actionable_work:
            console.print(f"[dim]{blocked_scope_summary}[/dim]")
        _print_next_steps(*next_steps)
    finally:
        await db.disconnect()


@task.command("graph")
@click.argument("task_ref")
@click.option(
    "--project",
    "project_ref",
    help="Project name or ID (required for title-based lookup)",
)
@click.option(
    "--pick",
    is_flag=True,
    help="Pick from matching tasks when title is ambiguous",
)
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json", "csv"]),
    default="text",
    show_default=True,
)
@async_command
async def task_graph(
    task_ref: str,
    project_ref: str | None,
    pick: bool,
    output_format: str,
) -> None:
    """Show dependency graph for a task."""
    from pms.core import EventStore, MetricsCollector, RevisionStore
    from pms.db.connection import init_database
    from pms.repositories import TaskRepository
    from pms.services.project_service import ProjectService
    from pms.services.task_service import TaskService

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        service = TaskService(db, event_store, revision_store, metrics)
        task_repo = TaskRepository(db, event_store, revision_store, metrics)
        project_service = ProjectService(db, event_store, revision_store, metrics)

        task_id = await _resolve_task_id(
            task_ref,
            project_ref,
            service,
            project_service,
            pick=pick,
        )
        if task_id is None:
            return

        graph = await service.get_dependency_graph(task_id)
        root_task = await service.get_task(task_id)
        project_names: dict[str, str | None] = {}
        if root_task and root_task.project_id:
            project = await project_service.get_project(root_task.project_id)
            project_names[root_task.project_id] = project.name if project else None

        dep_ids = list(dict.fromkeys(graph.blocked_by + graph.blocking))
        task_map: dict[str, Any] = {}
        if dep_ids:
            tasks = await task_repo.get_by_ids(dep_ids)
            task_map = {task.id: task for task in tasks}
            for task_obj in tasks:
                if task_obj.project_id and task_obj.project_id not in project_names:
                    project = await project_service.get_project(task_obj.project_id)
                    project_names[task_obj.project_id] = (
                        project.name if project else None
                    )
        activity_map = await service.get_last_activity_map(dep_ids)
        workflow_map = await service.get_last_transition_map(dep_ids, kind="workflow")
        status_map = await service.get_last_transition_map(dep_ids, kind="status")

        def _detail(dep_id: str) -> dict[str, Any]:
            task_obj = task_map.get(dep_id)
            if task_obj is None:
                return {
                    "id": dep_id,
                    "title": None,
                    "project_id": None,
                    "project_name": None,
                }
            last_linked_transition = (
                workflow_map.get(task_obj.id)
                if task_obj.workflow_id
                else status_map.get(task_obj.id)
            )
            return {
                "id": task_obj.id,
                "title": task_obj.title,
                "status": task_obj.status.value,
                "priority": task_obj.priority.value,
                "project_id": task_obj.project_id,
                "project_name": project_names.get(task_obj.project_id),
                "updated_at": task_obj.updated_at,
                "last_activity_at": _to_iso(activity_map.get(task_obj.id)),
                "last_transition_at": _to_iso(last_linked_transition),
            }

        if output_format == "json":
            execution_lock_plans = await service.get_execution_lock_plan_names(task_id)
            blocked_by_details = [_detail(dep_id) for dep_id in graph.blocked_by]
            active_blocked_by_details = _active_blocked_dependency_details(
                blocked_by_details
            )
            payload = {
                "task_id": graph.task_id,
                "task_title": root_task.title if root_task else None,
                "project_id": root_task.project_id if root_task else None,
                "project_name": project_names.get(root_task.project_id)
                if root_task and root_task.project_id
                else None,
                "status": root_task.status.value if root_task else None,
                "priority": root_task.priority.value if root_task else None,
                "updated_at": root_task.updated_at if root_task else None,
                "last_activity_at": _to_iso(await service.get_last_activity(task_id)),
                "last_transition_at": _to_iso(
                    await service.get_last_transition(task_id, kind="workflow")
                    or await service.get_last_transition(task_id, kind="status")
                ),
                "blocked_by": [detail["id"] for detail in active_blocked_by_details],
                "blocking": graph.blocking,
                "blocked_by_details": active_blocked_by_details,
                "resolved_blocked_by_details": [
                    detail
                    for detail in blocked_by_details
                    if detail.get("status") == "done"
                ],
                "execution_lock_plans": execution_lock_plans,
                "blocking_details": [_detail(dep_id) for dep_id in graph.blocking],
            }
            click.echo(json.dumps(payload, default=str))
            return

        if output_format == "csv":
            headers = ["task_id", "direction", "dependency_id"]
            click.echo(_csv_row(headers))
            for dep_id in graph.blocked_by:
                click.echo(_csv_row([graph.task_id, "blocked_by", dep_id]))
            for dep_id in graph.blocking:
                click.echo(_csv_row([graph.task_id, "blocking", dep_id]))
            return

        def _label(dep_id: str) -> str:
            task = task_map.get(dep_id)
            if task:
                return f"{task.title} ({task.id})"
            return dep_id

        task_label = (
            f"{root_task.title} ({graph.task_id})" if root_task else graph.task_id
        )
        console.print(f"[bold]Task:[/bold] {task_label}")
        if root_task and root_task.project_id:
            root_project_name = project_names.get(root_task.project_id)
            if root_project_name:
                console.print(f"Project: {root_project_name} ({root_task.project_id})")
            else:
                console.print(f"Project: {root_task.project_id}")
        console.print(
            f"Blocked by: {', '.join(_label(dep_id) for dep_id in graph.blocked_by) or '-'}"
        )
        console.print(
            f"Blocking: {', '.join(_label(dep_id) for dep_id in graph.blocking) or '-'}"
        )
    finally:
        await db.disconnect()


@task.command("tree")
@click.option(
    "--project",
    "project_ref",
    help="Project name or ID. Defaults to the task group --project value; omitted means all projects.",
)
@click.option("--root-task-id", help="Root task ID (optional)")
@click.option(
    "--view",
    "tree_view",
    type=click.Choice(["auto", "hierarchy", "dependencies"]),
    default="auto",
    show_default=True,
    help="Tree surface to render. auto uses dependencies when blocker edges exist.",
)
@click.option(
    "--descriptions/--no-descriptions",
    default=True,
    show_default=True,
    help="Include task descriptions in text/CSV/JSON output.",
)
@click.option(
    "--description-lines",
    type=int,
    default=0,
    show_default=True,
    help="Max description lines per task; 0 prints the full description.",
)
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json", "csv"]),
    default="text",
    show_default=True,
)
@async_command
async def task_tree(
    project_ref: str | None,
    root_task_id: str | None,
    tree_view: str,
    descriptions: bool,
    description_lines: int,
    output_format: str,
) -> None:
    """Show task hierarchy or dependency tree."""
    from pms.core import EventStore, MetricsCollector, RevisionStore
    from pms.db.connection import init_database
    from pms.repositories.project_repository import ProjectRepository
    from pms.repositories.task_repository import TaskRepository
    from pms.services.task_service import TaskService

    if description_lines < 0:
        _emit_cli_error(
            "--description-lines must be >= 0",
            output_format="json" if output_format == "json" else "text",
        )

    ctx = click.get_current_context(silent=True)
    inherited_project_ref = (
        (ctx.obj or {}).get("task_project_ref") if ctx is not None else None
    )
    effective_project_ref = project_ref or inherited_project_ref

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        project_repo = ProjectRepository(db, event_store, revision_store, metrics)
        task_repo = TaskRepository(db, event_store, revision_store, metrics)
        task_service = TaskService(db, event_store, revision_store, metrics)

        projects: list[Any]
        if effective_project_ref:
            project = await project_repo.get_by_name(effective_project_ref)
            if project is None:
                project = await project_repo.get_by_id(effective_project_ref)
            if project is None:
                console.print(f"[red]Project '{effective_project_ref}' not found[/red]")
                return
            projects = [project]
        else:
            project_page = await project_repo.get_all(
                limit=100000,
                offset=0,
                order_by="name",
                order_desc=False,
            )
            projects = list(project_page.items)

        root_task = None
        if root_task_id:
            root_task = await task_service.get_task(root_task_id)
            scoped_project_ids = {project.id for project in projects}
            if root_task is None or (
                effective_project_ref and root_task.project_id not in scoped_project_ids
            ):
                _emit_cli_error(
                    "Root task not found in the specified project",
                    output_format="json" if output_format == "json" else "text",
                )
            if not effective_project_ref:
                root_project = await project_repo.get_by_id(root_task.project_id)
                projects = [root_project] if root_project is not None else []

        async def _project_tasks(project_id: str) -> list[Any]:
            offset = 0
            items: list[Any] = []
            while True:
                page = await task_repo.get_by_project(
                    project_id,
                    include_subtasks=True,
                    limit=500,
                    offset=offset,
                )
                items.extend(page.items)
                if not page.has_more:
                    break
                offset += page.limit
            return items

        project_names = {project.id: project.name for project in projects}
        all_tasks: list[Any] = []
        for project in projects:
            project_tasks = await _project_tasks(project.id)
            all_tasks.extend(project_tasks)

        task_ids = [task_obj.id for task_obj in all_tasks]
        task_id_set = set(task_ids)
        task_map = {task_obj.id: task_obj for task_obj in all_tasks}

        if root_task_id and root_task_id not in task_id_set:
            _emit_cli_error(
                "Root task not found in the specified project",
                output_format="json" if output_format == "json" else "text",
            )

        if not all_tasks:
            empty_view = "hierarchy" if tree_view == "auto" else tree_view
            if output_format == "json":
                payload = {
                    "project": (
                        {"id": projects[0].id, "name": projects[0].name}
                        if len(projects) == 1
                        else None
                    ),
                    "projects": [
                        {"id": project.id, "name": project.name} for project in projects
                    ],
                    "root_task_id": root_task_id,
                    "view": empty_view,
                    "total_tasks": 0,
                    "edge_count": 0,
                    "nodes": [],
                }
                click.echo(json.dumps(payload, default=str))
                return
            if output_format == "csv":
                headers = [
                    "view",
                    "task_id",
                    "parent_id",
                    "project_id",
                    "project_name",
                    "title",
                    "description",
                    "depth",
                    "status",
                    "priority",
                    "blocked_by",
                    "blocks",
                    "last_activity_at",
                    "last_transition_at",
                ]
                click.echo(_csv_row(headers))
                return
            console.print("[dim]No tasks.[/dim]")
            return

        dependency_rows: list[dict[str, Any]] = []
        if task_ids:
            placeholders = ", ".join("?" * len(task_ids))
            rows = await db.fetch_all(
                f"""
                SELECT task_id, depends_on_id, dependency_type
                FROM task_dependencies
                WHERE dependency_type = 'blocks'
                  AND task_id IN ({placeholders})
                  AND depends_on_id IN ({placeholders})
                """,
                tuple(task_ids + task_ids),
            )
            dependency_rows = [dict(row) for row in rows]

        resolved_view = tree_view
        if resolved_view == "auto":
            resolved_view = "dependencies" if dependency_rows else "hierarchy"

        activity_map = await task_service.get_last_activity_map(task_ids)
        workflow_map = await task_service.get_last_transition_map(
            task_ids, kind="workflow"
        )
        status_map = await task_service.get_last_transition_map(task_ids, kind="status")

        def _last_transition(task_obj: Any) -> datetime | None:
            return (
                workflow_map.get(task_obj.id)
                if task_obj.workflow_id
                else status_map.get(task_obj.id)
            )

        def _description_text(task_obj: Any) -> str:
            if not descriptions:
                return ""
            description = (task_obj.description or "").strip()
            if not description:
                return ""
            if description_lines == 0:
                return description
            lines = description.splitlines()
            if len(lines) <= description_lines:
                return description
            shown = "\n".join(lines[:description_lines]).rstrip()
            return f"{shown}\n... ({len(lines) - description_lines} more lines)"

        include_project_in_label = len(projects) != 1

        def _task_label(task_obj: Any, *, repeated: bool = False) -> Text:
            project_name = project_names.get(task_obj.project_id)
            label = Text()
            label.append(task_obj.title)
            label.append(f" [{task_obj.status.value}]", style="dim")
            if project_name and include_project_in_label:
                label.append(f" @ {project_name}", style="dim")
            label.append(f" {task_obj.id[:8]}", style="dim")
            if repeated:
                label.append(" shown above", style="dim")
            description = _description_text(task_obj)
            if description:
                label.append("\n")
                label.append(description, style="dim")
            return label

        def _task_payload(task_obj: Any) -> dict[str, Any]:
            last_transition = _last_transition(task_obj)
            task_payload = _public_task_payload(task_obj)
            task_payload.update(
                {
                    "status": task_obj.status.value,
                    "priority": task_obj.priority.value,
                    "project_name": project_names.get(task_obj.project_id),
                    "description": task_obj.description if descriptions else None,
                    "last_activity_at": _to_iso(activity_map.get(task_obj.id)),
                    "last_transition_at": _to_iso(last_transition),
                }
            )
            if not descriptions:
                task_payload.pop("description", None)
            return task_payload

        children_by_blocker: dict[str, list[str]] = {
            task_id: [] for task_id in task_ids
        }
        parents_by_blocked: dict[str, list[str]] = {task_id: [] for task_id in task_ids}
        order_index = {task_obj.id: idx for idx, task_obj in enumerate(all_tasks)}
        for row in dependency_rows:
            blocked_id = row["task_id"]
            blocker_id = row["depends_on_id"]
            if blocked_id not in task_id_set or blocker_id not in task_id_set:
                continue
            children_by_blocker.setdefault(blocker_id, []).append(blocked_id)
            parents_by_blocked.setdefault(blocked_id, []).append(blocker_id)
        for values in children_by_blocker.values():
            values.sort(key=lambda task_id: order_index.get(task_id, 0))
        for values in parents_by_blocked.values():
            values.sort(key=lambda task_id: order_index.get(task_id, 0))

        def _scope_label() -> str:
            if root_task_id:
                task_obj = task_map[root_task_id]
                return f"{task_obj.title} ({task_obj.id[:8]})"
            if len(projects) == 1:
                return projects[0].name
            return "all projects"

        if resolved_view == "dependencies":
            if root_task_id:
                root_ids = [root_task_id]
            else:
                root_ids = [
                    task_obj.id
                    for task_obj in all_tasks
                    if not parents_by_blocked.get(task_obj.id)
                ]
                if not root_ids:
                    root_ids = [task_obj.id for task_obj in all_tasks]
            root_ids.sort(key=lambda task_id: order_index.get(task_id, 0))

            def _dependency_payload(
                task_id: str,
                *,
                path: set[str],
                emitted: set[str],
            ) -> dict[str, Any]:
                task_obj = task_map[task_id]
                repeated = task_id in emitted
                payload = {
                    "task": _task_payload(task_obj),
                    "depth": len(path),
                    "blocked_by": parents_by_blocked.get(task_id, []),
                    "blocks": children_by_blocker.get(task_id, []),
                    "repeated": repeated,
                    "cycle": task_id in path,
                    "children": [],
                }
                if repeated or task_id in path:
                    return payload
                emitted.add(task_id)
                payload["children"] = [
                    _dependency_payload(
                        child_id,
                        path={*path, task_id},
                        emitted=emitted,
                    )
                    for child_id in children_by_blocker.get(task_id, [])
                ]
                return payload

            if output_format == "json":
                emitted: set[str] = set()
                payload = {
                    "project": (
                        {"id": projects[0].id, "name": projects[0].name}
                        if len(projects) == 1
                        else None
                    ),
                    "projects": [
                        {"id": project.id, "name": project.name} for project in projects
                    ],
                    "root_task_id": root_task_id,
                    "view": resolved_view,
                    "total_tasks": len(all_tasks),
                    "edge_count": len(dependency_rows),
                    "nodes": [
                        _dependency_payload(root_id, path=set(), emitted=emitted)
                        for root_id in root_ids
                    ],
                }
                click.echo(json.dumps(payload, default=str))
                return

            flat_rows: list[tuple[str, int, bool]] = []
            flat_seen: set[str] = set()

            def _flatten_dependency(task_id: str, depth: int, path: set[str]) -> None:
                repeated = task_id in flat_seen or task_id in path
                flat_rows.append((task_id, depth, repeated))
                if repeated:
                    return
                flat_seen.add(task_id)
                for child_id in children_by_blocker.get(task_id, []):
                    _flatten_dependency(child_id, depth + 1, {*path, task_id})

            for root_id in root_ids:
                _flatten_dependency(root_id, 0, set())

            if output_format == "csv":
                headers = [
                    "view",
                    "task_id",
                    "parent_id",
                    "project_id",
                    "project_name",
                    "title",
                    "description",
                    "depth",
                    "status",
                    "priority",
                    "blocked_by",
                    "blocks",
                    "last_activity_at",
                    "last_transition_at",
                ]
                click.echo(_csv_row(headers))
                for task_id, depth, _repeated in flat_rows:
                    task_obj = task_map[task_id]
                    row = [
                        resolved_view,
                        task_obj.id,
                        task_obj.parent_id or "",
                        task_obj.project_id,
                        project_names.get(task_obj.project_id) or "",
                        task_obj.title,
                        _description_text(task_obj),
                        str(depth),
                        task_obj.status.value,
                        task_obj.priority.value,
                        ",".join(parents_by_blocked.get(task_id, [])),
                        ",".join(children_by_blocker.get(task_id, [])),
                        _to_iso(activity_map.get(task_id)) or "",
                        _to_iso(_last_transition(task_obj)) or "",
                    ]
                    click.echo(_csv_row(row))
                return

            tree = Tree(f"Task Dependency Tree: {_scope_label()}")

            def _add_dependency_node(
                parent: Tree,
                task_id: str,
                path: set[str],
                emitted: set[str],
            ) -> None:
                task_obj = task_map[task_id]
                repeated = task_id in emitted
                node = parent.add(_task_label(task_obj, repeated=repeated))
                if task_id in path:
                    node.add(Text("cycle detected", style="red"))
                    return
                if repeated:
                    return
                emitted.add(task_id)
                for child_id in children_by_blocker.get(task_id, []):
                    _add_dependency_node(node, child_id, {*path, task_id}, emitted)

            emitted_text: set[str] = set()
            for root_id in root_ids:
                _add_dependency_node(tree, root_id, set(), emitted_text)
            console.print(tree)
            console.print(
                f"[dim]View: dependencies | tasks {len(all_tasks)} | edges {len(dependency_rows)}[/dim]"
            )
            return

        hierarchy_pairs: list[tuple[Any, Any]] = []
        hierarchy_projects = (
            [project for project in projects if project.id == root_task.project_id]
            if root_task_id and root_task is not None
            else projects
        )
        for project in hierarchy_projects:
            trees = await task_service.get_task_tree(
                project_id=project.id,
                root_task_id=root_task_id,
            )
            for tree_node in trees:
                hierarchy_pairs.append((project, tree_node))

        def _tree_payload(tree) -> dict[str, Any]:
            task_obj = tree.task
            return {
                "task": _task_payload(task_obj),
                "depth": tree.depth,
                "children": [_tree_payload(child) for child in tree.children],
            }

        if output_format == "json":
            payload = {
                "project": (
                    {"id": projects[0].id, "name": projects[0].name}
                    if len(projects) == 1
                    else None
                ),
                "projects": [
                    {"id": project.id, "name": project.name} for project in projects
                ],
                "root_task_id": root_task_id,
                "view": resolved_view,
                "total_tasks": len(all_tasks),
                "edge_count": len(dependency_rows),
                "nodes": [_tree_payload(tree) for _project, tree in hierarchy_pairs],
            }
            click.echo(json.dumps(payload, default=str))
            return

        def _flatten(tree, rows) -> None:
            rows.append(tree)
            for child in tree.children:
                _flatten(child, rows)

        flat_nodes: list[Any] = []
        for _project, tree in hierarchy_pairs:
            _flatten(tree, flat_nodes)

        if output_format == "csv":
            headers = [
                "view",
                "task_id",
                "parent_id",
                "project_id",
                "project_name",
                "title",
                "description",
                "depth",
                "status",
                "priority",
                "blocked_by",
                "blocks",
                "last_activity_at",
                "last_transition_at",
            ]
            click.echo(_csv_row(headers))
            for node in flat_nodes:
                task_obj = node.task
                row = [
                    resolved_view,
                    task_obj.id,
                    task_obj.parent_id or "",
                    task_obj.project_id,
                    project_names.get(task_obj.project_id) or "",
                    task_obj.title,
                    _description_text(task_obj),
                    str(node.depth),
                    task_obj.status.value,
                    task_obj.priority.value,
                    ",".join(parents_by_blocked.get(task_obj.id, [])),
                    ",".join(children_by_blocker.get(task_obj.id, [])),
                    _to_iso(activity_map.get(task_obj.id)) or "",
                    _to_iso(_last_transition(task_obj)) or "",
                ]
                click.echo(_csv_row(row))
            return

        tree = Tree(f"Task Hierarchy: {_scope_label()}")

        def _add_hierarchy_node(parent: Tree, tree_node: Any) -> None:
            node = parent.add(_task_label(tree_node.task))
            for child in tree_node.children:
                _add_hierarchy_node(node, child)

        for project, tree_node in hierarchy_pairs:
            parent = tree
            if len(projects) != 1 and not root_task_id:
                parent = tree.add(
                    Text(f"{project.name} {project.id[:8]}", style="bold")
                )
            _add_hierarchy_node(parent, tree_node)
        console.print(tree)
        if flat_nodes:
            first_task = flat_nodes[0].task
            task_label, project_clause = _task_ref_with_project(
                first_task.title, project_names.get(first_task.project_id)
            )
            _print_next_steps(
                f"pms task show {task_label}{project_clause}",
                f"pms task graph {first_task.id}",
                f'pms task list --project "{project_names.get(first_task.project_id, first_task.project_id)}"',
            )
        console.print(
            f"[dim]View: hierarchy | tasks {len(all_tasks)} | edges {len(dependency_rows)}[/dim]"
        )
    finally:
        await db.disconnect()


