@revision.command("diff")
@click.argument(
    "entity_type",
    type=click.Choice(
        [
            "task",
            "project",
            "plan",
            "goal",
            "objective",
            "key_result",
            "organization",
            "team",
            "portfolio",
            "program",
            "product",
            "label",
            "label_category",
            "label_gate_rule",
            "evidence_gate_rule",
            "saved_search",
            "plan_test_job",
        ]
    ),
)
@click.argument("entity_id")
@click.option("--from", "from_revision", type=int, required=True)
@click.option("--to", "to_revision", type=int, required=True)
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["table", "json", "csv"]),
    default="table",
    show_default=True,
)
@async_command
async def revision_diff(
    entity_type: str,
    entity_id: str,
    from_revision: int,
    to_revision: int,
    output_format: str,
) -> None:
    """Show field-level changes between two revisions."""
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database

    if from_revision < 1 or to_revision < 1:
        _emit_cli_error(
            "Revision numbers must be >= 1",
            output_format="json" if output_format == "json" else "text",
        )
    if from_revision >= to_revision:
        _emit_cli_error(
            "from_revision must be less than to_revision",
            output_format="json" if output_format == "json" else "text",
        )

    db = await init_database()
    try:
        revision_store = RevisionStore(db)
        total = await revision_store.get_revision_count(entity_type, entity_id)
        if total == 0:
            _emit_cli_error(
                "Revisions not found",
                output_format="json" if output_format == "json" else "text",
            )
        if to_revision > total:
            _emit_cli_error(
                f"to_revision exceeds latest revision ({total})",
                output_format="json" if output_format == "json" else "text",
            )

        diff = await revision_store.diff(
            entity_type=entity_type,
            entity_id=entity_id,
            from_revision=from_revision,
            to_revision=to_revision,
        )

        if output_format == "json":
            payload = {
                "entity_type": diff.entity_type,
                "entity_id": diff.entity_id,
                "from_revision": diff.from_revision,
                "to_revision": diff.to_revision,
                "changes": [
                    {
                        "field_name": change.field_name,
                        "old_value": change.old_value,
                        "new_value": change.new_value,
                        "change_type": change.change_type.value,
                    }
                    for change in diff.changes
                ],
                "intermediate_revisions": diff.intermediate_revisions,
            }
            click.echo(json.dumps(payload, default=str))
            return

        if output_format == "csv":
            headers = ["field_name", "old_value", "new_value", "change_type"]
            click.echo(_csv_row(headers))
            for change in diff.changes:
                click.echo(
                    _csv_row(
                        [
                            change.field_name,
                            change.old_value or "",
                            change.new_value or "",
                            change.change_type.value,
                        ]
                    )
                )
            return

        table = Table(title=f"Revision Diff ({entity_type})")
        table.add_column("Field")
        table.add_column("From")
        table.add_column("To")
        table.add_column("Type")
        for change in diff.changes:
            table.add_row(
                change.field_name,
                change.old_value or "",
                change.new_value or "",
                change.change_type.value,
            )
        console.print(table)
        console.print(f"[dim]Changes: {len(diff.changes)}[/dim]")
    finally:
        await db.disconnect()


@revision.command("bundle")
@click.argument(
    "entity_type",
    type=click.Choice(
        [
            "task",
            "project",
            "plan",
            "goal",
            "objective",
            "key_result",
            "organization",
            "team",
            "portfolio",
            "program",
            "product",
            "label",
            "label_category",
            "label_gate_rule",
            "evidence_gate_rule",
            "saved_search",
            "plan_test_job",
        ]
    ),
)
@click.argument("entity_id")
@click.option("--include-linked", is_flag=True, help="Include linked items")
@click.option(
    "--include-linked-history",
    is_flag=True,
    help="Include history for linked items",
)
@click.option("--history-limit", type=int, default=20, show_default=True)
@click.option("--history-offset", type=int, default=0, show_default=True)
@click.option("--linked-limit", type=int, default=20, show_default=True)
@click.option("--linked-history-limit", type=int, default=None)
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["table", "json", "csv"]),
    default="table",
    show_default=True,
)
@async_command
async def revision_bundle(
    entity_type: str,
    entity_id: str,
    include_linked: bool,
    include_linked_history: bool,
    history_limit: int,
    history_offset: int,
    linked_limit: int,
    linked_history_limit: int | None,
    output_format: str,
) -> None:
    """Export revision history bundle for an entity."""
    from pms.db.connection import init_database
    from pms.services.history_bundle_service import HistoryBundleService

    db = await init_database()
    try:
        service = HistoryBundleService(db)
        bundle = await service.build_bundle(
            entity_type=entity_type,
            entity_id=entity_id,
            include_linked=include_linked,
            include_linked_history=include_linked_history,
            history_limit=history_limit,
            history_offset=history_offset,
            linked_limit=linked_limit,
            linked_history_limit=linked_history_limit,
        )
        if bundle is None:
            console.print(f"[red]{entity_type} '{entity_id}' not found[/red]")
            return

        if output_format == "json":
            click.echo(json.dumps(bundle.to_dict(), default=str))
            return

        if output_format == "csv":
            headers = [
                "entity_type",
                "entity_id",
                "revision_number",
                "change_type",
                "created_at",
                "created_by",
                "message",
            ]
            click.echo(_csv_row(headers))
            for rev in bundle.history.items:
                click.echo(
                    _csv_row(
                        [
                            entity_type,
                            entity_id,
                            str(rev.revision_number),
                            rev.change_type.value,
                            rev.created_at.isoformat(),
                            rev.created_by or "",
                            rev.message or "",
                        ]
                    )
                )
            return

        table = Table(title=f"Revision History ({entity_type})")
        table.add_column("Revision", justify="right")
        table.add_column("Type")
        table.add_column("When")
        table.add_column("By")
        table.add_column("Message")
        for rev in bundle.history.items:
            table.add_row(
                str(rev.revision_number),
                rev.change_type.value,
                format_relative(rev.created_at),
                rev.created_by or "-",
                rev.message or "-",
            )
        console.print(table)
        console.print(f"[dim]Total revisions: {bundle.history.total_count}[/dim]")

        if bundle.linked:
            linked_table = Table(title="Linked Items")
            linked_table.add_column("Group")
            linked_table.add_column("Count", justify="right")
            linked_table.add_column("Sample")
            for group, items in bundle.linked.items():
                names = [item.get("name") or item.get("id") for item in items[:3]]
                sample = ", ".join(names)
                if len(items) > 3:
                    sample = f"{sample}..."
                linked_table.add_row(group, str(len(items)), sample or "-")
            console.print(linked_table)

        if bundle.linked_history:
            name_lookup: dict[str, dict[str, str | None]] = {}
            for group, items in bundle.linked.items():
                name_lookup[group] = {item["id"]: item.get("name") for item in items}

            history_table = Table(title="Linked History")
            history_table.add_column("Group")
            history_table.add_column("Entity")
            history_table.add_column("Revisions", justify="right")
            history_table.add_column("Latest")
            for group, history_map in bundle.linked_history.items():
                for linked_id, history_page in history_map.items():
                    name = name_lookup.get(group, {}).get(linked_id)
                    label = f"{name} ({linked_id})" if name else linked_id
                    latest = (
                        history_page.items[0].created_at if history_page.items else None
                    )
                    history_table.add_row(
                        group,
                        label,
                        str(history_page.total_count),
                        format_relative(latest),
                    )
            console.print(history_table)
    finally:
        await db.disconnect()


