@category.command("list")
@click.option(
    "--include-archived",
    is_flag=True,
    help="Include archived categories",
)
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["table", "json", "csv"]),
    default="table",
    show_default=True,
)
@click.option(
    "--view",
    type=click.Choice(["overview", "detail", "trace"]),
    default="overview",
    show_default=True,
    help="Output view profile (overview/detail/trace)",
)
@click.option("--include-history", is_flag=True, help="Include history in JSON")
@click.option("--history-limit", type=int, default=20, show_default=True)
@click.option("--limit", type=int, default=100, show_default=True)
@click.option("--offset", type=int, default=0, show_default=True)
@async_command
async def label_category_list(
    output_format: str,
    include_archived: bool,
    view: str,
    include_history: bool,
    history_limit: int,
    limit: int,
    offset: int,
) -> None:
    """List label categories."""
    from pms.core.metrics import MetricsCollector
    from pms.db.connection import init_database
    from pms.services.label_service import LabelService

    db = await init_database()
    try:
        metrics = MetricsCollector(db)
        service = LabelService(db, metrics)
        if view == "trace":
            include_history = True

        categories = await service.list_categories(include_archived=include_archived)
        total_count = len(categories)
        if limit <= 0:
            view_items = categories[offset:]
        else:
            view_items = categories[offset : offset + limit]

        if output_format == "json":
            from pms.repositories.label_category_repository import (
                LabelCategoryRepository,
            )

            repo = LabelCategoryRepository(db)
            effective_history_limit = history_limit if history_limit > 0 else 1000

            def _category_links(cat_obj) -> dict[str, str]:
                return _normalize_command_links(
                    {
                        "self": f"pms label category show {cat_obj.id}",
                        "update": f"pms label category update {cat_obj.id}",
                        "delete": f"pms label category delete {cat_obj.id}",
                        "restore": f"pms label category restore {cat_obj.id}",
                    }
                )

            items = []
            for cat in view_items:
                if view == "overview":
                    payload = {
                        "id": cat.id,
                        "name": cat.name,
                        "is_exclusive": cat.is_exclusive,
                        "sort_order": cat.sort_order,
                        "updated_at": cat.updated_at,
                        "archived_at": cat.archived_at,
                        "links": _category_links(cat),
                    }
                else:
                    payload = {
                        "id": cat.id,
                        "name": cat.name,
                        "description": cat.description,
                        "is_exclusive": cat.is_exclusive,
                        "sort_order": cat.sort_order,
                        "created_at": cat.created_at,
                        "updated_at": cat.updated_at,
                        "archived_at": cat.archived_at,
                        "links": _category_links(cat),
                    }

                if include_history:
                    history = await repo.get_history(
                        cat.id, limit=effective_history_limit
                    )
                    payload["history"] = [
                        {
                            "revision_number": rev.revision_number,
                            "change_type": rev.change_type.value,
                            "message": rev.message,
                            "created_by": rev.created_by,
                            "created_at": rev.created_at,
                        }
                        for rev in history
                    ]

                items.append(payload)

            base_cmd = "pms label category list --format json"
            if include_archived:
                base_cmd += " --include-archived"
            if view != "overview":
                base_cmd += f" --view {view}"
            payload = {
                "items": items,
                "page": _page_payload(total_count, limit, offset),
                "links": _normalize_command_links(
                    {
                        "self": f"{base_cmd} --limit {limit} --offset {offset}",
                        "next": (
                            f"{base_cmd} --limit {limit} --offset {offset + limit}"
                            if limit > 0 and offset + limit < total_count
                            else None
                        ),
                    }
                ),
            }
            click.echo(json.dumps(payload, default=str))
            return

        if output_format == "csv":
            headers = [
                "id",
                "name",
                "description",
                "is_exclusive",
                "sort_order",
                "updated_at",
                "archived_at",
            ]
            click.echo(_csv_row(headers))
            for cat in view_items:
                row = [
                    cat.id,
                    cat.name,
                    cat.description or "",
                    "true" if cat.is_exclusive else "false",
                    str(cat.sort_order),
                    str(cat.updated_at)[:19] if cat.updated_at else "",
                    str(cat.archived_at)[:19] if cat.archived_at else "",
                ]
                click.echo(_csv_row(row))
            return

        from pms.utils.time import format_relative

        table = Table(title="Label Categories")
        table.add_column("Name", style="cyan")
        table.add_column("Exclusive")
        table.add_column("Sort")
        table.add_column("Updated")
        table.add_column("Archived")
        for cat in view_items:
            table.add_row(
                cat.name,
                "yes" if cat.is_exclusive else "no",
                str(cat.sort_order),
                format_relative(cat.updated_at),
                format_relative(cat.archived_at),
            )
        console.print(table)
        console.print(f"[dim]Total: {len(categories)}[/dim]")
    finally:
        await db.disconnect()


