@async_command
async def label_category_show(
    category_ref: str,
    output_format: str,
    view: str,
    include_history: bool,
    include_linked: bool,
    include_linked_history: bool,
    history_limit: int,
    linked_limit: int,
) -> None:
    """Show label category details."""
    from pms.core.metrics import MetricsCollector
    from pms.db.connection import init_database
    from pms.repositories.label_category_repository import LabelCategoryRepository
    from pms.repositories.label_repository import LabelRepository
    from pms.services.label_service import LabelService
    from pms.utils.time import format_relative

    if view == "trace":
        include_history = True
        include_linked = True
    if include_linked_history:
        include_linked = True
        include_history = True

    db = await init_database()
    try:
        metrics = MetricsCollector(db)
        service = LabelService(db, metrics)
        category_repo = LabelCategoryRepository(db)
        label_repo = LabelRepository(db)

        category = await service.get_category(category_ref)
        if category is None:
            category = await service.get_category_by_name(category_ref)
        if category is None:
            console.print(f"[red]Category '{category_ref}' not found[/red]")
            return

        if output_format == "json":
            effective_history_limit = history_limit if history_limit > 0 else 1000
            effective_linked_limit = linked_limit if linked_limit > 0 else 1000

            def _category_links(cat_obj) -> dict[str, str]:
                return _normalize_command_links(
                    {
                        "self": f"pms label category show {cat_obj.id}",
                        "update": f"pms label category update {cat_obj.id}",
                        "delete": f"pms label category delete {cat_obj.id}",
                        "restore": f"pms label category restore {cat_obj.id}",
                    }
                )

            if view == "overview":
                payload = {
                    "id": category.id,
                    "name": category.name,
                    "is_exclusive": category.is_exclusive,
                    "sort_order": category.sort_order,
                    "updated_at": category.updated_at,
                    "archived_at": category.archived_at,
                    "links": _category_links(category),
                }
            else:
                payload = {
                    "id": category.id,
                    "name": category.name,
                    "description": category.description,
                    "is_exclusive": category.is_exclusive,
                    "sort_order": category.sort_order,
                    "created_at": category.created_at,
                    "updated_at": category.updated_at,
                    "archived_at": category.archived_at,
                    "links": _category_links(category),
                }

            if include_linked:
                labels = await service.list_labels(category_id=category.id)
                total_count = len(labels)
                view_items = labels[:effective_linked_limit]
                payload["linked"] = {
                    "labels": [
                        {
                            "id": label_obj.id,
                            "name": label_obj.name,
                            "color": label_obj.color,
                            "is_system": label_obj.is_system,
                            "updated_at": label_obj.updated_at,
                            "archived_at": label_obj.archived_at,
                            "links": _normalize_command_links(
                                {
                                    "self": f"pms label show {label_obj.id}",
                                    "update": f"pms label update {label_obj.id}",
                                }
                            ),
                        }
                        for label_obj in view_items
                    ],
                    "page": _page_payload(total_count, effective_linked_limit, 0),
                }
                if include_linked_history and view_items:
                    payload["linked_history"] = {
                        label_obj.id: [
                            {
                                "revision_number": rev.revision_number,
                                "change_type": rev.change_type.value,
                                "message": rev.message,
                                "created_by": rev.created_by,
                                "created_at": rev.created_at,
                            }
                            for rev in await label_repo.get_history(
                                label_obj.id, limit=effective_history_limit
                            )
                        ]
                        for label_obj in view_items
                    }

            if include_history:
                history = await category_repo.get_history(
                    category.id, limit=effective_history_limit
                )
                payload["history"] = [
                    {
                        "revision_number": rev.revision_number,
                        "change_type": rev.change_type.value,
                        "message": rev.message,
                        "created_by": rev.created_by,
                        "created_at": rev.created_at,
                    }
                    for rev in history
                ]

            click.echo(json.dumps(payload, indent=2, default=str))
            return

        if output_format == "csv":
            headers = [
                "id",
                "name",
                "description",
                "is_exclusive",
                "sort_order",
                "created_at",
                "updated_at",
                "archived_at",
            ]
            click.echo(_csv_row(headers))
            click.echo(
                _csv_row(
                    [
                        category.id,
                        category.name,
                        category.description or "",
                        "true" if category.is_exclusive else "false",
                        str(category.sort_order),
                        str(category.created_at)[:19] if category.created_at else "",
                        str(category.updated_at)[:19] if category.updated_at else "",
                        str(category.archived_at)[:19] if category.archived_at else "",
                    ]
                )
            )
            return

        console.print(f"[bold cyan]{category.name}[/bold cyan]")
        console.print(f"[dim]ID: {category.id}[/dim]")
        console.print(f"Exclusive: {'yes' if category.is_exclusive else 'no'}")
        console.print(f"Sort Order: {category.sort_order}")
        if category.description:
            console.print(f"Description: {category.description}")
        console.print(f"Created: {format_relative(category.created_at)}")
        console.print(f"Updated: {format_relative(category.updated_at)}")
        if category.archived_at:
            console.print(f"Archived: {format_relative(category.archived_at)}")
    finally:
        await db.disconnect()


