@label.command("create")
@click.argument("name")
@click.option("-d", "--description", help="Label description")
@click.option("--category", "category_name", help="Category name")
@click.option("--category-id", help="Category ID")
@click.option("--color", help="Hex color")
@click.option("--system", is_flag=True, help="Mark as system label")
@async_command
async def label_create(
    name: str,
    description: str | None,
    category_name: str | None,
    category_id: str | None,
    color: str | None,
    system: bool,
) -> None:
    """Create a label."""
    from pms.core.metrics import MetricsCollector
    from pms.db.connection import init_database
    from pms.services.label_service import LabelService

    db = await init_database()
    try:
        metrics = MetricsCollector(db)
        service = LabelService(db, metrics)
        if category_name and category_id:
            _emit_cli_error(
                "Use --category or --category-id, not both", output_format="text"
            )
        resolved_category_id = category_id
        if category_name:
            category = await service.get_category_by_name(category_name)
            if category is None:
                console.print(f"[red]Category '{category_name}' not found[/red]")
                return
            resolved_category_id = category.id
        label_obj = await service.create_label(
            name=name,
            description=description,
            category_id=resolved_category_id,
            color=color,
            is_system=system,
        )
        console.print(f"[green]Created label:[/green] {label_obj.name}")
        console.print(f"[dim]ID: {label_obj.id}[/dim]")
    finally:
        await db.disconnect()


@label.command("list")
@click.option("--category-id", help="Filter by category ID")
@click.option(
    "--include-archived",
    is_flag=True,
    help="Include archived labels",
)
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["table", "json", "csv"]),
    default="table",
    show_default=True,
)
@click.option(
    "--view",
    type=click.Choice(["overview", "detail", "trace"]),
    default="overview",
    show_default=True,
    help="Output view profile (overview/detail/trace)",
)
@click.option("--include-history", is_flag=True, help="Include history in JSON")
@click.option("--history-limit", type=int, default=20, show_default=True)
@click.option("--limit", type=int, default=100, show_default=True)
@click.option("--offset", type=int, default=0, show_default=True)
@async_command
async def label_list(
    category_id: str | None,
    output_format: str,
    include_archived: bool,
    view: str,
    include_history: bool,
    history_limit: int,
    limit: int,
    offset: int,
) -> None:
    """List labels."""
    from pms.core.metrics import MetricsCollector
    from pms.db.connection import init_database
    from pms.services.label_service import LabelService

    db = await init_database()
    try:
        metrics = MetricsCollector(db)
        service = LabelService(db, metrics)
        if view == "trace":
            include_history = True

        labels = await service.list_labels(
            category_id=category_id, include_archived=include_archived
        )
        total_count = len(labels)
        view_items = labels[offset:] if limit <= 0 else labels[offset : offset + limit]

        if output_format == "json":
            from pms.repositories.label_repository import LabelRepository

            repo = LabelRepository(db)
            effective_history_limit = history_limit if history_limit > 0 else 1000

            def _label_links(label_obj) -> dict[str, str]:
                return _normalize_command_links(
                    {
                        "self": f"pms label show {label_obj.id}",
                        "update": f"pms label update {label_obj.id}",
                        "delete": f"pms label delete {label_obj.id}",
                        "restore": f"pms label restore {label_obj.id}",
                    }
                )

            items = []
            for label_obj in view_items:
                if view == "overview":
                    payload = {
                        "id": label_obj.id,
                        "name": label_obj.name,
                        "category_id": label_obj.category_id,
                        "color": label_obj.color,
                        "is_system": label_obj.is_system,
                        "updated_at": label_obj.updated_at,
                        "archived_at": label_obj.archived_at,
                        "links": _label_links(label_obj),
                    }
                else:
                    payload = {
                        "id": label_obj.id,
                        "name": label_obj.name,
                        "description": label_obj.description,
                        "category_id": label_obj.category_id,
                        "color": label_obj.color,
                        "is_system": label_obj.is_system,
                        "created_at": label_obj.created_at,
                        "updated_at": label_obj.updated_at,
                        "archived_at": label_obj.archived_at,
                        "links": _label_links(label_obj),
                    }

                if include_history:
                    history = await repo.get_history(
                        label_obj.id, limit=effective_history_limit
                    )
                    payload["history"] = [
                        {
                            "revision_number": rev.revision_number,
                            "change_type": rev.change_type.value,
                            "message": rev.message,
                            "created_by": rev.created_by,
                            "created_at": rev.created_at,
                        }
                        for rev in history
                    ]

                items.append(payload)

            base_cmd = "pms label list --format json"
            if category_id:
                base_cmd += f" --category-id {category_id}"
            if include_archived:
                base_cmd += " --include-archived"
            if view != "overview":
                base_cmd += f" --view {view}"
            payload = {
                "items": items,
                "page": _page_payload(total_count, limit, offset),
                "links": _normalize_command_links(
                    {
                        "self": f"{base_cmd} --limit {limit} --offset {offset}",
                        "next": (
                            f"{base_cmd} --limit {limit} --offset {offset + limit}"
                            if limit > 0 and offset + limit < total_count
                            else None
                        ),
                    }
                ),
            }
            click.echo(json.dumps(payload, default=str))
            return

        if output_format == "csv":
            headers = [
                "id",
                "name",
                "category_id",
                "color",
                "is_system",
                "updated_at",
                "archived_at",
            ]
            click.echo(_csv_row(headers))
            for label_obj in view_items:
                row = [
                    label_obj.id,
                    label_obj.name,
                    label_obj.category_id or "",
                    label_obj.color or "",
                    "true" if label_obj.is_system else "false",
                    str(label_obj.updated_at)[:19] if label_obj.updated_at else "",
                    str(label_obj.archived_at)[:19] if label_obj.archived_at else "",
                ]
                click.echo(_csv_row(row))
            return

        from pms.utils.time import format_relative

        table = Table(title="Labels")
        table.add_column("Name", style="cyan")
        table.add_column("Category")
        table.add_column("Color")
        table.add_column("System")
        table.add_column("Updated")
        table.add_column("Archived")
        for label_obj in view_items:
            table.add_row(
                label_obj.name,
                label_obj.category_id or "-",
                label_obj.color or "-",
                "yes" if label_obj.is_system else "no",
                format_relative(label_obj.updated_at),
                format_relative(label_obj.archived_at),
            )
        console.print(table)
        console.print(f"[dim]Total: {len(labels)}[/dim]")
    finally:
        await db.disconnect()


@label.command("show")
@click.argument("label_ref")
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json", "csv"]),
    default="text",
    show_default=True,
)
@click.option(
    "--view",
    type=click.Choice(["overview", "detail", "trace"]),
    default="detail",
    show_default=True,
    help="Output view profile (overview/detail/trace)",
)
@click.option("--include-history", is_flag=True, help="Include history in JSON")
@click.option("--include-linked", is_flag=True, help="Include linked items in JSON")
@click.option("--history-limit", type=int, default=20, show_default=True)
@async_command
async def label_show(
    label_ref: str,
    output_format: str,
    view: str,
    include_history: bool,
    include_linked: bool,
    history_limit: int,
) -> None:
    """Show label details."""
    from pms.core.metrics import MetricsCollector
    from pms.db.connection import init_database
    from pms.repositories.label_repository import LabelRepository
    from pms.services.label_service import LabelService
    from pms.utils.time import format_relative

    if view == "trace":
        include_history = True
        include_linked = True

    db = await init_database()
    try:
        metrics = MetricsCollector(db)
        service = LabelService(db, metrics)
        repo = LabelRepository(db)

        label_obj = await service.get_label(label_ref)
        if label_obj is None:
            label_obj = await service.get_label_by_name(label_ref)
        if label_obj is None:
            console.print(f"[red]Label '{label_ref}' not found[/red]")
            return

        if output_format == "json":
            effective_history_limit = history_limit if history_limit > 0 else 1000

            def _label_links(label_item) -> dict[str, str]:
                return {
                    "self": f"pms label show {label_item.id}",
                    "update": f"pms label update {label_item.id}",
                    "delete": f"pms label delete {label_item.id}",
                    "restore": f"pms label restore {label_item.id}",
                }

            if view == "overview":
                payload = {
                    "id": label_obj.id,
                    "name": label_obj.name,
                    "category_id": label_obj.category_id,
                    "color": label_obj.color,
                    "is_system": label_obj.is_system,
                    "updated_at": label_obj.updated_at,
                    "archived_at": label_obj.archived_at,
                    "links": _label_links(label_obj),
                }
            else:
                payload = {
                    "id": label_obj.id,
                    "name": label_obj.name,
                    "description": label_obj.description,
                    "category_id": label_obj.category_id,
                    "color": label_obj.color,
                    "is_system": label_obj.is_system,
                    "created_at": label_obj.created_at,
                    "updated_at": label_obj.updated_at,
                    "archived_at": label_obj.archived_at,
                    "links": _label_links(label_obj),
                }

            if include_linked and label_obj.category_id:
                category = await service.get_category(label_obj.category_id)
                if category:
                    payload["linked"] = {
                        "category": {
                            "id": category.id,
                            "name": category.name,
                            "description": category.description,
                            "is_exclusive": category.is_exclusive,
                            "sort_order": category.sort_order,
                            "updated_at": category.updated_at,
                            "links": _normalize_command_links(
                                {"self": f"pms label category show {category.id}"}
                            ),
                        }
                    }

            if include_history:
                history = await repo.get_history(
                    label_obj.id, limit=effective_history_limit
                )
                payload["history"] = [
                    {
                        "revision_number": rev.revision_number,
                        "change_type": rev.change_type.value,
                        "message": rev.message,
                        "created_by": rev.created_by,
                        "created_at": rev.created_at,
                    }
                    for rev in history
                ]

            click.echo(json.dumps(payload, indent=2, default=str))
            return

        if output_format == "csv":
            headers = [
                "id",
                "name",
                "description",
                "category_id",
                "color",
                "is_system",
                "created_at",
                "updated_at",
                "archived_at",
            ]
            click.echo(_csv_row(headers))
            click.echo(
                _csv_row(
                    [
                        label_obj.id,
                        label_obj.name,
                        label_obj.description or "",
                        label_obj.category_id or "",
                        label_obj.color or "",
                        "true" if label_obj.is_system else "false",
                        str(label_obj.created_at)[:19] if label_obj.created_at else "",
                        str(label_obj.updated_at)[:19] if label_obj.updated_at else "",
                        str(label_obj.archived_at)[:19]
                        if label_obj.archived_at
                        else "",
                    ]
                )
            )
            return

        console.print(f"[bold cyan]{label_obj.name}[/bold cyan]")
        console.print(f"[dim]ID: {label_obj.id}[/dim]")
        if label_obj.description:
            console.print(f"Description: {label_obj.description}")
        console.print(f"Category: {label_obj.category_id or '-'}")
        console.print(f"Color: {label_obj.color or '-'}")
        console.print(f"System: {'yes' if label_obj.is_system else 'no'}")
        console.print(f"Created: {format_relative(label_obj.created_at)}")
        console.print(f"Updated: {format_relative(label_obj.updated_at)}")
        if label_obj.archived_at:
            console.print(f"Archived: {format_relative(label_obj.archived_at)}")
    finally:
        await db.disconnect()


