@label.command("remove")
@click.argument("entity_type")
@click.argument("entity_id")
@click.argument("label_ref")
@async_command
async def label_remove(entity_type: str, entity_id: str, label_ref: str) -> None:
    """Remove a label assignment (use ID or name)."""
    from pms.core.metrics import MetricsCollector
    from pms.db.connection import init_database
    from pms.services.label_service import LabelService

    db = await init_database()
    try:
        metrics = MetricsCollector(db)
        service = LabelService(db, metrics)
        label_obj = await service.get_label(label_ref)
        if label_obj is None:
            label_obj = await service.get_label_by_name(label_ref)
        if label_obj is None:
            console.print(f"[red]Label '{label_ref}' not found[/red]")
            return

        await service.remove_label(entity_type, entity_id, label_obj.id)
        console.print(
            f"[yellow]Removed label:[/yellow] {label_obj.name} from {entity_type} {entity_id}"
        )
    finally:
        await db.disconnect()


@label.command("list-entity")
@click.argument("entity_type")
@click.argument("entity_id")
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["table", "json", "csv"]),
    default="table",
    show_default=True,
)
@click.option(
    "--view",
    type=click.Choice(["overview", "detail", "trace"]),
    default="overview",
    show_default=True,
    help="Output view profile (overview/detail/trace)",
)
@click.option(
    "--sort",
    "sort_by",
    type=click.Choice(["name", "category", "applied"]),
    default="applied",
    show_default=True,
)
@click.option(
    "--order",
    type=click.Choice(["asc", "desc"]),
    default="desc",
    show_default=True,
)
@click.option("--limit", type=int, default=100, show_default=True)
@click.option("--offset", type=int, default=0, show_default=True)
@async_command
async def label_list_entity(
    entity_type: str,
    entity_id: str,
    output_format: str,
    view: str,
    sort_by: str,
    order: str,
    limit: int,
    offset: int,
) -> None:
    """List labels assigned to an entity.

    Examples:
        pms label list-entity task <task_id> --view detail --format json
        pms label list-entity task <task_id> --sort name --order asc
    """
    from pms.core.metrics import MetricsCollector
    from pms.db.connection import init_database
    from pms.repositories.label_assignment_repository import LabelAssignmentRepository
    from pms.services.label_service import LabelService

    db = await init_database()
    try:
        metrics = MetricsCollector(db)
        service = LabelService(db, metrics)
        assignment_repo = LabelAssignmentRepository(db)
        assignments = await assignment_repo.list_for_entity(entity_type, entity_id)
        assignment_map = {assignment.label_id: assignment for assignment in assignments}

        labels = await service.list_entity_labels(entity_type, entity_id)
        label_items = [
            (label_obj, assignment_map.get(label_obj.id)) for label_obj in labels
        ]
        reverse = order == "desc"
        category_names: dict[str, str] = {}
        if sort_by == "category":
            category_ids = {
                label_obj.category_id
                for label_obj, _assignment in label_items
                if label_obj.category_id
            }
            for category_id in category_ids:
                category = await service.get_category(category_id)
                if category:
                    category_names[category_id] = category.name

        def _sort_key(item: tuple[Any, Any]):
            label_obj, assignment = item
            match sort_by:
                case "name":
                    return label_obj.name.lower()
                case "category":
                    return (
                        category_names.get(label_obj.category_id, "")
                        if label_obj.category_id
                        else ""
                    ).lower()
                case _:
                    return assignment.applied_at if assignment else datetime.min

        label_items.sort(key=_sort_key, reverse=reverse)

        total_count = len(label_items)
        if limit <= 0:
            view_items = label_items[offset:]
        else:
            view_items = label_items[offset : offset + limit]

        if sort_by != "category":
            category_ids = {
                label_obj.category_id
                for label_obj, _assignment in view_items
                if label_obj.category_id
            }
            for category_id in category_ids:
                if category_id not in category_names:
                    category = await service.get_category(category_id)
                    if category:
                        category_names[category_id] = category.name

        def _label_links(label_obj) -> dict[str, str]:
            return {
                "self": f"pms label show {label_obj.id}",
                "remove": (
                    f"pms label remove {entity_type} {entity_id} {label_obj.id}"
                ),
            }

        if output_format == "json":
            items = []
            for label_obj, assignment in view_items:
                category_name = (
                    category_names.get(label_obj.category_id)
                    if label_obj.category_id
                    else None
                )
                if view == "overview":
                    payload = {
                        "id": label_obj.id,
                        "name": label_obj.name,
                        "category_id": label_obj.category_id,
                        "category_name": category_name,
                        "color": label_obj.color,
                        "applied_at": _to_iso(assignment.applied_at)
                        if assignment
                        else None,
                        "links": _label_links(label_obj),
                    }
                else:
                    payload = label_obj.to_dict()
                    payload["category_name"] = category_name
                    payload["links"] = _label_links(label_obj)
                    if assignment:
                        payload["assignment"] = {
                            "id": assignment.id,
                            "entity_type": assignment.entity_type,
                            "entity_id": assignment.entity_id,
                            "label_id": assignment.label_id,
                            "applied_by": assignment.applied_by,
                            "applied_at": _to_iso(assignment.applied_at),
                            "created_at": _to_iso(assignment.created_at),
                            "updated_at": _to_iso(assignment.updated_at),
                        }
                items.append(payload)

            base_cmd = f"pms label list-entity {entity_type} {entity_id} --format json"
            if sort_by:
                base_cmd += f" --sort {sort_by}"
            if order:
                base_cmd += f" --order {order}"
            if view != "overview":
                base_cmd += f" --view {view}"
            payload = {
                "items": items,
                "page": _page_payload(total_count, limit, offset),
                "links": _normalize_command_links(
                    {
                        "self": f"{base_cmd} --limit {limit} --offset {offset}",
                        "next": (
                            f"{base_cmd} --limit {limit} --offset {offset + limit}"
                            if limit > 0 and offset + limit < total_count
                            else None
                        ),
                    }
                ),
            }
            click.echo(json.dumps(payload, default=str))
            return

        if output_format == "csv":
            headers = [
                "id",
                "name",
                "category_id",
                "category_name",
                "color",
                "applied_at",
                "applied_by",
            ]
            click.echo(_csv_row(headers))
            for label_obj, assignment in view_items:
                row = [
                    label_obj.id,
                    label_obj.name,
                    label_obj.category_id or "",
                    category_names.get(label_obj.category_id, "")
                    if label_obj.category_id
                    else "",
                    label_obj.color or "",
                    _to_iso(assignment.applied_at) if assignment else "",
                    assignment.applied_by if assignment else "",
                ]
                click.echo(_csv_row(row))
            return

        if not view_items:
            if total_count == 0:
                console.print("[yellow]No labels assigned.[/yellow]")
            else:
                console.print("[yellow]No labels in this page.[/yellow]")
            return

        table = Table(title=f"Labels for {entity_type} {entity_id}")
        table.add_column("Name", style="cyan")
        table.add_column("Category")
        table.add_column("Color")
        table.add_column("Applied")
        for label_obj, assignment in view_items:
            category_label = label_obj.category_id or "-"
            if label_obj.category_id and label_obj.category_id in category_names:
                category_label = category_names[label_obj.category_id]
            table.add_row(
                label_obj.name,
                category_label,
                label_obj.color or "-",
                format_relative(assignment.applied_at) if assignment else "-",
            )
        console.print(table)
        console.print(f"[dim]Total: {total_count}[/dim]")
    finally:
        await db.disconnect()


@label.group("assignment")
def label_assignment() -> None:
    """Manage label assignment history."""
    pass


@label_assignment.command("history")
@click.argument("assignment_id")
@click.option("--limit", type=int, default=20, show_default=True)
@click.option("--offset", type=int, default=0, show_default=True)
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["table", "json", "csv"]),
    default="table",
    show_default=True,
)
@async_command
async def label_assignment_history(
    assignment_id: str,
    limit: int,
    offset: int,
    output_format: str,
) -> None:
    """Show revision history for a label assignment."""
    from pms.core.metrics import MetricsCollector
    from pms.db.connection import init_database
    from pms.services.label_service import LabelService

    db = await init_database()
    try:
        metrics = MetricsCollector(db)
        service = LabelService(db, metrics)

        assignment = await service.get_assignment(assignment_id)
        if assignment is None:
            console.print(f"[red]Label assignment '{assignment_id}' not found[/red]")
            return

        total_count = await service.get_assignment_history_count(assignment_id)
        history = await service.get_assignment_history(
            assignment_id, limit=limit, offset=offset
        )

        if output_format == "json":
            base_cmd = f"pms label assignment history {assignment_id} --format json"
            payload = {
                "assignment": assignment.to_dict(),
                "items": [rev.to_dict() for rev in history],
                "page": _page_payload(total_count, limit, offset),
                "links": _normalize_command_links(
                    {
                        "self": f"{base_cmd} --limit {limit} --offset {offset}",
                        "next": (
                            f"{base_cmd} --limit {limit} --offset {offset + limit}"
                            if limit > 0 and offset + limit < total_count
                            else None
                        ),
                    }
                ),
            }
            click.echo(json.dumps(payload, default=str))
            return

        if output_format == "csv":
            headers = [
                "revision_number",
                "change_type",
                "message",
                "created_by",
                "created_at",
            ]
            click.echo(_csv_row(headers))
            for rev in history:
                click.echo(
                    _csv_row(
                        [
                            str(rev.revision_number),
                            rev.change_type.value,
                            rev.message or "",
                            rev.created_by or "",
                            rev.created_at.isoformat(),
                        ]
                    )
                )
            return

        from pms.utils.time import format_relative

        table = Table(title="Label Assignment History")
        table.add_column("Revision", justify="right")
        table.add_column("Type")
        table.add_column("Message")
        table.add_column("By")
        table.add_column("Created")
        for rev in history:
            table.add_row(
                str(rev.revision_number),
                rev.change_type.value,
                rev.message or "-",
                rev.created_by or "-",
                format_relative(rev.created_at),
            )
        console.print(table)
        console.print(f"[dim]Total: {total_count}[/dim]")
    finally:
        await db.disconnect()


@label.group()
def gate() -> None:
    """Manage label gate rules for workflow transitions."""
    pass


@gate.command("add")
@click.option("--workflow-id", required=True)
@click.option("--entity-type", default="task", show_default=True)
@click.option("--from-state", required=True)
@click.option("--to-state", required=True)
@click.option(
    "--rule-type",
    type=click.Choice(
        ["require_label", "forbid_label", "require_category", "forbid_category"]
    ),
    required=True,
)
@click.option("--label", "label_ref", help="Label ID or name")
@click.option("--category-id", help="Label category ID")
@click.option("--message", help="Override error message")
@async_command
async def label_gate_add(
    workflow_id: str,
    entity_type: str,
    from_state: str,
    to_state: str,
    rule_type: str,
    label_ref: str | None,
    category_id: str | None,
    message: str | None,
) -> None:
    """Add a label gate rule."""
    from pms.core.metrics import MetricsCollector
    from pms.db.connection import init_database
    from pms.models.label_gate_rule import LabelGateRuleType
    from pms.services.label_service import LabelService

    db = await init_database()
    try:
        metrics = MetricsCollector(db)
        service = LabelService(db, metrics)

        label_id = None
        if label_ref:
            label_obj = await service.get_label(label_ref)
            if label_obj is None:
                label_obj = await service.get_label_by_name(label_ref)
            if label_obj is None:
                console.print(f"[red]Label '{label_ref}' not found[/red]")
                return
            label_id = label_obj.id

        rule = await service.add_gate_rule(
            workflow_id=workflow_id,
            entity_type=entity_type,
            from_state=from_state,
            to_state=to_state,
            rule_type=LabelGateRuleType(rule_type),
            label_id=label_id,
            category_id=category_id,
            message=message,
        )
        console.print(f"[green]Added gate rule:[/green] {rule.id}")
    finally:
        await db.disconnect()


@gate.command("list")
@click.option("--workflow-id", required=True)
@click.option("--entity-type", default="task", show_default=True)
@click.option("--from-state", required=True)
@click.option("--to-state", required=True)
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["table", "json", "csv"]),
    default="table",
    show_default=True,
)
@click.option(
    "--view",
    type=click.Choice(["overview", "detail", "trace"]),
    default="overview",
    show_default=True,
    help="Output view profile (overview/detail/trace)",
)
@click.option("--include-history", is_flag=True, help="Include history in JSON")
@click.option("--history-limit", type=int, default=20, show_default=True)
@click.option("--limit", type=int, default=100, show_default=True)
@click.option("--offset", type=int, default=0, show_default=True)
@async_command
async def label_gate_list(
    workflow_id: str,
    entity_type: str,
    from_state: str,
    to_state: str,
    output_format: str,
    view: str,
    include_history: bool,
    history_limit: int,
    limit: int,
    offset: int,
) -> None:
    """List label gate rules."""
    from pms.core.metrics import MetricsCollector
    from pms.db.connection import init_database
    from pms.repositories.label_gate_rule_repository import LabelGateRuleRepository
    from pms.services.label_service import LabelService

    db = await init_database()
    try:
        metrics = MetricsCollector(db)
        service = LabelService(db, metrics)
        if view == "trace":
            include_history = True
        repo = LabelGateRuleRepository(db)
        rules = await service.list_gate_rules(
            workflow_id=workflow_id,
            entity_type=entity_type,
            from_state=from_state,
            to_state=to_state,
        )
        if not rules:
            if output_format == "json":
                payload = {
                    "items": [],
                    "page": _page_payload(0, limit, offset),
                    "links": _normalize_command_links(
                        {
                            "self": (
                                "pms label gate list --workflow-id "
                                f"{workflow_id} --entity-type {entity_type} "
                                f"--from-state {from_state} --to-state {to_state} "
                                "--format json"
                            )
                        }
                    ),
                }
                click.echo(json.dumps(payload, default=str))
                return
            if output_format == "csv":
                headers = [
                    "id",
                    "rule_type",
                    "label_id",
                    "category_id",
                    "message",
                    "workflow_id",
                    "entity_type",
                    "from_state",
                    "to_state",
                ]
                click.echo(_csv_row(headers))
                return
            console.print("[yellow]No gate rules found.[/yellow]")
            return

        total_count = len(rules)
        view_items = rules[offset:] if limit <= 0 else rules[offset : offset + limit]

        if output_format == "json":
            effective_history_limit = history_limit if history_limit > 0 else 1000

            def _rule_links(rule_obj) -> dict[str, str]:
                return {
                    "delete": f"pms label gate delete {rule_obj.id}",
                }

            items = []
            for rule in view_items:
                if view == "overview":
                    payload = {
                        "id": rule.id,
                        "rule_type": rule.rule_type.value,
                        "label_id": rule.label_id,
                        "category_id": rule.category_id,
                        "message": rule.message,
                        "links": _rule_links(rule),
                    }
                else:
                    payload = {
                        "id": rule.id,
                        "workflow_id": rule.workflow_id,
                        "entity_type": rule.entity_type,
                        "from_state": rule.from_state,
                        "to_state": rule.to_state,
                        "rule_type": rule.rule_type.value,
                        "label_id": rule.label_id,
                        "category_id": rule.category_id,
                        "message": rule.message,
                        "created_at": rule.created_at,
                        "updated_at": rule.updated_at,
                        "links": _rule_links(rule),
                    }
                if include_history:
                    history = await repo.get_history(
                        rule.id, limit=effective_history_limit
                    )
                    payload["history"] = [
                        {
                            "revision_number": rev.revision_number,
                            "change_type": rev.change_type.value,
                            "message": rev.message,
                            "created_by": rev.created_by,
                            "created_at": rev.created_at,
                        }
                        for rev in history
                    ]
                items.append(payload)

            base_cmd = (
                "pms label gate list --workflow-id "
                f"{workflow_id} --entity-type {entity_type} "
                f"--from-state {from_state} --to-state {to_state} --format json"
            )
            if view != "overview":
                base_cmd += f" --view {view}"
            payload = {
                "items": items,
                "page": _page_payload(total_count, limit, offset),
                "links": _normalize_command_links(
                    {
                        "self": f"{base_cmd} --limit {limit} --offset {offset}",
                        "next": (
                            f"{base_cmd} --limit {limit} --offset {offset + limit}"
                            if limit > 0 and offset + limit < total_count
                            else None
                        ),
                    }
                ),
            }
            click.echo(json.dumps(payload, default=str))
            return

        if output_format == "csv":
            headers = [
                "id",
                "rule_type",
                "label_id",
                "category_id",
                "message",
                "workflow_id",
                "entity_type",
                "from_state",
                "to_state",
            ]
            click.echo(_csv_row(headers))
            for rule in view_items:
                click.echo(
                    _csv_row(
                        [
                            rule.id,
                            rule.rule_type.value,
                            rule.label_id or "",
                            rule.category_id or "",
                            rule.message or "",
                            rule.workflow_id,
                            rule.entity_type,
                            rule.from_state,
                            rule.to_state,
                        ]
                    )
                )
            return

        from pms.utils.time import format_relative

        table = Table(title="Label Gate Rules")
        table.add_column("ID")
        table.add_column("Type")
        table.add_column("Label/Category")
        table.add_column("Message")
        table.add_column("Updated")
        for rule in view_items:
            target = rule.label_id or rule.category_id or "-"
            table.add_row(
                rule.id,
                rule.rule_type.value,
                target,
                rule.message or "",
                format_relative(rule.updated_at),
            )
        console.print(table)
    finally:
        await db.disconnect()


