@cli.group("custom-field")
def custom_field() -> None:
    """Manage custom field definitions and values."""
    pass


@custom_field.command("create")
@click.argument("name")
@click.option("--entity-type", required=True, help="Entity type (task, project, etc.)")
@click.option(
    "--type",
    "field_type",
    required=True,
    help="Field type (text, number, boolean, date, datetime, enum, json, url)",
)
@click.option("-d", "--description", help="Field description")
@click.option(
    "--option",
    "options",
    multiple=True,
    help="Enum option (repeat for multiple values)",
)
@click.option("--required", is_flag=True, help="Mark field as required")
@async_command
async def custom_field_create(
    name: str,
    entity_type: str,
    field_type: str,
    description: str | None,
    options: tuple[str, ...],
    required: bool,
) -> None:
    """Create a custom field definition."""
    from pms.core.metrics import MetricsCollector
    from pms.db.connection import init_database
    from pms.models.custom_field import CustomFieldType
    from pms.services.custom_field_service import CustomFieldService

    db = await init_database()
    try:
        metrics = MetricsCollector(db)
        service = CustomFieldService(db, metrics)
        try:
            parsed_type = CustomFieldType(field_type)
        except ValueError:
            options_list = ", ".join(ft.value for ft in CustomFieldType)
            console.print(f"[red]Invalid field type.[/red] Use: {options_list}")
            return

        definition = await service.create_definition(
            name=name,
            entity_type=entity_type,
            field_type=parsed_type,
            description=description,
            options=list(options),
            is_required=required,
        )
        console.print(f"[green]Created custom field:[/green] {definition.name}")
        console.print(f"[dim]ID: {definition.id}[/dim]")
    finally:
        await db.disconnect()


@custom_field.command("list")
@click.option("--entity-type", help="Filter by entity type")
@click.option("--include-archived", is_flag=True, help="Include archived fields")
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["table", "json", "csv"]),
    default="table",
    show_default=True,
)
@click.option(
    "--view",
    type=click.Choice(["overview", "detail", "trace"]),
    default="overview",
    show_default=True,
)
@click.option("--include-history", is_flag=True, help="Include history in JSON")
@click.option("--history-limit", type=int, default=20, show_default=True)
@click.option("--limit", type=int, default=100, show_default=True)
@click.option("--offset", type=int, default=0, show_default=True)
@async_command
async def custom_field_list(
    entity_type: str | None,
    include_archived: bool,
    output_format: str,
    view: str,
    include_history: bool,
    history_limit: int,
    limit: int,
    offset: int,
) -> None:
    """List custom field definitions."""
    from pms.core.metrics import MetricsCollector
    from pms.db.connection import init_database
    from pms.repositories.custom_field_repository import CustomFieldRepository
    from pms.services.custom_field_service import CustomFieldService

    db = await init_database()
    try:
        metrics = MetricsCollector(db)
        service = CustomFieldService(db, metrics)
        if view == "trace":
            include_history = True

        definitions = await service.list_definitions(
            entity_type=entity_type, include_archived=include_archived
        )
        total_count = len(definitions)
        view_items = (
            definitions[offset:] if limit <= 0 else definitions[offset : offset + limit]
        )

        if output_format == "json":
            repo = CustomFieldRepository(db)
            effective_history_limit = history_limit if history_limit > 0 else 1000

            def _links(defn) -> dict[str, str]:
                return _normalize_command_links(
                    {
                        "self": f"pms custom-field show {defn.id}",
                        "update": f"pms custom-field update {defn.id}",
                        "delete": f"pms custom-field delete {defn.id}",
                        "restore": f"pms custom-field restore {defn.id}",
                    }
                )

            items = []
            for defn in view_items:
                if view == "overview":
                    payload = {
                        "id": defn.id,
                        "name": defn.name,
                        "entity_type": defn.entity_type,
                        "field_type": defn.field_type.value,
                        "is_required": defn.is_required,
                        "updated_at": defn.updated_at,
                        "archived_at": defn.archived_at,
                        "links": _links(defn),
                    }
                else:
                    payload = {
                        "id": defn.id,
                        "name": defn.name,
                        "entity_type": defn.entity_type,
                        "field_type": defn.field_type.value,
                        "description": defn.description,
                        "options": list(defn.options),
                        "is_required": defn.is_required,
                        "created_at": defn.created_at,
                        "updated_at": defn.updated_at,
                        "archived_at": defn.archived_at,
                        "links": _links(defn),
                    }

                if include_history:
                    history = await repo.get_history(
                        defn.id, limit=effective_history_limit
                    )
                    payload["history"] = [
                        {
                            "revision_number": rev.revision_number,
                            "change_type": rev.change_type.value,
                            "message": rev.message,
                            "created_by": rev.created_by,
                            "created_at": rev.created_at,
                        }
                        for rev in history
                    ]

                items.append(payload)

            base_cmd = "pms custom-field list --format json"
            if entity_type:
                base_cmd += f" --entity-type {entity_type}"
            if include_archived:
                base_cmd += " --include-archived"
            if view != "overview":
                base_cmd += f" --view {view}"
            payload = {
                "items": items,
                "page": _page_payload(total_count, limit, offset),
                "links": _normalize_command_links(
                    {
                        "self": f"{base_cmd} --limit {limit} --offset {offset}",
                        "next": (
                            f"{base_cmd} --limit {limit} --offset {offset + limit}"
                            if limit > 0 and offset + limit < total_count
                            else None
                        ),
                    }
                ),
            }
            click.echo(json.dumps(payload, default=str))
            return

        if output_format == "csv":
            headers = [
                "id",
                "name",
                "entity_type",
                "field_type",
                "is_required",
                "updated_at",
                "archived_at",
            ]
            click.echo(_csv_row(headers))
            for defn in view_items:
                click.echo(
                    _csv_row(
                        [
                            defn.id,
                            defn.name,
                            defn.entity_type,
                            defn.field_type.value,
                            "true" if defn.is_required else "false",
                            str(defn.updated_at)[:19] if defn.updated_at else "",
                            str(defn.archived_at)[:19] if defn.archived_at else "",
                        ]
                    )
                )
            return

        from pms.utils.time import format_relative

        table = Table(title="Custom Fields")
        table.add_column("Name", style="cyan")
        table.add_column("Entity")
        table.add_column("Type")
        table.add_column("Required")
        table.add_column("Updated")
        table.add_column("Archived")
        for defn in view_items:
            table.add_row(
                defn.name,
                defn.entity_type,
                defn.field_type.value,
                "yes" if defn.is_required else "no",
                format_relative(defn.updated_at),
                format_relative(defn.archived_at),
            )
        console.print(table)
        console.print(f"[dim]Total: {total_count}[/dim]")
    finally:
        await db.disconnect()


@custom_field.command("show")
@click.argument("field_ref")
@click.option("--entity-type", help="Entity type when using a name reference")
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json", "csv"]),
    default="text",
    show_default=True,
)
@click.option(
    "--view",
    type=click.Choice(["overview", "detail", "trace"]),
    default="detail",
    show_default=True,
)
@click.option("--include-history", is_flag=True, help="Include history in JSON")
@click.option("--history-limit", type=int, default=20, show_default=True)
@async_command
async def custom_field_show(
    field_ref: str,
    entity_type: str | None,
    output_format: str,
    view: str,
    include_history: bool,
    history_limit: int,
) -> None:
    """Show custom field definition details."""
    from pms.core.metrics import MetricsCollector
    from pms.db.connection import init_database
    from pms.repositories.custom_field_repository import CustomFieldRepository
    from pms.services.custom_field_service import CustomFieldService
    from pms.utils.time import format_relative

    if view == "trace":
        include_history = True

    db = await init_database()
    try:
        metrics = MetricsCollector(db)
        service = CustomFieldService(db, metrics)
        repo = CustomFieldRepository(db)

        definition = await service.get_definition(field_ref, include_archived=True)
        if definition is None and entity_type:
            definition = await service.get_definition_by_name(
                field_ref, entity_type, include_archived=True
            )
        if definition is None:
            console.print(f"[red]Custom field '{field_ref}' not found[/red]")
            return

        if output_format == "json":
            payload = {
                "id": definition.id,
                "name": definition.name,
                "entity_type": definition.entity_type,
                "field_type": definition.field_type.value,
                "description": definition.description,
                "options": list(definition.options),
                "is_required": definition.is_required,
                "created_at": definition.created_at,
                "updated_at": definition.updated_at,
                "archived_at": definition.archived_at,
                "links": _normalize_command_links(
                    {
                        "update": f"pms custom-field update {definition.id}",
                        "delete": f"pms custom-field delete {definition.id}",
                        "restore": f"pms custom-field restore {definition.id}",
                    }
                ),
            }
            if include_history:
                history = await repo.get_history(
                    definition.id, limit=history_limit if history_limit > 0 else 1000
                )
                payload["history"] = [
                    {
                        "revision_number": rev.revision_number,
                        "change_type": rev.change_type.value,
                        "message": rev.message,
                        "created_by": rev.created_by,
                        "created_at": rev.created_at,
                    }
                    for rev in history
                ]
            click.echo(json.dumps(payload, default=str))
            return

        if output_format == "csv":
            headers = [
                "id",
                "name",
                "entity_type",
                "field_type",
                "description",
                "options",
                "is_required",
                "created_at",
                "updated_at",
                "archived_at",
            ]
            click.echo(_csv_row(headers))
            click.echo(
                _csv_row(
                    [
                        definition.id,
                        definition.name,
                        definition.entity_type,
                        definition.field_type.value,
                        definition.description or "",
                        json.dumps(list(definition.options)),
                        "true" if definition.is_required else "false",
                        str(definition.created_at)[:19]
                        if definition.created_at
                        else "",
                        str(definition.updated_at)[:19]
                        if definition.updated_at
                        else "",
                        str(definition.archived_at)[:19]
                        if definition.archived_at
                        else "",
                    ]
                )
            )
            return

        console.print(f"[bold cyan]{definition.name}[/bold cyan]")
        console.print(f"[dim]ID: {definition.id}[/dim]")
        console.print(f"Entity: {definition.entity_type}")
        console.print(f"Type: {definition.field_type.value}")
        console.print(f"Required: {'yes' if definition.is_required else 'no'}")
        if definition.description:
            console.print(f"Description: {definition.description}")
        if definition.options:
            console.print(f"Options: {', '.join(definition.options)}")
        console.print(f"Created: {format_relative(definition.created_at)}")
        console.print(f"Updated: {format_relative(definition.updated_at)}")
        if definition.archived_at:
            console.print(f"Archived: {format_relative(definition.archived_at)}")
    finally:
        await db.disconnect()


@custom_field.command("update")
@click.argument("field_id")
@click.option("--name", help="New name")
@click.option("-d", "--description", help="New description")
@click.option(
    "--type",
    "field_type",
    help="Field type (text, number, boolean, date, datetime, enum, json, url)",
)
@click.option(
    "--option",
    "options",
    multiple=True,
    help="Enum option (repeat for multiple values)",
)
@click.option("--required", "is_required", flag_value=True)
@click.option("--not-required", "is_required", flag_value=False)
@async_command
async def custom_field_update(
    field_id: str,
    name: str | None,
    description: str | None,
    field_type: str | None,
    options: tuple[str, ...],
    is_required: bool | None,
) -> None:
    """Update a custom field definition."""
    from pms.core.metrics import MetricsCollector
    from pms.db.connection import init_database
    from pms.models.custom_field import CustomFieldType
    from pms.services.custom_field_service import CustomFieldService

    db = await init_database()
    try:
        metrics = MetricsCollector(db)
        service = CustomFieldService(db, metrics)

        parsed_type = None
        if field_type is not None:
            try:
                parsed_type = CustomFieldType(field_type)
            except ValueError:
                options_list = ", ".join(ft.value for ft in CustomFieldType)
                console.print(f"[red]Invalid field type.[/red] Use: {options_list}")
                return

        definition = await service.update_definition(
            field_id,
            name=name,
            description=description,
            field_type=parsed_type,
            options=list(options) if options else None,
            is_required=is_required,
        )
        if definition is None:
            console.print(f"[red]Custom field '{field_id}' not found[/red]")
            return
        console.print(f"[green]Updated custom field:[/green] {definition.name}")
    finally:
        await db.disconnect()


@custom_field.command("delete")
@click.argument("field_id")
@async_command
async def custom_field_delete(field_id: str) -> None:
    """Delete (archive) a custom field definition."""
    from pms.core.metrics import MetricsCollector
