@custom_field.group("value")
def custom_field_value() -> None:
    """Manage custom field values."""
    pass


@custom_field_value.command("set")
@click.argument("field_ref")
@click.option("--entity-type", required=True)
@click.option("--entity-id", required=True)
@click.option("--value", "value_raw", help="Value as string")
@click.option(
    "--value-json",
    "value_json",
    help="Value as JSON string (for json/number/boolean)",
)
@click.option("--created-by", help="Actor setting the value")
@click.option("--source", help="Source system or workflow")
@click.option("--metadata-json", help="Additional metadata as JSON")
@async_command
async def custom_field_value_set(
    field_ref: str,
    entity_type: str,
    entity_id: str,
    value_raw: str | None,
    value_json: str | None,
    created_by: str | None,
    source: str | None,
    metadata_json: str | None,
) -> None:
    """Set a custom field value for an entity."""
    from pms.core.metrics import MetricsCollector
    from pms.db.connection import init_database
    from pms.services.custom_field_service import CustomFieldService

    if value_raw is None and value_json is None:
        _emit_cli_error("Provide --value or --value-json", output_format="text")
    if value_raw is not None and value_json is not None:
        _emit_cli_error("Use --value or --value-json, not both", output_format="text")

    value: Any = value_raw
    if value_json is not None:
        try:
            value = json.loads(value_json)
        except json.JSONDecodeError:
            _emit_cli_error("Invalid JSON in --value-json", output_format="text")

    metadata: dict[str, Any] | None = None
    if metadata_json:
        try:
            metadata = json.loads(metadata_json)
        except json.JSONDecodeError:
            _emit_cli_error("Invalid JSON in --metadata-json", output_format="text")

    db = await init_database()
    try:
        metrics = MetricsCollector(db)
        service = CustomFieldService(db, metrics)
        item = await service.set_value(
            field_ref,
            entity_type=entity_type,
            entity_id=entity_id,
            value=value,
            created_by=created_by,
            source=source,
            metadata=metadata,
        )
        console.print(
            f"[green]Set custom field:[/green] {item.definition.name} -> {entity_type} {entity_id}"
        )
        console.print(f"[dim]Value ID: {item.value.id}[/dim]")
    finally:
        await db.disconnect()


@custom_field_value.command("list")
@click.option("--entity-type", help="Filter by entity type")
@click.option("--entity-id", help="Filter by entity ID")
@click.option("--field-id", help="List values for a field definition")
@click.option("--include-history", is_flag=True, help="Include history")
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["table", "json", "csv"]),
    default="table",
    show_default=True,
)
@click.option(
    "--view",
    type=click.Choice(["overview", "detail", "trace"]),
    default="overview",
    show_default=True,
)
@click.option("--limit", type=int, default=100, show_default=True)
@click.option("--offset", type=int, default=0, show_default=True)
@async_command
async def custom_field_value_list(
    entity_type: str | None,
    entity_id: str | None,
    field_id: str | None,
    include_history: bool,
    output_format: str,
    view: str,
    limit: int,
    offset: int,
) -> None:
    """List custom field values for an entity or field."""
    from pms.core.metrics import MetricsCollector
    from pms.db.connection import init_database
    from pms.services.custom_field_service import CustomFieldService
    from pms.utils.time import format_relative

    if view == "trace":
        include_history = True

    if field_id is None and (entity_type is None or entity_id is None):
        _emit_cli_error(
            "Provide --field-id or --entity-type + --entity-id",
            output_format="json" if output_format == "json" else "text",
        )
    if field_id is not None and (entity_type or entity_id):
        _emit_cli_error(
            "Use --field-id or --entity-type + --entity-id, not both",
            output_format="json" if output_format == "json" else "text",
        )

    db = await init_database()
    try:
        metrics = MetricsCollector(db)
        service = CustomFieldService(db, metrics)

        if field_id:
            page = await service.list_values_for_field(
                field_id, limit=limit, offset=offset
            )
        else:
            page = await service.list_values_for_entity(
                entity_type=entity_type or "",
                entity_id=entity_id or "",
                include_history=include_history,
                limit=limit,
                offset=offset,
            )

        if output_format == "json":
            items = []
            for item in page.items:
                definition = item.definition.to_dict() if item.definition else None
                value_payload = item.value.to_dict()
                if view == "overview":
                    value_payload = {
                        "id": item.value.id,
                        "field_id": item.value.field_id,
                        "entity_type": item.value.entity_type,
                        "entity_id": item.value.entity_id,
                        "value": item.value.value,
                        "created_at": item.value.created_at,
                    }
                items.append(
                    {
                        "definition": definition,
                        "value": value_payload,
                    }
                )

            base_cmd = "pms custom-field value list --format json"
            if field_id:
                base_cmd += f" --field-id {field_id}"
            else:
                base_cmd += f" --entity-type {entity_type} --entity-id {entity_id}"
                if include_history:
                    base_cmd += " --include-history"
            if view != "overview":
                base_cmd += f" --view {view}"
            payload = {
                "items": items,
                "page": _page_payload(page.total_count, limit, offset),
                "links": _normalize_command_links(
                    {
                        "self": f"{base_cmd} --limit {limit} --offset {offset}",
                        "next": (
                            f"{base_cmd} --limit {limit} --offset {offset + limit}"
                            if limit > 0 and offset + limit < page.total_count
                            else None
                        ),
                    }
                ),
            }
            click.echo(json.dumps(payload, default=str))
            return

        if output_format == "csv":
            headers = [
                "value_id",
                "field_id",
                "field_name",
                "entity_type",
                "entity_id",
                "value",
                "created_at",
                "created_by",
            ]
            click.echo(_csv_row(headers))
            for item in page.items:
                field_name = item.definition.name if item.definition else ""
                click.echo(
                    _csv_row(
                        [
                            item.value.id,
                            item.value.field_id,
                            field_name,
                            item.value.entity_type,
                            item.value.entity_id,
                            json.dumps(item.value.value),
                            _to_iso(item.value.created_at) or "",
                            item.value.created_by or "",
                        ]
                    )
                )
            return

        table = Table(title="Custom Field Values")
        table.add_column("Field", style="cyan")
        table.add_column("Type")
        table.add_column("Value")
        table.add_column("Updated")
        table.add_column("By")
        for item in page.items:
            field_name = (
                item.definition.name if item.definition else item.value.field_id
            )
            field_type = item.definition.field_type.value if item.definition else "-"
            value_str = json.dumps(item.value.value)
            table.add_row(
                field_name,
                field_type,
                value_str,
                format_relative(item.value.created_at),
                item.value.created_by or "-",
            )
        console.print(table)
        console.print(f"[dim]Total: {page.total_count}[/dim]")
    finally:
        await db.disconnect()


