@cli.group()
def comment() -> None:
    """Manage comments and mentions."""
    pass


@comment.command("add")
@click.argument("entity_type")
@click.argument("entity_id")
@click.argument("body")
@click.option("--by", "created_by", required=True, help="Comment author")
@click.option(
    "--mention",
    "mentions",
    multiple=True,
    help="Explicit mention (repeatable)",
)
@click.option("--metadata-json", help="Comment metadata as JSON")
@click.option("--watch", is_flag=True, help="Watch this entity after commenting")
@async_command
async def comment_add(
    entity_type: str,
    entity_id: str,
    body: str,
    created_by: str,
    mentions: tuple[str, ...],
    metadata_json: str | None,
    watch: bool,
) -> None:
    """Add a comment to an entity."""
    from pms.core.metrics import MetricsCollector
    from pms.db.connection import init_database
    from pms.services.comment_service import CommentService

    metadata: dict[str, Any] | None = None
    if metadata_json:
        try:
            metadata = json.loads(metadata_json)
        except json.JSONDecodeError:
            _emit_cli_error("Invalid JSON in --metadata-json", output_format="text")

    db = await init_database()
    try:
        metrics = MetricsCollector(db)
        service = CommentService(db, metrics)
        try:
            item = await service.add_comment(
                entity_type=entity_type,
                entity_id=entity_id,
                body=body,
                created_by=created_by,
                mentions=list(mentions),
                metadata=metadata,
                watch=watch,
            )
        except ValueError as exc:
            console.print(f"[red]{exc}[/red]")
            return
        console.print(
            f"[green]Added comment:[/green] {item.comment.id} on {entity_type} {entity_id}"
        )
        if item.mentions:
            mention_list = ", ".join(m.mention for m in item.mentions)
            console.print(f"[dim]Mentions: {mention_list}[/dim]")
    finally:
        await db.disconnect()


@comment.command("list")
@click.argument("entity_type")
@click.argument("entity_id")
@click.option("--include-archived", is_flag=True)
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["table", "json", "csv"]),
    default="table",
    show_default=True,
)
@click.option(
    "--view",
    type=click.Choice(["overview", "detail", "trace"]),
    default="overview",
    show_default=True,
)
@click.option("--limit", type=int, default=100, show_default=True)
@click.option("--offset", type=int, default=0, show_default=True)
@async_command
async def comment_list(
    entity_type: str,
    entity_id: str,
    include_archived: bool,
    output_format: str,
    view: str,
    limit: int,
    offset: int,
) -> None:
    """List comments for an entity."""
    from pms.core.metrics import MetricsCollector
    from pms.db.connection import init_database
    from pms.services.comment_service import CommentService
    from pms.utils.time import format_relative

    db = await init_database()
    try:
        metrics = MetricsCollector(db)
        service = CommentService(db, metrics)
        try:
            page = await service.list_comments(
                entity_type=entity_type,
                entity_id=entity_id,
                include_archived=include_archived,
                limit=limit,
                offset=offset,
            )
        except ValueError as exc:
            console.print(f"[red]{exc}[/red]")
            return

        if output_format == "json":
            items = []
            for item in page.items:
                mentions = [m.mention for m in item.mentions]
                if view == "overview":
                    payload = {
                        "id": item.comment.id,
                        "created_by": item.comment.created_by,
                        "created_at": item.comment.created_at,
                        "mentions": mentions,
                    }
                else:
                    payload = item.comment.to_dict()
                    payload["mentions"] = mentions
                items.append(payload)

            base_cmd = f"pms comment list {entity_type} {entity_id} --format json"
            if include_archived:
                base_cmd += " --include-archived"
            if view != "overview":
                base_cmd += f" --view {view}"
            payload = {
                "items": items,
                "page": _page_payload(page.total_count, limit, offset),
                "links": _normalize_command_links(
                    {
                        "self": f"{base_cmd} --limit {limit} --offset {offset}",
                        "next": (
                            f"{base_cmd} --limit {limit} --offset {offset + limit}"
                            if limit > 0 and offset + limit < page.total_count
                            else None
                        ),
                    }
                ),
            }
            click.echo(json.dumps(payload, default=str))
            return

        if output_format == "csv":
            headers = [
                "id",
                "entity_type",
                "entity_id",
                "created_by",
                "body",
                "mentions",
                "created_at",
                "archived_at",
            ]
            click.echo(_csv_row(headers))
            for item in page.items:
                mention_list = ",".join(m.mention for m in item.mentions)
                click.echo(
                    _csv_row(
                        [
                            item.comment.id,
                            item.comment.entity_type,
                            item.comment.entity_id,
                            item.comment.created_by,
                            item.comment.body,
                            mention_list,
                            _to_iso(item.comment.created_at) or "",
                            _to_iso(item.comment.archived_at) or "",
                        ]
                    )
                )
            return

        table = Table(title=f"Comments for {entity_type} {entity_id}")
        table.add_column("By")
        table.add_column("Body")
        table.add_column("Mentions")
        table.add_column("Created")
        table.add_column("Archived")
        for item in page.items:
            mention_list = ", ".join(m.mention for m in item.mentions) or "-"
            body = item.comment.body
            if len(body) > 60:
                body = body[:57] + "..."
            table.add_row(
                item.comment.created_by,
                body,
                mention_list,
                format_relative(item.comment.created_at),
                format_relative(item.comment.archived_at),
            )
        console.print(table)
        console.print(f"[dim]Total: {page.total_count}[/dim]")
    finally:
        await db.disconnect()


@comment.command("show")
@click.argument("comment_id")
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json", "csv"]),
    default="text",
    show_default=True,
)
@async_command
async def comment_show(comment_id: str, output_format: str) -> None:
    """Show a comment by ID."""
    from pms.core.metrics import MetricsCollector
    from pms.db.connection import init_database
    from pms.services.comment_service import CommentService
    from pms.utils.time import format_relative

    db = await init_database()
    try:
        metrics = MetricsCollector(db)
        service = CommentService(db, metrics)
        item = await service.get_comment(comment_id, include_archived=True)
        if item is None:
            console.print(f"[red]Comment '{comment_id}' not found[/red]")
            return

        mentions = [m.mention for m in item.mentions]

        if output_format == "json":
            payload = item.comment.to_dict()
            payload["mentions"] = mentions
            click.echo(json.dumps(payload, default=str))
            return

        if output_format == "csv":
            headers = [
                "id",
                "entity_type",
                "entity_id",
                "created_by",
                "body",
                "mentions",
                "created_at",
                "archived_at",
            ]
            click.echo(_csv_row(headers))
            click.echo(
                _csv_row(
                    [
                        item.comment.id,
                        item.comment.entity_type,
                        item.comment.entity_id,
                        item.comment.created_by,
                        item.comment.body,
                        ",".join(mentions),
                        _to_iso(item.comment.created_at) or "",
                        _to_iso(item.comment.archived_at) or "",
                    ]
                )
            )
            return

        console.print(f"[bold cyan]Comment {item.comment.id}[/bold cyan]")
        console.print(f"Entity: {item.comment.entity_type} {item.comment.entity_id}")
        console.print(f"By: {item.comment.created_by}")
        console.print(f"Created: {format_relative(item.comment.created_at)}")
        if item.comment.archived_at:
            console.print(f"Archived: {format_relative(item.comment.archived_at)}")
        if mentions:
            console.print(f"Mentions: {', '.join(mentions)}")
        console.print(f"Body:\n{item.comment.body}")
    finally:
        await db.disconnect()


