@rule.command("create")
@click.argument("name")
@click.argument("event_pattern")
@click.argument("action_type")
@click.option("--description")
@click.option("--aggregate-type")
@click.option("--aggregate-id")
@click.option("--action-payload-json", default="{}", show_default=True)
@click.option("--disable", is_flag=True, help="Create rule disabled")
@click.option("--cooldown-seconds", type=float, default=0.0, show_default=True)
@async_command
async def automation_rule_create(
    name: str,
    event_pattern: str,
    action_type: str,
    description: str | None,
    aggregate_type: str | None,
    aggregate_id: str | None,
    action_payload_json: str,
    disable: bool,
    cooldown_seconds: float,
) -> None:
    """Create an automation rule."""
    from pms.core.metrics import MetricsCollector
    from pms.db.connection import init_database
    from pms.models.automation_rule import AutomationActionType
    from pms.services.automation_rule_service import AutomationRuleService

    try:
        payload = json.loads(action_payload_json or "{}")
    except json.JSONDecodeError:
        _emit_cli_error("Invalid JSON in --action-payload-json", output_format="text")

    try:
        action_enum = AutomationActionType(action_type)
    except ValueError:
        allowed = ", ".join(value.value for value in AutomationActionType)
        _emit_cli_error(f"Invalid action_type. Use: {allowed}", output_format="text")

    db = await init_database()
    try:
        metrics = MetricsCollector(db)
        service = AutomationRuleService(db, metrics)
        try:
            rule_obj = await service.create_rule(
                name=name,
                event_pattern=event_pattern,
                action_type=action_enum,
                action_payload=payload,
                description=description,
                aggregate_type=aggregate_type,
                aggregate_id=aggregate_id,
                enabled=not disable,
                cooldown_seconds=cooldown_seconds,
            )
        except ValueError as exc:
            _emit_cli_error(str(exc), output_format="text")
        console.print(f"[green]Created automation rule:[/green] {rule_obj.id}")
    finally:
        await db.disconnect()


@rule.command("list")
@click.option("--include-archived", is_flag=True)
@click.option("--enabled", type=click.Choice(["true", "false"]))
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["table", "json", "csv"]),
    default="table",
    show_default=True,
)
@click.option("--limit", type=int, default=100, show_default=True)
@click.option("--offset", type=int, default=0, show_default=True)
@async_command
async def automation_rule_list(
    include_archived: bool,
    enabled: str | None,
    output_format: str,
    limit: int,
    offset: int,
) -> None:
    """List automation rules."""
    from pms.core.metrics import MetricsCollector
    from pms.db.connection import init_database
    from pms.services.automation_rule_service import AutomationRuleService
    from pms.utils.time import format_relative

    enabled_filter = None
    if enabled is not None:
        enabled_filter = enabled == "true"

    db = await init_database()
    try:
        metrics = MetricsCollector(db)
        service = AutomationRuleService(db, metrics)
        rules = await service.list_rules(
            include_archived=include_archived,
            enabled=enabled_filter,
        )

        if output_format == "json":
            payload = {
                "items": [rule_obj.to_dict() for rule_obj in rules],
                "total_count": len(rules),
            }
            click.echo(json.dumps(payload, default=str))
            return

        if output_format == "csv":
            headers = [
                "id",
                "name",
                "event_pattern",
                "action_type",
                "enabled",
                "cooldown_seconds",
                "updated_at",
                "archived_at",
            ]
            click.echo(_csv_row(headers))
            for rule_obj in rules:
                click.echo(
                    _csv_row(
                        [
                            rule_obj.id,
                            rule_obj.name,
                            rule_obj.event_pattern,
                            rule_obj.action_type.value,
                            str(rule_obj.enabled),
                            str(rule_obj.cooldown_seconds),
                            _to_iso(rule_obj.updated_at) or "",
                            _to_iso(rule_obj.archived_at) or "",
                        ]
                    )
                )
            return

        table = Table(title="Automation Rules")
        table.add_column("Name")
        table.add_column("Pattern")
        table.add_column("Action")
        table.add_column("Enabled")
        table.add_column("Updated")
        for rule_obj in rules[offset : offset + limit]:
            table.add_row(
                rule_obj.name,
                rule_obj.event_pattern,
                rule_obj.action_type.value,
                "yes" if rule_obj.enabled else "no",
                format_relative(rule_obj.updated_at),
            )
        console.print(table)
        console.print(f"[dim]Total: {len(rules)}[/dim]")
    finally:
        await db.disconnect()


