@rule.command("update")
@click.argument("rule_id")
@click.option("--name")
@click.option("--description")
@click.option("--event-pattern")
@click.option("--aggregate-type")
@click.option("--aggregate-id")
@click.option("--action-type")
@click.option("--action-payload-json")
@click.option("--enable", is_flag=True, help="Enable the rule")
@click.option("--disable", is_flag=True, help="Disable the rule")
@click.option("--cooldown-seconds", type=float)
@async_command
async def automation_rule_update(
    rule_id: str,
    name: str | None,
    description: str | None,
    event_pattern: str | None,
    aggregate_type: str | None,
    aggregate_id: str | None,
    action_type: str | None,
    action_payload_json: str | None,
    enable: bool,
    disable: bool,
    cooldown_seconds: float | None,
) -> None:
    """Update an automation rule."""
    from pms.core.metrics import MetricsCollector
    from pms.db.connection import init_database
    from pms.models.automation_rule import AutomationActionType
    from pms.services.automation_rule_service import AutomationRuleService

    if enable and disable:
        _emit_cli_error(
            "Use either --enable or --disable, not both", output_format="text"
        )

    payload = None
    if action_payload_json is not None:
        try:
            payload = json.loads(action_payload_json)
        except json.JSONDecodeError:
            _emit_cli_error(
                "Invalid JSON in --action-payload-json", output_format="text"
            )

    action_enum = None
    if action_type:
        try:
            action_enum = AutomationActionType(action_type)
        except ValueError:
            allowed = ", ".join(value.value for value in AutomationActionType)
            console.print(f"[red]Invalid action_type. Use: {allowed}[/red]")
            return

    enabled = None
    if enable:
        enabled = True
    if disable:
        enabled = False

    db = await init_database()
    try:
        metrics = MetricsCollector(db)
        service = AutomationRuleService(db, metrics)
        try:
            rule_obj = await service.update_rule(
                rule_id,
                name=name,
                description=description,
                event_pattern=event_pattern,
                aggregate_type=aggregate_type,
                aggregate_id=aggregate_id,
                action_type=action_enum,
                action_payload=payload,
                enabled=enabled,
                cooldown_seconds=cooldown_seconds,
            )
        except ValueError as exc:
            console.print(f"[red]{exc}[/red]")
            return
        if rule_obj is None:
            console.print(f"[red]Automation rule '{rule_id}' not found[/red]")
            return
        console.print(f"[green]Updated automation rule:[/green] {rule_id}")
    finally:
        await db.disconnect()


