@automation.command("run")
@click.option("--event-id", required=True)
@click.option("--rule-id")
@click.option("--dry-run", is_flag=True)
@async_command
async def automation_run(event_id: str, rule_id: str | None, dry_run: bool) -> None:
    """Run automation rules for an event."""
    from pms.core.metrics import MetricsCollector
    from pms.db.connection import init_database
    from pms.services.automation_rule_service import AutomationRuleService

    db = await init_database()
    try:
        metrics = MetricsCollector(db)
        service = AutomationRuleService(db, metrics)
        try:
            results = await service.run_for_event_id(
                event_id,
                rule_id=rule_id,
                dry_run=dry_run,
            )
        except ValueError as exc:
            console.print(f"[red]{exc}[/red]")
            return

        if not results:
            console.print("[yellow]No automation rules matched.[/yellow]")
            return

        table = Table(title="Automation Run Results")
        table.add_column("Rule")
        table.add_column("Status")
        table.add_column("Run ID")
        for result in results:
            table.add_row(
                result.rule.name,
                result.run.status,
                result.run.id,
            )
        console.print(table)
    finally:
        await db.disconnect()


