@click.option("--workflow-id", required=True)
@click.option("--entity-type", default="task", show_default=True)
@click.option("--from-state", required=True)
@click.option("--to-state", required=True)
@click.option("--evidence-type", required=True)
@click.option("--min-count", type=int, default=1, show_default=True)
@click.option("--require-success", is_flag=True, help="Require successful test runs")
@click.option("--message", help="Override error message")
@async_command
async def evidence_gate_add(
    workflow_id: str,
    entity_type: str,
    from_state: str,
    to_state: str,
    evidence_type: str,
    min_count: int,
    require_success: bool,
    message: str | None,
) -> None:
    """Add an evidence gate rule."""
    from pms.core.metrics import MetricsCollector
    from pms.db.connection import init_database
    from pms.services.evidence_gate_service import EvidenceGateService

    db = await init_database()
    try:
        metrics = MetricsCollector(db)
        service = EvidenceGateService(db, metrics)

        rule = await service.add_gate_rule(
            workflow_id=workflow_id,
            entity_type=entity_type,
            from_state=from_state,
            to_state=to_state,
            evidence_type=evidence_type,
            min_count=min_count,
            require_success=require_success,
            message=message,
        )
        console.print(f"[green]Added evidence gate rule:[/green] {rule.id}")
    finally:
        await db.disconnect()


@gate.command("list")
@click.option("--workflow-id", required=True)
@click.option("--entity-type", default="task", show_default=True)
@click.option("--from-state", required=True)
@click.option("--to-state", required=True)
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["table", "json", "csv"]),
    default="table",
    show_default=True,
)
@click.option(
    "--view",
    type=click.Choice(["overview", "detail", "trace"]),
    default="overview",
    show_default=True,
    help="Output view profile (overview/detail/trace)",
)
@click.option("--include-history", is_flag=True, help="Include history in JSON")
@click.option("--history-limit", type=int, default=20, show_default=True)
@click.option("--limit", type=int, default=100, show_default=True)
@click.option("--offset", type=int, default=0, show_default=True)
@async_command
async def evidence_gate_list(
    workflow_id: str,
    entity_type: str,
    from_state: str,
    to_state: str,
    output_format: str,
    view: str,
    include_history: bool,
    history_limit: int,
    limit: int,
    offset: int,
) -> None:
    """List evidence gate rules."""
    from pms.core.metrics import MetricsCollector
    from pms.db.connection import init_database
    from pms.repositories.evidence_gate_rule_repository import (
        EvidenceGateRuleRepository,
    )
    from pms.services.evidence_gate_service import EvidenceGateService

    db = await init_database()
    try:
        metrics = MetricsCollector(db)
        service = EvidenceGateService(db, metrics)
        if view == "trace":
            include_history = True
        repo = EvidenceGateRuleRepository(db)
        rules = await service.list_gate_rules(
            workflow_id=workflow_id,
            entity_type=entity_type,
            from_state=from_state,
            to_state=to_state,
        )
        if not rules:
            if output_format == "json":
                payload = {
                    "items": [],
                    "page": _page_payload(0, limit, offset),
                    "links": _normalize_command_links(
                        {
                            "self": (
                                "pms evidence gate list --workflow-id "
                                f"{workflow_id} --entity-type {entity_type} "
                                f"--from-state {from_state} --to-state {to_state} "
                                "--format json"
                            )
                        }
                    ),
                }
                click.echo(json.dumps(payload, default=str))
                return
            if output_format == "csv":
                headers = [
                    "id",
                    "evidence_type",
                    "min_count",
                    "require_success",
                    "message",
                    "workflow_id",
                    "entity_type",
                    "from_state",
                    "to_state",
                ]
                click.echo(_csv_row(headers))
                return
            console.print("[yellow]No evidence gate rules found.[/yellow]")
            return

        total_count = len(rules)
        view_items = rules[offset:] if limit <= 0 else rules[offset : offset + limit]

        if output_format == "json":
            effective_history_limit = history_limit if history_limit > 0 else 1000

            def _rule_links(rule_obj) -> dict[str, str]:
                return {
                    "delete": f"pms evidence gate delete {rule_obj.id}",
                }

            items = []
            for rule in view_items:
                if view == "overview":
                    payload = {
                        "id": rule.id,
                        "evidence_type": rule.evidence_type,
                        "min_count": rule.min_count,
                        "require_success": rule.require_success,
                        "message": rule.message,
                        "links": _rule_links(rule),
                    }
                else:
                    payload = {
                        "id": rule.id,
                        "workflow_id": rule.workflow_id,
                        "entity_type": rule.entity_type,
                        "from_state": rule.from_state,
                        "to_state": rule.to_state,
                        "evidence_type": rule.evidence_type,
                        "min_count": rule.min_count,
                        "require_success": rule.require_success,
                        "message": rule.message,
                        "created_at": rule.created_at,
                        "updated_at": rule.updated_at,
                        "links": _rule_links(rule),
                    }
                if include_history:
                    history = await repo.get_history(
                        rule.id, limit=effective_history_limit
                    )
                    payload["history"] = [
                        {
                            "revision_number": rev.revision_number,
                            "change_type": rev.change_type.value,
                            "message": rev.message,
                            "created_by": rev.created_by,
                            "created_at": rev.created_at,
                        }
                        for rev in history
                    ]
                items.append(payload)

            base_cmd = (
                "pms evidence gate list --workflow-id "
                f"{workflow_id} --entity-type {entity_type} "
                f"--from-state {from_state} --to-state {to_state} --format json"
            )
            if view != "overview":
                base_cmd += f" --view {view}"
            payload = {
                "items": items,
                "page": _page_payload(total_count, limit, offset),
                "links": _normalize_command_links(
                    {
                        "self": f"{base_cmd} --limit {limit} --offset {offset}",
                        "next": (
                            f"{base_cmd} --limit {limit} --offset {offset + limit}"
                            if limit > 0 and offset + limit < total_count
                            else None
                        ),
                    }
                ),
            }
            click.echo(json.dumps(payload, default=str))
            return

        if output_format == "csv":
            headers = [
                "id",
                "evidence_type",
                "min_count",
                "require_success",
                "message",
                "workflow_id",
                "entity_type",
                "from_state",
                "to_state",
            ]
            click.echo(_csv_row(headers))
            for rule in view_items:
                click.echo(
                    _csv_row(
                        [
                            rule.id,
                            rule.evidence_type,
                            str(rule.min_count),
                            "true" if rule.require_success else "false",
                            rule.message or "",
                            rule.workflow_id,
                            rule.entity_type,
                            rule.from_state,
                            rule.to_state,
                        ]
                    )
                )
            return

        from pms.utils.time import format_relative

        table = Table(title="Evidence Gate Rules")
        table.add_column("ID")
        table.add_column("Evidence")
        table.add_column("Min")
        table.add_column("Require Success")
        table.add_column("Message")
        table.add_column("Updated")
        for rule in view_items:
            table.add_row(
                rule.id,
                rule.evidence_type,
                str(rule.min_count),
                "yes" if rule.require_success else "no",
                rule.message or "",
                format_relative(rule.updated_at),
            )
        console.print(table)
    finally:
        await db.disconnect()


@gate.command("delete")
@click.argument("rule_id")
@async_command
async def evidence_gate_delete(rule_id: str) -> None:
    """Delete an evidence gate rule."""
    from pms.core.metrics import MetricsCollector
    from pms.db.connection import init_database
    from pms.services.evidence_gate_service import EvidenceGateService

    db = await init_database()
    try:
        metrics = MetricsCollector(db)
        service = EvidenceGateService(db, metrics)
        await service.remove_gate_rule(rule_id)
        console.print(f"[yellow]Deleted evidence gate rule[/yellow] {rule_id}")
    finally:
        await db.disconnect()


def _write_env_file(updates: dict[str, str]) -> Path:
    from pms.config.settings import get_env_file_path

    env_path = get_env_file_path()
    env_path.parent.mkdir(parents=True, exist_ok=True)
    lines = env_path.read_text().splitlines() if env_path.exists() else []

    filtered: list[str] = []
    keys = set(updates.keys())
    for line in lines:
        stripped = line.strip()
        if not stripped or stripped.startswith("#") or "=" not in line:
            filtered.append(line)
            continue
        key = line.split("=", 1)[0].strip()
        if key in keys:
            continue
        filtered.append(line)

    for key, value in updates.items():
        filtered.append(f"{key}={value}")

    env_path.write_text("\n".join(filtered).rstrip() + "\n")
    return env_path


@cli.group()
def config() -> None:
    """Manage local PMS configuration."""
    pass


@config.command("show")
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json"]),
    default="text",
    show_default=True,
)
def config_show(output_format: str) -> None:
    """Show resolved configuration."""
    from pms.config import get_settings

    settings = get_settings()
    from pms.config.settings import get_env_file_path

    live_root = settings.data_dir.expanduser().resolve()
    db_path = settings.database_path.expanduser().resolve()
    log_dir = settings.log_dir.expanduser().resolve()
    env_file = get_env_file_path().expanduser().resolve()
    in_workspace = (
        Path.cwd().resolve() in live_root.parents or live_root == Path.cwd().resolve()
    )
    coordination = _runtime_coordination_status()

    payload = _payload_with_normalized_next_steps(
        {
            "paths": {
                "env_file": str(env_file),
                "data_dir": str(live_root),
                "database_path": str(db_path),
                "log_dir": str(log_dir),
            },
            "actor": {
                "current_actor_id": settings.current_actor_id,
            },
            "runtime": {
                "write_mode": settings.write_mode,
                "server_base_url": settings.server_base_url,
                "api_key_path": (
                    str(settings.api_key_path.expanduser().resolve())
                    if settings.api_key_path is not None
                    else None
                ),
                "server": _runtime_server_payload().to_dict(),
                "managed_servers": _managed_runtime_servers(),
                "coordination": coordination.to_dict(),
            },
            "sqlite": {
                "busy_timeout_ms": settings.sqlite_busy_timeout_ms,
                "lock_retry_count": settings.sqlite_lock_retry_count,
                "lock_retry_delay_ms": settings.sqlite_lock_retry_delay_ms,
                "journal_mode": settings.sqlite_journal_mode,
                "synchronous": settings.sqlite_synchronous,
            },
            "safety": {
                "workspace_managed_state": in_workspace,
                "notes": [
                    "Use a dedicated data dir for demos, tests, and destructive experiments.",
                    "Keep live and scratch PMS state in different PMS_DATA_DIR roots.",
                    "Prefer 'pms init --data-dir <dir>' before running standalone scenario scripts.",
                    "Use 'prefer_server' or 'require_server' when multiple writers should converge through one local PMS API process.",
                ],
            },
        },
        *coordination.recommended_next_steps,
    )

    if output_format == "json":
        click.echo(json.dumps(payload))
        return

    console.print(f"Data dir: {live_root}")
    console.print(f"Database: {db_path}")
    console.print(f"Logs: {log_dir}")
    console.print(f"Env file: {env_file}")
    console.print(f"Current actor: {settings.current_actor_id or '-'}")
    console.print("Runtime:")
    console.print(f"  write_mode: {settings.write_mode}")
    console.print(f"  server_base_url: {settings.server_base_url}")
    if settings.api_key_path is not None:
        console.print(f"  api_key_path: {settings.api_key_path.expanduser().resolve()}")
    server_payload = payload["runtime"]["server"]
    coordination_payload = payload["runtime"]["coordination"]
    console.print(f"  coordination_state: {coordination_payload['state']}")
    console.print(f"  coordination_summary: {coordination_payload['summary']}")
    if coordination_payload["reason"]:
        console.print(f"  coordination_reason: {coordination_payload['reason']}")
    recovery_payload = coordination_payload.get("recovery")
    if recovery_payload:
        console.print(f"  recovery_kind: {recovery_payload['kind']}")
        if recovery_payload["summary"]:
            console.print(f"  recovery_summary: {recovery_payload['summary']}")
    if server_payload["checked"]:
        console.print(
            "  server_reachable: " + ("yes" if server_payload["reachable"] else "no")
        )
        if server_payload["status"]:
            console.print(f"  server_status: {server_payload['status']}")
        if server_payload["database"]:
            console.print(f"  server_database: {server_payload['database']}")
        if server_payload["api_key_present"]:
            if server_payload["api_key_source"]:
                console.print(
                    f"  server_api_key_source: {server_payload['api_key_source']}"
                )
            if server_payload["api_key_authorized"] is True:
                console.print("  server_auth: authorized")
            elif server_payload["api_key_authorized"] is False:
                console.print("  server_auth: rejected")
                if server_payload["auth_error"]:
                    console.print(
                        f"  server_auth_error: {server_payload['auth_error']}"
                    )
        if server_payload["error"]:
            console.print(f"  server_error: {server_payload['error']}")
    console.print("SQLite:")
    console.print(f"  busy_timeout_ms: {settings.sqlite_busy_timeout_ms}")
    console.print(f"  lock_retry_count: {settings.sqlite_lock_retry_count}")
    console.print(f"  lock_retry_delay_ms: {settings.sqlite_lock_retry_delay_ms}")
    console.print(f"  journal_mode: {settings.sqlite_journal_mode}")
    console.print(f"  synchronous: {settings.sqlite_synchronous}")
    console.print("Safety:")
    console.print("  Workspace managed state: " + ("yes" if in_workspace else "no"))
    console.print(
        "  Use a separate data dir for demos, tests, and destructive experiments."
    )
    _print_next_steps(*payload["next_steps"])


@config.command("set")
@click.option("--data-dir", type=click.Path(path_type=Path))
@click.option("--database-path", type=click.Path(path_type=Path))
@click.option(
    "--write-mode",
    type=click.Choice(["direct", "prefer_server", "require_server"]),
)
@click.option("--server-url")
@click.option("--current-actor")
def config_set(
    data_dir: Path | None,
    database_path: Path | None,
    write_mode: str | None,
    server_url: str | None,
    current_actor: str | None,
) -> None:
    """Persist configuration values in the resolved env file for this execution context."""
    updates: dict[str, str] = {}
    if data_dir:
        updates["PMS_DATA_DIR"] = str(data_dir)
        if database_path is None:
            updates["PMS_DATABASE_PATH"] = str(Path(data_dir) / "pms.db")
        updates["PMS_LOG_DIR"] = str(Path(data_dir) / "logs")
    if database_path:
        updates["PMS_DATABASE_PATH"] = str(database_path)
        if data_dir is None:
            base_dir = Path(database_path).parent
            updates["PMS_DATA_DIR"] = str(base_dir)
            updates["PMS_LOG_DIR"] = str(base_dir / "logs")
    if write_mode:
        updates["PMS_WRITE_MODE"] = write_mode
    if server_url:
        updates["PMS_SERVER_BASE_URL"] = server_url
    if current_actor:
        updates["PMS_CURRENT_ACTOR_ID"] = current_actor

    if not updates:
        console.print("[yellow]No config values provided.[/yellow]")
        return

    env_path = _write_env_file(updates)
    for key, value in updates.items():
        os.environ[key] = value

    from pms.config.settings import reload_settings

    settings = reload_settings()
    console.print(f"[green]Saved config to env file: {env_path}[/green]")
    console.print(f"Data dir: {settings.data_dir}")
    console.print(f"Database: {settings.database_path}")
    console.print(f"Logs: {settings.log_dir}")
    console.print(f"Current actor: {settings.current_actor_id or '-'}")
    console.print(f"Write mode: {settings.write_mode}")
    console.print(f"Server URL: {settings.server_base_url}")


@cli.group()
def runtime() -> None:
    """Manage the preferred local server-backed runtime and recovery workflow."""
    pass


@runtime.command(
    "prefer-server",
    epilog=_help_epilog(
        f"runtime prefer-server --host {LOCAL_SERVER_DEFAULT_HOST} --port {LOCAL_RUNTIME_DEFAULT_PORT}",
        "config show --format json",
        "start --format json",
    ),
)
@click.option(
    "--host",
    default=LOCAL_SERVER_DEFAULT_HOST,
    show_default=True,
    help="Host to bind the managed local PMS server.",
)
@click.option(
    "--port",
    default=LOCAL_RUNTIME_DEFAULT_PORT,
    type=int,
    show_default=True,
    help="Port for the managed local PMS server.",
)
@click.option(
    "--install-client/--no-install-client",
    default=True,
    show_default=True,
    help="Install or refresh the Rust fast-path client after runtime bootstrap.",
)
@click.option(
    "--sign/--no-sign",
    default=True,
    show_default=True,
    help="Sign the installed Rust client wrapper with the current server URL.",
)
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json"]),
    default="text",
    show_default=True,
)
@async_command
async def runtime_prefer_server(
    host: str,
    port: int,
    install_client: bool,
    sign: bool,
    output_format: str,
) -> None:
    """Bootstrap the preferred local server-backed runtime.

    Persists `PMS_WRITE_MODE=prefer_server`, `PMS_SERVER_BASE_URL`, and
    `PMS_API_KEY_PATH` into the resolved env file for this execution context,
    ensures a managed local server is reachable, and optionally installs the
    Rust fast-path client.
    """
    from pms.config.settings import get_settings, reload_settings
    from pms.runtime.local_server import ensure_local_server

    settings = get_settings()
    bootstrap = ensure_local_server(
        data_dir=settings.data_dir,
        database_path=settings.database_path,
        log_dir=settings.log_dir,
        host=host,
        port=port,
    )
    if not bootstrap.reachable:
        raise click.ClickException(
            f"Local PMS server did not become ready. Check log: {bootstrap.log_file}"
        )

    server_url = bootstrap.server_url
    key_material = await _ensure_local_admin_key()
    key_path = Path(key_material.key_path)
    os.environ.pop("PMS_API_KEY", None)
    os.environ.pop("PMS_WRITE_MODE", None)
    os.environ.pop("PMS_SERVER_BASE_URL", None)
    os.environ.pop("PMS_API_KEY_PATH", None)

    env_path = _write_env_file(
        {
            "PMS_WRITE_MODE": "prefer_server",
            "PMS_SERVER_BASE_URL": server_url,
            "PMS_API_KEY_PATH": str(key_path.resolve()),
        }
    )
    updated_settings = reload_settings()

    installed_client_path = None
    if install_client:
        installed_client_path = _install_pms_client_binary(
            server_url=server_url,
            sign=sign,
        )

    payload = _payload_with_normalized_next_steps(
        {
            "runtime": {
                "write_mode": updated_settings.write_mode,
                "server_base_url": updated_settings.server_base_url,
                "api_key_path": (
                    str(updated_settings.api_key_path.expanduser().resolve())
                    if updated_settings.api_key_path is not None
                    else None
                ),
                "managed_servers": _managed_runtime_servers(),
                "coordination": _runtime_coordination_status().to_dict(),
            },
            "server": {
                "server_url": server_url,
                "reachable": bootstrap.reachable,
                "started_now": bootstrap.started_now,
                "pid": bootstrap.pid,
                "pid_file": bootstrap.pid_file,
                "log_file": bootstrap.log_file,
            },
            "auth": {
                "key_id": key_material.key_id,
                "prefix": key_material.prefix,
                "key_path": key_material.key_path,
                "reused_existing": key_material.reused_existing,
            },
            "client": {
                "installed": installed_client_path is not None,
                "path": installed_client_path,
            },
            "config_path": str(env_path.resolve()),
        },
        "export PMS_API_KEY=$(cat .pms-admin-key)",
        "start --format json",
        "config show --format json",
        (
            f"./.bin/pms-client --server {server_url} start --format json"
            if installed_client_path is not None
            else "dashboard --format json"
        ),
    )

    if output_format == "json":
        click.echo(json.dumps(payload))
        return

    console.print("[green]Preferred local server-backed runtime enabled.[/green]")
    console.print(f"Server URL: {server_url}")
    console.print(
        "Server status: "
        + ("started now" if bootstrap.started_now else "already reachable")
    )
    console.print(f"PID file: {bootstrap.pid_file}")
    console.print(f"Log file: {bootstrap.log_file}")
    console.print(f"Key path: {key_material.key_path}")
    console.print(f"Config saved to env file: {env_path.resolve()}")
    if installed_client_path is not None:
        console.print(f"Installed client: {installed_client_path}")
    _print_next_steps(*payload["next_steps"])


@runtime.command("stop-local-server")
@click.option("--port", default=LOCAL_RUNTIME_DEFAULT_PORT, type=int, show_default=True)
def runtime_stop_local_server(port: int) -> None:
    """Stop a managed local PMS server started for the preferred runtime."""
    from pms.config.settings import get_settings
    from pms.runtime.local_server import stop_local_server

    settings = get_settings()
    stopped = stop_local_server(data_dir=settings.data_dir, port=port)
    if stopped:
        console.print("[green]Stopped managed local PMS server.[/green]")
    else:
        console.print(
            "[yellow]No managed local PMS server was tracked for that port.[/yellow]"
        )


@runtime.command(
    "status",
    epilog=_help_epilog(
        "runtime status",
        "runtime status --format json",
        "runtime cleanup",
    ),
)
@click.option(
    "--host",
    default=LOCAL_SERVER_DEFAULT_HOST,
    show_default=True,
    help="Host to inspect for tracked managed local PMS servers.",
)
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json"]),
    default="text",
    show_default=True,
)
def runtime_status(host: str, output_format: str) -> None:
    """Show tracked managed local PMS server slots and their health state."""
    from pms.config.settings import get_settings
    from pms.runtime.local_server import (
        list_managed_local_servers,
        list_unmanaged_local_server_processes,
    )

    settings = get_settings()
    statuses = list_managed_local_servers(data_dir=settings.data_dir, host=host)
    unmanaged_processes = list_unmanaged_local_server_processes(
        data_dir=settings.data_dir,
        database_path=settings.database_path,
        host=host,
    )
    coordination = _runtime_coordination_status()
    server_payload = _runtime_server_payload()

    if output_format == "json":
        payload = _payload_with_normalized_next_steps(
            {
                "items": [
                    {
                        "port": item.port,
                        "server_url": item.server_url,
                        "pid": item.pid,
                        "tracked": item.tracked,
                        "running": item.running,
                        "reachable": item.reachable,
                        "pid_file": item.pid_file,
                        "log_file": item.log_file,
                        "error": item.error,
                    }
                    for item in statuses
                ],
                "count": len(statuses),
                "host": host,
                "unmanaged_local_processes": [
                    {
                        "pid": item.pid,
                        "port": item.port,
                        "kind": item.kind,
                        "command": item.command,
                    }
                    for item in unmanaged_processes
                ],
                "coordination": coordination.to_dict(),
            },
            "runtime cleanup",
            "config show --format json",
        )
        click.echo(json.dumps(payload))
        return

    def _print_runtime_coordination_summary() -> None:
        console.print(f"Coordination: {coordination.state}")
        console.print(f"Summary: {coordination.summary}")
        if coordination.reason:
            console.print(f"Reason: {coordination.reason}")
        if server_payload.api_key_present and server_payload.api_key_source:
            console.print(f"API key source: {server_payload.api_key_source}")
        if server_payload.api_key_authorized is True:
            console.print("Server auth: authorized")
        elif server_payload.api_key_authorized is False:
            console.print("Server auth: rejected")
            if server_payload.auth_error:
                console.print(f"Server auth error: {server_payload.auth_error}")

    if unmanaged_processes:
        console.print(
            f"[yellow]Detected {len(unmanaged_processes)} unmanaged local PMS server process(es).[/yellow]"
        )
        console.print(
            "Use `uv run pms runtime cleanup --include-unmanaged-local --format json` "
            "to stop workspace-local leftovers explicitly."
        )

    if not statuses:
        console.print(
            "[yellow]No managed local PMS servers are currently tracked.[/yellow]"
        )
        _print_runtime_coordination_summary()
        _print_next_steps(
            f"runtime prefer-server --host {LOCAL_SERVER_DEFAULT_HOST} --port {LOCAL_RUNTIME_DEFAULT_PORT}"
        )
        return

    table = Table(title="Managed Local PMS Servers")
    table.add_column("Port", style="cyan")
    table.add_column("PID")
    table.add_column("Running")
    table.add_column("Reachable")
    table.add_column("Log")
    for item in statuses:
        table.add_row(
            str(item.port),
            str(item.pid) if item.pid is not None else "-",
            "yes" if item.running else "no",
            "yes" if item.reachable else "no",
            item.log_file,
        )
    console.print(table)
    _print_runtime_coordination_summary()
    _print_next_steps("runtime cleanup", "config show --format json")


@runtime.command("cleanup")
@click.option("--host", default=LOCAL_SERVER_DEFAULT_HOST, show_default=True)
@click.option(
    "--include-unmanaged-local/--managed-only",
    default=False,
    show_default=True,
    help="Also stop workspace-local PMS server processes that are not tracked as managed slots.",
)
@click.option(
    "--unmanaged-port",
    "unmanaged_ports",
    type=int,
    multiple=True,
    help="Only stop unmanaged local PMS server processes on these ports.",
)
@click.option(
    "--unmanaged-pid",
    "unmanaged_pids",
    type=int,
    multiple=True,
    help="Only stop unmanaged local PMS server processes with these PIDs.",
)
@click.option(
    "--preserve-preferred-managed/--stop-all-managed",
    default=True,
    show_default=True,
    help="Preserve the configured preferred managed local server unless you explicitly stop all tracked managed servers.",
)
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json"]),
    default="text",
    show_default=True,
)
def runtime_cleanup(
    host: str,
    include_unmanaged_local: bool,
    unmanaged_ports: tuple[int, ...],
    unmanaged_pids: tuple[int, ...],
    preserve_preferred_managed: bool,
    output_format: str,
) -> None:
    """Stop and clear tracked managed local PMS servers."""
    from pms.config.settings import get_settings
    from pms.runtime.local_server import (
        cleanup_managed_local_servers,
        cleanup_unmanaged_local_server_processes,
    )

    settings = get_settings()
    unmanaged_port_filter = set(unmanaged_ports) or None
    unmanaged_pid_filter = set(unmanaged_pids) or None
    if (unmanaged_port_filter or unmanaged_pid_filter) and not include_unmanaged_local:
        _emit_cli_error(
            "Targeted unmanaged cleanup filters require --include-unmanaged-local.",
            output_format=output_format,
        )
        raise click.exceptions.Exit(2)
    preserve_server_url = (
        settings.server_base_url if preserve_preferred_managed else None
    )
    cleaned, preserved, failed_managed = cleanup_managed_local_servers(
        data_dir=settings.data_dir,
        host=host,
        preserve_server_url=preserve_server_url,
    )
    cleaned_unmanaged = (
        cleanup_unmanaged_local_server_processes(
            data_dir=settings.data_dir,
            database_path=settings.database_path,
            host=host,
            ports=unmanaged_port_filter,
            pids=unmanaged_pid_filter,
        )
        if include_unmanaged_local
        else []
    )
    coordination = _runtime_coordination_status()

    if output_format == "json":
        payload = _payload_with_normalized_next_steps(
            {
                "stopped": [
                    {
                        "port": item.port,
                        "server_url": item.server_url,
                        "pid": item.pid,
                        "reachable": item.reachable,
                        "pid_file": item.pid_file,
                        "log_file": item.log_file,
                    }
                    for item in cleaned
                ],
                "count": len(cleaned),
                "host": host,
                "preserved_managed": [
                    {
                        "port": item.port,
                        "server_url": item.server_url,
                        "pid": item.pid,
                        "reachable": item.reachable,
                        "pid_file": item.pid_file,
                        "log_file": item.log_file,
                    }
                    for item in preserved
                ],
                "failed_managed": [
                    {
                        "port": item.port,
                        "server_url": item.server_url,
                        "pid": item.pid,
                        "reachable": item.reachable,
                        "pid_file": item.pid_file,
                        "log_file": item.log_file,
                        "error": item.error,
                    }
                    for item in failed_managed
                ],
                "stopped_unmanaged": [
                    {
                        "pid": item.pid,
                        "port": item.port,
                        "kind": item.kind,
                        "command": item.command,
                    }
                    for item in cleaned_unmanaged
                ],
                "unmanaged_filters": {
                    "ports": sorted(unmanaged_port_filter)
                    if unmanaged_port_filter
                    else [],
                    "pids": sorted(unmanaged_pid_filter)
                    if unmanaged_pid_filter
                    else [],
                },
                "coordination": coordination.to_dict(),
            },
            "runtime status --format json",
            f"runtime prefer-server --host {LOCAL_SERVER_DEFAULT_HOST} --port {LOCAL_RUNTIME_DEFAULT_PORT}",
            *coordination.recommended_next_steps,
        )
        click.echo(json.dumps(payload))
        return

    if not cleaned:
        console.print("[yellow]No managed local PMS servers needed cleanup.[/yellow]")
    else:
        console.print(
            f"[green]Cleaned up {len(cleaned)} managed local PMS server(s).[/green]"
        )
    if preserved:
        console.print(
            f"[yellow]Preserved {len(preserved)} preferred managed local PMS server(s).[/yellow]"
        )
    if failed_managed:
        console.print(
            f"[red]Failed to stop {len(failed_managed)} managed local PMS server(s); runtime state was preserved for retry.[/red]"
        )
    if include_unmanaged_local:
        if cleaned_unmanaged:
            console.print(
                f"[green]Stopped {len(cleaned_unmanaged)} unmanaged local PMS server process(es).[/green]"
            )
        else:
            console.print(
                "[yellow]No unmanaged local PMS server processes needed cleanup.[/yellow]"
            )
    _print_next_steps(
        "runtime status --format json",
        f"runtime prefer-server --host {LOCAL_SERVER_DEFAULT_HOST} --port {LOCAL_RUNTIME_DEFAULT_PORT}",
    )


@cli.command("init")
@click.option("--data-dir", type=click.Path(path_type=Path))
@click.option("--database-path", type=click.Path(path_type=Path))
@click.option("--reset", is_flag=True, help="Delete existing local database first")
@click.option("--force", is_flag=True, help="Skip confirmation when resetting")
@async_command
async def init_cmd(
    data_dir: Path | None,
    database_path: Path | None,
    reset: bool,
    force: bool,
) -> None:
    """Initialize PMS database and configuration."""
    from pms.config.settings import get_settings, reload_settings
    from pms.db.connection import init_database

    updates: dict[str, str] = {}
    if data_dir:
        updates["PMS_DATA_DIR"] = str(data_dir)
        if database_path is None:
            updates["PMS_DATABASE_PATH"] = str(Path(data_dir) / "pms.db")
        updates["PMS_LOG_DIR"] = str(Path(data_dir) / "logs")
    if database_path:
        updates["PMS_DATABASE_PATH"] = str(database_path)
        if data_dir is None:
            base_dir = Path(database_path).parent
            updates["PMS_DATA_DIR"] = str(base_dir)
            updates["PMS_LOG_DIR"] = str(base_dir / "logs")

    if updates:
        env_path = _write_env_file(updates)
        for key, value in updates.items():
            os.environ[key] = value
        settings = reload_settings()
        console.print(f"[dim]Config: {env_path}[/dim]")
    else:
        settings = get_settings()

    settings.ensure_data_dir()
    if reset:
        db_path = settings.database_path
        if isinstance(db_path, Path):
            if db_path.exists():
                if not force:
                    confirm = click.confirm(
                        f"Delete existing database at {db_path}?",
                        default=False,
                    )
                    if not confirm:
                        console.print("[yellow]Reset cancelled[/yellow]")
                        return
                db_path.unlink()
        else:
            console.print(
                "[red]Reset is only supported for local SQLite databases[/red]"
            )
            return
    elif isinstance(settings.database_path, Path) and settings.database_path.exists():
        console.print(
            f"[dim]Database already exists at {settings.database_path} "
            "(use --reset to reinitialize)[/dim]"
        )

    db = await init_database()

    console.print(f"[green]Initialized PMS at {settings.data_dir}[/green]")
    console.print(f"[dim]Database: {settings.database_path}[/dim]")

    await db.disconnect()


@cli.command("quickstart")
@click.option("--defaults", is_flag=True, help="Use defaults and skip prompts")
@click.option("--org", "org_name", help="Organization name")
@click.option("--product", "product_name", help="Product name")
@click.option("--project", "project_name", help="Project name")
@click.option("--portfolio", "portfolio_name", help="Portfolio name")
@click.option("--program", "program_name", help="Program name")
@click.option("--task", "tasks", multiple=True, help="Task title (repeatable)")
@click.option(
    "--create-plan/--no-create-plan",
    default=None,
    help="Create a starter plan",
)
@click.option(
    "--create-rollups/--no-create-rollups",
    default=None,
    help="Create a starter portfolio/program rollup",
)
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json"]),
    default="text",
    show_default=True,
)
@async_command
async def quickstart(
    defaults: bool,
    org_name: str | None,
    product_name: str | None,
    project_name: str | None,
    portfolio_name: str | None,
    program_name: str | None,
    tasks: tuple[str, ...],
    create_plan: bool | None,
    create_rollups: bool | None,
    output_format: str,
) -> None:
    """Guided setup: org -> product -> project -> tasks -> review hints."""
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.models.plan import PlanFormat, PlanStatus
    from pms.models.task import Priority
    from pms.services.organization_service import OrganizationService
    from pms.services.plan_service import PlanService
    from pms.services.portfolio_service import PortfolioService
    from pms.services.product_service import ProductService
    from pms.services.program_service import ProgramService
    from pms.services.project_service import ProjectService
    from pms.services.task_service import TaskService

    def _parse_tasks(value: str) -> list[str]:
        return [item.strip() for item in value.split(",") if item.strip()]

    default_org = "Quickstart Org"
    default_product = "Quickstart Product"
    default_project = "Quickstart Project"
    default_portfolio = "Quickstart Portfolio"
    default_program = "Quickstart Program"
    default_tasks = ["Define scope", "Build MVP", "Review and iterate"]

    purpose = "Bootstrap PMS with a usable workspace, real project, starter tasks, and immediate follow-up commands."
    fastest_start = _cli_command("quickstart --defaults")

    if output_format == "text":
        console.print(f"[bold]Quickstart Purpose:[/bold] {purpose}")
        console.print(f"[dim]Fastest start:[/dim] {fastest_start}")

    if defaults:
        org_name = org_name or default_org
        product_name = product_name or default_product
        project_name = project_name or default_project
        portfolio_name = portfolio_name or default_portfolio
        program_name = program_name or default_program
        task_titles = list(tasks) if tasks else default_tasks
        create_plan = True if create_plan is None else create_plan
        create_rollups = True if create_rollups is None else create_rollups
    else:
        org_name = org_name or click.prompt("Organization name", default=default_org)
        product_name = product_name or click.prompt(
            "Product name", default=default_product
        )
        project_name = project_name or click.prompt(
            "Project name", default=default_project
        )
        if tasks:
            task_titles = list(tasks)
        else:
            task_input = click.prompt(
                "Task titles (comma-separated)",
                default=", ".join(default_tasks),
            )
            task_titles = _parse_tasks(task_input)
        if create_plan is None:
            create_plan = click.confirm("Create a starter plan?", default=True)
        if create_rollups is None:
            create_rollups = click.confirm(
                "Create portfolio/program rollups?", default=True
            )
        if create_rollups:
            portfolio_name = portfolio_name or click.prompt(
                "Portfolio name", default=default_portfolio
            )
            program_name = program_name or click.prompt(
                "Program name", default=default_program
            )

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        org_service = OrganizationService(db, event_store, revision_store, metrics)
        portfolio_service = PortfolioService(db, event_store, revision_store, metrics)
        product_service = ProductService(db, event_store, revision_store, metrics)
        program_service = ProgramService(db, event_store, revision_store, metrics)
        project_service = ProjectService(db, event_store, revision_store, metrics)
        task_service = TaskService(db, event_store, revision_store, metrics)
        plan_service = PlanService(db, event_store, revision_store, metrics)

        org = await org_service.get_organization_by_name(org_name)
        if org is None:
            org = await org_service.create_organization(name=org_name)
            if output_format == "text":
                console.print(f"[green]Created organization:[/green] {org.name}")
        else:
            if output_format == "text":
                console.print(f"[yellow]Using organization:[/yellow] {org.name}")

        product = await product_service.get_product_by_name(product_name)
        if product is None:
            product = await product_service.create_product(
                name=product_name,
                owner=org.owner or None,
            )
            if output_format == "text":
                console.print(f"[green]Created product:[/green] {product.name}")
        else:
            if output_format == "text":
                console.print(f"[yellow]Using product:[/yellow] {product.name}")

        project = await project_service.get_project_by_name(project_name)
        if project is None:
            project = await project_service.create_project(
                name=project_name,
                description="Quickstart project",
                product_id=product.id,
            )
            if output_format == "text":
                console.print(f"[green]Created project:[/green] {project.name}")
        else:
            if output_format == "text":
                console.print(f"[yellow]Using project:[/yellow] {project.name}")

        if create_rollups:
            portfolio = None
            if portfolio_name:
                portfolio = await portfolio_service.get_portfolio_by_name(
                    portfolio_name
                )
                if portfolio is None:
                    portfolio = await portfolio_service.create_portfolio(
                        name=portfolio_name,
                        org_id=org.id,
                        description="Quickstart portfolio",
                    )
                    if output_format == "text":
                        console.print(
                            f"[green]Created portfolio:[/green] {portfolio.name}"
                        )
                elif output_format == "text":
                    console.print(f"[yellow]Using portfolio:[/yellow] {portfolio.name}")

            program = None
            if program_name:
                program = await program_service.get_program_by_name(program_name)
                if program is None:
                    program = await program_service.create_program(
                        name=program_name,
                        org_id=org.id,
                        portfolio_id=portfolio.id if portfolio else None,
                        description="Quickstart program",
                    )
                    if output_format == "text":
                        console.print(f"[green]Created program:[/green] {program.name}")
                elif output_format == "text":
                    console.print(f"[yellow]Using program:[/yellow] {program.name}")

            linked_via_program = False
            if program is not None and project.program_id != program.id:
                updated_project = await project_service.update_project(
                    project_id=project.id,
                    program_id=program.id,
                )
                if updated_project is not None:
                    project = updated_project
                linked_via_program = True
                if output_format == "text":
                    console.print(
                        f"[yellow]Linked project to program:[/yellow] {program.name}"
                    )

            if (
                portfolio is not None
                and not linked_via_program
                and project.portfolio_id != portfolio.id
            ):
                updated_project = await project_service.update_project(
                    project_id=project.id,
                    portfolio_id=portfolio.id,
                )
                if updated_project is not None:
                    project = updated_project
                if output_format == "text":
                    console.print(
                        f"[yellow]Linked project to portfolio:[/yellow] {portfolio.name}"
                    )

        existing_task_result = await task_service.list_tasks(
            project_id=project.id,
            include_subtasks=True,
            limit=500,
            offset=0,
        )
        reusable_quickstart_tasks = {
            task.title.strip().lower(): task
            for task in existing_task_result.items
            if task.description == "Quickstart task" or "quickstart" in task.tags
        }

        created_tasks = []
        reused_tasks = []
        for title in task_titles:
            reusable = reusable_quickstart_tasks.get(title.strip().lower())
            if reusable is not None:
                created_tasks.append(reusable)
                reused_tasks.append(reusable)
                if output_format == "text":
                    console.print(
                        f"[yellow]Using quickstart task:[/yellow] {reusable.title}"
                    )
                continue

            task = await task_service.create_task(
                project_id=project.id,
                title=title,
                description="Quickstart task",
                priority=Priority.MEDIUM,
                tags=["quickstart"],
            )
            created_tasks.append(task)
            if output_format == "text":
                console.print(f"[green]Created task:[/green] {task.title}")

        record_progress = False
        if created_tasks:
            record_progress = defaults or click.confirm(
                "Record starter progress on the first task?", default=True
            )

        if create_plan:
            quickstart_plan = await plan_service.upsert_quickstart_plan(
                name=f"{project.name} Plan",
                description="Quickstart plan",
                status=PlanStatus.ACTIVE if record_progress else PlanStatus.DRAFT,
                format=PlanFormat.JSON,
                content={
                    "summary": "Starter plan generated by quickstart.",
                    "tasks": [task.title for task in created_tasks],
                },
                product_id=product.id,
                project_id=project.id,
                task_ids=[task.id for task in created_tasks] if created_tasks else None,
            )
            plan = quickstart_plan.plan
            if output_format == "text":
                action_label = (
                    "Updated" if quickstart_plan.reused_existing else "Created"
                )
                console.print(f"[green]{action_label} plan:[/green] {plan.name}")
                if quickstart_plan.archived_duplicate_plan_ids:
                    console.print(
                        "[yellow]Archived duplicate quickstart plans:[/yellow] "
                        f"{len(quickstart_plan.archived_duplicate_plan_ids)}"
                    )
        else:
            plan = None
            quickstart_plan = None

        if created_tasks and record_progress:
            starter = created_tasks[0]
            if starter.current_progress_percent == 0 and starter.status.value == "todo":
                await task_service.start_task(starter.id, reason="Quickstart")
                await task_service.update_task_progress(
                    starter.id,
                    percent_complete=10,
                    status_message="Kickoff progress",
                    updated_by="quickstart",
                )
                if output_format == "text":
                    console.print(f"[green]Progress updated:[/green] {starter.title}")
            elif output_format == "text":
                console.print(
                    f"[yellow]Starter progress already exists:[/yellow] {starter.title}"
                )

        next_steps = _normalize_next_steps(
            f'project show "{project.name}"',
            f'task list --project "{project.name}"',
            f'work daily --scope-type project --scope "{project.name}" --format json',
            "dashboard --format json",
            "start --format json",
        )
        payload = {
            "purpose": purpose,
            "fastest_start": fastest_start,
            "artifacts_created": {
                "organization": {"id": org.id, "name": org.name},
                "product": {"id": product.id, "name": product.name},
                "project": {"id": project.id, "name": project.name},
                "portfolio": (
                    {"id": portfolio.id, "name": portfolio.name}
                    if create_rollups and portfolio_name and portfolio is not None
                    else None
                ),
                "program": (
                    {"id": program.id, "name": program.name}
                    if create_rollups and program_name and program is not None
                    else None
                ),
                "tasks": [
                    {"id": task.id, "title": task.title} for task in created_tasks
                ],
                "reused_tasks": [
                    {"id": task.id, "title": task.title} for task in reused_tasks
                ],
                "plan": (
                    {
                        "id": plan.id,
                        "name": plan.name,
                        "reused_existing": (
                            quickstart_plan.reused_existing
                            if quickstart_plan is not None
                            else False
                        ),
                        "archived_duplicate_plan_ids": (
                            quickstart_plan.archived_duplicate_plan_ids
                            if quickstart_plan is not None
                            else []
                        ),
                    }
                    if create_plan and plan is not None
                    else None
                ),
            },
            "next_steps": next_steps,
            "links": _normalize_command_links(
                {
                    "guide": "start --format json",
                    "project": f'project show "{project.name}"',
                    "daily": (
                        f'work daily --scope-type project --scope "{project.name}" --format json'
                    ),
                    "dashboard": "dashboard --format json",
                }
            ),
        }
        if output_format == "json":
            click.echo(json.dumps(payload, default=str))
            return

        console.print("\n[bold]Artifacts created[/bold]")
        console.print(f"  Project: {project.name} ({project.id})")
        console.print(f"  Tasks: {len(created_tasks)}")
        if create_rollups:
            if portfolio_name:
                console.print(f"  Portfolio: {portfolio_name}")
            if program_name:
                console.print(f"  Program: {program_name}")
        if create_plan and plan is not None:
            console.print(f"  Plan: {plan.name} ({plan.id})")

        _print_next_steps(*next_steps)
    finally:
        await db.disconnect()


@cli.command(
    "start",
    epilog=_help_epilog(
        "start",
        "start --format json",
        "dashboard --format json",
        "project show <project-id> --format json",
    ),
)
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json"]),
    default="text",
    show_default=True,
)
@async_command
async def start_cmd(output_format: str) -> None:
    """Show the recommended start -> go -> observe path with live runtime state.

    Use this as the first operator entry point when you need to understand what
    PMS is for, which runtime is active, which work is ready, and what command
    to run next.
    """
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.models.base import now_utc
    from pms.services import (
        ActorService,
        OrganizationService,
        PortfolioService,
        ProgramService,
        ProjectService,
        QueueService,
        TaskService,
    )

    db = await init_database()

    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)

        organization_service = OrganizationService(
            db,
            event_store,
            revision_store,
            metrics,
        )
        portfolio_service = PortfolioService(db, event_store, revision_store, metrics)
        program_service = ProgramService(db, event_store, revision_store, metrics)
        project_service = ProjectService(db, event_store, revision_store, metrics)
        task_service = TaskService(db, event_store, revision_store, metrics)
        queue_service = QueueService(task_service)
        actor_service = ActorService(db, event_store, revision_store, metrics)

        organizations = await organization_service.list_organizations(limit=1, offset=0)
        portfolios = await portfolio_service.list_portfolios(limit=1, offset=0)
        programs = await program_service.list_programs(limit=1, offset=0)
        projects = await project_service.list_projects(limit=1, offset=0)
        tasks = await task_service.search_tasks(
            include_terminal=True,
            limit=1,
            offset=0,
        )
        ready_tasks = await task_service.list_ready_tasks(
            limit=_OPERATOR_VIEW_CANDIDATE_LIMIT, offset=0
        )
        in_progress_tasks = await task_service.search_tasks(
            statuses=[TaskStatus.IN_PROGRESS],
            include_terminal=True,
            limit=_OPERATOR_VIEW_CANDIDATE_LIMIT,
            offset=0,
        )
        blocked_tasks = await task_service.search_tasks(
            statuses=[TaskStatus.BLOCKED],
            include_terminal=True,
            limit=_OPERATOR_VIEW_CANDIDATE_LIMIT,
            offset=0,
        )
        queue_presets = await queue_service.list_presets(
            limit=_OPERATOR_VIEW_CANDIDATE_LIMIT
        )
        dashboard = await project_service.get_dashboard()

        excluded_project_ids = await _operator_hidden_project_ids_for_task_views(
            project_service,
            task_service,
            active_projects=dashboard.active_projects,
            candidate_limit=_OPERATOR_VIEW_CANDIDATE_LIMIT,
        )
        generated_project_ids = await _generated_project_ids(
            project_service,
            [
                *(summary.project.id for summary in dashboard.active_projects),
            ],
        )
        visible_ready_tasks = _slice_visible_tasks(
            ready_tasks.items,
            excluded_project_ids,
            limit=5,
        )
        visible_in_progress_tasks = _slice_visible_tasks(
            in_progress_tasks.items,
            excluded_project_ids,
            limit=5,
        )
        visible_start_tasks = [*visible_ready_tasks, *visible_in_progress_tasks]
        assignee_map = await _resolve_assignee_map(
            visible_start_tasks,
            actor_service,
        )
        checkout_actor_map = await _resolve_checkout_actor_map(
            visible_start_tasks,
            actor_service,
        )
        start_task_lookup = {task.id: task for task in visible_start_tasks}
        visible_dashboard_projects = _exclude_active_project_summaries(
            dashboard.active_projects,
            excluded_project_ids,
        )
        recent_completed_projects = await _recent_operator_visible_completed_projects(
            project_service,
            limit=3,
        )
        recent_completed_activity = await project_service.get_last_activity_map(
            [project.id for project in recent_completed_projects]
        )
        recent_completed_transition = await project_service.get_last_transition_map(
            [project.id for project in recent_completed_projects]
        )
        active_project_payloads = [
            _project_summary_surface_payload(summary)
            for summary in visible_dashboard_projects
        ]
        (
            recent_completed_project_payloads,
            recent_completed_activity,
            recent_completed_transition,
        ) = await _recent_completed_project_surface_payloads(
            project_service,
            recent_completed_projects,
            activity_map=recent_completed_activity,
            transition_map=recent_completed_transition,
        )
        visible_project_payload_by_id = {
            str(payload["project_id"]): payload
            for payload in [
                *active_project_payloads,
                *recent_completed_project_payloads,
            ]
            if payload.get("project_id") is not None
        }
        start_visible_projects = [
            *(summary.project for summary in visible_dashboard_projects),
            *recent_completed_projects,
        ]
        start_visible_activity_map = {
            summary.project.id: summary.last_activity_at
            for summary in visible_dashboard_projects
        }
        start_visible_activity_map.update(recent_completed_activity)
        start_visible_transition_map = {
            summary.project.id: summary.last_transition_at
            for summary in visible_dashboard_projects
        }
        start_visible_transition_map.update(recent_completed_transition)
        freshest_visible_project_activity = _freshest_entity_timestamp_entry(
            start_visible_projects,
            start_visible_activity_map,
            fallback_to_updated_at=True,
        )
        freshest_visible_project_transition = _freshest_entity_timestamp_entry(
            start_visible_projects,
            start_visible_transition_map,
            fallback_to_updated_at=True,
        )

        first_project_name = (
            visible_dashboard_projects[0].project.name
            if visible_dashboard_projects
            else None
        )

        next_steps: list[str] = []
        focus_target: CommandFocusTarget | None = None
        ready_project_names: dict[str, str | None] = {}
        in_progress_project_names: dict[str, str | None] = {}
        if projects.total_count == 0:
            next_steps.append("pms quickstart --defaults")
        else:
            for task_obj in visible_ready_tasks:
                if (
                    task_obj.project_id
                    and task_obj.project_id not in ready_project_names
                ):
                    project = await project_service.get_project(task_obj.project_id)
                    if project:
                        ready_project_names[task_obj.project_id] = project.name
            for task_obj in visible_in_progress_tasks:
                if (
                    task_obj.project_id
                    and task_obj.project_id not in in_progress_project_names
                ):
                    project = await project_service.get_project(task_obj.project_id)
                    if project:
                        in_progress_project_names[task_obj.project_id] = project.name
            focus_target = _select_command_focus(
                [*visible_ready_tasks, *visible_in_progress_tasks],
                {
                    **ready_project_names,
                    **in_progress_project_names,
                },
            )
            if focus_target is not None:
                next_steps.extend(focus_target.next_steps())
                if focus_target.project_name:
                    next_steps.append(
                        _cli_command(
                            f'work daily --scope-type project --scope "{focus_target.project_name}" --format json'
                        )
                    )
            if first_project_name:
                next_steps.append(
                    _cli_command(
                        f'work daily --scope-type project --scope "{first_project_name}" --format json'
                    )
                )
        if recent_completed_projects and (
            not visible_dashboard_projects
            or focus_target is None
            or focus_target.status_value != TaskStatus.IN_PROGRESS.value
        ):
            recent_project = recent_completed_projects[0]
            next_steps.append(
                _cli_command(f'project show "{recent_project.name}" --format json')
            )
            next_steps.append(
                _cli_command(
                    f'task list --project "{recent_project.name}" --format json'
                )
            )
        next_steps.append("pms dashboard --format json")
        next_steps.append("pms queue presets --format json")
        next_steps.append("./scripts/run_dropin_start_go_extend_grow.sh")

        unique_steps: list[str] = []
        for step in next_steps:
            if step not in unique_steps:
                unique_steps.append(step)
        coordination = _runtime_coordination_status()
        if coordination.state != "server_coordinated":
            unique_steps = _normalize_next_steps(
                *coordination.recommended_next_steps,
                *unique_steps,
            )

        observability_paths = _normalize_nested_command_fields(
            [
                {
                    "name": "Global Dashboard",
                    "command": "dashboard --format json",
                    "why": "Project/task rollup with ready and in-progress focus.",
                    "continue_with": (
                        "work daily --scope-type project --scope <name> --format json"
                    ),
                },
                {
                    "name": "Scoped Daily Digest",
                    "command": (
                        "work daily --scope-type project --scope <name> --format json"
                    ),
                    "why": (
                        "Accumulated snapshot + queues + transitions + review history."
                    ),
                    "continue_with": (
                        "work review --scope-type project --scope <name> --reviewed-by <you>"
                    ),
                },
                {
                    "name": "Queue Presets",
                    "command": "queue presets --format json",
                    "why": "Instant ready/blocker/at-risk action lists.",
                    "continue_with": "queue create <name> --filters '{...}'",
                },
                {
                    "name": "Org/Portfolio/Program Rollups",
                    "command": "org dashboard --format json",
                    "why": "Cross-project health and next actions for handoffs.",
                    "continue_with": "portfolio dashboard --org <name> --format json",
                },
            ]
        )

        scenario_paths = [
            {
                "name": "Drop-in Start Go Extend Grow",
                "command": "./scripts/run_dropin_start_go_extend_grow.sh",
                "contract": "./scripts/run_dropin_contract_smoke.sh",
                "docs": "examples/real_world/README.md#scenario-dropin",
            },
            {
                "name": "Team Handoff",
                "command": "./scripts/run_team_handoff_flow.sh",
                "contract": "./scripts/run_team_handoff_contract_smoke.sh",
                "docs": "examples/real_world/README.md#scenario-team-handoff",
            },
            {
                "name": "Incident Response",
                "command": "./scripts/run_incident_response_flow.sh",
                "contract": "./scripts/run_incident_response_contract_smoke.sh",
                "docs": "examples/real_world/README.md#scenario-incident-response",
            },
            {
                "name": "User Start Go Observe",
                "command": "./scripts/run_user_start_go_observe_flow.sh",
                "contract": "./scripts/run_user_start_go_observe_contract_smoke.sh",
                "docs": "examples/real_world/README.md#scenario-user-start-go-observe",
            },
            {
                "name": "Operational Review",
                "command": "./scripts/run_operational_review_flow.sh",
                "contract": "./scripts/run_operational_review_contract_smoke.sh",
                "docs": "examples/real_world/README.md#scenario-operational-review",
            },
            {
                "name": "Backlog Triage",
                "command": "./scripts/run_backlog_triage_flow.sh",
                "contract": "./scripts/run_backlog_triage_contract_smoke.sh",
                "docs": "examples/real_world/README.md#scenario-backlog-triage",
            },
            {
                "name": "Portfolio Steering",
                "command": "./scripts/run_portfolio_steering_flow.sh",
                "contract": "./scripts/run_portfolio_steering_contract_smoke.sh",
                "docs": "examples/real_world/README.md#scenario-portfolio-steering",
            },
            {
                "name": "Agent Execution Loop",
                "command": "./scripts/run_agent_execution_loop_flow.sh",
                "contract": "./scripts/run_agent_execution_loop_contract_smoke.sh",
                "docs": "examples/real_world/README.md#scenario-agent-execution-loop",
            },
            {
                "name": "Release Readiness",
                "command": "./scripts/run_release_readiness_flow.sh",
                "contract": "./scripts/run_release_readiness_contract_smoke.sh",
                "docs": "examples/real_world/README.md#scenario-release-readiness",
            },
        ]

        links = _normalize_command_links(
            {
                "dashboard": "dashboard --format json",
                "guide": "start --format json",
                "quickstart": "quickstart --defaults",
            }
        )
        if focus_target is not None and focus_target.project_name:
            links["daily_focus"] = _cli_command(
                f'work daily --scope-type project --scope "{focus_target.project_name}" --format json'
            )
        if recent_completed_projects:
            links["recent_terminal_project"] = _cli_command(
                f'project show "{recent_completed_projects[0].name}" --format json'
            )
        focus_task_payload = (
            focus_target.to_payload()
            if projects.total_count > 0 and focus_target is not None
            else None
        )
        if focus_task_payload is not None:
            focus_task_model = start_task_lookup.get(focus_task_payload["id"])
            if focus_task_model is not None:
                focus_task_payload["assignee"] = _task_assignee_payload(
                    focus_task_model,
                    assignee_map,
                )
                focus_task_payload["checkout"] = _task_checkout_payload(
                    focus_task_model,
                    checkout_actor_map,
                )
                focus_task_payload["links"] = _normalize_command_links(
                    {
                        "self": f"task show {focus_task_model.id}",
                        "actor": _task_assignee_actor_link(
                            focus_task_model,
                            assignee_map,
                        ),
                        "checkout_actor": _task_checkout_actor_link(
                            focus_task_model,
                            checkout_actor_map,
                        ),
                    }
                )

        completion_context: dict[str, Any] | None = None
        terminal_reason: str | None = None
        if recent_completed_projects:
            recent_project_name = recent_completed_project_payloads[0].get(
                "project_name"
            ) or recent_completed_project_payloads[0].get("name")
            completion_context = {
                "summary": _recent_terminal_project_completion_summary(
                    no_other_visible_active_work=(
                        focus_target is None and not visible_dashboard_projects
                    ),
                    active_surface_label="start guide",
                ),
                "items": _recent_terminal_project_completion_items(
                    recent_completed_project_payloads
                ),
                "next_steps": _normalize_next_steps(
                    _cli_command(f'project show "{recent_project_name}" --format json')
                    if recent_project_name
                    else None,
                    "dashboard --format json",
                    "start --format json",
                ),
            }
        if focus_target is None and not visible_dashboard_projects:
            terminal_reason = "no operator-visible active work is currently surfaced"

        payload = _payload_with_normalized_next_steps(
            {
                "generated_at": _to_iso(now_utc()),
                "purpose": (
                    "Practical start -> go entry point for discovering live state, fastest first action, and where to extend next."
                ),
                "artifacts_created": [],
                "live_state": {
                    "organizations": organizations.total_count,
                    "portfolios": portfolios.total_count,
                    "programs": programs.total_count,
                    "projects": projects.total_count,
                    "tasks": tasks.total_count,
                    "ready_tasks": ready_tasks.total_count,
                    "in_progress_tasks": in_progress_tasks.total_count,
                    "blocked_tasks": blocked_tasks.total_count,
                    "queue_presets": len(queue_presets),
                    "blocked_projects": dashboard.blocked_tasks,
                    "overdue_tasks": dashboard.overdue_tasks,
                    "suppressed_generated_projects": len(generated_project_ids),
                    "suppressed_hidden_projects": len(excluded_project_ids),
                },
                "runtime": {
                    "managed_servers": _managed_runtime_servers(),
                    "coordination": coordination.to_dict(),
                },
                "docs": {
                    "readme": "README.md",
                    "getting_started": "GETTING_STARTED.md",
                    "immediate_start": "docs/IMMEDIATE_START_GO.md",
                    "capabilities": "docs/CAPABILITIES_REFERENCE.md",
                    "workflows": "docs/END_TO_END_WORKFLOWS.md",
                },
                "observability_paths": observability_paths,
                "scenario_paths": scenario_paths,
                "scope": {
                    "kind": "instance_start",
                    "active_visible_projects": len(visible_dashboard_projects),
                    "recently_completed_projects": len(recent_completed_projects),
                },
                "completion_context": completion_context,
                "terminal_reason": terminal_reason,
                "freshest_visible_activity": (
                    visible_project_payload_by_id.get(
                        freshest_visible_project_activity[0].id
                    )
                    if freshest_visible_project_activity is not None
                    else None
                ),
                "freshest_visible_transition": (
                    visible_project_payload_by_id.get(
                        freshest_visible_project_transition[0].id
                    )
                    if freshest_visible_project_transition is not None
                    else None
                ),
                "focus_task": focus_task_payload,
                "graph_navigation": _command_focus_graph_navigation(
                    focus_task=focus_target,
                    task_lookup=start_task_lookup,
                    assignee_map=assignee_map,
                    project_id=focus_target.project_id
                    if focus_target is not None
                    else None,
                    project_name=focus_target.project_name
                    if focus_target is not None
                    else None,
                ),
                "actor_rollups": _actor_rollups_payload(
                    tasks=visible_start_tasks,
                    assignee_map=assignee_map,
                    checkout_actor_map=checkout_actor_map,
                    population_basis="start_visible_tasks",
                ),
                "active_projects": active_project_payloads,
                "recently_completed_projects": recent_completed_project_payloads,
                "links": links,
            },
            *unique_steps,
        )

        if output_format == "json":
            click.echo(json.dumps(payload, default=str))
            return

        console.print("[bold]Start -> Go Guide[/bold]")
        console.print("=" * 52)
        console.print(
            "Purpose: practical start -> go entry point for discovering live state, fastest first action, and where to extend next."
        )
        console.print(
            "Creates: no new state; this command maps the current workspace and tells you where to jump next."
        )
        console.print("Live State:")
        console.print(
            f"  orgs {organizations.total_count} | portfolios {portfolios.total_count} | "
            f"programs {programs.total_count}"
        )
        console.print(
            f"  projects {projects.total_count} | tasks {tasks.total_count} | "
            f"ready {ready_tasks.total_count} | in-progress {in_progress_tasks.total_count} | "
            f"blocked {blocked_tasks.total_count}"
        )
        if excluded_project_ids:
            console.print(
                f"  suppressed generated projects {len(generated_project_ids)}"
            )
            hidden_non_generated = len(excluded_project_ids) - len(
                generated_project_ids
            )
            if hidden_non_generated > 0:
                console.print(
                    f"  suppressed non-active projects {hidden_non_generated}"
                )
        if coordination.state != "server_coordinated":
            console.print(
                f"Runtime Coordination: [yellow]{coordination.summary}[/yellow]"
            )
            if coordination.reason:
                console.print(f"Reason: {coordination.reason}")
            if coordination.recovery_summary:
                console.print(f"Recovery: {coordination.recovery_summary}")
            recovery_steps = _normalize_next_steps(*coordination.recommended_next_steps)
            if recovery_steps:
                console.print("Run:")
                for step in recovery_steps:
                    console.print(f"  - {step}")
        console.print()

        if projects.total_count == 0:
            console.print(
                "[yellow]No projects yet.[/yellow] Use quickstart to bootstrap immediately."
            )
        elif first_project_name:
            console.print(f"Active project focus: [cyan]{first_project_name}[/cyan]")
        if projects.total_count > 0 and focus_target is not None:
            console.print(
                "Immediate task focus: "
                f"[cyan]{focus_target.title}[/cyan] "
                f"[{focus_target.status_value}]"
            )
            console.print(f"Why: {focus_target.reason}")
        elif completion_context is not None:
            console.print("Recent terminal work:")
            console.print(f"  {completion_context['summary']}")
            if recent_completed_projects:
                console.print(
                    f"  latest {recent_completed_projects[0].name} "
                    f"({_to_iso(recent_completed_activity.get(recent_completed_projects[0].id))})"
                )
        console.print()

        observe_table = Table(title="Observability Paths")
        observe_table.add_column("Path", style="cyan")
        observe_table.add_column("Use")
        observe_table.add_column("Continue With")
        for item in observability_paths:
            observe_table.add_row(
                item["command"],
                item["why"],
                item["continue_with"],
            )
        console.print(observe_table)

        scenario_table = Table(title="Real-World Scenario Entry Points")
        scenario_table.add_column("Scenario", style="cyan")
        scenario_table.add_column("Run")
        scenario_table.add_column("Contract Check")
        for item in scenario_paths:
            scenario_table.add_row(
                item["name"],
                item["command"],
                item["contract"],
            )
        console.print(scenario_table)

        console.print(
            "Docs: README.md | GETTING_STARTED.md | docs/IMMEDIATE_START_GO.md"
        )
        _print_next_steps(*unique_steps)
    finally:
        await db.disconnect()


@cli.command("install")
@click.option("--name", default="pms", help="MCP server name in Claude config")
@click.option("--force", is_flag=True, help="Overwrite if already installed")
def install_mcp(name: str, force: bool) -> None:
    """Install PMS as MCP server in Claude Desktop.

    Examples:
        pms install
        pms install --name pms-dev --force
    """
    from pms.cli.mcp_installer import get_claude_config_path, install_pms_server

    config_path = get_claude_config_path()

    console.print("[cyan]Installing PMS as MCP server...[/cyan]")
    console.print(f"[dim]Config: {config_path}[/dim]")

    success, message = install_pms_server(server_name=name, force=force)

    if success:
        console.print(f"[green]✓ {message}[/green]")
        console.print("\n[bold]Next steps:[/bold]")
        console.print("  1. Restart Claude Desktop")
        console.print("  2. PMS tools available as 'mcp__pms__*'")
        console.print("  3. Try: 'create a project called MyApp'")
        console.print(f"\n[dim]Verify: pms verify-install --name {name}[/dim]")
    else:
        console.print(f"[red]✗ {message}[/red]")


@cli.command("uninstall")
@click.option("--name", default="pms", help="MCP server name to remove")
def uninstall_mcp(name: str) -> None:
    """Remove PMS from Claude Desktop configuration.

    Examples:
        pms uninstall
        pms uninstall --name pms-dev
    """
    from pms.cli.mcp_installer import uninstall_pms_server

    success, message = uninstall_pms_server(server_name=name)

    if success:
        console.print(f"[green]✓ {message}[/green]")
    else:
        console.print(f"[yellow]{message}[/yellow]")


@cli.command("verify-install")
@click.option("--name", default="pms", help="MCP server name to verify")
def verify_install(name: str) -> None:
    """Verify PMS is properly installed in Claude Desktop.

    Examples:
        pms verify-install
    """
    from pms.cli.mcp_installer import get_claude_config_path, verify_installation

    config_path = get_claude_config_path()

    console.print("[cyan]Verifying PMS installation...[/cyan]")
    console.print(f"[dim]Config: {config_path}[/dim]")

    installed, message = verify_installation(server_name=name)

    if installed:
        console.print(f"[green]✓ {message}[/green]")
        console.print("\n[bold]PMS ready in Claude Desktop![/bold]")
    else:
        console.print(f"[red]✗ {message}[/red]")
        console.print(f"\n[yellow]Run: pms install --name {name}[/yellow]")


@cli.command("version")
def version_cmd() -> None:
    """Show PMS version and info."""
    console.print(f"[bold]PMS - Project Management System[/bold]")
    console.print(f"Version: {__version__}")


@cli.command("run")
@click.argument("prompt", nargs=-1, required=True)
@click.option(
    "-m",
    "--model",
    default="claude-sonnet-4-5",
    help="Claude model to use",
)
@click.option(
    "--max-turns",
    default=20,
    type=int,
    help="Maximum agent turns",
)
@click.option(
    "-v", "--verbose", is_flag=True, help="Show tool calls and detailed output"
)
@click.option(
    "--prime-context/--no-prime-context",
    default=True,
    show_default=True,
    help="Include saved context primer in the agent system prompt",
)
@async_command
async def run_cmd(
    prompt: tuple[str, ...],
    model: str,
    max_turns: int,
    verbose: bool,
    prime_context: bool,
) -> None:
    """Run the PMS agent with a natural language prompt.

    Examples:
        pms run "create a project called MyApp"
        pms run "list all tasks in MyApp project"
        pms run "create tasks for auth, database, and API in MyApp"
    """
    from pms.agents import CoordinatorAgent
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.memory import get_default_context_primer
    from pms.services import (
        GoalService,
        OrganizationService,
        PlanService,
        PortfolioService,
        ProgramService,
        ProjectService,
        TaskService,
        TeamService,
        TestRunService,
    )

    # Join prompt parts
    full_prompt = " ".join(prompt)

    console.print(f"[dim]Running agent with prompt: {full_prompt}[/dim]")
    console.print()

    db = await init_database()

    try:
        # Initialize services
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)

        project_service = ProjectService(db, event_store, revision_store, metrics)
        task_service = TaskService(db, event_store, revision_store, metrics)
        test_run_service = TestRunService(db, metrics)
        goal_service = GoalService(db, event_store, revision_store, metrics)
        plan_service = PlanService(db, event_store, revision_store, metrics)
        organization_service = OrganizationService(
            db, event_store, revision_store, metrics
        )
        team_service = TeamService(db, event_store, revision_store, metrics)
        portfolio_service = PortfolioService(db, event_store, revision_store, metrics)
        program_service = ProgramService(db, event_store, revision_store, metrics)
        context_primer = get_default_context_primer() if prime_context else None

        # Create and run agent
        agent = CoordinatorAgent(
            project_service=project_service,
            task_service=task_service,
            goal_service=goal_service,
            plan_service=plan_service,
            organization_service=organization_service,
            team_service=team_service,
            portfolio_service=portfolio_service,
            program_service=program_service,
            test_run_service=test_run_service,
            context_primer=context_primer,
            prime_context=prime_context,
            max_turns=max_turns,
            model=model,
        )

        result = await agent.run(full_prompt)

        # Display results
        if verbose and result.tool_calls:
            console.print("[bold]Tool calls:[/bold]")
            for call in result.tool_calls:
                console.print(f"  [dim]{call}[/dim]")
            console.print()

        if result.errors:
            console.print("[bold red]Errors:[/bold red]")
            for err in result.errors:
                console.print(f"  [red]{err}[/red]")
            console.print()

        console.print(result.message)

        # Flush metrics
        await metrics.flush_best_effort(context="cli.run")

    finally:
        await db.disconnect()


def _resolve_loop_config_path(config_path: str | None) -> Path | None:
    if config_path:
        return Path(config_path)
    candidates = ["pms-loop.yml", "ralph.yml", "ralph.codex-acp.yml"]
    for name in candidates:
        candidate = Path(name)
        if candidate.exists():
            return candidate
    return None


@loop.command("init")
@click.option("--config", "config_path", default="pms-loop.yml", show_default=True)
@click.option("--prompt-file", default="PROMPT.md", show_default=True)
@click.option("--force", is_flag=True, help="Overwrite existing files")
def loop_init(config_path: str, prompt_file: str, force: bool) -> None:
    """Initialize a loop config + prompt template."""
    config_target = Path(config_path)
    prompt_target = Path(prompt_file)

    if config_target.exists() and not force:
        console.print(f"[red]Config already exists:[/red] {config_target}")
        return
    if prompt_target.exists() and not force:
        console.print(f"[red]Prompt already exists:[/red] {prompt_target}")
        return

    config_target.write_text(
        "\n".join(
            [
                "# PMS Agent Loop Configuration",
                "agent: auto",
                "agent_priority:",
                "  - claude",
                "  - codex",
                "  - acp",
                "prompt_file: PROMPT.md",
                "max_iterations: 25",
                "max_runtime: 14400",
                "retry_delay: 2",
                "completion_promise: null",
                "stop_when_goals_complete: false",
                "goal_ids: []",
                "include_archived_goals: false",
                "allow_no_goals: false",
                "adapters:",
                "  claude:",
                "    type: claude",
                "    enabled: true",
                "  codex:",
                "    type: codex",
                "    enabled: false",
                "    command: codex-acp",
                "    args: []",
                "    codex_model: null",
                "    codex_reasoning_effort: null",
                "    permission_mode: interactive",
                "    permission_allowlist: []",
                "  command:",
                "    type: command",
                "    enabled: false",
                "    command: /path/to/agent",
                "    args: []",
                "    prompt_mode: stdin",
                "  acp:",
                "    type: acp",
                "    enabled: false",
                "    command: codex-acp",
                "    args: []",
                "    permission_mode: interactive",
                "    permission_allowlist: []",
                "",
            ]
        )
    )

    if not prompt_target.exists() or force:
        prompt_target.write_text(
            "\n".join(
                [
                    "# Task",
                    "",
                    "Describe the task for the agent loop.",
                    "",
                    "- [ ] CHECKPOINT_1: Basic structure complete",
                    "- [ ] CHECKPOINT_2: Core functionality working",
                    "- [ ] CHECKPOINT_3: Tests passing",
                    "- [ ] CHECKPOINT_4: Documentation complete",
                    "",
                ]
            )
        )

    console.print(f"[green]Created:[/green] {config_target}")
    console.print(f"[green]Created:[/green] {prompt_target}")
    console.print("[dim]Next: pms loop run --config pms-loop.yml[/dim]")


@loop.command("prompt-template")
@click.option("--project", "project_ref", help="Project name or ID")
@click.option("--project-id", help="Project ID")
@click.option("--goal", "goal_ref", help="Goal name or ID")
@click.option("--goal-id", help="Goal ID")
@click.option("--objective", "objective_ref", help="Objective name or ID")
@click.option("--objective-id", help="Objective ID")
@click.option("--plan", "plan_ref", help="Plan name or ID")
@click.option("--plan-id", help="Plan ID")
@click.option("--prompt-file", default="PROMPT.md", show_default=True)
@click.option("--write/--no-write", default=True, show_default=True)
@click.option("--force", is_flag=True, help="Overwrite prompt file if it exists")
@click.option("--stdout", is_flag=True, help="Print prompt to stdout")
@click.option("--task-limit", type=int, default=50, show_default=True)
@click.option("--keyresult-limit", type=int, default=50, show_default=True)
@click.option("--pick", is_flag=True, help="Pick from matching entities")
@async_command
async def loop_prompt_template(
    project_ref: str | None,
    project_id: str | None,
    goal_ref: str | None,
    goal_id: str | None,
    objective_ref: str | None,
    objective_id: str | None,
    plan_ref: str | None,
    plan_id: str | None,
    prompt_file: str,
    write: bool,
    force: bool,
    stdout: bool,
    task_limit: int,
    keyresult_limit: int,
    pick: bool,
) -> None:
    """Render a loop prompt template with IDs prefilled."""
    import json
    from pathlib import Path

    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.models import PlanFormat
    from pms.services.goal_service import GoalService
    from pms.services.plan_service import PlanService
    from pms.services.product_service import ProductService
    from pms.services.project_service import ProjectService
    from pms.services.task_service import TaskService

    def _parse_plan_content(plan_obj) -> dict[str, object]:
        if plan_obj is None or not plan_obj.content:
            return {}
        match plan_obj.format:
            case PlanFormat.JSON:
                try:
                    return json.loads(plan_obj.content) or {}
                except json.JSONDecodeError:
                    return {}
            case PlanFormat.YAML:
                try:
                    import yaml  # type: ignore[import-not-found]
                except ImportError:
                    return {}
                try:
                    parsed = yaml.safe_load(plan_obj.content)
                except yaml.YAMLError:
                    return {}
                return parsed or {}
            case _:
                return {}

    def _format_entity(label: str, name: str | None, entity_id: str | None) -> str:
        if name and entity_id:
            return f"- {label}: {name} ({entity_id})"
        if entity_id:
            return f"- {label}: {entity_id}"
        if name:
            return f"- {label}: {name}"
        return f"- {label}: -"

    def _ensure_list(value: object | None) -> list[object]:
        if value is None:
            return []
        if isinstance(value, list):
            return value
        return [value]

    if project_ref and project_id:
        _emit_cli_error(
            "Use --project or --project-id, not both",
            output_format="text",
        )
    if goal_ref and goal_id:
        _emit_cli_error("Use --goal or --goal-id, not both", output_format="text")
    if objective_ref and objective_id:
        _emit_cli_error(
            "Use --objective or --objective-id, not both",
            output_format="text",
        )
    if plan_ref and plan_id:
        _emit_cli_error("Use --plan or --plan-id, not both", output_format="text")

    prompt_target = Path(prompt_file)
    if write and prompt_target.exists() and not force:
        console.print(f"[red]Prompt already exists:[/red] {prompt_target}")
        return

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        project_service = ProjectService(db, event_store, revision_store, metrics)
        product_service = ProductService(db, event_store, revision_store, metrics)
        goal_service = GoalService(db, event_store, revision_store, metrics)
        plan_service = PlanService(db, event_store, revision_store, metrics)
        task_service = TaskService(db, event_store, revision_store, metrics)

        resolved_project_id = project_id or await _resolve_project_id(
            project_ref, project_service
        )
        resolved_goal_id = goal_id or await _resolve_goal_id(
            goal_ref, goal_service, pick=pick
        )
        resolved_objective_id = objective_id or await _resolve_objective_id(
            objective_ref, goal_ref or goal_id, goal_service, pick=pick
        )

        plan_obj = None
        resolved_plan_id = plan_id
        if plan_ref:
            resolved_plan_id = await _resolve_plan_id(
                plan_ref,
                project_ref or project_id,
                plan_service,
                project_service,
                pick=pick,
            )
        if resolved_plan_id is None and (resolved_project_id or resolved_goal_id):
            result = await plan_service.list_plans(
                project_id=resolved_project_id,
                goal_id=resolved_goal_id,
                objective_id=resolved_objective_id,
                limit=5,
                offset=0,
            )
            if result.total_count == 1:
                resolved_plan_id = result.items[0].id
        if resolved_plan_id:
            plan_obj = await plan_service.get_plan(resolved_plan_id)

        if plan_obj:
            if plan_obj.project_id and resolved_project_id is None:
                resolved_project_id = plan_obj.project_id
            if plan_obj.goal_id and resolved_goal_id is None:
                resolved_goal_id = plan_obj.goal_id
            if plan_obj.objective_id and resolved_objective_id is None:
                resolved_objective_id = plan_obj.objective_id

        if resolved_project_id is None:
            _emit_cli_error(
                "Project is required to build the prompt",
                output_format="text",
            )
        if resolved_goal_id is None:
            _emit_cli_error(
                "Goal is required to build the prompt",
                output_format="text",
            )
        if resolved_objective_id is None:
            _emit_cli_error(
                "Objective is required to build the prompt",
                output_format="text",
            )
        if plan_obj is None:
            _emit_cli_error(
                "Plan is required to build the prompt",
                output_format="text",
            )

        project = await project_service.get_project(resolved_project_id)
        if project is None:
            _emit_cli_error("Project not found", output_format="text")

        goal = await goal_service.get_goal(resolved_goal_id)
        objective = await goal_service.get_objective(resolved_objective_id)
        if goal is None or objective is None:
            _emit_cli_error("Goal/objective not found", output_format="text")

        product = None
        if project.product_id:
            product = await product_service.get_product(project.product_id)
        elif goal.product_id:
            product = await product_service.get_product(goal.product_id)

        plan_content = _parse_plan_content(plan_obj)
        criteria_items = _ensure_list(plan_content.get("acceptance_criteria"))
        task_map = _ensure_list(plan_content.get("task_map"))

        key_result_items = await goal_service.list_key_results(
            objective_id=objective.id,
            limit=keyresult_limit,
            offset=0,
        )
        key_results = key_result_items.items

        if not criteria_items and key_results:
            for idx, key_result in enumerate(key_results, start=1):
                criteria_items.append(
                    {
                        "id": f"kr-{idx}",
                        "description": key_result.name,
                        "key_result_id": key_result.id,
                    }
                )

        criteria_by_task_id: dict[str, list[str]] = {}
        criteria_by_task_title: dict[str, list[str]] = {}
        task_notes: dict[str, str] = {}
        for entry in task_map:
            if not isinstance(entry, dict):
                continue
            criteria_ids = [
                str(item).strip()
                for item in entry.get("acceptance_criteria", []) or []
                if str(item).strip()
            ]
            task_id = entry.get("task_id")
            task_title = entry.get("task")
            notes = entry.get("notes")
            if task_id:
                criteria_by_task_id[str(task_id)] = criteria_ids
                if notes:
                    task_notes[str(task_id)] = str(notes)
            if task_title:
                criteria_by_task_title[str(task_title)] = criteria_ids
                if notes:
                    task_notes[str(task_title)] = str(notes)

        tasks = []
        if plan_obj.task_ids:
            tasks = await task_service.get_tasks_by_ids(list(plan_obj.task_ids))
        if not tasks:
            task_result = await task_service.list_tasks(
                project_id=project.id,
                limit=task_limit,
                offset=0,
            )
            tasks = task_result.items

        product_label = product.name if product else "none"
        lines = [
            "# Project",
            f"{project.name} (product: {product_label})",
            "",
            "# Entity Index",
            _format_entity(
                "Product",
                product.name if product else None,
                product.id if product else None,
            ),
            _format_entity("Project", project.name, project.id),
            _format_entity("Goal", goal.name, goal.id),
            _format_entity("Objective", objective.name, objective.id),
            _format_entity("Plan", plan_obj.name, plan_obj.id),
            "",
            "# Acceptance Criteria (Key Results)",
        ]

        if criteria_items:
            for item in criteria_items:
                if isinstance(item, dict):
                    crit_id = str(item.get("id") or "").strip() or "-"
                    description = str(item.get("description") or "").strip() or "-"
                    kr_id = item.get("key_result_id") or item.get("key_result")
                else:
                    crit_id = "-"
                    description = str(item).strip() or "-"
                    kr_id = None
                suffix = f" (key_result_id: {kr_id})" if kr_id else ""
                lines.append(f"- [{crit_id}] {description}{suffix}")
        else:
            lines.append("- (none)")

        lines.append("")
        lines.append("# Task Map (from plan content)")
        if task_map:
            for entry in task_map:
                if not isinstance(entry, dict):
                    lines.append(f"- {entry}")
                    continue
                task_label = entry.get("task_id") or entry.get("task") or "-"
                criteria = entry.get("acceptance_criteria") or []
                horizon = entry.get("horizon")
                notes = entry.get("notes")
                crit_label = ", ".join(str(c) for c in criteria) if criteria else "none"
                line = f"- {task_label} -> {crit_label}"
                extras = []
                if horizon:
                    extras.append(f"horizon: {horizon}")
                if notes:
                    extras.append(f"notes: {notes}")
                if extras:
                    line += f" ({'; '.join(extras)})"
                lines.append(line)
        else:
            lines.append("- (none)")

        lines.append("")
        lines.append(f"# Task Index (first {task_limit})")
        if tasks:
            for task in tasks[:task_limit]:
                criteria = criteria_by_task_id.get(task.id)
                if not criteria and task.title:
                    criteria = criteria_by_task_title.get(task.title)
                crit_label = f" [{', '.join(criteria)}]" if criteria else ""
                note = task_notes.get(task.id) or task_notes.get(task.title or "")
                note_label = f" note: {note}" if note else ""
                lines.append(
                    f"- {task.id}: {task.title} ({task.status.value}){crit_label}{note_label}"
                )
        else:
            lines.append("- (no tasks found)")

        product_state_command = (
            _inline_cli_code(f'product show "{product.name}"')
            if product
            else _inline_cli_code("product list")
        )
        project_state_command = _inline_cli_code(f'project show "{project.name}"')
        goal_state_command = _inline_cli_code(f'goal list --project "{project.name}"')
        objective_state_command = _inline_cli_code(
            f'objective list --goal "{goal.name}"'
        )
        keyresult_state_command = _inline_cli_code(
            f'keyresult list --objective "{objective.name}" --goal "{goal.name}"'
        )
        plan_state_command = _inline_cli_code(
            f'plan show "{plan_obj.name}" --project "{project.name}"'
        )
        task_state_command = _inline_cli_code(f'task list --project "{project.name}"')

        lines.append("")
        lines.append("# Loop Rules (must follow)")
        lines.extend(
            [
                "1) Read PMS state first:",
                f"   - {product_state_command}",
                f"   - {project_state_command}",
                f"   - {goal_state_command}",
                f"   - {objective_state_command}",
                f"   - {keyresult_state_command}",
                f"   - {plan_state_command}",
                f"   - {task_state_command}",
                "2) Assign workflow for tasks without one:",
                f"   - {_inline_cli_code('workflow assign <task_id> sdlc concept --entity-type task')}",
                "3) Check out the task before work:",
                f"   - {_inline_cli_code('task checkout <task_id> --agent-id loop-agent')}",
                "4) Update task status and progress:",
                f"   - {_inline_cli_code('task start <task_id>')}",
                f"   - {_inline_cli_code('task progress <task_id> <percent> <message> --by loop-agent')}",
                f"   - {_inline_cli_code('task complete <task_id>')}",
                "5) Transition workflow states as you advance:",
                f"   - {_inline_cli_code('workflow transition <task_id> idea --by loop-agent')}",
                f"   - {_inline_cli_code('workflow transition <task_id> planning --by loop-agent')}",
                f"   - {_inline_cli_code('workflow transition <task_id> implementing --by loop-agent')}",
                f"   - {_inline_cli_code('workflow transition <task_id> integration_testing --by loop-agent')}",
                f"   - {_inline_cli_code('workflow transition <task_id> production --by loop-agent --approved-by lead')}",
                "6) Attach evidence for every task:",
                f"   - {_inline_cli_code('task evidence add <task_id> artifact <path>')}",
                f"   - For tests: {_inline_cli_code('test run .')} then",
                f"     {_inline_cli_code('task evidence add <task_id> test_run <run_id>')}",
                "7) Update key results and objective progress:",
            ]
        )

        if key_results:
            for key_result in key_results:
                keyresult_update_command = _inline_cli_code(
                    f'keyresult update {key_result.id} --goal "{goal.name}" --progress <percent>'
                )
                lines.append(f"   - {keyresult_update_command}")
        else:
            lines.append(
                "   - "
                + _inline_cli_code(
                    'keyresult update <key_result_id> --goal "<goal>" --progress <percent>'
                )
            )
        objective_update_command = _inline_cli_code(
            f'objective update "{objective.name}" --goal "{goal.name}" --progress <percent>'
        )
        goal_summary_command = _inline_cli_code(f'goal summary "{goal.name}"')
        goal_complete_command = _inline_cli_code(f'goal complete "{goal.name}"')
        lines.append(f"   - {objective_update_command}")
        lines.extend(
            [
                f"8) Use {goal_summary_command} each loop to confirm rollups.",
                f"9) When all criteria are complete, finish the goal:",
                f"   - {goal_complete_command}",
                "10) When the goal is complete, output <promise>DONE</promise>.",
                "",
            ]
        )

        prompt_text = "\n".join(lines)
        if write:
            prompt_target.write_text(prompt_text)
            console.print(f"[green]Wrote prompt template:[/green] {prompt_target}")
        if stdout or not write:
            click.echo(prompt_text)
        _print_next_steps(
            f'loop run --project "{project.name}" --prompt-file {prompt_target}',
            "loop guard --project <name> --hook",
        )
    finally:
        await db.disconnect()


@loop.command("setup")
@click.option("--defaults", is_flag=True, help="Use defaults and skip prompts")
@click.option("--org", "org_name", help="Organization name")
@click.option("--product", "product_name", help="Product name")
@click.option("--project", "project_ref", help="Project name or ID")
@click.option("--project-id", help="Project ID")
@click.option("--goal", "goal_name", help="Primary goal name")
@click.option(
    "--goal-horizon",
    type=click.Choice(["short_term", "medium_term", "long_term"]),
    default="short_term",
    show_default=True,
)
@click.option("--objective", "objective_name", help="Objective name")
@click.option(
    "--criterion",
    "criteria",
    multiple=True,
    help="Acceptance criterion (repeatable)",
)
@click.option("--task", "task_titles", multiple=True, help="Task title (repeatable)")
@click.option("--config", "config_path", default="pms-loop.yml", show_default=True)
@click.option("--prompt-file", default="PROMPT.md", show_default=True)
@click.option("--force", is_flag=True, help="Overwrite prompt/config files")
@click.option("--agent", default="claude", show_default=True)
@click.option("--completion-promise", default="DONE", show_default=True)
@click.option("--run/--no-run", default=False, show_default=True)
@click.option(
    "--assign-workflow/--no-assign-workflow",
    default=True,
    show_default=True,
)
@click.option("--workflow", "workflow_name", default="sdlc", show_default=True)
@click.option("--initial-state", default="concept", show_default=True)
@async_command
async def loop_setup(
    defaults: bool,
    org_name: str | None,
    product_name: str | None,
    project_ref: str | None,
    project_id: str | None,
    goal_name: str | None,
    goal_horizon: str,
    objective_name: str | None,
    criteria: tuple[str, ...],
    task_titles: tuple[str, ...],
    config_path: str,
    prompt_file: str,
    force: bool,
    agent: str,
    completion_promise: str,
    run: bool,
    assign_workflow: bool,
    workflow_name: str,
    initial_state: str,
) -> None:
    """Interactive prompt-to-loop setup for goal-driven work."""
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.models import GoalHorizon, PlanFormat, PlanStatus
    from pms.models.enums import DependencyType
    from pms.models.task import Priority
    from pms.services.agent_loop_service import AgentLoopService
    from pms.services.goal_service import GoalService
    from pms.services.organization_service import OrganizationService
    from pms.services.plan_service import PlanService
    from pms.services.product_service import ProductService
    from pms.services.project_service import ProjectService
    from pms.services.task_service import TaskService
    from pms.workflows.transition import assign_workflow as assign_workflow_fn

    def _parse_csv(value: str) -> list[str]:
        return [item.strip() for item in value.split(",") if item.strip()]

    def _prompt_list(label: str, fallback: list[str]) -> list[str]:
        items: list[str] = []
        if defaults:
            return fallback
        while True:
            entry = click.prompt(label, default="", show_default=False)
            if not entry.strip():
                break
            items.append(entry.strip())
        return items or fallback

    def _prompt_bool(label: str, default_value: bool) -> bool:
        if defaults:
            return default_value
        return click.confirm(label, default=default_value)

    def _parse_goal_horizon(value: str) -> GoalHorizon:
        match value:
            case "medium_term":
                return GoalHorizon.MEDIUM_TERM
            case "long_term":
                return GoalHorizon.LONG_TERM
            case _:
                return GoalHorizon.SHORT_TERM

    def _parse_dependency_type(value: str) -> DependencyType:
        match value:
            case "relates_to":
                return DependencyType.RELATES_TO
            case "duplicates":
                return DependencyType.DUPLICATES
            case _:
                return DependencyType.BLOCKS

    config_target = Path(config_path)
    prompt_target = Path(prompt_file)
    if config_target.exists() and not force:
        console.print(f"[red]Config already exists:[/red] {config_target}")
        return
    if prompt_target.exists() and not force:
        console.print(f"[red]Prompt already exists:[/red] {prompt_target}")
        return

    if project_ref and project_id:
        _emit_cli_error("Use --project or --project-id, not both", output_format="text")

    default_org = "Loop Org"
    default_product = "Loop Product"
    default_project = "Loop Project"
    default_goal = "Ship MVP"
    default_objective = "Acceptance criteria"
    default_criteria = [
        "Core flow implemented end-to-end",
        "Evidence captured for completed tasks",
        "Tests or smoke checks recorded",
    ]
    default_tasks = [
        "Define requirements and scope",
        "Implement core workflow",
        "Run tests and capture evidence",
    ]

    use_existing_project = bool(project_ref or project_id)

    project_name = project_ref
    if not use_existing_project:
        org_name = org_name or (
            default_org
            if defaults
            else click.prompt("Organization name", default=default_org)
        )
        product_name = product_name or (
            default_product
            if defaults
            else click.prompt("Product name", default=default_product)
        )
        project_name = project_name or (
            default_project
            if defaults
            else click.prompt("Project name", default=default_project)
        )

    goal_name = goal_name or (
        default_goal if defaults else click.prompt("Primary goal", default=default_goal)
    )
    objective_name = objective_name or (
        default_objective
        if defaults
        else click.prompt("Objective name", default=default_objective)
    )

    criteria_list = (
        list(criteria)
        if criteria
        else _prompt_list(
            "Acceptance criterion (blank to finish)",
            default_criteria,
        )
    )

    task_title_list = (
        list(task_titles)
        if task_titles
        else _prompt_list(
            "Task title (blank to finish)",
            default_tasks,
        )
    )

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)

        org_service = OrganizationService(db, event_store, revision_store, metrics)
        product_service = ProductService(db, event_store, revision_store, metrics)
        project_service = ProjectService(db, event_store, revision_store, metrics)
        goal_service = GoalService(db, event_store, revision_store, metrics)
        task_service = TaskService(db, event_store, revision_store, metrics)
        plan_service = PlanService(db, event_store, revision_store, metrics)

        project = None
        product = None

        if use_existing_project:
            resolved_project_id = project_id or await _resolve_project_id(
                project_ref, project_service
            )
            if resolved_project_id is None:
                return
            project = await project_service.get_project(resolved_project_id)
            if project is None:
                console.print(
                    f"[red]Project '{project_ref or project_id}' not found[/red]"
                )
                return
            if project.product_id:
                product = await product_service.get_product(project.product_id)
        else:
            org = await org_service.get_organization_by_name(org_name)
            if org is None:
                org = await org_service.create_organization(
                    name=org_name or default_org
                )
                console.print(f"[green]Created organization:[/green] {org.name}")
            else:
                console.print(f"[yellow]Using organization:[/yellow] {org.name}")

            product = await product_service.get_product_by_name(
                product_name or default_product
            )
            if product is None:
                product = await product_service.create_product(
                    name=product_name or default_product,
                    owner=org.owner or None,
                )
                console.print(f"[green]Created product:[/green] {product.name}")
            else:
                console.print(f"[yellow]Using product:[/yellow] {product.name}")

            project = await project_service.get_project_by_name(
                project_name or default_project
            )
            if project is None:
                project = await project_service.create_project(
                    name=project_name or default_project,
                    description="Loop setup project",
                    product_id=product.id if product else None,
                )
                console.print(f"[green]Created project:[/green] {project.name}")
            else:
                console.print(f"[yellow]Using project:[/yellow] {project.name}")

        goal = await goal_service.get_goal_by_name(goal_name)
        if goal is None or goal.project_id not in (None, project.id):
            goal = await goal_service.create_goal(
                name=goal_name,
                description="Loop setup goal",
                horizon=_parse_goal_horizon(goal_horizon),
                project_id=project.id,
                product_id=product.id if product else None,
            )
            console.print(f"[green]Created goal:[/green] {goal.name}")
        else:
            console.print(f"[yellow]Using goal:[/yellow] {goal.name}")

        objective = await goal_service.create_objective(
            goal_id=goal.id,
            name=objective_name,
            description="Acceptance criteria",
        )
        console.print(f"[green]Created objective:[/green] {objective.name}")

        criteria_items = []
        key_results = []
        for idx, description in enumerate(criteria_list, start=1):
            key_result = await goal_service.create_key_result(
                objective_id=objective.id,
                name=description,
                description=description,
            )
            key_results.append(key_result)
            criteria_items.append(
                {
                    "id": f"ac-{idx}",
                    "description": description,
                    "key_result_id": key_result.id,
                }
            )

        existing_tasks = await task_service.list_tasks(project_id=project.id, limit=500)
        existing_by_title = {
            task.title.strip().lower(): task for task in existing_tasks.items
        }

        task_entries = []
        for title in task_title_list:
            title = title.strip()
            if not title:
                continue
            description = None
            criteria_ids: list[str] = []
            tags: list[str] = []
            if not defaults:
                description = (
                    click.prompt(
                        f"Description for '{title}'",
                        default="",
                        show_default=False,
                    ).strip()
                    or None
                )
                if criteria_items:
                    criteria_input = click.prompt(
                        f"Acceptance criteria numbers for '{title}' (comma-separated)",
                        default="",
                        show_default=False,
                    )
                    for token in _parse_csv(criteria_input):
                        if token.isdigit():
                            idx = int(token)
                            if 1 <= idx <= len(criteria_items):
                                criteria_ids.append(criteria_items[idx - 1]["id"])
                if _prompt_bool(f"Is '{title}' a forward-looking task?", False):
                    tags.append("future")

            existing = existing_by_title.get(title.lower())
            if existing:
                task = existing
                console.print(f"[yellow]Using task:[/yellow] {task.title}")
            else:
                task = await task_service.create_task(
                    project_id=project.id,
                    title=title,
                    description=description,
                    priority=Priority.MEDIUM,
                    tags=tags or None,
                )
                console.print(f"[green]Created task:[/green] {task.title}")
            task_entries.append(
                {
                    "task": task,
                    "description": description,
                    "criteria_ids": criteria_ids,
                    "tags": tags,
                }
            )

        dependency_rows = []
        if task_entries and _prompt_bool("Add dependencies between tasks?", False):
            table = Table(title="Tasks")
            table.add_column("#", justify="right")
            table.add_column("Title")
            for idx, entry in enumerate(task_entries, start=1):
                table.add_row(str(idx), entry["task"].title)
            console.print(table)

            while True:
                depends_task = click.prompt(
                    "Task number that depends on others (blank to finish)",
                    default="",
                    show_default=False,
                )
                if not depends_task.strip():
                    break
                if not depends_task.isdigit():
                    console.print("[red]Enter a task number[/red]")
                    continue
                task_index = int(depends_task)
                if task_index < 1 or task_index > len(task_entries):
                    console.print("[red]Invalid task number[/red]")
                    continue
                depends_on_input = click.prompt(
                    "Depends on task numbers (comma-separated)",
                    default="",
                    show_default=False,
                )
                type_input = click.prompt(
                    "Dependency type (blocks, relates_to, duplicates)",
                    default="blocks",
                )
                dependency_type = _parse_dependency_type(type_input.strip())
                target_task = task_entries[task_index - 1]["task"]
                for token in _parse_csv(depends_on_input):
                    if not token.isdigit():
                        continue
                    dep_index = int(token)
                    if dep_index < 1 or dep_index > len(task_entries):
                        continue
                    depends_task_obj = task_entries[dep_index - 1]["task"]
                    dependency = await task_service.add_dependency(
                        target_task.id,
                        depends_task_obj.id,
                        dependency_type,
                    )
                    if dependency:
                        dependency_rows.append(
                            {
                                "task_id": target_task.id,
                                "task_title": target_task.title,
                                "depends_on_id": depends_task_obj.id,
                                "depends_on_title": depends_task_obj.title,
                                "type": dependency_type.value,
                            }
                        )

        if assign_workflow:
            for entry in task_entries:
                task = entry["task"]
                if task.workflow_id is None:
                    await assign_workflow_fn(
                        db=db,
                        event_store=event_store,
                        revision_store=revision_store,
                        metrics=metrics,
                        entity_type="task",
                        entity_id=task.id,
                        workflow_name=workflow_name,
                        initial_state=initial_state,
                    )

            if _prompt_bool("Assign workflow to the goal and objective?", False):
                await assign_workflow_fn(
                    db=db,
                    event_store=event_store,
                    revision_store=revision_store,
                    metrics=metrics,
                    entity_type="goal",
                    entity_id=goal.id,
                    workflow_name=workflow_name,
                    initial_state=initial_state,
                )
                await assign_workflow_fn(
                    db=db,
                    event_store=event_store,
                    revision_store=revision_store,
                    metrics=metrics,
                    entity_type="objective",
                    entity_id=objective.id,
                    workflow_name=workflow_name,
                    initial_state=initial_state,
                )

        plan_name = f"{project.name} Plan"
        plan_content = {
            "summary": "Loop setup plan",
            "goal": {"id": goal.id, "name": goal.name},
            "objective": {"id": objective.id, "name": objective.name},
            "acceptance_criteria": criteria_items,
            "tasks": [
                {
                    "id": entry["task"].id,
                    "title": entry["task"].title,
                    "description": entry["description"],
                    "acceptance_criteria": entry["criteria_ids"],
                    "tags": entry["tags"],
                }
                for entry in task_entries
            ],
            "dependencies": dependency_rows,
        }

        plan = await plan_service.create_plan(
            name=plan_name,
            description="Loop setup plan",
            status=PlanStatus.ACTIVE,
            format=PlanFormat.JSON,
            content=plan_content,
            product_id=product.id if product else None,
            project_id=project.id,
            goal_id=goal.id,
            objective_id=objective.id,
            task_ids=[entry["task"].id for entry in task_entries],
        )
        console.print(f"[green]Created plan:[/green] {plan.name}")

        prompt_lines = [
            "# Project",
            "",
            f"{project.name}",
            "",
            "# Goal",
            "",
            f"{goal.name} ({goal.id})",
            "",
            "# Acceptance Criteria (Objective + Key Results)",
            "",
            f"Objective: {objective.name} ({objective.id})",
            "",
            "Criteria:",
        ]
        for item in criteria_items:
            prompt_lines.append(
                f"- [{item['id']}] {item['description']} (key_result_id: {item['key_result_id']})"
            )
        prompt_lines.extend(
            [
                "",
                "# Plan",
                "",
                f"{plan.name} ({plan.id})",
                "",
                "# Tasks",
                "",
            ]
        )
        for entry in task_entries:
            task = entry["task"]
            criteria_label = ", ".join(entry["criteria_ids"]) or "-"
            prompt_lines.append(
                f"- {task.title} ({task.id}) criteria: {criteria_label}"
            )
        if dependency_rows:
            prompt_lines.extend(["", "# Dependencies", ""])
            for dep in dependency_rows:
                prompt_lines.append(
                    f"- {dep['task_title']} depends on {dep['depends_on_title']} ({dep['type']})"
                )
        prompt_lines.extend(
            [
                "",
                "# Loop Rules (must follow exactly)",
                "",
                "1) Read PMS state every iteration:",
                f'   - pms project show "{project.name}"',
                f'   - pms goal summary "{goal.name}"',
                f'   - pms plan show "{plan.name}" --project "{project.name}"',
                f'   - pms task list --project "{project.name}"',
                "2) For any task without workflow, assign the SDLC workflow:",
                "   - pms workflow assign <task_id> sdlc concept --entity-type task",
                "3) Check out tasks before work (distributed agents):",
                f'   - pms task checkout <task_id> --project "{project.name}" --agent-id loop-agent',
                "4) Update task progress and status:",
                f'   - pms task start <task_id> --project "{project.name}"',
                f'   - pms task progress <task_id> --project "{project.name}" <percent> <message> --by loop-agent',
                f'   - pms task complete <task_id> --project "{project.name}"',
                "5) Add new tasks if you discover gaps:",
                f'   - pms task create "{project.name}" "<new task title>"',
                "6) Attach evidence and test runs:",
                f'   - pms task evidence add <task_id> artifact <path> --project "{project.name}"',
                "   - pms test run .",
                f'   - pms task evidence add <task_id> test_run <run_id> --project "{project.name}"',
                "7) Update key results and objective progress as criteria are met:",
                f'   - pms keyresult update <key_result_id> --goal "{goal.name}" --progress <percent>',
                f'   - pms objective update "{objective.name}" --goal "{goal.name}" --progress <percent>',
                "8) Validate goal completion each loop:",
                f'   - pms goal summary "{goal.name}"',
                f'   - pms loop guard --project "{project.name}"',
                "9) Only emit <promise>DONE</promise> when all criteria are complete.",
            ]
        )

        prompt_target.write_text("\n".join(prompt_lines))

        config_lines = [
            "# PMS Agent Loop Configuration",
            f"agent: {agent}",
            "agent_priority:",
            "  - claude",
            "  - codex",
            "  - acp",
            f"prompt_file: {prompt_target}",
            "max_iterations: 100",
            "max_runtime: 14400",
            f"completion_promise: {completion_promise}",
            "stop_when_goals_complete: true",
            "goal_ids:",
            f"  - {goal.id}",
            "include_archived_goals: false",
            "allow_no_goals: false",
            "adapters:",
            "  claude:",
            "    type: claude",
            "    enabled: true",
            "  codex:",
            "    type: codex",
            "    enabled: false",
            "    command: codex-acp",
            "    args: []",
            "    codex_model: null",
            "    codex_reasoning_effort: null",
            "    permission_mode: interactive",
            "    permission_allowlist: []",
            "  command:",
            "    type: command",
            "    enabled: false",
            "    command: /path/to/agent",
            "    args: []",
            "    prompt_mode: stdin",
            "  acp:",
            "    type: acp",
            "    enabled: false",
            "    command: codex-acp",
            "    args: []",
            "    permission_mode: interactive",
            "    permission_allowlist: []",
            "",
        ]

        config_target.write_text("\n".join(config_lines))

        console.print(f"[green]Created:[/green] {config_target}")
        console.print(f"[green]Created:[/green] {prompt_target}")

        if run:
            from pms.agents import CoordinatorAgent
            from pms.agents.loop import LoopConfig
            from pms.memory import get_default_context_primer

            context_primer = get_default_context_primer()
            from pms.services.portfolio_service import PortfolioService
            from pms.services.program_service import ProgramService
            from pms.services.team_service import TeamService
            from pms.services.test_run_service import TestRunService

            portfolio_service = PortfolioService(
                db, event_store, revision_store, metrics
            )
            program_service = ProgramService(db, event_store, revision_store, metrics)
            team_service = TeamService(db, event_store, revision_store, metrics)
            test_run_service = TestRunService(db, metrics)

            agent_runner = CoordinatorAgent(
                project_service=project_service,
                task_service=task_service,
                goal_service=goal_service,
                plan_service=plan_service,
                organization_service=org_service,
                team_service=team_service,
                portfolio_service=portfolio_service,
                program_service=program_service,
                test_run_service=test_run_service,
                context_primer=context_primer,
                prime_context=True,
                max_turns=20,
                model="claude-sonnet-4-5",
            )

            loop_service = AgentLoopService(
                db,
                event_store,
                revision_store,
                metrics,
                coordinator_agent=agent_runner,
                goal_service=goal_service,
            )

            cfg = LoopConfig(
                agent=agent,
                prompt_file=prompt_target,
                completion_promise=completion_promise,
                stop_when_goals_complete=True,
                goal_ids=[goal.id],
            )

            console.print(
                f"[dim]Loop agent: {cfg.agent} | prompt: {cfg.prompt_source()}[/dim]"
            )

            def _on_iteration(iteration) -> None:
                status = "ok" if iteration.success else "fail"
                preview = (iteration.output or "")[:120].replace("\n", " ")
                console.print(
                    f"[cyan]Iteration {iteration.iteration}[/cyan] "
                    f"[dim]({status}, {iteration.duration_seconds:.1f}s)[/dim]"
                )
                if preview:
                    console.print(f"[dim]{preview}[/dim]")
                if iteration.error:
                    console.print(f"[red]{iteration.error}[/red]")

            summary = await loop_service.run_loop(
                cfg,
                project_id=project.id,
                on_iteration=_on_iteration,
            )

            console.print()
            console.print(
                f"[green]Loop ended:[/green] {summary.session_id} "
                f"[dim]({summary.stop_reason or 'completed'})[/dim]"
            )
            _print_next_steps(
                f"pms loop show {summary.session_id}",
                f"pms loop messages {summary.session_id}",
            )
        else:
            console.print("[dim]Next: pms loop run --config pms-loop.yml[/dim]")
    finally:
        await db.disconnect()


@loop.command("run")
@click.argument("prompt", nargs=-1)
@click.option("--config", "config_path", help="Loop config file (YAML/JSON/TOML)")
@click.option("--prompt-file", type=click.Path(path_type=Path))
@click.option("--project", "project_ref", help="Link loop to project name or ID")
@click.option("--project-id", help="Link loop to project ID")
@click.option("--agent", help="Adapter name (default: auto)")
@click.option("--agent-command", help="External agent command")
@click.option("--agent-arg", "agent_args", multiple=True, help="Agent arg (repeatable)")
@click.option("--codex", "use_codex", is_flag=True, help="Use Codex via ACP")
@click.option("--codex-model", help="Codex model override")
@click.option(
    "--codex-reasoning-effort",
    help="Codex reasoning effort override",
)
@click.option(
    "--codex-permission-mode",
    type=click.Choice(["auto_approve", "deny_all", "allowlist", "interactive"]),
    help="Codex permission mode",
)
@click.option(
    "--prompt-mode",
    type=click.Choice(["stdin", "arg", "file"]),
    default="stdin",
    show_default=True,
)
@click.option("--max-iterations", type=int, help="Maximum iterations")
@click.option("--max-runtime", type=int, help="Maximum runtime in seconds")
@click.option("--completion-promise", help="Promise tag for completion")
@click.option("--completion-marker", help="Marker string in prompt to stop")
@click.option(
    "--stop-when-goals-complete/--allow-stop-when-goals-incomplete",
    default=False,
    show_default=True,
    help="Block completion markers/promises until goals are complete",
)
@click.option("--goal", "goal_refs", multiple=True, help="Goal name or ID")
@click.option("--goal-id", "goal_ids", multiple=True, help="Goal ID")
@click.option(
    "--include-archived-goals",
    is_flag=True,
    help="Include archived goals in completion guard",
)
@click.option(
    "--allow-no-goals",
    is_flag=True,
    help="Allow stopping when no goals are found",
)
@click.option("--retry-delay", type=float, help="Delay between retries in seconds")
@click.option("--dry-run", is_flag=True, help="Skip agent execution")
@click.option(
    "-m",
    "--model",
    default="claude-sonnet-4-5",
    help="Claude model to use",
)
@click.option(
    "--max-turns",
    default=20,
    type=int,
    help="Maximum agent turns per iteration",
)
@click.option(
    "--prime-context/--no-prime-context",
    default=True,
    show_default=True,
    help="Include saved context primer in the agent system prompt",
)
@async_command
async def loop_run(
    prompt: tuple[str, ...],
    config_path: str | None,
    prompt_file: Path | None,
    project_ref: str | None,
    project_id: str | None,
    agent: str | None,
    agent_command: str | None,
    agent_args: tuple[str, ...],
    use_codex: bool,
    codex_model: str | None,
    codex_reasoning_effort: str | None,
    codex_permission_mode: str | None,
    prompt_mode: str,
    max_iterations: int | None,
    max_runtime: int | None,
    completion_promise: str | None,
    completion_marker: str | None,
    stop_when_goals_complete: bool,
    goal_refs: tuple[str, ...],
    goal_ids: tuple[str, ...],
    include_archived_goals: bool,
    allow_no_goals: bool,
    retry_delay: float | None,
    dry_run: bool,
    model: str,
    max_turns: int,
    prime_context: bool,
) -> None:
    """Run a Ralph-style agent loop."""
    from pms.agents import CoordinatorAgent
    from pms.agents.loop import AdapterConfig, LoopConfig, load_loop_config
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.memory import get_default_context_primer
    from pms.services import (
        AgentLoopService,
        GoalService,
        OrganizationService,
        PlanService,
        PortfolioService,
        ProgramService,
        ProjectService,
        TaskService,
        TeamService,
        TestRunService,
    )

    if project_ref and project_id:
        _emit_cli_error("Use --project or --project-id, not both", output_format="text")

    cfg = None
    resolved_config_path = _resolve_loop_config_path(config_path)
    if resolved_config_path:
        try:
            cfg = load_loop_config(resolved_config_path)
        except Exception as exc:
            console.print(f"[red]Failed to load config: {exc}[/red]")
            return
    else:
        cfg = LoopConfig()

    if prompt_file:
        cfg.prompt_file = prompt_file
        cfg.prompt_text = None
    if prompt:
        cfg.prompt_text = " ".join(prompt)
        cfg.prompt_file = None

    if use_codex and agent and agent != "codex":
        console.print(
            "[red]--codex cannot be combined with --agent unless agent is codex[/red]"
        )
        return

    if use_codex:
        agent = "codex"

    if agent:
        cfg.agent = agent
    if max_iterations is not None:
        cfg.max_iterations = max_iterations
    if max_runtime is not None:
        cfg.max_runtime_seconds = max_runtime
    if completion_promise is not None:
        cfg.completion_promise = completion_promise
    if completion_marker is not None:
        cfg.completion_marker = completion_marker
    if stop_when_goals_complete:
        cfg.stop_when_goals_complete = True
    if include_archived_goals:
        cfg.include_archived_goals = True
    if allow_no_goals:
        cfg.allow_no_goals = True
    if retry_delay is not None:
        cfg.retry_delay_seconds = retry_delay
    if dry_run:
        cfg.dry_run = True

    if agent_command:
        adapter_name = cfg.agent if cfg.agent != "auto" else "command"
        adapter_type = (
            "codex"
            if adapter_name == "codex"
            else "acp"
            if adapter_name == "acp"
            else "command"
        )
        cfg.agent = adapter_name
        cfg.adapters[adapter_name] = AdapterConfig(
            name=adapter_name,
            type=adapter_type,
            command=agent_command,
            agent_command=agent_command,
            args=list(agent_args),
            agent_args=list(agent_args),
            prompt_mode=prompt_mode,
        )
    elif cfg.agent == "codex":
        cfg.adapters.setdefault(
            "codex",
            AdapterConfig(
                name="codex",
                type="codex",
                agent_command="codex-acp",
                agent_args=list(agent_args),
                codex_model=codex_model,
                codex_reasoning_effort=codex_reasoning_effort,
                permission_mode=codex_permission_mode or "interactive",
            ),
        )
    elif cfg.agent == "acp":
        cfg.adapters.setdefault(
            "acp",
            AdapterConfig(
                name="acp",
                type="acp",
                agent_command="codex-acp" if use_codex else None,
                agent_args=list(agent_args),
                permission_mode=codex_permission_mode or "interactive",
            ),
        )

    if codex_model or codex_reasoning_effort or codex_permission_mode:
        codex_cfg = cfg.adapters.get("codex")
        if codex_cfg:
            if codex_model:
                codex_cfg.codex_model = codex_model
            if codex_reasoning_effort:
                codex_cfg.codex_reasoning_effort = codex_reasoning_effort
            if codex_permission_mode:
                codex_cfg.permission_mode = codex_permission_mode

    if cfg.prompt_text is None and cfg.prompt_file is None:
        _emit_cli_error("Provide a prompt or --prompt-file", output_format="text")

    db = await init_database()

    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)

        project_service = ProjectService(db, event_store, revision_store, metrics)
        task_service = TaskService(db, event_store, revision_store, metrics)
        test_run_service = TestRunService(db, metrics)
        goal_service = GoalService(db, event_store, revision_store, metrics)
        plan_service = PlanService(db, event_store, revision_store, metrics)
        organization_service = OrganizationService(
            db, event_store, revision_store, metrics
        )
        team_service = TeamService(db, event_store, revision_store, metrics)
        portfolio_service = PortfolioService(db, event_store, revision_store, metrics)
        program_service = ProgramService(db, event_store, revision_store, metrics)
        context_primer = get_default_context_primer() if prime_context else None

        agent_runner = CoordinatorAgent(
            project_service=project_service,
            task_service=task_service,
            goal_service=goal_service,
            plan_service=plan_service,
            organization_service=organization_service,
            team_service=team_service,
            portfolio_service=portfolio_service,
            program_service=program_service,
            test_run_service=test_run_service,
            context_primer=context_primer,
            prime_context=prime_context,
            max_turns=max_turns,
            model=model,
        )

        loop_service = AgentLoopService(
            db,
            event_store,
            revision_store,
            metrics,
            coordinator_agent=agent_runner,
            goal_service=goal_service,
        )

        resolved_project_id = project_id or await _resolve_project_id(
            project_ref, project_service
        )
        if project_ref and resolved_project_id is None:
            return

        resolved_goal_ids: list[str] = list(cfg.goal_ids)
        if goal_ids:
            resolved_goal_ids.extend(goal_ids)
        for goal_ref in goal_refs:
            resolved_goal_id = await _resolve_goal_id(goal_ref, goal_service)
            if resolved_goal_id is None:
                return
            resolved_goal_ids.append(resolved_goal_id)
        cfg.goal_ids = list(dict.fromkeys(resolved_goal_ids))

        if (
            cfg.stop_when_goals_complete
            and not cfg.goal_ids
            and not resolved_project_id
        ):
            console.print(
                "[red]Goal guard requires --project or explicit --goal/--goal-id[/red]"
            )
            return

        console.print(
            f"[dim]Loop agent: {cfg.agent} | prompt: {cfg.prompt_source()}[/dim]"
        )

        def _on_iteration(iteration) -> None:
            status = "ok" if iteration.success else "fail"
            preview = (iteration.output or "")[:120].replace("\n", " ")
            console.print(
                f"[cyan]Iteration {iteration.iteration}[/cyan] "
                f"[dim]({status}, {iteration.duration_seconds:.1f}s)[/dim]"
            )
            if preview:
                console.print(f"[dim]{preview}[/dim]")
            if iteration.error:
                console.print(f"[red]{iteration.error}[/red]")

        summary = await loop_service.run_loop(
            cfg,
            project_id=resolved_project_id,
            on_iteration=_on_iteration,
        )

        console.print()
        console.print(
            f"[green]Loop ended:[/green] {summary.session_id} "
            f"[dim]({summary.stop_reason or 'completed'})[/dim]"
        )
        _print_next_steps(
            f"pms loop show {summary.session_id}",
            f"pms loop messages {summary.session_id}",
        )

        await metrics.flush_best_effort(context="cli.loop_run")
    finally:
        await db.disconnect()


@loop.command("list")
@click.option("--project", "project_ref", help="Filter by project name or ID")
@click.option("--project-id", help="Filter by project ID")
@click.option("--include-ended", is_flag=True, help="Include ended loops")
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["table", "json"]),
    default="table",
    show_default=True,
)
@async_command
async def loop_list(
    project_ref: str | None,
    project_id: str | None,
    include_ended: bool,
    output_format: str,
) -> None:
    """List agent loops."""
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.services import AgentLoopService, ProjectService
    from pms.utils.time import format_relative

    if project_ref and project_id:
        _emit_cli_error(
            "Use --project or --project-id, not both",
            output_format="json" if output_format == "json" else "text",
        )

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        project_service = ProjectService(db, event_store, revision_store, metrics)
        loop_service = AgentLoopService(db, event_store, revision_store, metrics)

        resolved_project_id = project_id or await _resolve_project_id(
            project_ref, project_service
        )
        if project_ref and resolved_project_id is None:
            return

        loops = await loop_service.list_loops(
            project_id=resolved_project_id,
            include_ended=include_ended,
        )

        if output_format == "json":
            payload = [
                {
                    "id": loop.session_id,
                    "agent": loop.agent,
                    "status": loop.status,
                    "iterations": loop.iterations,
                    "max_iterations": loop.max_iterations,
                    "updated_at": loop.updated_at,
                    "updated_ago": format_relative(loop.updated_at),
                    "stop_reason": loop.stop_reason,
                }
                for loop in loops
            ]
            click.echo(json.dumps(payload, default=str))
            return

        table = Table(title="Agent Loops")
        table.add_column("ID")
        table.add_column("Agent")
        table.add_column("Status")
        table.add_column("Iter")
        table.add_column("Updated")
        table.add_column("Stop")

        for loop in loops:
            table.add_row(
                loop.session_id[:8],
                loop.agent,
                loop.status,
                f"{loop.iterations}/{loop.max_iterations or '-'}",
                format_relative(loop.updated_at),
                loop.stop_reason or "-",
            )

        console.print(table)
        console.print(f"[dim]Total: {len(loops)}[/dim]")
    finally:
        await db.disconnect()


@loop.command("show")
@click.argument("loop_id")
@click.option("--include-messages", is_flag=True, help="Include loop messages")
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["table", "json"]),
    default="table",
    show_default=True,
)
@async_command
async def loop_show(loop_id: str, include_messages: bool, output_format: str) -> None:
    """Show loop status and metadata."""
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.services import AgentLoopService
    from pms.utils.time import format_relative

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        loop_service = AgentLoopService(db, event_store, revision_store, metrics)

        summary = await loop_service.get_loop(loop_id)
        if summary is None:
            console.print(f"[red]Loop '{loop_id}' not found[/red]")
            return

        messages = None
        if include_messages:
            messages = await loop_service.get_loop_messages(loop_id)

        if output_format == "json":
            payload = {
                "loop": {
                    "id": summary.session_id,
                    "agent": summary.agent,
                    "status": summary.status,
                    "iterations": summary.iterations,
                    "max_iterations": summary.max_iterations,
                    "max_runtime_seconds": summary.max_runtime_seconds,
                    "stop_reason": summary.stop_reason,
                    "created_at": summary.created_at,
                    "updated_at": summary.updated_at,
                    "updated_ago": format_relative(summary.updated_at),
                    "ended_at": summary.ended_at,
                    "last_prompt": summary.last_prompt,
                    "last_response_summary": summary.last_response_summary,
                },
                "messages": messages,
            }
            click.echo(json.dumps(payload, default=str))
            return

        table = Table(title=f"Loop {summary.session_id}")
        table.add_column("Field")
        table.add_column("Value")
        table.add_row("Agent", summary.agent)
        table.add_row("Status", summary.status)
        table.add_row(
            "Iterations", f"{summary.iterations}/{summary.max_iterations or '-'}"
        )
        table.add_row("Updated", format_relative(summary.updated_at))
        table.add_row("Stop reason", summary.stop_reason or "-")
        if summary.ended_at:
            table.add_row("Ended", format_relative(summary.ended_at))
        console.print(table)

        if include_messages and messages:
            console.print()
            for item in messages:
                role = item.get("role", "?")
                content = item.get("content", "")
                stamp = item.get("timestamp")
                console.print(f"[bold]{role}[/bold] {stamp}")
                console.print(content)
                console.print()
    finally:
        await db.disconnect()


