@loop.command("guard")
@click.option("--project", "project_ref", help="Project name or ID")
@click.option("--project-id", help="Project ID")
@click.option("--goal", "goal_refs", multiple=True, help="Goal name or ID")
@click.option("--goal-id", "goal_ids", multiple=True, help="Goal ID")
@click.option(
    "--include-archived",
    is_flag=True,
    help="Include archived goals in the completion check",
)
@click.option(
    "--block-if-no-goals/--allow-no-goals",
    default=True,
    show_default=True,
    help="Block stop when no goals are found",
)
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["json", "text"]),
    default="json",
    show_default=True,
)
@click.option(
    "--hook",
    is_flag=True,
    help="Emit Claude Code Stop hook JSON payload",
)
@async_command
async def loop_guard(
    project_ref: str | None,
    project_id: str | None,
    goal_refs: tuple[str, ...],
    goal_ids: tuple[str, ...],
    include_archived: bool,
    block_if_no_goals: bool,
    output_format: str,
    hook: bool,
) -> None:
    """Block loop stop until goals are complete."""
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.models.base import now_utc
    from pms.models.enums import GoalStatus
    from pms.services import GoalService, ProjectService

    if project_ref and project_id:
        _emit_cli_error(
            "Use --project or --project-id, not both",
            output_format="json" if output_format == "json" else "text",
        )
    if not project_ref and not project_id and not goal_refs and not goal_ids:
        _emit_cli_error(
            "Provide --project or at least one goal",
            output_format="json" if output_format == "json" else "text",
        )

    db = await init_database()
    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)

        project_service = ProjectService(db, event_store, revision_store, metrics)
        goal_service = GoalService(db, event_store, revision_store, metrics)

        resolved_project_id = project_id or await _resolve_project_id(
            project_ref, project_service
        )
        if project_ref and resolved_project_id is None:
            return

        goals = []
        missing_refs: list[str] = []

        if goal_ids or goal_refs:
            for goal_id in goal_ids:
                goal = await goal_service.get_goal(goal_id)
                if goal is None:
                    missing_refs.append(goal_id)
                else:
                    goals.append(goal)
            for goal_ref in goal_refs:
                goal = await goal_service.get_goal(goal_ref)
                if goal is None:
                    goal = await goal_service.get_goal_by_name(goal_ref)
                if goal is None:
                    missing_refs.append(goal_ref)
                else:
                    goals.append(goal)
        else:
            if resolved_project_id is None:
                _emit_cli_error(
                    "Project is required to resolve goals",
                    output_format="json" if output_format == "json" else "text",
                )
            offset = 0
            limit = 200
            while True:
                result = await goal_service.list_goals(
                    project_id=resolved_project_id,
                    limit=limit,
                    offset=offset,
                )
                goals.extend(result.items)
                if not result.has_more:
                    break
                offset = result.offset + result.limit

        goal_map = {goal.id: goal for goal in goals}
        filtered_goals = list(goal_map.values())
        if not include_archived:
            filtered_goals = [
                goal for goal in filtered_goals if goal.status != GoalStatus.ARCHIVED
            ]

        incomplete_goals = [
            goal for goal in filtered_goals if goal.status != GoalStatus.COMPLETED
        ]
        completed_goals = [
            goal for goal in filtered_goals if goal.status == GoalStatus.COMPLETED
        ]
        archived_goals = [
            goal for goal in goal_map.values() if goal.status == GoalStatus.ARCHIVED
        ]

        blocked = False
        reasons: list[str] = []

        if missing_refs:
            blocked = True
            reasons.append(f"Unknown goals: {', '.join(missing_refs)}")

        if not filtered_goals:
            if block_if_no_goals:
                blocked = True
                reasons.append("No goals found for the guard scope")
        elif incomplete_goals:
            blocked = True
            names = ", ".join(goal.name for goal in incomplete_goals[:5])
            suffix = "..." if len(incomplete_goals) > 5 else ""
            reasons.append(
                f"{len(incomplete_goals)} incomplete goal(s): {names}{suffix}"
            )

        reason = "All goals are completed."
        if reasons:
            reason = " | ".join(reasons)

        project_name = project_ref
        if resolved_project_id:
            project = await project_service.get_project(resolved_project_id)
            if project:
                project_name = project.name

        def _goal_payload(goal) -> dict[str, Any]:
            return {
                "id": goal.id,
                "name": goal.name,
                "status": goal.status.value,
                "horizon": goal.horizon.value,
                "progress_percent": goal.progress_percent,
                "project_id": goal.project_id,
                "product_id": goal.product_id,
                "created_at": _to_iso(goal.created_at),
                "updated_at": _to_iso(goal.updated_at),
            }

        payload = {
            "ok": not blocked,
            "blocked": blocked,
            "reason": reason,
            "generated_at": _to_iso(now_utc()),
            "scope": {
                "project_id": resolved_project_id,
                "project_name": project_name,
                "goal_ids": [goal.id for goal in filtered_goals],
            },
            "counts": {
                "total_goals": len(filtered_goals),
                "completed_goals": len(completed_goals),
                "incomplete_goals": len(incomplete_goals),
                "archived_goals": len(archived_goals),
            },
            "goals": [_goal_payload(goal) for goal in filtered_goals],
            "incomplete": [_goal_payload(goal) for goal in incomplete_goals],
            "completed": [_goal_payload(goal) for goal in completed_goals],
            "archived": [_goal_payload(goal) for goal in archived_goals],
            "missing_goals": missing_refs,
            "include_archived": include_archived,
            "block_if_no_goals": block_if_no_goals,
        }

        if hook:
            hook_payload: dict[str, Any] = {"metadata": payload}
            if blocked:
                hook_payload["decision"] = "block"
                hook_payload["reason"] = reason
            click.echo(json.dumps(hook_payload))
            return

        if output_format == "json":
            click.echo(json.dumps(payload, indent=2))
            return

        status = "blocked" if blocked else "clear"
        console.print(f"[bold]Loop guard:[/bold] {status}")
        console.print(reason)
        if incomplete_goals:
            console.print()
            console.print("[bold]Incomplete goals:[/bold]")
            for goal in incomplete_goals:
                console.print(f"- {goal.name} ({goal.status.value})")
        if missing_refs:
            console.print()
            console.print("[bold]Missing goals:[/bold]")
            for ref in missing_refs:
                console.print(f"- {ref}")
    finally:
        await db.disconnect()


@cli.command(
    "dashboard",
    epilog=_help_epilog(
        "dashboard",
        "dashboard --format json",
        "plan list",
        "task blocked --format json",
    ),
)
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["table", "json", "csv"]),
    default="table",
    show_default=True,
)
@async_command
async def dashboard_cmd(output_format: str) -> None:
    """Show the instance-wide operator dashboard with scope and queue context."""
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.models import TaskStatus
    from pms.services import ProjectService, QueueService, TaskService
    from pms.services.actor_service import ActorService
    from pms.utils.time import format_relative

    db = await init_database()

    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)

        service = ProjectService(db, event_store, revision_store, metrics)
        dashboard = await service.get_dashboard()
        task_service = TaskService(db, event_store, revision_store, metrics)
        actor_service = ActorService(db, event_store, revision_store, metrics)
        ready_tasks = await task_service.list_ready_tasks(
            limit=_OPERATOR_VIEW_CANDIDATE_LIMIT
        )
        in_progress_tasks = await task_service.search_tasks(
            statuses=[TaskStatus.IN_PROGRESS],
            limit=_OPERATOR_VIEW_CANDIDATE_LIMIT,
        )
        queue_service = QueueService(task_service)
        queue_presets = await queue_service.list_presets(
            limit=_OPERATOR_VIEW_CANDIDATE_LIMIT
        )
        ready_activity = await task_service.get_last_activity_map(
            [task.id for task in ready_tasks.items]
        )
        in_progress_activity = await task_service.get_last_activity_map(
            [task.id for task in in_progress_tasks.items]
        )

        excluded_project_ids = await _operator_hidden_project_ids_for_task_views(
            service,
            task_service,
            active_projects=dashboard.active_projects,
            candidate_limit=_OPERATOR_VIEW_CANDIDATE_LIMIT,
        )
        generated_project_ids = await _generated_project_ids(
            service,
            [
                *(summary.project.id for summary in dashboard.active_projects),
            ],
        )
        visible_ready_tasks = _slice_visible_tasks(
            ready_tasks.items,
            excluded_project_ids,
            limit=5,
        )
        visible_in_progress_tasks = _slice_visible_tasks(
            in_progress_tasks.items,
            excluded_project_ids,
            limit=5,
        )
        visible_active_projects = _exclude_active_project_summaries(
            dashboard.active_projects,
            excluded_project_ids,
        )
        visible_goal_horizon_stats = await service.compute_effective_goal_horizon_stats(
            [summary.project.id for summary in visible_active_projects]
        )
        recent_completed_projects = await _recent_operator_visible_completed_projects(
            service,
            limit=3,
        )
        recent_completed_activity = await service.get_last_activity_map(
            [project.id for project in recent_completed_projects]
        )
        recent_completed_transition = await service.get_last_transition_map(
            [project.id for project in recent_completed_projects]
        )

        ready_project_names: dict[str, str] = {}
        in_progress_project_names: dict[str, str] = {}
        for task in visible_ready_tasks:
            if task.project_id and task.project_id not in ready_project_names:
                project = await service.get_project(task.project_id)
                if project:
                    ready_project_names[task.project_id] = project.name
        for task in visible_in_progress_tasks:
            if task.project_id and task.project_id not in in_progress_project_names:
                project = await service.get_project(task.project_id)
                if project:
                    in_progress_project_names[task.project_id] = project.name

        queue_project_names: dict[str, str] = {}
        for summary in queue_presets:
            for task in summary.items:
                if task.project_id in excluded_project_ids:
                    continue
                if task.project_id and task.project_id not in queue_project_names:
                    project = await service.get_project(task.project_id)
                    if project:
                        queue_project_names[task.project_id] = project.name

        visible_queue_presets = [
            await _resolve_visible_queue_summary(
                queue_service=queue_service,
                summary=summary,
                excluded_project_ids=excluded_project_ids,
                item_limit=3,
            )
            for summary in queue_presets
        ]
        visible_totals = _visible_dashboard_totals(visible_active_projects)
        blocked_tasks = await task_service.get_blocked_tasks()
        overdue_tasks = await task_service.get_overdue_tasks()
        visible_blocked_tasks = _exclude_tasks_from_projects(
            blocked_tasks,
            excluded_project_ids,
        )
        visible_overdue_tasks = _exclude_tasks_from_projects(
            overdue_tasks,
            excluded_project_ids,
        )
        blocked_activity = await task_service.get_last_activity_map(
            [task.id for task in visible_blocked_tasks]
        )
        blocked_project_names: dict[str, str | None] = {}
        for task in visible_blocked_tasks:
            if task.project_id and task.project_id not in blocked_project_names:
                project = await service.get_project(task.project_id)
                if project:
                    blocked_project_names[task.project_id] = project.name
        from pms.repositories.task_repository import TaskRepository

        task_repo = TaskRepository(db, event_store, revision_store, metrics)
        blocked_detail_map = await _build_blocked_task_detail_map(
            visible_blocked_tasks,
            task_service=task_service,
            task_repo=task_repo,
            project_service=service,
        )
        dashboard_tasks = [
            *visible_ready_tasks,
            *visible_in_progress_tasks,
            *visible_blocked_tasks,
            *[task for summary in visible_queue_presets for task in summary["items"]],
        ]
        assignee_map = await _resolve_assignee_map(
            dashboard_tasks,
            actor_service,
        )
        checkout_actor_map = await _resolve_checkout_actor_map(
            dashboard_tasks,
            actor_service,
        )
        dashboard_task_lookup = {task.id: task for task in dashboard_tasks}

        dashboard_links = _normalize_command_links(
            {
                "self": "dashboard --format json",
                "guide": "start --format json",
                "queues": "queue presets --format json",
                "daily": (
                    "work daily --scope-type project --scope <project_name> --format json"
                ),
            }
        )
        next_steps: list[str] = []
        focus_project_names: dict[str, str | None] = {
            **ready_project_names,
            **in_progress_project_names,
        }
        focus_target = _select_command_focus(
            [*visible_ready_tasks, *visible_in_progress_tasks],
            focus_project_names,
        )
        focus_task_payload = (
            focus_target.to_payload() if focus_target is not None else None
        )
        if focus_task_payload is not None:
            focus_task_model = dashboard_task_lookup.get(focus_task_payload["id"])
            if focus_task_model is not None:
                focus_task_payload["assignee"] = _task_assignee_payload(
                    focus_task_model,
                    assignee_map,
                )
                focus_task_payload["checkout"] = _task_checkout_payload(
                    focus_task_model,
                    checkout_actor_map,
                )
                focus_task_payload["links"] = _normalize_command_links(
                    {
                        "self": f"task show {focus_task_model.id}",
                        "actor": _task_assignee_actor_link(
                            focus_task_model,
                            assignee_map,
                        ),
                        "checkout_actor": _task_checkout_actor_link(
                            focus_task_model,
                            checkout_actor_map,
                        ),
                    }
                )
        if focus_target is not None:
            next_steps.extend(focus_target.next_steps())
            if focus_target.project_name:
                focus_daily = f'work daily --scope-type project --scope "{focus_target.project_name}" --format json'
                next_steps.append(_cli_command(focus_daily))
                dashboard_links["daily_focus"] = _cli_command(focus_daily)
        elif not visible_active_projects:
            next_steps.append(_cli_command("quickstart --defaults"))
        if visible_active_projects:
            next_steps.append(
                _cli_command(
                    f'work daily --scope-type project --scope "{visible_active_projects[0].project.name}" --format json'
                )
            )
        next_steps.append(_cli_command("queue presets --format json"))
        next_steps.append(_cli_command("start --format json"))
        coordination = _runtime_coordination_status()
        if coordination.state != "server_coordinated":
            next_steps = _normalize_next_steps(
                *coordination.recommended_next_steps,
                *next_steps,
            )
        if recent_completed_projects and (
            visible_totals["active_projects"] == 0
            or focus_target is None
            or focus_target.status_value != TaskStatus.IN_PROGRESS.value
        ):
            recent_project = recent_completed_projects[0]
            next_steps = _normalize_next_steps(
                *next_steps,
                _cli_command(f'project show "{recent_project.name}" --format json'),
                _cli_command(
                    f'task list --project "{recent_project.name}" --format json'
                ),
            )
        dashboard_scope = _instance_scope_summary(
            noun="dashboard",
            active_count=visible_totals["active_projects"],
            recent_completed_count=len(recent_completed_projects),
        )
        completion_context: dict[str, Any] | None = None
        completion_summary: str | None = None
        terminal_reason: str | None = None
        if recent_completed_projects:
            completion_summary = _recent_terminal_project_completion_summary(
                no_other_visible_active_work=visible_totals["active_projects"] == 0,
                active_surface_label="dashboard",
            )
            if visible_totals["active_projects"] == 0:
                terminal_reason = "all surfaced projects are already terminal"

        active_project_payloads = [
            _project_summary_surface_payload(summary)
            for summary in visible_active_projects
        ]
        (
            recent_completed_project_payloads,
            recent_completed_activity,
            recent_completed_transition,
        ) = await _recent_completed_project_surface_payloads(
            service,
            recent_completed_projects,
            activity_map=recent_completed_activity,
            transition_map=recent_completed_transition,
        )
        if recent_completed_project_payloads and completion_summary is not None:
            recent_project_name = recent_completed_project_payloads[0].get(
                "project_name"
            ) or recent_completed_project_payloads[0].get("name")
            completion_context = {
                "summary": completion_summary,
                "items": _recent_terminal_project_completion_items(
                    recent_completed_project_payloads
                ),
                "next_steps": _normalize_next_steps(
                    _cli_command(f'project show "{recent_project_name}" --format json')
                    if recent_project_name
                    else None,
                    "dashboard --format json",
                    "start --format json",
                ),
            }
        visible_project_payload_by_id = {
            str(payload["project_id"]): payload
            for payload in [
                *active_project_payloads,
                *recent_completed_project_payloads,
            ]
            if payload.get("project_id") is not None
        }
        dashboard_visible_projects = [
            *(summary.project for summary in visible_active_projects),
            *recent_completed_projects,
        ]
        dashboard_visible_activity_map = {
            summary.project.id: summary.last_activity_at
            for summary in visible_active_projects
        }
        dashboard_visible_activity_map.update(recent_completed_activity)
        dashboard_visible_transition_map = {
            summary.project.id: summary.last_transition_at
            for summary in visible_active_projects
        }
        dashboard_visible_transition_map.update(recent_completed_transition)
        freshest_visible_project_activity = _freshest_entity_timestamp_entry(
            dashboard_visible_projects,
            dashboard_visible_activity_map,
            fallback_to_updated_at=True,
        )
        freshest_visible_project_transition = _freshest_entity_timestamp_entry(
            dashboard_visible_projects,
            dashboard_visible_transition_map,
        )

        if output_format == "json":
            payload = {
                "scope": {
                    "kind": "instance_dashboard",
                    "summary": dashboard_scope,
                    "active_visible_projects": visible_totals["active_projects"],
                    "recently_completed_projects": len(recent_completed_projects),
                },
                "total_projects": visible_totals["active_projects"],
                "total_tasks": visible_totals["total_tasks"],
                "completed_tasks": visible_totals["completed_tasks"],
                "blocked_tasks": len(visible_blocked_tasks),
                "overdue_tasks": len(visible_overdue_tasks),
                "visible_totals": {
                    "population": "visible_operator",
                    "total_projects": visible_totals["active_projects"],
                    "total_tasks": visible_totals["total_tasks"],
                    "completed_tasks": visible_totals["completed_tasks"],
                    "blocked_tasks": len(visible_blocked_tasks),
                    "overdue_tasks": len(visible_overdue_tasks),
                },
                "instance_totals": {
                    "population": "all_non_archived_retained",
                    "total_projects": dashboard.total_projects,
                    "total_tasks": dashboard.total_tasks,
                    "completed_tasks": dashboard.completed_tasks,
                    "blocked_tasks": len(blocked_tasks),
                    "overdue_tasks": len(overdue_tasks),
                },
                "suppressed_generated_projects": len(generated_project_ids),
                "suppressed_hidden_projects": len(excluded_project_ids),
                "purpose": "Overall live-state control plane for project health, ready work, and next operator actions.",
                "artifacts_created": [],
                "completion_context": completion_context,
                "terminal_reason": terminal_reason,
                "freshest_visible_activity": (
                    visible_project_payload_by_id.get(
                        freshest_visible_project_activity[0].id
                    )
                    if freshest_visible_project_activity is not None
                    else None
                ),
                "freshest_visible_transition": (
                    visible_project_payload_by_id.get(
                        freshest_visible_project_transition[0].id
                    )
                    if freshest_visible_project_transition is not None
                    else None
                ),
                "runtime": {
                    "managed_servers": _managed_runtime_servers(),
                    "coordination": coordination.to_dict(),
                },
                "focus_task": focus_task_payload,
                "graph_navigation": _command_focus_graph_navigation(
                    focus_task=focus_target,
                    task_lookup=dashboard_task_lookup,
                    assignee_map=assignee_map,
                    project_id=focus_target.project_id
                    if focus_target is not None
                    else None,
                    project_name=focus_target.project_name
                    if focus_target is not None
                    else None,
                ),
                "actor_rollups": _actor_rollups_payload(
                    tasks=dashboard_tasks,
                    assignee_map=assignee_map,
                    checkout_actor_map=checkout_actor_map,
                    population_basis="dashboard_visible_tasks",
                ),
                "goal_horizon_stats": dashboard.goal_horizon_stats,
                "goal_horizon_stats_population": "all_non_archived_retained",
                "visible_goal_horizon_stats": visible_goal_horizon_stats,
                "visible_goal_horizon_stats_population": "visible_operator",
                "ready_tasks": [
                    {
                        "task_id": task.id,
                        "title": task.title,
                        "status": task.status.value,
                        "workflow_state": task.current_state,
                        "assignee": _task_assignee_payload(task, assignee_map),
                        "checkout": _task_checkout_payload(task, checkout_actor_map),
                        "project_id": task.project_id,
                        "project_name": ready_project_names.get(task.project_id)
                        if task.project_id
                        else None,
                        "links": _normalize_command_links(
                            {
                                "self": f"task show {task.id}",
                                "actor": _task_assignee_actor_link(task, assignee_map),
                                "checkout_actor": _task_checkout_actor_link(
                                    task, checkout_actor_map
                                ),
                            }
                        ),
                    }
                    for task in visible_ready_tasks
                ],
                "in_progress_tasks": [
                    {
                        "task_id": task.id,
                        "title": task.title,
                        "status": task.status.value,
                        "workflow_state": task.current_state,
                        "progress_percent": task.current_progress_percent,
                        "assignee": _task_assignee_payload(task, assignee_map),
                        "checkout": _task_checkout_payload(task, checkout_actor_map),
                        "project_id": task.project_id,
                        "project_name": in_progress_project_names.get(task.project_id)
                        if task.project_id
                        else None,
                        "links": _normalize_command_links(
                            {
                                "self": f"task show {task.id}",
                                "actor": _task_assignee_actor_link(task, assignee_map),
                                "checkout_actor": _task_checkout_actor_link(
                                    task, checkout_actor_map
                                ),
                            }
                        ),
                    }
                    for task in visible_in_progress_tasks
                ],
                "blocked_items": [
                    {
                        "task_id": task.id,
                        "title": task.title,
                        "status": task.status.value,
                        "project_id": task.project_id,
                        "project_name": blocked_project_names.get(task.project_id)
                        if task.project_id
                        else None,
                        "last_activity_at": _to_iso(blocked_activity.get(task.id)),
                        "assignee": _task_assignee_payload(task, assignee_map),
                        "checkout": _task_checkout_payload(task, checkout_actor_map),
                        "blocked_by": blocked_detail_map.get(task.id, {}).get(
                            "blocked_by",
                            [],
                        ),
                        "blocked_by_details": blocked_detail_map.get(
                            task.id,
                            {},
                        ).get("blocked_by_details", []),
                        "blocked_summary": blocked_detail_map.get(task.id, {}).get(
                            "blocked_summary",
                            "No dependency detail recorded",
                        ),
                        "links": _normalize_command_links(
                            {
                                "self": f"task show {task.id}",
                                "graph": f"task graph {task.id}",
                                "blocked": "task blocked --format json",
                                "actor": _task_assignee_actor_link(task, assignee_map),
                                "checkout_actor": _task_checkout_actor_link(
                                    task, checkout_actor_map
                                ),
                            }
                        ),
                    }
                    for task in visible_blocked_tasks[:5]
                ],
                "active_projects": active_project_payloads,
                "recently_completed_projects": recent_completed_project_payloads,
                "ready_tasks_last_activity": {
                    task.id: _to_iso(ready_activity.get(task.id))
                    for task in visible_ready_tasks
                },
                "in_progress_last_activity": {
                    task.id: _to_iso(in_progress_activity.get(task.id))
                    for task in visible_in_progress_tasks
                },
                "queue_presets": [
                    {
                        "name": summary["name"],
                        "description": summary["description"],
                        "population": "visible_operator",
                        "total_count": summary["total_count"],
                        "displayed_count": len(summary["items"]),
                        "is_truncated": len(summary["items"]) < summary["total_count"],
                        "items": [
                            {
                                "task_id": task.id,
                                "title": task.title,
                                "status": task.status.value,
                                "assignee": _task_assignee_payload(task, assignee_map),
                                "checkout": _task_checkout_payload(
                                    task, checkout_actor_map
                                ),
                                "project_id": task.project_id,
                                "project_name": queue_project_names.get(task.project_id)
                                if task.project_id
                                else None,
                                "updated_at": _to_iso(task.updated_at),
                                "blocked_summary": blocked_detail_map.get(
                                    task.id,
                                    {},
                                ).get("blocked_summary"),
                                "links": _normalize_command_links(
                                    {
                                        "self": f"task show {task.id}",
                                        "actor": _task_assignee_actor_link(
                                            task, assignee_map
                                        ),
                                        "checkout_actor": _task_checkout_actor_link(
                                            task, checkout_actor_map
                                        ),
                                    }
                                ),
                            }
                            for task in summary["items"]
                        ],
                    }
                    for summary in visible_queue_presets
                ],
                "links": dashboard_links,
                "next_steps": _normalize_next_steps(*next_steps),
            }
            payload = _payload_with_normalized_next_steps(
                payload, *payload["next_steps"]
            )
            click.echo(json.dumps(payload, default=str))
            return

        if output_format == "csv":
            headers = [
                "total_projects",
                "total_tasks",
                "completed_tasks",
                "blocked_tasks",
                "overdue_tasks",
                "instance_total_projects",
                "instance_total_tasks",
                "instance_completed_tasks",
                "instance_blocked_tasks",
                "instance_overdue_tasks",
                "suppressed_generated_projects",
                "suppressed_hidden_projects",
            ]
            click.echo(_csv_row(headers))
            row = [
                str(visible_totals["active_projects"]),
                str(visible_totals["total_tasks"]),
                str(visible_totals["completed_tasks"]),
                str(len(visible_blocked_tasks)),
                str(len(visible_overdue_tasks)),
                str(dashboard.total_projects),
                str(dashboard.total_tasks),
                str(dashboard.completed_tasks),
                str(len(blocked_tasks)),
                str(len(overdue_tasks)),
                str(len(generated_project_ids)),
                str(len(excluded_project_ids)),
            ]
            click.echo(_csv_row(row))
            if visible_active_projects:
                project_headers = [
                    "project_id",
                    "project_name",
                    "health_score",
                    "completed_tasks",
                    "total_tasks",
                    "last_activity_at",
                    "last_transition_at",
                ]
                click.echo(_csv_row(project_headers))
                for summary in visible_active_projects:
                    click.echo(
                        _csv_row(
                            [
                                summary.project.id,
                                summary.project.name,
                                f"{summary.health_score:.2f}",
                                str(summary.stats.completed_tasks)
                                if summary.stats
                                else "0",
                                str(summary.stats.total_tasks)
                                if summary.stats
                                else "0",
                                _to_iso(summary.last_activity_at) or "",
                                _to_iso(summary.last_transition_at) or "",
                            ]
                        )
                    )
            if dashboard.goal_horizon_stats:
                goal_headers = [
                    "horizon",
                    "total_goals",
                    "completed_goals",
                    "avg_progress",
                ]
                click.echo(_csv_row(goal_headers))
                for horizon, stats in dashboard.goal_horizon_stats.items():
                    click.echo(
                        _csv_row(
                            [
                                horizon,
                                str(stats.get("total_goals", 0)),
                                str(stats.get("completed_goals", 0)),
                                f"{stats.get('avg_progress', 0.0):.1f}",
                            ]
                        )
                    )
            if visible_queue_presets:
                queue_headers = ["queue_name", "total_count", "description"]
                click.echo(_csv_row(queue_headers))
                for summary in visible_queue_presets:
                    click.echo(
                        _csv_row(
                            [
                                summary["name"],
                                str(len(summary["items"])),
                                summary["description"],
                            ]
                        )
                    )
            return

        console.print("[bold]Dashboard Overview[/bold]")
        console.print("=" * 40)
        console.print(f"Scope: {dashboard_scope}")
        console.print(
            "Purpose: overall live-state control plane for project health, ready work, and next operator actions."
        )
        console.print(
            "Creates: no new state; this command reads current live system status."
        )
        console.print(f"Visible Active Projects: {visible_totals['active_projects']}")
        console.print(f"Visible Tasks: {visible_totals['total_tasks']}")
        console.print(
            f"Completed: [green]{visible_totals['completed_tasks']}[/green] / {visible_totals['total_tasks']}"
        )
        if excluded_project_ids:
            console.print(
                "Instance Totals: "
                f"{dashboard.total_projects} projects, "
                f"{dashboard.total_tasks} tasks, "
                f"{dashboard.completed_tasks} completed, "
                f"{len(blocked_tasks)} blocked"
            )
            console.print(
                f"Suppressed generated projects: [dim]{len(generated_project_ids)}[/dim]"
            )
            hidden_non_generated = len(excluded_project_ids) - len(
                generated_project_ids
            )
            if hidden_non_generated > 0:
                console.print(
                    f"Suppressed non-active projects: [dim]{hidden_non_generated}[/dim]"
                )
        if coordination.state != "server_coordinated":
            console.print(
                f"Runtime Coordination: [yellow]{coordination.summary}[/yellow]"
            )
            if coordination.reason:
                console.print(f"Reason: {coordination.reason}")

        if visible_blocked_tasks:
            console.print(f"Blocked: [red]{len(visible_blocked_tasks)}[/red]")
        if visible_overdue_tasks:
            console.print(f"Overdue: [yellow]{len(visible_overdue_tasks)}[/yellow]")
        if freshest_visible_project_activity is not None:
            console.print(
                "Freshest Visible Activity: "
                f"{freshest_visible_project_activity[0].name} "
                f"({format_relative(freshest_visible_project_activity[1])})"
            )
        if freshest_visible_project_transition is not None:
            console.print(
                "Freshest Visible Transition: "
                f"{freshest_visible_project_transition[0].name} "
                f"({format_relative(freshest_visible_project_transition[1])})"
            )

        if visible_active_projects:
            console.print()
            console.print("[bold]Active Projects:[/bold]")

            table = Table()
            table.add_column("Project", style="cyan")
            table.add_column("Health", justify="right")
            table.add_column("Tasks")
            table.add_column("Activity")
            table.add_column("Transition")

            for summary in visible_active_projects:
                health_style = (
                    "green"
                    if summary.health_score >= 0.7
                    else "yellow"
                    if summary.health_score >= 0.4
                    else "red"
                )
                tasks_info = "-"
                if summary.stats:
                    tasks_info = (
                        f"{summary.stats.completed_tasks}/{summary.stats.total_tasks}"
                    )

                table.add_row(
                    summary.project.name,
                    f"[{health_style}]{summary.health_score:.0%}[/{health_style}]",
                    tasks_info,
                    format_relative(summary.last_activity_at),
                    format_relative(summary.last_transition_at),
                )

            console.print(table)

        if recent_completed_projects:
            console.print()
            console.print("[bold]Recently Completed Projects:[/bold]")
            for project in recent_completed_projects:
                activity_stamp = (
                    recent_completed_activity.get(project.id)
                    or project.updated_at
                    or project.created_at
                )
                transition_stamp = recent_completed_transition.get(project.id)
                console.print(
                    f"- {project.name} "
                    f"(activity {format_relative(activity_stamp)}"
                    f"; transition {format_relative(transition_stamp)})"
                )
            console.print(
                "Completed-scope shortcuts: "
                + ", ".join(
                    _cli_command(f'project show "{project.name}" --format json')
                    for project in recent_completed_projects
                )
            )

        if dashboard.goal_horizon_stats:
            console.print()
            console.print("[bold]Goals by Horizon:[/bold]")
            goal_table = Table()
            goal_table.add_column("Horizon", style="cyan")
            goal_table.add_column("Goals")
            goal_table.add_column("Avg Progress")
            for horizon, stats in dashboard.goal_horizon_stats.items():
                goal_table.add_row(
                    horizon,
                    f"{stats.get('completed_goals', 0)}/{stats.get('total_goals', 0)}",
                    f"{stats.get('avg_progress', 0.0):.1f}%",
                )
            console.print(goal_table)

        if focus_task_payload is not None:
            console.print()
            console.print(
                "Focus: "
                f"{focus_task_payload['title']} "
                f"[{focus_task_payload['status']}] "
                f"({focus_task_payload['current_progress_percent']}%)"
            )
            console.print(f"Why: {focus_task_payload['reason']}")

        if visible_queue_presets:
            console.print()
            console.print("[bold]Queues:[/bold]")
            for summary in visible_queue_presets:
                console.print(
                    f"- {summary['name']} "
                    f"({'showing ' + str(len(summary['items'])) + ' of ' + str(summary['total_count']) if len(summary['items']) < summary['total_count'] else str(summary['total_count'])}) "
                    f"{summary['description']}"
                )
                for task in summary["items"]:
                    project_label = (
                        queue_project_names.get(task.project_id, task.project_id)
                        if task.project_id
                        else "unknown"
                    )
                    blocked_suffix = ""
                    if summary["name"] == "blocked":
                        blocked_summary = blocked_detail_map.get(task.id, {}).get(
                            "blocked_summary"
                        )
                        if blocked_summary:
                            blocked_suffix = f" blocked by {blocked_summary}"
                    console.print(
                        f"  - {task.title} [{project_label}] "
                        f"updated {format_relative(task.updated_at)}{blocked_suffix}"
                    )

        console.print()
        if visible_ready_tasks:
            console.print("[bold]Next Actions (Ready Tasks):[/bold]")
            for task in visible_ready_tasks:
                project_label = (
                    ready_project_names.get(task.project_id, task.project_id)
                    if task.project_id
                    else "unknown"
                )
                workflow_state = task.current_state or "-"
                last_activity = ready_activity.get(task.id)
                console.print(
                    f"- {task.title} [{project_label}] "
                    f"status {task.status.value} workflow {workflow_state} "
                    f"activity {format_relative(last_activity or task.updated_at)} id {task.id[:8]}"
                )
        else:
            console.print("[bold]Next Actions (Ready Tasks):[/bold] none")

        console.print()
        if visible_in_progress_tasks:
            console.print("[bold]In Progress:[/bold]")
            for task in visible_in_progress_tasks:
                project_label = (
                    in_progress_project_names.get(task.project_id, task.project_id)
                    if task.project_id
                    else "unknown"
                )
                workflow_state = task.current_state or "-"
                progress = f"{task.current_progress_percent}%"
                last_activity = in_progress_activity.get(task.id)
                console.print(
                    f"- {task.title} [{project_label}] "
                    f"workflow {workflow_state} progress {progress} "
                    f"activity {format_relative(last_activity or task.updated_at)} id {task.id[:8]}"
                )
        else:
            console.print("[bold]In Progress:[/bold] none")

        console.print()
        if visible_blocked_tasks:
            console.print("[bold]Blocked:[/bold]")
            for task in visible_blocked_tasks[:5]:
                project_label = (
                    blocked_project_names.get(task.project_id, task.project_id)
                    if task.project_id
                    else "unknown"
                )
                blocked_summary = blocked_detail_map.get(task.id, {}).get(
                    "blocked_summary",
                    "No dependency detail recorded",
                )
                console.print(
                    f"- {task.title} [{project_label}] "
                    f"blocked by {blocked_summary} "
                    f"activity {format_relative(blocked_activity.get(task.id) or task.updated_at)} "
                    f"id {task.id[:8]}"
                )
        else:
            console.print("[bold]Blocked:[/bold] none")

        _print_next_steps(*next_steps)

    finally:
        await db.disconnect()


@cli.group()
def remote() -> None:
    """Manage remote hosts and operations."""
    pass


@remote.command("add")
@click.argument("name")
@click.argument("host")
@click.argument("username")
@click.option("-p", "--port", default=22, type=int, help="SSH port")
@click.option("-k", "--key", "key_path", help="Path to SSH private key")
@click.option("-r", "--remote-path", help="Default remote path for syncs")
@click.option("-t", "--tag", "tags", multiple=True, help="Host tags")
@async_command
async def remote_add(
    name: str,
    host: str,
    username: str,
    port: int,
    key_path: str | None,
    remote_path: str | None,
    tags: tuple[str, ...],
) -> None:
    """Add a new remote host configuration.

    Examples:
        pms remote add myserver 192.168.1.100 deploy
        pms remote add prod example.com admin -k ~/.ssh/id_rsa -r /var/www
    """
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.services import RemoteService

    db = await init_database()

    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)

        service = RemoteService(db, event_store, revision_store, metrics)

        remote_host = await service.add_host(
            name=name,
            host=host,
            username=username,
            port=port,
            key_path=key_path,
            default_remote_path=remote_path,
            tags=list(tags) if tags else None,
        )

        await metrics.flush_best_effort(context="cli.remote_add")

        console.print(f"[green]Added remote host:[/green] {remote_host.name}")
        console.print(f"[dim]ID: {remote_host.id}[/dim]")
        console.print(f"[dim]Connection: {username}@{host}:{port}[/dim]")
    finally:
        await db.disconnect()


@remote.command("list")
@click.option("-t", "--tag", help="Filter by tag")
@click.option(
    "-f",
    "--format",
    "fmt",
    type=click.Choice(["table", "json", "csv"]),
    default="table",
)
@click.option(
    "--view",
    type=click.Choice(["overview", "detail", "trace"]),
    default="overview",
    show_default=True,
    help="Output view profile (overview/detail/trace)",
)
@click.option("--limit", type=int, default=100, show_default=True)
@click.option("--offset", type=int, default=0, show_default=True)
@async_command
async def remote_list(
    tag: str | None, fmt: str, view: str, limit: int, offset: int
) -> None:
    """List all remote hosts."""
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.services import RemoteService

    db = await init_database()

    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)

        service = RemoteService(db, event_store, revision_store, metrics)
        hosts = await service.list_hosts(tag=tag)
        total_count = len(hosts)
        view_items = hosts[offset:] if limit <= 0 else hosts[offset : offset + limit]

        match fmt:
            case "json":
                items = []
                for host in view_items:
                    if view == "overview":
                        payload = {
                            "id": host.id,
                            "name": host.name,
                            "host": host.host,
                            "username": host.username,
                            "port": host.port,
                            "tags": list(host.tags),
                            "host_type": host.host_type.value,
                            "created_at": _to_iso(host.created_at),
                            "links": _normalize_command_links(
                                {"self": f"pms remote show {host.id}"}
                            ),
                        }
                    else:
                        payload = host.to_dict()
                        payload["links"] = _normalize_command_links(
                            {"self": f"pms remote show {host.id}"}
                        )
                    items.append(payload)

                base_cmd = "pms remote list --format json"
                if tag:
                    base_cmd += f" --tag {tag}"
                if view != "overview":
                    base_cmd += f" --view {view}"
                payload = {
                    "items": items,
                    "page": _page_payload(total_count, limit, offset),
                    "links": _normalize_command_links(
                        {
                            "self": f"{base_cmd} --limit {limit} --offset {offset}",
                            "next": (
                                f"{base_cmd} --limit {limit} --offset {offset + limit}"
                                if limit > 0 and offset + limit < total_count
                                else None
                            ),
                        }
                    ),
                }
                click.echo(json.dumps(payload, indent=2, default=str))
            case "csv":
                headers = ["id", "name", "host", "username", "port", "tags"]
                click.echo(_csv_row(headers))
                for h in view_items:
                    row = [
                        h.id,
                        h.name,
                        h.host,
                        h.username,
                        str(h.port),
                        ", ".join(h.tags) if h.tags else "",
                    ]
                    click.echo(_csv_row(row))
            case _:
                table = Table(title="Remote Hosts")
                table.add_column("Name", style="cyan")
                table.add_column("Host")
                table.add_column("User")
                table.add_column("Port", justify="right")
                table.add_column("Tags")

                for h in view_items:
                    table.add_row(
                        h.name,
                        h.host,
                        h.username,
                        str(h.port),
                        ", ".join(h.tags) if h.tags else "-",
                    )

                console.print(table)
                console.print(f"[dim]Total: {len(hosts)}[/dim]")
    finally:
        await db.disconnect()


@remote.command("show")
@click.argument("name")
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json", "csv"]),
    default="text",
    show_default=True,
)
@click.option(
    "--view",
    type=click.Choice(["overview", "detail", "trace"]),
    default="detail",
    show_default=True,
    help="Output view profile (overview/detail/trace)",
)
@async_command
async def remote_show(name: str, output_format: str, view: str) -> None:
    """Show remote host details."""
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.services import RemoteService

    db = await init_database()

    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)

        service = RemoteService(db, event_store, revision_store, metrics)
        host = await service.get_host(name)

        if host is None:
            if output_format == "text":
                console.print(f"[yellow]Remote host '{name}' not found[/yellow]")
                return
            _emit_cli_error(
                f"Remote host '{name}' not found",
                output_format="json" if output_format == "json" else "text",
            )

        if output_format == "json":
            if view == "overview":
                payload = {
                    "id": host.id,
                    "name": host.name,
                    "host": host.host,
                    "username": host.username,
                    "port": host.port,
                    "tags": list(host.tags),
                    "host_type": host.host_type.value,
                    "created_at": _to_iso(host.created_at),
                    "links": _normalize_command_links(
                        {"self": f"pms remote show {host.id}"}
                    ),
                }
            else:
                payload = {
                    "id": host.id,
                    "name": host.name,
                    "host": host.host,
                    "username": host.username,
                    "port": host.port,
                    "key_path": host.key_path,
                    "default_remote_path": host.default_remote_path,
                    "tags": list(host.tags),
                    "host_type": host.host_type.value,
                    "created_at": _to_iso(host.created_at),
                    "links": _normalize_command_links(
                        {"self": f"pms remote show {host.id}"}
                    ),
                }
            click.echo(json.dumps(payload, default=str))
            return

        if output_format == "csv":
            headers = [
                "id",
                "name",
                "host",
                "username",
                "port",
                "key_path",
                "default_remote_path",
                "tags",
                "host_type",
                "created_at",
            ]
            click.echo(_csv_row(headers))
            row = [
                host.id,
                host.name,
                host.host,
                host.username,
                str(host.port),
                host.key_path or "",
                host.default_remote_path or "",
                ", ".join(host.tags) if host.tags else "",
                host.host_type.value,
                str(host.created_at),
            ]
            click.echo(_csv_row(row))
            return

        from pms.utils.time import format_relative

        console.print(f"[bold cyan]{host.name}[/bold cyan]")
        console.print(f"[dim]ID: {host.id}[/dim]")
        console.print(f"Host: {host.host}")
        console.print(f"Username: {host.username}")
        console.print(f"Port: {host.port}")
        if host.key_path:
            console.print(f"Key: {host.key_path}")
        if host.default_remote_path:
            console.print(f"Default Path: {host.default_remote_path}")
        if host.tags:
            console.print(f"Tags: {', '.join(host.tags)}")
        console.print(f"Type: {host.host_type.value}")
        console.print(f"Created: {format_relative(host.created_at)}")
    finally:
        await db.disconnect()


@remote.command("delete")
@click.argument("name")
@click.option("-y", "--yes", is_flag=True, help="Skip confirmation")
@async_command
async def remote_delete(name: str, yes: bool) -> None:
    """Delete a remote host configuration."""
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.services import RemoteService

    if not yes and not click.confirm(f"Delete remote host '{name}'?"):
        console.print("[dim]Cancelled[/dim]")
        return

    db = await init_database()

    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)

        service = RemoteService(db, event_store, revision_store, metrics)
        deleted = await service.delete_host(name)

        if deleted:
            console.print(f"[green]Deleted remote host:[/green] {name}")
        else:
            console.print(f"[red]Remote host '{name}' not found[/red]")
    finally:
        await db.disconnect()


@remote.command("test")
@click.argument("name")
@async_command
async def remote_test(name: str) -> None:
    """Test connection to a remote host."""
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.services import RemoteService

