@test_retention_policy.command("list")
@click.option(
    "--scope-type",
    type=click.Choice(["project", "organization"]),
    help="Filter by scope type",
)
@click.option("--scope-id", help="Filter by scope ID")
@click.option("--include-archived", is_flag=True, help="Include archived policies")
@click.option("--limit", type=int, default=50, show_default=True)
@click.option("--offset", type=int, default=0, show_default=True)
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["table", "json", "csv"]),
    default="table",
    show_default=True,
)
@async_command
async def test_retention_policy_list(
    scope_type: str | None,
    scope_id: str | None,
    include_archived: bool,
    limit: int,
    offset: int,
    output_format: str,
) -> None:
    """List retention policies."""
    from pms.core.metrics import MetricsCollector
    from pms.db.connection import init_database
    from pms.repositories.test_run_retention_policy_repository import (
        TestRunRetentionPolicyRepository,
    )
    from pms.services.test_run_retention_policy_service import (
        TestRunRetentionPolicyService,
    )
    from pms.utils.time import format_relative

    db = await init_database()
    try:
        metrics = MetricsCollector(db)
        repo = TestRunRetentionPolicyRepository(db)
        service = TestRunRetentionPolicyService(repo, metrics)
        policies = await service.list_policies(
            scope_type=scope_type,
            scope_id=scope_id,
            limit=limit,
            offset=offset,
            include_archived=include_archived,
        )

        if output_format == "json":
            items = []
            for policy in policies.items:
                payload = policy.to_dict()
                payload["links"] = _normalize_command_links(
                    {"self": f"pms test retention-policy show {policy.id}"}
                )
                items.append(payload)
            base_cmd = "pms test retention-policy list --format json"
            if scope_type:
                base_cmd += f" --scope-type {scope_type}"
            if scope_id:
                base_cmd += f" --scope-id {scope_id}"
            if include_archived:
                base_cmd += " --include-archived"
            payload = {
                "items": items,
                "page": {
                    "total_count": policies.total_count,
                    "limit": policies.limit,
                    "offset": policies.offset,
                    "has_more": policies.has_more,
                    "next_offset": policies.offset + policies.limit
                    if policies.has_more
                    else None,
                },
                "links": _normalize_command_links(
                    {
                        "self": f"{base_cmd} --limit {limit} --offset {offset}",
                        "next": (
                            f"{base_cmd} --limit {limit} --offset {policies.offset + policies.limit}"
                            if policies.has_more
                            else None
                        ),
                    }
                ),
            }
            click.echo(json.dumps(payload, default=str))
            return

        if output_format == "csv":
            headers = [
                "id",
                "scope_type",
                "scope_id",
                "max_log_bytes",
                "max_artifact_bytes",
                "max_age_days",
                "notes",
                "updated_at",
                "archived_at",
            ]
            click.echo(_csv_row(headers))
            for policy in policies.items:
                row = [
                    policy.id,
                    policy.scope_type,
                    policy.scope_id,
                    str(policy.max_log_bytes),
                    str(policy.max_artifact_bytes),
                    str(policy.max_age_days),
                    policy.notes or "",
                    _to_iso(policy.updated_at) or "",
                    _to_iso(policy.archived_at) or "",
                ]
                click.echo(_csv_row(row))
            return

        table = Table(title="Retention Policies")
        table.add_column("ID", style="dim")
        table.add_column("Scope", style="cyan")
        table.add_column("Logs")
        table.add_column("Artifacts")
        table.add_column("Age")
        table.add_column("Updated")
        table.add_column("Archived")
        for policy in policies.items:
            table.add_row(
                policy.id[:8],
                f"{policy.scope_type}:{policy.scope_id}",
                _format_bytes(policy.max_log_bytes)
                if policy.max_log_bytes > 0
                else "disabled",
                _format_bytes(policy.max_artifact_bytes)
                if policy.max_artifact_bytes > 0
                else "disabled",
                f"{policy.max_age_days}d" if policy.max_age_days > 0 else "disabled",
                format_relative(policy.updated_at),
                "yes" if policy.archived_at else "-",
            )
        console.print(table)
        console.print(f"[dim]Total: {policies.total_count}[/dim]")
    finally:
        await db.disconnect()


