@cli.group()
def aws() -> None:
    """AWS test server management.

    Manage spot instances for testing, run edit-sync-test cycles,
    and stream remote logs.
    """
    pass


@aws.group()
def spot() -> None:
    """Find cost-effective spot instances."""
    pass


@spot.command("find")
@click.option("--vcpus", default=2, help="Minimum vCPUs")
@click.option("--memory", default=4.0, help="Minimum memory (GB)")
@click.option("--max-price", default="0.10", help="Maximum price per hour (USD)")
@click.option(
    "--region",
    "regions",
    multiple=True,
    default=["us-east-1", "us-west-2"],
    help="AWS regions to search",
)
@click.option(
    "--arch",
    type=click.Choice(["x86_64", "arm64"]),
    default="x86_64",
    help="CPU architecture",
)
@click.option("-n", "--limit", default=5, help="Number of results")
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["table", "json", "csv"]),
    default="table",
    show_default=True,
)
@async_command
async def spot_find(
    vcpus: int,
    memory: float,
    max_price: str,
    regions: tuple[str, ...],
    arch: str,
    limit: int,
    output_format: str,
) -> None:
    """Find cost-effective spot instances for testing.

    Examples:
        pms aws spot find
        pms aws spot find --vcpus 4 --memory 8 --max-price 0.05
        pms aws spot find --arch arm64 --region us-west-2
    """
    from decimal import Decimal

    try:
        import boto3
    except ImportError:
        _emit_missing_optional_dependency(
            "AWS support", "boto3", "pip install pms[aws]"
        )

    from pms.aws import SpotFinder
    from pms.aws.models import SpotQuery

    console.print(f"[dim]Searching for spot instances in {', '.join(regions)}...[/dim]")

    try:
        session = boto3.Session()
        finder = SpotFinder.create(session, regions)

        query = SpotQuery(
            min_vcpus=vcpus,
            min_memory_gb=memory,
            max_price_per_hour=Decimal(max_price),
            regions=regions,
            architecture=arch,
        )

        options = await finder.find_best_options(query, limit=limit)

        if not options:
            if output_format == "json":
                click.echo("[]")
                return
            if output_format == "csv":
                headers = [
                    "instance_type",
                    "availability_zone",
                    "current_price",
                    "vcpus",
                    "memory_gb",
                    "interruption_rate",
                    "score",
                ]
                click.echo(_csv_row(headers))
                return
            console.print("[yellow]No spot instances found matching criteria[/yellow]")
            return

        if output_format == "json":
            payload = [
                {
                    "instance_type": opt.instance_type,
                    "availability_zone": opt.availability_zone,
                    "current_price": monetary_string(opt.current_price),
                    "vcpus": opt.vcpus,
                    "memory_gb": opt.memory_gb,
                    "interruption_rate": opt.interruption_rate,
                    "score": opt.score,
                }
                for opt in options
            ]
            click.echo(json.dumps(payload))
            return

        if output_format == "csv":
            headers = [
                "instance_type",
                "availability_zone",
                "current_price",
                "vcpus",
                "memory_gb",
                "interruption_rate",
                "score",
            ]
            click.echo(_csv_row(headers))
            for opt in options:
                row = [
                    opt.instance_type,
                    opt.availability_zone,
                    monetary_string(opt.current_price) or "0",
                    str(opt.vcpus),
                    f"{opt.memory_gb}",
                    f"{opt.interruption_rate}",
                    f"{opt.score:.2f}",
                ]
                click.echo(_csv_row(row))
            return

        table = Table(title="Best Spot Options")
        table.add_column("Instance", style="cyan")
        table.add_column("Zone")
        table.add_column("Price/hr", justify="right")
        table.add_column("vCPUs", justify="right")
        table.add_column("Memory", justify="right")
        table.add_column("Interrupt", justify="right")
        table.add_column("Score", justify="right")

        for opt in options:
            table.add_row(
                opt.instance_type,
                opt.availability_zone,
                f"${opt.current_price:.4f}",
                str(opt.vcpus),
                f"{opt.memory_gb}GB",
                f"{opt.interruption_rate * 100:.0f}%",
                f"{opt.score:.2f}",
            )

        console.print(table)
        console.print(
            f"\n[dim]Tip: Launch with: pms aws server launch mytest --type {options[0].instance_type}[/dim]"
        )

    except Exception as e:
        console.print(f"[red]Error: {e}[/red]")


@aws.group()
def server() -> None:
    """Manage test servers."""
    pass


@server.command("launch")
@click.argument("name")
@click.option("--type", "instance_type", default="t3.medium", help="Instance type")
@click.option("--region", default="us-east-1", help="AWS region")
@click.option("--max-hours", default=4.0, help="Auto-terminate after N hours")
@click.option("--idle-minutes", default=30, help="Terminate after N minutes idle")
@click.option("--max-price", help="Maximum spot price (USD/hr)")
@click.option("--project", "project_id", help="Link to PMS project")
@click.option("--docker", is_flag=True, help="Install Docker")
@click.option("--no-wait", is_flag=True, help="Don't wait for server to be ready")
@async_command
async def server_launch(
    name: str,
    instance_type: str,
    region: str,
    max_hours: float,
    idle_minutes: int,
    max_price: str | None,
    project_id: str | None,
    docker: bool,
    no_wait: bool,
) -> None:
    """Launch a spot instance test server.

    Examples:
        pms aws server launch mytest
        pms aws server launch mytest --type t3.large --max-hours 2
        pms aws server launch mytest --docker --project "Web API"
    """
    from decimal import Decimal

    try:
        import boto3
    except ImportError:
        _emit_missing_optional_dependency(
            "AWS support", "boto3", "pip install pms[aws]"
        )

    from pms.aws import FleetManager, SpotServerConfig
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.services import RemoteService

    db = await init_database()

    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        remote_service = RemoteService(db, event_store, revision_store, metrics)

        session = boto3.Session()
        ec2_client = session.client("ec2", region_name=region)

        fleet = FleetManager(
            db=db,
            event_store=event_store,
            metrics=metrics,
            remote_service=remote_service,
            ec2_client=ec2_client,
            region=region,
        )

        config = SpotServerConfig(
            name=name,
            instance_type=instance_type,
            max_runtime_hours=max_hours,
            idle_terminate_minutes=idle_minutes,
            spot_max_price=Decimal(max_price) if max_price else None,
            project_id=project_id,
            install_docker=docker,
        )

        console.print(
            f"[dim]Launching spot instance {instance_type} in {region}...[/dim]"
        )

        server = await fleet.launch_server(config, wait_for_ready=not no_wait)

        console.print()
        console.print(f"[green]Test server launched![/green]")
        console.print(f"[bold cyan]{server.name}[/bold cyan]")
        console.print(f"[dim]ID: {server.id}[/dim]")
        console.print(f"Instance: {server.instance_id}")
        if server.public_ip:
            console.print(f"IP: {server.public_ip}")
            console.print(f"SSH: ssh ec2-user@{server.public_ip}")
        console.print(f"State: {server.state.value}")
        console.print(f"Price: ${server.hourly_price}/hr")
        console.print(f"Auto-terminate: {max_hours}h (or {idle_minutes}m idle)")

        await metrics.flush_best_effort(context="cli.aws_server_launch")
    except Exception as e:
        console.print(f"[red]Error: {e}[/red]")
    finally:
        await db.disconnect()


@server.command("list")
@click.option("--all", "show_all", is_flag=True, help="Show terminated servers too")
@click.option("--project", "project_id", help="Filter by project")
@click.option(
    "-f",
    "--format",
    "fmt",
    type=click.Choice(["table", "json", "csv"]),
    default="table",
)
@click.option(
    "--view",
    type=click.Choice(["overview", "detail", "trace"]),
    default="overview",
    show_default=True,
    help="Output view profile (overview/detail/trace)",
)
@click.option("--limit", type=int, default=100, show_default=True)
@click.option("--offset", type=int, default=0, show_default=True)
@async_command
async def server_list(
    show_all: bool,
    project_id: str | None,
    fmt: str,
    view: str,
    limit: int,
    offset: int,
) -> None:
    """List test servers."""
    try:
        import boto3
    except ImportError:
        _emit_missing_optional_dependency(
            "AWS support", "boto3", "pip install pms[aws]"
        )

    from pms.aws import FleetManager, ServerState
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.services import RemoteService

    db = await init_database()

    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        remote_service = RemoteService(db, event_store, revision_store, metrics)

        # We need to create a minimal fleet manager to list servers
        session = boto3.Session()
        ec2_client = session.client("ec2", region_name="us-east-1")

        fleet = FleetManager(
            db=db,
            event_store=event_store,
            metrics=metrics,
            remote_service=remote_service,
            ec2_client=ec2_client,
            region="us-east-1",
        )

        state_filter = None if show_all else None  # None excludes terminated by default
        servers = await fleet.list_servers(state=state_filter, project_id=project_id)
        total_count = len(servers)
        view_items = (
            servers[offset:] if limit <= 0 else servers[offset : offset + limit]
        )

        match fmt:
            case "json":
                items = []
                for server in view_items:
                    if view == "overview":
                        payload = {
                            "id": server.id,
                            "name": server.name,
                            "instance_id": server.instance_id,
                            "state": server.state.value,
                            "public_ip": server.public_ip,
                            "region": server.region,
                            "hourly_price": monetary_string(server.hourly_price),
                            "estimated_cost": monetary_string(server.estimated_cost),
                            "links": _normalize_command_links(
                                {"self": f"pms aws server show {server.id}"}
                            ),
                        }
                    else:
                        payload = {
                            "id": server.id,
                            "name": server.name,
                            "instance_id": server.instance_id,
                            "state": server.state.value,
                            "public_ip": server.public_ip,
                            "private_ip": server.private_ip,
                            "region": server.region,
                            "availability_zone": server.availability_zone,
                            "instance_type": server.config.instance_type,
                            "hourly_price": monetary_string(server.hourly_price),
                            "estimated_cost": monetary_string(server.estimated_cost),
                            "launched_at": server.launched_at,
                            "last_activity": server.last_activity,
                            "max_runtime_hours": server.config.max_runtime_hours,
                            "idle_terminate_minutes": server.config.idle_terminate_minutes,
                            "project_id": server.config.project_id,
                            "links": _normalize_command_links(
                                {"self": f"pms aws server show {server.id}"}
                            ),
                        }
                    items.append(payload)

                base_cmd = "pms aws server list --format json"
                if show_all:
                    base_cmd += " --all"
                if project_id:
                    base_cmd += f" --project {project_id}"
                if view != "overview":
                    base_cmd += f" --view {view}"
                payload = {
                    "items": items,
                    "page": _page_payload(total_count, limit, offset),
                    "links": _normalize_command_links(
                        {
                            "self": f"{base_cmd} --limit {limit} --offset {offset}",
                            "next": (
                                f"{base_cmd} --limit {limit} --offset {offset + limit}"
                                if limit > 0 and offset + limit < total_count
                                else None
                            ),
                        }
                    ),
                }
                click.echo(json.dumps(payload, indent=2))
            case "csv":
                headers = [
                    "id",
                    "name",
                    "instance_id",
                    "state",
                    "public_ip",
                    "region",
                    "hourly_price",
                    "estimated_cost",
                ]
                click.echo(_csv_row(headers))
                for s in view_items:
                    row = [
                        s.id,
                        s.name,
                        s.instance_id,
                        s.state.value,
                        s.public_ip or "",
                        s.region,
                        monetary_string(s.hourly_price) or "0",
                        monetary_string(s.estimated_cost) or "0",
                    ]
                    click.echo(_csv_row(row))
            case _:
                table = Table(title="Test Servers")
                table.add_column("Name", style="cyan")
                table.add_column("State")
                table.add_column("IP")
                table.add_column("Type")
                table.add_column("Price/hr", justify="right")
                table.add_column("Cost", justify="right")
                table.add_column("Launched")
                for s in view_items:
                    state_style = {
                        ServerState.PENDING: "yellow",
                        ServerState.RUNNING: "green",
                        ServerState.STOPPING: "yellow",
                        ServerState.TERMINATED: "dim",
                        ServerState.INTERRUPTED: "red",
                    }.get(s.state, "white")

                    table.add_row(
                        s.name,
                        f"[{state_style}]{s.state.value}[/{state_style}]",
                        s.public_ip or "-",
                        s.config.instance_type,
                        f"${s.hourly_price}",
                        f"${s.estimated_cost:.4f}",
                        str(s.launched_at)[:19],
                    )

                console.print(table)
                console.print(f"[dim]Total: {len(servers)}[/dim]")

    finally:
        await db.disconnect()


@server.command("show")
@click.argument("name_or_id")
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json", "csv"]),
    default="text",
    show_default=True,
)
@click.option(
    "--view",
    type=click.Choice(["overview", "detail", "trace"]),
    default="detail",
    show_default=True,
    help="Output view profile (overview/detail/trace)",
)
@async_command
async def server_show(name_or_id: str, output_format: str, view: str) -> None:
    """Show test server details."""
    try:
        import boto3
    except ImportError:
        _emit_missing_optional_dependency(
            "AWS support", "boto3", "pip install pms[aws]"
        )

    from pms.aws import FleetManager
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.services import RemoteService

    db = await init_database()

    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        remote_service = RemoteService(db, event_store, revision_store, metrics)

        session = boto3.Session()
        ec2_client = session.client("ec2", region_name="us-east-1")

        fleet = FleetManager(
            db=db,
            event_store=event_store,
            metrics=metrics,
            remote_service=remote_service,
            ec2_client=ec2_client,
            region="us-east-1",
        )

        server = await fleet.get_server(name_or_id)
        if server is None:
            # Try to find by name in list
            servers = await fleet.list_servers()
            server = next((s for s in servers if s.name == name_or_id), None)

        if server is None:
            console.print(f"[red]Server '{name_or_id}' not found[/red]")
            return

        # Refresh from AWS
        refreshed = await fleet.refresh_state(server.id)
        if refreshed:
            server = refreshed

        # Type narrowing - server cannot be None here
        assert server is not None

        if output_format == "json":
            if view == "overview":
                payload = {
                    "id": server.id,
                    "name": server.name,
                    "instance_id": server.instance_id,
                    "state": server.state.value,
                    "public_ip": server.public_ip,
                    "region": server.region,
                    "hourly_price": monetary_string(server.hourly_price),
                    "estimated_cost": monetary_string(server.estimated_cost),
                    "links": _normalize_command_links(
                        {"self": f"pms aws server show {server.id}"}
                    ),
                }
            else:
                payload = {
                    "id": server.id,
                    "name": server.name,
                    "instance_id": server.instance_id,
                    "state": server.state.value,
                    "region": server.region,
                    "availability_zone": server.availability_zone,
                    "public_ip": server.public_ip,
                    "private_ip": server.private_ip,
                    "instance_type": server.config.instance_type,
                    "hourly_price": monetary_string(server.hourly_price),
                    "estimated_cost": monetary_string(server.estimated_cost),
                    "launched_at": server.launched_at,
                    "last_activity": server.last_activity,
                    "max_runtime_hours": server.config.max_runtime_hours,
                    "idle_terminate_minutes": server.config.idle_terminate_minutes,
                    "project_id": server.config.project_id,
                    "links": _normalize_command_links(
                        {"self": f"pms aws server show {server.id}"}
                    ),
                }
            click.echo(json.dumps(payload, default=str))
            return

        if output_format == "csv":
            headers = [
                "id",
                "name",
                "instance_id",
                "state",
                "region",
                "availability_zone",
                "public_ip",
                "private_ip",
                "instance_type",
                "hourly_price",
                "estimated_cost",
                "launched_at",
                "last_activity",
                "max_runtime_hours",
                "idle_terminate_minutes",
            ]
            click.echo(_csv_row(headers))
            row = [
                server.id,
                server.name,
                server.instance_id,
                server.state.value,
                server.region,
                server.availability_zone,
                server.public_ip or "",
                server.private_ip or "",
                server.config.instance_type,
                monetary_string(server.hourly_price) or "0",
                monetary_string(server.estimated_cost) or "0",
                str(server.launched_at),
                str(server.last_activity) if server.last_activity else "",
                str(server.config.max_runtime_hours),
                str(server.config.idle_terminate_minutes),
            ]
            click.echo(_csv_row(row))
            return

        console.print(f"[bold cyan]{server.name}[/bold cyan]")
        console.print(f"[dim]ID: {server.id}[/dim]")
        console.print(f"Instance ID: {server.instance_id}")
        console.print(f"State: {server.state.value}")
        console.print(f"Region: {server.region} ({server.availability_zone})")
        if server.public_ip:
            console.print(f"Public IP: {server.public_ip}")
            console.print(f"SSH: ssh ec2-user@{server.public_ip}")
        if server.private_ip:
            console.print(f"Private IP: {server.private_ip}")
        console.print(f"Instance Type: {server.config.instance_type}")
        console.print(f"Hourly Price: ${server.hourly_price}")
        console.print(f"Estimated Cost: ${server.estimated_cost:.4f}")
        console.print(f"Launched: {server.launched_at}")
        if server.last_activity:
            console.print(f"Last Activity: {server.last_activity}")
        console.print(f"Max Runtime: {server.config.max_runtime_hours}h")
        console.print(f"Idle Timeout: {server.config.idle_terminate_minutes}m")

    finally:
        await db.disconnect()


@server.command("terminate")
@click.argument("name_or_id")
@click.option("-y", "--yes", is_flag=True, help="Skip confirmation")
@async_command
async def server_terminate(name_or_id: str, yes: bool) -> None:
    """Terminate a test server."""
    try:
        import boto3
    except ImportError:
        _emit_missing_optional_dependency(
            "AWS support", "boto3", "pip install pms[aws]"
        )

    if not yes and not click.confirm(f"Terminate server '{name_or_id}'?"):
        console.print("[dim]Cancelled[/dim]")
        return

    from pms.aws import FleetManager
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.services import RemoteService

    db = await init_database()

    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        remote_service = RemoteService(db, event_store, revision_store, metrics)

        session = boto3.Session()
        ec2_client = session.client("ec2", region_name="us-east-1")

        fleet = FleetManager(
            db=db,
            event_store=event_store,
            metrics=metrics,
            remote_service=remote_service,
            ec2_client=ec2_client,
            region="us-east-1",
        )

        # Find server
        server = await fleet.get_server(name_or_id)
        if server is None:
            servers = await fleet.list_servers()
            server = next((s for s in servers if s.name == name_or_id), None)

        if server is None:
            console.print(f"[red]Server '{name_or_id}' not found[/red]")
            return

        console.print(f"[dim]Terminating {server.name}...[/dim]")
        terminated = await fleet.terminate_server(server.id, reason="user_request")

        if terminated:
            console.print(f"[green]Terminated server:[/green] {server.name}")
            console.print(f"[dim]Total cost: ${server.estimated_cost:.4f}[/dim]")
        else:
            console.print(f"[red]Failed to terminate server[/red]")

        await metrics.flush_best_effort(context="cli.aws_server_terminate")
    finally:
        await db.disconnect()


