@test.command("run")
@click.argument("server_name")
@click.argument("project_path")
@click.option("-c", "--command", "test_command", default="pytest", help="Test command")
@click.option(
    "-s",
    "--setup",
    "setup_cmd",
    help="Setup command (e.g., pip install -r requirements.txt)",
)
@click.option(
    "-r", "--remote-path", default="/home/ec2-user/project", help="Remote path"
)
@click.option(
    "-w",
    "--workdir",
    "working_dir",
    help="Working directory relative to remote path",
)
@click.option("-t", "--timeout", default=600.0, help="Test timeout in seconds")
@click.option(
    "--env",
    "env_vars",
    multiple=True,
    help="Environment variable (KEY=VALUE, repeatable)",
)
@click.option(
    "--exclude",
    "exclude_patterns",
    multiple=True,
    help="Exclude pattern for sync (repeatable)",
)
@click.option(
    "--capture-log",
    "capture_logs",
    multiple=True,
    help="Capture remote log file contents (repeatable)",
)
@click.option(
    "--save-artifact",
    "save_artifacts",
    multiple=True,
    help="Download artifact paths after the run (repeatable)",
)
@click.option("--project-id", help="Link test run to a project")
@click.option("--plan-id", help="Link test run to a plan")
@click.option(
    "--task-id",
    "task_ids",
    multiple=True,
    help="Link test run to task IDs (repeatable)",
)
@click.option(
    "--on-success-state",
    help="Workflow state to transition tasks to on success",
)
@click.option(
    "--on-failure-state",
    help="Workflow state to transition tasks to on failure",
)
@click.option(
    "--transition-by",
    help="Workflow transition actor (default: aws_test_runner)",
)
@click.option(
    "--transition-reason",
    help="Workflow transition reason",
)
@click.option(
    "--no-stream",
    is_flag=True,
    help="Print AWS run output only after completion",
)
@async_command
async def test_run(
    server_name: str,
    project_path: str,
    test_command: str,
    setup_cmd: str | None,
    remote_path: str,
    working_dir: str | None,
    timeout: float,
    env_vars: tuple[str, ...],
    exclude_patterns: tuple[str, ...],
    capture_logs: tuple[str, ...],
    save_artifacts: tuple[str, ...],
    project_id: str | None,
    plan_id: str | None,
    task_ids: tuple[str, ...],
    on_success_state: str | None,
    on_failure_state: str | None,
    transition_by: str | None,
    transition_reason: str | None,
    no_stream: bool,
) -> None:
    """Sync project and run tests on a remote server.

    Examples:
        pms aws test run mytest ./myproject
        pms aws test run mytest ./src -c "pytest -v tests/"
        pms aws test run mytest . -s "pip install -r requirements.txt" -c "make test"
    """
    from pathlib import Path

    try:
        import boto3
    except ImportError:
        _emit_missing_optional_dependency(
            "AWS support", "boto3", "pip install pms[aws]"
        )

    from pms.aws import FleetManager, TestRunner
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.services import RemoteService
    from pms.services.test_execution_service import (
        TestExecutionConfig,
        TestExecutionService,
    )

    async def emit_output_line(source: str, line: str) -> None:
        if source == "stderr":
            console.print(f"[red]{line}[/red]")
            return
        console.print(line)

    env_pairs: list[tuple[str, str]] = []
    for item in env_vars:
        if "=" not in item:
            console.print(f"[red]Invalid --env entry: {item}[/red]")
            return
        key, value = item.split("=", 1)
        env_pairs.append((key, value))

    local_path = Path(project_path).resolve()
    if not local_path.exists():
        console.print(f"[red]Project path does not exist: {local_path}[/red]")
        return

    db = await init_database()

    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        remote_service = RemoteService(db, event_store, revision_store, metrics)

        session = boto3.Session()
        ec2_client = session.client("ec2", region_name="us-east-1")

        fleet = FleetManager(
            db=db,
            event_store=event_store,
            metrics=metrics,
            remote_service=remote_service,
            ec2_client=ec2_client,
            region="us-east-1",
        )

        runner = TestRunner(
            db=db,
            event_store=event_store,
            metrics=metrics,
            remote_service=remote_service,
            fleet_manager=fleet,
        )
        execution = TestExecutionService(remote_runner=runner)

        config = TestExecutionConfig(
            mode="aws",
            server_name=server_name,
            project_path=local_path,
            remote_path=remote_path,
            test_command=test_command,
            setup_command=setup_cmd,
            working_dir=working_dir,
            env_vars=tuple(env_pairs),
            timeout=timeout,
            exclude_patterns=tuple(exclude_patterns) if exclude_patterns else None,
            stream_output=not no_stream,
            capture_logs=tuple(capture_logs),
            save_artifacts=tuple(save_artifacts),
            project_id=project_id,
            plan_id=plan_id,
            task_ids=tuple(task_ids),
            transition_on_success=on_success_state,
            transition_on_failure=on_failure_state,
            transition_by=transition_by,
            transition_reason=transition_reason,
        )

        console.print(f"[dim]Syncing {local_path} to {server_name}...[/dim]")
        console.print(f"[dim]Running: {test_command}[/dim]")
        console.print()

        result = await execution.run(
            config,
            on_output_line=emit_output_line if not no_stream else None,
        )

        # Print output
        if result.stdout and no_stream:
            console.print(result.stdout)

        if result.stderr and no_stream:
            console.print(f"[red]{result.stderr}[/red]")

        console.print()
        style = "green" if result.success else "red"
        console.print(f"[{style}]{result.summary}[/{style}]")
        for line in _format_transition_summary(result):
            console.print(f"[dim]{line}[/dim]")
        console.print(f"[dim]Run ID: {result.run_id}[/dim]")

        await metrics.flush_best_effort(context="cli.aws_test_run")
    except Exception as e:
        console.print(f"[red]Error: {e}[/red]")
    finally:
        await db.disconnect()


@test.command("sync")
@click.argument("server_name")
@click.argument("project_path")
@click.option(
    "-r", "--remote-path", default="/home/ec2-user/project", help="Remote path"
)
@async_command
async def test_sync(server_name: str, project_path: str, remote_path: str) -> None:
    """Just sync project files without running tests.

    Examples:
        pms aws test sync mytest ./myproject
        pms aws test sync mytest ./src -r /home/ec2-user/app
    """
    from pathlib import Path

    try:
        import boto3
    except ImportError:
        _emit_missing_optional_dependency(
            "AWS support", "boto3", "pip install pms[aws]"
        )

    from pms.aws import FleetManager, TestRunner
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.services import RemoteService

    local_path = Path(project_path).resolve()
    if not local_path.exists():
        console.print(f"[red]Project path does not exist: {local_path}[/red]")
        return

    db = await init_database()

    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        remote_service = RemoteService(db, event_store, revision_store, metrics)

        session = boto3.Session()
        ec2_client = session.client("ec2", region_name="us-east-1")

        fleet = FleetManager(
            db=db,
            event_store=event_store,
            metrics=metrics,
            remote_service=remote_service,
            ec2_client=ec2_client,
            region="us-east-1",
        )

        runner = TestRunner(
            db=db,
            event_store=event_store,
            metrics=metrics,
            remote_service=remote_service,
            fleet_manager=fleet,
        )

        # Find server by name
        servers = await fleet.list_servers()
        server = next((s for s in servers if s.name == server_name), None)
        if server is None:
            server = await fleet.get_server(server_name)

        if server is None:
            console.print(f"[red]Server '{server_name}' not found[/red]")
            return

        console.print(
            f"[dim]Syncing {local_path} to {server_name}:{remote_path}...[/dim]"
        )

        result = await runner.sync_only(
            server_id=server.id,
            project_path=local_path,
            remote_path=remote_path,
        )

        if result.success:
            console.print(f"[green]Sync completed![/green]")
            console.print(f"Files transferred: {result.files_transferred}")
        else:
            console.print(f"[red]Sync failed[/red]")
            if result.stderr:
                console.print(f"[red]{result.stderr}[/red]")

        console.print(f"[dim]Duration: {result.duration_seconds:.2f}s[/dim]")

        await metrics.flush_best_effort(context="cli.aws_test_sync")
    except Exception as e:
        console.print(f"[red]Error: {e}[/red]")
    finally:
        await db.disconnect()


@test.command("exec")
@click.argument("server_name")
@click.argument("command")
@click.option("-w", "--workdir", help="Working directory")
@click.option("-t", "--timeout", default=300.0, help="Command timeout")
@async_command
async def test_exec(
    server_name: str,
    command: str,
    workdir: str | None,
    timeout: float,
) -> None:
    """Run a command on a test server without syncing.

    Examples:
        pms aws test exec mytest "ls -la"
        pms aws test exec mytest "pytest -v" --workdir /home/ec2-user/project
    """
    try:
        import boto3
    except ImportError:
        _emit_missing_optional_dependency(
            "AWS support", "boto3", "pip install pms[aws]"
        )

    from pms.aws import FleetManager, TestRunner
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.services import RemoteService

    db = await init_database()

    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        remote_service = RemoteService(db, event_store, revision_store, metrics)

        session = boto3.Session()
        ec2_client = session.client("ec2", region_name="us-east-1")

        fleet = FleetManager(
            db=db,
            event_store=event_store,
            metrics=metrics,
            remote_service=remote_service,
            ec2_client=ec2_client,
            region="us-east-1",
        )

        runner = TestRunner(
            db=db,
            event_store=event_store,
            metrics=metrics,
            remote_service=remote_service,
            fleet_manager=fleet,
        )

        # Find server by name
        servers = await fleet.list_servers()
        server = next((s for s in servers if s.name == server_name), None)
        if server is None:
            server = await fleet.get_server(server_name)

        if server is None:
            console.print(f"[red]Server '{server_name}' not found[/red]")
            return

        console.print(f"[dim]Executing on {server_name}: {command}[/dim]")
        console.print()

        result = await runner.run_only(
            server_id=server.id,
            command=command,
            working_dir=workdir,
            timeout=timeout,
        )

        if result.stdout:
            console.print(result.stdout)

        if result.stderr:
            console.print(f"[red]{result.stderr}[/red]")

        console.print()
        style = "green" if result.success else "red"
        console.print(f"[{style}]Exit code: {result.exit_code}[/{style}]")
        console.print(f"[dim]Duration: {result.duration_seconds:.2f}s[/dim]")

        await metrics.flush_best_effort(context="cli.aws_test_exec")
    except Exception as e:
        console.print(f"[red]Error: {e}[/red]")
    finally:
        await db.disconnect()


@aws.command("logs")
@click.argument("server_name")
@click.argument("log_paths", nargs=-1)
@click.option("-n", "--lines", default=100, help="Number of lines to show")
@click.option("-f", "--follow", is_flag=True, help="Follow logs in real-time")
@async_command
async def aws_logs(
    server_name: str,
    log_paths: tuple[str, ...],
    lines: int,
    follow: bool,
) -> None:
    """Tail remote log files.

    Examples:
        pms aws logs mytest /var/log/app.log
        pms aws logs mytest /var/log/app.log /var/log/error.log -f
    """
    if not log_paths:
        _emit_cli_error("Please specify at least one log path", output_format="text")

    try:
        import boto3
    except ImportError:
        _emit_missing_optional_dependency(
            "AWS support", "boto3", "pip install pms[aws]"
        )

    from pms.aws import FleetManager, TestRunner
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
    from pms.db.connection import init_database
    from pms.services import RemoteService

    db = await init_database()

    try:
        event_store = EventStore(db)
        revision_store = RevisionStore(db)
        metrics = MetricsCollector(db)
        remote_service = RemoteService(db, event_store, revision_store, metrics)

        session = boto3.Session()
        ec2_client = session.client("ec2", region_name="us-east-1")

        fleet = FleetManager(
            db=db,
            event_store=event_store,
            metrics=metrics,
            remote_service=remote_service,
            ec2_client=ec2_client,
            region="us-east-1",
        )

        runner = TestRunner(
            db=db,
            event_store=event_store,
            metrics=metrics,
            remote_service=remote_service,
            fleet_manager=fleet,
        )

        # Find server by name
        servers = await fleet.list_servers()
        server = next((s for s in servers if s.name == server_name), None)
        if server is None:
            server = await fleet.get_server(server_name)

        if server is None:
            console.print(f"[red]Server '{server_name}' not found[/red]")
            return

        console.print(f"[dim]Tailing logs from {server_name}...[/dim]")
        console.print()

        async for log_path, line in runner.tail_logs(
            server_id=server.id,
            log_paths=list(log_paths),
            follow=follow,
            lines=lines,
        ):
            if len(log_paths) > 1 and log_path:
                console.print(f"[dim]{log_path}:[/dim] {line}")
            else:
                console.print(line)

    except KeyboardInterrupt:
        console.print("\n[dim]Stopped[/dim]")
    except Exception as e:
        console.print(f"[red]Error: {e}[/red]")
    finally:
        await db.disconnect()


