@cli.group()
def generate() -> None:
    """Generate new tools and code (meta-programming)."""
    pass


@generate.command("tool")
@click.argument("description")
@click.option("-n", "--name", help="Override tool name")
@click.option(
    "-c",
    "--category",
    type=click.Choice(["project", "task", "remote", "aws_spot", "aws_test"]),
    help="Tool category",
)
@click.option("-o", "--output", is_flag=True, help="Save generated code to files")
@async_command
async def generate_tool(
    description: str,
    name: str | None,
    category: str | None,
    output: bool,
) -> None:
    """Generate a new PMS tool from natural language description.

    Examples:
        pms generate tool "List all GitHub PRs for a repo"
        pms generate tool "Sync Linear issues to tasks" --category task
        pms generate tool "Send Slack notification" --name notify_slack --output
    """
    from pms.agents.tool_generator import GenerationStatus, ToolGenerator

    generator = ToolGenerator()

    console.print(f"[dim]Analyzing: {description}[/dim]")

    # Analyze description
    spec = await generator.analyze_description(description)

    # Override if provided
    if name:
        spec.name = name
    if category:
        from pms.tools.registry import ToolCategory

        spec.category = ToolCategory(category)

    # Show spec
    console.print()
    console.print("[bold]Tool Specification:[/bold]")
    console.print(f"  Name: [cyan]{spec.name}[/cyan]")
    console.print(f"  Category: [yellow]{spec.category.value}[/yellow]")
    console.print(f"  Service: {spec.service_dependency or 'none'}")
    console.print("  Parameters:")
    for pname, pinfo in spec.parameters.items():
        req = "[red]*[/red]" if pinfo["required"] else ""
        console.print(f"    - {pname}: {pinfo['type'].__name__}{req}")
    console.print(f"  Keywords: {', '.join(spec.search_keywords)}")

    # Generate code
    console.print()
    console.print("[dim]Generating code...[/dim]")

    generated = await generator.generate_tool(spec)

    match generated.status:
        case GenerationStatus.FAILED:
            detail = "Generation failed"
            if generated.errors:
                detail += ": " + "; ".join(generated.errors)
            _emit_cli_error(detail, output_format="text")
        case _:
            pass

    # Show generated code
    console.print()
    console.print("[bold green]Generated Tool Code:[/bold green]")
    console.print("```python")
    console.print(generated.tool_code)
    console.print("```")

    console.print()
    console.print("[bold blue]Generated Test Code:[/bold blue]")
    console.print("```python")
    console.print(generated.test_code)
    console.print("```")

    console.print()
    console.print("[bold yellow]Registry Entry:[/bold yellow]")
    console.print("```python")
    console.print(generated.registry_entry)
    console.print("```")

    # Save if requested
    if output:
        module_name = spec.service_dependency or spec.category.value.split(".")[0]
        path = await generator.save_generated_tool(generated, module_name)
        console.print()
        console.print(f"[green]Saved to: {path}[/green]")


@generate.command("spec")
@click.argument("description")
@async_command
async def generate_spec(description: str) -> None:
    """Analyze a description and show the tool specification.

    This is a preview command - shows what would be generated without creating code.

    Examples:
        pms generate spec "Import Notion pages as tasks"
    """
    from pms.agents.tool_generator import ToolGenerator

    generator = ToolGenerator()

    spec = await generator.analyze_description(description)

    console.print("[bold]Tool Specification:[/bold]")
    console.print(f"  Name: [cyan]{spec.name}[/cyan]")
    console.print(f"  Description: {spec.description}")
    console.print(f"  Category: [yellow]{spec.category.value}[/yellow]")
    console.print(f"  Service Dependency: {spec.service_dependency or 'none'}")
    console.print(f"  Is Core: {spec.is_core}")
    console.print()
    console.print("  [bold]Parameters:[/bold]")
    for pname, pinfo in spec.parameters.items():
        req = "[red]required[/red]" if pinfo["required"] else "[dim]optional[/dim]"
        console.print(f"    {pname}: {pinfo['type'].__name__} ({req})")
        console.print(f"      [dim]{pinfo['description']}[/dim]")
    console.print()
    console.print("  [bold]Search Keywords:[/bold]")
    console.print(f"    {', '.join(spec.search_keywords)}")


@generate.command("module")
@click.argument("module_name")
@click.argument("tools", nargs=-1)
@click.option("--preview", is_flag=True, help="Preview without creating files")
@async_command
async def generate_module(
    module_name: str,
    tools: tuple[str, ...],
    preview: bool,
) -> None:
    """Generate a complete new tool module.

    Examples:
        pms generate module github "List repos" "Create issue" "Sync PRs"
        pms generate module slack "Send message" "List channels" --preview
    """
    if not tools:
        _emit_cli_error(
            "Please provide at least one tool description", output_format="text"
        )

    from pms.agents.tool_generator import ToolGenerator

    generator = ToolGenerator()

    console.print(f"[bold]Generating module: {module_name}[/bold]")
    console.print(f"Tools: {len(tools)}")
    console.print()

    generated_tools = []
    for desc in tools:
        console.print(f"[dim]Analyzing: {desc}[/dim]")
        spec = await generator.analyze_description(desc)

        # Override service to match module
        spec.service_dependency = module_name

        generated = await generator.generate_tool(spec)
        generated_tools.append(generated)

        match generated.status:
            case GenerationStatus.COMPLETED:
                console.print(f"  [green]✓[/green] {spec.name}")
            case _:
                console.print(f"  [red]✗[/red] {spec.name}: {generated.errors}")

    console.print()

    if preview:
        console.print("[yellow]Preview mode - no files created[/yellow]")
        console.print()
        for gen in generated_tools:
            match gen.status:
                case GenerationStatus.COMPLETED:
                    console.print(f"[bold]{gen.spec.name}[/bold]")
                    console.print("```python")
                    console.print(gen.tool_code)
                    console.print("```")
                    console.print()
                case _:
                    continue
    else:
        # Save all tools
        for gen in generated_tools:
            match gen.status:
                case GenerationStatus.COMPLETED:
                    path = await generator.save_generated_tool(gen, module_name)
                case _:
                    continue

        console.print(
            f"[green]Created module: pms/tools/{module_name}_tools.py[/green]"
        )
        console.print()
        console.print("[dim]Next steps:[/dim]")
        console.print(
            f"  1. Implement the service: pms/services/{module_name}_service.py"
        )
        console.print(f"  2. Add to server.py: import and register tools")
        console.print(f"  3. Add to registry.py: add ToolMetadata entries")
        console.print(f"  4. Run tests: pytest tests/unit/test_{module_name}_tools.py")


