@cli.group()
def capabilities() -> None:
    """Discover system capabilities and documentation.

    Self-documentation commands for exploring what PMS can do,
    available namespaces, tools, patterns, and health status.
    """
    pass


@capabilities.command("info")
@click.option(
    "-f",
    "--format",
    "fmt",
    type=click.Choice(["table", "json", "csv"]),
    default="table",
)
def capabilities_info(fmt: str) -> None:
    """Show basic system information.

    Examples:
        pms capabilities info
        pms capabilities info --format json
    """
    from pms.core import get_system_info

    info = get_system_info()
    purpose = "Capability inventory entry point for understanding what PMS can do, where to inspect details, and what to generate next."
    next_steps = [
        "pms capabilities list --format json",
        "pms capabilities docs",
        "pms capabilities schema",
        "pms start --format json",
    ]

    match fmt:
        case "json":
            payload = _payload_with_normalized_next_steps(
                {
                    **info,
                    "purpose": purpose,
                    "links": _normalize_command_links(
                        {
                            "self": "capabilities info --format json",
                            "list": "capabilities list --format json",
                            "docs": "capabilities docs",
                            "schema": "capabilities schema",
                            "guide": "start --format json",
                        }
                    ),
                },
                *next_steps,
            )
            click.echo(json.dumps(payload, indent=2, default=str))
        case "csv":
            headers = ["key", "value"]
            click.echo(_csv_row(headers))
            for key, value in info.items():
                if isinstance(value, dict):
                    click.echo(_csv_row([key, json.dumps(value)]))
                else:
                    click.echo(_csv_row([key, str(value)]))
        case _:
            console.print("[bold]PMS - Project Management System[/bold]")
            console.print()
            console.print(f"Purpose: {purpose}")
            console.print()
            console.print(f"Version: [cyan]{info['version']}[/cyan]")
            console.print(
                f"Total Capabilities: [green]{info['total_capabilities']}[/green]"
            )
            console.print()
            console.print("[bold]Capability Summary:[/bold]")
            for cap_type, count in info["capabilities"].items():
                console.print(f"  {cap_type}: {count}")
            _print_next_steps(*next_steps)


@capabilities.command("list")
@click.option(
    "-t",
    "--type",
    "cap_type",
    type=click.Choice(
        [
            "namespaces",
            "tools",
            "patterns",
            "event_types",
            "reference_types",
            "knowledge_types",
            "feedback_categories",
        ]
    ),
    help="Filter by capability type",
)
@click.option(
    "-f",
    "--format",
    "fmt",
    type=click.Choice(["table", "json", "csv"]),
    default="table",
)
@click.option(
    "--view",
    type=click.Choice(["overview", "detail", "trace"]),
    default="overview",
    show_default=True,
    help="Output view profile (overview/detail/trace)",
)
@click.option("--limit", type=int, default=100, show_default=True)
@click.option("--offset", type=int, default=0, show_default=True)
def capabilities_list(
    cap_type: str | None,
    fmt: str,
    view: str,
    limit: int,
    offset: int,
) -> None:
    """List all system capabilities.

    Examples:
        pms capabilities list
        pms capabilities list --type tools
        pms capabilities list --type namespaces --format json
    """
    from pms.core import get_capabilities

    caps = get_capabilities()

    if cap_type:
        caps = {cap_type: caps.get(cap_type, [])}

    records: list[dict[str, Any]] = []
    for category, items in caps.items():
        for item in items:
            if isinstance(item, dict):
                name = str(item.get("name", item.get("value", "")))
                value = str(item.get("value", "")) if item.get("value") else ""
                description = str(item.get("description", ""))
                metadata = {
                    k: v
                    for k, v in item.items()
                    if k not in {"name", "value", "description"}
                }
                raw = item
            else:
                name = str(item)
                value = ""
                description = ""
                metadata = {}
                raw = item
            records.append(
                {
                    "category": category,
                    "name": name,
                    "value": value,
                    "description": description,
                    "metadata": metadata,
                    "raw": raw,
                }
            )

    total_count = len(records)
    view_items = records[offset:] if limit <= 0 else records[offset : offset + limit]

    match fmt:
        case "json":
            items = []
            for record in view_items:
                if view == "overview":
                    payload = {
                        "category": record["category"],
                        "name": record["name"],
                        "description": record["description"],
                    }
                elif view == "trace":
                    payload = {
                        "category": record["category"],
                        "name": record["name"],
                        "value": record["value"],
                        "description": record["description"],
                        "metadata": record["metadata"],
                        "raw": record["raw"],
                    }
                else:
                    payload = {
                        "category": record["category"],
                        "name": record["name"],
                        "value": record["value"],
                        "description": record["description"],
                        "metadata": record["metadata"],
                    }
                items.append(payload)

            base_cmd = "pms capabilities list --format json"
            if cap_type:
                base_cmd += f" --type {cap_type}"
            if view != "overview":
                base_cmd += f" --view {view}"
            payload = {
                "items": items,
                "page": _page_payload(total_count, limit, offset),
                "links": _normalize_command_links(
                    {
                        "self": f"{base_cmd} --limit {limit} --offset {offset}",
                        "next": (
                            f"{base_cmd} --limit {limit} --offset {offset + limit}"
                            if limit > 0 and offset + limit < total_count
                            else None
                        ),
                    }
                ),
            }
            click.echo(json.dumps(payload, indent=2, default=str))
        case "csv":
            headers = ["category", "name", "value", "description", "metadata"]
            click.echo(_csv_row(headers))
            for record in view_items:
                row = [
                    record["category"],
                    record["name"],
                    record["value"],
                    record["description"],
                    json.dumps(record["metadata"]),
                ]
                click.echo(_csv_row(row))
        case _:
            if not view_items:
                console.print("[dim]No capabilities found[/dim]")
                return

            table = Table(title="Capabilities")
            table.add_column("Category", style="cyan")
            table.add_column("Name")
            table.add_column("Description")
            if view != "overview":
                table.add_column("Value")

            for record in view_items:
                row = [
                    record["category"],
                    record["name"],
                    (record["description"] or "")[:50],
                ]
                if view != "overview":
                    row.append(str(record["value"])[:30])
                table.add_row(*row)

            console.print(table)
            console.print(f"[dim]Total: {total_count}[/dim]")


@capabilities.command("schema")
@click.option("-o", "--output", type=click.Path(), help="Save schema to file")
def capabilities_schema(output: str | None) -> None:
    """Show full JSON schema for all capabilities.

    Examples:
        pms capabilities schema
        pms capabilities schema --output schema.json
    """
    import json

    from pms.core import get_system_schema

    schema = get_system_schema()

    json_str = json.dumps(schema, indent=2, default=str)

    if output:
        from pathlib import Path

        Path(output).write_text(json_str)
        console.print(f"[green]Schema saved to: {output}[/green]")
    else:
        # Use print() to avoid Rich console text wrapping which breaks JSON
        print(json_str)


@capabilities.command("docs")
@click.option(
    "-f",
    "--format",
    "fmt",
    type=click.Choice(["markdown", "text"]),
    default="markdown",
)
@click.option("-o", "--output", type=click.Path(), help="Save documentation to file")
def capabilities_docs(fmt: str, output: str | None) -> None:
    """Generate full system documentation.

    Examples:
        pms capabilities docs
        pms capabilities docs --format text
        pms capabilities docs --output CAPABILITIES.md
    """
    from pms.core import get_full_documentation

    docs = get_full_documentation(format=fmt)

    if output:
        from pathlib import Path

        if fmt == "markdown":
            from pms.utils.markdown_formatting import format_markdown_with_prettier

            docs = format_markdown_with_prettier(docs, filepath=output)

        Path(output).write_text(docs)
        console.print(f"[green]Documentation saved to: {output}[/green]")
    else:
        console.print(docs)


@capabilities.command("health")
@click.option(
    "-f",
    "--format",
    "fmt",
    type=click.Choice(["table", "json", "csv"]),
    default="table",
)
def capabilities_health(fmt: str) -> None:
    """Check system health status.

    Examples:
        pms capabilities health
        pms capabilities health --format json
    """
    from pms.core import get_health_status

    status = get_health_status()

    match fmt:
        case "json":
            print(json.dumps(status, indent=2, default=str))
        case "csv":
            headers = ["key", "value"]
            click.echo(_csv_row(headers))
            for key, value in status.items():
                if isinstance(value, dict):
                    click.echo(_csv_row([key, json.dumps(value)]))
                else:
                    click.echo(_csv_row([key, str(value)]))
        case _:
            overall = (
                "[green]Healthy[/green]"
                if status["healthy"]
                else "[red]Unhealthy[/red]"
            )
            console.print(f"[bold]System Health:[/bold] {overall}")
            console.print()

            if status.get("components"):
                table = Table(title="Components")
                table.add_column("Component", style="cyan")
                table.add_column("Status")
                table.add_column("Details")

                for comp_name, comp_info in status["components"].items():
                    if isinstance(comp_info, dict):
                        healthy = comp_info.get("healthy", False)
                        status_str = "[green]✓[/green]" if healthy else "[red]✗[/red]"
                        # Get additional details
                        details = []
                        for k, v in comp_info.items():
                            if k not in ("healthy", "error"):
                                details.append(f"{k}: {v}")
                        if comp_info.get("error"):
                            details.append(f"[red]{comp_info['error']}[/red]")
                        table.add_row(comp_name, status_str, ", ".join(details)[:50])
                    else:
                        table.add_row(comp_name, str(comp_info), "")

                console.print(table)


