@cli.group()
def namespace() -> None:
    """Manage entity namespaces (pluggable type system).

    Namespaces define the types of entities in PMS. Each namespace
    has a prefix (e.g., 'proj_', 'task_') used in ID generation.
    """
    pass


@namespace.command("list")
@click.option("--builtin", is_flag=True, help="Show only built-in namespaces")
@click.option("--custom", is_flag=True, help="Show only custom namespaces")
@click.option(
    "-f",
    "--format",
    "fmt",
    type=click.Choice(["table", "json", "csv"]),
    default="table",
)
@click.option(
    "--view",
    type=click.Choice(["overview", "detail", "trace"]),
    default="overview",
    show_default=True,
    help="Output view profile (overview/detail/trace)",
)
@click.option("--limit", type=int, default=100, show_default=True)
@click.option("--offset", type=int, default=0, show_default=True)
def namespace_list(
    builtin: bool,
    custom: bool,
    fmt: str,
    view: str,
    limit: int,
    offset: int,
) -> None:
    """List all registered namespaces.

    Examples:
        pms namespace list
        pms namespace list --builtin
        pms namespace list --custom --format json
    """
    from pms.core import list_namespaces
    from pms.core.id_contract import namespace_id_contract

    namespaces = list_namespaces()

    # Filter if requested
    if builtin:
        namespaces = [ns for ns in namespaces if ns.is_builtin]
    elif custom:
        namespaces = [ns for ns in namespaces if not ns.is_builtin]
    total_count = len(namespaces)
    if limit <= 0:
        view_items = namespaces[offset:]
    else:
        view_items = namespaces[offset : offset + limit]

    match fmt:
        case "json":
            items = []
            for ns in view_items:
                contract = namespace_id_contract(ns.prefix, ns.name)
                if view == "overview":
                    payload = {
                        "prefix": ns.prefix,
                        "name": ns.name,
                        "description": ns.description,
                        "is_builtin": ns.is_builtin,
                        **contract,
                        "links": _normalize_command_links(
                            {"self": f"namespace show {ns.prefix}"}
                        ),
                    }
                elif view == "trace":
                    payload = {
                        "prefix": ns.prefix,
                        "name": ns.name,
                        "description": ns.description,
                        "module": ns.module,
                        "is_builtin": ns.is_builtin,
                        **contract,
                        "schema": ns.schema,
                        "links": _normalize_command_links(
                            {"self": f"namespace show {ns.prefix}"}
                        ),
                    }
                else:
                    payload = {
                        "prefix": ns.prefix,
                        "name": ns.name,
                        "description": ns.description,
                        "module": ns.module,
                        "is_builtin": ns.is_builtin,
                        **contract,
                        "links": _normalize_command_links(
                            {"self": f"namespace show {ns.prefix}"}
                        ),
                    }
                items.append(payload)

            base_cmd = "pms namespace list --format json"
            if builtin:
                base_cmd += " --builtin"
            elif custom:
                base_cmd += " --custom"
            if view != "overview":
                base_cmd += f" --view {view}"
            payload = {
                "items": items,
                "page": _page_payload(total_count, limit, offset),
                "links": _normalize_command_links(
                    {
                        "self": f"{base_cmd} --limit {limit} --offset {offset}",
                        "next": (
                            f"{base_cmd} --limit {limit} --offset {offset + limit}"
                            if limit > 0 and offset + limit < total_count
                            else None
                        ),
                    }
                ),
            }
            click.echo(json.dumps(payload, indent=2))
        case "csv":
            headers = [
                "prefix",
                "name",
                "description",
                "module",
                "is_builtin",
                "namespace_generated_id_format",
                "namespace_generated_id_kind",
                "runtime_row_id_contract_scope",
                "runtime_row_id_style",
            ]
            click.echo(_csv_row(headers))
            for ns in view_items:
                contract = namespace_id_contract(ns.prefix, ns.name)
                row = [
                    ns.prefix,
                    ns.name,
                    ns.description or "",
                    ns.module,
                    "true" if ns.is_builtin else "false",
                    contract["namespace_generated_id_format"],
                    contract["namespace_generated_id_kind"],
                    contract["runtime_row_id_contract_scope"],
                    contract["runtime_row_id_style"] or "",
                ]
                click.echo(_csv_row(row))
        case _:
            table = Table(title="Namespaces")
            table.add_column("Prefix", style="cyan")
            table.add_column("Name")
            table.add_column("Description")
            table.add_column("Module", style="dim")
            table.add_column("Built-in")

            for ns in view_items:
                table.add_row(
                    ns.prefix,
                    ns.name,
                    (ns.description or "")[:40],
                    ns.module,
                    "[green]✓[/green]" if ns.is_builtin else "",
                )

            console.print(table)
            console.print(f"[dim]Total: {total_count}[/dim]")


@namespace.command("show")
@click.argument("prefix")
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json", "csv"]),
    default="text",
    show_default=True,
)
@click.option(
    "--view",
    type=click.Choice(["overview", "detail", "trace"]),
    default="detail",
    show_default=True,
    help="Output view profile (overview/detail/trace)",
)
def namespace_show(prefix: str, output_format: str, view: str) -> None:
    """Show details for a specific namespace.

    Examples:
        pms namespace show proj
        pms namespace show task
    """
    from pms.core import get_namespace
    from pms.core.id_contract import namespace_id_contract

    ns = get_namespace(prefix)

    if ns is None:
        console.print(f"[red]Namespace '{prefix}' not found[/red]")
        return

    contract = namespace_id_contract(ns.prefix, ns.name)

    if output_format == "json":
        if view == "overview":
            payload = {
                "prefix": ns.prefix,
                "name": ns.name,
                "description": ns.description,
                "is_builtin": ns.is_builtin,
                **contract,
                "links": _normalize_command_links(
                    {"self": f"namespace show {ns.prefix}"}
                ),
            }
        elif view == "trace":
            payload = {
                "prefix": ns.prefix,
                "name": ns.name,
                "description": ns.description,
                "module": ns.module,
                "is_builtin": ns.is_builtin,
                **contract,
                "schema": ns.schema,
                "example_id": ns.generate_id(),
                "links": _normalize_command_links(
                    {"self": f"namespace show {ns.prefix}"}
                ),
            }
        else:
            payload = {
                "prefix": ns.prefix,
                "name": ns.name,
                "description": ns.description,
                "module": ns.module,
                "is_builtin": ns.is_builtin,
                **contract,
                "example_id": ns.generate_id(),
                "links": _normalize_command_links(
                    {"self": f"namespace show {ns.prefix}"}
                ),
            }
        click.echo(json.dumps(payload, default=str))
        return

    if output_format == "csv":
        headers = [
            "prefix",
            "name",
            "description",
            "module",
            "is_builtin",
            "namespace_generated_id_format",
            "namespace_generated_id_kind",
            "runtime_row_id_contract_scope",
            "runtime_row_id_style",
            "example_id",
            "schema",
        ]
        click.echo(_csv_row(headers))
        row = [
            ns.prefix,
            ns.name,
            ns.description or "",
            ns.module,
            "true" if ns.is_builtin else "false",
            contract["namespace_generated_id_format"],
            contract["namespace_generated_id_kind"],
            contract["runtime_row_id_contract_scope"],
            contract["runtime_row_id_style"] or "",
            ns.generate_id(),
            json.dumps(ns.schema or {}),
        ]
        click.echo(_csv_row(row))
        return

    console.print(f"[bold cyan]{ns.name}[/bold cyan]")
    console.print(f"[dim]Prefix: {ns.prefix}[/dim]")
    console.print(f"Description: {ns.description or 'N/A'}")
    console.print(f"Module: {ns.module}")
    console.print(f"Built-in: {'Yes' if ns.is_builtin else 'No'}")

    if view != "overview" and ns.schema:
        console.print()
        console.print("[bold]Schema:[/bold]")
        console.print(json.dumps(ns.schema, indent=2))

    # Show namespace-generated ID metadata and any public runtime row-ID contract.
    if view != "overview":
        console.print()
        console.print("[bold]ID Contract:[/bold]")
        console.print(
            f"  Namespace-generated ID format: {contract['namespace_generated_id_format']}"
        )
        console.print(
            "  Runtime row-ID contract scope: "
            f"{contract['runtime_row_id_contract_scope']}"
        )
        runtime_style = contract["runtime_row_id_style"] or "not applicable"
        console.print(f"  Runtime row-ID style: {runtime_style}")
        console.print()
        console.print("[bold]Example Namespace ID:[/bold]")
        example_id = ns.generate_id()
        console.print(f"  {example_id}")


@namespace.command("register")
@click.argument("prefix")
@click.argument("name")
@click.option("-d", "--description", help="Namespace description")
@click.option("-m", "--module", default="custom", help="Module name")
@click.option(
    "-s",
    "--schema",
    "schema_file",
    type=click.Path(exists=True),
    help="JSON schema file",
)
def namespace_register(
    prefix: str,
    name: str,
    description: str | None,
    module: str,
    schema_file: str | None,
) -> None:
    """Register a new custom namespace.

    Examples:
        pms namespace register cust custom_entity -d "My custom entity"
        pms namespace register ext external -m "my_plugin" -s schema.json
    """
    from pms.core.namespace import Namespace, get_namespace_registry

    registry = get_namespace_registry()

    # Check if already exists
    if registry.get(prefix):
        console.print(f"[red]Namespace '{prefix}' already exists[/red]")
        return

    # Load schema if provided
    schema = {}
    if schema_file:
        import json
        from pathlib import Path

        schema = json.loads(Path(schema_file).read_text())

    # Create and register
    ns = Namespace(
        prefix=prefix,
        name=name,
        description=description or "",
        module=module,
        schema=schema,
        is_builtin=False,
    )

    try:
        registry.register(ns)
        console.print(f"[green]Registered namespace:[/green] {prefix}")
        console.print(f"[dim]Name: {name}[/dim]")
        console.print(f"[dim]Example Namespace ID: {ns.generate_id()}[/dim]")
    except ValueError as e:
        console.print(f"[red]Error: {e}[/red]")


@namespace.command("unregister")
@click.argument("prefix")
@click.option("-y", "--yes", is_flag=True, help="Skip confirmation")
def namespace_unregister(prefix: str, yes: bool) -> None:
    """Unregister a custom namespace.

    Note: Built-in namespaces cannot be unregistered.

    Examples:
        pms namespace unregister cust
    """
    from pms.core.namespace import get_namespace_registry

    registry = get_namespace_registry()

    ns = registry.get(prefix)
    if ns is None:
        console.print(f"[red]Namespace '{prefix}' not found[/red]")
        return

    if ns.is_builtin:
        console.print(f"[red]Cannot unregister built-in namespace '{prefix}'[/red]")
        return

    if not yes and not click.confirm(f"Unregister namespace '{prefix}'?"):
        console.print("[dim]Cancelled[/dim]")
        return

    try:
        registry.unregister(prefix)
        console.print(f"[green]Unregistered namespace:[/green] {prefix}")
    except ValueError as e:
        console.print(f"[red]Error: {e}[/red]")


@namespace.command("schema")
@click.option("-o", "--output", type=click.Path(), help="Save schema to file")
def namespace_schema(output: str | None) -> None:
    """Show full namespace schema.

    Examples:
        pms namespace schema
        pms namespace schema --output namespaces.json
    """
    import json

    from pms.core import get_namespace_schema

    schema = get_namespace_schema()

    json_str = json.dumps(schema, indent=2, default=str)

    if output:
        from pathlib import Path

        Path(output).write_text(json_str)
        console.print(f"[green]Schema saved to: {output}[/green]")
    else:
        # Use print() to avoid Rich console text wrapping which breaks JSON
        print(json_str)


