@plugin.command("validate")
@click.argument("path", type=click.Path(exists=True))
def plugin_validate(path: str) -> None:
    """Validate a plugin manifest and structure.

    Examples:
        pms plugin validate ./my-plugin
        pms plugin validate ~/.pms/plugins/hello-world
    """
    from pathlib import Path

    from pms.plugins import PluginManifest

    plugin_path = Path(path).expanduser()
    errors = []
    warnings = []

    console.print(f"[bold]Validating plugin at: {plugin_path}[/bold]")
    console.print("=" * 50)

    # Check for manifest
    manifest_path = plugin_path / "plugin.json"
    dsl_files = list(plugin_path.glob("*.tools"))

    if manifest_path.exists():
        try:
            manifest = PluginManifest.from_file(manifest_path)

            # Validate manifest
            manifest_errors = manifest.validate()
            errors.extend(manifest_errors)

            console.print(f"[green]\u2713[/green] plugin.json found")
            console.print(f"  Name: {manifest.name}")
            console.print(f"  Version: {manifest.version}")
            console.print(f"  Tools: {len(manifest.tools)}")

            # Check entrypoint
            entrypoint_path = plugin_path / manifest.entrypoint
            if entrypoint_path.exists():
                console.print(
                    f"[green]\u2713[/green] Entrypoint found: {manifest.entrypoint}"
                )

                # Try to parse Python file
                try:
                    import ast

                    content = entrypoint_path.read_text()
                    ast.parse(content)
                    console.print(f"[green]\u2713[/green] Python syntax valid")

                    # Check for tool functions
                    for tool in manifest.tools:
                        if (
                            f"async def {tool.name}" in content
                            or f"def {tool.name}" in content
                        ):
                            console.print(
                                f"[green]\u2713[/green] Tool function found: {tool.name}"
                            )
                        else:
                            warnings.append(f"Tool function not found: {tool.name}")
                except SyntaxError as e:
                    errors.append(f"Python syntax error: {e}")
            else:
                errors.append(f"Entrypoint not found: {manifest.entrypoint}")

        except Exception as e:
            errors.append(f"Failed to parse manifest: {e}")

    elif dsl_files:
        console.print(
            f"[green]\u2713[/green] DSL file(s) found: {[f.name for f in dsl_files]}"
        )
        # Validate DSL files
        for dsl_file in dsl_files:
            try:
                from pms.plugins import DSLParser

                content = dsl_file.read_text()
                parser = DSLParser()
                tools = parser.parse(content)
                console.print(
                    f"  [green]\u2713[/green] {dsl_file.name}: {len(tools)} tools"
                )
            except Exception as e:
                errors.append(f"DSL parse error in {dsl_file.name}: {e}")
    else:
        errors.append("No plugin.json or .tools files found")

    # Print results
    console.print()
    if errors:
        console.print("[red][bold]Errors:[/bold][/red]")
        for error in errors:
            console.print(f"  [red]\u2717[/red] {error}")

    if warnings:
        console.print("[yellow][bold]Warnings:[/bold][/yellow]")
        for warning in warnings:
            console.print(f"  [yellow]![/yellow] {warning}")

    if not errors and not warnings:
        console.print("[green][bold]\u2713 Plugin is valid![/bold][/green]")
    elif not errors:
        console.print("[yellow][bold]Plugin valid with warnings[/bold][/yellow]")
    else:
        console.print("[red][bold]\u2717 Plugin has errors[/bold][/red]")
        raise click.exceptions.Exit(1)


@plugin.command("test")
@click.argument("path", type=click.Path(exists=True))
@click.option("-v", "--verbose", is_flag=True, help="Verbose output")
@click.option("--dry-run", is_flag=True, help="Show what would be tested")
@async_command
async def plugin_test(path: str, verbose: bool, dry_run: bool) -> None:
    """Test a plugin by loading and calling its tools.

    Examples:
        pms plugin test ./my-plugin
        pms plugin test ./my-plugin --verbose
    """
    from pathlib import Path

    from pms.plugins import PluginManifest
    from pms.plugins.testing import PluginTestHarness

    plugin_path = Path(path).expanduser()
    console.print(f"[bold]Testing plugin at: {plugin_path}[/bold]")
    console.print("=" * 50)

    # Find manifest
    manifest_path = plugin_path / "plugin.json"
    if not manifest_path.exists():
        _emit_cli_error("No plugin.json found", output_format="text")

    manifest = PluginManifest.from_file(manifest_path)

    if dry_run:
        console.print("\n[cyan]Dry run - would test:[/cyan]")
        console.print(f"  Plugin: {manifest.name}")
        console.print(f"  Tools: {[t.name for t in manifest.tools]}")
        return

    # Create test harness
    harness = PluginTestHarness()
    results: dict[str, Any] = {"passed": 0, "failed": 0, "errors": []}

    try:
        # Load plugin
        console.print(f"\n[cyan]Loading plugin: {manifest.name}...[/cyan]")
        plugin = await harness.load_plugin(plugin_path)
        console.print(f"[green]\u2713 Plugin loaded[/green]")
        results["passed"] += 1

        # Test each tool
        for tool in manifest.tools:
            tool_name = f"{manifest.name}.{tool.name}"
            console.print(f"\n[cyan]Testing tool: {tool.name}[/cyan]")

            try:
                # Build minimal test arguments
                test_args: dict[str, Any] = {}
                for param_name, param in tool.parameters.items():
                    if param.required:
                        # Provide test values based on type
                        match param.type:
                            case "string" | "str":
                                test_args[param_name] = "test"
                            case "int" | "integer":
                                test_args[param_name] = 1
                            case "float" | "number":
                                test_args[param_name] = 1.0
                            case "bool" | "boolean":
                                test_args[param_name] = True
                            case "dict":
                                test_args[param_name] = {}
                            case "list":
                                test_args[param_name] = []
                            case _:
                                pass

                if verbose:
                    console.print(f"  Args: {test_args}")

                result = await harness.call_tool(tool_name, **test_args)

                if verbose:
                    console.print(f"  Result: {result}")

                # Check for errors in result
                if isinstance(result, dict) and "error" in result:
                    console.print(
                        f"  [yellow]\u26a0 Tool returned error: {result['error']}[/yellow]"
                    )
                    results["errors"].append(f"{tool.name}: {result['error']}")
                else:
                    console.print(f"  [green]\u2713 Tool executed successfully[/green]")
                    results["passed"] += 1

            except Exception as e:
                console.print(f"  [red]\u2717 Tool failed: {e}[/red]")
                results["failed"] += 1
                results["errors"].append(f"{tool.name}: {e}")

    except Exception as e:
        console.print(f"[red]\u2717 Failed to load plugin: {e}[/red]")
        results["failed"] += 1
        results["errors"].append(f"Load: {e}")

    # Summary
    console.print("\n" + "=" * 50)
    console.print("[bold]Test Summary[/bold]")
    console.print(f"  Passed: [green]{results['passed']}[/green]")
    console.print(f"  Failed: [red]{results['failed']}[/red]")

    if results["errors"]:
        console.print("\n[red]Errors:[/red]")
        for error in results["errors"]:
            console.print(f"  - {error}")


@namespace.command("generate-id")
@click.argument("prefix")
@click.option("-n", "--count", default=1, help="Number of IDs to generate")
def namespace_generate_id(prefix: str, count: int) -> None:
    """Generate IDs for a namespace.

    Examples:
        pms namespace generate-id task
        pms namespace generate-id proj --count 5
    """
    from pms.core import generate_id_for_namespace

    for _ in range(count):
        try:
            entity_id = generate_id_for_namespace(prefix)
            console.print(entity_id)
        except ValueError as e:
            console.print(f"[red]Error: {e}[/red]")
            return


