@async_command
async def report_project(project_id: str, fmt: str, output_file: str | None) -> None:
    """Generate a detailed project report.

    Examples:
        pms report project proj_abc123
        pms report project proj_abc123 --format html -o report.html
        pms report project proj_abc123 --format json > project.json
    """
    from pms.core.events import EventStore
    from pms.core.metrics import MetricsCollector
    from pms.core.revisions import RevisionStore
