@cli.group()
def auth() -> None:
    """Manage API keys and authentication."""
    pass


@auth.command("init")
@click.option("--name", default="Admin Key", help="Name for the admin API key")
@click.option("--show-key", is_flag=True, help="Display the key after creation")
@async_command
async def auth_init(name: str, show_key: bool) -> None:
    """Initialize authentication by creating the first admin API key.

    This command creates an API key with full admin permissions.
    The key is saved to .pms-admin-key (KEEP THIS SECURE!).

    Examples:
        pms auth init
        pms auth init --name "My Admin Key" --show-key
    """
    from pathlib import Path

    from pms.db.connection import init_database
    from pms.repositories.api_key_repository import ApiKeyRepository
    from pms.services.auth_service import AuthService
    from pms.utils.secret_files import write_secret_file

    db = await init_database()

    try:
        api_key_repo = ApiKeyRepository(db)
        auth_service = AuthService(api_key_repo)

        # Check if admin key already exists
        existing_keys = await auth_service.list_keys()
        admin_keys = [
            k for k in existing_keys if "*" in k.scopes or "admin:keys" in k.scopes
        ]

        if admin_keys and not click.confirm(
            "[yellow]Admin key(s) already exist. Create another?[/yellow]",
            default=False,
        ):
            console.print("[yellow]Cancelled.[/yellow]")
            console.print(
                "[dim]If .pms-admin-key is stale or missing, run: "
                f"{_cli_command('auth recover-local-admin --show-key')}[/dim]"
            )
            return

        # Create admin API key
        plain_key, api_key = await auth_service.create_api_key(
            name=name,
            scopes=["*"],  # Full admin access
            expires_in_days=None,  # Never expires
            rate_limit=None,  # No rate limit
            metadata={"type": "admin", "created_by": "cli_bootstrap"},
        )

        # Save to file
        key_file = Path(".pms-admin-key")
        write_secret_file(key_file, plain_key)

        console.print("[green]✓ Admin API key created successfully![/green]")
        console.print(f"[dim]Key ID: {api_key.id}[/dim]")
        console.print(f"[dim]Prefix: {api_key.prefix}[/dim]")
        console.print(f"[dim]Scopes: {', '.join(api_key.scopes)}[/dim]")
        console.print("")
        console.print(f"[yellow]⚠️  API key saved to: {key_file.absolute()}[/yellow]")
        console.print(
            "[yellow]   Keep this file secure! It grants full admin access.[/yellow]"
        )

        if show_key:
            console.print("")
            console.print(
                "[bold]API Key (copy this now - won't be shown again):[/bold]"
            )
            console.print(f"[cyan]{plain_key}[/cyan]")
        else:
            console.print("")
            console.print("[dim]To see the key, run with --show-key flag[/dim]")
            console.print(f"[dim]Or read from file: cat {key_file}[/dim]")

        console.print("")
        console.print("[bold green]Next steps:[/bold green]")
        console.print(
            f"  1. Export the key: {_cli_command('export PMS_API_KEY=$(cat .pms-admin-key)')}"
        )
        console.print(
            f"  2. Create additional keys: {_cli_command('auth create --help')}"
        )
        console.print(f"  3. List keys: {_cli_command('auth list')}")

    except Exception as e:
        console.print(f"[red]Error creating admin key: {e}[/red]")
        raise
    finally:
        await db.disconnect()


@auth.command("recover-local-admin")
@click.option(
    "--name", default="Recovered Admin Key", help="Name for the recovered admin API key"
)
@click.option("--show-key", is_flag=True, help="Display the key after creation")
@async_command
async def auth_recover_local_admin(name: str, show_key: bool) -> None:
    """Mint a replacement local admin API key and refresh .pms-admin-key.

    This is intended for direct local operators when the database already has
    admin keys but the saved `.pms-admin-key` file is stale or missing.
    """
    from pathlib import Path

    from pms.db.connection import init_database
    from pms.repositories.api_key_repository import ApiKeyRepository
    from pms.services.auth_service import AuthService
    from pms.utils.secret_files import write_secret_file

    db = await init_database()

    try:
        api_key_repo = ApiKeyRepository(db)
        auth_service = AuthService(api_key_repo)

        plain_key, api_key = await auth_service.create_api_key(
            name=name,
            scopes=["*"],
            expires_in_days=None,
            rate_limit=None,
            metadata={"type": "admin", "created_by": "local_recovery"},
        )

        key_file = Path(".pms-admin-key")
        write_secret_file(key_file, plain_key)

        console.print("[green]✓ Local admin API key recovered successfully![/green]")
        console.print(f"[dim]Key ID: {api_key.id}[/dim]")
        console.print(f"[dim]Prefix: {api_key.prefix}[/dim]")
        console.print(f"[dim]Saved to: {key_file.absolute()}[/dim]")

        if show_key:
            console.print("")
            console.print("[bold]Recovered API Key:[/bold]")
            console.print(f"[cyan]{plain_key}[/cyan]")

        console.print("")
        console.print("[bold green]Next steps:[/bold green]")
        console.print(
            f"  1. Export the key: {_cli_command('export PMS_API_KEY=$(cat .pms-admin-key)')}"
        )
        console.print(f"  2. Validate server auth: {_cli_command('auth list')}")
        console.print(
            "  3. Use the installed binary: "
            f"./.bin/pms-client --server {LOCAL_SERVER_DEFAULT_BASE_URL} health"
        )
    finally:
        await db.disconnect()


@auth.command("create")
@click.option("--name", required=True, help="Name for the API key")
@click.option(
    "--scope",
    "scopes",
    multiple=True,
    required=True,
    help="Scopes (can specify multiple)",
)
@click.option("--expires", type=int, help="Expiration in days")
@click.option("--rate-limit", type=int, help="Requests per minute")
@click.option(
    "--api-key", envvar="PMS_API_KEY", help="Admin API key (or set PMS_API_KEY env var)"
)
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json"]),
    default="text",
    show_default=True,
)
@async_command
async def auth_create(
    name: str,
    scopes: tuple[str, ...],
    expires: int | None,
    rate_limit: int | None,
    api_key: str | None,
    output_format: str,
) -> None:
    """Create a new API key (requires admin key).

    Examples:
        pms auth create --name "Agent 1" --scope "tasks:read" --scope "tasks:write"
        pms auth create --name "Viewer" --scope "tasks:read" --expires 30
        export PMS_API_KEY=pms_abc123...
        pms auth create --name "Limited" --scope "tasks:read" --rate-limit 100
    """
    if not api_key:
        _emit_cli_error(
            "Error: Admin API key required. Set PMS_API_KEY environment variable or use --api-key flag",
            output_format=output_format,
        )

    from pms.db.connection import init_database
    from pms.repositories.api_key_repository import ApiKeyRepository
    from pms.services.auth_service import AuthService

    db = await init_database()

    try:
        api_key_repo = ApiKeyRepository(db)
        auth_service = AuthService(api_key_repo)

        # Validate admin key
        admin_api_key = await auth_service.validate_api_key(api_key, "admin:keys")
        if not admin_api_key:
            _emit_cli_error(
                "Error: Invalid or unauthorized API key. You need an API key with 'admin:keys' or '*' scope.",
                output_format=output_format,
            )

        # Create new API key
        plain_key, new_key = await auth_service.create_api_key(
            name=name,
            scopes=list(scopes),
            expires_in_days=expires,
            rate_limit=rate_limit,
        )

        if output_format == "json":
            click.echo(
                json.dumps(
                    {
                        "id": new_key.id,
                        "name": new_key.name,
                        "prefix": new_key.prefix,
                        "scopes": new_key.scopes,
                        "rate_limit": new_key.rate_limit,
                        "expires_at": new_key.expires_at,
                        "plain_key": plain_key,
                        "links": _normalize_command_links(
                            {
                                "get": f"auth get {new_key.id} --format json",
                                "deactivate": f"auth deactivate {new_key.id} --format json",
                                "revoke": f"auth revoke {new_key.id} --format json",
                            }
                        ),
                    },
                    default=str,
                )
            )
            return

        console.print("[green]✓ API key created successfully![/green]")
        console.print(f"[dim]Key ID: {new_key.id}[/dim]")
        console.print(f"[dim]Prefix: {new_key.prefix}[/dim]")
        console.print(f"[dim]Scopes: {', '.join(new_key.scopes)}[/dim]")
        if new_key.rate_limit:
            console.print(f"[dim]Rate limit: {new_key.rate_limit} req/min[/dim]")
        if new_key.expires_at:
            console.print(f"[dim]Expires: {new_key.expires_at}[/dim]")
        console.print("")
        console.print(
            "[bold yellow]⚠️  COPY THIS KEY NOW (won't be shown again):[/bold yellow]"
        )
        console.print(f"[cyan]{plain_key}[/cyan]")

    except Exception as e:
        _emit_cli_error(f"Error creating API key: {e}", output_format=output_format)
    finally:
        await db.disconnect()


@auth.command("list")
@click.option("--show-inactive", is_flag=True, help="Include inactive keys")
@click.option("--include-archived", is_flag=True, help="Include archived keys")
@click.option("--api-key", envvar="PMS_API_KEY", help="Admin API key")
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["table", "json", "csv"]),
    default="table",
    show_default=True,
)
@click.option(
    "--view",
    type=click.Choice(["overview", "detail", "trace"]),
    default="overview",
    show_default=True,
    help="Output view profile (overview/detail/trace)",
)
@click.option("--include-history", is_flag=True, help="Include history in JSON")
@click.option("--history-limit", type=int, default=20, show_default=True)
@click.option("--limit", type=int, default=100, show_default=True)
@click.option("--offset", type=int, default=0, show_default=True)
@async_command
async def auth_list(
    show_inactive: bool,
    include_archived: bool,
    api_key: str | None,
    output_format: str,
    view: str,
    include_history: bool,
    history_limit: int,
    limit: int,
    offset: int,
) -> None:
    """List all API keys (requires admin key).

    Examples:
        pms auth list
        pms auth list --show-inactive
    """
    if not api_key:
        _emit_cli_error(
            "Error: Admin API key required. Set PMS_API_KEY environment variable or use --api-key flag",
            output_format="json" if output_format == "json" else "text",
        )

    from pms.db.connection import init_database
    from pms.repositories.api_key_repository import ApiKeyRepository
    from pms.services.auth_service import AuthService

    db = await init_database()

    try:
        api_key_repo = ApiKeyRepository(db)
        auth_service = AuthService(api_key_repo)

        # Validate admin key
        admin_api_key = await auth_service.validate_api_key(api_key, "admin:keys")
        if not admin_api_key:
            _emit_cli_error(
                "Error: Invalid or unauthorized API key.",
                output_format="json" if output_format == "json" else "text",
            )

        # List keys
        if view == "trace":
            include_history = True

        keys = await auth_service.list_keys(
            include_inactive=show_inactive,
            include_archived=include_archived,
        )
        total_count = len(keys)
        view_items = keys[offset:] if limit <= 0 else keys[offset : offset + limit]

        if not keys:
            if output_format == "json":
                payload = {
                    "items": [],
                    "page": _page_payload(0, limit, offset),
                    "links": _normalize_command_links(
                        {"self": "auth list --format json"}
                    ),
                }
                click.echo(json.dumps(payload, default=str))
                return
            if output_format == "csv":
                headers = [
                    "id",
                    "name",
                    "prefix",
                    "scopes",
                    "rate_limit",
                    "status",
                    "last_used_at",
                    "archived_at",
                ]
            click.echo(_csv_row(headers))
            return
            console.print("[yellow]No API keys found.[/yellow]")
            return

        if output_format == "json":
            api_key_repo = ApiKeyRepository(db)
            effective_history_limit = history_limit if history_limit > 0 else 1000

            def _key_links(key_obj) -> dict[str, str]:
                return _normalize_command_links(
                    {
                        "get": f"auth get {key_obj.id} --format json",
                        "deactivate": f"auth deactivate {key_obj.id}",
                        "revoke": f"auth revoke {key_obj.id}",
                        "restore": f"auth restore {key_obj.id}",
                    }
                )

            items = []
            for key in view_items:
                if view == "overview":
                    payload = {
                        "id": key.id,
                        "name": key.name,
                        "prefix": key.prefix,
                        "scopes": key.scopes,
                        "is_active": key.is_active,
                        "last_used_at": key.last_used_at,
                        "archived_at": key.archived_at,
                        "links": _key_links(key),
                    }
                else:
                    payload = {
                        "id": key.id,
                        "name": key.name,
                        "prefix": key.prefix,
                        "scopes": key.scopes,
                        "rate_limit": key.rate_limit,
                        "is_active": key.is_active,
                        "last_used_at": key.last_used_at,
                        "expires_at": key.expires_at,
                        "metadata": key.metadata,
                        "created_at": key.created_at,
                        "updated_at": key.updated_at,
                        "archived_at": key.archived_at,
                        "links": _key_links(key),
                    }

                if include_history:
                    history = await api_key_repo.get_history(
                        key.id, limit=effective_history_limit
                    )
                    payload["history"] = [
                        {
                            "revision_number": rev.revision_number,
                            "change_type": rev.change_type.value,
                            "message": rev.message,
                            "created_by": rev.created_by,
                            "created_at": rev.created_at,
                        }
                        for rev in history
                    ]

                items.append(payload)

            base_cmd = _cli_command("auth list --format json")
            if show_inactive:
                base_cmd += " --show-inactive"
            if include_archived:
                base_cmd += " --include-archived"
            if view != "overview":
                base_cmd += f" --view {view}"
            payload = {
                "items": items,
                "page": _page_payload(total_count, limit, offset),
                "links": _normalize_command_links(
                    {
                        "self": f"{base_cmd} --limit {limit} --offset {offset}",
                        "next": (
                            f"{base_cmd} --limit {limit} --offset {offset + limit}"
                            if limit > 0 and offset + limit < total_count
                            else None
                        ),
                    }
                ),
            }
            click.echo(json.dumps(payload, default=str))
            return

        if output_format == "csv":
            headers = [
                "id",
                "name",
                "prefix",
                "scopes",
                "rate_limit",
                "status",
                "last_used_at",
                "archived_at",
            ]
            click.echo(_csv_row(headers))
            for key in view_items:
                status = "active" if key.is_active else "inactive"
                row = [
                    key.id,
                    key.name,
                    key.prefix,
                    ", ".join(key.scopes),
                    str(key.rate_limit or ""),
                    status,
                    key.last_used_at.strftime("%Y-%m-%d %H:%M")
                    if key.last_used_at
                    else "",
                    key.archived_at.strftime("%Y-%m-%d %H:%M")
                    if key.archived_at
                    else "",
                ]
                click.echo(_csv_row(row))
            return

        from pms.utils.time import format_relative

        table = Table(title="API Keys")
        table.add_column("Name", style="cyan")
        table.add_column("Prefix", style="dim")
        table.add_column("Scopes")
        table.add_column("Rate Limit")
        table.add_column("Status")
        table.add_column("Last Used")
        table.add_column("Archived")

        for key in view_items:
            status_color = "green" if key.is_active else "red"
            status = "Active" if key.is_active else "Inactive"
            last_used = format_relative(key.last_used_at) if key.last_used_at else "-"
            archived_label = (
                format_relative(key.archived_at) if key.archived_at else "-"
            )
            rate_limit_str = f"{key.rate_limit}/min" if key.rate_limit else "None"
            scopes_str = (
                ", ".join(key.scopes)
                if len(key.scopes) <= 3
                else f"{', '.join(key.scopes[:3])}..."
            )

            table.add_row(
                key.name,
                key.prefix,
                scopes_str,
                rate_limit_str,
                f"[{status_color}]{status}[/{status_color}]",
                last_used,
                archived_label,
            )

        console.print(table)
        console.print(f"\n[dim]Total: {total_count} key(s)[/dim]")

    except Exception as e:
        console.print(f"[red]Error listing API keys: {e}[/red]")
        raise
    finally:
        await db.disconnect()


@auth.command("get")
@click.argument("key_id")
@click.option("--api-key", envvar="PMS_API_KEY", help="Admin API key")
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json", "csv"]),
    default="text",
    show_default=True,
)
@click.option(
    "--view",
    type=click.Choice(["overview", "detail", "trace"]),
    default="detail",
    show_default=True,
    help="Output view profile (overview/detail/trace)",
)
@click.option("--include-history", is_flag=True, help="Include history in JSON")
@click.option("--history-limit", type=int, default=20, show_default=True)
@async_command
async def auth_get(
    key_id: str,
    api_key: str | None,
    output_format: str,
    view: str,
    include_history: bool,
    history_limit: int,
) -> None:
    """Show a single API key (requires admin key)."""
    if not api_key:
        _emit_cli_error(
            "Error: Admin API key required. Set PMS_API_KEY environment variable or use --api-key flag",
            output_format="json" if output_format == "json" else "text",
        )

    from pms.db.connection import init_database
    from pms.repositories.api_key_repository import ApiKeyRepository
    from pms.services.auth_service import AuthService
    from pms.utils.time import format_relative

    db = await init_database()
    try:
        api_key_repo = ApiKeyRepository(db)
        auth_service = AuthService(api_key_repo)

        admin_api_key = await auth_service.validate_api_key(api_key, "admin:keys")
        if not admin_api_key:
            _emit_cli_error(
                "Error: Invalid or unauthorized API key.",
                output_format="json" if output_format == "json" else "text",
            )

        key_obj = await auth_service.get_key_by_id(key_id)
        if key_obj is None:
            _emit_cli_error(
                f"API key '{key_id}' not found",
                output_format="json" if output_format == "json" else "text",
            )

        if view == "trace":
            include_history = True

        if output_format == "json":
            payload = {
                "id": key_obj.id,
                "name": key_obj.name,
                "prefix": key_obj.prefix,
                "scopes": key_obj.scopes,
                "rate_limit": key_obj.rate_limit,
                "is_active": key_obj.is_active,
                "last_used_at": key_obj.last_used_at,
                "expires_at": key_obj.expires_at,
                "metadata": key_obj.metadata,
                "created_at": key_obj.created_at,
                "updated_at": key_obj.updated_at,
                "archived_at": key_obj.archived_at,
                "links": _normalize_command_links(
                    {
                        "get": f"auth get {key_obj.id} --format json",
                        "deactivate": f"auth deactivate {key_obj.id}",
                        "revoke": f"auth revoke {key_obj.id}",
                        "restore": f"auth restore {key_obj.id}",
                    }
                ),
            }
            if include_history:
                effective_history_limit = history_limit if history_limit > 0 else 1000
                history = await api_key_repo.get_history(
                    key_obj.id, limit=effective_history_limit
                )
                payload["history"] = [
                    {
                        "revision_number": rev.revision_number,
                        "change_type": rev.change_type.value,
                        "message": rev.message,
                        "created_by": rev.created_by,
                        "created_at": rev.created_at,
                    }
                    for rev in history
                ]
            click.echo(json.dumps(payload, default=str))
            return

        if output_format == "csv":
            headers = [
                "id",
                "name",
                "prefix",
                "scopes",
                "rate_limit",
                "status",
                "last_used_at",
                "expires_at",
                "created_at",
                "updated_at",
                "archived_at",
            ]
            click.echo(_csv_row(headers))
            status = "active" if key_obj.is_active else "inactive"
            row = [
                key_obj.id,
                key_obj.name,
                key_obj.prefix,
                ", ".join(key_obj.scopes),
                str(key_obj.rate_limit or ""),
                status,
                _to_iso(key_obj.last_used_at) or "",
                _to_iso(key_obj.expires_at) or "",
                _to_iso(key_obj.created_at) or "",
                _to_iso(key_obj.updated_at) or "",
                _to_iso(key_obj.archived_at) or "",
            ]
            click.echo(_csv_row(row))
            return

        status_color = "green" if key_obj.is_active else "red"
        status = "Active" if key_obj.is_active else "Inactive"
        last_used = (
            format_relative(key_obj.last_used_at) if key_obj.last_used_at else "-"
        )
        archived_label = (
            format_relative(key_obj.archived_at) if key_obj.archived_at else "-"
        )
        rate_limit_str = f"{key_obj.rate_limit}/min" if key_obj.rate_limit else "None"
        scopes_str = (
            ", ".join(key_obj.scopes)
            if len(key_obj.scopes) <= 5
            else f"{', '.join(key_obj.scopes[:5])}..."
        )

        console.print(f"[bold]API Key[/bold] {key_obj.name}")
        console.print(f"ID: {key_obj.id}")
        console.print(f"Prefix: {key_obj.prefix}")
        console.print(f"Scopes: {scopes_str}")
        console.print(f"Rate limit: {rate_limit_str}")
        console.print(f"Status: [{status_color}]{status}[/{status_color}]")
        console.print(f"Last used: {last_used}")
        console.print(f"Archived: {archived_label}")
        if key_obj.expires_at:
            console.print(f"Expires: {key_obj.expires_at}")
        _print_next_steps(
            f"auth deactivate {key_obj.id}",
            f"auth revoke {key_obj.id}",
            f"auth restore {key_obj.id}",
        )
    finally:
        await db.disconnect()


@auth.command("deactivate")
@click.argument("key_id")
@click.option("--api-key", envvar="PMS_API_KEY", help="Admin API key")
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json"]),
    default="text",
    show_default=True,
)
@async_command
async def auth_deactivate(key_id: str, api_key: str | None, output_format: str) -> None:
    """Deactivate an API key without deleting it."""
    if not api_key:
        _emit_cli_error("Error: Admin API key required.", output_format=output_format)

    from pms.db.connection import init_database
    from pms.repositories.api_key_repository import ApiKeyRepository
    from pms.services.auth_service import AuthService

    db = await init_database()

    try:
        api_key_repo = ApiKeyRepository(db)
        auth_service = AuthService(api_key_repo)

        admin_api_key = await auth_service.validate_api_key(api_key, "admin:keys")
        if not admin_api_key:
            _emit_cli_error(
                "Error: Invalid or unauthorized API key.",
                output_format=output_format,
            )

        key_obj = await auth_service.get_key_by_id(key_id)
        if key_obj is None:
            _emit_cli_error(
                f"Error: API key not found: {key_id}", output_format=output_format
            )

        await auth_service.deactivate_key(key_id)
        if output_format == "json":
            click.echo(
                json.dumps(
                    {
                        "id": key_obj.id,
                        "name": key_obj.name,
                        "status": "inactive",
                        "action": "deactivated",
                        "links": _normalize_command_links(
                            {
                                "restore": f"auth restore {key_id} --format json",
                                "get": f"auth get {key_id} --format json",
                            }
                        ),
                    },
                    default=str,
                )
            )
            return
        console.print(f"[green]✓ API key deactivated: {key_obj.name}[/green]")
        _print_next_steps(
            f"auth restore {key_id}",
            f"auth get {key_id} --format json",
        )
    finally:
        await db.disconnect()


@auth.command("scopes")
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json", "csv"]),
    default="text",
    show_default=True,
)
def auth_scopes(output_format: str) -> None:
    """List available auth scopes."""
    from pms.api.auth import Scopes

    scopes = sorted(Scopes.all_scopes())
    if output_format == "json":
        click.echo(json.dumps({"scopes": scopes}, default=str))
        return
    if output_format == "csv":
        click.echo(_csv_row(["scope"]))
        for scope in scopes:
            click.echo(_csv_row([scope]))
        return
    console.print(f"Scopes ({len(scopes)}):")
    for scope in scopes:
        console.print(f"  - {scope}")


@auth.command("revoke")
@click.argument("key_id")
@click.option("--api-key", envvar="PMS_API_KEY", help="Admin API key")
@click.option("-y", "--yes", is_flag=True, help="Skip confirmation prompt")
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json"]),
    default="text",
    show_default=True,
)
@async_command
async def auth_revoke(
    key_id: str, api_key: str | None, yes: bool, output_format: str
) -> None:
    """Revoke (delete) an API key (requires admin key).

    Examples:
        pms auth revoke apikey_abc123
    """
    if not api_key:
        _emit_cli_error("Error: Admin API key required.", output_format=output_format)

    from pms.db.connection import init_database
    from pms.repositories.api_key_repository import ApiKeyRepository
    from pms.services.auth_service import AuthService

    db = await init_database()

    try:
        api_key_repo = ApiKeyRepository(db)
        auth_service = AuthService(api_key_repo)

        # Validate admin key
        admin_api_key = await auth_service.validate_api_key(api_key, "admin:keys")
        if not admin_api_key:
            _emit_cli_error(
                "Error: Invalid or unauthorized API key.",
                output_format=output_format,
            )

        # Get key to revoke
        key_to_revoke = await auth_service.get_key_by_id(key_id)
        if not key_to_revoke:
            _emit_cli_error(
                f"Error: API key not found: {key_id}", output_format=output_format
            )

        if not yes and not click.confirm(
            f"Revoke API key '{key_to_revoke.name}' ({key_to_revoke.prefix})?"
        ):
            if output_format == "json":
                click.echo(
                    json.dumps(
                        {
                            "cancelled": True,
                            "id": key_to_revoke.id,
                            "name": key_to_revoke.name,
                            "action": "revoke",
                        },
                        default=str,
                    )
                )
            else:
                console.print("[yellow]Cancelled.[/yellow]")
            return

        await auth_service.delete_key(key_id)
        if output_format == "json":
            click.echo(
                json.dumps(
                    {
                        "id": key_to_revoke.id,
                        "name": key_to_revoke.name,
                        "action": "revoked",
                    },
                    default=str,
                )
            )
            return
        console.print(f"[green]✓ API key revoked: {key_to_revoke.name}[/green]")

    except Exception as e:
        _emit_cli_error(f"Error revoking API key: {e}", output_format=output_format)
    finally:
        await db.disconnect()


@auth.command("restore")
@click.argument("key_id")
@click.option("--api-key", envvar="PMS_API_KEY", help="Admin API key")
@click.option(
    "--format",
    "output_format",
    type=click.Choice(["text", "json"]),
    default="text",
    show_default=True,
)
@async_command
async def auth_restore(key_id: str, api_key: str | None, output_format: str) -> None:
    """Restore an archived API key or reactivate an inactive one."""
    if not api_key:
        _emit_cli_error("Error: Admin API key required.", output_format=output_format)

    from pms.db.connection import init_database
    from pms.repositories.api_key_repository import ApiKeyRepository
    from pms.services.auth_service import AuthService

    db = await init_database()

    try:
        api_key_repo = ApiKeyRepository(db)
        auth_service = AuthService(api_key_repo)

        admin_api_key = await auth_service.validate_api_key(api_key, "admin:keys")
        if not admin_api_key:
            _emit_cli_error(
                "Error: Invalid or unauthorized API key.",
                output_format=output_format,
            )

        restored = await auth_service.restore_key(key_id)
        if not restored:
            _emit_cli_error(
                f"Error: API key not found: {key_id}", output_format=output_format
            )

        if output_format == "json":
            click.echo(
                json.dumps(
                    {
                        "id": restored.id,
                        "name": restored.name,
                        "status": "active" if restored.is_active else "inactive",
                        "action": "restored",
                        "links": _normalize_command_links(
                            {"get": f"auth get {restored.id} --format json"}
                        ),
                    },
                    default=str,
                )
            )
            return
        console.print(f"[green]✓ API key restored/reactivated: {restored.name}[/green]")

    except Exception as e:
        _emit_cli_error(f"Error restoring API key: {e}", output_format=output_format)
    finally:
        await db.disconnect()


# =============================================================================
# Server Command
# =============================================================================


@cli.command("serve")
@click.option("--host", default=LOCAL_SERVER_DEFAULT_HOST, help="Server host")
@click.option(
    "--port", default=LOCAL_RUNTIME_DEFAULT_PORT, type=int, help="Server port"
)
@click.option("--reload", is_flag=True, help="Auto-reload on code changes")
def serve(host: str, port: int, reload: bool) -> None:
    """Start PMS API server."""
    import atexit
    import os

    from pms.config import get_settings
    from pms.runtime.local_server import (
        clear_active_local_server_state,
        get_active_local_server,
        replace_active_local_server,
        write_active_local_server_state,
    )

    try:
        import uvicorn
    except ImportError:
        console.print(
            "[red]Error: uvicorn not installed. Install with: pip install uvicorn[standard][/red]"
        )
        return

    settings = get_settings()
    server_url = f"http://{host}:{port}"
    active_server = get_active_local_server(settings.data_dir, timeout_seconds=0.5)
    if active_server is not None:
        if active_server.server_url == server_url:
            console.print(
                f"[yellow]PMS server already active at {server_url} "
                f"(pid {active_server.pid}).[/yellow]"
            )
            console.print(
                "[dim]Use `uv run pms runtime status --format json` or "
                "`uv run pms runtime cleanup --include-unmanaged-local --format json` "
                "before starting another local server.[/dim]"
            )
            return

        console.print(
            "[yellow]Replacing active PMS server for this PMS data dir:[/yellow] "
            f"{active_server.server_url} (pid {active_server.pid})"
        )
        replacement = replace_active_local_server(
            data_dir=settings.data_dir,
            timeout_seconds=5.0,
        )
        if replacement is not None and not replacement.replaced:
            console.print(
                "[red]Error: could not stop the currently active PMS server "
                f"at {active_server.server_url}. {replacement.error}[/red]"
            )
            return

    console.print(f"[bold green]Starting PMS API Server[/bold green]")
    console.print(f"  Host: {host}")
    console.print(f"  Port: {port}")
    console.print(f"  Docs: {server_url}/docs")
    console.print(f"  Current write mode: {settings.write_mode}")
    if settings.write_mode != "direct":
        console.print(
            "  Suggested config: "
            f"pms config set --write-mode {settings.write_mode} --server-url {server_url}"
        )
    else:
        console.print(
            "  Suggested config: "
            f"pms config set --write-mode prefer_server --server-url {server_url}"
        )
    console.print("")

    write_active_local_server_state(
        settings.data_dir,
        pid=os.getpid(),
        host=host,
        port=port,
        log_file=str((settings.data_dir / "runtime" / f"server-{port}.log").resolve()),
    )
    atexit.register(clear_active_local_server_state, settings.data_dir, pid=os.getpid())
    try:
        uvicorn.run(
            "pms.api.app:app",
            host=host,
            port=port,
            reload=reload,
            log_level="info",
        )
    finally:
        clear_active_local_server_state(settings.data_dir, pid=os.getpid())


if __name__ == "__main__":
    cli()
